def _figure_navigation_active(canvas):
    toolbar = getattr(canvas, 'toolbar', None)
    return toolbar is not None and bool(toolbar.mode)


class _FigureNavigationToolbar(_FigureNavigationToolbarBase):
    def configure_subplots(self, *args):
        # Manual spacing controls need ownership of layout. Constrained layout
        # otherwise silently ignores every change made by the subplot sliders.
        figure = self.canvas.figure
        figure._responsive_analysis_layout = None
        if figure.get_layout_engine() is not None:
            with matplotlib.rc_context({'figure.autolayout': False,
                                        'figure.constrained_layout.use': False}):
                figure.set_layout_engine(None)
        return super().configure_subplots(*args)


_figure_navigation_canvases = _navigation_weakref.WeakSet()


class FigureCanvasTkAgg(_FigureCanvasTkAggBase):
    """Give every embedded figure native Matplotlib navigation controls."""
    def __init__(self, *args, **kwargs):
        self._navigation_initializing = True
        super().__init__(*args, **kwargs)
        self._navigation_initializing = False
        self._navigation_installing = False
        self._navigation_attempts = 0
        _figure_navigation_canvases.add(self)
        self._deferred_draw = True
        self.get_tk_widget().bind('<Map>', self._became_visible, add='+')

    def _became_visible(self, event=None):
        if globals().get('_startup_building', False):
            return
        self._install_navigation()
        if self._deferred_draw:
            self.draw_idle()

    def draw(self, *args, **kwargs):
        # Hidden tabs can accumulate data/artist changes without rasterizing.
        if (globals().get('_startup_building', False)
                or not self.get_tk_widget().winfo_ismapped()):
            self._deferred_draw = True
            return
        result = super().draw(*args, **kwargs)
        self._deferred_draw = False
        return result

    def draw_idle(self):
        if (globals().get('_startup_building', False)
                or not self.get_tk_widget().winfo_ismapped()):
            self._deferred_draw = True
            return
        return super().draw_idle()

    def mpl_connect(self, event, callback):
        owner = getattr(callback, '__self__', None)
        if (getattr(self, '_navigation_initializing', False) or
                isinstance(owner, _FigureNavigationBase) or
                event not in ('button_press_event', 'button_release_event', 'motion_notify_event', 'scroll_event', 'pick_event')):
            return super().mpl_connect(event, callback)

        def selection_safe_callback(pointer):
            toolbar = getattr(self, 'toolbar', None)
            if toolbar is not None and toolbar.mode:
                return
            return callback(pointer)
        return super().mpl_connect(event, selection_safe_callback)

    def _install_navigation(self):
        import tkinter as _navigation_tk
        widget = self.get_tk_widget()
        try:
            if globals().get('_startup_building', False) or not widget.winfo_ismapped():
                return
            if not widget.winfo_exists() or getattr(self, 'toolbar', None) is not None:
                return
            manager = widget.winfo_manager()
            if manager not in ('pack','grid'):
                self._navigation_attempts += 1
                if self._navigation_attempts < 10:
                    widget.after(100,self._install_navigation)
                return
            parent = widget.master
            toolbar = _FigureNavigationToolbar(self, parent, pack_toolbar=False)
            if manager == 'pack':
                toolbar.pack(side='top',fill='x',before=widget)
            else:
                info = widget.grid_info()
                row = max(int(w.grid_info()['row'])+int(w.grid_info().get('rowspan',1))
                          for w in parent.grid_slaves())
                toolbar.grid(row=row,column=int(info['column']),
                    columnspan=int(info.get('columnspan',1)),sticky='ew')
                parent.grid_rowconfigure(row,weight=0)
            toolbar.update_idletasks()

            def cleanup(event):
                if event.widget is widget:
                    try:
                        toolbar.destroy()
                    except _navigation_tk.TclError:
                        pass
            widget.bind('<Destroy>',cleanup,add='+')
        except _navigation_tk.TclError:
            # A source refresh can destroy a canvas before its idle callback.
            return

from matplotlib.widgets import RectangleSelector

# CPU/GPU FFT routing. CUDA is initialized only for a large numerical operation.
# All GUI calls and fits stay on the CPU/main thread; arrays remain NumPy at APIs.
_compute_fft_decisions = {}
_compute_gpu = None
_compute_gpu_checked = False
_compute_gpu_error = ''
_compute_last_backend = 'CPU'
_compute_cpu_workers = max(1, min(4, (os.cpu_count() or 2) // 2))
_compute_gpu_calls = 0
_compute_cpu_calls = 0
_compute_dll_handles = []

def _compute_get_gpu():
    global _compute_gpu, _compute_gpu_checked, _compute_gpu_error
    if _compute_gpu_checked:
        return _compute_gpu
    _compute_gpu_checked = True
    try:
        # Optional per-Python-version cache; never modifies the kernel environment.
        cache = Path.home()/'.cache'/'finalized'/'gpu'/f'cp{sys.version_info.major}{sys.version_info.minor}'
        if (cache/'cupy').is_dir() and str(cache) not in sys.path:
            sys.path.insert(0, str(cache))
        if os.name == 'nt':
            cuda = Path(os.environ.get('CUDA_PATH', r'C:\Program Files\NVIDIA GPU Computing Toolkit\CUDA\v12.5'))/'bin'
            if cuda.is_dir() and hasattr(os, 'add_dll_directory'):
                _compute_dll_handles.append(os.add_dll_directory(str(cuda)))
            # NVIDIA runtime wheels are ABI-independent and may be shared by
            # cached CuPy wheels for different notebook Python versions.
            runtime_roots = [cache/'nvidia'] + [p/'nvidia' for p in cache.parent.glob('cp*') if p != cache]
            for runtime_root in runtime_roots:
                for library in ('cuda_runtime', 'cuda_nvrtc', 'cufft'):
                    dlls = runtime_root/library/'bin'
                    if dlls.is_dir():
                        _compute_dll_handles.append(os.add_dll_directory(str(dlls)))
                        if library == 'cuda_nvrtc':
                            import ctypes
                            for builtin in dlls.glob('nvrtc-builtins*.dll'):
                                _compute_dll_handles.append(ctypes.WinDLL(str(builtin)))
                if not cuda.is_dir() and (runtime_root/'cuda_runtime'/'include').is_dir():
                    os.environ['CUDA_PATH'] = str(runtime_root/'cuda_runtime')
        import cupy as cp
        if cp.cuda.runtime.getDeviceCount() < 1:
            raise RuntimeError('No CUDA device')
        _compute_gpu = cp
    except Exception as exc:
        _compute_gpu_error = f'{type(exc).__name__}: {exc}'
        _compute_gpu = None
    return _compute_gpu


def _compute_fft2(image, inverse=False):
    global _compute_last_backend, _compute_gpu_error, _compute_gpu_calls, _compute_cpu_calls
    from scipy import fft as cpu_fft
    a = np.asarray(image)
    # Match NumPy FFT precision for the installed NumPy, including older kernels.
    target = np.fft.fft2(np.zeros((1,1), dtype=a.dtype)).dtype
    work = np.asarray(a, dtype=target)
    cpu_operation = cpu_fft.ifft2 if inverse else cpu_fft.fft2
    def cpu():
        return cpu_operation(work, workers=_compute_cpu_workers)
    # CUDA setup/transfers cost more than a small ROI transform.
    if a.ndim != 2 or a.size < 1024*1024:
        _compute_last_backend = 'CPU'
        _compute_cpu_calls += 1
        return cpu()
    cp = _compute_get_gpu()
    key = (a.shape, str(target), bool(inverse))
    if cp is not None and _compute_fft_decisions.get(key, True):
        try:
            free, total = cp.cuda.runtime.memGetInfo()
            if work.nbytes * 12 > min(free*.4, total*.4):
                raise MemoryError('FFT would use too much GPU memory')
            operation = cp.fft.ifft2 if inverse else cp.fft.fft2
            def gpu():
                return cp.asnumpy(operation(cp.asarray(work)))
            if key not in _compute_fft_decisions:
                # Warm the CUDA plan, then compare complete transfer+compute time.
                gpu()
                started = time.perf_counter(); gpu_result = gpu(); gpu_s = time.perf_counter()-started
                started = time.perf_counter(); cpu_result = cpu(); cpu_s = time.perf_counter()-started
                # Single-precision FFT roundoff scales with transform magnitude;
                # a fixed per-bin absolute tolerance over-penalizes near-zero bins.
                fft_scale = max(1.0, float(np.sqrt(np.mean(np.abs(cpu_result)**2))))
                accurate = np.allclose(gpu_result, cpu_result, rtol=2e-5 if target.itemsize==8 else 1e-10,
                                       atol=2e-6*fft_scale if target.itemsize==8 else 1e-9)
                _compute_fft_decisions[key] = accurate and gpu_s < cpu_s*.9
                if not _compute_fft_decisions[key]:
                    _compute_last_backend = 'CPU'; _compute_cpu_calls += 1
                    return cpu_result
                _compute_last_backend = 'GPU'; _compute_gpu_calls += 1
                return gpu_result
            _compute_last_backend = 'GPU'; _compute_gpu_calls += 1
            return gpu()
        except Exception as exc:
            _compute_gpu_error = f'{type(exc).__name__}: {exc}'
            _compute_fft_decisions[key] = False
    _compute_last_backend = 'CPU'; _compute_cpu_calls += 1
    return cpu()


# Numeric workers never read Tk variables or touch Matplotlib/Tk widgets.
_compute_image_decisions = {}
_compute_operation_stats = {}
_compute_resize_coordinates = {}
_compute_resize_coordinate_bytes = 0
_compute_cpu_gaussian_filter = gaussian_filter
_compute_batch_frames = 0


def _compute_image_operation(name, key, cpu, gpu, work_bytes, size, angular=False, minimum_gpu_size=512*512, validation_repeats=2):
    global _compute_last_backend, _compute_gpu_error
    stats = _compute_operation_stats.setdefault(name, {'CPU': 0, 'GPU': 0})
    if size < minimum_gpu_size:
        stats['CPU'] += 1
        return cpu()
    cp = _compute_get_gpu()
    decision_key = (name, key)
    if cp is not None and _compute_image_decisions.get(decision_key, True):
        try:
            free, total = cp.cuda.runtime.memGetInfo()
            if work_bytes*8 > min(free*.30, total*.30):
                raise MemoryError('Image operation exceeds the bounded GPU working budget')
            if decision_key not in _compute_image_decisions:
                # Include PCIe transfers; CUDA compilation is warmed once per kernel.
                gpu(cp)
                gpu_times = []; cpu_times = []
                for _ in range(validation_repeats):
                    started = time.perf_counter(); device = gpu(cp)
                    gpu_times.append(time.perf_counter()-started)
                    started = time.perf_counter(); host = cpu()
                    cpu_times.append(time.perf_counter()-started)
                scale = max(1., float(np.max(np.abs(host))))
                delta = np.angle(np.exp(1j*(device-host))) if angular else device-host
                accurate = (device.shape == host.shape and device.dtype == host.dtype and
                            np.array_equal(np.isfinite(device), np.isfinite(host)) and
                            np.array_equal(np.isposinf(device), np.isposinf(host)) and
                            np.array_equal(np.isneginf(device), np.isneginf(host)) and
                            np.all(np.abs(delta[np.isfinite(delta)]) <= scale*2e-11))
                use_gpu = bool(accurate and np.median(gpu_times) < .85*np.median(cpu_times))
                if len(_compute_image_decisions) >= 48:
                    _compute_image_decisions.pop(next(iter(_compute_image_decisions)))
                _compute_image_decisions[decision_key] = use_gpu
                stats['last_cpu_s'] = float(np.median(cpu_times))
                stats['last_gpu_s'] = float(np.median(gpu_times))
                stats['max_validation_error'] = float(np.max(np.abs(delta)))
                _compute_last_backend = 'GPU' if use_gpu else 'CPU'
                stats[_compute_last_backend] += 1
                return device if use_gpu else host
            result = gpu(cp)
            _compute_last_backend = 'GPU'; stats['GPU'] += 1
            return result
        except Exception as exc:
            _compute_gpu_error = f'{type(exc).__name__}: {exc}'
            _compute_image_decisions[decision_key] = False
    _compute_last_backend = 'CPU'; stats['CPU'] += 1
    return cpu()


# Optional GPU equivalent of scikit-image's 2-D Chambolle solver.
# All iterations, boundary conditions and stopping criteria are retained.
_COMPUTE_TV_GPU_KERNELS = None
_COMPUTE_TV_GPU_LOCK = _export_threading.Lock()


def _compute_tv_gpu(image, weight, cp, eps=1e-5, max_num_iter=300):
    global _COMPUTE_TV_GPU_KERNELS
    with _COMPUTE_TV_GPU_LOCK:
        if _COMPUTE_TV_GPU_KERNELS is None:
            divergence = cp.ElementwiseKernel(
                'raw float64 input, raw float64 py, raw float64 px, int32 rows, int32 cols',
                'float64 output',
                '''int y=i/cols; int x=i-y*cols;
                   double d=-(py[i]+px[i]);
                   if(y>0) d+=py[i-cols]; if(x>0) d+=px[i-1];
                   output=input[i]+d;''', 'finalized_tv_divergence')
            update = cp.ElementwiseKernel(
                'raw float64 output, raw float64 input, float64 weight, int32 rows, int32 cols',
                'float64 py, float64 px, float64 energy',
                '''int y=i/cols; int x=i-y*cols;
                   double gy=y+1<rows ? output[i+cols]-output[i] : 0.;
                   double gx=x+1<cols ? output[i+1]-output[i] : 0.;
                   double norm=sqrt(gy*gy+gx*gx);
                   double denominator=1.+norm*(.25/weight);
                   py=(py-.25*gy)/denominator;
                   px=(px-.25*gx)/denominator;
                   double d=output[i]-input[i];
                   energy=d*d+weight*norm;''', 'finalized_tv_update')
            _COMPUTE_TV_GPU_KERNELS = divergence, update
        divergence, update = _COMPUTE_TV_GPU_KERNELS
        a=cp.asarray(image,dtype=cp.float64,order='C');rows,cols=a.shape
        py=cp.zeros_like(a);px=cp.zeros_like(a);energy=cp.empty_like(a)
        output=a.copy();initial=previous=None
        for iteration in range(max_num_iter):
            if iteration: divergence(a,py,px,rows,cols,output)
            update(output,a,weight,rows,cols,py,px,energy)
            current=float(energy.sum())/a.size
            if not iteration: initial=previous=current
            elif abs(previous-current)<eps*initial: break
            else: previous=current
        return cp.asnumpy(output)


def _compute_tv_denoise(image, weight, eps=1e-5, max_num_iter=300):
    from skimage.restoration import denoise_tv_chambolle
    values=np.asarray(image,dtype=np.float64)
    cpu=lambda:denoise_tv_chambolle(values,weight=weight,eps=eps,
        max_num_iter=max_num_iter,channel_axis=None)
    key=(values.shape,values.dtype.str,float(eps),int(max_num_iter))
    return _compute_image_operation('TV denoising',key,cpu,
        lambda cp:_compute_tv_gpu(values,weight,cp,eps,max_num_iter),values.nbytes,values.size,
        minimum_gpu_size=128*128,validation_repeats=1)



def _compute_raw_resize(values, shape, phase=False):
    """Preserve pixel-center cubic interpolation; phase uses unit-circle linear interpolation."""
    global _compute_resize_coordinate_bytes
    values = np.asarray(values, dtype=np.float64)
    shape = tuple(map(int, shape))
    if values.shape == shape:
        return values.copy()
    ratio = np.asarray(values.shape, dtype=float)/shape
    key = (values.shape, shape, bool(phase))

    def cpu():
        global _compute_resize_coordinate_bytes
        coordinates = _compute_resize_coordinates.get(key)
        if coordinates is None:
            yy, xx = np.meshgrid((np.arange(shape[0])+.5)*values.shape[0]/shape[0]-.5,
                                 (np.arange(shape[1])+.5)*values.shape[1]/shape[1]-.5, indexing='ij')
            coordinates = np.array([yy, xx])
            if coordinates.nbytes <= 64*1024*1024:
                while _compute_resize_coordinates and _compute_resize_coordinate_bytes+coordinates.nbytes > 64*1024*1024:
                    old = _compute_resize_coordinates.pop(next(iter(_compute_resize_coordinates)))
                    _compute_resize_coordinate_bytes -= old.nbytes
                _compute_resize_coordinates[key] = coordinates
                _compute_resize_coordinate_bytes += coordinates.nbytes
        if phase:
            real = map_coordinates(np.cos(values), coordinates, order=1, mode='nearest')
            imag = map_coordinates(np.sin(values), coordinates, order=1, mode='nearest')
            return np.arctan2(imag, real)
        return map_coordinates(values, coordinates, order=3, mode='nearest', prefilter=True)

    def gpu(cp):
        from cupyx.scipy.ndimage import affine_transform
        array = cp.asarray(values)
        matrix = cp.asarray(ratio); offset = cp.asarray(.5*ratio-.5)
        options = dict(offset=offset, output_shape=shape, mode='nearest', prefilter=True)
        if phase:
            real = affine_transform(cp.cos(array), matrix, order=1, **options)
            imag = affine_transform(cp.sin(array), matrix, order=1, **options)
            return cp.asnumpy(cp.arctan2(imag, real))
        return cp.asnumpy(affine_transform(array, matrix, order=3, **options))

    return _compute_image_operation('ROI resampling', key, cpu, gpu,
        values.nbytes+int(np.prod(shape))*8, int(np.prod(shape)), angular=phase)


def _compute_gaussian_filter(input, sigma, order=0, output=None, mode='reflect',
                             cval=0., truncate=4., *, radius=None, axes=None):
    options = dict(order=order, output=output, mode=mode, cval=cval, truncate=truncate)
    if radius is not None: options['radius'] = radius
    if axes is not None: options['axes'] = axes
    a = np.asarray(input)
    cpu = lambda: _compute_cpu_gaussian_filter(a, sigma, **options)
    # Integer rounding/output buffers and higher derivatives keep SciPy semantics.
    if a.ndim != 2 or a.dtype.kind != 'f' or output is not None or np.any(np.asarray(order) != 0):
        return cpu()
    key = (a.shape, a.dtype.str, repr(sigma), repr(mode), float(cval),
           float(truncate), repr(radius), repr(axes))
    # Do not compile a new CUDA convolution while a user browses one image.
    # A long frame batch amortizes compilation; a previously chosen GPU kernel
    # can then be reused immediately in both batch and interactive views.
    if ('Gaussian filtering', key) not in _compute_image_decisions and _compute_batch_frames < 64:
        return cpu()

    def gpu(cp):
        from cupyx.scipy.ndimage import gaussian_filter as device_gaussian
        return cp.asnumpy(device_gaussian(cp.asarray(a), sigma, **options))

    return _compute_image_operation('Gaussian filtering', key, cpu, gpu, a.nbytes, a.size)


gaussian_filter = _compute_gaussian_filter


def _compute_build_resized_stack(owner, bounds, local, resized_mask, width, height):
    return _native_build_stack(owner, bounds, local, resized_mask, width, height)



_NATIVE_BACKGROUND_CHOICES = ('None', 'Mean subtraction', 'Median subtraction', 'Plane subtraction',
    'Gaussian background subtraction', 'Polynomial background subtraction')
_NATIVE_FFT_CHOICES = ('None', '2D Hann window', 'Gaussian FFT low-pass', 'Circular FFT low-pass')
_NATIVE_DENOISE_CHOICES = ('None', 'TV', 'Gaussian')


def _native_config(owner):
    def get(name, default):
        variable = getattr(owner, name, None)
        return default if variable is None else variable.get()
    config = dict(background=get('native_background_var', 'None'), fft=get('native_fft_var', 'None'),
        denoise=get('native_denoise_var', 'None'), background_sigma=float(get('native_background_sigma_var', 30.)),
        polynomial_degree=int(get('native_polynomial_degree_var', 2)), cutoff=float(get('native_fft_cutoff_var', .30)),
        tv_weight=float(get('native_tv_weight_var', .02)), denoise_sigma=float(get('native_gaussian_sigma_var', .6)),
        filter=str(owner.filter_var.get()), strength=float(owner.strength_var.get()),
        raw=_intensity_raw(owner), component=_tab4_component_confirmed(owner),
        brightness=float(owner.brightness_var.get()), contrast=float(owner.contrast_var.get()),
        fft_radius=float(owner.fft_mask_var.get()))
    config['interpolation'] = getattr(owner, '_roi_applied_interpolation', 'Bicubic')
    if config['raw']: config['brightness'], config['contrast'] = 0., 1.
    # Only active parameters participate in cache/finalization signatures.
    if config['background'] != 'Gaussian background subtraction': config['background_sigma'] = 30.
    if config['background'] != 'Polynomial background subtraction': config['polynomial_degree'] = 2
    if config['fft'] != 'Gaussian FFT low-pass': config['cutoff'] = .30
    if config['fft'] != 'Circular FFT low-pass': config['fft_radius'] = .60
    if config['denoise'] != 'TV': config['tv_weight'] = .02
    if config['denoise'] != 'Gaussian': config['denoise_sigma'] = .6
    if config['filter'] == 'None': config['strength'] = 3.
    return config



def _native_config_key(owner):
    return tuple(sorted(_native_config(owner).items()))


def _native_signature(owner):
    resolution = tuple(getattr(owner, 'roi_resolution', ()) or ())
    return (id(getattr(owner, 'recons', None)), id(getattr(owner, 'roi_mask', None)),
        tuple(np.shape(getattr(owner, 'recons', None))), resolution, _component_normalization_signature(owner),
        _native_config_key(owner), bool(getattr(owner, '_tab6_analysis_rotation_committed', False)),
        float(getattr(owner, '_tab6_analysis_rotation_angle', 0.)),
        int(getattr(owner, '_tab6_analysis_rotation_version', 0)),
        float(owner._proc_get_tab5_base_pixel_size()))


def _native_gaussian(values, sigma):
    if _export_threading.current_thread() is not _export_threading.main_thread():
        return _compute_cpu_gaussian_filter(values, sigma)
    return gaussian_filter(values, sigma)


def _native_fft(values, inverse=False):
    if _export_threading.current_thread() is not _export_threading.main_thread():
        from scipy import fft
        return (fft.ifft2 if inverse else fft.fft2)(values, workers=1)
    return _compute_fft2(values, inverse=inverse)


def _native_process(values, mask, reference, cfg):
    """Process the selected component at native ROI resolution, preserving Raw units."""
    image = np.asarray(values, dtype=np.float64)
    valid = np.asarray(mask, bool) & np.isfinite(image)
    if not valid.any(): return np.zeros_like(image)
    phase = cfg['component'] == 'Phase' and cfg['raw']
    if cfg['component'] == 'Phase' and any(cfg[name] != 'None' for name in ('background', 'fft', 'denoise')):
        raise ValueError('Background/FFT/TV processing requires Real, Imaginary or Amplitude. Wrapped Phase cannot be processed as scalar intensity.')
    if all(cfg[name] == 'None' for name in ('background', 'fft', 'filter', 'denoise')):
        if cfg['raw'] or (cfg['brightness'] == 0. and cfg['contrast'] == 1.): return image
        return np.clip((image-.5)*cfg['contrast']+.5+cfg['brightness'], 0., 1.)
    background = cfg['background']
    if background not in _NATIVE_BACKGROUND_CHOICES: raise ValueError('Unknown native background method')
    if background in ('Mean subtraction', 'Median subtraction'):
        baseline = np.mean(image[valid]) if background == 'Mean subtraction' else np.median(image[valid])
        image = image - baseline
    elif background in ('Plane subtraction', 'Polynomial background subtraction'):
        degree = 1 if background == 'Plane subtraction' else int(cfg['polynomial_degree'])
        if not 1 <= degree <= 5: raise ValueError('Polynomial degree must be between 1 and 5')
        y, x = np.mgrid[-1:1:complex(image.shape[0]), -1:1:complex(image.shape[1])]
        terms = [(x**px)*(y**(total-px)) for total in range(degree+1) for px in range(total+1)]
        design = np.column_stack([term[valid] for term in terms])
        if len(design) < design.shape[1]: raise ValueError('Too few valid native pixels for the selected polynomial')
        coefficients, _, rank, _ = np.linalg.lstsq(design, image[valid], rcond=None)
        if rank != design.shape[1]: raise ValueError('The native ROI cannot define the selected polynomial background')
        image = image - sum(coefficient*term for coefficient, term in zip(coefficients, terms))
    elif background == 'Gaussian background subtraction':
        sigma = float(cfg['background_sigma'])
        if sigma <= 0: raise ValueError('Background sigma must be positive')
        clean = np.where(valid, image, np.median(image[valid]))
        image = image - _native_gaussian(clean, sigma)
    fill = (float(np.angle(np.mean(np.exp(1j*image[valid])))) if phase else float(np.median(image[valid])))
    clean = np.where(valid, image, fill)
    fft_mode = cfg['fft']
    if fft_mode == '2D Hann window':
        wy = np.hanning(image.shape[0]) if image.shape[0] > 1 else np.ones(1)
        wx = np.hanning(image.shape[1]) if image.shape[1] > 1 else np.ones(1)
        clean = clean * wy[:, None] * wx[None, :]
    elif fft_mode in ('Gaussian FFT low-pass', 'Circular FFT low-pass'):
        fy = np.fft.fftfreq(image.shape[0])[:, None]
        fx = np.fft.fftfreq(image.shape[1])[None, :]
        radius = np.hypot(fx, fy)
        fraction = float(cfg['cutoff'] if fft_mode == 'Gaussian FFT low-pass' else cfg['fft_radius'])
        if not 0 < fraction <= 1: raise ValueError('FFT cutoff/radius must be greater than 0 and at most 1')
        transfer = np.exp(-.5*(radius/(.5*fraction))**2) if fft_mode == 'Gaussian FFT low-pass' else radius <= .5*fraction
        clean = _native_fft(_native_fft(clean)*transfer, inverse=True).real
    elif fft_mode != 'None': raise ValueError('Unknown native FFT method')
    kind = cfg['filter']; strength = float(cfg['strength'])
    if kind != 'None' and strength <= 0: raise ValueError('Filter strength must be positive')
    def smooth(sigma):
        return np.arctan2(_native_gaussian(np.sin(clean), sigma), _native_gaussian(np.cos(clean), sigma)) if phase else _native_gaussian(clean, sigma)
    offset = 0. if cfg['raw'] else .5
    if kind in ('Gaussian', 'Low-pass'): clean = smooth(strength)
    elif kind == 'High-pass': clean = np.angle(np.exp(1j*(clean-smooth(strength)))) if phase else offset+clean-smooth(strength)
    elif kind == 'Band-pass': clean = np.angle(np.exp(1j*(smooth(strength)-smooth(2*strength)))) if phase else offset+smooth(strength)-smooth(2*strength)
    elif kind != 'None': raise ValueError('Unknown native spatial filter')
    denoise = cfg['denoise']
    if denoise == 'Gaussian':
        sigma = float(cfg['denoise_sigma'])
        if sigma <= 0: raise ValueError('Denoising sigma must be positive')
        clean = _native_gaussian(clean, sigma)
    elif denoise == 'TV':
        from skimage.restoration import denoise_tv_chambolle
        weight = float(cfg['tv_weight'])
        if weight <= 0: raise ValueError('TV weight must be positive')
        # The reference notebook uses 0–1 input. A fixed dataset range converts
        # that dimensionless weight to Raw units without per-frame normalization.
        span = float(reference['span']) if cfg['raw'] else 1.
        if np.isfinite(span) and span > 0:
            clean = _compute_tv_denoise(clean, weight=weight*span, eps=2e-4, max_num_iter=200)
    elif denoise != 'None': raise ValueError('Unknown native denoising method')
    clean = np.where(mask, clean, 0.)
    if not cfg['raw']:
        clean = np.clip((clean-.5)*cfg['contrast']+.5+cfg['brightness'], 0., 1.)
    return clean


_ROI_INTERPOLATION_CHOICES = ('Nearest-neighbor', 'Bilinear', 'Bicubic')


def _roi_interpolation_selected(owner):
    variable = getattr(owner, 'roi_interpolation_var', None)
    method = 'Bicubic' if variable is None else str(variable.get())
    if method not in _ROI_INTERPOLATION_CHOICES:
        raise ValueError('Choose Nearest-neighbor, Bilinear or Bicubic interpolation.')
    return method


def _roi_resample(values, shape, method, raw=True, phase=False):
    """Resize the same confirmed ROI using pixel-center coordinates."""
    if method not in _ROI_INTERPOLATION_CHOICES:
        raise ValueError('Unknown ROI interpolation method')
    shape = tuple(map(int, shape))
    if len(shape) != 2 or min(shape) < 1:
        raise ValueError('Output dimensions must be positive')
    image = np.asarray(values, dtype=np.float64 if raw else np.float32)
    if image.shape == shape: return image.copy()
    if not raw:
        methods = {'Nearest-neighbor': Image.Resampling.NEAREST,
                   'Bilinear': Image.Resampling.BILINEAR, 'Bicubic': Image.Resampling.BICUBIC}
        result = np.asarray(Image.fromarray(image).resize((shape[1], shape[0]), methods[method]), dtype=np.float32)
        return np.clip(result, 0., 1.)
    if method == 'Bicubic':
        # Retain the existing validated cubic GPU/CPU implementation, including
        # its circular phase interpolation rather than interpolating wrapped angles.
        return _compute_raw_resize(image, shape, phase)
    order = 0 if method == 'Nearest-neighbor' else 1
    ratio = np.asarray(image.shape, dtype=float)/shape
    offset = .5*ratio-.5
    circular = phase and order > 0

    def cpu():
        from scipy.ndimage import affine_transform
        def sample(array):
            return affine_transform(array, np.diag(ratio), offset=offset, output_shape=shape,
                                    order=order, mode='nearest', prefilter=False)
        if circular: return np.arctan2(sample(np.sin(image)), sample(np.cos(image)))
        return sample(image)

    def gpu(cp):
        from cupyx.scipy.ndimage import affine_transform
        array = cp.asarray(image)
        matrix = cp.asarray(ratio); shift = cp.asarray(offset)
        def sample(data):
            return affine_transform(data, matrix, offset=shift, output_shape=shape,
                                    order=order, mode='nearest', prefilter=False)
        result = cp.arctan2(sample(cp.sin(array)), sample(cp.cos(array))) if circular else sample(array)
        return cp.asnumpy(result)

    key = (image.shape, shape, method, bool(phase))
    return _compute_image_operation('ROI '+method+' resampling', key, cpu, gpu,
        image.nbytes+int(np.prod(shape))*8, int(np.prod(shape)), angular=circular)


def _native_render_frame(source, index, bounds, local, resized_mask, width, height, reference, cfg):
    x0, x1, y0, y1 = bounds
    image = np.asarray(source[index, y0:y1+1, x0:x1+1], dtype=float).copy()
    valid = local & np.isfinite(image)
    values = image[valid]
    phase = cfg['raw'] and cfg['component'] == 'Phase'
    fill = (float(np.angle(np.mean(np.exp(1j*values)))) if phase else float(np.median(values))) if values.size else 0.
    image[~valid] = fill
    if not cfg['raw']: image = _normalize_component_frame_values(image, reference)
    image[~local] = 0.
    image = _native_process(image, local, reference, cfg)
    if not cfg['raw']:
        image = np.clip(np.nan_to_num(np.asarray(image, dtype=np.float32)), 0., 1.)
    result = _roi_resample(image, (height, width), cfg.get('interpolation', 'Bicubic'), cfg['raw'], phase)
    result[~resized_mask] = 0.
    return result



def _native_build_stack(owner, bounds, local, resized_mask, width, height):
    from concurrent.futures import ThreadPoolExecutor
    global _compute_batch_frames
    cfg = _native_config(owner); source = owner.recons
    references = [_component_frame_normalization(owner, i) for i in range(len(source))]
    for reference in references: reference['intensity_mode'] = _intensity_mode(owner)
    dtype = np.float64 if cfg['raw'] else np.float32
    output = np.empty((len(source), height, width), dtype=dtype)
    render = lambda i: _native_render_frame(source, i, bounds, local, resized_mask, width, height, references[i], cfg)
    previous_batch = _compute_batch_frames; _compute_batch_frames = max(previous_batch, len(source))
    def gpu_count():
        return _compute_gpu_calls+sum(int(row.get('GPU', 0)) for row in _compute_operation_stats.values())
    try:
        before_gpu = gpu_count()
        if len(source): output[0] = render(0)
        used_gpu = gpu_count() > before_gpu
        workers = max(1, min(_compute_cpu_workers, (256*1024*1024)//max(1, width*height*np.dtype(dtype).itemsize*8)))
        parallel = not used_gpu and len(source) >= 4 and width*height >= 256*256 and workers > 1
        if parallel:
            with ThreadPoolExecutor(max_workers=workers, thread_name_prefix='native-roi-cpu') as executor:
                for start in range(1, len(source), workers):
                    indices = range(start, min(len(source), start+workers))
                    for index, frame in zip(indices, executor.map(render, indices)): output[index] = frame
        else:
            for index in range(1, len(source)): output[index] = render(index)
    finally: _compute_batch_frames = previous_batch
    owner._native_stack_config = tuple(sorted(cfg.items()))
    owner._compute_last_resize_workers = workers if parallel else 1
    owner._native_preview_cache = {}
    return output, references


def _native_preview_frame(owner, index):
    if not getattr(owner, 'roi_resolution_applied', False): raise ValueError('Apply the ROI output resolution first')
    if getattr(owner, '_roi_normalization_signature', None) != _component_normalization_signature(owner):
        raise ValueError('Apply ROI resolution again for the confirmed component')
    cfg = _native_config(owner); key = tuple(sorted(cfg.items()))
    if getattr(owner, '_native_stack_config', None) == key:
        return np.asarray(owner.roi_stack[int(index)], dtype=_intensity_dtype(owner))
    cache = getattr(owner, '_native_preview_cache', {})
    signature = (id(owner.roi_stack), key, int(index))
    if signature in cache: return cache[signature]
    crop = owner.roi_crop
    bounds = tuple(int(crop[name]) for name in ('xmin', 'xmax', 'ymin', 'ymax'))
    x0, x1, y0, y1 = bounds
    local = np.asarray(owner.roi_mask, bool)[y0:y1+1, x0:x1+1]
    height, width = owner.roi_stack.shape[1:]
    frame = _native_render_frame(owner.recons, int(index), bounds, local, owner.local_mask,
        width, height, _component_frame_normalization(owner, int(index)), cfg)
    cache[signature] = frame
    while len(cache) > 2: cache.pop(next(iter(cache)))
    owner._native_preview_cache = cache
    return frame


def _native_mark_dirty(owner, reason='Processing preview changed'):
    if getattr(owner, '_native_finalized_snapshot', None) is not None:
        owner._native_finalized_snapshot = None
        owner._native_finalized_signature = None
        for tab in (10, 11): _ii2d_clear(owner, tab)
        for name in ('roi2_stack', 'roi2_coords', 'roi2_confirmed_coords', 'line_source_stack',
                     'gauss2d_source_stack', '_lpa_stack', '_t7_stack_copy', '_tab8_primary_stack', '_tab8_roi3_stack', '_tab9_roi1_stack',
                     '_tab9_roi4_stack', '_tab10_roi4_stack', '_tab11_primary_stack'):
            setattr(owner, name, None)
        for name in ('_tab8_roi3_confirmed', '_tab9_roi1_ready', '_tab9_roi4_confirmed', '_tab10_roi4_confirmed', '_tab11_primary_ready'):
            setattr(owner, name, False)
    variable = getattr(owner, 'native_finalize_status_var', None)
    if variable is not None: variable.set(reason+' — click Finalize before downstream analysis.')


def _native_require_finalized(owner):
    snapshot = getattr(owner, '_native_finalized_snapshot', None)
    if snapshot is None or getattr(owner, '_native_finalized_signature', None) != _native_signature(owner):
        _native_mark_dirty(owner)
        raise ValueError('Tab 6: apply native processing/output resolution, then click Finalize before further calculations.')
    return snapshot


def _native_settings_changed(owner, *args):
    if getattr(owner, '_native_setting_up', False): return
    _native_mark_dirty(owner)
    try: owner._native_seen_preview_key = _native_config_key(owner)
    except (ValueError, tk.TclError):
        owner.native_finalize_status_var.set('Enter valid processing parameters, then click Finalize.')
        return
    owner._native_preview_cache = {}
    owner._tab6_exact_processed_primary_stack_signature = None
    owner._tab6_auth_stack_signature_v21 = None
    owner._native_sync_control_states()
    job = getattr(owner, '_native_preview_job', None)
    if job is not None:
        try: owner.root.after_cancel(job)
        except Exception: pass
    owner._native_preview_job = owner.root.after(160, lambda: _native_preview_refresh(owner))


def _native_preview_refresh(owner):
    owner._native_preview_job = None
    if getattr(owner, 'recons', None) is not None and getattr(owner, 'roi_resolution_applied', False):
        owner.update_processing_view()


def _native_apply(owner):
    try:
        if getattr(owner, 'roi_stack', None) is None: raise ValueError('Confirm a primary ROI in Tab 5 first')
        width, height = owner.roi_resolution
        _proc_apply_resolution(owner, width, height)
        owner._tab6_exact_processed_primary_stack_signature = None
        owner._tab6_auth_stack_signature_v21 = None
        owner.update_processing_view()
        owner.native_finalize_status_var.set('Native processing applied to all frames. Click Finalize to use this ROI for analysis.')
        return True
    except Exception as exc:
        owner.native_finalize_status_var.set(str(exc))
        messagebox.showerror('Native ROI processing', str(exc), parent=owner.root)
        return False


def _native_finalize(owner):
    try:
        if getattr(owner, 'roi_stack', None) is None: raise ValueError('Confirm a primary ROI first')
        if getattr(owner, '_native_finalized_snapshot', None) is not None and owner._native_finalized_signature == _native_signature(owner):
            return True
        job = getattr(owner, '_native_preview_job', None)
        if job is not None:
            try: owner.root.after_cancel(job)
            except Exception: pass
            owner._native_preview_job = None
        _native_config(owner)  # Validate Tk values before starting work.
        owner._native_finalizing = True
        try:
            if owner._native_stack_config != _native_config_key(owner):
                width, height = owner.roi_resolution
                _proc_apply_resolution(owner, width, height)
            if _native_sync_calibration(owner): owner.update_processing_view()
            stack, scale, source_signature = _NATIVE_OLD_DOWNSTREAM(owner)
            if stack is None: raise ValueError('The primary ROI is unavailable')
            mask = None
            candidate = getattr(owner, '_tab6_base_mask', None) if bool(getattr(owner, '_tab6_analysis_rotation_committed', False)) else owner.local_mask
            if candidate is not None:
                angle = _tab6_auth_angle_v21(owner)
                if bool(getattr(owner, '_tab6_analysis_rotation_committed', False)) and abs(angle) > 1e-12:
                    rotated = _tab6_final_rotate_array(owner, np.asarray(candidate, dtype=float), angle=angle, order=0)
                    x0,x1,y0,y1 = owner._tab6_auth_bbox_v21
                    mask = rotated[y0:y1, x0:x1] > .5
                elif np.shape(candidate) == stack.shape[1:]: mask = np.asarray(candidate, bool).copy()
            if mask is None or mask.shape != stack.shape[1:]: mask = np.ones(stack.shape[1:], bool)
            # This committed source is immutable; downstream consumers may take copies.
            frozen = np.asarray(stack, dtype=_intensity_dtype(owner))
            if np.shares_memory(frozen, owner.roi_stack): frozen = frozen.copy()
            frozen.setflags(write=False)
            mask.setflags(write=False)
            owner._native_finalized_version = int(getattr(owner, '_native_finalized_version', 0))+1
            signature = _native_signature(owner)
            owner._native_finalized_signature = signature
            owner._native_finalized_snapshot = (frozen, tuple(map(float, scale)),
                ('TAB6_FINALIZED_NATIVE_FIRST', owner._native_finalized_version, signature))
            owner._native_finalized_mask = mask
            owner._native_finalized_config = _native_config(owner)
            # The immutable commitment now supplies previews and hand-offs too.
            # Release the duplicate full-stack caches; retain the original
            # resampled native stack for future preview edits and rotation.
            owner._tab6_exact_processed_primary_stack_cache = None
            owner._tab6_exact_processed_primary_stack_signature = None
            owner._tab6_auth_stack_v21 = None
            owner._tab6_auth_stack_signature_v21 = None
        finally: owner._native_finalizing = False
        owner.native_finalize_status_var.set(f'FINALIZED | {len(frozen)} frames | {frozen.shape[2]} × {frozen.shape[1]} px | version {owner._native_finalized_version}')
        owner.log('Tab 6 finalized: native background → FFT → filter/denoise → upscale → rotation; downstream calculations use this committed ROI.')
        return True
    except Exception as exc:
        owner.native_finalize_status_var.set('Finalize unavailable: '+str(exc))
        messagebox.showerror('Finalize primary ROI', str(exc), parent=owner.root)
        return False


def _native_build_controls(owner, parent):
    owner._native_setting_up = True
    defaults = dict(native_background_var=('None', tk.StringVar), native_fft_var=('None', tk.StringVar),
        native_denoise_var=('None', tk.StringVar), native_background_sigma_var=(30., tk.DoubleVar),
        native_polynomial_degree_var=(2, tk.IntVar), native_fft_cutoff_var=(.30, tk.DoubleVar),
        native_tv_weight_var=(.02, tk.DoubleVar), native_gaussian_sigma_var=(.6, tk.DoubleVar))
    for name, (value, kind) in defaults.items():
        if not hasattr(owner, name): setattr(owner, name, kind(master=owner.root, value=value))
    owner.native_finalize_status_var = tk.StringVar(master=owner.root, value='Preview only — click Finalize before downstream analysis.')
    box = ttk.LabelFrame(parent, text='NATIVE ROI — DENOISE / BACKGROUND / FFT', padding=7)
    box.pack(fill='x', padx=6, pady=6); owner.native_controls = box
    ttk.Label(box, text='Process at original pixel resolution, then upscale once.', wraplength=365).pack(anchor='w')
    def combo(label, name, choices):
        ttk.Label(box, text=label).pack(anchor='w', pady=(6,0))
        widget = ttk.Combobox(box, textvariable=getattr(owner,name), values=choices, state='readonly', width=35)
        widget.pack(fill='x'); setattr(owner, name.replace('_var','_combo'), widget)
    def number(label, name, start, end, step):
        row = ttk.Frame(box); row.pack(fill='x', pady=2)
        ttk.Label(row, text=label).pack(side='left')
        widget = ttk.Spinbox(row, from_=start, to=end, increment=step, width=8, textvariable=getattr(owner,name))
        widget.pack(side='right'); return widget
    combo('Background correction', 'native_background_var', _NATIVE_BACKGROUND_CHOICES)
    background_sigma = number('Background sigma (native px)', 'native_background_sigma_var', 1, 300, 1)
    degree = number('Polynomial degree', 'native_polynomial_degree_var', 1, 5, 1)
    combo('Native FFT processing', 'native_fft_var', _NATIVE_FFT_CHOICES)
    cutoff = number('Gaussian cutoff / Nyquist', 'native_fft_cutoff_var', .01, 1, .01)
    combo('Post-FFT denoising', 'native_denoise_var', _NATIVE_DENOISE_CHOICES)
    tv = number('TV weight / fixed dataset range', 'native_tv_weight_var', .001, .5, .005)
    sigma = number('Denoise sigma (native px)', 'native_gaussian_sigma_var', .1, 20, .1)
    ttk.Label(box, text='None bypasses each stage. Raw values retain their units; brightness/contrast change Raw display only.', wraplength=365).pack(anchor='w', pady=(5,0))
    ttk.Button(box, text='APPLY NATIVE PROCESSING', command=lambda:_native_apply(owner)).pack(fill='x', pady=(6,0))
    def sync():
        background_sigma.configure(state='normal' if owner.native_background_var.get()=='Gaussian background subtraction' else 'disabled')
        degree.configure(state='normal' if owner.native_background_var.get()=='Polynomial background subtraction' else 'disabled')
        cutoff.configure(state='normal' if owner.native_fft_var.get()=='Gaussian FFT low-pass' else 'disabled')
        tv.configure(state='normal' if owner.native_denoise_var.get()=='TV' else 'disabled')
        sigma.configure(state='normal' if owner.native_denoise_var.get()=='Gaussian' else 'disabled')
    owner._native_sync_control_states = sync; sync()
    for name in defaults: getattr(owner,name).trace_add('write', lambda *a:_native_settings_changed(owner))
    owner._native_setting_up = False


def _focused_json(value):
    if isinstance(value, (bytes, np.bytes_)):
        value = value.decode('utf-8')
    if isinstance(value, str):
        value = json.loads(value)
    return value if isinstance(value, dict) else {}


def _resolve_focused_metadata(self, h5, metadata, dataset_path):
    """Resolve crop metadata by specificity: dataset, group, root settings."""
    dataset = h5[dataset_path]
    group = dataset.parent
    settings = _focused_json(metadata.get('settings_json',{})).copy()
    display = {}
    for owner in (group,dataset):
        display.update(_focused_json(owner.attrs.get('display_settings_json',{})))
        for key in ('roi','primary_mode','experimental_setup','focus'):
            if key in owner.attrs:
                value = self._decode_h5_value(owner.attrs[key])
                if isinstance(value,str) and key in ('roi','focus','experimental_setup'):
                    value = json.loads(value)
                display[key] = value
    support = h5['modal_supports']
    full_shape = tuple(int(v) for v in support.shape[-2:])
    declared = metadata.get('reconstruction_shape')
    if declared is not None and tuple(int(v) for v in declared) != full_shape:
        raise ValueError(f'reconstruction_shape {declared} disagrees with modal_supports {full_shape}.')
    metadata['reconstruction_shape'] = list(full_shape)
    if 'roi' in display:
        settings['DISPLAY_ROI'] = display['roi']
        crop_source = 'focused dataset/group metadata'
    else:
        crop_source = 'root settings_json'
    if 'primary_mode' in display:
        settings['primary_mode'] = int(display['primary_mode'])
    metadata['settings_json'] = json.dumps(settings)
    roi = self._read_newv2_display_roi(metadata)
    if roi is None:
        if tuple(dataset.shape) != full_shape:
            raise ValueError(f'{dataset_path} is a crop {dataset.shape}, but its source ROI is missing; cannot infer its position from shape alone.')
        roi = (slice(0,full_shape[0]),slice(0,full_shape[1]))
        crop_source = 'verified full-grid focused dataset'
    normalized = []
    for sl,n in zip(roi,full_shape):
        step = 1 if sl.step is None else int(sl.step)
        start = 0 if sl.start is None else int(sl.start)
        stop = n if sl.stop is None else int(sl.stop)
        if start < 0: start += n
        if stop < 0: stop += n
        if step <= 0 or not 0 <= start < stop <= n:
            raise ValueError(f'Invalid focused ROI slice {sl} for source size {n}; no silent clipping is allowed.')
        normalized.append([start,stop,step])
    expected = tuple(len(range(*sl)) for sl in normalized)
    if expected != tuple(dataset.shape):
        raise ValueError(f'Saved ROI describes {expected}, but {dataset_path} contains {dataset.shape}.')
    mode = self._newv2_primary_mode(metadata)
    if (support.ndim == 3 and not 0 <= mode < support.shape[0]) or (support.ndim == 2 and mode != 0):
        raise ValueError(f'Primary mode {mode} is not available in modal_supports {support.shape}.')
    settings['DISPLAY_ROI'] = normalized
    metadata['settings_json'] = json.dumps(settings)
    display['roi'] = normalized
    return display,dict(dataset=dataset_path,native_shape=list(dataset.shape),
        source_grid=list(full_shape),roi=normalized,primary_mode=mode,crop_source=crop_source)

def _focused_grid_description(self, info, shape):
    """Describe any verified focused crop in physical or native-grid coordinates."""
    if info.get('format') == 'new_v2_full_state':
        return _full_state_grid_description(self,info,shape)
    if info.get('format') != 'new_v2':
        return None
    meta = info.get('metadata',{})
    settings = _focused_json(meta.get('settings_json',{}))
    display = info.get('focused_display',{})
    grid = tuple(int(v) for v in meta.get('reconstruction_shape',[]))
    roi = self._read_newv2_display_roi(meta)
    if len(grid) != 2 or roi is None:
        return None
    normalized = tuple(sl.indices(n) for sl,n in zip(roi,grid))
    if any(step <= 0 for _,_,step in normalized):
        raise ValueError('Focused crop strides must be positive.')
    if tuple(len(range(*sl)) for sl in normalized) != tuple(shape):
        raise ValueError(f'Focused ROI {normalized} disagrees with dataset {shape}.')
    setup = display.get('experimental_setup',settings.get('DISPLAY_SETUP',{}))
    keys = (setup.get('energy',meta.get('energy_eV')),setup.get('ccd_dist'),setup.get('px_size'))
    units = 'px'
    sy = sx = 1.
    if any(v is not None for v in keys):
        if all(v is not None for v in keys):
            energy,distance,pitch = map(float,keys)
            preprocess = _focused_json(meta.get('preprocess_config_json',{}))
            bins = [float(preprocess.get('binning',1)),float(meta.get('retrieval_binning',settings.get('RETRIEVAL_BINNING',1)))]
            if not np.isfinite([energy,distance,pitch]+bins).all() or min([energy,distance,pitch]+bins) <= 0 or any(int(b)!=b for b in bins):
                raise ValueError('Optical sampling and binning must be finite, positive; binning must be integral.')
            sy,sx = [1239.8419843320026/energy*distance/(n*pitch*np.prod(bins)) for n in grid]
            units = 'nm'
        else:
            self.log(f'Incomplete optical metadata for {info.get("path")}; preserving native-grid pixel coordinates, not inventing nm.')
    ys,xs = normalized
    focus = display.get('focus',{})
    signature = [focus.get(k,settings.get(v)) for k,v in
        [('focus_um','DISPLAY_PROP_UM'),('phase_rad','DISPLAY_PHASE_RAD'),('dx','DISPLAY_PROP_DX'),('dy','DISPLAY_PROP_DY')]]
    signature = [None if v is None else float(v) for v in signature]
    return dict(shape=grid,roi=normalized,sx=sx*xs[2],sy=sy*ys[2],
        x0=(xs[0]-grid[1]//2)*sx,y0=(ys[0]-grid[0]//2)*sy,units=units,
        focus=signature,mode=self._newv2_primary_mode(meta),
        dataset=info.get('dataset_path','focused_differences/poisson'))


def _prepare_focused_grid(self, images, masks, infos, paths):
    """Plan a shared analysis grid from loaded crop metadata, independent of acquisition."""
    if not images or not (len(images)==len(masks)==len(infos)==len(paths)):
        raise ValueError('Loaded image, support and metadata counts do not match.')
    _confirm_reconstruction_signal(self,infos)
    focused = [i for i in infos if i.get('format') in ('new_v2','new_v2_full_state')]
    if len({(i.get('dataset_path','focused_differences/poisson'),self._newv2_primary_mode(i.get('metadata',{}))) for i in focused}) > 1:
        raise ValueError('Selected focused files mix reconstruction stages or primary modes; choose consistent exports.')
    descriptions = [_focused_grid_description(self,info,a.shape) for a,info in zip(images,infos)]
    shapes = {a.shape for a in images}
    known = all(g is not None for g in descriptions)
    if not known:
        if len(shapes)==1 and not focused:
            return images,next((m for m in masks if m is not None),None),None
        raise ValueError('Different/unknown focused crops cannot be combined without verified ROI and source-grid metadata; arbitrary stretching is disabled.')
    units = {g['units'] for g in descriptions}
    if len(units)!=1:
        raise ValueError('Some focused crops have physical sampling while others do not; supply consistent optical metadata.')
    if units=={'px'} and len({g['shape'] for g in descriptions})!=1:
        raise ValueError('Different source grids require optical metadata to establish physical sampling.')
    ref=descriptions[0]
    for g in descriptions[1:]:
        for a,b in zip(g['focus'],ref['focus']):
            if (a is None)!=(b is None) or (a is not None and not np.isclose(a,b,rtol=1e-9,atol=1e-9)):
                raise ValueError('Focused crops use inconsistent focus/phase/shift settings; crop adaptation cannot correct different signal conventions.')
    aligned = len(shapes)==1 and all(np.allclose([g[k] for k in ('sx','sy','x0','y0')],
        [ref[k] for k in ('sx','sy','x0','y0')],rtol=1e-9,atol=1e-7) for g in descriptions)
    if aligned:
        return images,next((m for m in masks if m is not None),None),None
    sx=max(g['sx'] for g in descriptions)
    sy=max(g['sy'] for g in descriptions)
    # Independent X/Y sampling handles rectangular grids and positive ROI strides.
    index=max(range(len(images)),key=lambda i:descriptions[i]['sx']*descriptions[i]['sy'])
    ref=descriptions[index]
    low=[max(g[k] for g in descriptions) for k in ('x0','y0')]
    high=[min(g['x0']+(a.shape[1]-1)*g['sx'] for a,g in zip(images,descriptions)),
          min(g['y0']+(a.shape[0]-1)*g['sy'] for a,g in zip(images,descriptions))]
    starts=[int(np.ceil((lo-origin)/step-1e-9)) for lo,origin,step in zip(low,[ref['x0'],ref['y0']],[sx,sy])]
    ends=[int(np.floor((hi-origin)/step+1e-9)) for hi,origin,step in zip(high,[ref['x0'],ref['y0']],[sx,sy])]
    x=ref['x0']+np.arange(starts[0],ends[0]+1)*sx
    y=ref['y0']+np.arange(starts[1],ends[1]+1)*sy
    if min(len(x),len(y))<9:
        raise ValueError('Saved focused crops have insufficient shared coverage (minimum 9 x 9 analysis samples).')
    unit=ref['units']
    source_label = 'full retrieval grids' if all(i.get('format')=='new_v2_full_state' for i in infos) else 'focused crops'
    summary=(f'Loaded {source_label}: {sorted(shapes)}.\n'
        f'Shared analysis grid: {len(x)} x {len(y)} pixels; X {sx:.6g}, Y {sy:.6g} {unit}/sample.\n\n'
        'Adapt to the shared coverage? Original files remain unchanged. Complex components use bilinear '
        'interpolation only where necessary; support masks use nearest-neighbor and common intersection. '
        'No missing area is filled with measured zeros. Verify Tab 5 calibration before physical measurements.')
    if not messagebox.askyesno('Align full retrieval states' if source_label=='full retrieval grids' else 'Adapt saved focused crops',summary,parent=self.root):
        raise ValueError('Focused-crop alignment cancelled; no new stack was loaded.')
    from scipy.ndimage import map_coordinates
    xx,yy=np.meshgrid(x,y)
    result=[]; common=np.ones(xx.shape,bool); records=[]
    for image,mask,g,p in zip(images,masks,descriptions,paths):
        if mask is None or mask.shape!=image.shape:
            raise ValueError(f'Focused-crop adaptation requires matching support: {p}')
        coords=np.array([(yy-g['y0'])/g['sy'],(xx-g['x0'])/g['sx']])
        if (coords[0].min() < -1e-7 or coords[1].min() < -1e-7 or
                coords[0].max() > image.shape[0]-1+1e-7 or coords[1].max() > image.shape[1]-1+1e-7):
            raise ValueError(f'Shared grid exceeds available focused samples: {p}')
        coords[0]=np.clip(coords[0],0,image.shape[0]-1)
        coords[1]=np.clip(coords[1],0,image.shape[1]-1)
        integer=np.allclose(coords,np.rint(coords),rtol=0,atol=1e-8)
        if integer:
            row,col=np.rint(coords).astype(int)
            sampled=image[row,col].copy()
            sampled_mask=mask[row,col]
        else:
            sampled=(map_coordinates(image.real,coords,order=1,mode='nearest',prefilter=False)
                     +1j*map_coordinates(image.imag,coords,order=1,mode='nearest',prefilter=False))
            sampled_mask=map_coordinates(mask.astype(np.uint8),coords,order=0,mode='nearest',prefilter=False).astype(bool)
        common &= sampled_mask
        result.append(sampled)
        records.append(dict(path=str(p),native_shape=list(image.shape),source_grid=g,
                            interpolation='none; exact pixel selection' if integer else 'bilinear complex'))
    if not common.any():
        raise ValueError('Adapted focused support masks have no common supported pixels.')
    ys,xs=ref['roi']
    ratio_x=sx/ref['sx'];ratio_y=sy/ref['sy']
    native_reference=np.isclose(ratio_x,round(ratio_x)) and np.isclose(ratio_y,round(ratio_y))
    ref_roi=None
    if native_reference:
        ref_roi=[[ys[0]+int(round(starts[1]*ratio_y))*ys[2],ys[0]+int(round((ends[1]*ratio_y+1)))*ys[2],int(round(ratio_y))*ys[2]],
                 [xs[0]+int(round(starts[0]*ratio_x))*xs[2],xs[0]+int(round((ends[0]*ratio_x+1)))*xs[2],int(round(ratio_x))*xs[2]]]
    grid=dict(shape=list(xx.shape),sx_nm=sx if unit=='nm' else None,sy_nm=sy if unit=='nm' else None,
        spacing_x=sx,spacing_y=sy,coordinate_units=unit,origin_nm=[float(x[0]),float(y[0])] if unit=='nm' else None,
        coordinate_origin=[float(x[0]),float(y[0])],reference_path=str(paths[index]),reference_full_shape=ref['shape'],
        reference_roi=ref_roi,sources=records,method='metadata-driven shared focused coverage; no extrapolation')
    self.log('Focused-crop adaptation: '+summary.replace('\n',' '))
    return result,common,grid


def _magnet_split_branches(current, field):
    cur, fld = np.asarray(current, dtype=float), np.asarray(field, dtype=float)
    if cur.ndim != 1 or fld.ndim != 1 or len(cur) != len(fld) or len(cur) < 2:
        raise ValueError('Calibration current/field must be equal-length 1-D arrays with at least two points.')
    if not np.isfinite(cur).all() or not np.isfinite(fld).all():
        raise ValueError('Calibration contains nonfinite current or field values.')
    spans = []
    start, direction = 0, 0
    for index in range(1, len(cur)):
        delta = cur[index]-cur[index-1]
        sign = int(np.sign(delta))
        if not sign:
            if not np.isclose(fld[index], fld[index-1], rtol=1e-9, atol=1e-9):
                raise ValueError('Consecutive duplicate currents have different fields; select a clean measured sweep.')
            continue
        if direction and sign != direction:
            spans.append((start,index))
            start = index-1
        direction = sign
    spans.append((start,len(cur)))
    branches = []
    for start, end in spans:
        raw_x, raw_y = cur[start:end], fld[start:end]
        order = np.argsort(raw_x, kind='stable')
        x, indices = np.unique(raw_x[order], return_index=True)
        y = raw_y[order][indices]
        if len(x) < 2:
            continue
        label = f'Branch {len(branches)+1}: {raw_x[0]:+g} to {raw_x[-1]:+g} A'
        branches.append(dict(label=label, current=x, field=y, raw_current=raw_x,
            raw_field=raw_y, span=float(x[-1]-x[0])))
    if not branches:
        raise ValueError('Calibration does not contain a measured current interval.')
    return branches


def _magnet_install_controls(self, parent):
    self._fixed_magnet_calibration = None
    self.magnet_fix_status_var = tk.StringVar(value='Not fixed for new uploads')
    self.magnet_fix_button = ttk.Button(parent, text='Fix', command=lambda: _magnet_toggle_fix(self))
    self.magnet_fix_button.pack(fill='x', pady=4)
    ttk.Label(parent, textvariable=self.magnet_fix_status_var,
        wraplength=360, justify='left').pack(fill='x', pady=(0, 4))
    self._magnet_branches = []
    self._magnet_calibration_file_key = None
    self._magnet_selected_label = ''
    self.magnet_branch_var = tk.StringVar(value='')
    self.magnet_calibration_status_var = tk.StringVar(value='Current (A) -> field (mT); no calibration loaded')
    ttk.Label(parent, text='Measured calibration branch').pack(anchor='w')
    self.magnet_branch_combo = ttk.Combobox(parent, textvariable=self.magnet_branch_var,
        state='disabled', width=36)
    self.magnet_branch_combo.pack(fill='x', pady=3)
    self.magnet_branch_combo.bind('<<ComboboxSelected>>', lambda event: _magnet_branch_changed(self))
    ttk.Label(parent, textvariable=self.magnet_calibration_status_var,
        wraplength=360, justify='left').pack(fill='x', pady=3)


def _magnet_default_branch(branches):
    # Prefer the measured +4 A -> -4 A sweep regardless of JSON branch order.
    descending = [b for b in branches
        if b['raw_current'][0] >= 4.0 - 1e-9 and b['raw_current'][-1] <= -4.0 + 1e-9]
    return max(descending or branches, key=lambda b: b['span'])


def _magnet_save_fixed(self):
    self._fixed_magnet_calibration = copy.deepcopy(dict(
        file=self.field_calib_file, key=self._magnet_calibration_file_key,
        branches=self._magnet_branches, label=self._magnet_selected_label))
    self.magnet_fix_button.configure(text='Unfix')
    self.magnet_fix_status_var.set(
        f'Fixed for new uploads: {Path(self._magnet_calibration_file_key).name} | {self._magnet_selected_label}')


def _magnet_toggle_fix(self):
    if self._fixed_magnet_calibration is not None:
        self._fixed_magnet_calibration = None
        self.magnet_fix_button.configure(text='Fix')
        self.magnet_fix_status_var.set('Not fixed for new uploads')
        return True
    if (self.field_interpolator is None or not self._magnet_branches
            or not self.field_calib_file
            or str(Path(self.field_calib_file).resolve()) != self._magnet_calibration_file_key):
        self.magnet_fix_status_var.set('Load a valid calibration before clicking Fix.')
        return False
    _magnet_save_fixed(self)
    self.log('Calibration fixed for subsequent datasets and New Upload.')
    return True


def _magnet_restore_fixed(self, fixed):
    self._fixed_magnet_calibration = copy.deepcopy(fixed)
    self.magnet_fix_button.configure(text='Unfix' if fixed is not None else 'Fix')
    if fixed is None:
        self.magnet_branch_combo.configure(values=(), state='disabled')
        self.magnet_fix_status_var.set('Not fixed for new uploads')
        return
    # Retain the validated measured values, even if the original file is moved.
    self.field_calib_file = fixed['file']
    self.calib_var.set(str(fixed['file']))
    self._magnet_calibration_file_key = fixed['key']
    self._magnet_branches = copy.deepcopy(fixed['branches'])
    self.magnet_branch_combo.configure(
        values=tuple(b['label'] for b in self._magnet_branches), state='readonly')
    branch = next(b for b in self._magnet_branches if b['label'] == fixed['label'])
    _magnet_activate_branch(self, branch)


def _magnet_prepare_dataset_calibration(self):
    if self._fixed_magnet_calibration is not None:
        _magnet_restore_fixed(self, self._fixed_magnet_calibration)
        return True
    return self.load_calibration()


def _magnet_activate_branch(self, branch):
    self.calib_current = branch['current'].copy()
    self.calib_field_mT = branch['field'].copy()
    self.field_interpolator = interp1d(self.calib_current, self.calib_field_mT,
        kind='linear', bounds_error=False, fill_value=np.nan)
    self._magnet_selected_label = branch['label']
    self.magnet_branch_var.set(branch['label'])
    self.magnet_calibration_status_var.set(
        f'{branch["label"]}; range {self.calib_current[0]:+g} to {self.calib_current[-1]:+g} A. No extrapolation.')
    if self._fixed_magnet_calibration is not None:
        _magnet_save_fixed(self)
    self.log('Magnet calibration: '+self.magnet_calibration_status_var.get())


def _magnet_branch_changed(self):
    branch = next((b for b in self._magnet_branches if b['label']==self.magnet_branch_var.get()), None)
    if branch is None:
        return False
    _magnet_activate_branch(self, branch)
    _magnet_apply_fields(self, refresh=True)
    return True


def _magnet_apply_fields(self, refresh=False):
    current = getattr(self, 'current_values_A', None)
    if current is None:
        if refresh:
            self._plot_field_calibration()
        return
    current = np.asarray(current, dtype=float)
    if current.ndim != 1:
        raise ValueError('Loaded reconstruction currents must be one-dimensional.')
    explicit = getattr(self, '_reconstruction_h5_fields_mT', None)
    if explicit is None or np.shape(explicit) != current.shape:
        explicit = np.full(current.shape, np.nan)
    fields = np.asarray(explicit, dtype=float).copy()
    sources = np.full(current.shape, 'unavailable', dtype=object)
    sources[np.isfinite(fields)] = 'h5_field_mT'
    known_current = np.isfinite(current) & ~np.isfinite(fields)
    sources[known_current] = 'uncalibrated_current_A'
    if self.field_interpolator is not None and known_current.any():
        fields[known_current] = np.asarray(self.field_interpolator(current[known_current]), dtype=float)
        sources[known_current] = np.where(np.isfinite(fields[known_current]),
            'calibrated_current_A', 'outside_calibration_range')
    previous = getattr(self, 'real_fields_mT', None)
    changed = previous is None or np.shape(previous)!=fields.shape or not np.allclose(previous, fields, equal_nan=True)
    self.real_fields_mT = fields
    self.field_value_source = sources
    self.field_calibration_branch_by_frame = np.where(sources=='calibrated_current_A',
        getattr(self, '_magnet_selected_label', ''), '')
    outside = int(np.count_nonzero(sources=='outside_calibration_range'))
    if outside:
        self.log(f'{outside} frame(s) outside the selected calibration range; field remains unavailable, not extrapolated.')
    if refresh:
        self._plot_field_calibration()
        if changed:
            _magnet_refresh_results(self)


def _magnet_refresh_results(self):
    # Re-label existing results; calibration does not require refitting image data.
    if getattr(self, 'recons', None) is None:
        return
    self.field_label_var.set(self._field_label_for_frame(int(self.current_index)))
    if getattr(self, '_figs', {}).get('recon') is not None:
        self.show_current_recon()
    if getattr(self, '_figs', {}).get('roi') is not None:
        _tab4_component_refresh_roi_image(self)
    if getattr(self, 'pd_results', None):
        _tab8_cancel_batch(self, status=False)
        for frame in list(self.pd_results):
            _tab8_v7_refresh_density_row(self, frame)
        _tab8_v7_refresh_table(self)
        _tab8_v7_plot(self)
        _tab8_v7_particle_number_size_plot(self)
        _tab8_v7_plot_dfit(self)
    if hasattr(self, '_tab10_intensity_profiles'):
        _tab10_sync_intensity_values(self)
        _tab10_plot_axis_changed(self)
        _tab10_plot_intensity(self)
    if hasattr(self, '_tab11_intensity_profiles'):
        _tab11_sync_intensity(self)
        for attr, axis, mode in [('_tab11_current_tracking_df','tab11_ax_current_tracking','current'),
                                  ('_tab11_tracking_df','tab11_ax_all_tracking','all')]:
            df = getattr(self, attr, None)
            if isinstance(df, pd.DataFrame) and not df.empty:
                _tab11_plot_tracking_panel(self, df, getattr(self, axis), mode=mode)
        _tab11_plot_intensity(self)

    if hasattr(self, 'domain_periodicity'):
        self.domain_periodicity.refresh_fields()


def _magnet_load_calibration(self):
    if not self.field_calib_file:
        messagebox.showwarning('Calibration', 'Select the calibration JSON first.', parent=self.root)
        return False
    try:
        with open(self.field_calib_file, 'r', encoding='utf-8') as handle:
            data = json.load(handle)
        branches = _magnet_split_branches(data['current'], data['field'])
        file_key = str(Path(self.field_calib_file).resolve())
        previous = self._magnet_selected_label if self._magnet_calibration_file_key == file_key else ''
        # Preserve an explicit choice; default to the measured +4 A -> -4 A sweep.
        branch = next((b for b in branches if b['label']==previous), None)
        if branch is None:
            branch = _magnet_default_branch(branches)
    except (OSError, ValueError, TypeError, KeyError) as exc:
        self.field_interpolator = self.calib_current = self.calib_field_mT = None
        self._magnet_branches = []
        self._magnet_selected_label = ''
        self._magnet_calibration_file_key = None
        self.magnet_branch_var.set('')
        self.magnet_branch_combo.configure(values=(), state='disabled')
        self.magnet_calibration_status_var.set(f'Calibration invalid: {exc}')
        self.log(self.magnet_calibration_status_var.get())
        _magnet_apply_fields(self, refresh=True)
        return False
    self._magnet_branches = branches
    self._magnet_calibration_file_key = file_key
    self.magnet_branch_combo.configure(values=tuple(b['label'] for b in branches), state='readonly')
    _magnet_activate_branch(self, branch)
    _magnet_apply_fields(self, refresh=True)
    return True


def _tab8_advanced_visibility(self):
    if self.pd_advanced_var.get():
        self._tab8_advanced_panel.grid()
    else:
        self._tab8_advanced_panel.grid_remove()

def _tab8_core_visibility(self):
    enabled = self.pd_core_analysis_var.get()
    if enabled:
        self._tab8_core_sizes.pack(fill='x', before=self._tab8_advanced_filters_host, pady=3)
    else:
        self._tab8_core_sizes.pack_forget()
    filters = getattr(self, '_tab8_core_filters_host', None)
    if filters is not None and filters.winfo_exists():
        if enabled:
            filters.pack(fill='x', pady=3)
        else:
            filters.pack_forget()
    _tab8_cancel_batch(self, status=False)

def _inspect_full_retrieval_state(self, h5, metadata, fp, dataset_path):
    role=str(metadata.get('reconstruction_role',metadata.get('role',''))).strip().lower()
    source=str(metadata.get('source_file','')).strip().lower()
    if source=='saturated_hologram' or role in ('reference','saturated','saturation_reference') or str(metadata.get('is_reference','')).lower()=='true':
        raise KeyError('Saturation/reference reconstruction is not an acquisition frame; it is excluded from state discovery.')
    dataset=h5[dataset_path]
    if dataset.ndim not in (2,3) or min(dataset.shape[-2:])<2:
        raise ValueError(f'{dataset_path} must be a 2-D state or a 3-D modal stack, got {dataset.shape}.')
    domain=str(self._decode_h5_value(dataset.attrs.get('field_domain',dataset.parent.attrs.get('field_domain','')))).lower()
    if 'fourier' in domain:
        raise ValueError('Full-grid analysis requires a real/object-space reconstruction, not a Fourier-domain field.')
    shape=tuple(map(int,dataset.shape[-2:]))
    declared=metadata.get('reconstruction_shape')
    if declared is not None and tuple(map(int,np.asarray(declared).ravel()))!=shape:
        raise ValueError(f'Declared retrieval grid {declared} differs from saved state {shape}.')
    settings=_focused_json(metadata.get('settings_json',{})).copy()
    saved_settings=settings.copy()
    mode_value=settings.get('primary_mode',0)
    for owner in (dataset.parent,dataset):
        display=_focused_json(owner.attrs.get('display_settings_json',{}))
        mode_value=display.get('primary_mode',mode_value)
        if 'experimental_setup' in display:
            settings['DISPLAY_SETUP']=display['experimental_setup']
        if 'experimental_setup' in owner.attrs:
            settings['DISPLAY_SETUP']=_focused_json(owner.attrs['experimental_setup'])
        if 'primary_mode' in owner.attrs:
            mode_value=owner.attrs['primary_mode']
    number=float(mode_value)
    if not np.isfinite(number) or not number.is_integer():
        raise ValueError('Full-state primary mode must be an integer.')
    mode=int(number)
    if mode<0 or (dataset.ndim==3 and mode>=dataset.shape[0]):
        raise ValueError(f'Primary mode {mode} unavailable in {dataset_path} {dataset.shape}.')
    support=h5.get('modal_supports')
    if support is not None:
        if not isinstance(support,h5py.Dataset) or support.ndim not in (2,3) or tuple(support.shape[-2:])!=shape:
            raise ValueError('Full-state support does not match its retrieval grid.')
        if support.ndim==3 and mode>=support.shape[0]:
            raise ValueError('Primary mode is unavailable in full-state support.')
    roi=[[0,shape[0],1],[0,shape[1],1]]
    settings['DISPLAY_ROI']=roi
    settings['primary_mode']=mode
    metadata=dict(metadata,reconstruction_shape=list(shape),settings_json=json.dumps(settings))
    current=self._metadata_number(metadata,['current_A','magnet_A','current','current_a','applied_current_A','I_A'])
    field=self._metadata_number(metadata,['field_mT','field_mt','magnetic_field_mT','B_mT'])
    point=self._metadata_number(metadata,['point_number','point','loop_point'])
    order=self._metadata_number(metadata,['observation_order','cache_index'])
    raw=current if current is not None else field if field is not None else order if order is not None else point if point is not None else 0.
    return dict(format='new_v2_full_state',signal_kind='full_retrieved_state',path=fp,
        dataset_path=dataset_path,shape=shape,primary_mode=mode,metadata=metadata,
        saved_settings=saved_settings,support_available=support is not None,
        current_A=np.nan if current is None else current,field_mT=np.nan if field is None else field,
        raw_value=float(raw),raw_kind='current_A' if current is not None else 'field_mT' if field is not None else 'metadata_order',
        point_number=np.nan if point is None else point,observation_order=float(raw if order is None else order),
        sort_key=(0,float(raw if order is None else order),str(fp).lower()))


def _load_full_retrieval_state(self,h5,info):
    dataset=h5[info['dataset_path']]
    mode=info['primary_mode']
    image=np.asarray(dataset[mode] if dataset.ndim==3 else dataset[()],dtype=np.complex128)
    if image.shape!=tuple(info['shape']) or not np.isfinite(image).all():
        raise ValueError('Full retrieval state is nonfinite or has changed dimensions.')
    dataset=h5.get('modal_supports')
    support=np.ones(image.shape,bool) if dataset is None else np.asarray(dataset[mode] if dataset.ndim==3 else dataset[()],dtype=bool)
    if support.shape!=image.shape or not support.any():
        raise ValueError('Full retrieval state has incompatible or empty support.')
    info['support_native_to_image']=True
    return image,np.array(support,copy=True),info


def _confirm_reconstruction_signal(self,infos):
    full=[info for info in infos if info.get('format')=='new_v2_full_state']
    if not full:
        return
    if len(full)!=len(infos):
        raise ValueError('Full reconstructed states cannot be mixed with focused/legacy difference signals. Load them as separate acquisitions.')
    shapes=sorted({tuple(info['shape']) for info in full})
    stages=sorted({info['dataset_path'] for info in full})
    if len(stages)!=1 or len({info['primary_mode'] for info in full})!=1:
        raise ValueError('Full-state files must use consistent reconstruction stages and primary modes.')
    message=(f'No saved focused difference is available in these {len(full)} files.\n'
        f'Native full retrieval grids (rows, columns): {shapes}\nSource: {stages[0]} | Primary mode: {full[0]["primary_mode"]}\n\n'
        'Proceed with FULL RECONSTRUCTED STATE analysis?\n'
        'This is not the focused state-minus-saturation difference. No saturation subtraction, '
        'display focusing, phase shift, or saved focused ROI is applied. '
        'All downstream measurements will use this explicitly selected state signal. '
        'Verify Tab 5 physical pixel calibration before size measurements.')
    if not messagebox.askyesno('Confirm full-grid STATE analysis',message,parent=self.root):
        raise ValueError('Full-grid state analysis cancelled; no new stack loaded.')
    self.log('User confirmed full-grid reconstructed STATE analysis, not focused difference.')


def _full_state_grid_description(self,info,shape):
    metadata=info['metadata'].copy()
    settings=_focused_json(metadata.get('settings_json',{})).copy()
    setup=settings.get('DISPLAY_SETUP',{})
    settings['DISPLAY_ROI']=[[0,shape[0],1],[0,shape[1],1]]
    metadata['settings_json']=json.dumps(settings)
    view=dict(info,format='new_v2',metadata=metadata,
        focused_display=dict(roi=settings['DISPLAY_ROI'],experimental_setup=setup,
            focus=dict(focus_um=0.,phase_rad=0.,dx=0.,dy=0.)))
    return _focused_grid_description(self,view,shape)


class CDIWorkflowApp:

    def __init__(self, root):
        self.root = root
        self.root.title('X-Ray Hologram Reconstruction')
        self.root.geometry('1500x950')
        self.root.minsize(1200, 800)
        self.data_dir = None
        self.hdf5_files = []
        self.ramp_direction_var = tk.StringVar(value='Ramp Up (- to +)')
        self.ramp_direction_status_var = tk.StringVar(value='Dataset direction: --')
        # Two-folder cycle input: one complete -1 A -> +1 A acquisition and
        # one complete +1 A -> -1 A acquisition. These are intentionally
        # kept separate from the single-folder ramp modes.
        self._cycle_neg_to_pos_dir = None
        self._cycle_pos_to_neg_dir = None
        self._cycle_neg_to_pos_items = []
        self._cycle_pos_to_neg_items = []
        self._cycle_folders_active = False
        self._cycle_folder_prompt_direction = None
        # Global reconstruction index for two-folder cycle mode. Folder 1
        # occupies 0..N and Folder 2 occupies N+1..M.
        self.reconstruction_global_indices = np.asarray([], dtype=int)
        self._cycle_global_index_by_path = {}
        self._last_ramp_direction = self.ramp_direction_var.get()
        self.field_calib_file = None
        self.frc_file = None
        self.mask_lib = None
        self.mask_lib_path = None
        self.field_interpolator = None
        self.calib_current = None
        self.calib_field_mT = None
        self.recons = None
        self.complex_recons = None
        self.real_recons = None
        self.imag_recons = None
        self.amplitude_recons = None
        self.phase_recons = None
        self.supportmask = None
        self.supportmask2 = None
        self.raw_fields = None
        self.real_fields_mT = None
        self.current_values_A = None
        self.field_value_source = None
        self.reconstruction_metadata_by_path = {}
        self.reconstruction_formats = None
        self.roi_mask = None
