    def _build_log_tab(self):
        if self.log_text is not None:
            try:
                self.log_text.destroy()
            except Exception:
                pass
        self.log_text = tk.Text(self.tab_log, wrap='word')
        self.log_text.pack(fill='both', expand=True, padx=8, pady=8)

        def clear_log():
            self._log_messages.clear()
            self.log_text.delete('1.0', 'end')
        ttk.Button(self.tab_log, text='Clear log', command=clear_log).pack(pady=5)
        if self._log_messages:
            self.log_text.insert('end', '\n'.join(self._log_messages) + '\n')
            self.log_text.see('end')

    def log(self, msg):
        text = str(msg)
        print(text)
        if not hasattr(self, '_log_messages'):
            self._log_messages = []
        self._log_messages.append(text)
        widget = getattr(self, 'log_text', None)
        if widget is not None:
            try:
                widget.insert('end', text + '\n')
                widget.see('end')
            except tk.TclError:
                self.log_text = None
        status_var = getattr(self, 'status_var', None)
        if status_var is not None:
            try:
                status_var.set(text[:180])
            except tk.TclError:
                pass
        try:
            if not globals().get('_startup_building', False):
                self.root.update_idletasks()
        except Exception:
            pass

    def clear_canvas_frame(self, frame):
        for w in frame.winfo_children():
            w.destroy()
        for k, fig in list(self._figs.items()):
            if fig is not None:
                plt.close(fig)
        self._figs.clear()

    def embed_figure(self, frame, fig, key='main'):
        self.clear_canvas_frame(frame)
        canvas = FigureCanvasTkAgg(fig, master=frame)
        canvas.draw()
        canvas.get_tk_widget().pack(fill='both', expand=True)
        self._figs[key] = fig
        return canvas

    def browse_data_folder(self):
        folder = _export_capture_folder(filedialog.askdirectory, parent=self.root, title='Select HDF5 Data Folder')
        if not folder:
            return
        self.data_dir = Path(folder)
        self.data_dir_var.set(str(self.data_dir))
        self.hdf5_files = sorted(list(self.data_dir.rglob('*.h5')) + list(self.data_dir.rglob('*.hdf5')), key=self._natural_path_key)
        self.reconstruction_files = []
        self.reconstruction_paths = []
        self.reconstruction_raw_fields = np.asarray([], dtype=float)
        self._discover_reconstruction_files()
        self._update_ramp_direction_status(select_default=True)
        self._last_ramp_direction = self.ramp_direction_var.get()
        self.file_list.delete(0, 'end')
        recon_set = {str(Path(fp).resolve()) for fp in self.reconstruction_paths}
        for i, f in enumerate(self.hdf5_files):
            tag = ' [RECON]' if str(Path(f).resolve()) in recon_set else ' [RAW/OTHER]'
            self.file_list.insert('end', f'{i}: {f.name}{tag}')
        self.file_count_var.set(f'{len(self.hdf5_files)} HDF5 files | {len(self.reconstruction_paths)} reconstruction files')
        self.log(f'Found {len(self.hdf5_files)} HDF5 files; identified {len(self.reconstruction_paths)} CDI reconstruction files.')
        if self.reconstruction_paths:
            self.roi_index_var.set(0)
            self.proc_slider.configure(to=max(0, len(self.reconstruction_paths) - 1))
            self.field_slider_var.set(0)
            self.info_var.set(f'{len(self.reconstruction_paths)} reconstruction files found. Click LOAD ALL RECONSTRUCTIONS.')
        else:
            self.info_var.set('No CDI reconstruction files found. Expected NEW_V2 focused_differences/poisson or legacy p_pc/n_pc.')

    @staticmethod
    def _find_hdf5_dataset(h5, name):
        """Return a dataset named *name* whether it is top-level or nested."""
        if name in h5:
            return h5[name]
        found = []

        def visitor(path, obj):
            if isinstance(obj, h5py.Dataset) and path.split('/')[-1] == name:
                found.append(path)
        h5.visititems(visitor)
        if not found:
            return None
        return h5[found[0]]

    @staticmethod
    def _normalize_reconstruction_array(array, dataset_name='reconstruction'):
        arr = np.asarray(array)
        arr = np.real(arr).astype(np.float64, copy=False)
        arr = np.squeeze(arr)
        if arr.ndim != 2:
            raise ValueError(f'{dataset_name} must resolve to a 2-D image after squeezing singleton axes; got {arr.shape}')
        return arr

    @staticmethod
    def _normalize_complex_reconstruction_array(array, dataset_name='complex reconstruction'):
        arr = np.asarray(array, dtype=np.complex128)
        arr = np.squeeze(arr)
        if arr.ndim != 2:
            raise ValueError(f'{dataset_name} must resolve to a 2-D complex image after squeezing singleton axes; got {arr.shape}')
        return arr



    @staticmethod
    def _decode_h5_value(value):
        """Decode HDF5 attrs into Python scalars/containers for diagnostics."""
        if isinstance(value, bytes):
            return value.decode('utf-8', errors='replace')
        if isinstance(value, np.generic):
            return value.item()
        if isinstance(value, np.ndarray):
            if value.shape == ():
                return CDIWorkflowApp._decode_h5_value(value.item())
            return [CDIWorkflowApp._decode_h5_value(v) for v in value.tolist()]
        return value

    @staticmethod
    def _read_h5_metadata(h5):
        metadata = {}
        for key in h5.attrs.keys():
            try:
                metadata[key] = CDIWorkflowApp._decode_h5_value(h5.attrs[key])
            except Exception:
                metadata[key] = '<unreadable>'
        # Scalar datasets are common in older Recon_*.hdf5 exports.
        for key in ('magnet_A','current_A','current_a','applied_current_A','I_A',
                    'field_mT','field_mt','magnetic_field_mT','B_mT'):
            dataset = h5.get(key)
            if isinstance(dataset,h5py.Dataset) and dataset.size == 1:
                existing = CDIWorkflowApp._metadata_number(metadata,[key])
                if existing is None:
                    metadata[key] = CDIWorkflowApp._decode_h5_value(np.asarray(dataset[()]).reshape(-1)[0])
                    if key in ('magnet_A','current_A','current_a','applied_current_A','I_A'):
                        metadata.setdefault('current_source','HDF5 dataset '+dataset.name)
        return metadata

    @staticmethod
    def _metadata_number(metadata, names):
        lowered = {str(key).lower(): value for key, value in (metadata or {}).items()}
        for name in names:
            key = str(name).lower()
            if key not in lowered:
                continue
            try:
                decoded = CDIWorkflowApp._decode_h5_value(lowered[key])
                number = float(decoded)
                if np.isfinite(number):
                    return number
            except Exception:
                continue
        return None

    @staticmethod
    def _parse_h5_slice_value(value):
        if isinstance(value, slice):
            return value
        if isinstance(value, (list, tuple)):
            if len(value) == 2:
                return slice(int(value[0]), int(value[1]))
            if len(value) == 3:
                step = None if value[2] is None else int(value[2])
                return slice(int(value[0]), int(value[1]), step)
        if isinstance(value, str):
            text = value.strip()
            match = re.search(
                r"slice\s*\(\s*(-?\d+)\s*,\s*(-?\d+)(?:\s*,\s*(-?\d+|None))?\s*\)",
                text,
                flags=re.IGNORECASE,
            )
            if match:
                step_text = match.group(3)
                step = None if step_text in (None, 'None') else int(step_text)
                return slice(int(match.group(1)), int(match.group(2)), step)
            match = re.match(r"\s*(-?\d+)\s*:\s*(-?\d+)(?:\s*:\s*(-?\d+))?\s*$", text)
            if match:
                step = None if match.group(3) is None else int(match.group(3))
                return slice(int(match.group(1)), int(match.group(2)), step)
        return None

    @staticmethod
    def _read_newv2_display_roi(metadata):
        settings = (metadata or {}).get('settings_json')
        settings = CDIWorkflowApp._decode_h5_value(settings)
        if isinstance(settings, str):
            try:
                settings = json.loads(settings)
            except Exception:
                return None
        if not isinstance(settings, dict):
            return None
        roi = settings.get('DISPLAY_ROI', settings.get('display_roi'))
        if isinstance(roi, dict):
            y_value = roi.get('y', roi.get('Y'))
            x_value = roi.get('x', roi.get('X'))
            if y_value is not None and x_value is not None:
                y_slice = CDIWorkflowApp._parse_h5_slice_value(y_value)
                x_slice = CDIWorkflowApp._parse_h5_slice_value(x_value)
                if y_slice is not None and x_slice is not None:
                    return y_slice, x_slice
        if isinstance(roi, (list, tuple)) and len(roi) == 2:
            y_slice = CDIWorkflowApp._parse_h5_slice_value(roi[0])
            x_slice = CDIWorkflowApp._parse_h5_slice_value(roi[1])
            if y_slice is not None and x_slice is not None:
                return y_slice, x_slice
        return None

    @staticmethod
    def _newv2_primary_mode(metadata):
        settings = (metadata or {}).get('settings_json')
        settings = CDIWorkflowApp._decode_h5_value(settings)
        if isinstance(settings, str):
            try:
                settings = json.loads(settings)
            except Exception:
                settings = {}
        if not isinstance(settings, dict):
            settings = {}
        try:
            return int(settings.get('primary_mode', 0))
        except Exception:
            return 0

    @staticmethod
    def _h5_structure_summary(h5):
        lines = []

        def visitor(path, obj):
            if isinstance(obj, h5py.Dataset):
                lines.append(f'/{path} shape={obj.shape} dtype={obj.dtype}')
            else:
                lines.append(f'/{path}/')

        h5.visititems(visitor)
        return '; '.join(lines[:30]) + ('; ...' if len(lines) > 30 else '')

    def _inspect_reconstruction_h5(self, fp):
        """Return a metadata dict for supported legacy or NEW_V2 reconstruction files."""
        fp = Path(fp)
        with h5py.File(fp, 'r') as f:
            metadata = self._read_h5_metadata(f)
            dataset_path = next((k for k in ('focused_differences/poisson','focused_differences/warmup') if isinstance(f.get(k),h5py.Dataset)), 'focused_differences/poisson')
            focused = f.get(dataset_path)
            if isinstance(focused, h5py.Dataset):
                if focused.ndim != 2:
                    raise ValueError(
                        f"NEW_V2 dataset focused_differences/poisson has shape {focused.shape}; expected 2-D."
                    )
                if 'modal_supports' not in f:
                    raise KeyError("NEW_V2 file is missing modal_supports.")
                support_ds = f['modal_supports']
                if support_ds.ndim not in (2, 3):
                    raise ValueError(f"modal_supports has unsupported shape {support_ds.shape}.")
                current_A = self._metadata_number(
                    metadata,
                    ['current_A', 'magnet_A', 'current', 'current_a', 'applied_current_A', 'applied_current', 'I_A', 'I'],
                )
                field_mT = self._metadata_number(
                    metadata,
                    ['field_mT', 'field_mt', 'magnetic_field_mT', 'magnetic_field', 'B_mT', 'B'],
                )
                point_number = self._metadata_number(metadata, ['point_number', 'point', 'loop_point'])
                observation_order = self._metadata_number(metadata, ['observation_order', 'cache_index'])
                if current_A is not None and np.isfinite(current_A):
                    raw_value = float(current_A)
                    raw_kind = 'current_A'
                elif field_mT is not None and np.isfinite(field_mT):
                    raw_value = float(field_mT)
                    raw_kind = 'field_mT'
                else:
                    raw_value = float(observation_order if observation_order is not None else len(getattr(self, 'reconstruction_files', []) or []))
                    raw_kind = 'metadata_order'
                order_value = observation_order if observation_order is not None else point_number
                if order_value is None:
                    order_value = raw_value
                focused_display, crop_info = _resolve_focused_metadata(self,f,metadata,dataset_path)
                return {
                    'dataset_path': dataset_path,
                    'focused_display': focused_display,
                    'focused_crop': crop_info,
                    'format': 'new_v2',
                    'path': fp,
                    'shape': tuple(focused.shape),
                    'metadata': metadata,
                    'current_A': np.nan if current_A is None else float(current_A),
                    'field_mT': np.nan if field_mT is None else float(field_mT),
                    'raw_value': float(raw_value),
                    'raw_kind': raw_kind,
                    'point_number': np.nan if point_number is None else float(point_number),
                    'observation_order': float(order_value),
                    'sort_key': (0, float(order_value), str(fp).lower()),
                }

            p_ds = self._find_hdf5_dataset(f, 'p_pc')
            n_ds = self._find_hdf5_dataset(f, 'n_pc')
            if p_ds is not None or n_ds is not None:
                if p_ds is None or n_ds is None:
                    raise KeyError('Legacy reconstruction is incomplete: p_pc and n_pc are both required.')
                if p_ds.shape != n_ds.shape:
                    raise ValueError(f'p_pc shape {p_ds.shape} != n_pc shape {n_ds.shape}')
                squeezed_shape = tuple(dim for dim in p_ds.shape if int(dim) != 1)
                if len(squeezed_shape) != 2:
                    raise ValueError(
                        f'p_pc/n_pc resolve to shape {p_ds.shape}; expected one 2-D image (singleton axes are allowed).'
                    )
                current_A = self._metadata_number(metadata,
                    ['current_A','magnet_A','current_a','applied_current_A','I_A'])
                field_mT = self._metadata_number(metadata,
                    ['field_mT','field_mt','magnetic_field_mT','B_mT'])
                if current_A is not None:
                    raw_value, raw_kind = current_A, 'current_A'
                elif field_mT is not None:
                    raw_value, raw_kind = field_mT, 'field_mT'
                else:
                    # A token named field= does not establish physical units.
                    match = re.search(r'(?:cdi_)?field[=:_]([-+]?\d*\.?\d+(?:[eE][-+]?\d+)?)', fp.name, re.I)
                    raw_value = float(match.group(1)) if match else float(len(getattr(self,'reconstruction_files',[]) or []))
                    raw_kind = 'legacy_filename_untyped' if match else 'metadata_order'
                    self.log(f'{fp.name}: no stored current or explicit field_mT; field remains unavailable.')
                return {
                    'format':'legacy_p_pc_n_pc','path':fp,'shape':tuple(squeezed_shape),
                    'metadata':metadata,
                    'current_A':np.nan if current_A is None else float(current_A),
                    'field_mT':np.nan if field_mT is None else float(field_mT),
                    'raw_value':float(raw_value),'raw_kind':raw_kind,
                    'current_source':metadata.get('current_source','HDF5 current attribute'),
                    'point_number':np.nan,'observation_order':float(raw_value),
                    'sort_key':(1,float(raw_value),str(fp).lower()),
                }

            state_path=next((p for p in ('reconstructions/poisson','reconstructions/warmup')
                if isinstance(f.get(p),h5py.Dataset)),None)
            if state_path is not None:
                return _inspect_full_retrieval_state(self,f,metadata,fp,state_path)
            raise KeyError(
                'Unsupported HDF5 reconstruction format. Expected NEW_V2 focused_differences/poisson '
                'with modal_supports, or legacy p_pc and n_pc. Structure: ' + self._h5_structure_summary(f)
            )

    def _load_reconstruction_h5(self, fp):
        """Load one supported HDF5 reconstruction as a 2-D complex image plus support."""
        fp = Path(fp)
        info = getattr(self, 'reconstruction_metadata_by_path', {}).get(str(fp.resolve()))
        if info is None:
            info = self._inspect_reconstruction_h5(fp)
            self.__dict__.setdefault('reconstruction_metadata_by_path', {})[str(fp.resolve())] = info
        with h5py.File(fp, 'r') as f:
            if info['format'] == 'new_v2_full_state':
                return _load_full_retrieval_state(self,f,info)
            if info['format'] == 'new_v2':
                image = np.asarray(f[info.get('dataset_path','focused_differences/poisson')][()], dtype=np.complex128)
                if image.ndim != 2:
                    raise ValueError(f"focused_differences/poisson must be 2-D; got {image.shape}")
                if not image.size or not np.isfinite(image).all():
                    raise ValueError(f'Focused reconstruction is empty or contains nonfinite values: {fp}')
                support_full = np.asarray(f['modal_supports'][()], dtype=bool)
                primary_mode = self._newv2_primary_mode(info.get('metadata', {}))
                if support_full.ndim == 3:
                    if primary_mode < 0 or primary_mode >= support_full.shape[0]:
                        raise IndexError(f'primary_mode={primary_mode} outside modal_supports modes={support_full.shape[0]}')
                    support_full = support_full[primary_mode]
                elif support_full.ndim != 2:
                    raise ValueError(f'Unsupported modal_supports shape {support_full.shape}')
                support = support_full
                if support.shape != image.shape:
                    display_roi = self._read_newv2_display_roi(info.get('metadata', {}))
                    if display_roi is None:
                        raise ValueError(
                            f'NEW_V2 support shape {support.shape} does not match focused image {image.shape}; '
                            'settings_json DISPLAY_ROI is missing, so the crop cannot be verified.'
                        )
                    y_slice, x_slice = display_roi
                    support = support_full[y_slice, x_slice]
                support = np.array(support, dtype=bool, copy=True)
                if support.shape != image.shape:
                    raise ValueError(f'NEW_V2 support crop shape {support.shape} does not match image {image.shape}')
                if not np.any(support):
                    raise ValueError('NEW_V2 support mask has no True pixels after mode/ROI selection.')
                info['support_native_to_image'] = True
                return image, support, info

            p_ds = self._find_hdf5_dataset(f, 'p_pc')
            n_ds = self._find_hdf5_dataset(f, 'n_pc')
            if p_ds is None or n_ds is None:
                raise KeyError('p_pc and/or n_pc dataset not found')
            if p_ds.shape != n_ds.shape:
                raise ValueError(f'p_pc shape {p_ds.shape} != n_pc shape {n_ds.shape}')
            image = self._normalize_complex_reconstruction_array(p_ds[()] - n_ds[()], 'p_pc - n_pc')
            support_ds = self._find_hdf5_dataset(f, 'supportmask')
            support = None if support_ds is None else np.asarray(support_ds[...], dtype=bool)
            info['support_native_to_image'] = bool(support is not None and support.shape == image.shape)
            return image, support, info

    def _field_label_for_frame(self, idx, include_frame=False):
        parts = []
        n_frames = len(self.recons) if getattr(self, 'recons', None) is not None else 0
        if include_frame:
            parts.append(f'Frame {idx + 1}/{n_frames}')
        current = np.nan
        if getattr(self, 'current_values_A', None) is not None and idx < len(self.current_values_A):
            current = float(self.current_values_A[idx])
        field = np.nan
        if getattr(self, 'real_fields_mT', None) is not None and idx < len(self.real_fields_mT):
            field = float(self.real_fields_mT[idx])
        if np.isfinite(current):
            parts.append(f'I = {current:+.6g} A')
        if np.isfinite(field):
            parts.append(f'B = {field:+.2f} mT')
        elif np.isfinite(current):
            parts.append('B = -- mT (load calibration or H5 field_mT)')
        elif getattr(self, 'raw_fields', None) is not None and idx < len(self.raw_fields):
            raw = float(self.raw_fields[idx])
            if np.isfinite(raw):
                parts.append(f'Raw = {raw:+.6g}')
        return ' | '.join(parts) if parts else 'Field: --'

    def _field_value_for_frame(self, idx):
        if getattr(self, 'real_fields_mT', None) is not None and idx < len(self.real_fields_mT):
            return float(self.real_fields_mT[idx])
        return np.nan

    def _reconstruction_acquisition_key(self, fp):
        info = getattr(self, 'reconstruction_metadata_by_path', {}).get(str(Path(fp).resolve()), {})
        order = info.get('observation_order', np.nan)
        if order is None or not np.isfinite(float(order)):
            order = info.get('point_number', np.nan)
        if order is not None and np.isfinite(float(order)):
            return (0, float(order), str(Path(fp)).lower())
        return (1, *self._natural_path_key(fp))


    def _discover_reconstruction_files(self):
        """Find CDI reconstruction HDF5 files by content, supporting legacy and NEW_V2."""
        if self.data_dir is None:
            return []
        items = []
        metadata_by_path = {}
        skipped = []
        for fp in self.hdf5_files:
            fp = Path(fp)
            if fp.name.startswith('Data_ImId_'):
                continue
            try:
                info = self._inspect_reconstruction_h5(fp)
            except Exception as exc:
                skipped.append((fp, f'{type(exc).__name__}: {exc}'))
                self.log(f'Skipping HDF5 {fp}: {type(exc).__name__}: {exc}')
                continue
            metadata_by_path[str(fp.resolve())] = info
            items.append((float(info['raw_value']), fp))
            if info['format'] == 'new_v2':
                field_text = f"{info['field_mT']:+.3f} mT" if np.isfinite(info['field_mT']) else 'no H5 field_mT'
                current_text = f"{info['current_A']:+.6g} A" if np.isfinite(info['current_A']) else 'no current_A'
                self.log(
                    f"Detected NEW_V2 reconstruction: {fp} | shape={info['shape']} | "
                    f"{current_text} | {field_text} | order={info['observation_order']:+.0f}"
                )
        # Preserve V50's physical ramp controls: sort the source value here,
        # then _apply_ramp_direction_order may reverse or cycle it.
        items.sort(
            key=lambda item: (
                float(item[0]),
                self._reconstruction_acquisition_key(item[1]),
            )
        )
        self.reconstruction_files = items
        self.reconstruction_paths = [fp for _, fp in items]
        self.reconstruction_raw_fields = np.asarray([field for field, _ in items], dtype=float)
        self.reconstruction_metadata_by_path = metadata_by_path
        if skipped:
            self.log(f'Discovery skipped {len(skipped)} unsupported/incomplete HDF5 file(s). See log lines above for diagnostics.')
        return items
    def browse_calibration(self):
        f = filedialog.askopenfilename(parent=self.root, title='Select Field Calibration JSON', filetypes=[('JSON', '*.json'), ('All files', '*.*')])
        if f:
            self.field_calib_file = Path(f)
            self.calib_var.set(str(f))

    def _select_single_calibration_path(self, current, field):
        """Select the widest contiguous measured sweep, without mixing branches."""
        branch = _magnet_default_branch(_magnet_split_branches(current,field))
        return branch['current'].copy(),branch['field'].copy()

    def load_calibration(self):
        return _magnet_load_calibration(self)

    def _ordered_frame_field_axes(self):
        """Return reconstruction frame numbers and fields in the active ramp order.

        X1 = frame number in acquisition/reconstruction order.
        X2 = calibrated field mapped onto the same X1 coordinate.
        This is intentionally derived from the already ordered reconstruction
        stack so Tabs 2 onward inherit the selected ramp without re-sorting their
        analysis data independently.
        """
        if self.real_fields_mT is None:
            return (np.array([], dtype=float), np.array([], dtype=float))
        x1 = np.arange(1, len(self.real_fields_mT) + 1, dtype=float)
        x2 = np.asarray(self.real_fields_mT, dtype=float)
        return (x1, x2)

    def _plot_field_calibration(self):
        if self.field_plot_canvas is not None:
            try:
                self.field_plot_canvas.get_tk_widget().destroy()
            except Exception:
                pass
        if self.field_plot_fig is not None:
            try:
                plt.close(self.field_plot_fig)
            except Exception:
                pass
        fig, axes = plt.subplots(nrows=1, ncols=2, figsize=(11, 4.8), dpi=100)
        self.field_plot_fig = fig
        if self.calib_current is not None and self.calib_field_mT is not None:
            axes[0].plot(self.calib_current, self.calib_field_mT, 'o-', markersize=4, linewidth=1.5, label='Calibration data')
            xx = np.linspace(float(np.min(self.calib_current)), float(np.max(self.calib_current)), 500)
            if self.field_interpolator is not None:
                axes[0].plot(xx, self.field_interpolator(xx), '-', linewidth=2, label='Interpolation')
            axes[0].set_title('Raw magnet calibration (-4 A to +4 A single path)')
            axes[0].set_xlabel('Current (A)')
            axes[0].set_ylabel('Field (mT)')
            axes[0].grid(True, linestyle=':', alpha=0.7)
            axes[0].legend(fontsize=8)
        else:
            axes[0].set_title('Raw magnet calibration')
            axes[0].text(0.5, 0.5, 'Load calibration JSON', ha='center', va='center', transform=axes[0].transAxes)
            axes[0].set_axis_on()
            axes[0].set_xlabel('Current (A)')
            axes[0].set_ylabel('Field (mT)')
            axes[0].grid(True, linestyle=':', alpha=0.35)
        if self.raw_fields is not None and self.real_fields_mT is not None:
            idx, _ = self._ordered_frame_field_axes()
            idx0 = idx - 1.0
            raw_label = 'Current metadata (A)' if getattr(self, 'current_values_A', None) is not None and np.any(np.isfinite(self.current_values_A)) else 'Raw legacy value'
            raw_values = self.current_values_A if raw_label.startswith('Current') else self.raw_fields
            axes[1].plot(idx0, raw_values, 'o-', ms=3, lw=1.0, label=raw_label)
            axes[1].plot(idx0, self.real_fields_mT, 'o-', ms=3, lw=1.0, label='Magnetic field (mT)')
            axes[1].set_title('Reconstruction metadata and calibrated field')
            axes[1].set_xlabel('Reconstruction index')
            axes[1].set_ylabel('Current (A) / Field (mT)')
            axes[1].grid(True, linestyle=':', alpha=0.7)
            axes[1].legend(fontsize=8)
        else:
            axes[1].set_title('Raw vs calibrated reconstruction field')
            axes[1].text(0.5, 0.5, 'Load reconstructions', ha='center', va='center', transform=axes[1].transAxes)
            axes[1].set_axis_on()
            axes[1].set_xlabel('Reconstruction index')
            axes[1].set_ylabel('Field (mT)')
            axes[1].grid(True, linestyle=':', alpha=0.35)
        fig.tight_layout()
        self.field_plot_canvas = FigureCanvasTkAgg(fig, master=self.field_plot_frame)
        self.field_plot_canvas.draw()
        self.field_plot_canvas.get_tk_widget().pack(fill='both', expand=True)

    def browse_mask_library(self):
        filename = filedialog.askopenfilename(parent=self.root, title='Select mask_lib.py', filetypes=[('Python files', '*.py'), ('All files', '*.*')])
        if not filename:
            return
        self.mask_lib_path = Path(filename)
        self.mask_lib_var.set(str(self.mask_lib_path))
        self.mask_status_var.set('Mask library selected — click Load mask_lib')
        self.log(f'Mask library selected: {self.mask_lib_path}')

    def _fallback_scale_mask(self, mask, target_shape):
        """Exact fallback equivalent to the scale_mask() found in the original notebook."""
        mask = np.asarray(mask, dtype=float)
        target_shape = tuple(np.asarray(target_shape, dtype=int))
        scale_factor = np.array(target_shape) / np.array(mask.shape)
        if scale_factor[0] != scale_factor[1]:
            self.log('Warning: mask scaling is different for both axes!')
        mask_rescaled = zoom(mask, scale_factor)
        mask_rescaled[mask_rescaled <= 0.5] = 0
        mask_rescaled[mask_rescaled > 0.5] = 1
        return mask_rescaled.astype(bool)

    def _install_compatible_mask_lib(self, reason=None):
        """Create a local mask_lib-compatible object exposing the required scale_mask()."""
        self.mask_lib = types.SimpleNamespace(scale_mask=self._fallback_scale_mask)
        if reason:
            self.log(f'Using embedded mask_lib.scale_mask() compatibility mode: {reason}')
        else:
            self.log('Using embedded mask_lib.scale_mask() compatibility mode.')
        self.mask_status_var.set('✓ mask_lib compatible scale_mask loaded')
        return True

    def load_mask_library(self):
        if self.mask_lib_path is None:
            messagebox.showwarning('Mask Library', 'Please browse and select mask_lib.py first.')
            return False
        if not self.mask_lib_path.exists():
            messagebox.showerror('Mask Library', f'File does not exist:\n{self.mask_lib_path}')
            return False
        try:
            library_dir = str(self.mask_lib_path.parent)
            if library_dir not in sys.path:
                sys.path.insert(0, library_dir)
            spec = importlib.util.spec_from_file_location('mask_lib', str(self.mask_lib_path))
            if spec is None or spec.loader is None:
                raise ImportError(f'Could not create import specification for {self.mask_lib_path}')
            module = importlib.util.module_from_spec(spec)
            sys.modules['mask_lib'] = module
            spec.loader.exec_module(module)
            if not hasattr(module, 'scale_mask'):
                module.scale_mask = self._fallback_scale_mask
                self.log('mask_lib.py loaded, but scale_mask() was missing; embedded scale_mask() attached.')
            self.mask_lib = module
            self.mask_status_var.set('✓ full mask_lib loaded')
            self.log(f'Loaded mask library: {self.mask_lib_path}')
            self.log(f'scale_mask: {self.mask_lib.scale_mask}')
            return True
        except ModuleNotFoundError as exc:
            missing = getattr(exc, 'name', '') or str(exc)
            if missing == 'CCI_core':
                return self._install_compatible_mask_lib('CCI_core is unavailable')
            return self._install_compatible_mask_lib(f'missing dependency: {missing}')
        except Exception as exc:
            self.log(f'Full mask_lib load failed: {exc}')
            return self._install_compatible_mask_lib(type(exc).__name__)

    def _scale_support_mask(self, mask, target_shape):
        if self.mask_lib is None:
            self.mask_lib = types.SimpleNamespace(scale_mask=self._fallback_scale_mask)
            self.mask_status_var.set('Fallback scale_mask active')
        try:
            scaled = np.asarray(self.mask_lib.scale_mask(mask, target_shape), dtype=bool)
            if scaled.shape != tuple(target_shape):
                raise ValueError(f'scale_mask returned {scaled.shape}, expected {tuple(target_shape)}')
            return scaled
        except Exception as exc:
            self.log(f'mask_lib.scale_mask failed: {exc}; using fallback.')
            return self._fallback_scale_mask(mask, target_shape)

    def test_single_hdf5(self):
        """Diagnostic reconstruction from one HDF5 using only p_pc and n_pc.
        mask_lib/supportmask are optional for this test.
        """
        fp = filedialog.askopenfilename(parent=self.root, title='Select ONE CDI reconstruction HDF5', filetypes=[('HDF5 files', '*.h5 *.hdf5'), ('All files', '*.*')])
        if not fp:
            return
        fp = Path(fp)
        try:
            with h5py.File(fp, 'r') as f:
                if 'p_pc' not in f or 'n_pc' not in f:
                    raise KeyError('The selected file must contain p_pc and n_pc.')
                p_pc = np.asarray(f['p_pc'][:], dtype=np.complex128)
                n_pc = np.asarray(f['n_pc'][:], dtype=np.complex128)
            if p_pc.shape != n_pc.shape:
                raise ValueError(f'p_pc shape {p_pc.shape} != n_pc shape {n_pc.shape}')
            complex_reconstruction = p_pc - n_pc
            reconstruction = np.real(complex_reconstruction)
            imaginary = np.imag(complex_reconstruction)
            image = reconstruction[0] if reconstruction.ndim == 3 else reconstruction
            imag_image = imaginary[0] if imaginary.ndim == 3 else imaginary
            amplitude = np.abs(image)
            phase = np.angle(complex_reconstruction[0] if complex_reconstruction.ndim == 3 else complex_reconstruction)
            finite = np.isfinite(image)
            if np.any(finite):
                lo, hi = np.percentile(image[finite], (1, 99))
                if hi <= lo:
                    hi = lo + 1e-12
            else:
                lo, hi = (0, 1)
            fig, axes = plt.subplots(2, 3, figsize=(14, 8), dpi=100)
            axes[0, 0].imshow(np.real(p_pc[0] if p_pc.ndim == 3 else p_pc), cmap='gray', origin='lower')
            axes[0, 0].set_title('p_pc (Real)')
            axes[0, 1].imshow(np.real(n_pc[0] if n_pc.ndim == 3 else n_pc), cmap='gray', origin='lower')
            axes[0, 1].set_title('n_pc (Real)')
            axes[0, 2].imshow(image, cmap='gray', origin='lower', vmin=lo, vmax=hi)
            axes[0, 2].set_title('Real Reconstruction')
            axes[1, 0].imshow(imag_image, cmap='gray', origin='lower')
            axes[1, 0].set_title('Imaginary Reconstruction')
            axes[1, 1].imshow(amplitude, cmap='gray', origin='lower')
            axes[1, 1].set_title('Amplitude')
            vals = image[finite]
            axes[1, 2].hist(vals.ravel(), bins=100)
            axes[1, 2].set_title('Real reconstruction histogram')
            axes[1, 2].set_xlabel('Intensity')
            for ax in axes.flat:
                ax.axis('image' if ax is not axes[1, 2] else 'auto')
            fig.suptitle(f'Single HDF5 reconstruction test — {fp.name}', fontsize=13)
            fig.tight_layout()
            self.embed_figure(self.recon_canvas_frame, fig, key='single_test')
            self.nb.select(self.tab_recon)
            self.log(f'Single HDF5 test: {fp.name} | p_pc={p_pc.shape}, n_pc={n_pc.shape}, reconstruction={reconstruction.shape}')
        except Exception as exc:
            messagebox.showerror('Single HDF5 reconstruction test', str(exc), parent=self.root)
            self.log(f'Single HDF5 test failed: {exc}')

    def full_load(self):
        if self.field_calib_file:
            try:
                if not _magnet_prepare_dataset_calibration(self):
                    self.log('Calibration unavailable; loading images with unavailable field values where current requires calibration.')
            except Exception as exc:
                self.log(f'Calibration load failed: {type(exc).__name__}: {exc}; continuing without calibrated field values.')
        return self.load_all_reconstructions()

    def _parse_field(self, filename):
        m = re.search('cdi_field=([-+]?\\d*\\.?\\d+)', Path(filename).name)
        if m is None:
            raise ValueError(f"Could not find 'cdi_field=' in {filename}")
        return float(m.group(1))

    def _select_two_cycle_folders(self, force=False):
        """Open one popup to select the two folders in the CURRENT cycle order.

        The popup always defines Folder 1 and Folder 2 according to the selected
        cycle direction:

          + to - to + : Folder 1 = +1 A -> -1 A (global 0..N),
                        Folder 2 = -1 A -> +1 A (global N+1..M)

          - to + to - : Folder 1 = -1 A -> +1 A (global 0..N),
                        Folder 2 = +1 A -> -1 A (global N+1..M)

        The two source folders are kept separate; only their playback order is
        changed by the cycle selector.
        """
        direction = self.ramp_direction_var.get().strip()
        if direction not in ('+ to - to +', '- to + to -'):
            return False

        # Reuse an already-selected pair only when it was selected for the
        # same cycle direction. Switching between the two cycle modes prompts
        # again so Folder 1 always has the meaning requested by the user.
        if (not force and self._cycle_folders_active and
                getattr(self, '_cycle_folder_prompt_direction', None) == direction and
                self._cycle_neg_to_pos_dir and self._cycle_pos_to_neg_dir and
                Path(self._cycle_neg_to_pos_dir).is_dir() and
                Path(self._cycle_pos_to_neg_dir).is_dir()):
            return True

        if direction == '+ to - to +':
            first_label = 'FIRST folder: +1 A  to  -1 A'
            second_label = 'SECOND folder: -1 A  to  +1 A'
            title = '+ to - to +  |  Select two reconstruction folders'
        else:
            first_label = 'FIRST folder: -1 A  to  +1 A'
            second_label = 'SECOND folder: +1 A  to  -1 A'
            title = '- to + to -  |  Select two reconstruction folders'

        result = {'first': '', 'second': '', 'ok': False}
        # Create a real independent Tk popup.  Do not use grab_set here: on
        # some Windows/Tk builds the grab can leave a Toplevel invisible or
        # behind the main window when this callback is fired from a Combobox.
        popup = tk.Toplevel(self.root)
        popup.title(title)
        popup.transient(self.root)
        popup.resizable(False, False)
        popup.protocol('WM_DELETE_WINDOW', lambda: cancel())
        popup.withdraw()

        frm = ttk.Frame(popup, padding=14)
        frm.grid(row=0, column=0, sticky='nsew')

        ttk.Label(frm, text=title, font=('Arial', 11, 'bold')).grid(
            row=0, column=0, columnspan=3, sticky='w', pady=(0, 10))
       # ttk.Label(frm, text='Folder 1 will receive global file indices 0 → N.').grid(
       #     row=1, column=0, columnspan=3, sticky='w', pady=(0, 8))
       # ttk.Label(frm, text='Folder 2 will receive global file indices N+1 → M.').grid(
        #    row=2, column=0, columnspan=3, sticky='w', pady=(0, 12))

        first_var = tk.StringVar()
        second_var = tk.StringVar()
        ttk.Label(frm, text=first_label, font=('Arial', 10, 'bold')).grid(
            row=3, column=0, columnspan=3, sticky='w', pady=(0, 3))
        ttk.Entry(frm, textvariable=first_var, width=72).grid(row=4, column=0, sticky='ew', padx=(0, 6))
        ttk.Button(frm, text='Browse…', command=lambda: first_var.set(
            _export_capture_folder(filedialog.askdirectory, parent=popup, title=first_label) or first_var.get()
        )).grid(row=4, column=2, sticky='e')

        ttk.Label(frm, text=second_label, font=('Arial', 10, 'bold')).grid(
            row=5, column=0, columnspan=3, sticky='w', pady=(12, 3))
        ttk.Entry(frm, textvariable=second_var, width=72).grid(row=6, column=0, sticky='ew', padx=(0, 6))
        ttk.Button(frm, text='Browse…', command=lambda: second_var.set(
            _export_capture_folder(filedialog.askdirectory, parent=popup, title=second_label) or second_var.get()
        )).grid(row=6, column=2, sticky='e')

        status = tk.StringVar(value='Select both folders, then click LOAD TWO FOLDERS.')
        ttk.Label(frm, textvariable=status, foreground='darkgreen', wraplength=760).grid(
            row=7, column=0, columnspan=3, sticky='w', pady=(12, 8))

        def cancel():
            result['ok'] = False
            try:
                popup.grab_release()
            except Exception:
                pass
            popup.destroy()

        def accept():
            first = first_var.get().strip()
            second = second_var.get().strip()
            if not first or not second:
                status.set('Please select both folders.')
                return
            p1 = Path(first).expanduser().resolve()
            p2 = Path(second).expanduser().resolve()
            if not p1.is_dir() or not p2.is_dir():
                status.set('Both selections must be existing folders.')
                return
            if p1 == p2:
                status.set('Folder 1 and Folder 2 must be different folders.')
                return
            result['first'] = str(p1)
            result['second'] = str(p2)
            result['ok'] = True
            try:
                popup.grab_release()
            except Exception:
                pass
            popup.destroy()

        btns = ttk.Frame(frm)
        btns.grid(row=8, column=0, columnspan=3, sticky='e', pady=(6, 0))
        ttk.Button(btns, text='CANCEL', command=cancel).pack(side='right', padx=(6, 0))
        ttk.Button(btns, text='LOAD TWO FOLDERS', command=accept).pack(side='right')
        popup.bind('<Return>', lambda e: accept())
        popup.bind('<Escape>', lambda e: cancel())
        popup.update_idletasks()
        try:
            rw = max(1, self.root.winfo_width())
            rh = max(1, self.root.winfo_height())
            pw = max(420, popup.winfo_reqwidth())
            ph = max(260, popup.winfo_reqheight())
            x = self.root.winfo_rootx() + max(0, (rw - pw) // 2)
            y = self.root.winfo_rooty() + max(0, (rh - ph) // 2)
            popup.geometry(f'{pw}x{ph}+{x}+{y}')
        except Exception:
            pass
        # Explicitly map, raise and focus the window.  The short topmost pulse
        # prevents the popup from opening behind the main Tk window on Windows.
        try:
            popup.deiconify()
            popup.lift()
            popup.attributes('-topmost', True)
            popup.after(250, lambda: popup.attributes('-topmost', False) if popup.winfo_exists() else None)
            popup.focus_force()
        except Exception:
            pass
        try:
            first_entry = popup.nametowidget(str(frm.winfo_children()[4])) if len(frm.winfo_children()) > 4 else None
            if first_entry is not None:
                first_entry.focus_set()
        except Exception:
            pass
        self.root.update_idletasks()
        self.root.wait_window(popup)

        if not result['ok']:
            return False

        # Assign the selected folders to their physical acquisition directions.
        if direction == '+ to - to +':
            self._cycle_pos_to_neg_dir = Path(result['first'])
            self._cycle_neg_to_pos_dir = Path(result['second'])
        else:
            self._cycle_neg_to_pos_dir = Path(result['first'])
            self._cycle_pos_to_neg_dir = Path(result['second'])

        self._cycle_folders_active = True
        self._cycle_folder_prompt_direction = direction
        self.log(f'{direction}: Folder 1 (global 0..N): {result["first"]}')
        self.log(f'{direction}: Folder 2 (global N+1..M): {result["second"]}')
        return True

    def _discover_reconstruction_items_in_folder(self, folder):
        """Use the existing robust HDF5 discovery routine on one cycle folder."""
        folder = Path(folder)
        h5_files = sorted(list(folder.rglob('*.h5')) + list(folder.rglob('*.hdf5')),
                          key=self._natural_path_key)
        if not h5_files:
            return []

        # Reuse the application's existing dataset validation/discovery logic
        # without permanently replacing the main data-folder state.
        old_dir = self.data_dir
        old_files = self.hdf5_files
        old_reconstruction_files = getattr(self, 'reconstruction_files', [])
        old_reconstruction_paths = getattr(self, 'reconstruction_paths', [])
        old_reconstruction_raw_fields = getattr(
            self, 'reconstruction_raw_fields', np.asarray([], dtype=float)
        )
        try:
            self.data_dir = folder
            self.hdf5_files = h5_files
            self.reconstruction_files = []
            self.reconstruction_paths = []
            self.reconstruction_raw_fields = np.asarray([], dtype=float)
            items = list(self._discover_reconstruction_files() or [])
            return items
        finally:
            self.data_dir = old_dir
            self.hdf5_files = old_files
            self.reconstruction_files = old_reconstruction_files
            self.reconstruction_paths = old_reconstruction_paths
            self.reconstruction_raw_fields = old_reconstruction_raw_fields

    def _build_two_folder_cycle_items(self, direction):
        """Load the two folders in the exact Folder-1/Folder-2 order shown in the popup.

        Folder 1 is always indexed 0..N and Folder 2 is always N+1..M.
        Their physical ramp directions depend on the selected cycle option.
        """
        if not self._select_two_cycle_folders(force=False):
            return []

        neg_to_pos = self._discover_reconstruction_items_in_folder(self._cycle_neg_to_pos_dir)
        pos_to_neg = self._discover_reconstruction_items_in_folder(self._cycle_pos_to_neg_dir)
        if not neg_to_pos or not pos_to_neg:
            messagebox.showerror(
                'Cycle reconstruction folders',
                'Both selected folders must contain readable CDI reconstruction HDF5 files\n'
                'in NEW_V2 focused_differences/poisson or legacy p_pc/n_pc format.\n\n'
                f'-1 A -> +1 A folder: {len(neg_to_pos)} reconstruction files\n'
                f'+1 A -> -1 A folder: {len(pos_to_neg)} reconstruction files',
                parent=self.root)
            self._cycle_neg_to_pos_items = []
            self._cycle_pos_to_neg_items = []
            return []

        neg_to_pos = sorted(neg_to_pos, key=lambda item: float(item[0]))
        pos_to_neg = sorted(pos_to_neg, key=lambda item: float(item[0]), reverse=True)
        self._cycle_neg_to_pos_items = neg_to_pos
        self._cycle_pos_to_neg_items = pos_to_neg

        # The popup defines the source-file index space. Folder 1 is 0..N,
        # Folder 2 is N+1..M, irrespective of playback direction.
        if direction == '+ to - to +':
            folder1 = pos_to_neg
            folder2 = neg_to_pos
        else:
            folder1 = neg_to_pos
            folder2 = pos_to_neg

        self._cycle_global_index_by_path = {}
        for idx, (_, fp) in enumerate(folder1):
            self._cycle_global_index_by_path[str(Path(fp).resolve())] = int(idx)
        offset = len(folder1)
        for j, (_, fp) in enumerate(folder2):
            self._cycle_global_index_by_path[str(Path(fp).resolve())] = int(offset + j)

        # Playback is exactly Folder 1 followed by Folder 2.
        items = list(folder1) + list(folder2)
        self.reconstruction_global_indices = np.asarray(
            [self._cycle_global_index_by_path[str(Path(fp).resolve())] for _, fp in items],
            dtype=int)

        fmin = min(float(x[0]) for x in items)
        fmax = max(float(x[0]) for x in items)
        self.log(
            f'Built {direction}: Folder 1={len(folder1)} frames (global 0..{len(folder1)-1}), '
            f'Folder 2={len(folder2)} frames (global {len(folder1)}..{len(items)-1}), '
            f'total={len(items)}, raw range={fmin:+.6f} to {fmax:+.6f}')
        return items

    def _ramp_direction_changed(self, event=None):
        """Apply the selected ramp order; cycle modes use two separate folders."""
        direction = self.ramp_direction_var.get().strip()
        cycle_mode = direction in ('+ to - to +', '- to + to -')

        if cycle_mode:
            if not self._select_two_cycle_folders(force=False):
                # Do not leave the UI pointing at a cycle mode that has no
                # two-folder dataset attached.
                fallback = self._last_ramp_direction
                if fallback in ('+ to - to +', '- to + to -'):
                    fallback = 'Ramp Up (- to +)'
                self.ramp_direction_var.set(fallback)
                try:
                    self.ramp_direction_combo.set(fallback)
                except Exception:
                    pass
                return

            # A cycle changes the actual source files, so reload the stack from
            # the two folders. This also reapplies the field calibration to the
            # newly ordered raw-current sequence.
            if self.field_calib_file:
                try:
                    _magnet_prepare_dataset_calibration(self)
                except Exception as exc:
                    self.log(f'Calibration reload warning: {type(exc).__name__}: {exc}')
            self._last_ramp_direction = direction
            self.load_all_reconstructions()
            return

        old_paths = [str(Path(p).resolve()) for p in (getattr(self, 'reconstruction_paths', []) or [])]
        had_loaded = getattr(self, 'recons', None) is not None and len(old_paths) == len(self.recons)
        self._apply_ramp_direction_order()
        self._last_ramp_direction = direction
        if had_loaded:
            new_paths = [str(Path(p).resolve()) for p in (getattr(self, 'reconstruction_paths', []) or [])]
            pos = {p: i for i, p in enumerate(old_paths)}
            try:
                order = np.asarray([pos[p] for p in new_paths], dtype=int)
                if order.size == len(self.recons):
                    self.recons = self.recons[order]
                    for name in ('complex_recons', 'real_recons', 'imag_recons', 'amplitude_recons', 'phase_recons'):
                        arr = getattr(self, name, None)
                        if arr is not None and len(arr) == len(order):
                            setattr(self, name, arr[order])
                    if self.raw_fields is not None and len(self.raw_fields) == len(order):
                        self.raw_fields = self.raw_fields[order]
                    if self.real_fields_mT is not None and len(self.real_fields_mT) == len(order):
                        self.real_fields_mT = self.real_fields_mT[order]
                    if hasattr(self, 'current_index'):
                        self.current_index = 0
                    if hasattr(self, 'field_slider'):
                        self.field_slider.configure(to=max(0, len(self.recons)-1))
                        self.field_slider_var.set(0)
                    if hasattr(self, 'field_index_var'):
                        self.field_index_var.set(0)
                    self.field_label_var.set(self._field_label_for_frame(0))
                    self.refresh_roi_image()
                    self.show_current_recon()
            except Exception as exc:
                self.log(f'Ramp reorder warning: {type(exc).__name__}: {exc}')
        else:
            self._update_ramp_direction_status(select_default=False)

    @staticmethod
    def _natural_path_key(path_obj):
        """Natural filename sort so frame/index numbers are ordered numerically."""
        name = Path(path_obj).name.lower()
        return [int(part) if part.isdigit() else part for part in re.split('(\\d+)', name)]

    def _infer_uploaded_dataset_direction(self):
        """Infer acquisition direction from the uploaded data-file sequence.

        This deliberately uses the original uploaded HDF5 file ordering rather
        than the field-sorted reconstruction list, so the inferred direction
        reflects the dataset sequence before this application applies any
        user-selected ramp ordering.
        """
        recon_set = {str(Path(p).resolve()) for p in getattr(self, 'reconstruction_paths', []) or []}
        paths = [Path(p) for p in getattr(self, 'hdf5_files', []) or [] if str(Path(p).resolve()) in recon_set]
        paths = sorted(paths, key=self._reconstruction_acquisition_key)
        pairs = []
        for fp in paths:
            name = fp.name
            field = None
            for pat in ('cdi_field[=:_-]([-+]?\\d*\\.?\\d+(?:[eE][-+]?\\d+)?)', 'field[=:_-]([-+]?\\d*\\.?\\d+(?:[eE][-+]?\\d+)?)'):
                m = re.search(pat, name, flags=re.IGNORECASE)
                if m:
                    try:
                        field = float(m.group(1))
                        break
                    except ValueError:
                        pass
            if field is not None and np.isfinite(field):
                pairs.append(field)
        if len(pairs) < 2:
            return None
        diffs = np.diff(np.asarray(pairs, dtype=float))
        diffs = diffs[np.isfinite(diffs) & (np.abs(diffs) > 1e-12)]
        if diffs.size == 0:
            return None
        pos = int(np.count_nonzero(diffs > 0))
        neg = int(np.count_nonzero(diffs < 0))
        if pos > neg:
            return 'Ramp Up (- to +)'
        if neg > pos:
            return 'Ramp Down (+ to -)'
        return None

    def _update_ramp_direction_status(self, select_default=False):
        """Describe detected field coverage/order and optionally choose a dataset-based default."""
        raw = np.asarray(getattr(self, 'reconstruction_raw_fields', np.asarray([], dtype=float)), dtype=float)
        raw = raw[np.isfinite(raw)]
        if raw.size == 0:
            self.ramp_direction_status_var.set('Dataset direction: no field values detected yet.')
            return
        fmin = float(np.min(raw))
        fmax = float(np.max(raw))
        inferred = self._infer_uploaded_dataset_direction()
        if select_default and inferred is not None:
            self.ramp_direction_var.set(inferred)
        detected_text = inferred if inferred is not None else 'unable to determine'
        direction = self.ramp_direction_var.get()
        if direction in ('+ to - to +', '- to + to -') and self._cycle_folders_active:
            self.ramp_direction_status_var.set(
                f'Two folders: -1 A -> +1 A + +1 A -> -1 A | Order: {direction}'
            )
            return
        if direction == '+ to - to +':
            path_text = f'{fmax:+.3f} -> {fmin:+.3f} -> {fmax:+.3f} mT'
            self.ramp_direction_status_var.set(f'Field path: {path_text} | Order: + to - to +')
        elif direction == '- to + to -':
            path_text = f'{fmin:+.3f} -> {fmax:+.3f} -> {fmin:+.3f} mT'
            self.ramp_direction_status_var.set(f'Field path: {path_text} | Order: - to + to -')
        else:
            self.ramp_direction_status_var.set(f'Field range: {fmin:+.3f} to {fmax:+.3f} mT | Order:{direction}')

    def _ramp_cycle_items(self, items, direction):
        """Build the requested full +/- cycle from the central extremum-to-extremum path.

        The uploaded acquisition may contain partial tails, e.g.
        0 -> +max -> -min -> 0.  Those tails must NOT be included in the
        two-pass cycle.  The physical cycle is the complete excursion between
        the global positive and negative extrema:

            + to - to + : +max -> -min -> +max
            - to + to - : -min -> +max -> -min

        The same extremum-to-extremum frames are used in both passes, with the
        second pass traversed in the opposite direction.  The turning point is
        shared once, so N frames in one pass produce 2*N-1 frames.
        """
        items = list(items)
        if direction not in ('+ to - to +', '- to + to -') or len(items) < 2:
            return items

        # Reconstruct the ORIGINAL acquisition order, not the field-sorted order.
        by_path = {str(Path(fp).resolve()): (float(field), fp) for field, fp in items}
        acq = []
        for fp in sorted((Path(p) for p in (getattr(self, 'hdf5_files', []) or [])), key=self._reconstruction_acquisition_key):
            key = str(fp.resolve())
            if key in by_path:
                field, original_fp = by_path[key]
                if np.isfinite(field):
                    acq.append((field, original_fp))
        if len(acq) < 2:
            acq = [(float(f), fp) for f, fp in items if np.isfinite(float(f))]
        if len(acq) < 2:
            return acq

        fields = np.asarray([float(v[0]) for v in acq], dtype=float)
        i_max = int(np.argmax(fields))
        i_min = int(np.argmin(fields))

        # Find the two extrema in their actual acquisition order and keep ONLY
        # the central full excursion between them.  This deliberately removes
        # partial tails such as 0 -> +max and -min -> 0.
        if i_max < i_min:
            forward_max_to_min = acq[i_max:i_min + 1]
            forward_min_to_max = list(reversed(forward_max_to_min))
            if direction == '+ to - to +':
                return forward_max_to_min + forward_min_to_max[1:]
            return forward_min_to_max + forward_max_to_min[1:]
        elif i_min < i_max:
            forward_min_to_max = acq[i_min:i_max + 1]
            forward_max_to_min = list(reversed(forward_min_to_max))
            if direction == '- to + to -':
                return forward_min_to_max + forward_max_to_min[1:]
            return forward_max_to_min + forward_min_to_max[1:]
        else:
            return acq

    def _apply_ramp_direction_order(self):
        """Sort the active reconstruction source in the selected physical order."""
        direction = self.ramp_direction_var.get().strip()
        valid = ('Ramp Down (+ to -)', 'Ramp Up (- to +)', '+ to - to +', '- to + to -')
        if direction not in valid:
            direction = 'Ramp Up (- to +)'
            self.ramp_direction_var.set(direction)

        if direction in ('+ to - to +', '- to + to -'):
            items = self._build_two_folder_cycle_items(direction)
            if not items:
                self.reconstruction_files = []
                self.reconstruction_paths = []
                self.reconstruction_raw_fields = np.asarray([], dtype=float)
                return
        else:
            items = list(getattr(self, 'reconstruction_files', []) or [])
            if not items:
                return
            descending = direction == 'Ramp Down (+ to -)'
            items.sort(key=lambda item: float(item[0]), reverse=descending)

        self.reconstruction_files = items
        self.reconstruction_paths = [fp for _, fp in items]
        self.reconstruction_raw_fields = np.asarray([float(field) for field, _ in items], dtype=float)
        if direction not in ('+ to - to +', '- to + to -'):
            self.reconstruction_global_indices = np.arange(len(items), dtype=int)
            self._cycle_global_index_by_path = {}
        self._update_ramp_direction_status(select_default=False)


    def load_all_reconstructions(self):
        """Load CDI reconstructions from one folder or from the two cycle folders."""
        source_keys = ('reconstruction_files','reconstruction_paths','reconstruction_raw_fields',
                       'reconstruction_metadata_by_path','reconstruction_global_indices','_cycle_global_index_by_path')
        previous_source = {key:getattr(self,key) for key in source_keys if hasattr(self,key)}
        direction = self.ramp_direction_var.get().strip()
        cycle_mode = direction in ('+ to - to +', '- to + to -')

        if cycle_mode:
            if not self._select_two_cycle_folders(force=False):
                return False
        else:
            if self.data_dir is None:
                messagebox.showwarning('Data', 'Select an HDF5 data folder first.', parent=self.root)
                return False
            self._discover_reconstruction_files()
            if not self.reconstruction_paths:
                messagebox.showerror(
                    'No CDI reconstructions',
                    'No readable CDI reconstruction files were found.\n\n'
                    'Supported formats:\n'
                    '- NEW_V2 focused difference, or full reconstructions/poisson or warmup (confirmation required)\n'
                    '- Legacy: p_pc + n_pc',
                    parent=self.root,
                )
                self.log('ERROR: no readable CDI reconstruction HDF5 files found.')
                return False

        self._apply_ramp_direction_order()
        if not self.reconstruction_paths:
            return False
        self.log(f'Loading {len(self.reconstruction_paths)} CDI reconstructions in {self.ramp_direction_var.get()} order.')
        self.status_var.set('Loading reconstructions...')
        self.root.update_idletasks()

        recons = []
        complex_recons = []
        support = None
        support_native_to_image = False
        raw_fields = []
        current_values = []
        h5_fields = []
        formats = []
        failures = []
        loaded_infos = []
        loaded_masks = []

        for i, fp in enumerate(self.reconstruction_paths):
            try:
                complex_reconstruction, support_candidate, info = self._load_reconstruction_h5(fp)
                reconstruction = np.real(complex_reconstruction).astype(np.float64, copy=False)
                recons.append(reconstruction)
                complex_recons.append(complex_reconstruction)
                formats.append(info.get('format', 'unknown'))
                loaded_infos.append(info)
                loaded_masks.append(support_candidate)
                if support is None and support_candidate is not None:
                    support = np.asarray(support_candidate, dtype=bool)
                    support_native_to_image = bool(info.get('support_native_to_image', False))
                raw_field = float(self.reconstruction_raw_fields[i])
                raw_fields.append(raw_field)
                current_values.append(float(info.get('current_A', np.nan)))
                h5_fields.append(float(info.get('field_mT', np.nan)))
                global_idx = int(self.reconstruction_global_indices[i]) if len(getattr(self, 'reconstruction_global_indices', [])) == len(self.reconstruction_paths) else int(i)
                self.log(
                    f"Loaded file index {global_idx}: {fp.name} | format={info.get('format')} | "
                    f"sequence {i}/{len(self.reconstruction_paths)-1} | raw={raw_field:+.6f} "
                    f"({info.get('raw_kind', 'unknown')}) | shape={reconstruction.shape}"
                )
            except Exception as exc:
                failures.append((str(fp), f'{type(exc).__name__}: {exc}'))
                self.log(f'FAILED {fp}: {type(exc).__name__}: {exc}')

        if not recons:
            messagebox.showerror(
                'Reconstruction Load Error',
                'All detected reconstruction files failed to load.\n\n'
                + '\n'.join((f'{name}: {err}' for name, err in failures[:8])),
                parent=self.root,
            )
            return False

        if failures:
            messagebox.showerror('Incomplete reconstruction acquisition',
                'No new stack loaded: some files failed.\n'+ '\n'.join(f'{p}: {e}' for p,e in failures[:10]), parent=self.root)
            return False
        try:
            complex_recons, support, focused_grid = _prepare_focused_grid(
                self,complex_recons,loaded_masks,loaded_infos,self.reconstruction_paths)
            recons = [np.real(a).astype(np.float64,copy=False) for a in complex_recons]
            support_native_to_image = support is not None and support.shape == recons[0].shape
        except Exception as exc:
            for key in source_keys:
                if key in previous_source:
                    setattr(self,key,previous_source[key])
                elif hasattr(self,key):
                    delattr(self,key)
            self.log(f'Focused-crop compatibility failed: {type(exc).__name__}: {exc}')
            messagebox.showerror('Focused Crop Compatibility',str(exc),parent=self.root)
            self.status_var.set('Focused-crop loading stopped; see LOG for file details.')
            return False
        self._analysis_signal_kind = 'full_retrieved_state' if all(i.get('format')=='new_v2_full_state' for i in loaded_infos) else 'difference'
        self._focused_common_grid = focused_grid
        self._support_full_grid_cache = None

        self.recons = np.stack(recons, axis=0)
        self.complex_recons = np.stack(complex_recons, axis=0)
        self.real_recons = np.real(self.complex_recons).astype(np.float64, copy=False)
        self.imag_recons = np.imag(self.complex_recons).astype(np.float64, copy=False)
        self.amplitude_recons = np.abs(self.complex_recons).astype(np.float64, copy=False)
        self.phase_recons = np.angle(self.complex_recons).astype(np.float64, copy=False)
        self.supportmask = support
        target_shape = self.recons.shape[1:3]

        if support is None:
            self.supportmask2 = np.ones(target_shape, dtype=bool)
            self.mask_status_var.set('Support mask not present - using full image support')
            self.log('No support mask found; reconstruction loaded with full image support.')
        else:
            try:
                if support.shape == target_shape:
                    self.supportmask2 = np.asarray(support, dtype=bool)
                elif support_native_to_image:
                    raise ValueError(f'native support shape {support.shape} does not match image shape {target_shape}')
                else:
                    self.supportmask2 = self._scale_support_mask(support, target_shape)
            except Exception as exc:
                self.log(f'Support-mask preparation failed: {type(exc).__name__}: {exc}; using full image support.')
                self.supportmask2 = np.ones(target_shape, dtype=bool)

        self.raw_fields = np.asarray(raw_fields, dtype=float)
        self.current_values_A = np.asarray(current_values, dtype=float)
        h5_fields = np.asarray(h5_fields, dtype=float)
        self.reconstruction_formats = np.asarray(formats, dtype=object)

        self._reconstruction_h5_fields_mT = h5_fields.copy()
        _magnet_apply_fields(self, refresh=False)
        self._plot_field_calibration()

        support_label = 'full image' if support is None else str(self.supportmask2.shape)
        valid_fields = int(np.count_nonzero(np.isfinite(self.real_fields_mT)))
        self.info_var.set(
            f'Reconstructions: {self.recons.shape}; Support: {support_label}; '
            f'Fields: {valid_fields}/{len(self.real_fields_mT)} valid mT'
        )
        self.support_start_var.set(0)
        self.support_end_var.set(len(self.recons) - 1)
        self.support_start_spin.configure(to=len(self.recons) - 1)
        self.support_end_spin.configure(to=len(self.recons) - 1)
        self.support_status_var.set(f'{len(self.recons)} reconstructions loaded.')
        self.roi_index_var.set(min(50, len(self.recons) - 1))
        self.proc_slider.configure(to=max(0, len(self.recons) - 1))
        if hasattr(self, 'roi2_slider'):
            self.roi2_slider.configure(from_=0, to=max(0, len(self.recons) - 1), state='disabled')
            self.roi2_idx_var.set(0)
        self.roi_status_var.set('Ready for ROI selection.')
        self.current_index = 0
        self.field_slider_var.set(0)
        try:
            max_idx = max(0, len(self.recons) - 1)
            self.field_slider.configure(from_=0, to=max_idx, state='normal')
            self.field_slider_var.set(0)
            self.field_index_var.set(0)
        except Exception as exc:
            self.log(f'Tab 2 field slider setup warning: {type(exc).__name__}: {exc}')
        self.field_label_var.set(self._field_label_for_frame(0))
        self.log(
            f'Loaded reconstruction stack: {self.recons.shape} | success={len(recons)} | failed={len(failures)} | '
            f'formats={dict(pd.Series(formats).value_counts()) if formats else {}}'
        )
        if np.any(~np.isfinite(self.real_fields_mT) & np.isfinite(self.current_values_A)):
            self.log('Some NEW_V2 files contain current_A but no field_mT; labels/exports keep field_mT as NaN until a calibration JSON is loaded.')
        if hasattr(self, '_roi2_sync_controls'):
            self._roi2_sync_controls()
        if hasattr(self, '_multi_roi_sync_controls'):
            self._multi_roi_sync_controls()
        if hasattr(self, '_multi_fit_sync_controls'):
            self._multi_fit_sync_controls()
        self.nb.select(self.tab_recon)
        self.show_current_recon()
        return True

    def sort_by_field(self):
        if self.recons is None:
            return
        direction_var = getattr(self, 'ramp_direction_var', None)
        direction = direction_var.get() if direction_var is not None else 'Ramp Up (- to +)'
        if direction in ('+ to - to +', '- to + to -') and getattr(self, 'reconstruction_paths', None):
            old_paths = [str(Path(p).resolve()) for p in self.reconstruction_paths]
            items = [(float(f), Path(p)) for f, p in zip(self.reconstruction_raw_fields, self.reconstruction_paths)]
            ordered_items = self._ramp_cycle_items(items, direction)
            pos = {p: i for i, p in enumerate(old_paths)}
            order = np.asarray([pos[str(Path(p).resolve())] for _, p in ordered_items], dtype=int)
            self.reconstruction_paths = [p for _, p in ordered_items]
            self.reconstruction_files = ordered_items
        else:
            order = np.argsort(self.real_fields_mT)
            if direction == 'Ramp Down (+ to -)':
                order = order[::-1]
        self.recons = self.recons[order]
        if self.complex_recons is not None:
            self.complex_recons = self.complex_recons[order]
        if self.real_recons is not None:
            self.real_recons = self.real_recons[order]
        if self.imag_recons is not None:
            self.imag_recons = self.imag_recons[order]
        if self.amplitude_recons is not None:
            self.amplitude_recons = self.amplitude_recons[order]
        if self.phase_recons is not None:
            self.phase_recons = self.phase_recons[order]
        self.raw_fields = self.raw_fields[order]
        self.real_fields_mT = self.real_fields_mT[order]
        self.reconstruction_raw_fields = np.asarray(self.raw_fields, dtype=float).copy()
        self._update_ramp_direction_status(select_default=False)
        self.log('Reconstruction stack sorted in selected ramp order.')
        self.refresh_roi_image()
        self.show_current_recon()

    def _slider_index_update(self, val=None):
        """Update the selected Tab-2 frame from the slider safely and discretely."""
        recons = getattr(self, 'recons', None)
        if recons is None:
            return
        try:
            n_frames = int(len(recons))
        except Exception:
            return
        if n_frames <= 0:
            return

        try:
            raw_value = self.field_slider_var.get() if val is None else val
            idx = int(round(float(raw_value)))
        except (TypeError, ValueError):
            idx = int(getattr(self, 'current_index', 0))
        idx = max(0, min(idx, n_frames - 1))

        # Keep the slider, index and displayed frame synchronized.
        self.current_index = idx
        try:
            if abs(float(self.field_slider_var.get()) - idx) > 1e-9:
                self.field_slider_var.set(idx)
        except Exception:
            pass
        try:
            self.field_index_var.set(idx)
        except Exception:
            pass

        if self.real_fields_mT is not None and idx < len(self.real_fields_mT):
            self.field_label_var.set(self._field_label_for_frame(idx))
        elif self.raw_fields is not None and idx < len(self.raw_fields):
            self.field_label_var.set(f'Field: {self.raw_fields[idx]:+.2f}')
        else:
            self.field_label_var.set(f'Frame: {idx + 1}/{n_frames}')

        # Cancel the previous pending redraw so rapid slider movement only
        # renders the most recent frame.
        if self._slider_redraw_job is not None:
            try:
                self.root.after_cancel(self._slider_redraw_job)
            except Exception:
                pass
            self._slider_redraw_job = None

        if hasattr(self, 'recon_view_canvas'):
            self._slider_redraw_job = self.root.after(60, self._redraw_recon_from_slider)

    def _redraw_recon_from_slider(self):
        """Deferred redraw for the currently selected Tab-2 frame."""
        self._slider_redraw_job = None
        if self.recons is None:
            return
        self.show_current_recon()

    def show_current_recon(self):
        """Display Real / Imaginary / Amplitude / Phase in a centered
        2x2 figure fixed at figsize=(10, 10), inside a scrollable area.
        """
        try:
            if self.recons is None:
                self.field_label_var.set('Field: -- | Load reconstructions first')
                self.log('Tab 2: no reconstruction stack loaded.')
                return
            n_frames = len(self.recons)
            idx = max(0, min(int(self.current_index), n_frames - 1))
            self.current_index = idx
            native_support = None
            native_info = {}
            paths = getattr(self, 'reconstruction_paths', [])
            if paths and idx < len(paths):
                complex_img, native_support, native_info = self._load_reconstruction_h5(paths[idx])
            elif getattr(self, 'complex_recons', None) is not None:
                complex_img = np.asarray(self.complex_recons[idx], dtype=np.complex128)
                native_support = self.supportmask2
            else:
                complex_img = np.asarray(self.recons[idx], dtype=np.complex128)
                native_support = self.supportmask2
            complex_img = np.squeeze(complex_img)
            if complex_img.ndim != 2:
                raise ValueError(f'Selected reconstruction must be 2-D after squeezing; got {complex_img.shape}')
            real_img = np.real(complex_img)
            imag_img = np.imag(complex_img)
            amplitude_img = np.abs(complex_img)
            phase_img = np.angle(complex_img)

            def robust_limits(image, symmetric=False):
                finite = image[np.isfinite(image)]
                if finite.size == 0:
                    return (-1.0, 1.0)
                if symmetric:
                    vmax = float(np.percentile(np.abs(finite), 99))
                    if not np.isfinite(vmax) or vmax <= 0:
                        vmax = float(np.max(np.abs(finite)))
                    if not np.isfinite(vmax) or vmax <= 0:
                        vmax = 1.0
                    return (-vmax, vmax)
                vmin, vmax = np.percentile(finite, [1, 99])
                if not np.isfinite(vmin) or not np.isfinite(vmax):
                    vmin = float(np.min(finite))
                    vmax = float(np.max(finite))
                if vmax <= vmin:
                    vmax = vmin + 1e-12
                return (float(vmin), float(vmax))
            real_vmin, real_vmax = robust_limits(real_img, symmetric=True)
            imag_vmin, imag_vmax = robust_limits(imag_img, symmetric=True)
            amp_vmin, amp_vmax = robust_limits(amplitude_img, symmetric=False)
            fig, axes = plt.subplots(2, 2, figsize=(14, 10), dpi=100)
            im0 = axes[0, 0].imshow(real_img, cmap='gray', origin='lower', vmin=real_vmin, vmax=real_vmax, interpolation='nearest', aspect='equal')
            axes[0, 0].set_title('1. Real Reconstruction')
            axes[0, 0].set_xlabel('X pixel')
            axes[0, 0].set_ylabel('Y pixel')
            fig.colorbar(im0, ax=axes[0, 0], fraction=0.046, pad=0.04, label='Real part')
            im1 = axes[0, 1].imshow(imag_img, cmap='gray', origin='lower', vmin=imag_vmin, vmax=imag_vmax, interpolation='nearest', aspect='equal')
            axes[0, 1].set_title('2. Imaginary Reconstruction')
            axes[0, 1].set_xlabel('X pixel')
            axes[0, 1].set_ylabel('Y pixel')
            fig.colorbar(im1, ax=axes[0, 1], fraction=0.046, pad=0.04, label='Imaginary part')
            im2 = axes[1, 0].imshow(amplitude_img, cmap='gray', origin='lower', vmin=amp_vmin, vmax=amp_vmax, interpolation='nearest', aspect='equal')
            axes[1, 0].set_title('3. Amplitude')
            axes[1, 0].set_xlabel('X pixel')
            axes[1, 0].set_ylabel('Y pixel')
            fig.colorbar(im2, ax=axes[1, 0], fraction=0.046, pad=0.04, label='Amplitude')
            im3 = axes[1, 1].imshow(phase_img, cmap='twilight', origin='lower', vmin=-np.pi, vmax=np.pi, interpolation='nearest', aspect='equal')
            axes[1, 1].set_title('4. Phase')
            axes[1, 1].set_xlabel('X pixel')
            axes[1, 1].set_ylabel('Y pixel')
            phase_cbar = fig.colorbar(im3, ax=axes[1, 1], fraction=0.046, pad=0.04)
            phase_cbar.set_label('Phase (rad)')
            if native_support is not None:
                try:
                    support = np.asarray(native_support, dtype=float)
                    if support.shape == real_img.shape:
                        for ax in axes.ravel():
                            ax.contour(support, levels=[0.5], colors='red', linewidths=0.8)
                except Exception as exc:
                    self.log(f'Tab 2 support contour skipped: {exc}')
            field = self._field_value_for_frame(idx)
            frame_label = self._field_label_for_frame(idx, include_frame=True)
            self.field_label_var.set(frame_label)
            h, w = complex_img.shape
            crop = native_info.get('focused_crop', {})
            crop_label = (f'Full retrieval grid: {w} x {h} px | STATE, not difference'
                if native_info.get('format')=='new_v2_full_state' else f'Native source crop: {w} x {h} px')
            if crop.get('roi'):
                ys, xs = crop['roi']
                crop_label += f" | X={xs[0]}:{xs[1]}:{xs[2]}, Y={ys[0]}:{ys[1]}:{ys[2]}"
            if getattr(self, '_focused_common_grid', None) is not None:
                ah, aw = self.recons.shape[-2:]
                crop_label += f' | Analysis grid: {aw} x {ah} px'
            fig.suptitle(f'Reconstruction {idx + 1}/{n_frames} | {frame_label}\n{crop_label}', fontsize=11)
            fig.subplots_adjust(left=0.07, right=0.94, bottom=0.07, top=0.9, wspace=0.24, hspace=0.24)
            self._recon_axes = axes
            self._recon_panel_images = [(axes[0, 0], real_img, '1. Real Reconstruction'), (axes[0, 1], imag_img, '2. Imaginary Reconstruction'), (axes[1, 0], amplitude_img, '3. Amplitude'), (axes[1, 1], phase_img, '4. Phase')]
            # Disconnect callbacks from the old Matplotlib canvas before destroying it.
            self._unbind_recon_dynamic_zoom()
            self._hide_recon_zoom_popup()
            old_holder = getattr(self, '_recon_figure_holder', None)
            if old_holder is not None:
                try:
                    old_holder.destroy()
                except Exception:
                    pass
            old_fig = self._figs.pop('recon', None)
            if old_fig is not None:
                try:
                    plt.close(old_fig)
                except Exception:
                    pass
            self._recon_figure_holder = ttk.Frame(self.recon_canvas_frame)
            self._recon_figure_holder.pack(anchor='center', padx=12, pady=12)
            canvas = FigureCanvasTkAgg(fig, master=self._recon_figure_holder)
            canvas.draw()
            canvas.get_tk_widget().pack(fill='none', expand=False)
            self._recon_canvas = canvas
            self._figs['recon'] = fig
            if self.recon_dynamic_zoom_var.get():
                self._bind_recon_dynamic_zoom()
            self.recon_scroll_inner.update_idletasks()
            self.recon_view_canvas.update_idletasks()
            viewport_w = self.recon_view_canvas.winfo_width()
            viewport_h = self.recon_view_canvas.winfo_height()
            inner_w = self.recon_scroll_inner.winfo_reqwidth()
            inner_h = self.recon_scroll_inner.winfo_reqheight()
            canvas_w = max(viewport_w, inner_w)
            canvas_h = max(viewport_h, inner_h)
            x = max(0, (viewport_w - inner_w) // 2)
            y = max(0, (viewport_h - inner_h) // 2)
            self.recon_view_canvas.coords(self.recon_view_window, x, y)
            self.recon_view_canvas.configure(scrollregion=(0, 0, canvas_w, canvas_h))
            if inner_w > viewport_w:
                self.recon_view_canvas.xview_moveto(0.0)
            if inner_h > viewport_h:
                self.recon_view_canvas.yview_moveto(0.0)
            self.log(f'Tab 2 displayed frame {idx + 1}/{n_frames} | field={field:+.2f} mT | shape={real_img.shape}')
        except Exception as exc:
            self.field_label_var.set('Field: -- | ERROR')
            self.log(f'Tab 2 display failed: {type(exc).__name__}: {exc}')
            messagebox.showerror('Tab 2 Reconstruction Display', f'Could not display the selected reconstruction.\\n\\n{type(exc).__name__}: {exc}\\n\\nCheck Tab 1 and the selected HDF5 files.', parent=self.root)

    def reset_recon_tab(self):
        """Reset Tab-2 viewing state without reloading or modifying the data."""
        if self.recons is None or len(self.recons) == 0:
            self.current_index = 0
            self.field_slider_var.set(0)
            self.field_label_var.set('Field: --')
            return
        if getattr(self, '_slider_redraw_job', None) is not None:
            try:
                self.root.after_cancel(self._slider_redraw_job)
            except Exception:
                pass
            self._slider_redraw_job = None
        self.current_index = 0
        self.field_slider_var.set(0)
        try:
            self.field_index_var.set(0)
            self.field_slider.configure(to=max(0, len(self.recons) - 1), state='normal')
        except Exception:
            pass
        if self.real_fields_mT is not None and len(self.real_fields_mT):
            self.field_label_var.set(f'Field: {self.real_fields_mT[0]:+.2f} mT')
        elif self.raw_fields is not None and len(self.raw_fields):
            self.field_label_var.set(f'Field: {self.raw_fields[0]:+.2f}')
        else:
            self.field_label_var.set('Field: --')
        self.nb.select(self.tab_recon)
        self.show_current_recon()
        self.log('Tab 2 reset: returned to first reconstruction frame.')

    def _toggle_recon_dynamic_zoom(self):
        """Enable/disable the live mouse-position zoom preview for Tab 2."""
        if self.recon_dynamic_zoom_var.get():
            self._bind_recon_dynamic_zoom()
            self.log('Tab 2 Dynamic Zoom: ENABLED.')
        else:
            self._unbind_recon_dynamic_zoom()
            self._hide_recon_zoom_popup()
            self.log('Tab 2 Dynamic Zoom: DISABLED.')

    def _unbind_recon_dynamic_zoom(self):
        """Disconnect previously registered Matplotlib mouse callbacks."""
        canvas = getattr(self, '_recon_canvas', None)
        if canvas is None:
            self._recon_zoom_bindings = []
            return
        for cid in getattr(self, '_recon_zoom_bindings', []):
            try:
                canvas.mpl_disconnect(cid)
            except Exception:
                pass
        self._recon_zoom_bindings = []

    def _bind_recon_dynamic_zoom(self):
        """Attach live hover and leave callbacks to the Tab-2 reconstruction canvas."""
        self._unbind_recon_dynamic_zoom()
        canvas = getattr(self, '_recon_canvas', None)
        axes = getattr(self, '_recon_axes', None)
        if canvas is None or axes is None:
            return
        try:
            motion_cid = canvas.mpl_connect(
                'motion_notify_event',
                self._recon_dynamic_zoom_motion
            )
            leave_cid = canvas.mpl_connect(
                'figure_leave_event',
                lambda event: self._hide_recon_zoom_popup()
            )
            self._recon_zoom_bindings = [motion_cid, leave_cid]
        except Exception as exc:
            self._recon_zoom_bindings = []
            self.log(f'Tab 2 Dynamic Zoom binding failed: {type(exc).__name__}: {exc}')

    def _hide_recon_zoom_popup(self):
        popup = getattr(self, '_recon_zoom_popup', None)
        if popup is not None:
            try:
                popup.withdraw()
            except Exception:
                pass
        self._recon_zoom_active_ax = None

    def _show_recon_zoom_popup(self, image, x, y, title, source_ax=None):
        """Show a stronger dynamic zoom and preserve the red support/ROI boundary."""
        if image is None or x is None or y is None:
            return

        h, w = image.shape[:2]
        xi = int(round(x))
        yi = int(round(y))

        # Increased magnification: show a smaller pixel window around the cursor.
        # 35 px half-window gives a 71 x 71 px source region instead of the old
        # ~121 x 121 px region.
        half = min(int(self._recon_zoom_half_window_px), max(5, min(h, w) // 2 - 1))
        x0 = max(0, xi - half)
        x1 = min(w, xi + half + 1)
        y0 = max(0, yi - half)
        y1 = min(h, yi + half + 1)
        patch = np.asarray(image[y0:y1, x0:x1])

        popup = getattr(self, '_recon_zoom_popup', None)
        if popup is None or not popup.winfo_exists():
            popup = tk.Toplevel(self.root)
            popup.title('Dynamic Zoom Preview')
            popup.geometry('560x560')
            popup.minsize(480, 480)
            popup.resizable(True, True)
            popup.attributes('-topmost', True)

            top = ttk.Frame(popup, padding=(6, 4))
            top.pack(fill='x')
            self._recon_zoom_title_var = tk.StringVar(value='Dynamic Zoom Preview')
            ttk.Label(
                top, textvariable=self._recon_zoom_title_var,
                font=('Arial', 10, 'bold')
            ).pack(side='left')
            ttk.Button(
                top, text='Close', command=self._hide_recon_zoom_popup
            ).pack(side='right')

            fig, ax = plt.subplots(figsize=(5.3, 5.3), dpi=100)
            fig.subplots_adjust(left=0.10, right=0.98, bottom=0.09, top=0.88)
            self._recon_zoom_fig = fig
            self._recon_zoom_axes = ax
            self._recon_zoom_img_artist = ax.imshow(
                patch, cmap='gray', origin='lower',
                interpolation='nearest', aspect='equal'
            )
            ax.set_xlabel('X pixel')
            ax.set_ylabel('Y pixel')
            ax.set_title(title)
            self._recon_zoom_canvas = FigureCanvasTkAgg(fig, master=popup)
            self._recon_zoom_canvas.draw()
            self._recon_zoom_canvas.get_tk_widget().pack(
                fill='both', expand=True, padx=4, pady=(0, 4)
            )
            self._recon_zoom_popup = popup
        else:
            ax = self._recon_zoom_axes
            if getattr(ax, 'images', None):
                self._recon_zoom_img_artist = ax.images[0]
            try:
                popup.deiconify()
                popup.attributes('-topmost', True)
                popup.lift()
            except Exception:
                pass

        # Match the source image display limits/colormap.
        if source_ax is not None and source_ax.images:
            source_im = source_ax.images[0]
            try:
                vmin, vmax = source_im.get_clim()
                self._recon_zoom_img_artist.set_clim(vmin, vmax)
                self._recon_zoom_img_artist.set_cmap(source_im.get_cmap())
            except Exception:
                pass

        self._recon_zoom_img_artist.set_data(patch)
        self._recon_zoom_img_artist.set_extent(
            (x0 - 0.5, x1 - 0.5, y0 - 0.5, y1 - 0.5)
        )

        ax = self._recon_zoom_axes
        ax.set_xlim(x0 - 0.5, x1 - 0.5)
        ax.set_ylim(y0 - 0.5, y1 - 0.5)

        # ------------------------------------------------------------
        # COPY THE RED BOUNDARY FROM THE SOURCE AXES INTO THE ZOOM.
        # Tab 2 draws the support boundary as a red contour. Matplotlib
        # stores that contour in ax.collections. Recreate only red-ish
        # contour paths in the zoom axes, using the original pixel
        # coordinates. The x/y limits above automatically crop them.
        # ------------------------------------------------------------
        for artist in getattr(self, '_recon_zoom_boundary_artists', []):
            try:
                artist.remove()
            except Exception:
                pass
        self._recon_zoom_boundary_artists = []

        if source_ax is not None:
            try:
                for coll in source_ax.collections:
                    is_red = False
                    try:
                        rgba = np.asarray(coll.get_edgecolor(), dtype=float)
                        if rgba.size:
                            rgba = rgba.reshape(-1, 4)[0]
                            is_red = (rgba[0] > 0.65 and rgba[1] < 0.35 and rgba[2] < 0.35)
                    except Exception:
                        pass
                    if not is_red:
                        try:
                            rgba = np.asarray(coll.get_facecolor(), dtype=float)
                            if rgba.size:
                                rgba = rgba.reshape(-1, 4)[0]
                                is_red = (rgba[0] > 0.65 and rgba[1] < 0.35 and rgba[2] < 0.35)
                        except Exception:
                            pass
                    if not is_red:
                        continue

                    for path in coll.get_paths():
                        verts = np.asarray(path.vertices, dtype=float)
                        if verts.ndim != 2 or verts.shape[0] < 2:
                            continue
                        # Split NaN-separated paths so contour gaps remain gaps.
                        finite = np.isfinite(verts[:, 0]) & np.isfinite(verts[:, 1])
                        if not np.any(finite):
                            continue
                        vv = verts.copy()
                        vv[~finite] = np.nan
                        line, = ax.plot(
                            vv[:, 0], vv[:, 1],
                            color='red', linewidth=2.0,
                            solid_capstyle='round', zorder=30
                        )
                        self._recon_zoom_boundary_artists.append(line)
            except Exception as exc:
                try:
                    self.log(f'Tab 2 Dynamic Zoom boundary copy skipped: {exc}')
                except Exception:
                    pass

        # Keep a clearly visible red boundary even when the source contour
        # is very thin at the original display scale.
        ax.set_title(f'{title}\nCenter: X={xi}, Y={yi}')
        if hasattr(self, '_recon_zoom_title_var'):
            self._recon_zoom_title_var.set(f'Dynamic Zoom — {title}')
        self._recon_zoom_active_ax = source_ax
        self._recon_zoom_canvas.draw_idle()

        try:
            px = self.root.winfo_pointerx()
            py = self.root.winfo_pointery()
            popup = self._recon_zoom_popup
            popup.update_idletasks()
            popup_w = popup.winfo_width()
            popup_h = popup.winfo_height()
            screen_w = popup.winfo_screenwidth()
            screen_h = popup.winfo_screenheight()
            offset = 22
            left = px + offset
            top = py + offset
            if left + popup_w > screen_w:
                left = px - popup_w - offset
            if top + popup_h > screen_h:
                top = py - popup_h - offset
            left = max(0, left)
            top = max(0, top)
            popup.geometry(f'+{int(left)}+{int(top)}')
            popup.deiconify()
        except Exception:
            try:
                self._recon_zoom_popup.deiconify()
            except Exception:
                pass

    def _recon_dynamic_zoom_motion(self, event):
        """Update zoom preview while hovering over any Tab-2 image."""
        if not self.recon_dynamic_zoom_var.get():
            return
        axes = getattr(self, '_recon_axes', None)
        panel_images = getattr(self, '_recon_panel_images', None)
        if axes is None or panel_images is None:
            return
        active_ax = None
        active_image = None
        active_title = None
        for ax, image, title in panel_images:
            if event.inaxes is ax:
                active_ax = ax
                active_image = image
                active_title = title
                break
        if active_ax is None or event.xdata is None or event.ydata is None:
            self._hide_recon_zoom_popup()
            return
        self._show_recon_zoom_popup(active_image, event.xdata, event.ydata, active_title, source_ax=active_ax)

    # ================================================================
    # TAB-3 DYNAMIC ZOOM
    # ================================================================
    def _toggle_support_dynamic_zoom(self):
        """Enable/disable live mouse-position zoom for Tab-3 support previews."""
        if self.support_dynamic_zoom_var.get():
            self._bind_support_dynamic_zoom()
            self.log('Tab 3 Dynamic Zoom: ENABLED.')
        else:
            self._unbind_support_dynamic_zoom()
            self._hide_support_zoom_popup()
            self.log('Tab 3 Dynamic Zoom: DISABLED.')

    def _unbind_support_dynamic_zoom(self):
        """Disconnect all Tab-3 support-preview mouse callbacks."""
        canvas = getattr(self, 'support_canvas', None)
        if canvas is None:
            self._support_zoom_bindings = []
            return
        for cid in getattr(self, '_support_zoom_bindings', []):
            try:
                canvas.mpl_disconnect(cid)
            except Exception:
                pass
        self._support_zoom_bindings = []

    def _bind_support_dynamic_zoom(self):
        """Attach hover/leave callbacks to the Tab-3 support figure."""
        self._unbind_support_dynamic_zoom()
        canvas = getattr(self, 'support_canvas', None)
        axes = getattr(self, 'support_axes', None)
        if canvas is None or axes is None:
            return
        try:
            motion_cid = canvas.mpl_connect(
                'motion_notify_event',
                self._support_dynamic_zoom_motion
            )
            leave_cid = canvas.mpl_connect(
                'figure_leave_event',
                lambda event: self._hide_support_zoom_popup()
            )
            self._support_zoom_bindings = [motion_cid, leave_cid]
        except Exception as exc:
            self._support_zoom_bindings = []
            self.log(
                f'Tab 3 Dynamic Zoom binding failed: '
                f'{type(exc).__name__}: {exc}'
            )

    def _hide_support_zoom_popup(self):
        popup = getattr(self, '_support_zoom_popup', None)
        if popup is not None:
            try:
                popup.withdraw()
            except Exception:
                pass
        self._support_zoom_active_ax = None

    def _show_support_zoom_popup(self, image, x, y, title, source_ax=None):
        """Show a high-magnification preview centered on the mouse position."""
        if image is None or x is None or y is None:
            return

        image = np.ma.asarray(image)
        if image.ndim < 2:
            return
        h, w = image.shape[:2]
        if h < 2 or w < 2:
            return

        if not (-0.5 <= float(x) <= w-0.5 and -0.5 <= float(y) <= h-0.5):
            self._hide_support_zoom_popup()
            return
        xi = int(np.clip(np.rint(float(x)), 0, w - 1))
        yi = int(np.clip(np.rint(float(y)), 0, h - 1))
        half = min(
            int(self._support_zoom_half_window_px),
            max(5, min(h, w) // 2 - 1)
        )
        # Keep the viewport centered and square at native image edges. Only
        # extraction is clamped; the black display margin is not analysis data.
        margin = max(2, int(np.ceil(0.05 * (2 * half + 1))))
        radius = half + margin
        view_x0, view_x1 = xi - radius, xi + radius + 1
        view_y0, view_y1 = yi - radius, yi + radius + 1
        x0 = max(0, view_x0)
        x1 = min(w, view_x1)
        y0 = max(0, view_y0)
        y1 = min(h, view_y1)
        patch = np.ma.asarray(image[y0:y1, x0:x1])

        popup = getattr(self, '_support_zoom_popup', None)
        if popup is None or not popup.winfo_exists():
            popup = tk.Toplevel(self.root)
            popup.title('Tab 3 Dynamic Zoom Preview')
            popup.geometry('560x560')
            popup.minsize(480, 480)
            popup.resizable(True, True)
            popup.attributes('-topmost', True)

            top = ttk.Frame(popup, padding=(6, 4))
            top.pack(fill='x')
            self._support_zoom_title_var = tk.StringVar(
                value='Tab 3 Dynamic Zoom Preview'
            )
            ttk.Label(
                top,
                textvariable=self._support_zoom_title_var,
                font=('Arial', 10, 'bold')
            ).pack(side='left')
            ttk.Button(
                top,
                text='Close',
                command=self._hide_support_zoom_popup
            ).pack(side='right')

            fig, ax = plt.subplots(figsize=(5.3, 5.3), dpi=100)
            fig.subplots_adjust(left=0.10, right=0.98, bottom=0.09, top=0.88)
            self._support_zoom_fig = fig
            self._support_zoom_axes = ax
            self._support_zoom_img_artist = ax.imshow(
                patch,
                cmap='gray',
                origin='lower',
                interpolation='nearest',
                aspect='equal'
            )
            ax.set_xlabel('X pixel')
            ax.set_ylabel('Y pixel')
            ax.set_title(title)
            self._support_zoom_canvas = FigureCanvasTkAgg(fig, master=popup)
            self._support_zoom_canvas.draw()
            self._support_zoom_canvas.get_tk_widget().pack(
                fill='both', expand=True, padx=4, pady=(0, 4)
            )
            self._support_zoom_popup = popup
        else:
            ax = self._support_zoom_axes
            if getattr(ax, 'images', None):
                self._support_zoom_img_artist = ax.images[0]
            try:
                popup.deiconify()
                popup.attributes('-topmost', True)
                popup.lift()
            except Exception:
                pass

        # Preserve the source panel's image scaling/colormap.
        if source_ax is not None and source_ax.images:
            source_im = source_ax.images[0]
            try:
                vmin, vmax = source_im.get_clim()
                self._support_zoom_img_artist.set_clim(vmin, vmax)
                self._support_zoom_img_artist.set_cmap(source_im.get_cmap())
            except Exception:
                pass

        self._support_zoom_img_artist.set_data(patch)
        self._support_zoom_img_artist.set_extent(
            (x0 - 0.5, x1 - 0.5, y0 - 0.5, y1 - 0.5)
        )

        ax = self._support_zoom_axes
        ax.set_autoscale_on(False)
        ax.set_xlim(view_x0 - 0.5, view_x1 - 0.5)
        ax.set_ylim(view_y0 - 0.5, view_y1 - 0.5)
        ax.set_aspect('equal', adjustable='box')
        ax.set_anchor('C')
        ax.set_facecolor('black')

        # Recreate support boundaries/contours from the source axis.
        for artist in getattr(self, '_support_zoom_boundary_artists', []):
            try:
                artist.remove()
            except Exception:
                pass
        self._support_zoom_boundary_artists = []

        if source_ax is not None:
            try:
                for coll in source_ax.collections:
                    color = None
                    try:
                        rgba = np.asarray(coll.get_edgecolor(), dtype=float)
                        if rgba.size:
                            color = rgba.reshape(-1, 4)[0]
                    except Exception:
                        pass
                    if color is None:
                        try:
                            rgba = np.asarray(coll.get_facecolor(), dtype=float)
                            if rgba.size:
                                color = rgba.reshape(-1, 4)[0]
                        except Exception:
                            pass
                    if color is None or len(color) < 3:
                        continue

                    for path in coll.get_paths():
                        verts = np.asarray(path.vertices, dtype=float)
                        if verts.ndim != 2 or verts.shape[0] < 2:
                            continue
                        finite = np.isfinite(verts[:, 0]) & np.isfinite(verts[:, 1])
                        if not np.any(finite):
                            continue
                        vv = verts.copy()
                        vv[~finite] = np.nan
                        # Keep compound-path codes so separate support regions
                        # are not joined by spurious lines in the zoom preview.
                        from matplotlib.patches import PathPatch
                        boundary_patch = PathPatch(path, facecolor='none',
                            edgecolor=tuple(color[:4]), linewidth=2.0, zorder=float(coll.get_zorder()) + 10)
                        ax.add_patch(boundary_patch)
                        self._support_zoom_boundary_artists.append(boundary_patch)
            except Exception as exc:
                try:
                    self.log(
                        f'Tab 3 Dynamic Zoom boundary copy skipped: {exc}'
                    )
                except Exception:
                    pass

        ax.set_title(f'{title}\nCenter: X={xi}, Y={yi}')
        if hasattr(self, '_support_zoom_title_var'):
            self._support_zoom_title_var.set(
                f'Dynamic Zoom — {title}'
            )
        self._support_zoom_active_ax = source_ax
        self._support_zoom_canvas.draw_idle()

        # Keep popup close to, but not directly underneath, the cursor.
        try:
            px = self.root.winfo_pointerx()
            py = self.root.winfo_pointery()
            popup = self._support_zoom_popup
            popup.update_idletasks()
            popup_w = popup.winfo_width()
            popup_h = popup.winfo_height()
            screen_w = popup.winfo_screenwidth()
            screen_h = popup.winfo_screenheight()
            offset = 22
            left = px + offset
            top = py + offset
            if left + popup_w > screen_w:
                left = px - popup_w - offset
            if top + popup_h > screen_h:
                top = py - popup_h - offset
            left = max(0, left)
            top = max(0, top)
            popup.geometry(f'+{int(left)}+{int(top)}')
            popup.deiconify()
        except Exception:
            try:
                self._support_zoom_popup.deiconify()
            except Exception:
                pass

    def _support_dynamic_zoom_motion(self, event):
        """Update Tab-3 dynamic zoom while hovering over any preview image."""
        if not self.support_dynamic_zoom_var.get():
            return

        axes = getattr(self, 'support_axes', None)
        if axes is None:
            return

        active_ax = None
        active_image = None
        active_title = None
        try:
            for ax in np.asarray(axes).flat:
                if event.inaxes is ax and getattr(ax, 'images', None):
                    active_ax = ax
                    active_image = ax.images[0].get_array()
                    active_title = ax.get_title() or 'Support Preview'
                    break
        except Exception:
            active_ax = None

        if active_ax is None or event.xdata is None or event.ydata is None:
            self._hide_support_zoom_popup()
            return

        self._show_support_zoom_popup(
            active_image,
            event.xdata,
            event.ydata,
            active_title,
            source_ax=active_ax
        )

    def show_support(self):
        """Open original and scaled support masks in a separate window."""
        if self.supportmask is None and self.supportmask2 is None:
            messagebox.showwarning('Support Mask', 'No support mask is available.', parent=self.root)
            return
        existing = getattr(self, '_support_popup', None)
        if existing is not None:
            try:
                if existing.winfo_exists():
                    existing.deiconify()
                    existing.lift()
                    existing.focus_force()
                    return
            except Exception:
                pass
        popup = tk.Toplevel(self.root)
        popup.title('Support Masks — Original vs Scaled')
        popup.geometry('1500x850')
        popup.minsize(1000, 650)
        top = ttk.Frame(popup, padding=8)
        top.pack(fill='x')
        ttk.Label(top, text='Support Mask Comparison', font=('Arial', 13, 'bold')).pack(side='left')
        original = np.asarray(self.supportmask, dtype=bool) if self.supportmask is not None else None
        scaled = np.asarray(self.supportmask2, dtype=bool) if self.supportmask2 is not None else None
        fig, axes = plt.subplots(1, 2, figsize=(14, 7), dpi=100)
        if original is not None:
            ax0 = axes[0]
            ax0.imshow(original, cmap='gray', origin='lower', interpolation='nearest', aspect='equal')
            ax0.contour(original.astype(float), levels=[0.5], colors='red', linewidths=1.0)
            ax0.set_title(f'Original Support Mask\n{original.shape[1]} × {original.shape[0]} px | {int(original.sum()):,} pixels')
            ax0.set_xlabel('X pixel')
            ax0.set_ylabel('Y pixel')
        else:
            axes[0].text(0.5, 0.5, 'Original support unavailable', ha='center', va='center', transform=axes[0].transAxes)
            axes[0].axis('off')
        if scaled is not None:
            ax1 = axes[1]
            ax1.imshow(scaled, cmap='gray', origin='lower', interpolation='nearest', aspect='equal')
            ax1.contour(scaled.astype(float), levels=[0.5], colors='red', linewidths=1.0)
            ax1.set_title(f'Scaled Support Mask\n{scaled.shape[1]} × {scaled.shape[0]} px | {int(scaled.sum()):,} pixels')
            ax1.set_xlabel('X pixel')
            ax1.set_ylabel('Y pixel')
        else:
            axes[1].text(0.5, 0.5, 'Scaled support unavailable', ha='center', va='center', transform=axes[1].transAxes)
            axes[1].axis('off')
        fig.suptitle('Original Support Mask vs Scaled Support Mask', fontsize=14)
        fig.subplots_adjust(left=0.035, right=0.975, bottom=0.075, top=0.87, wspace=0.22)
        canvas = FigureCanvasTkAgg(fig, master=popup)
        canvas.draw()
        canvas.get_tk_widget().pack(fill='both', expand=True, padx=8, pady=(0, 8))
        bottom = ttk.Frame(popup, padding=(8, 0, 8, 8))
        bottom.pack(fill='x')
        original_info = f'Original: {original.shape[1]}×{original.shape[0]} ({int(original.sum()):,} pixels)' if original is not None else 'Original: unavailable'
        scaled_info = f'Scaled: {scaled.shape[1]}×{scaled.shape[0]} ({int(scaled.sum()):,} pixels)' if scaled is not None else 'Scaled: unavailable'
        ttk.Label(bottom, text=f'{original_info}    |    {scaled_info}').pack(side='left')
        ttk.Button(bottom, text='Close', command=self._close_support_popup).pack(side='right')
        self._support_popup = popup
        self._support_popup_fig = fig
        self._support_popup_canvas = canvas
        popup.protocol('WM_DELETE_WINDOW', self._close_support_popup)
        popup.lift()
        popup.focus_force()

    def _close_support_popup(self):
        """Close the separate support-mask window."""
        popup = getattr(self, '_support_popup', None)
        try:
            if getattr(self, '_support_popup_fig', None) is not None:
                plt.close(self._support_popup_fig)
        except Exception:
            pass
        try:
            if popup is not None and popup.winfo_exists():
                popup.destroy()
        except Exception:
            pass
        self._support_popup = None
        self._support_popup_fig = None
        self._support_popup_canvas = None

    def setup_field_slider(self):
        self.nb.select(self.tab_recon)
        self.show_current_recon()

    def _build_support_tab(self):
        """Build support-mask optimization with a fully scrollable control panel."""
        self.support_threshold_mode_var = tk.StringVar(value='Manual')
        self.support_live_preview_var = tk.BooleanVar(value=True)
        self.support_open_var = tk.IntVar(value=0)
        self.support_erode_var = tk.IntVar(value=0)
        self.support_fill_holes_var = tk.BooleanVar(value=True)
        self.support_hole_area_var = tk.IntVar(value=500)
        self.support_largest_var = tk.BooleanVar(value=False)
        self._support_preview_job = None
        self._support_prepared_cache = None
        self.support_view_var = tk.StringVar(value='Full HDF5 grid')
        self._support_full_grid_cache = None
        self.support_grid_var = tk.StringVar(value='Native reconstruction: --')
        self.support_threshold_var = tk.DoubleVar(value=0.12)
        self.support_consensus_var = tk.DoubleVar(value=0.5)
        self.support_min_size_var = tk.IntVar(value=500)
        self.support_close_var = tk.IntVar(value=3)
        self.support_dilate_var = tk.IntVar(value=3)
        self.support_sigma_var = tk.DoubleVar(value=1.0)
        self.support_mode_var = tk.StringVar(value='Median')
        self.support_seed_var = tk.StringVar(value='Original support')
        self.support_start_var = tk.IntVar(value=0)
        self.support_end_var = tk.IntVar(value=0)
        self.support_source_var = tk.StringVar(value='Generate from reconstruction')
        self._uploaded_support_mask = None
        self._uploaded_support_path = None
        self.support_status_var = tk.StringVar(value='Load reconstructions first.')
        self.support_original_pixels_var = tk.StringVar(value='Original: --')
        self.support_candidate_pixels_var = tk.StringVar(value='Candidate: --')
        # Always start a Tab-3 rebuild with its previous zoom callback/window closed.
        try:
            self._unbind_support_dynamic_zoom()
            self._hide_support_zoom_popup()
            self.support_dynamic_zoom_var.set(False)
        except Exception:
            pass

        main = ttk.Frame(self.tab_support, padding=8)
        main.pack(fill='both', expand=True)
        left = ttk.Frame(main)
        left.pack(side='left', fill='both', expand=True, padx=(0, 8))

        zoom_bar = ttk.Frame(left)
        zoom_bar.pack(fill='x', pady=(0, 4))
        ttk.Checkbutton(
            zoom_bar,
            text='Enable Dynamic Zoom',
            variable=self.support_dynamic_zoom_var,
            command=self._toggle_support_dynamic_zoom
        ).pack(side='left')
        ttk.Label(
            zoom_bar,
            text=''
        ).pack(side='left', padx=(10, 0))

        ttk.Label(zoom_bar, text='Grid').pack(side='left', padx=(12, 4))
        self.support_view_combo = ttk.Combobox(zoom_bar, textvariable=self.support_view_var,
            values=['Full HDF5 grid', 'Focused crop'], state='readonly', width=18)
        self.support_view_combo.pack(side='left')
        self.support_view_combo.bind('<<ComboboxSelected>>', lambda event: self._support_refresh_grid_view())

        self.support_fig, self.support_axes = plt.subplots(2, 2, figsize=(10, 8), dpi=100)
        self.support_canvas = FigureCanvasTkAgg(self.support_fig, master=left)
        self.support_canvas.draw()
        self.support_canvas.get_tk_widget().pack(fill='both', expand=True)
        if self.support_dynamic_zoom_var.get():
            self._bind_support_dynamic_zoom()
        panel = ttk.Frame(main, width=440)
        panel.pack(side='right', fill='y')
        panel.pack_propagate(False)
        self.support_ctrl_canvas = tk.Canvas(panel, highlightthickness=0, borderwidth=0)
        self.support_ctrl_scrollbar = ttk.Scrollbar(panel, orient='vertical', command=self.support_ctrl_canvas.yview)
        self.support_ctrl_canvas.configure(yscrollcommand=self.support_ctrl_scrollbar.set)
        self.support_ctrl_scrollbar.pack(side='right', fill='y')
        self.support_ctrl_canvas.pack(side='left', fill='both', expand=True)
        self.support_ctrl_inner = ttk.Frame(self.support_ctrl_canvas, padding=(6, 4, 10, 12))
        self.support_ctrl_window = self.support_ctrl_canvas.create_window((0, 0), window=self.support_ctrl_inner, anchor='nw')

        def _support_update_scrollregion(event=None):
            self.support_ctrl_canvas.configure(scrollregion=self.support_ctrl_canvas.bbox('all'))

        def _support_resize_inner(event):
            self.support_ctrl_canvas.itemconfigure(self.support_ctrl_window, width=event.width)
        self.support_ctrl_inner.bind('<Configure>', _support_update_scrollregion)
        self.support_ctrl_canvas.bind('<Configure>', _support_resize_inner)

        def _support_mousewheel(event):
            if event.delta:
                self.support_ctrl_canvas.yview_scroll(int(-event.delta / 120), 'units')
            elif getattr(event, 'num', None) == 4:
                self.support_ctrl_canvas.yview_scroll(-3, 'units')
            elif getattr(event, 'num', None) == 5:
                self.support_ctrl_canvas.yview_scroll(3, 'units')
        self.support_ctrl_canvas.bind('<MouseWheel>', _support_mousewheel)
        self.support_ctrl_inner.bind('<MouseWheel>', _support_mousewheel)
        ttk.Label(self.support_ctrl_inner, text='CONSENSUS SUPPORT GENERATOR', font=('Arial', 12, 'bold')).pack(anchor='w', pady=(2, 4))
        ttk.Label(self.support_ctrl_inner, text='Full controls are available by scrolling.\\nPipeline: normalize → smooth → threshold → clean → consensus → final morphology.', wraplength=390, justify='left').pack(anchor='w', pady=(0, 10))
        source_box = ttk.LabelFrame(self.support_ctrl_inner, text='0. MASK SOURCE — choose one', padding=8)
        source_box.pack(fill='x', pady=5)
        ttk.Radiobutton(source_box, text='Generate support from reconstruction stack', variable=self.support_source_var, value='Generate from reconstruction', command=self._support_source_changed).pack(anchor='w', pady=2)
        ttk.Radiobutton(source_box, text='Use uploaded .npy mask', variable=self.support_source_var, value='Uploaded .npy mask', command=self._support_source_changed).pack(anchor='w', pady=2)
        source_buttons = ttk.Frame(source_box)
        source_buttons.pack(fill='x', pady=(6, 2))
        ttk.Button(source_buttons, text='UPLOAD .NPY MASK', command=self.upload_support_mask).pack(side='left', expand=True, fill='x', padx=(0, 3))
        ttk.Button(source_buttons, text='GENERATE MASK', command=self._support_generate_clicked).pack(side='left', expand=True, fill='x', padx=(3, 0))
        self.support_source_file_var = tk.StringVar(value='No .npy mask loaded.')
        ttk.Label(source_box, textvariable=self.support_source_file_var, wraplength=390, justify='left').pack(anchor='w', pady=(4, 0))
        ttk.Label(source_box, text='Uploaded masks are validated as 2-D arrays and resized to the reconstruction size when necessary. Upload does not replace the active support until APPLY AS SUPPORT MASK is pressed.', wraplength=390, justify='left').pack(anchor='w', pady=(5, 0))
        box = ttk.LabelFrame(self.support_ctrl_inner, text='1. Detection / Consensus', padding=8)
