            y1 = float(c['ymax'] + 1) * sy
            self.line_source_status_var.set(f'✓ Source = Tab 6 confirmed Secondary ROI | X={x0:.6g}–{x1:.6g} nm, Y={y0:.6g}–{y1:.6g} nm | crop physical size={x1 - x0:.6g} × {y1 - y0:.6g} nm | frames={len(self.line_source_stack)}')
