# Rebuild the Tab-7 controls after the original builder has created them.
_LPA_BUILD_ORIGINAL_V2 = _build_line_profile_analysis_tab

def _build_line_profile_analysis_tab_v2(self):
    result = _LPA_BUILD_ORIGINAL_V2(self)
    try:
        outer = self.tab_line_profile_analysis.winfo_children()[0]

        # Existing top control row.
        children = list(outer.winfo_children())
        controls = None
        vertical = None
        for w in children:
            try:
                if isinstance(w, ttk.Panedwindow):
                    vertical = w
            except Exception:
                pass
            try:
                labels = set()
                if isinstance(w, ttk.Frame):
                    for c in w.winfo_children():
                        try:
                            labels.add(str(c.cget('text')))
                        except Exception:
                            pass
                    if {'ROI2 FROM TAB 6', 'RESET ZOOM', 'DRAW LINE', 'MEASURE'} & labels:
                        controls = w
            except Exception:
                pass

        if controls is None:
            controls = ttk.Frame(outer)
            if vertical is not None:
                controls.pack(fill='x', pady=(0, 4), before=vertical)
            else:
                controls.pack(fill='x', pady=(0, 4))

        # Existing export buttons stay on the original top row.
        existing_texts = set()
        for c in controls.winfo_children():
            try:
                existing_texts.add(str(c.cget('text')))
            except Exception:
                pass
        if 'TABLE EXPORT' not in existing_texts:
            ttk.Button(
                controls,
                text='TABLE EXPORT',
                command=lambda: _t7v2_table_export(self),
                width=13,
            ).pack(side='left', padx=5)
        if 'PLOT EXPORT' not in existing_texts:
            ttk.Button(
                controls,
                text='PLOT EXPORT',
                command=lambda: _t7v2_export_plot(self),
                width=13,
            ).pack(side='left', padx=5)

        # Persistent Tab-7 threshold state.
        if not hasattr(self, '_lpa_intensity_threshold_var'):
            self._lpa_intensity_threshold_var = tk.BooleanVar(value=False)
        if not hasattr(self, '_lpa_intensity_threshold_value_var'):
            self._lpa_intensity_threshold_value_var = tk.DoubleVar(value=0.50)
        if not hasattr(self, '_lpa_avg_distance_nm'):
            self._lpa_avg_distance_nm = np.nan
        if not hasattr(self, '_lpa_sd_distance_nm'):
            self._lpa_sd_distance_nm = np.nan

        # Dedicated SECOND ROW. This is built directly as part of Tab 7,
        # rather than searching widget indexes after the application has built.
        row = getattr(self, '_lpa_threshold_controls_row', None)
        try:
            if row is not None and row.winfo_exists():
                row.destroy()
        except Exception:
            pass

        row = ttk.Frame(outer)
        self._lpa_threshold_controls_row = row
        if vertical is not None:
            row.pack(fill='x', pady=(0, 5), before=vertical)
        else:
            row.pack(fill='x', pady=(0, 5))

        ttk.Checkbutton(
            row,
            text='Intensity threshold',
            variable=self._lpa_intensity_threshold_var,
            command=lambda: _t7_threshold_toggle(self),
        ).pack(side='left', padx=(2, 6))

        ttk.Label(row, text='Set Value =').pack(side='left', padx=(0, 3))

        self._lpa_threshold_value_spin = tk.Spinbox(
            row,
            from_=0.00,
            to=1.00,
            increment=0.01,
            width=6,
            format='%.2f',
            textvariable=self._lpa_intensity_threshold_value_var,
            command=lambda: _t7_threshold_value_changed(self),
        )
        self._lpa_threshold_value_spin.pack(side='left', padx=(0, 10))

        # Also react when the user types directly into the Spinbox.
        old_trace = getattr(self, '_lpa_threshold_trace_name', None)
        if old_trace:
            try:
                self._lpa_intensity_threshold_value_var.trace_remove('write', old_trace)
            except Exception:
                pass
        try:
            self._lpa_threshold_trace_name = self._lpa_intensity_threshold_value_var.trace_add(
                'write', lambda *_args: _t7_threshold_value_changed(self)
            )
        except Exception:
            self._lpa_threshold_trace_name = None

        ttk.Button(
            row,
            text='FIT',
            width=9,
            command=lambda: _t7_threshold_fit(self),
        ).pack(side='left', padx=(2, 5))

        ttk.Button(
            row,
            text='AVG. DISTANCE',
            width=15,
            command=lambda: _t7_avg_distance(self),
        ).pack(side='left', padx=(0, 5))

        # Initialise the enhanced measurement table without performing a fit.
        self._lpa_measurements = []
        self._lpa_measure_mode = False
        self._lpa_measure_first = None
        self._lpa_measure_drag = None
        _t7_threshold_configure_table(self)
        _t7_threshold_update_table(self)
    except Exception as exc:
        try:
            self._lpa_status_var.set(
                f'Tab-7 controls initialization warning: {type(exc).__name__}: {exc}'
            )
        except Exception:
            pass
    return result

_build_line_profile_analysis_tab = _build_line_profile_analysis_tab_v2

