def _final_rebind_tab6_callbacks(self):
    """Rebind ONLY Tab-6 image mouse callbacks using Matplotlib's native event system.

    The previous patch relied on a Tk-to-Matplotlib coordinate conversion while the
    original Tab-6 Matplotlib callbacks were commented out.  That left the button
    in DRAWING mode but no reliable press/motion/release events reached the ROI
    selector.  This patch restores the Tab-6 callbacks directly on the existing
    _proc_canvas.  No other tab callbacks are changed.
    """
    canvas=getattr(self,'_proc_canvas',None)
    ax=getattr(self,'_proc_ax',None)
    if canvas is None or ax is None:
        return

    # Remove only the callbacks installed by this patch, if any.
    for attr in ('_final_tab6_mpl_press_cid','_final_tab6_mpl_motion_cid','_final_tab6_mpl_release_cid'):
        cid=getattr(self, attr, None)
        if cid is not None:
            try: canvas.mpl_disconnect(cid)
            except Exception: pass
            setattr(self, attr, None)

    # Remove only our older Tk bindings; they are no longer needed and can
    # otherwise compete with Matplotlib's native event dispatch.
    widget=canvas.get_tk_widget()
    _final_unbind_owned_tk(widget,'<ButtonPress-1>','_final_tab6_press_tk_id')
    _final_unbind_owned_tk(widget,'<B1-Motion>','_final_tab6_motion_tk_id')
    _final_unbind_owned_tk(widget,'<ButtonRelease-1>','_final_tab6_release_tk_id')

    self._final_tab6_mpl_press_cid=canvas.mpl_connect(
        'button_press_event', lambda e: _final_tab6_mpl_press(self,e))
    self._final_tab6_mpl_motion_cid=canvas.mpl_connect(
        'motion_notify_event', lambda e: _final_tab6_mpl_motion(self,e))
    self._final_tab6_mpl_release_cid=canvas.mpl_connect(
        'button_release_event', lambda e: _final_tab6_mpl_release(self,e))


# Keep the existing Tab-6 confirmation/data path intact, but guarantee the
# displayed ROI is redrawn as the confirmed green rectangle after confirmation.
_TAB6_CONFIRM_DISPLAY_BASE = CDIWorkflowApp.confirm_secondary_roi_from_processing
def _final_tab6_confirm_display(self, *args, **kwargs):
    result = _TAB6_CONFIRM_DISPLAY_BASE(self, *args, **kwargs)
    try:
        self._proc_draw_secondary_roi_patch(confirmed=True)
        if getattr(self, '_proc_canvas', None) is not None:
            self._proc_canvas.draw_idle()
    except Exception:
        pass
    return result
CDIWorkflowApp.confirm_secondary_roi_from_processing = _final_tab6_confirm_display


