# ============================================================================
# TAB 8
# ============================================================================


# ============================================================================
# TAB 8 — ROBUST REBUILD (V7)
# Skyrmion / Particle — Outer Particle + Inner Core + Core Symmetry
# ============================================================================
# Scope:
#   * Tabs 1–7 and all later tabs are left untouched.
#   * Tab 8 consumes the exact processed/finalized Primary ROI1 from Tab 6.
#   * Tab-6 X/Y calibration is authoritative; all Tab-8 image axes are in nm.
#   * Frame slider is one-based in the UI, always enabled when source data exist,
#     and responds directly to mouse dragging.
#   * PLAY / PAUSE / FIRST / PREVIOUS / NEXT provide deterministic frame control.
#   * ROI3 is selected on the Primary ROI1 image, then explicitly confirmed.
#   * Detection, manual ADD BLOB, selection, delete, undo, CLEAR MARK and RESET
#     are isolated to Tab 8.
#   * Analysis results are retained by acquisition/frame number and plotted only
#     for frames that were actually analyzed.
# ============================================================================

def _tab8_roi_shape_changed(self, shape):
    if shape not in ('Square', 'Circle'): return False
    old = getattr(self, '_tab8_roi_shape', 'Square')
    if old != shape: _tab8_v7_clear_roi3(self)
    self._tab8_roi_shape = shape
    self.pd_rectangle_roi_var.set(shape == 'Square')
    self.pd_circle_roi_var.set(shape == 'Circle')
    self.pd_circle_diameter_entry.configure(state='normal')
    self.pd_circle_diameter_button.configure(state='normal')
    self.pd_status_var.set(f'{shape}: enter diameter / side length in nm and click Set; position on Primary ROI, then CONFIRM ROI.')
    return True


def _tab8_fixed_shape_coords(self, cx, cy, size=None, shape=None):
    shape = shape or getattr(self, '_tab8_roi_shape', 'Square')
    if shape not in ('Square', 'Circle'): raise ValueError('Select Square or Circle.')
    sx, sy = map(float, self._tab8_fixed_scale)
    ph, pw = self._tab8_primary_shape
    size = float(self.pd_circle_diameter_var.get()) if size is None else float(size)
    lower, upper = 2*max(sx,sy), min(pw*sx,ph*sy)
    if not np.isfinite(size) or not lower <= size <= upper:
        raise ValueError(f'Diameter / side length must be between {lower:.6g} and {upper:.6g} nm.')
    radius = size/2.
    cx = float(np.clip(cx, radius, pw*sx-radius))
    cy = float(np.clip(cy, radius, ph*sy-radius))
    coords = dict(xmin=max(0,int(np.floor((cx-radius)/sx))),
        xmax=min(pw-1,int(np.ceil((cx+radius)/sx))-1),
        ymin=max(0,int(np.floor((cy-radius)/sy))),
        ymax=min(ph-1,int(np.ceil((cy+radius)/sy))-1), shape=shape)
    if shape == 'Circle': coords.update(circle_x_nm=cx,circle_y_nm=cy,circle_radius_nm=radius)
    else: coords.update(square_x_nm=cx,square_y_nm=cy,square_side_nm=size)
    return coords


def _tab8_fixed_circle_coords(self, cx, cy, diameter=None):
    return _tab8_fixed_shape_coords(self, cx, cy, diameter, shape='Circle')


def _tab8_circle_preview(self, cx, cy):
    # Compatibility name: fixed-size positioning now supports both shapes.
    try: c = _tab8_fixed_shape_coords(self,cx,cy)
    except (ValueError, TypeError, tk.TclError) as exc:
        self.pd_status_var.set(str(exc)); return False
    self._tab8_pending_roi3_coords = c
    self._tab8_roi3_coords = dict(c)
    self._tab8_roi3_confirmed = False
    _tab8_v7_draw_overlays(self)
    circle = c['shape'] == 'Circle'
    size = 2*c['circle_radius_nm'] if circle else c['square_side_nm']
    self.pd_status_var.set(f"{c['shape']} {'diameter' if circle else 'side length'} {size:.6g} nm | arrows move; CONFIRM ROI locks.")
    return True


def _tab8_circle_apply_diameter(self):
    # Shared Diameter / Side length Set action, retaining legacy callback name.
    primary = _tab8_v7_get_primary_stack(self)
    if primary is None:
        self.pd_status_var.set('Load Primary ROI from Tab 6 first.'); return False
    c = getattr(self, '_tab8_roi3_coords', None) or {}
    sx,sy = self._tab8_fixed_scale
    cx = c.get('square_x_nm',c.get('circle_x_nm',primary.shape[2]*sx/2.))
    cy = c.get('square_y_nm',c.get('circle_y_nm',primary.shape[1]*sy/2.))
    try: _tab8_fixed_shape_coords(self,cx,cy)
    except (ValueError,TypeError,tk.TclError) as exc:
        self.pd_status_var.set(str(exc)); return False
    _tab8_v7_clear_roi3(self)
    self._tab8_roi3_select_mode = True
    self.pd_roi3_select_button.configure(text='CANCEL ROI3')
    self.pd_canvas.get_tk_widget().focus_set()
    return _tab8_circle_preview(self,cx,cy)


def _tab8_circle_key(self, event):
    if (not getattr(self, '_tab8_roi3_select_mode', False) or getattr(self, '_tab8_roi3_confirmed', False)): return
    c = getattr(self, '_tab8_pending_roi3_coords', None)
    if not isinstance(c,dict): return
    moves = {'Left':(-1,0),'Right':(1,0),'Up':(0,1),'Down':(0,-1)}
    if event.keysym not in moves: return
    dx,dy = moves[event.keysym]; step = 10 if event.state & 1 else 1
    sx,sy = self._tab8_fixed_scale
    cx=c.get('square_x_nm',c.get('circle_x_nm')); cy=c.get('square_y_nm',c.get('circle_y_nm'))
    _tab8_circle_preview(self,cx+dx*sx*step,cy+dy*sy*step)
    return 'break'


def _tab8_detection_summary(self):
    d = getattr(self, '_tab8_detection_diagnostics', {})
    counts = d.get('rejected',{})
    rejected = ', '.join(f'{key}={value}' for key,value in counts.items() if value)
    text = f"Detection: {d.get('accepted',0)} accepted / {d.get('candidates',0)} candidates"
    if rejected:
        text += ' | Rejected: '+rejected
    if counts.get('SNR',0):
        text += f" | best rejected SNR={d.get('best_rejected_snr',0.):.3g}; required={d.get('min_snr',0.):.3g}"
    if hasattr(self,'pd_detection_diagnostics_var'):
        self.pd_detection_diagnostics_var.set(text)
    return text


def _tab8_roi_shape_patch(self, xa, xb, ya, yb, edge='red', coords=None):
    from matplotlib.patches import Circle, Rectangle
    shape = (coords or {}).get('shape', getattr(self, '_tab8_roi_shape', 'Square'))
    if shape == 'Circle':
        cx = (coords or {}).get('circle_x_nm', (xa+xb)/2.)
        cy = (coords or {}).get('circle_y_nm', (ya+yb)/2.)
        radius = (coords or {}).get('circle_radius_nm', min(xb-xa, yb-ya)/2.)
        return Circle((cx,cy), max(1e-12,radius), fill=False, edgecolor=edge, linewidth=2., zorder=30)
    if shape == 'Square' and coords and 'square_side_nm' in coords:
        side=coords['square_side_nm']
        xa,ya=coords['square_x_nm']-side/2.,coords['square_y_nm']-side/2.
        xb,yb=xa+side,ya+side
    return Rectangle((xa,ya), max(1e-12,xb-xa), max(1e-12,yb-ya),
                     fill=False, edgecolor=edge, linewidth=2., zorder=30)


def _tab8_roi_apply_shape(self):
    c = getattr(self, '_tab8_roi3_coords', None)
    stack = getattr(self, '_tab8_roi3_stack', None)
    if stack is None or not isinstance(c, dict): return
    shape = c.get('shape')
    if shape not in ('Circle','Square'): return
    # Legacy rectangular ROI dictionaries have no physical square metadata.
    if shape == 'Square' and 'square_side_nm' not in c: return
    sx,sy = self._tab8_fixed_scale
    yy,xx = np.indices(stack.shape[1:])
    xx = (xx+c['xmin']+.5)*sx; yy = (yy+c['ymin']+.5)*sy
    if shape == 'Circle':
        mask = (xx-c['circle_x_nm'])**2+(yy-c['circle_y_nm'])**2 <= c['circle_radius_nm']**2
    else:
        half=c['square_side_nm']/2.
        mask = (np.abs(xx-c['square_x_nm'])<=half) & (np.abs(yy-c['square_y_nm'])<=half)
    stack[:,~mask] = np.nan


def _tab8_roi_circle_coords(self, x0, y0, x1, y1):
    sx,sy = self._tab8_fixed_scale
    ph,pw = self._tab8_primary_shape
    xa,xb = sorted((x0,x1))
    ya,yb = sorted((y0,y1))
    cx,cy = (xa+xb)/2., (ya+yb)/2.
    radius = min(xb-xa,yb-ya)/2.
    return dict(xmin=max(0,int(np.floor((cx-radius)/sx))),
                xmax=min(pw-1,int(np.ceil((cx+radius)/sx))-1),
                ymin=max(0,int(np.floor((cy-radius)/sy))),
                ymax=min(ph-1,int(np.ceil((cy+radius)/sy))-1),
                shape='Circle', circle_x_nm=cx, circle_y_nm=cy, circle_radius_nm=radius)


def _tab8_v7_get_scale(self):
    """Return the exact physical X/Y scale used by Tab 6/Fig. 2.

    Priority is the physical extent actually applied to the Tab-6 Primary ROI
    display. This prevents Tab 8 from falling back to the resized output-pixel
    calibration and therefore showing a compressed ~0-2400 nm FOV when Fig. 2
    represents the full ~0-13500 nm Primary ROI.
    """
    # 1) Authoritative extent generated by Tab 6 physical-axis update.
    try:
        ext = getattr(self, '_proc_full_physical_extent', None)
        arr = getattr(self, '_proc_image_display', None)
        if ext is not None and arr is not None and arr.get_array() is not None:
            a = np.asarray(arr.get_array())
            h, w = a.shape[:2]
            x0, x1, y0, y1 = map(float, ext)
            if w > 0 and h > 0 and x1 > x0 and y1 > y0:
                return ((x1-x0)/float(w), (y1-y0)/float(h))
    except Exception:
        pass

    # 2) Read the actual extent from the Tab-6 image artist if available.
    try:
        im = getattr(self, '_proc_image_display', None)
        if im is not None and im.get_array() is not None:
            a = np.asarray(im.get_array())
            h, w = a.shape[:2]
            x0, x1, y0, y1 = map(float, im.get_extent())
            if w > 0 and h > 0 and x1 > x0 and y1 > y0:
                return ((x1-x0)/float(w), (y1-y0)/float(h))
    except Exception:
        pass

    # 3) Existing calibrated physical ROI dimensions as fallback.
    try:
        base = float(getattr(self, 'primary_roi_final_nm_per_pixel', np.nan))
        ow = int(getattr(self, 'original_roi_w', 0) or 0)
        oh = int(getattr(self, 'original_roi_h', 0) or 0)
        rw, rh = getattr(self, 'roi_resolution', (0, 0))
        rw, rh = int(rw), int(rh)
        if np.isfinite(base) and base > 0 and ow > 0 and oh > 0 and rw > 0 and rh > 0:
            return (base*float(ow)/float(rw), base*float(oh)/float(rh))
    except Exception:
        pass

    try:
        v = float(getattr(self, 'primary_roi_final_nm_per_pixel'))
        if np.isfinite(v) and v > 0:
            return (v, v)
    except Exception:
        pass
    return None, None

def _tab8_v7_get_field(self, idx):
    values = getattr(self, 'real_fields_mT', None)
    if values is not None and 0 <= int(idx) < len(values):
        value = float(values[int(idx)])
        if np.isfinite(value):
            return value
    return float('nan')



def _tab8_v7_get_primary_stack(self):
    stack = getattr(self, '_tab8_primary_stack', None)
    try:
        a = np.asarray(stack)
        if a.ndim == 3 and a.shape[0] > 0 and a.shape[1] > 1 and a.shape[2] > 1:
            return a
    except Exception:
        pass
    return None


def _tab8_v7_get_roi3_stack(self):
    if not getattr(self, '_tab8_roi3_confirmed', False):
        return None
    stack = getattr(self, '_tab8_roi3_stack', None)
    try:
        a = np.asarray(stack)
        if a.ndim == 3 and a.shape[0] > 0 and a.shape[1] > 1 and a.shape[2] > 1:
            return a
    except Exception:
        pass
    return None


def _tab8_v7_primary_extent(self):
    st = _tab8_v7_get_primary_stack(self)
    sx, sy = getattr(self, '_tab8_fixed_scale', (None, None))
    if st is None or sx is None or sy is None:
        return None
    h, w = st.shape[1:3]
    return (0.0, float(w) * float(sx), 0.0, float(h) * float(sy))


def _tab8_v7_roi3_extent(self):
    st = _tab8_v7_get_roi3_stack(self)
    sx, sy = getattr(self, '_tab8_fixed_scale', (None, None))
    if st is None or sx is None or sy is None:
        return None
    h, w = st.shape[1:3]
    return (0.0, float(w) * float(sx), 0.0, float(h) * float(sy))


def _tab8_v7_equiv_scale(self):
    sx, sy = _tab8_v7_get_scale(self)
    if sx is None or sy is None:
        return None
    return float(np.sqrt(sx * sy))


def _tab8_v7_clear_artists(self, attr):
    for artist in list(getattr(self, attr, []) or []):
        try:
            artist.remove()
        except Exception:
            pass
    setattr(self, attr, [])


def _tab8_v7_stop_playback(self, update_button=True):
    """Cancel only Tab-8's scheduled playback callback."""
    self._tab8_playing = False
    job = getattr(self, '_tab8_play_job', None)
    if job is not None:
        try:
            self.root.after_cancel(job)
        except Exception:
            pass
    self._tab8_play_job = None
    if update_button:
        try:
            self.pd_play_button.configure(text='PLAY')
        except Exception:
            pass


def _tab8_v7_set_frame(self, idx, user_action=False):
    """Set a valid frame index and refresh only Tab-8."""
    st = _tab8_v7_get_primary_stack(self)
    if st is None:
        return False
    n = int(st.shape[0])
    idx = max(0, min(int(idx), n - 1))
    try:
        self._tab8_programmatic = True
        self._tab8_frame_var.set(idx)
        self._tab8_frame_slider.set(idx)
    finally:
        self._tab8_programmatic = False
    _tab8_v7_frame_changed(self, idx)
    return True


def _tab8_v7_frame_changed(self, value=None):
    """Authoritative manual/playback frame callback; synchronizes Fig. 2 and Fig. 4–6."""
    st = _tab8_v7_get_primary_stack(self)
    if st is None:
        try:
            self._tab8_frame_label_var.set('Frame --/-- | Field = --')
            self._tab8_frame_slider.configure(from_=0, to=0, state='disabled')
        except Exception:
            pass
        return False

    n = int(st.shape[0])
    try: idx = int(round(float(value))) if value is not None else int(self._tab8_frame_var.get())
    except Exception: idx = 0
    idx = max(0, min(idx, n - 1))
    self._tab8_programmatic = True
    try: self._tab8_frame_var.set(idx)
    finally: self._tab8_programmatic = False

    self.pd_current_detections = [dict(d) for d in (getattr(self, 'pd_frame_detections', {}) or {}).get(idx, [])]
    self.pd_selected_detection = None
    self.pd_multi_selected = set()

    # If this frame was already analyzed, keep D_Fit synchronized with the current
    # threshold and do not require the user to click Analyze again.
    if bool(getattr(self, 'pd_dfit_var', None).get()) and self.pd_current_detections and idx in (getattr(self, 'pd_frame_detections', {}) or {}):
        try:
            _tab8_v7_run_dfit(self, idx, force=False)
            _tab8_v7_refresh_density_row(self, idx)
            _tab8_v7_refresh_table(self)
        except Exception:
            pass

    _tab8_v7_refresh_all_figures(self)

    try:
        field = _tab8_v7_get_field(self, idx)
        ftxt = f'{field:+.2f} mT' if np.isfinite(field) else 'Field = --'
        self._tab8_frame_label_var.set(f'Frame {idx+1}/{n} | {ftxt}')
    except Exception:
        pass
    return True

def _tab8_v7_refresh_image(self):
    """Refresh the two image panels while preserving fixed physical FOV."""
    primary = _tab8_v7_get_primary_stack(self)
    if primary is None:
        return False

    idx = max(0, min(int(self._tab8_frame_var.get()), primary.shape[0] - 1))
    pimg = np.asarray(primary[idx], dtype=float)

    sx, sy = getattr(self, '_tab8_fixed_scale', (None, None))
    if sx is None or sy is None:
        sx, sy = _tab8_v7_get_scale(self)
    if sx is None or sy is None:
        return False

    h, w = pimg.shape[:2]
    # Match the exact physical FOV of Tab 6 / Fig. 2 whenever available.
    # Do not derive the primary-panel extent from the resized output dimensions.
    pext = None
    try:
        tab6_ext = getattr(self, '_proc_full_physical_extent', None)
        if tab6_ext is not None:
            tx0, tx1, ty0, ty1 = map(float, tab6_ext)
            if tx1 > tx0 and ty1 > ty0:
                pext = (tx0, tx1, ty0, ty1)
    except Exception:
        pext = None
    if pext is None:
        pext = (0.0, w * float(sx), 0.0, h * float(sy))
    self._tab8_primary_xy_extent = pext

    try:
        self.pd_image_artist_gray.set_data(pimg)
        self.pd_image_artist_gray.set_extent(pext)
        try:
            self.pd_image_artist_gray.set_cmap(str(self.colormap_var.get() or 'gray'))
        except Exception:
            pass
        self.pd_ax_gray.set_autoscale_on(False)
        self.pd_ax_gray.set_xlim(*pext[:2])
        self.pd_ax_gray.set_ylim(*pext[2:])
        self.pd_ax_gray.set_aspect('equal', adjustable='box')
        self.pd_ax_gray.set_xlabel('X (nm)')
        self.pd_ax_gray.set_ylabel('Y (nm)')
        self.pd_ax_gray.set_title('Finalized Primary ROI', fontsize=10)
    except Exception:
        pass

    roi3 = _tab8_v7_get_roi3_stack(self)
    if roi3 is not None:
        rimg = _tab8_tv_analysis_frame(self, idx, preview=True)

        # ROI3 is a cropped analysis image. Its pixel coordinates (including
        # detections and Gaussian-fit centers) are LOCAL to the ROI3 crop.
        # Therefore keep ROI3's origin at (0, 0), but use the SAME physical
        # nm/pixel calibration as Tab 6 / Primary ROI1.
        #
        # Do NOT use the ROI3 location inside Primary ROI1 as the ROI3 axis
        # origin; that would make the crop appear at e.g. X=400..1600 nm and
        # would put locally stored particle labels outside the image.
        rext = (
            0.0,
            float(rimg.shape[1]) * float(sx),
            0.0,
            float(rimg.shape[0]) * float(sy),
        )
        self._tab8_roi3_xy_extent = rext
        try:
            self.pd_image_artist_color.set_data(rimg)
            self.pd_image_artist_color.set_extent(rext)
            try:
                self.pd_image_artist_color.set_cmap(str(self.colormap_var.get() or 'viridis'))
            except Exception:
                pass
            self.pd_ax_color.set_autoscale_on(False)
            # Preserve ROI3 zoom while changing frames. The zoom is restricted
            # to the confirmed ROI3 image and remains in physical nm units.
            zoomed = bool(getattr(self, '_tab8_roi3_zoomed', False))
            zoom_limits = getattr(self, '_tab8_roi3_zoom_limits', None)
            if zoomed and zoom_limits is not None and getattr(self, '_tab8_roi3_confirmed', False):
                try:
                    (zx0, zx1), (zy0, zy1) = zoom_limits
                    zx0, zx1, zy0, zy1 = _tab8_v7_roi3_clamp_view(
                        rext, zx0, zx1, zy0, zy1
                    )
                    self.pd_ax_color.set_xlim(zx0, zx1)
                    self.pd_ax_color.set_ylim(zy0, zy1)
                    self._tab8_roi3_zoom_limits = ((zx0, zx1), (zy0, zy1))
                except Exception:
                    self.pd_ax_color.set_xlim(rext[0], rext[1])
                    self.pd_ax_color.set_ylim(rext[2], rext[3])
                    self._tab8_roi3_zoomed = False
                    self._tab8_roi3_zoom_limits = None
            else:
                self.pd_ax_color.set_xlim(rext[0], rext[1])
                self.pd_ax_color.set_ylim(rext[2], rext[3])
                self._tab8_roi3_zoomed = False
                self._tab8_roi3_zoom_limits = None
            self.pd_ax_color.set_aspect('equal', adjustable='box')
            self.pd_ax_color.set_xlabel('X (nm)')
            self.pd_ax_color.set_ylabel('Y (nm)')
            self.pd_ax_color.set_title(_tab8_tv_roi_title(self), fontsize=10)
            self.pd_colorbar.update_normal(self.pd_image_artist_color)
            self.pd_colorbar.set_label('Intensity', fontsize=8)
        except Exception:
            pass
    else:
        self._tab8_roi3_xy_extent = None
        try:
            self.pd_image_artist_color.set_data(pimg)
            self.pd_image_artist_color.set_extent(pext)
            self.pd_ax_color.set_autoscale_on(False)
            self.pd_ax_color.set_xlim(*pext[:2])
            self.pd_ax_color.set_ylim(*pext[2:])
            self.pd_ax_color.set_aspect('equal', adjustable='box')
            self.pd_ax_color.set_xlabel('X (nm)')
            self.pd_ax_color.set_ylabel('Y (nm)')
            self.pd_ax_color.set_title('Primary ROI — select ROI', fontsize=10)
            self.pd_colorbar.update_normal(self.pd_image_artist_color)
            self.pd_colorbar.set_label('Intensity', fontsize=8)
        except Exception:
            pass

    _tab8_v7_draw_overlays(self)

    try:
        self.pd_canvas.draw_idle()
    except Exception:
        pass
    return True



def _tab8_v7_draw_overlays(self):
    """Redraw only Tab-8 overlays in the current physical coordinate system."""
    _tab8_v7_clear_artists(self, 'pd_geom_artists')
    _tab8_v7_clear_artists(self, 'pd_label_marker_artists')

    try:
        patch = getattr(self, '_tab8_roi3_patch', None)
        if patch is not None:
            patch.remove()
    except Exception:
        pass
    self._tab8_roi3_patch = None

    pext = _tab8_v7_primary_extent(self)
    sx, sy = getattr(self, '_tab8_fixed_scale', (None, None))
    if pext is None or sx is None or sy is None:
        return

    # ROI3 rectangle is always shown on the Primary ROI1 image.
    c = getattr(self, '_tab8_roi3_coords', None)
    if isinstance(c, dict):
        try:
            x0 = int(c['xmin']) * sx
            x1 = (int(c['xmax']) + 1) * sx
            y0 = int(c['ymin']) * sy
            y1 = (int(c['ymax']) + 1) * sy
            edge = 'lime' if getattr(self, '_tab8_roi3_confirmed', False) else 'red'
            self._tab8_roi3_patch = _tab8_roi_shape_patch(self, x0, x1, y0, y1, edge, c)
            self.pd_ax_gray.add_patch(self._tab8_roi3_patch)
        except Exception:
            self._tab8_roi3_patch = None

    roi3 = _tab8_v7_get_roi3_stack(self)
    if roi3 is None or getattr(self, '_tab8_marks_cleared', False):
        try:
            self.pd_canvas.draw_idle()
        except Exception:
            pass
        return

    dets = [
        dict(d) for d in (getattr(self, 'pd_current_detections', []) or [])
        if d.get('accepted', True)
    ]
    selected = set(getattr(self, 'pd_multi_selected', set()) or set())
    theta = np.linspace(0, 2 * np.pi, 180)

    for k, d in enumerate(dets):
        try:
            ox = float(d.get('outer_x', d.get('x', 0.0)))
            oy = float(d.get('outer_y', d.get('y', 0.0)))
            cx = float(d.get('x', ox))
            cy = float(d.get('y', oy))
            od = max(0.0, float(d.get('diameter_px', 0.0)))
            cd = max(0.0, float(d.get('core_diameter_px', 0.0)))
            ar = max(1.0, float(d.get('core_aspect_ratio', 1.0)))
            outer, = self.pd_ax_color.plot(
                (ox + od / 2 * np.cos(theta)) * sx,
                (oy + od / 2 * np.sin(theta)) * sy,
                color='yellow', lw=2.8 if k in selected else 1.8, zorder=20
            )
            self.pd_geom_artists.append(outer)
            if d.get('core_analysis_enabled',True):
                inner, = self.pd_ax_color.plot(
                    (cx + cd * ar / 2 * np.cos(theta)) * sx,
                    (cy + cd / 2 * np.sin(theta)) * sy,
                    color='lime', lw=2.2 if k in selected else 1.4, zorder=21
                )
                self.pd_geom_artists.append(inner)
            # Particle number labels are mandatory when D_Fit is ON,
            # even if the optional generic center/label overlay is disabled.
            dfit_enabled = bool(
                getattr(self, 'pd_dfit_var', None) is not None and self.pd_dfit_var.get()
            )
            show_label = bool(self.pd_show_centers_var.get()) or dfit_enabled
            if show_label:
                center, = self.pd_ax_color.plot(
                    [cx * sx], [cy * sy],
                    marker='o', ms=5.5, mfc='none', mec='lime', mew=1.6, zorder=22, clip_on=True
                )
                try:
                    vx0, vx1 = self.pd_ax_color.get_xlim()
                    vy0, vy1 = self.pd_ax_color.get_ylim()
                except Exception:
                    vx0, vx1, vy0, vy1 = 0.0, float('inf'), 0.0, float('inf')
                label = None
                lx, ly = cx * sx, cy * sy
                # Show labels only for particles whose centers are inside the
                # currently visible confirmed-ROI view. This prevents labels
                # from appearing outside the image when zoomed.
                if (min(vx0, vx1) <= lx <= max(vx0, vx1) and
                        min(vy0, vy1) <= ly <= max(vy0, vy1)):
                    label = self.pd_ax_color.text(
                        lx, ly, str(k + 1),
                        color='black', ha='center', va='center', fontsize=8,
                        fontweight='bold', clip_on=True,
                        bbox=dict(boxstyle='circle,pad=0.18', fc='yellow', ec='lime', lw=1.0),
                        zorder=23
                    )
                self.pd_label_marker_artists.append(center)
                if label is not None:
                    self.pd_label_marker_artists.append(label)
        except Exception:
            continue

    # D_Fit radial overlay on Fig. 2 / ROI — ANALYSIS.
    # Draw the 12 center-to-radial-gradient-edge rays for every detected particle.
    if bool(getattr(self, 'pd_dfit_var', None).get()):
        try:
            idx = int(self._tab8_frame_var.get())
            if idx in (getattr(self, 'pd_frame_detections', {}) or {}):
                # Ensure results exist even when D_Fit was enabled after analysis.
                data = list((getattr(self, 'pd_dfit_results', {}) or {}).get(idx, []) or [])
                if not data:
                    _tab8_v7_run_dfit(self, idx, force=True)
                    data = list((getattr(self, 'pd_dfit_results', {}) or {}).get(idx, []) or [])

                angle_colors = plt.cm.hsv(np.linspace(0.0, 1.0, 12, endpoint=False))
                segments=[];endpoints=[];ray_colors=[]
                for r in sorted(data, key=lambda q: int(q.get('particle_no', 0))):
                    cx = float(r.get('center_x_px', np.nan))
                    cy = float(r.get('center_y_px', np.nan))
                    if not (np.isfinite(cx) and np.isfinite(cy)):
                        continue
                    for j, m in enumerate(r.get('measurements', []) or []):
                        rr = float(m.get('radius_px', np.nan))
                        ang = float(m.get('angle_deg', np.nan))
                        if not (np.isfinite(rr) and np.isfinite(ang)):
                            continue
                        th = np.deg2rad(ang)
                        ex = (cx + rr*np.cos(th)) * sx
                        ey = (cy + rr*np.sin(th)) * sy
                        segments.append([(cx*sx,cy*sy),(ex,ey)])
                        endpoints.append((ex,ey));ray_colors.append(angle_colors[j%12])
                if segments:
                    from matplotlib.collections import LineCollection
                    rays=LineCollection(segments,colors=ray_colors,linewidths=1.,alpha=.9,zorder=24)
                    self.pd_ax_color.add_collection(rays)
                    endpoints=np.asarray(endpoints)
                    points=self.pd_ax_color.scatter(endpoints[:,0],endpoints[:,1],s=4.5**2,
                        facecolors='white',edgecolors=ray_colors,linewidths=1.,zorder=25)
                    self.pd_geom_artists.extend([rays,points])
        except Exception:
            pass

    try:
        self.pd_canvas.draw_idle()
    except Exception:
        pass


def _tab8_v7_normalize(self, image):
    """Stable normalization for Tab-8 detection, using finite pixels only."""
    z = np.asarray(image, dtype=float)
    if z.ndim != 2:
        raise ValueError(f'Expected a 2-D image, got shape {z.shape}.')
    finite = z[np.isfinite(z)]
    if finite.size == 0:
        return np.zeros_like(z, dtype=float)
    lo, hi = np.percentile(finite, [1.0, 99.0])
    if not np.isfinite(lo) or not np.isfinite(hi) or hi <= lo:
        lo = float(np.min(finite))
        hi = float(np.max(finite))
    if hi <= lo:
        return np.zeros_like(z, dtype=float)
    return np.clip((z - lo) / (hi - lo), 0.0, 1.0)


def _tab8_v7_compute_dfit_for_particle(self, image, particle):
    """Tab-10 D-Fit adopted by Tab-8 Blob Analysis.

    The original Tab-8 blob detector is unchanged.  This function only replaces
    the old D-Fit diameter/core-intensity calculation with the Tab-10 method:
    12 radial raw profiles -> optional Savitzky-Golay smoothing -> radial
    gradient edge detection -> 6 opposite-pair diameters -> mean +/- SD.
    """
    img = np.asarray(image, dtype=float)
    if img.ndim != 2 or img.size < 25:
        return None

    sx, sy = getattr(self, '_tab8_fixed_scale', (1.0, 1.0))
    sx = float(sx) if np.isfinite(sx) and sx > 0 else 1.0
    sy = float(sy) if np.isfinite(sy) and sy > 0 else 1.0

    cx = float(particle.get('x', particle.get('outer_x', np.nan)))
    cy = float(particle.get('y', particle.get('outer_y', np.nan)))
    if not (np.isfinite(cx) and np.isfinite(cy)):
        return None

    try:
        sg_level = int(np.clip(round(float(self.pd_dfit_sg_level_var.get())), 0, 30))
    except Exception:
        sg_level = 0

    h, w = img.shape
    cx = float(np.clip(cx, 0, w - 1))
    cy = float(np.clip(cy, 0, h - 1))

    det_diam = float(particle.get(
        'diameter_px', particle.get('feret_diameter_px', 20.0)
    ))
    if not np.isfinite(det_diam) or det_diam <= 0:
        det_diam = 20.0

    # Local radial search window, with enough room beyond the detected blob.
    rr = max(8.0, 1.20 * det_diam)
    max_r = min(
        1.80 * rr,
        cx, cy,
        (w - 1.0) - cx,
        (h - 1.0) - cy
    )
    if not np.isfinite(max_r) or max_r < 3.0:
        return None

    t_px = np.linspace(0.0, float(max_r), 800, dtype=float)
    angles = [float(a) for a in np.arange(0.0, 360.0, 30.0)]
    radians = np.deg2rad(angles)
    cosines, sines = np.cos(radians), np.sin(radians)
    if (getattr(self, '_tab8_roi3_coords', None) or {}).get('shape') in ('Circle','Square'):
        import weakref
        support_cache = getattr(self,'_tab8_dfit_support_cache',None)
        if support_cache is None or support_cache[0]() is not img:
            support=np.isfinite(img).astype(float)
            support_cache=(weakref.ref(img),support,bool(support.all()))
            self._tab8_dfit_support_cache=support_cache
        if not support_cache[2]:
            supported=map_coordinates(support_cache[1],
                [cy+sines[:,None]*t_px, cx+cosines[:,None]*t_px],
                order=1,mode='constant',cval=0.)
            bad=np.flatnonzero(~np.all(supported>=1.-1e-6,axis=0))
            if bad.size: t_px=t_px[:int(bad[0])]
            if t_px.size<5 or t_px[-1]<3.: return None
    sampled=map_coordinates(img,
        [cy+sines[:,None]*t_px,cx+cosines[:,None]*t_px],order=1,mode='nearest')
    profiles={angle:sampled[i] for i,angle in enumerate(angles)
              if np.count_nonzero(np.isfinite(sampled[i]))>=5}

    if len(profiles) < 8:
        return None

    # Raw average line profile supplies the raw core intensity exactly as in
    # Tab-10; it is NOT used as a threshold.
    stack = np.vstack([
        np.asarray(profiles[a], dtype=float) for a in angles if a in profiles
    ])
    avg_raw = np.nanmean(stack, axis=0)

    use_threshold = bool(self.pd_dfit_threshold_mode_var.get()) and bool(self.pd_dfit_var.get())
    if use_threshold:
        try:
            dfit_threshold = float(np.clip(float(self.pd_dfit_threshold_var.get()), 0.00, 1.00))
        except Exception:
            dfit_threshold = 0.50
        dfit = _tab10_11_dfit_from_profiles(
            profiles, t_px, sx=sx, sy=sy, threshold=dfit_threshold,
            average_profile=avg_raw, sg_level=sg_level
        )
    else:
        dfit = _tab10_gradient_dfit_from_profiles(
            profiles, t_px, sx=sx, sy=sy, sg_level=sg_level,
            average_profile=avg_raw
        )
    if dfit is None:
        return None

    measurements = []
    for m in dfit.get('measurements', []):
        rr_nm = float(m.get('radius_nm', np.nan))
        ang = float(m.get('angle_deg', np.nan))
        if np.isfinite(rr_nm) and np.isfinite(ang):
            step_nm = float(np.hypot(
                sx*np.cos(np.deg2rad(ang)),
                sy*np.sin(np.deg2rad(ang))
            ))
            rr_px = rr_nm / step_nm if step_nm > 0 else np.nan
        else:
            rr_px = np.nan

        q = dict(m)
        q['particle_no'] = None
        q['radius_px'] = float(rr_px) if np.isfinite(rr_px) else np.nan
        q['diameter_px'] = float(2.0*rr_px) if np.isfinite(rr_px) else np.nan
        q['diameter_nm'] = (
            float(2.0*rr_nm) if np.isfinite(rr_nm) else np.nan
        )
        measurements.append(q)

    return {
        'particle_no': None,
        'center_x_px': cx,
        'center_y_px': cy,
        'measurements': measurements,
        'pair_measurements': dfit.get('pair_measurements', []),
        'avg_dia_nm': float(dfit.get('avg_diameter_nm', np.nan)),
        'sd_nm': float(dfit.get('sd_diameter_nm', np.nan)),
        'core_intensity': float(particle.get('core_intensity', np.nan)),
        # Spatial core-pixel SD, not an uncertainty of the fitted diameter.
        'core_intensity_sd': float(particle.get('core_intensity_sd', np.nan)),
        'valid_count': int(dfit.get('valid_count', 0)),
        'sg_level': int(dfit.get('sg_level', sg_level)),
        'sg_window_points': int(dfit.get('sg_window_points', 0)),
        'diameter_method': dfit.get(
            'diameter_method',
            '12 radial profiles; Savitzky-Golay-smoothed radial gradient edge; six opposite-pair diameters'
        ),
        'threshold_mode': bool(use_threshold),
        'threshold': float(dfit.get('threshold', np.nan)) if use_threshold else np.nan,
        'radial_profiles': dfit.get('radial_normalized_profiles', {}),
        'radial_smoothed_profiles': dfit.get('radial_smoothed_profiles', {}),
        'radial_gradient_profiles': dfit.get('radial_gradient_profiles', {}),
    }


def _tab8_v7_run_dfit(self, frame_idx=None, force=False):
    """Run the Tab-10 radial-gradient D-Fit for every accepted Tab-8 particle."""
    if frame_idx is None:
        frame_idx = int(self._tab8_frame_var.get())
    st = _tab8_v7_get_roi3_stack(self)
    if st is None:
        return {}
    frame_idx = max(0, min(frame_idx, st.shape[0] - 1))
    if not bool(self.pd_dfit_var.get()) and not force:
        return {}

    try:
        sg_level = int(np.clip(round(float(self.pd_dfit_sg_level_var.get())), 0, 30))
    except Exception:
        sg_level = 0
    try:
        self.pd_dfit_sg_level_var.set(sg_level)
        if hasattr(self, 'pd_dfit_sg_value_label'):
            self.pd_dfit_sg_value_label.configure(text=str(sg_level))
    except Exception:
        pass

    dets = [
        dict(d) for d in
        (getattr(self, 'pd_frame_detections', {}) or {}).get(frame_idx, [])
        if d.get('accepted', True)
    ]
    if frame_idx == int(self._tab8_frame_var.get()) and getattr(self, 'pd_current_detections', None):
        dets = [dict(d) for d in self.pd_current_detections if d.get('accepted', True)]

    import hashlib
    image = _tab8_tv_analysis_frame(self, frame_idx)
    signature = (hashlib.sha256(image.tobytes()).digest(),
                 tuple(getattr(self, '_tab8_fixed_scale', ())),
                 _tab8_analysis_signature(self), repr(dets))
    keys = getattr(self, '_tab8_dfit_cache_keys', {})
    if not force and keys.get(frame_idx) == signature and frame_idx in self.pd_dfit_results:
        return self.pd_dfit_results[frame_idx]
    out = []
    for i, d in enumerate(dets, 1):
        r = _tab8_v7_compute_dfit_for_particle(self, image, d)
        if r is not None:
            r['tv_denoise_enabled'], r['tv_weight'] = _tab8_tv_options(self)
            r['tv_scope'] = 'Selected ROI in source units; weight at original pixel scale'
            r['tv_sampling_factor'] = _tab8_tv_sampling_factor(self)
            r['tv_effective_weight'] = r['tv_weight']*r['tv_sampling_factor'] if r['tv_denoise_enabled'] else 0.
            r['particle_no'] = i
            for q in r.get('measurements', []):
                q['particle_no'] = i
            out.append(r)

    self.pd_dfit_results[frame_idx] = out
    keys[frame_idx] = signature
    self._tab8_dfit_cache_keys = keys
    return out




def _tab8_v7_dfit_threshold_changed(self):
    try:
        v = float(self.pd_dfit_threshold_var.get())
    except Exception:
        v = 0.50
    v = float(np.clip(v, 0.00, 1.00))
    self.pd_dfit_threshold_var.set(v)
    if bool(self.pd_dfit_var.get()):
        _tab8_v7_dfit_changed(self)
    else:
        try:
            self.pd_dfit_threshold_mode_var.set(False)
        except Exception:
            pass


def _tab8_v7_dfit_changed(self):
    """Recalculate analyzed Tab-8 frames when D-Fit or SG smoothing changes."""
    try:
        enabled = bool(self.pd_dfit_var.get())
    except Exception:
        enabled = False

    try:
        sg_level = int(np.clip(round(float(self.pd_dfit_sg_level_var.get())), 0, 30))
    except Exception:
        sg_level = 0
    try:
        self.pd_dfit_sg_level_var.set(sg_level)
        if hasattr(self, 'pd_dfit_sg_value_label'):
            self.pd_dfit_sg_value_label.configure(text=str(sg_level))
        state = 'normal' if enabled else 'disabled'
        if hasattr(self, 'pd_dfit_threshold_check'):
            self.pd_dfit_threshold_check.configure(state=state)
        if hasattr(self, 'pd_dfit_threshold_spin'):
            self.pd_dfit_threshold_spin.configure(state=(state if bool(self.pd_dfit_threshold_mode_var.get()) else 'disabled'))
    except Exception:
        pass

    if not enabled:
        getattr(self, 'pd_dfit_results', {}).clear()
        for idx in sorted((getattr(self, 'pd_frame_detections', {}) or {}).keys()):
            try:
                _tab8_v7_refresh_density_row(self, int(idx))
            except Exception:
                pass
        self.pd_status_var.set('D_Fit OFF — standard particle-size analysis retained.')
        _tab8_v7_refresh_all_figures(self)
        return

    analyzed = sorted((getattr(self, 'pd_frame_detections', {}) or {}).keys())
    for idx in analyzed:
        try:
            _tab8_v7_run_dfit(self, int(idx), force=True)
            _tab8_v7_refresh_density_row(self, int(idx))
        except Exception as exc:
            try:
                self.pd_status_var.set(
                    f'D_Fit warning on frame {int(idx)+1}: '
                    f'{type(exc).__name__}: {exc}'
                )
            except Exception:
                pass

    _tab8_v7_refresh_table(self)
    _tab8_v7_refresh_all_figures(self)
    self.pd_status_var.set(
        f'D_Fit ON — Savitzky–Golay filter = {sg_level}; '
        f'analyzed {len(analyzed)} frame(s).'
    )


def _tab8_v7_refresh_all_figures(self):
    """Refresh Fig. 3–6 and the Fig. 2 D_Fit overlay from one place.

    D_Fit ON:
      Fig. 3 = particle count/density vs field
      Fig. 4 = 12-angle D_Fit radial-gradient diameters (current frame)
      Fig. 5 = D_Fit Avg. Dia ± SD vs field for analyzed frames
      Fig. 6 = current-frame Particle No. vs D_Fit Avg. Dia ± SD

    D_Fit OFF:
      Fig. 3 remains count/density;
      Fig. 4 is explicitly disabled/empty;
      Fig. 5/6 show the standard particle-size result.
    """
    summary_key=(repr(getattr(self,'pd_results',{})),bool(self.pd_dfit_var.get()))
    if getattr(self,'_tab8_summary_refresh_key',None)!=summary_key:
        try:
            _tab8_v7_plot(self)
            self._tab8_summary_refresh_key=summary_key
        except Exception:
            pass
    try:
        _tab8_v7_plot_dfit(self)
    except Exception:
        pass
    try:
        _tab8_v7_particle_number_size_plot(self)
    except Exception:
        pass
    try:
        _tab8_v7_refresh_image(self)
    except Exception:
        pass

def _tab8_v7_plot_dfit(self):
    """Fig. 4: current-frame 12-angle D_Fit diameters."""
    ax = getattr(self, 'pd_dfit_ax', None)
    if ax is None:
        return

    ax.clear()
    ax.set_xlabel('Angle (deg)')
    ax.set_ylabel('D_Fit diameter (nm)')
    ax.grid(True, alpha=.2)
    ax.set_xticks(np.arange(0, 360, 30))
    ax.set_xlim(0, 330)

    enabled = bool(getattr(self, 'pd_dfit_var', None).get()) if getattr(self, 'pd_dfit_var', None) is not None else False
    idx = int(self._tab8_frame_var.get())

    if not enabled:
        ax.set_title('Fig. 4 — D_Fit radial diameter (OFF)', fontsize=10)
        ax.text(.5, .5, 'Enable D_Fit to display the 12 radial measurements.',
                ha='center', va='center', transform=ax.transAxes, fontsize=9)
        try:
            self.pd_canvas.draw_idle()
        except Exception:
            pass
        return

    # If the frame has already been analyzed but D_Fit results are missing,
    # compute them here so the plot cannot remain stale/empty after a frame change.
    data = list((getattr(self, 'pd_dfit_results', {}) or {}).get(idx, []) or [])
    if not data and idx in (getattr(self, 'pd_frame_detections', {}) or {}):
        try:
            _tab8_v7_run_dfit(self, idx, force=True)
            data = list((getattr(self, 'pd_dfit_results', {}) or {}).get(idx, []) or [])
        except Exception:
            data = []

    ax.set_title('Fig. 4 — D_Fit radial diameter', fontsize=10)
    if not data:
        ax.text(.5, .5, 'Analyze the current frame with D_Fit enabled.',
                ha='center', va='center', transform=ax.transAxes, fontsize=9)
        try:
            self.pd_canvas.draw_idle()
        except Exception:
            pass
        return

    any_curve = False
    for r in sorted(data, key=lambda q: int(q.get('particle_no', 0))):
        measurements = r.get('measurements', []) or []
        angles = np.asarray([float(m.get('angle_deg', np.nan)) for m in measurements], dtype=float)
        vals = np.asarray([float(m.get('diameter_nm', np.nan)) for m in measurements], dtype=float)
        good = np.isfinite(angles) & np.isfinite(vals)
        if not np.any(good):
            continue
        ax.plot(angles[good], vals[good], 'o-', lw=1.15, ms=3,
                label=f"P{int(r.get('particle_no', 0))}")
        any_curve = True

    if any_curve:
        ax.legend(loc='best', fontsize=7, ncol=2)
    else:
        ax.text(.5, .5, 'No valid radial-gradient edges were found.',
                ha='center', va='center', transform=ax.transAxes, fontsize=9)

    try:
        self.pd_canvas.draw_idle()
    except Exception:
        pass

def _tab8_size_scale(self):
    scale = getattr(self, '_tab8_fixed_scale', None)
    if scale is None or len(scale) != 2 or not np.isfinite(scale).all() or min(scale) <= 0:
        raise ValueError('nm controls require a valid Tab 6 X/Y calibration.')
    return float(np.sqrt(float(scale[0]) * float(scale[1])))


def _tab8_sensitivity_sync(self):
    if not hasattr(self, '_tab8_size_inputs') or getattr(self, '_tab8_size_syncing', False):
        return
    unit = self._tab8_size_unit
    try:
        factor = _tab8_size_scale(self)
        self.pd_size_units_combo.configure(values=('px', 'nm'))
    except ValueError:
        factor = 1.
        self.pd_size_units_combo.configure(values=('px',))
        unit = self._tab8_size_unit = 'px'
        self.pd_size_units_var.set('px')
    for name, variable in self._tab8_size_inputs.items():
        variable.set(format(float(getattr(self, name).get()) * (factor if unit == 'nm' else 1.), '.12g'))
    self.pd_size_calibration_var.set(
        f'X={self._tab8_fixed_scale[0]:.6g}, Y={self._tab8_fixed_scale[1]:.6g} nm/px; equivalent-area diameter'
        if getattr(self, '_tab8_fixed_scale', None) is not None and 'nm' in self.pd_size_units_combo['values']
        else 'Physical calibration unavailable')


def _tab8_apply_sizes(self):
    try:
        values = {name: float(getattr(self,name).get()) if ('core_' in name and not self.pd_core_analysis_var.get()) else float(variable.get()) for name, variable in self._tab8_size_inputs.items()}
        if not np.isfinite(list(values.values())).all():
            raise ValueError('Size values must be finite.')
        if min(values[n] for n in values if n != 'pd_min_sep_var') <= 0 or values['pd_min_sep_var'] < 0:
            raise ValueError('Diameters must be positive; separation must be nonnegative.')
        if values['pd_min_diam_var'] > values['pd_max_diam_var'] or values['pd_core_min_diam_var'] > values['pd_core_max_diam_var']:
            raise ValueError('Minimum diameter must not exceed maximum diameter.')
        snr, region = float(self.pd_min_snr_var.get()), float(self.pd_threshold_var.get())
        if not np.isfinite([snr, region]).all() or snr < 0 or not .01 <= region <= .99:
            raise ValueError('SNR must be nonnegative and region threshold 0.01-0.99.')
        if self.pd_detector_method_var.get() == 'Multiscale LoG':
            peak, count = float(self.pd_log_threshold_var.get()), int(self.pd_log_scales_var.get())
            if not np.isfinite(peak) or not .01 <= peak <= .99 or not 3 <= count <= 30:
                raise ValueError('LoG threshold must be 0.01-0.99 and scale count 3-30.')
        factor = _tab8_size_scale(self) if self._tab8_size_unit == 'nm' else 1.
    except (ValueError, tk.TclError) as exc:
        self.pd_status_var.set(f'Size controls: {exc}')
        return False
    self._tab8_size_syncing = True
    try:
        for name, value in values.items():
            getattr(self, name).set(value / factor)
    finally:
        self._tab8_size_syncing = False
    _tab8_sensitivity_sync(self)
    return True


def _tab8_size_units_changed(self):
    selected = self.pd_size_units_var.get()
    if not _tab8_apply_sizes(self):
        self.pd_size_units_var.set(self._tab8_size_unit)
        return False
    if selected == 'nm':
        try:
            _tab8_size_scale(self)
        except ValueError as exc:
            self.pd_size_units_var.set(self._tab8_size_unit)
            self.pd_status_var.set(str(exc))
            return False
    self._tab8_size_unit = selected
    _tab8_sensitivity_sync(self)
    _tab8_cancel_batch(self, status=False)
    return True


def _tab8_size_units_available(self):
    try:
        _tab8_size_scale(self)
        values = ('px', 'nm')
    except ValueError:
        values = ('px',)
    self.pd_size_units_combo.configure(values=values)


