    controls=ttk.Frame(advanced);controls.pack(fill='x')
    controls.columnconfigure(1,weight=1);controls.columnconfigure(3,weight=1)
    ttk.Label(controls,text='Minimum SNR').grid(row=0,column=0,sticky='w')
    ttk.Spinbox(controls,from_=0,to=30,increment=.5,textvariable=self.pd_min_snr_var,width=8).grid(
        row=0,column=1,sticky='ew',padx=3)
    self.pd_local_snr_check=ttk.Checkbutton(controls,text='Local background SNR',variable=self.pd_local_snr_var)
    self.pd_local_snr_check.grid(row=0,column=2,columnspan=2,sticky='w')
    ttk.Label(controls,text='LoG peak threshold').grid(row=1,column=0,sticky='w')
    self.pd_log_threshold_spin=ttk.Spinbox(controls,from_=.01,to=.99,increment=.01,
        textvariable=self.pd_log_threshold_var,width=8)
    self.pd_log_threshold_spin.grid(row=1,column=1,sticky='ew',padx=3)
    ttk.Label(controls,text='Scale count').grid(row=1,column=2,sticky='w')
    self.pd_log_scales_spin=ttk.Spinbox(controls,from_=3,to=30,increment=1,
        textvariable=self.pd_log_scales_var,width=8)
    self.pd_log_scales_spin.grid(row=1,column=3,sticky='ew',padx=3)
