def _tab6_build_exact_processed_primary_stack(self):
    """
    Build/read the exact Primary ROI1 stack represented by Tab 6's
    ROI-processing display (_proc_image), not the merely resolution-improved
    roi_stack. The result is cached by the source/processing signature.
    """
    if getattr(self,'recons',None) is None:
        return None

    base=getattr(self,'roi_stack',None)
    local=getattr(self,'local_mask',None)
    if base is None or local is None:
        return None

    try:
        n=len(base)
        shape=tuple(np.asarray(base[0]).shape[:2]) if n else None
    except Exception:
        return None
    if n<=0 or shape is None:
        return None

    def _get(var,default):
        try:
            return var.get()
        except Exception:
            return default

    try:
        kind=str(_get(getattr(self,'filter_var',None),'None'))
    except Exception:
        kind='None'
    try:
        strength=float(_get(getattr(self,'strength_var',None),1.0))
    except Exception:
        strength=1.0
    try:
        contrast=float(_get(getattr(self,'contrast_var',None),1.0))
    except Exception:
        contrast=1.0
    try:
        brightness=float(_get(getattr(self,'brightness_var',None),0.0))
    except Exception:
        brightness=0.0

    if _intensity_raw(self):
        contrast, brightness = 1., 0.
    signature=(
        id(base),tuple(np.asarray(base).shape),
        id(local),tuple(np.asarray(local).shape),
        kind,round(strength,12),round(contrast,12),round(brightness,12),
        _component_normalization_signature(self), _native_config_key(self)
    )

    cached=getattr(self,'_tab6_exact_processed_primary_stack_cache',None)
    cached_sig=getattr(self,'_tab6_exact_processed_primary_stack_signature',None)
    if cached is not None and cached_sig==signature:
        return cached

    global _compute_batch_frames
    previous_batch = _compute_batch_frames
    _compute_batch_frames = max(n, previous_batch)
    try:
        processed=np.empty((n,)+shape,dtype=_intensity_dtype(self))
        for i in range(n):
            arr=np.asarray(_proc_image(self,i),dtype=_intensity_dtype(self))
            if arr.ndim!=2 or arr.shape!=shape:
                raise RuntimeError(
                    f'Tab 6 processed Primary ROI1 frame {i+1}/{n} '
                    f'has inconsistent shape {arr.shape}, expected {shape}.'
                )
            processed[i]=arr
    finally:
        _compute_batch_frames = previous_batch

    self._tab6_exact_processed_primary_stack_cache=processed
    self._tab6_exact_processed_primary_stack_signature=signature
    return processed





def _tab8_v7_sync_source(self, preserve_current=True):
    """
    Synchronize Tab 8 with the exact processed Primary ROI1 stack from Tab 6.
    Only Tab-8 cache/state is changed here.
    """
    try:
        if getattr(self, 'roi_stack', None) is None or getattr(self, 'recons', None) is None:
            raise RuntimeError('Processed Primary ROI1 is not available in Tab 6.')
        processed, scale, finalized_signature = _native_require_finalized(self)
        sx, sy = scale
        processed = np.asarray(processed, dtype=_intensity_dtype(self))
        if processed.ndim != 3 or processed.shape[0] < 1:
            raise RuntimeError(f'Invalid processed Primary ROI1 stack shape: {processed.shape}.')
    except Exception as exc:
        self._tab8_primary_stack = None
        self._tab8_primary_shape = None
        try:
            self._tab8_frame_slider.configure(from_=0, to=0, state='disabled')
        except Exception:
            pass
        self.pd_status_var.set(
            f'Tab 8 source unavailable: {type(exc).__name__}: {exc}'
        )
        self._tab8_fixed_scale = None
        _tab8_sensitivity_sync(self)
        return False

    n, h, w = map(int, processed.shape)
    old_idx = 0
    if preserve_current:
        try:
            old_idx = int(self._tab8_frame_var.get())
        except Exception:
            old_idx = 0
    old_idx = max(0, min(old_idx, n - 1))

    old_sig = getattr(self, '_tab8_source_geometry_signature', None)
    new_sig = (id(processed), n, h, w, round(float(sx), 12), round(float(sy), 12))
    geometry_changed = (
        old_sig is not None and
        (old_sig[2], old_sig[3], old_sig[4], old_sig[5]) !=
        (h, w, round(float(sx), 12), round(float(sy), 12))
    )
    source_changed = old_sig != new_sig
    if source_changed:
        self.pd_last_deleted = None
        _tab8_cancel_batch(self, status=False)
        self.pd_dfit_results = {}
        self._tab8_dfit_cache_keys = {}

    support = getattr(self, '_native_finalized_mask', None)
    self._tab8_primary_support = (np.asarray(support, dtype=bool).copy()
        if support is not None and np.shape(support) == (h, w) else None)
    self._tab8_primary_stack = processed
    self._tab8_primary_shape = (h, w)
    self._tab8_fixed_shape = (h, w)
    self._tab8_fixed_scale = (float(sx), float(sy))
    self._tab8_source_geometry_signature = new_sig
    self._tab8_primary_xy_extent = (0.0, w * float(sx), 0.0, h * float(sy))

    # Preserve ROI3 only when its pixel geometry remains valid. If Tab-6 output
    # geometry changes, old ROI3 coordinates cannot safely be reused.
    if geometry_changed:
        self._tab8_roi3_coords = None
        self._tab8_pending_roi3_coords = None
        self._tab8_roi3_stack = None
        self._tab8_roi3_shape = None
        self._tab8_roi3_xy_extent = None
        self._tab8_roi3_confirmed = False
        self.pd_results = {}
        self.pd_frame_detections = {}
        self.pd_current_detections = []
        self.pd_selected_detection = None
        self.pd_multi_selected = set()
    elif source_changed:
        self.pd_results = {}
        self.pd_frame_detections = {}
        self.pd_current_detections = []
        self.pd_selected_detection = None
        self.pd_multi_selected = set()
    if not geometry_changed and isinstance(getattr(self, '_tab8_roi3_coords', None), dict):
        c = self._tab8_roi3_coords
        try:
            x0, x1 = int(c['xmin']), int(c['xmax'])
            y0, y1 = int(c['ymin']), int(c['ymax'])
            valid = 0 <= x0 < x1 < w and 0 <= y0 < y1 < h
        except Exception:
            valid = False
        if valid:
            self._tab8_roi3_stack = self._tab8_primary_stack[:, y0:y1 + 1, x0:x1 + 1].copy()
            _tab8_roi_apply_shape(self)
            self._tab8_roi3_shape = self._tab8_roi3_stack.shape[1:3]
            self._tab8_roi3_xy_extent = (
                0.0, (x1 - x0 + 1) * float(sx),
                0.0, (y1 - y0 + 1) * float(sy)
            )
        else:
            self._tab8_roi3_coords = None
            self._tab8_pending_roi3_coords = None
            self._tab8_roi3_stack = None
            self._tab8_roi3_shape = None
            self._tab8_roi3_xy_extent = None
            self._tab8_roi3_confirmed = False
            self.pd_results = {}
            self.pd_frame_detections = {}
            self.pd_current_detections = []

    self._tab8_programmatic = True
    try:
        self._tab8_frame_slider.configure(
            from_=0, to=n - 1, resolution=1,
            variable=self._tab8_frame_var, state='normal'
        )
        self.pd_range_start_spin.configure(from_=1, to=n)
        self.pd_range_end_spin.configure(from_=1, to=n)
        self.pd_range_start_var.set(max(1, min(int(self.pd_range_start_var.get()), n)))
        self.pd_range_end_var.set(max(1, min(int(self.pd_range_end_var.get()), n)))
        self._tab8_frame_var.set(old_idx)
        self._tab8_frame_slider.set(old_idx)
    finally:
        self._tab8_programmatic = False

    if not getattr(self, '_tab8_slider_initialized', False):
        # Start at the middle frame only once; thereafter preserve the user's frame.
        mid = (n - 1) // 2
        self._tab8_programmatic = True
        try:
            self._tab8_frame_var.set(mid)
            self._tab8_frame_slider.set(mid)
            old_idx = mid
        finally:
            self._tab8_programmatic = False
        self._tab8_slider_initialized = True

    _tab8_v7_frame_changed(self, old_idx)
    self.pd_status_var.set(
        f'✓ Exact processed Primary ROI1 from Tab 6 | '
        f'FOV = {w * sx:.6g} × {h * sy:.6g} nm | Frame {old_idx + 1}/{n}'
    )
    _tab8_sensitivity_sync(self)
    return True




def _tab8_v7_play(self):
    st = _tab8_v7_get_primary_stack(self)
    if st is None or st.shape[0] <= 1:
        self.pd_status_var.set('PLAY requires at least two source frames.')
        return False
    if self._tab8_playing:
        return True
    self._tab8_playing = True
    try:
        self.pd_play_button.configure(text='PLAYING…')
        self.pd_pause_button.configure(state='normal')
    except Exception:
        pass
    _tab8_v7_play_step(self)
    return True


def _tab8_v7_play_step(self):
    if not getattr(self, '_tab8_playing', False):
        return
    st = _tab8_v7_get_primary_stack(self)
    if st is None:
        _tab8_v7_stop_playback(self)
        return
    n = int(st.shape[0])
    idx = int(self._tab8_frame_var.get())
    next_idx = idx + 1
    if next_idx >= n:
        next_idx = 0
    _tab8_v7_set_frame(self, next_idx, user_action=True)

    try:
        fps = max(1, min(60, int(self.pd_fps_var.get())))
    except Exception:
        fps = 10
    delay = max(15, int(round(1000.0 / fps)))
    try:
        self._tab8_play_job = self.root.after(delay, lambda: _tab8_v7_play_step(self))
    except Exception:
        self._tab8_play_job = None
        self._tab8_playing = False


def _tab8_v7_pause(self):
    _tab8_v7_stop_playback(self, update_button=True)
    self.pd_status_var.set(f'PAUSED at frame {int(self._tab8_frame_var.get()) + 1}.')


def _tab8_v7_first(self):
    _tab8_v7_stop_playback(self, update_button=True)
    _tab8_v7_set_frame(self, 0)
    self.pd_status_var.set('Moved to first frame.')


def _tab8_v7_previous(self):
    _tab8_v7_stop_playback(self, update_button=True)
    idx = max(0, int(self._tab8_frame_var.get()) - 1)
    _tab8_v7_set_frame(self, idx)


def _tab8_v7_next(self):
    _tab8_v7_stop_playback(self, update_button=True)
    st = _tab8_v7_get_primary_stack(self)
    if st is not None:
        _tab8_v7_set_frame(self, min(st.shape[0] - 1, int(self._tab8_frame_var.get()) + 1))


@_auto_open_export
def _tab8_v7_export_table(self):
    if getattr(self, '_tab8_batch_busy', False):
        self.pd_status_var.set('Finish or cancel analysis before exporting.')
        return False
    if not getattr(self, 'pd_results', None):
        messagebox.showwarning('Tab 8', 'No analyzed-frame results available.', parent=self.root)
        return False
    fp = filedialog.asksaveasfilename(parent=self.root, initialdir=self._export_initialdir(),
        title='Export Tab 8 table', defaultextension='.csv', filetypes=[('CSV', '*.csv')])
    if not fp:
        return False
    cols = ['Frame No.', 'Field (mT)', 'Avg. Dia (nm)', 'SD (nm)', 'Supported ROI area (um2)',
            'Density (particles/um2)', 'Blob/Particle Count', 'Avg. Core Intensity',
            'SD of Core Intensity']
    rows = [list(self.pd_results[k][:9]) for k in sorted(self.pd_results)
            if isinstance(self.pd_results[k], (tuple, list)) and len(self.pd_results[k]) >= 9]
    summary = pd.DataFrame(rows, columns=cols)
    summary.insert(0, 'Frame_Index', summary['Frame No.'].astype(int)-1)
    geometry = getattr(self, '_tab8_roi3_coords', None) or {}
    summary['TV_Denoise'] = _tab8_tv_options(self)[0]
    summary['TV_Weight'] = _tab8_tv_options(self)[1] if _tab8_tv_options(self)[0] else 0.
    summary['TV_Sampling_Factor'] = _tab8_tv_sampling_factor(self)
    summary['TV_Effective_Weight'] = summary['TV_Weight']*summary['TV_Sampling_Factor']
    summary['TV_Weight_Reference'] = 'Original reconstruction pixel; affine 1-99 percentile ROI signal range'
    summary['ROI_Shape'] = geometry.get('shape', 'Square')
    summary['ROI_Geometry'] = repr(geometry)
    summary['Intensity_Method'] = ('Signed TV-denoised selected-ROI core mean minus local annular median' if _tab8_tv_options(self)[0] else 'Signed processed-source core mean minus local annular median')
    summary['Core_SD_Definition'] = 'Across accepted particle means; not fit uncertainty'
    particles = []
    for idx, detections in sorted(self.pd_frame_detections.items()):
        for number, detection in enumerate(detections, 1):
            row = {k:v for k,v in detection.items()
                   if v is None or isinstance(v, (str, bool, int, float, np.generic))}
            row.update(Frame_Index=idx, Frame=idx+1, Field_mT=_tab8_v7_get_field(self, idx),
                       Particle_No=number, Core_SD_Definition='Spatial core-pixel SD, not standard error')
            row.update(ROI_Shape=geometry.get('shape', 'Square'), ROI_Geometry=repr(geometry))
            particles.append(row)
    detail = pd.DataFrame(particles) if particles else pd.DataFrame(
        columns=['Frame_Index', 'Frame', 'Field_mT', 'Particle_No', 'core_intensity'])
    companion = Path(fp).with_name(Path(fp).stem + '_Particles.csv')
    try:
        _export_capture_write(summary.to_csv, fp, index=False)
        _export_capture_write(detail.to_csv, companion, index=False)
        for name in ('DFitParticles', 'DFitEdges'):
            _export_capture_write(_tab8_complete_export_tables(self)[name].to_csv, Path(fp).with_name(Path(fp).stem+'_'+name+'.csv'), index=False)
        self.pd_status_var.set(f'Exported summary, particles and all-frame D-fit measurements: {Path(fp).name}')
        return True
    except Exception as exc:
        _export_error_dialog(messagebox.showerror, 'Tab 8 Export', str(exc), parent=self.root)
        return False




@_auto_open_export
def _tab8_v7_export_figure5_csv(self):
    if getattr(self, '_tab8_batch_busy', False):
        self.pd_status_var.set('Finish or cancel analysis before exporting.')
        return False
    if not getattr(self,'pd_results',None): messagebox.showwarning('Tab 8','No analyzed data available.',parent=self.root); return False
    fp=filedialog.asksaveasfilename(parent=self.root,initialdir=self._export_initialdir(),title='Export Fig. 3–6 data',defaultextension='.csv',filetypes=[('CSV','*.csv')])
    if not fp:return False
    try:
        with _export_capture_stream(open, fp, 'w', newline='', encoding='utf-8-sig') as f:
            # Fig 3
            f.write('FIG. 3 DATA — Particle count/density vs field\n')
            fig3=[[self.pd_results[k][0],self.pd_results[k][1],self.pd_results[k][6],self.pd_results[k][5],self.pd_results[k][7],self.pd_results[k][8]] for k in sorted(self.pd_results) if len(self.pd_results[k])>=9]
            _export_capture_write(pd.DataFrame(fig3, columns=['Frame No.', 'Field (mT)', 'Blob/Particle Count', 'Density', 'Average Core Intensity', 'SD of Core Intensity']).to_csv, f, index=False)
            f.write('\nFIG. 4 DATA — D_Fit current frame\n')
            idx=int(self._tab8_frame_var.get()); records=[]
            for r in (getattr(self,'pd_dfit_results',{}) or {}).get(idx,[]):
                for m in r.get('measurements',[]): records.append([m.get('particle_no'),m.get('angle_deg'),m.get('radius_nm'),m.get('diameter_nm'),m.get('edge_strength'),m.get('edge_drop'),m.get('sg_window_points'),m.get('valid'),r.get('avg_dia_nm'),r.get('sd_nm'),r.get('core_intensity')])
            _export_capture_write(pd.DataFrame(records, columns=['Particle/Blob No.', 'Angle (deg)', 'Gradient-edge Radius (nm)', 'Diameter (nm)', 'Edge Strength', 'Edge Drop', 'SG Window (points)', 'Valid Edge', 'Avg. Dia (nm)', 'SD (nm)', 'Background-subtracted Core Intensity']).to_csv, f, index=False)
            f.write('\nFIG. 5 DATA — Selected frames\n')
            selected=[]
            for k in sorted(self.pd_results):
                row=self.pd_results[k]
                try: frame_no=int(row[0]); field=float(row[1]); avg_size=float(row[2]); sd=float(row[3])
                except Exception: continue
                dets=[d for d in (getattr(self,'pd_frame_detections',{}) or {}).get(int(k),[]) if d.get('accepted',True)]
                vals=np.asarray([d.get('core_intensity',np.nan) for d in dets],float); vals=vals[np.isfinite(vals)]
                core=float(np.mean(vals)) if vals.size else np.nan
                if bool(getattr(self,'pd_dfit_var',None) is not None and self.pd_dfit_var.get()):
                    rr=(getattr(self,'pd_dfit_results',{}) or {}).get(int(k),[])
                    rv=np.asarray([r.get('core_intensity',np.nan) for r in rr],float); rv=rv[np.isfinite(rv)]
                    if rv.size: core=float(np.mean(rv))
                core_sd=float(row[8]) if len(row)>=9 and np.isfinite(float(row[8])) else 0.0 if np.isfinite(core) else np.nan
                selected.append([frame_no,field,avg_size,sd,core,core_sd])
            _export_capture_write(pd.DataFrame(selected, columns=['Frame', 'Field (mT)', 'Avg. Particle Size', 'SD', 'Average Core Intensity', 'SD of Core Intensity']).to_csv, f, index=False)
            f.write('\nFIG. 6 DATA — Current frame\n')
            cur=[]
            rr_list=(getattr(self,'pd_dfit_results',{}) or {}).get(idx,[]) if bool(getattr(self,'pd_dfit_var',None) is not None and self.pd_dfit_var.get()) else []
            if rr_list:
                for r in sorted(rr_list,key=lambda q:int(q.get('particle_no',0))): cur.append([r.get('particle_no'),r.get('avg_dia_nm'),r.get('sd_nm'),r.get('core_intensity',np.nan),r.get('core_intensity_sd',0.0)])
            else:
                dets=sorted([d for d in (getattr(self,'pd_current_detections',[]) or []) if d.get('accepted',True)],key=lambda d:(float(d.get('y',0)),float(d.get('x',0))))
                scale=_tab8_v7_equiv_scale(self) or 1.0
                for i,d in enumerate(dets,1): cur.append([i,_tab8_standard_diameter(self, d),0.0,d.get('core_intensity',np.nan),d.get('core_intensity_sd',np.nan)])
            _export_capture_write(pd.DataFrame(cur, columns=['Particle No.', 'Avg. Particle Size', 'SD', 'Average Core Intensity', 'SD of Core Intensity']).to_csv, f, index=False)
        for name, table in _tab8_complete_export_tables(self).items():
            _export_capture_write(table.to_csv, Path(fp).with_name(Path(fp).stem+'_'+name+'.csv'), index=False)
        self.pd_status_var.set(f'Exported Fig. 3–6 data and four rectangular CSV tables: {os.path.basename(fp)}'); return True
    except Exception as exc:
        _export_error_dialog(messagebox.showerror, 'Tab 8 Export', f'Could not export Fig. 3–6 CSV:\n\n{type(exc).__name__}: {exc}', parent=self.root); return False

@_auto_open_export
def _tab8_v7_export_image(self):
    """Export the current-frame Primary ROI and Confirmed ROI with analysis markers.

    Primary ROI export:
      - full Primary ROI image
      - Confirmed ROI boundary
      - center marker
      - particle number
      - NO outer-particle/core markers
      - NO D_Fit radial rays/crossing points

    Confirmed ROI export:
      - full Confirmed ROI image
      - outer-particle marker
      - inner-core marker
      - particle number
      - 12 D_Fit radial rays/crossing points when D_Fit is ON

    Detection coordinates are stored in Confirmed-ROI-local pixels.  The Primary
    ROI export therefore applies the confirmed-ROI (xmin, ymin) pixel offset.
    Both exports use the Tab-6 physical calibration and X/Y axes in nm.
    """
    if getattr(self, '_tab8_batch_busy', False):
        self.pd_status_var.set('Finish or cancel analysis before exporting.')
        return False
    primary = _tab8_v7_get_primary_stack(self)
    roi3 = _tab8_v7_get_roi3_stack(self)
    coords = getattr(self, '_tab8_roi3_coords', None)

    if primary is None:
        messagebox.showwarning(
            'Tab 8 Export',
            'Processed Primary ROI1 is not available.',
            parent=self.root
        )
        return False

    if roi3 is None or not isinstance(coords, dict):
        messagebox.showwarning(
            'Tab 8 Export',
            'Confirm ROI3 first. Both Primary ROI and Confirmed ROI exports require a confirmed ROI.',
            parent=self.root
        )
        return False

    sx, sy = getattr(self, '_tab8_fixed_scale', (None, None))
    if sx is None or sy is None:
        sx, sy = _tab8_v7_get_scale(self)
    if sx is None or sy is None or float(sx) <= 0 or float(sy) <= 0:
        messagebox.showwarning(
            'Tab 8 Export',
            'Tab 6 Measurement Scale is unavailable.',
            parent=self.root
        )
        return False
    sx, sy = float(sx), float(sy)

    idx = max(0, min(int(self._tab8_frame_var.get()), primary.shape[0] - 1))
    outdir = self._export_initialdir()
    if not outdir:
        return False
    os.makedirs(outdir, exist_ok=True)

    field = _tab8_v7_get_field(self, idx)
    field_tag = f'{field:+.2f}mT' if np.isfinite(field) else f'Frame{idx + 1:04d}'
    field_tag = field_tag.replace('+', 'p').replace('-', 'm')

    # Detections are stored in Confirmed-ROI-local pixel coordinates.
    dets = [
        dict(d) for d in (getattr(self, 'pd_current_detections', []) or [])
        if d.get('accepted', True)
    ]
    # If the current frame has stored detections but the display list is empty,
    # fall back to the frame-level detections.
    if not dets:
        dets = [
            dict(d) for d in (getattr(self, 'pd_frame_detections', {}) or {}).get(idx, [])
            if d.get('accepted', True)
        ]

    # Ensure the D_Fit data correspond to the current threshold and current frame.
    dfit_enabled = False
    try:
        dfit_enabled = bool(self.pd_dfit_var.get())
    except Exception:
        dfit_enabled = False

    dfit_data = []
    if dfit_enabled and dets:
        try:
            dfit_data = list((getattr(self, 'pd_dfit_results', {}) or {}).get(idx, []) or [])
            if not dfit_data:
                dfit_data = list(_tab8_v7_run_dfit(self, idx, force=True) or [])
        except Exception:
            dfit_data = []

    dfit_by_particle = {}
    for row in dfit_data:
        try:
            pno = int(row.get('particle_no'))
            dfit_by_particle[pno] = row
        except Exception:
            continue

    try:
        cmap = str(self.colormap_var.get() or 'gray')
    except Exception:
        cmap = 'gray'

    # Use the same physical Primary-ROI extent used by Tab 8 when available.
    pext = getattr(self, '_tab8_primary_xy_extent', None)
    if pext is None:
        try:
            tab6_ext = getattr(self, '_proc_full_physical_extent', None)
            if tab6_ext is not None:
                tx0, tx1, ty0, ty1 = map(float, tab6_ext)
                if tx1 > tx0 and ty1 > ty0:
                    pext = (tx0, tx1, ty0, ty1)
        except Exception:
            pext = None
    if pext is None:
        pext = (
            0.0,
            float(primary.shape[2]) * sx,
            0.0,
            float(primary.shape[1]) * sy
        )

    rext = (
        0.0,
        float(roi3.shape[2]) * sx,
        0.0,
        float(roi3.shape[1]) * sy
    )

    roi_x0 = int(coords.get('xmin', 0))
    roi_y0 = int(coords.get('ymin', 0))

    @_auto_open_export
    def save_png(
        arr,
        title,
        path,
        extent,
        x_offset_px=0,
        y_offset_px=0,
        draw_roi_boundary=False,
        draw_dfit=False,
        draw_particle_core=True,
    ):
        """Save one ROI image in physical nm coordinates with selected overlays."""
        a = np.asarray(arr, dtype=float)
        if a.ndim != 2:
            raise ValueError(f'Expected a 2-D image, got shape {a.shape}.')

        finite = a[np.isfinite(a)]
        if finite.size:
            lo = float(np.min(finite))
            hi = float(np.max(finite))
            if not np.isfinite(lo) or not np.isfinite(hi):
                lo, hi = 0.0, 1.0
            if hi <= lo:
                hi = lo + 1.0
        else:
            lo, hi = 0.0, 1.0

        fig = plt.Figure(figsize=(7.2, 6.4), dpi=300, facecolor='white')
        ax = fig.add_axes([0.11, 0.11, 0.72, 0.78])
        im = ax.imshow(
            a,
            origin='lower',
            extent=extent,
            interpolation='nearest',
            aspect='equal',
            cmap=cmap,
            vmin=lo,
            vmax=hi,
        )
        ax.set_xlim(extent[0], extent[1])
        ax.set_ylim(extent[2], extent[3])
        ax.set_aspect('equal', adjustable='box')
        ax.set_xlabel('X (nm)', fontsize=11)
        ax.set_ylabel('Y (nm)', fontsize=11)
        ax.set_title(title, fontsize=13, pad=7)
        ax.tick_params(labelsize=9)

        # Confirmed ROI boundary on the full Primary ROI only.
        if draw_roi_boundary:
            bx0 = roi_x0 * sx
            by0 = roi_y0 * sy
            bw = float(roi3.shape[2]) * sx
            bh = float(roi3.shape[1]) * sy
            ax.add_patch(
                _tab8_roi_shape_patch(self,bx0,bx0+bw,by0,by0+bh,edge='yellow',coords=coords)
            )

        # Particle/core markers and particle numbers.
        theta = np.linspace(0.0, 2.0 * np.pi, 240)
        for k, d in enumerate(dets, 1):
            try:
                # Confirmed-ROI-local detection coordinates -> output coordinates.
                ox = float(d.get('outer_x', d.get('x', 0.0))) + float(x_offset_px)
                oy = float(d.get('outer_y', d.get('y', 0.0))) + float(y_offset_px)
                cx = float(d.get('x', ox - float(x_offset_px))) + float(x_offset_px)
                cy = float(d.get('y', oy - float(y_offset_px))) + float(y_offset_px)
                od = max(
                    0.0,
                    float(d.get('diameter_px', d.get('feret_diameter_px', 0.0)))
                )
                cd = max(0.0, float(d.get('core_diameter_px', 0.0)))
                ar = max(1.0, float(d.get('core_aspect_ratio', 1.0)))

                # Outer particle and inner core markers are exported only
                # for the Confirmed ROI.
                if draw_particle_core:
                    ax.plot(
                        (ox + od / 2.0 * np.cos(theta)) * sx,
                        (oy + od / 2.0 * np.sin(theta)) * sy,
                        color='yellow',
                        lw=2.2,
                        zorder=20,
                        clip_on=True,
                    )
                    ax.plot(
                        (cx + cd * ar / 2.0 * np.cos(theta)) * sx,
                        (cy + cd / 2.0 * np.sin(theta)) * sy,
                        color='lime',
                        lw=1.8,
                        zorder=21,
                        clip_on=True,
                    )

                if not draw_particle_core:
                    # PRIMARY ROI ONLY:
                    # - yellow outline around the particle (not around the number)
                    # - small yellow center dot
                    # - particle number positioned below the center dot
                    # - black font, size 10, with a 0.5-thin yellow border and no fill
                    if od > 0:
                        ax.plot(
                            (ox + od / 2.0 * np.cos(theta)) * sx,
                            (oy + od / 2.0 * np.sin(theta)) * sy,
                            color='lime',
                            lw=1.0,
                            zorder=20,
                            clip_on=True,
                        )
                    ax.plot(
                        [cx * sx],
                        [cy * sy],
                        marker='o',
                        ms=2.0,
                        mfc='lime',
                        mec='none',
                        mew=0.2,
                        linestyle='None',
                        zorder=22,
                        clip_on=True,
                    )
                    ax.annotate(
                        str(k),
                        xy=(cx * sx, cy * sy),
                        xytext=(0, -5),
                        textcoords='offset points',
                        color='yellow',
                        ha='center',
                        va='top',
                        fontsize=6.0,
                        fontweight='bold',
                        clip_on=True,
                        bbox=dict(
                        boxstyle='square,pad=0.12',
                        facecolor='black',
                        edgecolor='black',
                        linewidth=0.2,
                        alpha=0.5,
                        ),
                        zorder=23,
                    )
                else:
                    # CONFIRMED ROI: retain the existing center-marker and number style.
                    ax.plot(
                        [cx * sx],
                        [cy * sy],
                        marker='o',
                        ms=5.0,
                        mfc='none',
                        mec='blue',
                        mew=1.5,
                        zorder=22,
                        clip_on=True,
                    )
                    ax.text(
                        cx * sx,
                        cy * sy,
                        str(k),
                        color='black',
                        ha='center',
                        va='center',
                        fontsize=8.0,
                        fontweight='bold',
                        clip_on=True,
                        bbox=dict(
                            boxstyle='circle,pad=0.18',
                            fc='yellow',
                            ec='lime',
                            lw=1.0,
                        ),
                        zorder=23,
                    )
            except Exception:
                continue

        # D_Fit is intentionally exported only on the Confirmed ROI image.
        if draw_dfit and dfit_enabled and dfit_by_particle:
            angle_colors = plt.cm.hsv(np.linspace(0.0, 1.0, 12, endpoint=False))
            for pno in sorted(dfit_by_particle):
                row = dfit_by_particle[pno]
                try:
                    cx = float(row.get('center_x_px', np.nan))
                    cy = float(row.get('center_y_px', np.nan))
                except Exception:
                    continue
                if not (np.isfinite(cx) and np.isfinite(cy)):
                    continue

                for j, meas in enumerate(row.get('measurements', []) or []):
                    try:
                        rr = float(meas.get('radius_px', np.nan))
                        ang = float(meas.get('angle_deg', np.nan))
                    except Exception:
                        continue
                    if not (np.isfinite(rr) and np.isfinite(ang)):
                        continue
                    th = np.deg2rad(ang)
                    ex = cx + rr * np.cos(th)
                    ey = cy + rr * np.sin(th)
                    col = angle_colors[j % 12]
                    ax.plot(
                        [cx * sx, ex * sx],
                        [cy * sy, ey * sy],
                        color=col,
                        lw=1.25,
                        alpha=0.90,
                        zorder=24,
                        clip_on=True,
                    )
                    ax.plot(
                        [ex * sx],
                        [ey * sy],
                        marker='o',
                        ms=4.8,
                        mfc='white',
                        mec=col,
                        mew=1.3,
                        zorder=25,
                        clip_on=True,
                    )

        cax = fig.add_axes([0.87, 0.11, 0.035, 0.78])
        cb = fig.colorbar(im, cax=cax)
        cb.set_label('Intensity', fontsize=10)
        cb.ax.tick_params(labelsize=8)

        _export_capture_write(fig.savefig, path, dpi=300, format='png', bbox_inches='tight', facecolor='white')
        plt.close(fig)

    primary_path = os.path.join(
        outdir,
        f'Tab8_PrimaryROI_Frame{idx + 1:04d}_{field_tag}.png'
    )
    confirmed_path = os.path.join(
        outdir,
        f'Tab8_ConfirmedROI_Frame{idx + 1:04d}_{field_tag}.png'
    )

    # 1) Full Primary ROI: markers are shifted from Confirmed-ROI-local
    # coordinates to Primary-ROI coordinates by (xmin, ymin).
    save_png(
        primary[idx],
        'PROCESSED PRIMARY ROI',
        primary_path,
        pext,
        x_offset_px=roi_x0,
        y_offset_px=roi_y0,
        draw_roi_boundary=True,
        draw_dfit=False,
        draw_particle_core=False,
    )

    # 2) Confirmed ROI: same particle/core markers + particle numbers,
    # plus D_Fit rays/crossings when D_Fit is ON.
    save_png(
        _tab8_tv_analysis_frame(self, idx),
        _tab8_tv_roi_title(self, 'CONFIRMED ROI'),
        confirmed_path,
        rext,
        x_offset_px=0,
        y_offset_px=0,
        draw_roi_boundary=False,
        draw_dfit=True,
        draw_particle_core=True,
    )

    self.pd_status_var.set(
        'Exported Primary (boundary + center + numbers) and Confirmed ROI at 300 DPI: '
        f'{os.path.basename(primary_path)}; {os.path.basename(confirmed_path)}'
    )

    try:
        _export_request_open(outdir)
    except Exception:
        try:
            _export_request_open(outdir)
        except Exception:
            pass
    return True


@_auto_open_export
def _tab8_v7_export_figure(self):
    if getattr(self, '_tab8_batch_busy', False):
        self.pd_status_var.set('Finish or cancel analysis before exporting.')
        return False
    if not getattr(self, 'pd_results', None):
        messagebox.showwarning('Tab 8', 'No analyzed-frame results available.', parent=self.root)
        return False
    fp = filedialog.asksaveasfilename(
        parent=self.root, initialdir=self._export_initialdir(),
        title='Export Tab 8 analysis graphs',
        defaultextension='.png',
        filetypes=[('PNG', '*.png')]
    )
    if not fp:
        return False
    try:
        _export_capture_write(self.pd_plot_fig.savefig, fp, dpi=300, bbox_inches='tight')
        self.pd_status_var.set(f'Exported analysis graphs: {os.path.basename(fp)}')
        return True
    except Exception as exc:
        _export_error_dialog(messagebox.showerror, 'Tab 8 Export', f'Could not export analysis graphs:\n\n{type(exc).__name__}: {exc}', parent=self.root)
        return False


def _tab8_v7_reset_tab_state(self):
    """Reset Tab 8 in place; do not create or remove notebook tabs."""
    _analysis_progress_update(self, 8, 0)
    _tab8_v7_stop_playback(self, update_button=True)
    self._tab8_roi3_coords = None
    self._tab8_pending_roi3_coords = None
    self._tab8_roi3_stack = None
    self._tab8_roi3_shape = None
    self._tab8_roi3_xy_extent = None
    self._tab8_roi3_confirmed = False
    self._tab8_roi3_select_mode = False
    self._tab8_roi3_dragging = False
    self._tab8_roi3_start = None
    self._tab8_clear_display = False
    self._tab8_marks_cleared = False
    self.pd_results = {}
    self.pd_frame_detections = {}
    self.pd_current_detections = []
    self.pd_selected_detection = None
    self.pd_multi_selected = set()
    self.pd_last_deleted = None
    self.pd_add_blob_mode = False
    self.pd_min_snr_var.set(5.)
    self.pd_split_touching_var.set(False)
    self.pd_dfit_results = {}
    self._tab8_roi_shape = 'Square'
    self.pd_rectangle_roi_var.set(True)
    self.pd_circle_roi_var.set(False)
    self.pd_circle_diameter_var.set(500.)
    self.pd_circle_diameter_entry.configure(state='normal')
    self.pd_circle_diameter_button.configure(state='normal')
    self._tab8_detection_diagnostics = {}
    self.pd_detection_diagnostics_var.set('Detection diagnostics: analyze a frame.')
    _tab8_v7_restore_default_controls(self)

    primary = _tab8_v7_get_primary_stack(self)
    if primary is not None:
        self.pd_range_start_var.set(1)
        self.pd_range_end_var.set(int(primary.shape[0]))
        _tab8_v7_set_frame(self, int((primary.shape[0] - 1) // 2))
    _tab8_v7_refresh_table(self)
    _tab8_v7_plot(self, empty_message='Tab 8 reset — select ROI3 and analyze frames.')
    _tab8_v7_particle_number_size_plot(self)
    _tab8_v7_refresh_image(self)
    self.pd_status_var.set('TAB 8 RESET complete. Processed Primary ROI1 from Tab 6 retained.')
    return True



def _tab8_v7_roi3_full_extent(self):
    """Full confirmed-ROI3 physical extent in nm."""
    ext = getattr(self, '_tab8_roi3_xy_extent', None)
    if ext is None:
        try:
            ext = _tab8_v7_roi3_extent(self)
        except Exception:
            ext = None
    if ext is None:
        return None
    try:
        x0, x1, y0, y1 = map(float, ext)
        if x1 <= x0 or y1 <= y0:
            return None
        return (x0, x1, y0, y1)
    except Exception:
        return None


def _tab8_v7_roi3_clamp_view(full, x0, x1, y0, y1):
    fx0, fx1, fy0, fy1 = map(float, full)
    fw = max(fx1 - fx0, 1e-12)
    fh = max(fy1 - fy0, 1e-12)
    vw = min(max(x1 - x0, fw * 0.02), fw)
    vh = min(max(y1 - y0, fh * 0.02), fh)

    # Recenter if the requested viewport is larger than the full extent.
    if vw >= fw:
        x0, x1 = fx0, fx1
    else:
        x0 = min(max(x0, fx0), fx1 - vw)
        x1 = x0 + vw

    if vh >= fh:
        y0, y1 = fy0, fy1
    else:
        y0 = min(max(y0, fy0), fy1 - vh)
        y1 = y0 + vh
    return (x0, x1, y0, y1)


def _tab8_v7_roi3_apply_view(self, x0=None, x1=None, y0=None, y1=None, redraw=True):
    """Apply a zoom view ONLY to the confirmed ROI3 image (pd_ax_color)."""
    ax = getattr(self, 'pd_ax_color', None)
    canvas = getattr(self, 'pd_canvas', None)
    full = _tab8_v7_roi3_full_extent(self)

    if ax is None or full is None or not getattr(self, '_tab8_roi3_confirmed', False):
        return False

    if None in (x0, x1, y0, y1):
        x0, x1, y0, y1 = full

    x0, x1, y0, y1 = _tab8_v7_roi3_clamp_view(full, float(x0), float(x1), float(y0), float(y1))
    fx0, fx1, fy0, fy1 = full

    zoomed = (
        (x1 - x0) < 0.999999 * (fx1 - fx0) or
        (y1 - y0) < 0.999999 * (fy1 - fy0)
    )

    ax.set_autoscale_on(False)
    ax.set_xlim(x0, x1)
    ax.set_ylim(y0, y1)
    ax.set_aspect('equal', adjustable='box')
    ax.set_xlabel('X (nm)')
    ax.set_ylabel('Y (nm)')
    self._tab8_roi3_zoomed = bool(zoomed)
    self._tab8_roi3_zoom_limits = ((x0, x1), (y0, y1)) if zoomed else None

    if redraw and canvas is not None:
        try:
            canvas.draw_idle()
        except Exception:
            pass
    return True


def _tab8_v7_roi3_zoom(self, factor, center_x=None, center_y=None):
    """Zoom ONLY the confirmed ROI3 image around the supplied physical point."""
    full = _tab8_v7_roi3_full_extent(self)
    if full is None or not getattr(self, '_tab8_roi3_confirmed', False):
        try:
            self.pd_status_var.set('Confirm ROI before using ROI zoom.')
        except Exception:
            pass
        return False

    ax = getattr(self, 'pd_ax_color', None)
    if ax is None:
        return False

    try:
        x0, x1 = map(float, ax.get_xlim())
        y0, y1 = map(float, ax.get_ylim())
    except Exception:
        x0, x1, y0, y1 = full

    if center_x is None or center_y is None:
        center_x = 0.5 * (x0 + x1)
        center_y = 0.5 * (y0 + y1)

    factor = float(factor)
    if factor <= 0:
        factor = 1.0

    # factor < 1 => zoom in; factor > 1 => zoom out.
    new_w = (x1 - x0) * factor
    new_h = (y1 - y0) * factor
    nx0 = float(center_x) - 0.5 * new_w
    nx1 = float(center_x) + 0.5 * new_w
    ny0 = float(center_y) - 0.5 * new_h
    ny1 = float(center_y) + 0.5 * new_h
    return _tab8_v7_roi3_apply_view(self, nx0, nx1, ny0, ny1)


def _tab8_v7_roi3_zoom_in(self):
    return _tab8_v7_roi3_zoom(self, 1.0 / 1.25)


def _tab8_v7_roi3_zoom_out(self):
    return _tab8_v7_roi3_zoom(self, 1.25)


def _tab8_v7_roi3_zoom_reset(self):
    full = _tab8_v7_roi3_full_extent(self)
    if full is None or not getattr(self, '_tab8_roi3_confirmed', False):
        return False
    return _tab8_v7_roi3_apply_view(self, *full)


def _tab8_v7_roi3_zoom_scroll(self, event):
    """Mouse-wheel zoom for ROI3 image only; all other Tab-8 plots are ignored."""
    try:
        if getattr(event, 'inaxes', None) is not self.pd_ax_color:
            return
        if not getattr(self, '_tab8_roi3_confirmed', False):
            return
        step = getattr(event, 'step', 0)
        if step == 0:
            if getattr(event, 'button', None) == 'up':
                step = 1
            elif getattr(event, 'button', None) == 'down':
                step = -1
        factor = (1.0 / 1.2) if step > 0 else (1.2 if step < 0 else 1.0)
        if factor != 1.0:
            _tab8_v7_roi3_zoom(
                self, factor,
                getattr(event, 'xdata', None),
                getattr(event, 'ydata', None)
            )
            return 'break'
    except Exception:
        pass
    return None

