    # Use a per-section row counter so every section remains independent.
    _section_state = {'frame': None, 'row': 0, 'col': 0}

    def _begin_parameter_section(parent=None):
        frame = ttk.Frame(detbox if parent is None else parent)
        frame.pack(fill='x', pady=(1, 2))
        frame.columnconfigure(0, weight=1)
        frame.columnconfigure(1, weight=1)
        _section_state.update(frame=frame, row=0, col=0)

    def scl(label, var, lo, hi, res):
        frame = _section_state['frame']
        row = _section_state['row']
        col = _section_state['col']

        cell = ttk.Frame(frame)
        cell.grid(
            row=row,
            column=col,
            sticky='ew',
            padx=(0, 5) if col == 0 else (5, 0),
            pady=(1, 2)
        )
        cell.columnconfigure(0, weight=1)

        ttk.Label(
            cell,
            text=label
        ).grid(row=0, column=0, sticky='w')

        s = tk.Scale(
            cell,
            from_=lo,
            to=hi,
            resolution=res,
            orient='horizontal',
            variable=var,
            length=255,
            showvalue=True,
            highlightthickness=0,
            bd=1,
            takefocus=True
        )
        s.grid(row=1, column=0, sticky='ew')

        if col == 1:
            _section_state['row'] += 1
            _section_state['col'] = 0
        else:
            _section_state['col'] = 1

        return s

    # ---------------- SHAPE / FILTER GATES ----------------
    ttk.Label(
        detbox,
        text='SHAPE / FILTER GATES',
        font=('Arial', 10, 'bold')
    ).pack(anchor='w')

    _begin_parameter_section()
