def _tab8_v7_notebook_changed(self, event=None):
    try:
        selected = self.nb.select()
        if selected == str(self.tab_particle_density):
            self.root.after_idle(lambda: _tab8_v7_ensure_ready(self))
    except Exception:
        pass


def _tab8_v7_ensure_ready(self):
    """Refresh Tab 8 source/slider without rebuilding Tab 8."""
    try:
        st = _tab8_v7_get_primary_stack(self)
        if st is None:
            ok = bool(_tab8_v7_sync_source(self, preserve_current=True))
            if not ok:
                # Tab 6 may still be finishing reconstruction when the main
                # window is first built. Retry a few times without rebuilding
                # widgets or changing any other tab.
                tries = int(getattr(self, '_tab8_source_retry_count', 0))
                if tries < 20:
                    self._tab8_source_retry_count = tries + 1
                    try:
                        self.root.after(300, lambda: _tab8_v7_ensure_ready(self))
                    except Exception:
                        pass
                return False
            self._tab8_source_retry_count = 0
            st = _tab8_v7_get_primary_stack(self)
            if st is None:
                return False
        n = st.shape[0]
        idx = max(0, min(int(self._tab8_frame_var.get()), n - 1))
        self._tab8_frame_slider.configure(from_=0, to=n - 1, resolution=1, state='normal')
        self._tab8_frame_var.set(idx)
        _tab8_v7_refresh_image(self)
        return True
    except Exception as exc:
        try:
            self.pd_status_var.set(f'Tab 8 refresh failed: {type(exc).__name__}: {exc}')
        except Exception:
            pass
        return False


