# ---------------------------------------------------------------------------
# TAB 10 — SINGLE-ROI 1D GAUSSIAN FIT (CONFIRMED ROI4 FROM TAB 9)
# ---------------------------------------------------------------------------

def _tab10_roi4_available(self):
    # ROI4 availability is determined by the CONFIRMED ROI4 state in Tab 9.
    # The processed ROI1 stack is fetched on demand if necessary.
    return (
        bool(getattr(self, '_tab9_roi4_confirmed', False))
        and getattr(self, '_tab9_roi4_coords', None) is not None
    )


def _tab10_sync_roi4_from_tab9(self, preserve_frame=True):
    """Fetch the CURRENT confirmed ROI from Tab 9 exactly."""
    try:
        self.tab10_status_var.set('Fetching CURRENT confirmed ROI from Tab 9...')
        self.root.update_idletasks()
    except Exception:
        pass

    if not bool(getattr(self,'_tab9_roi4_confirmed',False)):
        self.tab10_status_var.set(
            'ROI4 is not confirmed in Tab 9. Confirm ROI in Tab 9 first.'
        )
        self.tab10_slider.configure(state='disabled')
        return False

    c=getattr(self,'_tab9_roi4_coords',None)
    if not isinstance(c,dict):
        self.tab10_status_var.set(
            'Tab 9 reports ROI confirmed, but the current ROI4 coordinates are missing.'
        )
        self.tab10_slider.configure(state='disabled')
        return False

    source=getattr(self,'_tab9_roi1_stack',None)
    if source is None or not bool(getattr(self,'_tab9_roi1_ready',False)):
        if not _tab9_roi4_fetch_from_tab6(self,preserve_frame=True):
            self.tab10_status_var.set(
                'Could not fetch processed Primary ROI1 from Tab 6.'
            )
            self.tab10_slider.configure(state='disabled')
            return False
        source=getattr(self,'_tab9_roi1_stack',None)

    previous_stack = getattr(self, "_tab10_roi4_stack", None)
    had_analysis = bool(self._tab10_intensity_profiles)
    previous_scope = self._tab10_ii_scope
    previous_range = (int(self.tab10_start_var.get()), int(self.tab10_end_var.get()))
    previous_scale = getattr(self, "_tab10_roi4_scale", None)
    source=np.asarray(source,dtype=_intensity_dtype(self))
    if source.ndim!=3 or source.shape[0]<1:
        self.tab10_status_var.set(
            f'Invalid Tab 9 processed Primary ROI1 stack: {source.shape}'
        )
        self.tab10_slider.configure(state='disabled')
        return False

    h,w=source.shape[1:3]
    xmin=int(c['xmin']); xmax=int(c['xmax'])
    ymin=int(c['ymin']); ymax=int(c['ymax'])
    if not (0<=xmin<=xmax<w and 0<=ymin<=ymax<h):
        self.tab10_status_var.set(
            f'Confirmed ROI4 is outside Tab 9 Primary ROI1: '
            f'X={xmin}:{xmax}, Y={ymin}:{ymax}, source={w}×{h}px'
        )
        self.tab10_slider.configure(state='disabled')
        return False

    # Prefer the frozen stack only when it matches the CURRENT coordinates and shape.
    frozen=np.asarray(getattr(self,'_tab9_roi4_stack',None),dtype=_intensity_dtype(self)) \
        if getattr(self,'_tab9_roi4_stack',None) is not None else None
    fc=getattr(self,'_tab9_roi4_stack_coords',None)
    expected_shape=(source.shape[0],ymax-ymin+1,xmax-xmin+1)

    if (
        frozen is not None
        and frozen.ndim==3
        and isinstance(fc,dict)
        and fc==c
        and tuple(frozen.shape)==tuple(expected_shape)
    ):
        roi_stack=frozen.copy()
    else:
        roi_stack=source[:,ymin:ymax+1,xmin:xmax+1].copy()
        try:
            self._tab9_roi4_stack=roi_stack.copy()
            self._tab9_roi4_stack_coords=dict(c)
            self._tab9_roi4_stack_shape=tuple(roi_stack.shape)
        except Exception:
            pass

    # Transfer exactly Tab9 scale.
    try:
        sx,sy=map(float,self._tab9_roi4_scale)
    except Exception:
        sx,sy=map(float,_tab9_roi4_scale_nm(self))
    changed = (previous_stack is None or previous_scale != (sx, sy)
               or not np.array_equal(previous_stack, roi_stack, equal_nan=True))
    if changed:
        _tab10_reset_center_follow(self)
        self._tab10_center_cache = None
        self._tab10_tracking_fixed_center = None
        self._tab10_last_detected_core = None
        self._tab10_detection_diagnostics = {}
        _tab10_clear_intensity_source(self)
    self._tab10_roi4_scale=(sx,sy)

    self._tab10_roi4_stack=roi_stack.copy()
    self._tab10_roi4_global_coords=dict(c)
    self._tab10_roi4_coords={
        'xmin':0,'xmax':roi_stack.shape[2]-1,
        'ymin':0,'ymax':roi_stack.shape[1]-1
    }
    self._tab10_roi4_confirmed=True

    # Match Tab9 display color/limits.
    try:
        art=self.tab9_roi4_image2
        self._tab10_roi4_display_cmap=str(art.get_cmap().name)
        self._tab10_roi4_display_clim=tuple(float(v) for v in art.get_clim())
    except Exception:
        self._tab10_roi4_display_cmap=str(
            getattr(self,'_tab9_roi1_cmap','gray')
        )
        self._tab10_roi4_display_clim=tuple(
            getattr(self,'_tab9_roi1_clim',(0.0,1.0))
        )

    n=int(roi_stack.shape[0])

    # IMPORTANT: when preserve_frame=True, use Tab9's CURRENT frame.
    # This eliminates Tab10 opening at frame 1 while Tab9 is on frame 80.
    if preserve_frame:
        try:
            old=int(self.tab9_roi4_frame_var.get())
        except Exception:
            old=0
    else:
        try:
            old=int(self.tab10_frame_var.get())
        except Exception:
            old=0
    old=(n - 1) // 2 if changed else max(0,min(old,n-1))

    self._tab10_programmatic=True
    try:
        self.tab10_frame_var.set(old)
        self.tab10_slider.configure(
            from_=0,to=n-1,resolution=1,state='normal'
        )
        self.tab10_slider.set(old)
        _set_frame_slider_midpoint_once(self,self.tab10_slider,n,self.tab10_frame_var,zero_based=True,token='tab10')
        self.tab10_start_var.set(0)
        self.tab10_end_var.set(n-1)
        self.tab10_start_display_var.set('1')
        self.tab10_end_display_var.set(str(n))
        try:
            self.tab10_frame_label_var.set(
                f'Frame No. {old + 1}/{n} | Equivalent Field: '
                f'{float(_tab10_intensity_field(self, old)):+.6g} mT'
            )
            self.tab10_frame_info_var.set(
                f'Frame No. {old + 1}/{n} | Equivalent Field: '
                f'{float(_tab10_intensity_field(self, old)):+.6g} mT'
            )
            self.tab10_start_spin.configure(from_=1, to=n, increment=1)
            self.tab10_end_spin.configure(from_=1, to=n, increment=1)
        except Exception:
            pass
    finally:
        self._tab10_programmatic=False

    self.tab10_status_var.set(
        f'✓ CURRENT confirmed ROI4 fetched from Tab 9 | '
        f'FOV={roi_stack.shape[2]*sx:.6g} × {roi_stack.shape[1]*sy:.6g} nm | '
        f'Frame {old+1}/{n}'
    )
    _tab10_render_current(self,old)
    _tab10_sync_intensity_values(self)
    _tab10_plot_intensity(self)
    if changed and had_analysis and self.tab10_integrated_intensity_var.get():
        self._tab10_ii_scope = previous_scope
        if previous_scope == 'tracking':
            self.tab10_start_var.set(max(0, min(previous_range[0], n - 1)))
            self.tab10_end_var.set(max(0, min(previous_range[1], n - 1)))
            _tab10_sync_frame_range_controls(self)
        self._tab10_ii_recalculate_job = self.root.after(
            250, lambda: _tab10_recalculate_intensity(self))
    return True







def _tab10_get_crop(self, frame_idx):
    """Return the already-cropped confirmed ROI4 for a frame."""
    if getattr(self, '_tab10_roi4_stack', None) is None:
        if not _tab10_sync_roi4_from_tab9(self, preserve_frame=True):
            return None
    stack = np.asarray(self._tab10_roi4_stack, dtype=float)
    if stack.ndim != 3 or stack.shape[0] < 1:
        raise ValueError(f'ROI4 stack is invalid: {stack.shape}')
    idx = max(0, min(int(frame_idx), stack.shape[0] - 1))
    crop = np.asarray(stack[idx], dtype=float).copy()
    if crop.size == 0 or crop.ndim != 2:
        raise ValueError('ROI4 crop is empty or not a 2D image.')
    return crop



def _particle_focus_center(crop, fraction=.5, reference=None):
    """Choose one connected core near the intended ROI-local reference."""
    from scipy.ndimage import label, gaussian_filter
    a = np.asarray(crop, float)
    if a.ndim != 2 or min(a.shape) < 3 or not np.isfinite(a).any():
        raise ValueError('Particle centering requires a finite 2-D ROI.')
    h, w = a.shape
    yy, xx = np.indices(a.shape)
    rx, ry = (w-1)/2., (h-1)/2.
    if isinstance(reference, dict):
        rx, ry = float(reference['x0']), float(reference['y0'])
    bg = float(np.nanmedian(a))
    smooth = gaussian_filter(np.where(np.isfinite(a), a, bg), .8)
    contrast = smooth-bg
    radius = max(2., .28*min(h,w))
    search = np.isfinite(a) & (np.hypot(xx-rx, yy-ry) <= radius)
    if not search.any():
        raise ValueError('Particle reference is outside valid ROI data.')
    noise = 1.4826*float(np.median(np.abs(contrast[np.isfinite(a)]-np.median(contrast[np.isfinite(a)]))))
    candidates = []
    for sign in (1., -1.):
        response = sign*contrast
        peak = float(np.max(response[search]))
        floor = max(float(np.clip(fraction,.05,.95))*peak, 2.5*noise, 1e-12)
        labels, count = label((response > floor) & np.isfinite(a))
        for idx in range(1,count+1):
            mask = labels == idx
            if mask.sum() < 3 or not np.any(mask & search):
                continue
            # A cropped edge particle is never an automatic target.
            if mask[0].any() or mask[-1].any() or mask[:,0].any() or mask[:,-1].any():
                continue
            weights = np.where(mask, np.maximum(response-floor,0.),0.)
            total = weights.sum()
            if total <= 0:
                continue
            cx, cy = float((xx*weights).sum()/total), float((yy*weights).sum()/total)
            distance = np.hypot(cx-rx, cy-ry)
            if distance <= radius:
                candidates.append((distance, dict(x0=cx,y0=cy,background=bg,
                    sign=sign,peak=float(np.max(response[mask])),threshold=floor)))
    if candidates:
        return min(candidates,key=lambda item:item[0])[1]
    # Keep the intended position in a nondetection; never substitute an edge core.
    return dict(x0=rx,y0=ry,background=bg,sign=1.,peak=0.,threshold=0.)


def _particle_focus_profiles(crop, cx, cy, extracted):
    """Keep original samples, limiting a common symmetric interval before neighbors."""
    from scipy.ndimage import label, gaussian_filter
    t, profiles, avg = extracted
    a = np.asarray(crop,float)
    finite = np.isfinite(a)
    if not finite.any():
        return extracted
    bg = float(np.nanmedian(a))
    response = np.abs(gaussian_filter(np.where(finite,a,bg),.8)-bg)
    yy, xx = np.indices(a.shape)
    dist = np.hypot(xx-cx,yy-cy)
    local = response[dist <= max(2., .12*min(a.shape))]
    peak = float(np.max(local)) if local.size else 0.
    work = np.where(finite,a,bg)
    noise_valid = finite.copy()
    edge = max(1,int(.15*min(a.shape)))
    noise_valid[:edge] = False
    noise_valid[-edge:] = False
    noise_valid[:,:edge] = False
    noise_valid[:,-edge:] = False
    target_noise = _core_response_noise(work, gaussian_filter(work,.8)-bg,
                                       noise_valid,cx,cy,.8,0.)
    if peak <= 4.5*target_noise:
        return extracted
    noise = 1.4826*float(np.median(np.abs(response[finite]-np.median(response[finite]))))
    floor = max(.35*peak, 3.*noise, 1e-12)
    labels, count = label((response > floor) & finite)
    if not count:
        return extracted
    components = [(idx, float(np.min(dist[labels==idx]))) for idx in range(1,count+1)
                  if np.count_nonzero(labels==idx) >= 9]
    if not components:
        return extracted
    target = min(components,key=lambda item:item[1])[0]
    # No target near the reference: retain raw nondetection profiles, not a neighbor.
    if np.min(dist[labels==target]) > max(2., .12*min(a.shape)):
        return extracted
    # Include a tail guard outside each thresholded core, not just its bright peak.
    limits = [distance-max(2.,1.5*np.sqrt(np.count_nonzero(labels==idx)/np.pi))
              for idx,distance in components if idx != target
              and np.max(response[labels==idx]) >= .5*peak]
    if not limits:
        return extracted
    limit = min(limits)
    keep = np.abs(np.asarray(t,float)) <= limit
    if limit <= 2 or np.count_nonzero(keep) < 12:
        raise ValueError('Neighbor overlaps target analysis region; select a tighter ROI.')
    return (np.asarray(t)[keep], {angle:np.asarray(values)[keep] for angle,values in profiles.items()},
            np.asarray(avg)[keep])


def _tab10_center(self, crop):
    return _particle_focus_center(crop, self.tab10_contrast_fraction_var.get())



def _tab10_active_angles(self):
    """Gaussian mode uses selected reference lines; D-Fit always uses 12 radial lines."""
    if bool(getattr(self, 'tab10_dfit_var', None) is not None and self.tab10_dfit_var.get()):
        return [float(a) for a in np.arange(0.0, 360.0, 30.0)]
    return _tab10_get_reference_angles(self)


def _tab10_get_reference_angles(self):
    return {
        '1': [0.0],
        '2': [0.0, 90.0],
        '4': [0.0, 45.0, 90.0, 135.0],
        '6': [0.0, 30.0, 60.0, 90.0, 120.0, 150.0]
    }.get(str(self.tab10_ref_mode_var.get()), [0.0, 90.0])


def _tab10_update_reference_label(self, event=None):
    angles = _tab10_get_reference_angles(self)
    self.tab10_ref_label.configure(
        text=f'{len(angles)} lines: ' + ' / '.join(f'{a:g}°' for a in angles)
    )
    _tab10_render_current(self)


def _tab10_extract_profiles(self, crop, cx, cy, angles):
    return _particle_focus_profiles(crop, cx, cy, self._extract_multi_line_profiles(
        crop, float(cx), float(cy), list(angles), nsamples=800))



def _tab10_detect_particle_for_tracking(self, crop):
    """Validate localized bright/dark cores before optional zero-gated fits."""
    try:
        a = np.asarray(crop, dtype=float)
        if a.ndim != 2 or a.size < 49:
            return False, None

        finite = np.isfinite(a)
        if not np.any(finite):
            return False, None
        med = float(np.nanmedian(a[finite]))
        if not np.isfinite(med):
            return False, None
        a = np.where(finite, a, med)

        h, w = a.shape
        if min(h, w) < 9:
            return False, None

        fixed = getattr(self, '_tab10_tracking_fixed_center', None)
        if not isinstance(fixed, dict):
            fixed = _tab10_detection_reference(self, crop)

        fx = float(fixed.get('x0', np.nan))
        fy = float(fixed.get('y0', np.nan))
        if not (np.isfinite(fx) and np.isfinite(fy)):
            return False, None

        # Use the previous accepted core when available.  This is the key
        # sequential-tracking improvement: frame 76 is allowed to remain
        # attached to the real particle even if its contrast temporarily
        # falls below the global threshold.
        prev = getattr(self, '_tab10_last_detected_core', None)
        if isinstance(prev, dict):
            px = float(prev.get('x0', fx))
            py = float(prev.get('y0', fy))
            if np.isfinite(px) and np.isfinite(py):
                refx, refy = px, py
            else:
                refx, refy = fx, fy
        else:
            refx, refy = fx, fy

        # The search remains anchored to the fixed ROI center.  A previous
        # accepted core may tighten the search locally but cannot move the
        # tracking reference outside the ROI.
        base_radius = max(5.0, 0.22 * min(h, w))
        prev_radius = max(4.0, 0.20 * min(h, w))
        yy, xx = np.indices((h, w), dtype=float)

        # Edge/corner particles must not inflate the target's noise estimate.
        edge = max(1, int(.15*min(h,w)))
        interior = np.zeros_like(finite)
        interior[edge:h-edge,edge:w-edge] = True
        finite &= interior
        fill = float(np.median(a[finite])) if finite.any() else float(np.median(a))
        a = np.where(finite, a, fill)

        # Background removal for detection only.
        bg_sigma = max(3.0, 0.18 * min(h, w))
        bg = gaussian_filter(a, sigma=bg_sigma, mode='nearest')
        residual = a - bg

        # Robust residual noise.
        b = max(2, int(round(0.10 * min(h, w))))
        border = np.concatenate([
            residual[:b, :].ravel(), residual[-b:, :].ravel(),
            residual[:, :b].ravel(), residual[:, -b:].ravel()
        ])
        border = border[np.isfinite(border)]
        if border.size < 20:
            border = residual.ravel()

        noise = 1.4826 * float(np.median(
            np.abs(border - np.median(border))
        ))
        if not np.isfinite(noise) or noise <= 0:
            noise = float(np.std(border))
        if not np.isfinite(noise) or noise <= 0:
            noise = max(np.finfo(float).eps, float(np.std(residual)) * 0.1)

        scales = (
            max(1.5, 0.025 * min(h, w)),
            max(2.0, 0.035 * min(h, w)),
            max(2.5, 0.050 * min(h, w)),
            max(3.0, 0.070 * min(h, w)),
            max(4.0, 0.095 * min(h, w)),
            max(5.0, 0.125 * min(h, w)),
        )

        # User's 0.60 threshold remains part of validation.
        frac = 0.60
        try:
            frac = float(np.clip(
                self.tab10_contrast_fraction_var.get(), 0.0, 0.95
            ))
        except Exception:
            pass

        best = None

        for sig in scales:
            smooth = gaussian_filter(residual, sigma=sig, mode='nearest')

            rb = np.concatenate([
                smooth[:b, :].ravel(), smooth[-b:, :].ravel(),
                smooth[:, :b].ravel(), smooth[:, -b:].ravel()
            ])
            rb = rb[np.isfinite(rb)]
            rmad = 1.4826 * float(np.median(
                np.abs(rb - np.median(rb))
            ))
            if not np.isfinite(rmad) or rmad <= 0:
                rmad = float(np.std(rb))
            if not np.isfinite(rmad) or rmad <= 0:
                rmad = noise / max(1.0, np.sqrt(2*np.pi)*sig)

            for polarity in (1.0, -1.0):
                response = polarity * smooth

                # Primary search: around fixed center.  If a previous core
                # exists, include its local neighborhood as an equally valid
                # search area, provided it remains close to fixed center.
                search = (
                    ((xx - fx)**2 + (yy - fy)**2 <= base_radius**2) |
                    (((xx - refx)**2 + (yy - refy)**2 <= prev_radius**2) &
                     ((xx - fx)**2 + (yy - fy)**2 <= base_radius**2))
                )

                candidate = np.where(search, response, -np.inf)
                flat = int(np.argmax(candidate))
                cy, cx = np.unravel_index(flat, candidate.shape)
                peak = float(response[cy, cx])
                if not np.isfinite(peak):
                    continue

                candidate_noise = _core_response_noise(a, smooth, finite, cx, cy, sig, rmad)
                snr = peak / max(candidate_noise, np.finfo(float).eps)

                inner_r = max(1.5, 0.65 * sig)
                outer_r = max(inner_r + 1.0, 1.75 * sig)
                dist = np.hypot(xx - cx, yy - cy)
                inner = response[dist <= inner_r]
                annulus = response[
                    (dist >= inner_r) & (dist <= outer_r)
                ]
                if inner.size < 3 or annulus.size < 8:
                    continue

                raw_ring = a[(dist >= outer_r) & (dist <= max(outer_r + 1.0, 3.0 * sig))]
                if raw_ring.size < 8:
                    continue
                raw_core = polarity * (a[dist <= inner_r] - np.median(raw_ring))
                if np.count_nonzero(raw_core > max(0.25 * peak, candidate_noise)) < 3:
                    continue
                center_level = float(np.median(inner))
                annulus_level = float(np.median(annulus))
                prominence = center_level - annulus_level

                # Two operating levels:
                # A) normal frames: the original robust gate;
                # B) sequential-recovery frames: slightly relaxed only when
                # the candidate is close to the previous accepted core.
                near_previous = (
                    isinstance(prev, dict) and
                    np.hypot(cx - refx, cy - refy) <= prev_radius
                )

                if near_previous:
                    snr_min = 4.5
                    prom_abs = 2.2 * candidate_noise
                    prom_rel = 0.07 * peak
                else:
                    snr_min = 4.5
                    prom_abs = 2.2 * candidate_noise
                    prom_rel = 0.10 * peak

                if snr < snr_min:
                    continue
                if prominence < max(prom_abs, prom_rel):
                    continue

                # Edge rejection.
                margin = max(2.0, 1.35 * sig)
                if (
                    cx < margin or cx > w - 1 - margin or
                    cy < margin or cy > h - 1 - margin
                ):
                    continue

                # 0.60 contrast + compactness.  For a dim real particle the
                # mask may be smaller, but it must remain localized.
                patch = response[
                    max(0, int(cy - outer_r)):min(h, int(cy + outer_r) + 1),
                    max(0, int(cx - outer_r)):min(w, int(cx + outer_r) + 1)
                ]
                if patch.size == 0:
                    continue

                threshold = frac * peak
                area = int(np.count_nonzero(patch >= threshold))
                expected = np.pi * max(sig, 1.0)**2

                min_area = max(2, int(0.10 * expected))
                max_area = max(12, int(8.5 * expected))
                if area < min_area or area > max_area:
                    continue

                # Central signal must exceed the noise floor.
                center_floor = 1.8 if near_previous else 2.3
                if center_level < center_floor * candidate_noise:
                    continue

                # Candidate must remain close to the fixed center.  Previous
                # continuity never permits an unrelated distant structure.
                if np.hypot(cx - fx, cy - fy) > base_radius:
                    continue

                score = (
                    snr
                    + 0.45 * prominence / max(candidate_noise, 1e-12)
                    + (1.5 if near_previous else 0.0)
                )

                if best is None or score > best['score']:
                    best = {
                        'x0': float(cx),
                        'y0': float(cy),
                        'background': float(np.nanmedian(bg)),
                        'sign': float(polarity),
                        'peak': float(peak),
                        'threshold': float(frac * peak),
                        'snr': float(snr),
                        'prominence': float(prominence),
                        'scale': float(sig),
                        'score': float(score),
                        'near_previous': bool(near_previous),
                    }

        if best is None:
            return False, None

        return True, best

    except Exception as exc:
        raise RuntimeError(f"Core detection failed: {exc}") from exc




def _tab10_11_find_crossing(x, y, level, side=None):
    """Return an interpolated x crossing of y=level on the requested side.

    side='left' selects x<0, side='right' selects x>0.  The crossing is
    interpolated in the original x coordinate; no radius*2 approximation is
    used for the final D-FIT diameter.
    """
    x = np.asarray(x, dtype=float)
    y = np.asarray(y, dtype=float)
    good = np.isfinite(x) & np.isfinite(y)
    x, y = x[good], y[good]
    if x.size < 2:
        return np.nan
    order = np.argsort(x)
    x, y = x[order], y[order]
    if side == 'left':
        keep = x <= 0.0
    elif side == 'right':
        keep = x >= 0.0
    else:
        keep = np.ones_like(x, dtype=bool)
    x, y = x[keep], y[keep]
    if x.size < 2:
        return np.nan
    d = y - float(level)
    hit = np.where((d[:-1] == 0) | (d[:-1] * d[1:] <= 0))[0]
    if hit.size == 0:
        return np.nan
    # For each side choose the crossing nearest the center. This avoids
    # accidental crossings caused by distant background wiggles.
    candidates = []
    for j in hit:
        x0, x1 = float(x[j]), float(x[j+1])
        y0, y1 = float(y[j]), float(y[j+1])
        if abs(y1-y0) > 1e-14:
            xc = x0 + (float(level)-y0)*(x1-x0)/(y1-y0)
        else:
            xc = x0
        if np.isfinite(xc):
            candidates.append(float(xc))
    if not candidates:
        return np.nan
    if side == 'left':
        return float(max([v for v in candidates if v <= 1e-9], default=np.nan))
    if side == 'right':
        return float(min([v for v in candidates if v >= -1e-9], default=np.nan))
    return float(candidates[np.argmin(np.abs(candidates))])


def _tab10_fit_roi4(self, frame_idx, detection=None):
    crop=_tab10_get_crop(self,frame_idx)
    if crop is None:return None
    follow = getattr(self, '_tab10_center_follow_enabled', False)
    zero_enabled = follow or (detection is not False and (detection is not None or self.tab10_zero_if_undetected_var.get()))
    if zero_enabled:
        detected, det = detection if isinstance(detection, tuple) else (_tab10_follow_core(self, crop, frame_idx) if follow else _tab10_detect_with_diagnostics(self, crop, frame_idx))
        if not detected:
            return _tab10_zero_result(self, frame_idx, crop, _tab10_detection_reference(self, crop))
        # An explicitly recalculated center stays fixed; otherwise use the validated core.
        center = dict(det) if follow else getattr(self, '_tab10_center_cache', None)
        if not isinstance(center, dict):
            center = dict(det)
    else:
        center = getattr(self, '_tab10_center_cache', None)
        if not isinstance(center, dict):
            center = _tab10_center(self, crop)
    cx, cy = float(center['x0']), float(center['y0'])
    angles=_tab10_active_angles(self)
    t_px,profiles,avg=_tab10_extract_profiles(self,crop,cx,cy,angles)
    sx,sy=self._tab10_roi4_scale
    # Gaussian mode retains the existing common display coordinate. D-Fit,
    # however, uses the exact direction-dependent physical scale below.
    sline=float(np.sqrt(float(sx)*float(sy))) if sx>0 and sy>0 else 1.0
    t_nm=np.asarray(t_px,float)*sline
    fit=self._fit_fixed_center_1d_gaussian(t_nm,avg)
    stack=np.vstack([profiles[float(a)] for a in angles])
    per_line_rmse=np.sqrt(np.nanmean((stack-avg[None,:])**2,axis=1))
    line_rmse=float(np.nanmean(per_line_rmse)); line_cv=float(line_rmse/max(float(np.nanmax(np.abs(avg))),1e-12))
    field=_tab10_intensity_field(self,int(frame_idx)); c=self._tab10_roi4_coords
    result={'roi_index':4,'frame':int(frame_idx),'field_mT':float(field),'center_x_px':float(c['xmin']+cx),'center_y_px':float(c['ymin']+cy),'local_center_x_px':float(cx),'local_center_y_px':float(cy),'contrast_background':float(center['background']),'contrast_threshold':float(center['threshold']),'contrast_sign':float(center['sign']),'contrast_peak':float(center['peak']),'angles':list(angles),'t_px':np.asarray(t_px,float),'t_nm':t_nm,'profiles':profiles,'average_profile':np.asarray(avg,float),'fit_profile':np.asarray(fit['fit_profile'],float),'residual_profile':np.asarray(fit['residual_profile'],float),'background':float(fit['background']),'amplitude':float(fit['amplitude']),'amplitude_err':float(fit.get('amplitude_err',np.nan)),'peak_intensity':float(fit['background']+fit['amplitude']),'sigma':float(fit['sigma']),'sigma_err':float(fit.get('sigma_err',np.nan)),'fwhm':float(fit['fwhm']),'fwhm_err':float(fit.get('fwhm_err',np.nan)),'r2':float(fit.get('r2',np.nan)),'rmse':float(fit.get('rmse',np.nan)),'line_rmse':line_rmse,'line_cv':line_cv,'per_line_rmse':per_line_rmse,'fov_width_nm':float((c['xmax']-c['xmin']+1)*sx),'fov_height_nm':float((c['ymax']-c['ymin']+1)*sy)}
    # Always calculate D-Fit in the background so the Tab-10 result table
    # contains BOTH Gaussian-fit and D-Fit values, regardless of which
    # visualization mode is selected.
    use_threshold = bool(self.tab10_dfit_threshold_mode_var.get()) and bool(self.tab10_dfit_var.get())
    dfit_profiles, dfit_t_px, dfit_avg = profiles, t_px, avg
    if not all(float(a) in profiles for a in np.arange(0.0, 360.0, 30.0)):
        dfit_t_px, dfit_profiles, dfit_avg = _tab10_extract_profiles(
            self, crop, cx, cy, np.arange(0.0, 360.0, 30.0))
    result.update(dfit_input_profiles=dfit_profiles, dfit_input_t_px=np.asarray(dfit_t_px, float),
                  dfit_input_average_profile=np.asarray(dfit_avg, float),
                  dfit_scale_x_nm_per_px=float(sx), dfit_scale_y_nm_per_px=float(sy))
    if use_threshold:
        try:
            dfit_threshold = float(np.clip(float(self.tab10_dfit_threshold_var.get()), 0.00, 1.00))
        except Exception:
            dfit_threshold = 0.50
        dfit=_tab10_11_dfit_from_profiles(
            dfit_profiles,dfit_t_px,sx=float(sx),sy=float(sy), threshold=dfit_threshold,
            average_profile=np.asarray(dfit_avg,float), sg_level=self.tab10_dfit_sg_level_var.get()
        )
    else:
        dfit=_tab10_gradient_dfit_from_profiles(
            dfit_profiles,dfit_t_px,sx=float(sx),sy=float(sy),
            sg_level=self.tab10_dfit_sg_level_var.get(),
            average_profile=np.asarray(dfit_avg,float)
        )
    if dfit is not None:
            result.update({
                'diameter_nm':dfit['avg_diameter_nm'],
                'diameter_err_nm':dfit['sd_diameter_nm'],
                'dfit_sg_level':dfit['sg_level'],
                'dfit_sg_window_points':dfit['sg_window_points'],
                'dfit_left_intercept_nm':dfit.get('fit_left_intercept_nm',dfit.get('left_edge_mean_nm',np.nan)),
                'dfit_right_intercept_nm':dfit.get('fit_right_intercept_nm',dfit.get('right_edge_mean_nm',np.nan)),
                'dfit_measurements':dfit['measurements'],
                'dfit_pair_measurements':dfit.get('pair_measurements', []),
                'core_intensity':dfit['core_intensity'],
                'dfit_average_profile_t_nm':dfit.get('normalized_average_t_nm', np.asarray(t_nm,float)),
                'dfit_valid_count':dfit['valid_count'],
                'dfit_normalized_average_profile':dfit['normalized_average_profile'],
                'dfit_radial_normalized_profiles':dfit.get('radial_normalized_profiles', {}),
                'dfit_radial_smoothed_profiles':dfit.get('radial_smoothed_profiles', {}),
                'dfit_radial_gradient_profiles':dfit.get('radial_gradient_profiles', {}),
                'dfit_diameter_profile_t_nm':dfit.get('diameter_profile_t_nm', np.asarray([], dtype=float)),
                'dfit_diameter_profiles':dfit.get('diameter_profiles', {}),
                'dfit_diameter_smoothed_profiles':dfit.get('diameter_smoothed_profiles', {}),
                'dfit_normalized_profile_min':dfit['normalized_profile_min'],
                'dfit_normalized_profile_max':dfit['normalized_profile_max'],
                'dfit_normalized_left_raw_intensity':dfit['normalized_left_raw_intensity'],
                'dfit_normalized_right_raw_intensity':dfit['normalized_right_raw_intensity'],
                'dfit_diameter_method': dfit.get('diameter_method', 'Savitzky-Golay radial gradient edge'),
                'dfit_scale_x_nm_per_px': float(sx),
                'dfit_scale_y_nm_per_px': float(sy),
                'dfit_threshold_mode': bool(use_threshold),
                'dfit_threshold': float(dfit.get('threshold', np.nan)) if use_threshold else np.nan,
                'dfit_diameter_method': dfit.get('diameter_method', 'Savitzky-Golay radial gradient edge')
            })
    if follow:
        result.update(center_tracking=True, center_anchor_x_px=self._tab10_center_anchor['x0'],
                      center_anchor_y_px=self._tab10_center_anchor['y0'])
    if zero_enabled:
        result.update(self._tab10_detection_diagnostics.get(int(frame_idx), {}))
    else:
        result.update(core_detected=None, detection_status='not checked', detection_reason='Zero if Undetected disabled')
    result['analysis_position_min_nm'] = float(np.min(t_nm))
    result['analysis_position_max_nm'] = float(np.max(t_nm))
    result['gaussian_covariance'] = np.asarray(fit['covariance'], float).copy()
    result.update(_intensity_provenance(self, int(frame_idx)))
    _tab10_update_integrated_result(self, result)
    _tab10_cache_intensity_profile(self, result)
    last = getattr(self, '_tab10_last_fit', None)
    if (self._tab10_ii_scope == 'tracking' and isinstance(last, dict)
            and int(last['frame']) == int(frame_idx)):
        self._tab10_ii_current_result = result
    return result



def _tab10_gradient_dfit_from_profiles(profiles, t_px, sx=1.0, sy=1.0,
                                      sg_level=0, average_profile=None):
    """Tab-10 D-Fit: radial gradient/edge-based particle diameter.

    The D-Fit boundary is NOT defined by an intensity threshold.  For each of
    the 12 radial directions, a Savitzky-Golay-smoothed radial intensity profile
    is differentiated with respect to the true physical radial coordinate.
    The strongest valid outward particle-to-background transition is selected
    as the edge. Opposite radial edges form six independent diameters; the
    reported diameter is their mean and the SD is the sample standard deviation.

    sg_level is the user slider value 0..30. 0 = no smoothing; N = a
    Savitzky-Golay window of (2*N+1) samples with polynomial order 2.
    """
    t = np.asarray(t_px, dtype=float)
    if t.ndim != 1 or t.size < 5:
        return None

    sx = float(sx) if np.isfinite(sx) and sx > 0 else 1.0
    sy = float(sy) if np.isfinite(sy) and sy > 0 else 1.0
    try:
        sg_level = int(np.clip(round(float(sg_level)), 0, 30))
    except Exception:
        sg_level = 0

    raw_avg = np.asarray(average_profile, dtype=float) if average_profile is not None else None
    raw_core = np.nan
    if raw_avg is not None and raw_avg.size == t.size:
        ci = int(np.argmin(np.abs(t)))
        if np.isfinite(raw_avg[ci]):
            raw_core = float(raw_avg[ci])

    angle_keys = sorted([float(a) for a in profiles.keys()])
    canonical = [float(a) for a in np.arange(0.0, 360.0, 30.0)]
    if all(a in profiles for a in canonical):
        angle_keys = canonical

    radial = {}
    measurements = []

    for ang in angle_keys:
        p = np.asarray(profiles[float(ang)], dtype=float)
        n = min(p.size, t.size)
        if n < 5:
            continue

        theta = np.deg2rad(float(ang))
        step_nm = float(np.hypot(sx*np.cos(theta), sy*np.sin(theta)))
        x = t[:n] * step_nm
        y = p[:n]
        good = np.isfinite(x) & np.isfinite(y) & (x >= -1e-12)
        x, y = x[good], y[good]
        if x.size < 5:
            continue
        order = np.argsort(x)
        x, y = x[order], y[order]
        iz = int(np.argmin(np.abs(x)))

        # Savitzky-Golay smoothing: slider 0 means OFF; N means 2*N+1 points.
        y_s = y.copy()
        sg_window = 1
        if sg_level > 0 and y.size >= 5:
            sg_window = min(2*sg_level + 1, y.size if y.size % 2 else y.size - 1)
            if sg_window >= 5:
                try:
                    y_s = savgol_filter(y, sg_window, 2, mode='interp')
                except Exception:
                    y_s = y.copy()
                    sg_window = 1

        # Estimate local background from the outer part of the radial profile.
        outer_start = max(iz + 3, int(0.75*x.size))
        outer = y_s[outer_start:]
        outer = outer[np.isfinite(outer)]
        if outer.size < 5:
            outer = y_s[max(iz+3, int(0.65*x.size)):]
            outer = outer[np.isfinite(outer)]
        bg = float(np.nanmedian(outer)) if outer.size else float(np.nanmedian(y_s))
        core = raw_core if np.isfinite(raw_core) else float(y_s[iz])
        contrast = core - bg
        if not np.isfinite(contrast) or abs(contrast) <= 1e-12:
            measurements.append({'angle_deg': float(ang), 'radius_nm': np.nan,
                                 'edge_strength': np.nan, 'edge_drop': np.nan,
                                 'sg_window_points': int(sg_window),
                                 'core_raw_intensity': float(core),
                                 'background_raw_intensity': float(bg),
                                 'valid': False})
            continue

        # Gradient is taken against true nm distance. For a bright particle,
        # the desired boundary is a negative gradient; for a dark particle it
        # is a positive gradient.
        grad = np.gradient(y_s, x)
        expected_sign = 1.0 if contrast > 0 else -1.0
        score = -expected_sign * grad
        finite_score = np.isfinite(score)

        rmax = float(np.nanmax(x))
        # Do not use the center pixel or the crop edge as an edge candidate.
        search = finite_score & (x >= max(2.0*max(step_nm, 1e-12), 0.02*rmax)) & (x <= 0.92*rmax)
        idxs = np.flatnonzero(search)
        edge_idx = None
        if idxs.size:
            # Robust gradient-noise estimate from the outer/background region.
            go = score[outer_start:]
            go = go[np.isfinite(go)]
            gmad = 1.4826 * float(np.median(np.abs(go - np.median(go)))) if go.size else 0.0
            if not np.isfinite(gmad) or gmad <= 0:
                gmad = float(np.std(go)) if go.size else 0.0
            min_prom = max(3.0*gmad, np.finfo(float).eps)
            try:
                peaks, props = find_peaks(
                    np.where(search, score, -np.inf),
                    prominence=min_prom,
                    distance=max(1, sg_window//2)
                )
            except Exception:
                peaks = np.array([], dtype=int)
                props = {}
            peaks = np.asarray([i for i in peaks if search[i]], dtype=int)
            if peaks.size:
                # Require an actual outward intensity transition at the peak.
                valid_peaks = []
                half = max(2, sg_window//2)
                for i in peaks:
                    lo = max(0, i-half); hi = min(y_s.size, i+half+1)
                    left_slice = y_s[max(0, i-half):i]
                    right_slice = y_s[i+1:min(y_s.size, i+half+1)]
                    if left_slice.size < 2 or right_slice.size < 2:
                        continue
                    drop = expected_sign * (float(np.nanmean(left_slice)) - float(np.nanmean(right_slice)))
                    if np.isfinite(drop) and drop > max(2.0*gmad*max(step_nm,1e-12), 0.0):
                        valid_peaks.append((float(score[i]), int(i), float(drop)))
                if valid_peaks:
                    valid_peaks.sort(key=lambda z: z[0], reverse=True)
                    edge_idx = valid_peaks[0][1]

            # Fallback: strongest valid gradient if peak detection found none.
            if edge_idx is None:
                cand = idxs[np.nanargmax(score[idxs])]
                half = max(2, sg_window//2)
                left_slice = y_s[max(0, cand-half):cand]
                right_slice = y_s[cand+1:min(y_s.size, cand+half+1)]
                if left_slice.size >= 2 and right_slice.size >= 2:
                    drop = expected_sign * (float(np.nanmean(left_slice)) - float(np.nanmean(right_slice)))
                    if np.isfinite(drop) and drop > 0:
                        edge_idx = int(cand)

        edge_r = np.nan
        edge_strength = np.nan
        edge_drop = np.nan
        if edge_idx is not None:
            i = int(edge_idx)
            # Parabolic interpolation of the local gradient maximum for
            # sub-sample radial precision.
            delta = 0.0
            if 0 < i < score.size-1 and np.all(np.isfinite(score[i-1:i+2])):
                den = score[i-1] - 2.0*score[i] + score[i+1]
                if abs(den) > 1e-15:
                    delta = 0.5*(score[i-1] - score[i+1]) / den
                    delta = float(np.clip(delta, -0.5, 0.5))
            if 0 < i < y_s.size-1:
                edge_r = float(x[i] + delta*(x[i+1]-x[i]))
            else:
                edge_r = float(x[i])
            edge_strength = float(score[i])
            half = max(2, sg_window//2)
            left_slice = y_s[max(0, i-half):i]
            right_slice = y_s[i+1:min(y_s.size, i+half+1)]
            if left_slice.size and right_slice.size:
                edge_drop = float(expected_sign*(np.nanmean(left_slice)-np.nanmean(right_slice)))

        # Common-core normalization is retained for visualization/export only;
        # it is NOT used to decide the edge position.
        span = core - bg
        yn = (y_s - bg)/span if np.isfinite(span) and abs(span)>1e-12 else np.full_like(y_s, np.nan)
        if 0 <= iz < yn.size:
            yn[iz] = 1.0

        radial[float(ang)] = {
            'x': np.asarray(x, dtype=float),
            'raw': np.asarray(y, dtype=float),
            'smoothed': np.asarray(y_s, dtype=float),
            'normalized': np.asarray(yn, dtype=float),
            'gradient': np.asarray(grad, dtype=float),
            'edge_radius_nm': float(edge_r) if np.isfinite(edge_r) else np.nan,
            'edge_strength': float(edge_strength) if np.isfinite(edge_strength) else np.nan,
            'edge_drop': float(edge_drop) if np.isfinite(edge_drop) else np.nan,
        }
        measurements.append({
            'angle_deg': float(ang),
            'radius_nm': float(edge_r) if np.isfinite(edge_r) else np.nan,
            'edge_strength': float(edge_strength) if np.isfinite(edge_strength) else np.nan,
            'edge_drop': float(edge_drop) if np.isfinite(edge_drop) else np.nan,
            'sg_window_points': int(sg_window),
            'core_raw_intensity': float(core),
            'background_raw_intensity': float(bg),
            'valid': bool(np.isfinite(edge_r)),
        })

    if not measurements:
        return None

    row_by_angle = {round(float(m['angle_deg']) % 360.0, 6): m for m in measurements}
    pair_rows = []
    diameter_values = []
    pair_angles = []
    left_edges = []
    right_edges = []
    for a in [0.0,30.0,60.0,90.0,120.0,150.0]:
        b = (a+180.0)%360.0
        ra = row_by_angle.get(round(a,6)); rb = row_by_angle.get(round(b,6))
        if ra is None or rb is None: continue
        r1=float(ra.get('radius_nm',np.nan)); r2=float(rb.get('radius_nm',np.nan))
        d=r1+r2 if np.isfinite(r1) and np.isfinite(r2) else np.nan
        pair_rows.append({'angle_deg':a,'opposite_angle_deg':b,'radius_1_nm':r1,'radius_2_nm':r2,'diameter_nm':d})
        if np.isfinite(d):
            diameter_values.append(d); pair_angles.append(a)
            right_edges.append(r1); left_edges.append(-r2)

    diameter_values=np.asarray(diameter_values,float)
    dmean=float(np.nanmean(diameter_values)) if diameter_values.size else np.nan
    dsd=float(np.std(diameter_values,ddof=1)) if diameter_values.size>=2 else (0.0 if diameter_values.size==1 else np.nan)
    left_mean=float(np.nanmean(left_edges)) if left_edges else np.nan
    right_mean=float(np.nanmean(right_edges)) if right_edges else np.nan

    # Six full diameter profiles from the smoothed, normalized radial profiles.
    full_profiles=[]; diameter_profile_dict={}; smoothed_diameter_profile_dict={}; common_pos=None
    for a in pair_angles:
        b=(a+180.0)%360.0
        A=radial.get(float(a)); B=radial.get(float(b))
        if A is None or B is None: continue
        xa,ya=A['x'],A['normalized']; xb,yb=B['x'],B['normalized']
        max_common=min(float(np.nanmax(xa)),float(np.nanmax(xb)))
        if not np.isfinite(max_common) or max_common<=0: continue
        ngrid=max(200,min(len(xa),len(xb)))
        pos=np.linspace(0.0,max_common,ngrid)
        yA=np.interp(pos,xa,ya); yB=np.interp(pos,xb,yb)
        full=np.concatenate((yB[:0:-1],yA)); full_profiles.append(full)
        diameter_profile_dict[float(a)]=np.asarray(full,float)
        sA=np.interp(pos,xa,A['smoothed']); sB=np.interp(pos,xb,B['smoothed'])
        smoothed_diameter_profile_dict[float(a)] = np.concatenate((sB[:0:-1],sA))
        if common_pos is None: common_pos=pos

    if not full_profiles or common_pos is None:
        return None
    full_profiles=np.vstack(full_profiles)
    avg_norm=np.nanmean(full_profiles,axis=0)
    t_avg=np.concatenate((-common_pos[:0:-1],common_pos))
    cidx=int(np.argmin(np.abs(t_avg)))
    avg_norm[cidx]=1.0

    return {
        'measurements': measurements,
        'pair_measurements': pair_rows,
        'core_intensity': float(raw_core) if np.isfinite(raw_core) else np.nan,
        'valid_count': int(np.sum([m.get('valid',False) for m in measurements])),
        'avg_diameter_nm': dmean,
        'sd_diameter_nm': dsd,
        'normalized_average_profile': np.asarray(avg_norm,float),
        'normalized_average_t_nm': np.asarray(t_avg,float),
        'radial_normalized_profiles': {float(a):(v['x'],v['normalized']) for a,v in radial.items()},
        'radial_smoothed_profiles': {float(a):(v['x'],v['smoothed']) for a,v in radial.items()},
        'radial_gradient_profiles': {float(a):(v['x'],v['gradient']) for a,v in radial.items()},
        'diameter_profile_t_nm': np.asarray(t_avg,float),
        'diameter_profiles': diameter_profile_dict,
        'diameter_smoothed_profiles': smoothed_diameter_profile_dict,
        'normalized_profile_min': float(np.nanmin(avg_norm)),
        'normalized_profile_max': float(np.nanmax(avg_norm)),
        'left_edge_mean_nm': left_mean,
        'right_edge_mean_nm': right_mean,
        'sg_level': int(sg_level),
        'sg_window_points': int(2*sg_level+1) if sg_level>0 else 0,
        'diameter_method': '12 radial profiles; Savitzky-Golay-smoothed radial gradient edge; six opposite-pair diameters',
        'threshold': np.nan,
        'threshold_intensity': np.nan,
        'normalized_threshold': np.nan,
        'normalized_left_intercept_nm': left_mean,
        'normalized_right_intercept_nm': right_mean,
        'normalized_left_raw_intensity': np.nan,
        'normalized_right_raw_intensity': np.nan,
    }


def _tab10_11_dfit_from_profiles(profiles, t_px, sx=1.0, sy=1.0, center=None, threshold=0.50,
                                    fit_profile=None, fit_background=np.nan, fit_amplitude=np.nan,
                                    average_profile=None, sg_level=0):
    """Tab-10 D-Fit: 12 radial threshold points, 6 diameters, common core normalization.

    Definition:
      1. Use the raw average line profile of the frame to obtain the core/raw
         intensity at the fixed center.
      2. Normalize the ENTIRE frame's radial profiles by this ONE common core
         intensity, so the particle core is exactly 1.0 for all 12 directions.
      3. Along each of the 12 radial directions (0..330 deg, 30 deg spacing),
         find the first outward crossing of the user threshold (default 0.50).
      4. Pair opposite directions to obtain six diameters.
      5. Build six full diameter profiles from those opposite radial profiles,
         using the SAME common-core normalization, average those six profiles,
         and locate the 0.50 crossings of that average profile.
      6. Report the diameter from the averaged six-line profile.  The six-pair
         diameters provide the SD.
    """
    try:
        thr = float(np.clip(float(threshold), 0.01, 0.99))
    except Exception:
        thr = 0.50
    try:
        sg_level = int(np.clip(round(float(sg_level)), 0, 30))
    except Exception:
        sg_level = 0

    t = np.asarray(t_px, dtype=float)
    if t.ndim != 1 or t.size < 2:
        return None

    sx = float(sx) if np.isfinite(sx) and sx > 0 else 1.0
    sy = float(sy) if np.isfinite(sy) and sy > 0 else 1.0

    # Raw average profile is authoritative for the raw/core intensity.
    raw_avg = np.asarray(average_profile, dtype=float) if average_profile is not None else None
    raw_core = np.nan
    if raw_avg is not None and raw_avg.size == t.size:
        ci = int(np.argmin(np.abs(t)))
        if np.isfinite(raw_avg[ci]):
            raw_core = float(raw_avg[ci])

    angle_keys = sorted([float(a) for a in profiles.keys()])
    canonical = [float(a) for a in np.arange(0.0, 360.0, 30.0)]
    if all(a in profiles for a in canonical):
        angle_keys = canonical

    # If the raw average is unavailable, use the mean of the 12 center samples
    # only as a fallback.  Do NOT independently normalize each radial profile.
    if not np.isfinite(raw_core) or abs(raw_core) <= 1e-12:
        centers = []
        for ang in angle_keys:
            p = np.asarray(profiles[float(ang)], dtype=float)
            n = min(p.size, t.size)
            if n < 2:
                continue
            z = int(np.argmin(np.abs(t[:n])))
            if np.isfinite(p[z]):
                centers.append(float(p[z]))
        if centers:
            raw_core = float(np.nanmean(centers))

    if not np.isfinite(raw_core) or abs(raw_core) <= 1e-12:
        return None

    # True 0-to-1 D-Fit normalization:
    # baseline/background = 0 and particle core = 1.
    # Dividing only by the core would leave a non-zero background and move
    # the 0.50 crossing outward, artificially inflating the diameter.
    if raw_avg is not None and raw_avg.size == t.size:
        baseline_intensity = float(np.nanmin(raw_avg))
    else:
        all_vals = []
        for ang in angle_keys:
            pp = np.asarray(profiles[float(ang)], dtype=float)
            vv = pp[np.isfinite(pp)]
            if vv.size:
                all_vals.append(vv)
        baseline_intensity = (
            float(np.nanmin(np.concatenate(all_vals)))
            if all_vals else np.nan
        )

    if not np.isfinite(baseline_intensity) or raw_core <= baseline_intensity + 1e-12:
        return None

    normalization_span = float(raw_core - baseline_intensity)
    radial_rows = []
    radial_norm = {}

    for ang in angle_keys:
        p = np.asarray(profiles[float(ang)], dtype=float)
        n = min(p.size, t.size)
        if n < 2:
            continue

        theta = np.deg2rad(float(ang))
        step_nm = float(np.hypot(sx*np.cos(theta), sy*np.sin(theta)))
        xr = t[:n] * step_nm
        yr = p[:n]

        pm = np.isfinite(xr) & (xr >= -1e-12) & np.isfinite(yr)
        xr = xr[pm]
        yr = yr[pm]
        if xr.size < 2:
            continue

        oo = np.argsort(xr)
        xr = xr[oo]
        yr = yr[oo]

        iz = int(np.argmin(np.abs(xr)))

        # All 12 directions use the SAME frame baseline and core.
        yn = (yr - baseline_intensity) / normalization_span

        # Enforce the common normalized core exactly at 1.0.
        yn[iz] = 1.0

        crossing = _tab10_11_find_crossing(xr, yn, thr, side='right')

        radial_norm[float(ang)] = (xr, yn)
        radial_rows.append({
            'angle_deg': float(ang),
            'threshold': float(thr),
            'threshold_relative_intensity': float(thr),
            'threshold_intensity': float(thr),
            'radius_nm': float(crossing) if np.isfinite(crossing) else np.nan,
            'diameter_nm': np.nan,
            'crossing_x_nm': float(crossing) if np.isfinite(crossing) else np.nan,
            'crossing_y': float(thr),
            'core_raw_intensity': float(raw_core),
            'baseline_raw_intensity': float(baseline_intensity),
            'core_normalized_intensity': 1.0,
        })

    if not radial_rows:
        return None

    # Six opposite pairs.
    row_by_angle = {round(float(r['angle_deg']) % 360.0, 6): r for r in radial_rows}
    pair_rows = []
    diameter_values = []
    pair_angles = []

    for a in [0.0, 30.0, 60.0, 90.0, 120.0, 150.0]:
        b = (a + 180.0) % 360.0
        ra = row_by_angle.get(round(a, 6))
        rb = row_by_angle.get(round(b, 6))
        if ra is None or rb is None:
            continue

        r1 = float(ra['radius_nm'])
        r2 = float(rb['radius_nm'])
        d = r1 + r2 if np.isfinite(r1) and np.isfinite(r2) else np.nan

        ra['diameter_nm'] = d
        rb['diameter_nm'] = d

        pair_rows.append({
            'angle_deg': a,
            'opposite_angle_deg': b,
            'radius_1_nm': r1,
            'radius_2_nm': r2,
            'diameter_nm': d
        })

        if np.isfinite(d):
            diameter_values.append(d)
            pair_angles.append(a)

    diameter_values = np.asarray(diameter_values, dtype=float)
    six_diam_mean = float(np.nanmean(diameter_values)) if diameter_values.size else np.nan
    six_diam_sd = (
        float(np.std(diameter_values, ddof=1))
        if diameter_values.size >= 2
        else (0.0 if diameter_values.size == 1 else np.nan)
    )

    # Construct six full diameter profiles using the SAME normalized core.
    full_profiles = []
    common_pos = None

    for a in pair_angles:
        b = (a + 180.0) % 360.0
        A = radial_norm.get(float(a))
        B = radial_norm.get(float(b))
        if A is None or B is None:
            continue

        xa, ya = A
        xb, yb = B
        max_common = min(float(np.nanmax(xa)), float(np.nanmax(xb)))
        if not np.isfinite(max_common) or max_common <= 0:
            continue

        ngrid = max(200, min(len(xa), len(xb)))
        pos = np.linspace(0.0, max_common, ngrid)

        yA = np.interp(pos, xa, ya)
        yB = np.interp(pos, xb, yb)

        # Negative side = opposite radial direction; positive side = a.
        full = np.concatenate((yB[:0:-1], yA))
        full_profiles.append(full)

        if common_pos is None:
            common_pos = pos

    if not full_profiles or common_pos is None:
        return None

    full_profiles = np.vstack(full_profiles)
    avg_norm = np.nanmean(full_profiles, axis=0)

    # Keep every normalized full diameter-line profile for export.
    diameter_profile_dict = {}
    for k, a in enumerate(pair_angles):
        if k < len(full_profiles):
            diameter_profile_dict[float(a)] = np.asarray(full_profiles[k], dtype=float)
    t_avg = np.concatenate((-common_pos[:0:-1], common_pos))

    cidx = int(np.argmin(np.abs(t_avg)))
    avg_norm[cidx] = 1.0

    # Optional SG smoothing is applied to the averaged normalized D-Fit line
    # before locating user-threshold crossings. This keeps threshold mode
    # consistent with the displayed SG-smoothed average profile.
    sg_window = 0
    if sg_level > 0 and avg_norm.size >= 5:
        sg_window = min(2 * sg_level + 1, avg_norm.size if avg_norm.size % 2 else avg_norm.size - 1)
        if sg_window >= 5:
            try:
                avg_norm = savgol_filter(avg_norm, sg_window, 2, mode='interp')
                avg_norm[cidx] = 1.0
            except Exception:
                sg_window = 0

    # D-Fit points for the averaged six-line profile.
    left_d = _tab10_11_find_crossing(t_avg, avg_norm, thr, side='left')
    right_d = _tab10_11_find_crossing(t_avg, avg_norm, thr, side='right')

    avg_diameter = (
        right_d - left_d
        if np.isfinite(left_d) and np.isfinite(right_d)
        else six_diam_mean
    )

    return {
        'threshold': float(thr),
        'threshold_relative_intensity': float(thr),
        'threshold_intensity': float(thr),
        'background': float(fit_background) if np.isfinite(fit_background) else np.nan,
        'amplitude': float(fit_amplitude) if np.isfinite(fit_amplitude) else np.nan,
        'measurements': radial_rows,
        'pair_measurements': pair_rows,
        'core_intensity': float(raw_core),
        'baseline_intensity': float(baseline_intensity),
        'normalization_span': float(normalization_span),
        'valid_count': int(np.sum(np.isfinite([r['radius_nm'] for r in radial_rows]))),
        'radial_dfit_sd_nm': six_diam_sd,
        'normalized_average_profile': np.asarray(avg_norm, dtype=float),
        'normalized_average_t_nm': np.asarray(t_avg, dtype=float),
        'radial_normalized_profiles': {
            float(a): (np.asarray(radial_norm[float(a)][0], dtype=float),
                       np.asarray(radial_norm[float(a)][1], dtype=float))
            for a in radial_norm
        },
        'diameter_profile_t_nm': np.asarray(t_avg, dtype=float),
        'diameter_profiles': diameter_profile_dict,
        'normalized_profile_min': float(np.nanmin(avg_norm)),
        'normalized_profile_max': float(np.nanmax(avg_norm)),
        'normalized_threshold': float(thr),
        'normalized_left_intercept_nm': float(left_d) if np.isfinite(left_d) else np.nan,
        'normalized_right_intercept_nm': float(right_d) if np.isfinite(right_d) else np.nan,
        'normalized_left_raw_intensity': np.nan,
        'normalized_right_raw_intensity': np.nan,
        'avg_diameter_nm': float(avg_diameter) if np.isfinite(avg_diameter) else np.nan,
        'six_pair_mean_diameter_nm': six_diam_mean,
        'sg_level': int(sg_level),
        'sg_window_points': int(sg_window),
        'diameter_method': (
            '12 radial profiles normalized by one common frame-core intensity; '
            'six opposite-pair diameters; average of six full normalized diameter profiles'
        ),
        'sd_diameter_nm': six_diam_sd,
        'fit_left_intercept_nm': float(left_d) if np.isfinite(left_d) else np.nan,
        'fit_right_intercept_nm': float(right_d) if np.isfinite(right_d) else np.nan,
    }


def _tab10_render_current(self, idx=None):
    """Refresh all four Tab-10 panels for the selected confirmed ROI4 frame."""
    if _ii2d_enabled(self,10):return _ii2d_render_safe(self,10,idx)
    if getattr(self, '_tab10_roi4_stack', None) is None:
        return
    n = len(self._tab10_roi4_stack)
    if n <= 0:
        return
    if idx is None:
        idx = int(self.tab10_frame_var.get())
    idx = max(0, min(int(idx), n - 1))
    crop = _tab10_get_crop(self, idx)
    if crop is None:
        return

    sx, sy = self._tab10_roi4_scale
    center = _tab10_display_center(self, crop, idx)
    cx, cy = float(center['x0']), float(center['y0'])
    angles = _tab10_active_angles(self)
    field = _tab10_intensity_field(self, idx)

    # Panel 1: exact ROI4 crop from Tab 9, rebased to local 0..FOV nm.
    # Remove the previous colorbar before clearing the image axis so repeated
    # frame changes/FIT/TRACK operations never accumulate colorbar axes.
    if getattr(self, '_tab10_cbar_image', None) is not None:
        try: self._tab10_cbar_image.remove()
        except Exception: pass
        self._tab10_cbar_image = None
    self._tab10_stop_requested = False
    self.tab10_ax_image.clear()
    cmap = getattr(self, '_tab10_roi4_display_cmap', getattr(self, '_tab9_roi1_cmap', 'gray'))
    clim = getattr(self, '_tab10_roi4_display_clim', getattr(self, '_tab9_roi1_clim', (0.0, 1.0)))
    self.tab10_ax_image.imshow(
        crop, cmap=cmap, origin='lower',
        extent=(0.0, crop.shape[1] * sx, 0.0, crop.shape[0] * sy),
        vmin=clim[0], vmax=clim[1], interpolation='nearest', aspect='equal'
    )
    self.tab10_ax_image.plot(cx * sx, cy * sy, marker='+', markersize=16,
                             markeredgewidth=2.5, linestyle='None', label='Fixed center')
    rmax = 2.0 * max(1.0, min(cx, crop.shape[1] - 1 - cx, cy, crop.shape[0] - 1 - cy))
    tline = np.array([-rmax, rmax], dtype=float)
    for angle in angles:
        th = np.deg2rad(float(angle))
        self.tab10_ax_image.plot((cx + tline*np.cos(th))*sx,
                                 (cy + tline*np.sin(th))*sy,
                                 linewidth=1.5, label=f'{angle:g}°')

    if bool(getattr(self, 'tab10_dfit_var', None) is not None and self.tab10_dfit_var.get()):
        # D-Fit display: always show the 12 radial lines immediately when D-Fit
        # is enabled. No D-Fit calculation is performed here.
        # Crossing markers are added only when a user has explicitly run FIT
        # CURRENT ROI or TRACK-SELECTED FRAMES.
        fit_result = getattr(self, '_tab10_last_fit', None)
        if isinstance(fit_result, dict) and int(fit_result['frame']) != idx:
            fit_result = None
        measurements = (fit_result or {}).get('dfit_measurements', []) if isinstance(fit_result, dict) else []
        sg_level = int((fit_result or {}).get('dfit_sg_level', self.tab10_dfit_sg_level_var.get())) if isinstance(fit_result, dict) else int(self.tab10_dfit_sg_level_var.get())
        # Exactly ONE D-Fit point per radial direction: 12 points total.
        # Each point is the strongest valid outward particle-to-background
        # gradient edge after Savitzky–Golay smoothing.
        for m in measurements:
            rr = float(m.get('radius_nm', np.nan)); aa = float(m.get('angle_deg', np.nan))
            if not (np.isfinite(rr) and np.isfinite(aa)):
                continue
            th = np.deg2rad(aa)
            # rr is a TRUE physical radial distance (nm). Convert the radial
            # vector directly to the displayed X/Y nm axes. Do NOT divide by
            # sqrt(sx*sy), because that would distort the threshold location
            # whenever sx != sy.
            x_nm = cx*sx + rr*np.cos(th)
            y_nm = cy*sy + rr*np.sin(th)
            self.tab10_ax_image.plot(x_nm, y_nm,
                                     marker='o',markersize=5.0,markerfacecolor='none',
                                     markeredgecolor='red',markeredgewidth=1.5,linestyle='None',zorder=25)
        self.tab10_ax_image.text(0.02,0.98,
                                 f'D-Fit: radial gradient edge | SG = {sg_level}',
                                 transform=self.tab10_ax_image.transAxes,va='top',ha='left',fontsize=8,
                                 bbox=dict(facecolor='black',alpha=0.28,edgecolor='none',pad=2),color='white',zorder=26)
        self.tab10_ax_image.legend(fontsize=7, loc='best')
    self.tab10_ax_image.set_title(f'ROI — Frame {idx + 1}/{n} | {_analysis_field_label(field)}')
    self.tab10_ax_image.set_xlabel('X (nm)'); self.tab10_ax_image.set_ylabel('Y (nm)')
    self.tab10_ax_image.set_xlim(0, crop.shape[1]*sx); self.tab10_ax_image.set_ylim(0, crop.shape[0]*sy)
    self.tab10_ax_image.set_aspect('equal', adjustable='box'); self.tab10_ax_image.grid(alpha=0.15)
    try:
        im = self.tab10_ax_image.images[-1]
        self._tab10_cbar_image = self.tab10_fig.colorbar(im, ax=self.tab10_ax_image, fraction=0.046, pad=0.04)
        self._tab10_cbar_image.set_label('Intensity')
    except Exception:
        self._tab10_cbar_image = None

    # Panel 2: individual full profiles + BLACK average.
    t_px, profiles, avg = _tab10_extract_profiles(self, crop, cx, cy, angles)
    sline = float(np.sqrt(sx*sy)) if sx > 0 and sy > 0 else 1.0
    t_nm = np.asarray(t_px, dtype=float) * sline
    self.tab10_ax_profiles.clear()
    if bool(getattr(self, 'tab10_dfit_var', None) is not None and self.tab10_dfit_var.get()):
        # In D-Fit mode, use the true physical distance along each radial line.
        # This avoids the old sqrt(sx*sy) approximation that caused the plotted
        # threshold point to disagree with the nm scale for oblique directions.
        for angle in angles:
            th_a = np.deg2rad(float(angle))
            step_a = float(np.hypot(sx*np.cos(th_a), sy*np.sin(th_a))) if sx > 0 and sy > 0 else 1.0
            self.tab10_ax_profiles.plot(np.asarray(t_px,float)*step_a, profiles[float(angle)], linewidth=1.2, label=f'{angle:g}°')
        self.tab10_ax_profiles.plot(t_nm, avg, color='black', linewidth=2.8, label='Average')
    else:
        for angle in angles:
            self.tab10_ax_profiles.plot(t_nm, profiles[float(angle)], linewidth=1.2, label=f'{angle:g}°')
        self.tab10_ax_profiles.plot(t_nm, avg, color='black', linewidth=2.8, label='Average')
    self.tab10_ax_profiles.axvline(0.0, linestyle='--', linewidth=1.0)
    self.tab10_ax_profiles.set_aspect('auto', adjustable='box')
    try: self.tab10_ax_profiles.set_box_aspect(None)
    except (AttributeError, TypeError): pass
    profile_x = np.concatenate([np.asarray(line.get_xdata(), float) for line in self.tab10_ax_profiles.lines if len(line.get_xdata())])
    profile_x = profile_x[np.isfinite(profile_x)]
    if profile_x.size:
        xlo, xhi = float(np.min(profile_x)), float(np.max(profile_x))
        xpad = max(0.03*(xhi-xlo), float(np.nanmedian(np.diff(np.unique(profile_x)))) if np.unique(profile_x).size > 1 else 1.0)
        self.tab10_ax_profiles.set_xlim(xlo-xpad, xhi+xpad)
    self.tab10_ax_profiles.set_title(f'Selected Line Profiles')
    self.tab10_ax_profiles.set_xlabel('Position from fixed center (nm)'); self.tab10_ax_profiles.set_ylabel('Intensity (a.u.)')
    self.tab10_ax_profiles.legend(fontsize=7, loc='upper right', ncol=2); self.tab10_ax_profiles.grid(alpha=0.2)
    self.tab10_fig.subplots_adjust(wspace=0.34, left=0.07, right=0.96, bottom=0.08, top=0.94)

    # Keep Panel 3 clean until a fit is requested.
    if getattr(self, '_tab10_last_fit', None) is None:
        self.tab10_ax_fit.clear()
        self.tab10_ax_fit.set_title('Average full profile + fixed-center 1D Gaussian')
        self.tab10_ax_fit.set_xlabel('Position from fixed center (nm)'); self.tab10_ax_fit.set_ylabel('Intensity (a.u.)')
        self.tab10_ax_fit.grid(alpha=0.2)

    # Panel 4 is intentionally refreshed only by FIT/TRACK so that a frame
    # change does not destroy an already completed tracking plot.
    self.tab10_frame_var.set(idx)
    try:
        n = len(self._tab10_roi4_stack)
        field = float(_tab10_intensity_field(self, idx))
        self.tab10_frame_label_var.set(
            f'Frame No. {idx + 1}/{n} | Equivalent Field: {field:+.2f} mT'
        )
        self.tab10_frame_info_var.set(
            f'Frame No. {idx + 1}/{n} | Equivalent Field: {field:+.2f} mT'
        )
    except Exception:
        pass
    _tab10_update_fit_parameters(self, center=center, message='Center calculated; Gaussian fit not performed.')
    self.tab10_canvas.draw_idle()




def _tab10_sync_frame_range_controls(self, n=None):
    """Keep TAB 10 frame/range controls 1-based while tracking stays 0-based internally."""
    try:
        if n is None:
            n = len(self._tab10_roi4_stack)
        n = max(1, int(n))
    except Exception:
        n = 1

    try:
        start0 = int(self.tab10_start_var.get())
    except Exception:
        start0 = 0
    try:
        end0 = int(self.tab10_end_var.get())
    except Exception:
        end0 = n - 1

    start0 = max(0, min(start0, n - 1))
    end0 = max(0, min(end0, n - 1))
    if start0 > end0:
        start0, end0 = end0, start0

    self.tab10_start_var.set(start0)
    self.tab10_end_var.set(end0)

    try:
        self.tab10_start_display_var.set(str(start0 + 1))
        self.tab10_end_display_var.set(str(end0 + 1))
        self.tab10_start_spin.configure(from_=1, to=n, increment=1)
        self.tab10_end_spin.configure(from_=1, to=n, increment=1)
    except Exception:
        pass


def _tab10_range_spinbox_changed(self, which=None, event=None):
    """Apply a manually entered or arrow-changed 1-based frame range."""
    try:
        n = len(self._tab10_roi4_stack)
    except Exception:
        n = 0
    if n <= 0:
        return

    def parse(var, fallback):
        try:
            return int(round(float(var.get())))
        except Exception:
            return fallback

    start = parse(self.tab10_start_display_var, int(self.tab10_start_var.get()) + 1)
    end = parse(self.tab10_end_display_var, int(self.tab10_end_var.get()) + 1)

    start = max(1, min(start, n))
    end = max(1, min(end, n))

    if start > end:
        if which == 'start':
            start = end
        elif which == 'end':
            end = start
        else:
            start, end = end, start

    self.tab10_start_display_var.set(str(start))
    self.tab10_end_display_var.set(str(end))
    self.tab10_start_var.set(start - 1)
    self.tab10_end_var.set(end - 1)


def _tab10_frame_changed(self, value=None):
    if _ii2d_enabled(self,10):return _ii2d_frame_changed(self,10,value)
    try:
        idx = int(round(float(value))) if value is not None else int(self.tab10_frame_var.get())
    except Exception:
        idx = int(self.tab10_frame_var.get())
    if getattr(self, '_tab10_programmatic', False):
        return
    self._tab10_programmatic = True
    try:
        if getattr(self, '_tab10_roi4_stack', None) is None:
            _tab10_sync_roi4_from_tab9(self, preserve_frame=True)
        if getattr(self, '_tab10_roi4_stack', None) is not None:
            n = len(self._tab10_roi4_stack)
            idx = max(0, min(idx, n - 1))
            self.tab10_frame_var.set(idx)
            try:
                self.tab10_frame_label_var.set(
                    f'Frame No. {idx + 1}/{n} | Equivalent Field: '
                    f'{float(_tab10_intensity_field(self, idx)):+.6g} mT'
                )
                self.tab10_frame_info_var.set(
                    f'Frame No. {idx + 1}/{n} | Equivalent Field: '
                    f'{float(_tab10_intensity_field(self, idx)):+.6g} mT'
                )
            except Exception:
                pass
            self._tab10_last_fit = None
            _tab10_render_current(self, idx)
            _tab10_update_fit_parameters(
                self, message='Frame changed — fit current ROI4 when ready.'
            )
            self.tab10_fit_status_var.set(
                'Frame changed — fit current ROI4 when ready.'
            )
            if self._tab10_center_follow_enabled:
                self.tab10_fit_status_var.set('Detecting selected core and recalculating this frame...')
                _tab10_queue_center_follow(self)
    finally:
        self._tab10_programmatic = False



def _tab10_cancel_center_follow_job(self):
    job = getattr(self, '_tab10_center_follow_job', None)
    if job:
        self.root.after_cancel(job)
    self._tab10_center_follow_job = None


def _tab10_reset_center_follow(self):
    _tab10_cancel_center_follow_job(self)
    self._tab10_center_follow_enabled = False
    self._tab10_center_anchor = None
    self._tab10_follow_centers = {}
    self.tab10_fix_center_button.configure(text='FIX CENTER')
    self.tab10_center_follow_status_var.set('Recalculate center, then Fix Center to follow this core.')


def _tab10_toggle_fix_center(self):
    if _ii2d_enabled(self,10):return _ii2d_run(self,10)
    if self._tab10_ii_busy:
        return
    if self._tab10_center_follow_enabled:
        _tab10_reset_center_follow(self)
        _tab10_clear_intensity_source(self)
        self.tab10_fit_status_var.set('Center tracking released.')
        return
    if self._tab10_roi4_stack is None:
        if not _tab10_sync_roi4_from_tab9(self, preserve_frame=True):
            return
    frame = int(self.tab10_frame_var.get())
    crop = _tab10_get_crop(self, frame)
    seed = getattr(self, '_tab10_center_cache', None)
    if not isinstance(seed, dict):
        seed = _tab10_center(self, crop)
    self._tab10_center_anchor = dict(seed)
    self._tab10_center_follow_enabled = True
    detected, center = _tab10_follow_core(self, crop, frame)
    if not detected:
        _tab10_reset_center_follow(self)
        self.tab10_center_follow_status_var.set('No core detected here. Select a clear frame and recalculate center.')
        return
    self._tab10_center_cache = dict(center)
    _tab10_clear_intensity_source(self)
    self.tab10_fix_center_button.configure(text='RELEASE CENTER')
    _tab10_fit_current(self)


def _tab10_follow_core(self, crop, frame):
    # The anchor identifies the selected particle; the fitted center moves per frame.
    old_fixed = getattr(self, '_tab10_tracking_fixed_center', None)
    old_previous = getattr(self, '_tab10_last_detected_core', None)
    self._tab10_tracking_fixed_center = dict(self._tab10_center_anchor)
    # A slider jump must give the same result regardless of the browsing order.
    self._tab10_last_detected_core = None
    try:
        detected, core = _tab10_detect_with_diagnostics(self, crop, frame)
    finally:
        self._tab10_tracking_fixed_center = old_fixed
        self._tab10_last_detected_core = old_previous
    if not detected:
        self._tab10_follow_centers.pop(int(frame), None)
        self.tab10_center_follow_status_var.set(f'Frame {frame+1}: selected core not detected; no center substituted.')
        return False, None
    # Refine the validated peak to the connected core's contrast-weighted center.
    center = _particle_focus_center(crop, self.tab10_contrast_fraction_var.get(), reference=core)
    if center['peak'] <= 0 or center['sign'] != core['sign']:
        center = dict(core)
    center.update({key:core[key] for key in ('snr', 'prominence', 'scale')})
    self._tab10_follow_centers[int(frame)] = dict(center)
    self._tab10_detection_diagnostics[int(frame)].update(
        detection_x_px=float(center['x0']), detection_y_px=float(center['y0']))
    self.tab10_center_follow_status_var.set(
        f'Core fixed | Frame {frame+1}: center ({center["x0"]:.3f}, {center["y0"]:.3f}) px; auto-follow ON')
    return True, center


def _tab10_queue_center_follow(self):
    _tab10_cancel_center_follow_job(self)
    source = self._tab10_roi4_stack
    frame = int(self.tab10_frame_var.get())
    def calculate():
        self._tab10_center_follow_job = None
        if (not self._tab10_center_follow_enabled or source is not self._tab10_roi4_stack
                or frame != int(self.tab10_frame_var.get())):
            return
        if self._tab10_ii_busy:
            self._tab10_center_follow_job = self.root.after(150, calculate)
            return
        _tab10_fit_current(self, preserve_tracking=True)
    self._tab10_center_follow_job = self.root.after(150, calculate)


def _tab10_recalculate_center(self):
    if _ii2d_enabled(self,10):return _ii2d_run(self,10)
    if self._tab10_ii_busy:
        return
    if getattr(self, '_tab10_roi4_stack', None) is None:
        if not _tab10_sync_roi4_from_tab9(self, preserve_frame=True):
            return
    try:
        _tab10_reset_center_follow(self)
        frame=int(self.tab10_frame_var.get())
        crop=_tab10_get_crop(self,frame)
        center=_tab10_center(self,crop)
        self._tab10_center_cache=center
        _tab10_update_fit_parameters(self, center=center, message='Center recalculated; Gaussian fit not performed.')
        _tab10_clear_intensity_source(self)
        if self.tab10_integrated_intensity_var.get():
            _tab10_fit_current(self)
            return
        _tab10_render_current(self,frame)
        self.tab10_fit_status_var.set(f'✓ Center recalculated | ({center["x0"]:.3f}, {center["y0"]:.3f}) px local')
    except Exception as exc:
        messagebox.showerror('Tab 10 Center', str(exc), parent=self.root)



def _tab10_draw_fit_result(self, result):
    if getattr(self,'_tab10_fit_residual_ax',None) is not None:
        try:self._tab10_fit_residual_ax.remove()
        except Exception:pass
        self._tab10_fit_residual_ax=None
    self.tab10_ax_fit.clear()
    _ii2d_prepare_line_axis(self.tab10_ax_fit)
    t=np.asarray(result['t_nm'],float); avg=np.asarray(result['average_profile'],float)
    if result.get('core_detected') is False:
        self.tab10_ax_fit.plot(t, avg, color='black', label='Average full profile')
        self.tab10_ax_fit.set_title('Core not detected - no Gaussian / D-fit')
        self.tab10_ax_fit.set_xlabel('Position from reference center (nm)')
        self.tab10_ax_fit.set_ylabel('Intensity (a.u.)')
        self.tab10_ax_fit.legend(fontsize=8)
        self.tab10_canvas.draw_idle()
        return
    if bool(self.tab10_dfit_var.get()):
        # D-FIT mode: raw radial profiles on Y1; SG-smoothed normalized
        # average of the six diameter lines on Y2. Boundary is defined by
        # the radial gradient edge, not by a user intensity threshold.
        for angle in result['angles']:
            th_a = np.deg2rad(float(angle))
            step_a = float(np.hypot(result.get('dfit_scale_x_nm_per_px',1.0)*np.cos(th_a),
                                    result.get('dfit_scale_y_nm_per_px',1.0)*np.sin(th_a)))
            self.tab10_ax_fit.plot(np.asarray(result['t_px'],float)*step_a,
                                   result['profiles'][float(angle)], linewidth=0.9, alpha=0.58,
                                   label=f'{angle:g}°')
        self.tab10_ax_fit.plot(t,avg,color='black',linewidth=2.5,label='Avg. line profile')
        ra=self.tab10_ax_fit.twinx(); self._tab10_fit_residual_ax=ra
        norm_avg=np.asarray(result.get('dfit_normalized_average_profile',np.full_like(t,np.nan)),float)
        norm_t=np.asarray(result.get('dfit_average_profile_t_nm',t),float)
        if norm_avg.shape==norm_t.shape:
            ra.plot(norm_t,norm_avg,color='purple',linewidth=2.0,label='SG-smoothed')
        left=float(result.get('dfit_left_intercept_nm',np.nan)); right=float(result.get('dfit_right_intercept_nm',np.nan))
        if np.isfinite(left) and np.isfinite(right):
            threshold_mode = bool(result.get('dfit_threshold_mode', False))
            threshold_value = float(result.get('dfit_threshold', np.nan)) if threshold_mode else 0.0
            if threshold_mode and np.isfinite(threshold_value):
                ra.axhline(threshold_value, color='gray', linestyle='--', linewidth=1.0, zorder=12,
                           label=f'Threshold = {threshold_value:.2f}')
            guide_y = threshold_value if threshold_mode and np.isfinite(threshold_value) else 0.0
            ra.plot([left,right],[guide_y,guide_y],color='green',linewidth=1.5,solid_capstyle='round',zorder=18,
                    label=f'Diameter = {right-left:.4g} nm')
            vals = np.interp([left,right], norm_t, norm_avg) if norm_t.size==norm_avg.size else [np.nan,np.nan]
            if np.all(np.isfinite(vals)):
                ra.plot([left,right],vals,'o',ms=5.5,markerfacecolor='red',markeredgecolor='black',
                        markeredgewidth=0.7,zorder=20,
                        label='Threshold crossing points' if threshold_mode else 'Edge points')
        sg_level=int(result.get('dfit_sg_level',self.tab10_dfit_sg_level_var.get()))
        ra.set_ylabel('Normalized Intensity (a.u.)')
        self.tab10_ax_fit.axvline(0.0,color='gray',linestyle=':',linewidth=1.0,label='Center')
        self.tab10_ax_fit.set_title('Avg. line profile — D-Fit (radial gradient edge)')
        self.tab10_ax_fit.set_xlabel('Position from fixed center (nm)'); self.tab10_ax_fit.set_ylabel('Intensity (a.u.)'); self.tab10_ax_fit.grid(alpha=0.2)
        h1,l1=self.tab10_ax_fit.get_legend_handles_labels(); h2,l2=ra.get_legend_handles_labels()
        self.tab10_ax_fit.legend(h1+h2,l1+l2,fontsize=7,loc='best')
    else:
        self.tab10_ax_fit.plot(t,avg,color='black',linewidth=1.7,label='Average full profile')
        self.tab10_ax_fit.plot(t,result['fit_profile'],color='blue',linewidth=2.3,linestyle='--',label='Fixed-center Gaussian fit')
        ra=self.tab10_ax_fit.twinx(); self._tab10_fit_residual_ax=ra
        ra.plot(t,result['residual_profile'],linestyle=':',linewidth=1.2,label='Residual')
        ra.axhline(0.0,linestyle='--',linewidth=0.8); ra.set_ylabel('Residual')
        self.tab10_ax_fit.axvline(0.0,linestyle=':',linewidth=1.0); self.tab10_ax_fit.set_title(f'Average of {len(result["angles"])} Lines - Gaussian Fit'); self.tab10_ax_fit.set_xlabel('Position from fixed center (nm)'); self.tab10_ax_fit.set_ylabel('Intensity (a.u.)'); self.tab10_ax_fit.grid(alpha=0.2)
        h1,l1=self.tab10_ax_fit.get_legend_handles_labels(); h2,l2=ra.get_legend_handles_labels(); self.tab10_ax_fit.legend(h1+h2,l1+l2,fontsize=8,loc='best')


def _tab10_fit_current(self, preserve_tracking=False):
    if _ii2d_enabled(self,10):return _ii2d_run(self,10)
    _tab10_cancel_center_follow_job(self)
    if self._tab10_ii_busy:
        return
    job = self._tab10_ii_recalculate_job
    if job:
        self.root.after_cancel(job)
        self._tab10_ii_recalculate_job = None
    preview_tracking = preserve_tracking and self._tab10_ii_scope == 'tracking'
    self._tab10_ii_scope = 'current'
    self._tab10_ii_busy = True
    self._tab10_ii_dirty = False
    if not preview_tracking:
        self._tab10_intensity_profiles = {}
        self._tab10_tracking_profiles = {}
    try:
        self._tab10_stop_requested = False
        if getattr(self,'_tab10_roi4_stack',None) is None:
            if not _tab10_sync_roi4_from_tab9(self,preserve_frame=True):return
        try:
            frame=max(0,min(int(self.tab10_frame_var.get()),len(self._tab10_roi4_stack)-1))
            _analysis_progress_update(self, 10, 0)
            result=_tab10_fit_roi4(self,frame)
            self._tab10_last_fit=result
            _tab10_render_current(self,frame)
            _tab10_draw_fit_result(self, result)
            row = _tab10_numeric_result(result)
            if preview_tracking and isinstance(self._tab10_tracking_df, pd.DataFrame):
                df = self._tab10_tracking_df
                self._tab10_tracking_df = pd.concat([df[df.frame != frame], pd.DataFrame([row])], ignore_index=True).sort_values('frame')
                if result.get('core_detected') is False:
                    self._tab10_tracking_profiles.pop(frame, None)
                else:
                    self._tab10_tracking_profiles[frame] = dict(result,
                        gaussian_fit=np.asarray(result['fit_profile']).copy(),
                        gaussian_fwhm=result['fwhm'], gaussian_fwhm_sd=result['fwhm_err'],
                        dfit_diameter=result.get('diameter_nm',np.nan),
                        dfit_diameter_sd=result.get('diameter_err_nm',np.nan))
                _tab10_plot_tracking(self,self._tab10_tracking_df,int(self.tab10_start_var.get()),int(self.tab10_end_var.get()),draw_now=False)
            else:
                self._tab10_tracking_df = pd.DataFrame([row])
                _tab10_plot_tracking(self,self._tab10_tracking_df,frame,frame,draw_now=False)
            _tab10_update_fit_parameters(self,result=result)
            if result.get('core_detected') is False: self.tab10_fit_status_var.set(f'Frame {frame+1}: core not detected; ' + ('size set to zero' if self.tab10_zero_if_undetected_var.get() else 'fit unavailable') + ', no Gaussian/D-fit performed.')
            elif bool(self.tab10_dfit_var.get()): self.tab10_fit_status_var.set(f'✓ D-Fit | Frame {frame+1}/{len(self._tab10_roi4_stack)} | Diameter={result.get("diameter_nm",np.nan):.6g} nm | SD={result.get("diameter_err_nm",np.nan):.6g} nm | Valid radial edges={result.get("dfit_valid_count",0)}/12 | SG={result.get("dfit_sg_level",self.tab10_dfit_sg_level_var.get())} (window={result.get("dfit_sg_window_points",0)})')
            else: self.tab10_fit_status_var.set(f'✓ 1D-Gaussian Fit | Frame {frame+1}/{len(self._tab10_roi4_stack)} | FWHM={result["fwhm"]:.6g} nm | Amplitude={result["amplitude"]:.6g} | R²={result["r2"]:.6g}')
            _analysis_progress_update(self, 10, 1)
            _tab10_refresh_layout(self)
        except Exception as exc:
            self._tab10_last_fit = None
            error_row = dict(roi_index=4, frame=frame, field_mT=_tab10_intensity_field(self, frame), fwhm=np.nan, diameter_nm=np.nan, amplitude=np.nan, detection_status='error', detection_reason=str(exc))
            self._tab10_intensity_profiles.pop(frame, None)
            self._tab10_tracking_profiles.pop(frame, None)
            if preview_tracking and isinstance(self._tab10_tracking_df, pd.DataFrame):
                df = self._tab10_tracking_df
                self._tab10_tracking_df = pd.concat([df[df.frame != frame], pd.DataFrame([error_row])], ignore_index=True).sort_values('frame')
            else:
                self._tab10_tracking_df = pd.DataFrame([error_row])
            self.tab10_ax_fit.clear()
            self.tab10_ax_fit.set_title('Fit unavailable - see analysis status')
            _tab10_plot_tracking(self, self._tab10_tracking_df, frame, frame, draw_now=False)
            self.log(f'Tab 10 frame {frame+1} fit failed: {exc}')
            self.tab10_fit_status_var.set(f'✗ Fit failed: {type(exc).__name__}: {exc}')
            try:_tab10_update_fit_parameters(self,message=f'Fit failed: {type(exc).__name__}: {exc}')
            except Exception:pass
            messagebox.showerror('Tab 10 Fit',str(exc),parent=self.root)
    finally:
        self._tab10_ii_busy = False
        if preview_tracking:
            self._tab10_ii_scope = 'tracking'
        _tab10_sync_intensity_values(self)
        _tab10_plot_intensity(self)

def _tab10_use_all_frames(self):
    if not _tab10_roi4_available(self):
        messagebox.showwarning(
            'Tab 10',
            'Confirm ROI in Tab 9 first.',
            parent=self.root
        )
        return
    n = len(self._tab9_roi1_stack)
    self.tab10_start_var.set(0)
    self.tab10_end_var.set(max(0, n - 1))
    try:
        self.tab10_start_display_var.set('1')
        self.tab10_end_display_var.set(str(n))
        self.tab10_start_spin.configure(from_=1, to=n, increment=1)
        self.tab10_end_spin.configure(from_=1, to=n, increment=1)
    except Exception:
        pass
    self.tab10_frame_var.set(0)
    self.tab10_slider.set(0)
    try:
        field0 = float(_tab10_intensity_field(self, 0))
        self.tab10_frame_label_var.set(
            f'Frame No. 1/{n} | Equivalent Field: {field0:+.6g} mT'
        )
        self.tab10_frame_info_var.set(
            f'Frame No. 1/{n} | Equivalent Field: {field0:+.6g} mT'
        )
    except Exception:
        try: self.tab10_frame_label_var.set(f'Frame No. 1/{n} | Equivalent Field: —')
        except Exception: pass
    _tab10_render_current(self, 0)
    self.tab10_fit_status_var.set(f'Frame range set to all frames: 0–{n - 1}.')


def _tab10_plot_tracking(self, df, start, end, draw_now=True):
    """Figure 4 driven by the two Plot-axis dropdown selections, with mode-aware defaults."""
    for attr in ('_tab10_ax_tracking2', '_tab10_tracking_secx'):
        old_ax = getattr(self, attr, None)
        if old_ax is not None:
            try: old_ax.remove()
            except Exception: pass
            setattr(self, attr, None)
    self.tab10_ax_tracking.clear()

    ax2 = self.tab10_ax_tracking.twinx(); self._tab10_ax_tracking2 = ax2

    y1_choice = str(getattr(getattr(self, 'tab10_plot_y1_var', None), 'get', lambda: 'Gaussian FWHM (nm)')())
    y2_choice = str(getattr(getattr(self, 'tab10_plot_y2_var', None), 'get', lambda: 'Gaussian Amplitude (a.u.)')())

    y1_map = {
        'Gaussian FWHM (nm)': ('fwhm', 'fwhm_err', 'Gaussian FWHM (nm)', 'Gaussian FWHM (nm)'),
        'D-Fit Diameter (nm)': ('diameter_nm', 'diameter_err_nm', 'D-Fit Diameter (nm)', 'D-Fit Diameter (nm)'),
    }
    y2_map = {
        'Gaussian Amplitude (a.u.)': ('amplitude', 'amplitude_err', 'Gaussian Amplitude (a.u.)', 'Gaussian Amplitude (a.u.)'),
        'Core Intensity (a.u.)': ('core_intensity', None, 'Core Intensity (a.u.)', 'Core Intensity (a.u.)'),
    }
    size_col, err_col, y1_label, y1_legend = y1_map.get(y1_choice, y1_map['Gaussian FWHM (nm)'])
    intensity_col, intensity_err_col, y2_label, y2_legend = y2_map.get(y2_choice, y2_map['Gaussian Amplitude (a.u.)'])

    if df is None or df.empty:
        self.tab10_ax_tracking.set_title(f'{y1_label} + {y2_label}')
        self.tab10_ax_tracking.set_xlabel('Equivalent Field (mT)')
        self.tab10_ax_tracking.set_ylabel(y1_label)
        ax2.set_ylabel(y2_label)
    else:
        data = df.copy()
        for col in ('field_mT','frame','fwhm','fwhm_err','diameter_nm','diameter_err_nm','amplitude','amplitude_err','core_intensity'):
            if col in data.columns: data[col] = pd.to_numeric(data[col], errors='coerce')
        frame_axis = _tracking_frame_axis(data)
        x = data['frame'].to_numpy(float)+1 if frame_axis else data['field_mT'].to_numpy(float)
        y=data.get(size_col,pd.Series(np.nan,index=data.index)).to_numpy(float)
        ye=pd.to_numeric(data.get(err_col,pd.Series(np.zeros(len(data)),index=data.index)),errors='coerce').fillna(0).to_numpy(float) if err_col else np.zeros(len(data),dtype=float)
        yi=data.get(intensity_col,pd.Series(np.nan,index=data.index)).to_numpy(float)
        if intensity_err_col is not None:
            yie=pd.to_numeric(data.get(intensity_err_col,pd.Series(np.zeros(len(data)),index=data.index)),errors='coerce').fillna(0).to_numpy(float)
        else:
            yie=np.zeros(len(data),dtype=float)
        gy=np.isfinite(x)&np.isfinite(y)
        gi=np.isfinite(x)&np.isfinite(yi)
        if np.any(gy):
            self.tab10_ax_tracking.errorbar(x[gy],y[gy],yerr=ye[gy],marker='^',linestyle='-',color='black',linewidth=1.5,capsize=2,label=y1_legend)
        if np.any(gi):
            ax2.errorbar(x[gi],yi[gi],yerr=yie[gi],marker='o',linestyle='--',color='blue',linewidth=1.4,capsize=2,label=y2_legend)
        top=self.tab10_ax_tracking.twiny(); self._tab10_tracking_secx=top; top.set_xlim(self.tab10_ax_tracking.get_xlim())
        _tracking_top_axis(top, data, frame_axis)
        self.tab10_ax_tracking.set_title(f'{y1_label} + {y2_label} | frames {start+1}–{end+1}')
        self.tab10_ax_tracking.set_xlabel('Frame' if frame_axis else 'Field (mT)'); self.tab10_ax_tracking.set_ylabel(y1_label)
        ax2.set_ylabel(y2_label); ax2.yaxis.tick_right(); ax2.yaxis.set_label_position('right')
        self.tab10_ax_tracking.grid(alpha=0.2)
        h1,l1=self.tab10_ax_tracking.get_legend_handles_labels(); h2,l2=ax2.get_legend_handles_labels()
        if h1 or h2: self.tab10_ax_tracking.legend(h1+h2,l1+l2,fontsize=8,loc='best')
    _tab10_sync_intensity_values(self)
    _tab10_plot_intensity(self)
    _tab10_refresh_layout(self)
    if draw_now:
        try: self.tab10_canvas.draw(); self.root.update_idletasks()
        except Exception: pass


def _tab10_plot_axis_changed(self, *_args):
    """Redraw Figure 4 immediately after either Plot-axis dropdown changes."""
    try:
        df = getattr(self, '_tab10_tracking_df', None)
        start = int(self.tab10_start_var.get())
        end = int(self.tab10_end_var.get())
        if start > end: start, end = end, start
        _tab10_plot_tracking(self, df, start, end, draw_now=True)
    except Exception:
        try: self.tab10_canvas.draw_idle()
        except Exception: pass



def _tab10_track_all(self):
    if _ii2d_enabled(self,10):return _ii2d_run(self,10,tracking=True)
    _tab10_cancel_center_follow_job(self)
    if self._tab10_ii_busy:
        return
    job = self._tab10_ii_recalculate_job
    if job:
        self.root.after_cancel(job)
        self._tab10_ii_recalculate_job = None
    self._tab10_ii_scope = 'tracking'
    self._tab10_ii_busy = True
    self._tab10_ii_dirty = False
    self._tab10_intensity_profiles = {}
    self._tab10_detection_diagnostics = {}
    self._tab10_ii_current_result = None
    run_source = self._tab10_roi4_stack
    try:
        """
        TAB 10 TRACK-SELECTED FRAMES.

        Tracking sequence intentionally mirrors TAB 11 TRACK ALL ROIs:
            frame -> crop -> core detection -> fit only when detected.

        Only TAB 10 tracking is changed here. FIT CURRENT ROI, TAB 11,
        TAB 9, and all other functions/cells remain untouched.
        """
        if getattr(self, '_tab10_roi4_stack', None) is None:
            if not _tab10_sync_roi4_from_tab9(self, preserve_frame=True):
                return

        run_source = self._tab10_roi4_stack
        nframes = len(self._tab10_roi4_stack)
        if nframes <= 0:
            return

        # Reset the cooperative stop flag for this explicit tracking run.
        self._tab10_stop_requested = False

        start = max(0, min(int(self.tab10_start_var.get()), nframes - 1))
        end = max(0, min(int(self.tab10_end_var.get()), nframes - 1))
        if start > end:
            start, end = end, start

        # Read the option once for the complete tracking run, exactly as TAB 11.
        zero_mode = bool(
            getattr(self, 'tab10_zero_if_undetected_var', None) is not None
            and self.tab10_zero_if_undetected_var.get()
        )

        follow = self._tab10_center_follow_enabled
        # Keep an identity anchor; enabled center tracking refines every frame.
        # _tab10_center() itself is NOT modified.
        self._tab10_tracking_fixed_center = None
        # Sequential detector state: reset for each tracking run.
        self._tab10_last_detected_core = None
        if zero_mode or follow:
            try:
                cache = self._tab10_center_anchor if follow else getattr(self, '_tab10_center_cache', None)
                if isinstance(cache, dict):
                    self._tab10_tracking_fixed_center = dict(cache)
                else:
                    first_crop = _tab10_get_crop(self, start)
                    self._tab10_tracking_fixed_center = _tab10_detection_reference(self, first_crop)
            except Exception:
                self._tab10_tracking_fixed_center = None

        rows = []
        self._tab10_tracking_df = pd.DataFrame()

        # Full profile archive for the selected tracking range.  This is kept
        # separately from the numeric result table because profile arrays should
        # not be forced into one-cell DataFrame values.
        self._tab10_tracking_profiles = {}

        # Same tracking-panel initialization philosophy as TAB 11:
        # clear only the tracking result; do not alter FIT CURRENT ROI.
        _tab10_plot_tracking(
            self,
            self._tab10_tracking_df,
            start,
            end,
            draw_now=True
        )

        self.tab10_fit_status_var.set(
            f'⏳ Tracking ROI4 | frames {start + 1}–{end + 1} | 0/{end - start + 1}'
        )
        self.root.update_idletasks()

        total = end - start + 1
        done = 0
        _analysis_progress_update(self, 10, 0, total)
        detected_count = 0
        stopped = False

        # ---------------------------------------------------------------
        # Same fundamental order as TAB 11 TRACK ALL ROIs:
        # frame -> crop -> detect -> fit only if valid core exists.
        # ---------------------------------------------------------------
        for frame in range(start, end + 1):
            if run_source is not self._tab10_roi4_stack:
                return
            if getattr(self, '_tab10_stop_requested', False):
                stopped = True
                break
            try:
                crop = _tab10_get_crop(self, frame)

                if follow:
                    detected, det = _tab10_follow_core(self, crop, frame)
                elif zero_mode:
                    detected, det = _tab10_detect_with_diagnostics(self, crop, frame)
                else:
                    # Zero mode OFF: preserve the original TAB 10 fitting path.
                    detected, det = True, None

                if not detected:
                    r = _tab10_zero_result(self, frame, crop, _tab10_detection_reference(self, crop))
                    rows.append(_tab10_numeric_result(r))
                else:
                    # Same detector-first / fitter-second sequence as TAB 11.
                    r = _tab10_fit_roi4(self, frame, detection=(detected, det) if zero_mode or follow else False)

                    if r is None:
                        raise RuntimeError(
                            'Particle detected but fitting returned no result.'
                        )

                    rows.append(_tab10_numeric_result(r))

                    # Archive Gaussian/raw and D-Fit normalized profiles for every
                    # successfully fitted frame in the selected range.
                    self._tab10_tracking_profiles[int(frame)] = {
                        'frame': int(frame),
                        'field_mT': float(r.get('field_mT', np.nan)),
                        'angles': [float(a) for a in r.get('angles', [])],
                        't_nm': np.asarray(r.get('t_nm', []), dtype=float).copy(),
                        'profiles': {
                            float(a): np.asarray(r['profiles'][float(a)], dtype=float).copy()
                            for a in r.get('angles', [])
                        },
                        'average_profile': np.asarray(r.get('average_profile', []), dtype=float).copy(),
                        'gaussian_fit': np.asarray(r.get('fit_profile', []), dtype=float).copy(),
                        'residual_profile': np.asarray(r.get('residual_profile', []), dtype=float).copy(),
                        'dfit_radial_normalized_profiles': {
                            float(a): (
                                np.asarray(v[0], dtype=float).copy(),
                                np.asarray(v[1], dtype=float).copy()
                            )
                            for a, v in r.get('dfit_radial_normalized_profiles', {}).items()
                        },
                        'dfit_diameter_profile_t_nm': np.asarray(
                            r.get('dfit_diameter_profile_t_nm', []), dtype=float
                        ).copy(),
                        'dfit_diameter_profiles': {
                            float(a): np.asarray(v, dtype=float).copy()
                            for a, v in r.get('dfit_diameter_profiles', {}).items()
                        },
                        'dfit_diameter_smoothed_profiles': {
                            float(a): np.asarray(v, dtype=float).copy()
                            for a, v in r.get('dfit_diameter_smoothed_profiles', {}).items()
                        },
                        'dfit_normalized_average_profile': np.asarray(
                            r.get('dfit_normalized_average_profile', []), dtype=float
                        ).copy(),
                        'dfit_radial_smoothed_profiles': {
                            float(a): (np.asarray(v[0], dtype=float).copy(), np.asarray(v[1], dtype=float).copy())
                            for a, v in r.get('dfit_radial_smoothed_profiles', {}).items()
                        },
                        'dfit_radial_gradient_profiles': {
                            float(a): (np.asarray(v[0], dtype=float).copy(), np.asarray(v[1], dtype=float).copy())
                            for a, v in r.get('dfit_radial_gradient_profiles', {}).items()
                        },
                        'dfit_sg_level': int(r.get('dfit_sg_level', self.tab10_dfit_sg_level_var.get())),
                        'dfit_sg_window_points': int(r.get('dfit_sg_window_points', 0)),
                        'gaussian_fwhm': float(r.get('fwhm', np.nan)),
                        'gaussian_fwhm_sd': float(r.get('fwhm_err', np.nan)),
                        'dfit_diameter': float(r.get('diameter_nm', np.nan)),
                        'dfit_diameter_sd': float(r.get('diameter_err_nm', np.nan)),
                    }
                    detected_count += 1
                    if zero_mode and isinstance(det, dict):
                        # Carry only a validated core into the next frame.
                        self._tab10_last_detected_core = {
                            'x0': float(det.get('x0', np.nan)),
                            'y0': float(det.get('y0', np.nan)),
                        }

            except Exception as exc:
                # Invalid data or fit failure is unavailable, never a measured zero.
                self.log(f'Tab 10 frame {frame+1} analysis failed: {type(exc).__name__}: {exc}')
                rows.append({
                    'roi_index': 4,
                    'frame': frame,
                    'field_mT': float(_tab10_intensity_field(self, frame)),
                    'fwhm': np.nan,
                    'fwhm_err': np.nan,
                    'diameter_nm': np.nan,
                    'diameter_err_nm': np.nan,
                    'core_intensity': np.nan,
                    'amplitude': np.nan,
                    'amplitude_err': np.nan,
                    'sigma': np.nan,
                    'sigma_err': np.nan,
                    'r2': np.nan,
                    'rmse': np.nan,
                    'line_rmse': np.nan,
                    'line_cv': np.nan,
                    'core_detected': None,
                    'detection_status': 'error',
                    'detection_reason': str(exc),
                    'error': f'{type(exc).__name__}: {exc}',
                })

            done += 1
            _analysis_progress_update(self, 10, done, total)

            # Keep the existing TAB 10 live tracking plot behavior.
            self._tab10_tracking_df = pd.DataFrame(rows)
            _tab10_plot_tracking(
                self,
                self._tab10_tracking_df,
                start,
                end,
                draw_now=True
            )

            self.tab10_fit_status_var.set(
                f'⏳ ROI4 tracking | frame {frame + 1}/{nframes} | '
                f'{done}/{total} | cores detected: {detected_count}'
            )
            try:
                # Process button events so STOP FIT can be clicked during tracking.
                self.root.update()
            except Exception:
                self.root.update_idletasks()

            if run_source is not self._tab10_roi4_stack:
                return

            if getattr(self, '_tab10_stop_requested', False):
                stopped = True
                break

        # Final tracking result.
        self._tab10_tracking_df = pd.DataFrame(rows)
        _tab10_plot_tracking(
            self,
            self._tab10_tracking_df,
            start,
            end,
            draw_now=True
        )

        self._tab10_tracking_fixed_center = None

        if stopped or getattr(self, '_tab10_stop_requested', False):
            self.tab10_fit_status_var.set(
                f'⏹ ROI4 tracking stopped | frames {start + 1}–{end + 1} | '
                f'{len(rows)} completed measurements | {detected_count} particle cores detected'
            )
        else:
            self.tab10_fit_status_var.set(
                f'✓ ROI4 tracking complete | frames {start + 1}–{end + 1} | '
                f'{len(rows)} measurements | {detected_count} particle cores detected'
            )

        self._tab10_stop_requested = False
    finally:
        self._tab10_ii_busy = False
        # New Upload/source replacement owns the new state; do not restore old rows.
        if run_source is self._tab10_roi4_stack:
            last = getattr(self, '_tab10_last_fit', None)
            if (self.tab10_integrated_intensity_var.get() and not self._tab10_ii_dirty
                    and self._tab10_ii_current_result is None and isinstance(last, dict)
                    and self._tab10_intensity_profiles):
                try:
                    _tab10_fit_roi4(self, int(last['frame']))
                except Exception as exc:
                    self._tab10_last_fit = None
                    self.log(f'Tab 10 displayed-profile refit unavailable: {exc}')
            if self._tab10_ii_current_result is not None:
                self._tab10_last_fit = self._tab10_ii_current_result
                _tab10_draw_fit_result(self, self._tab10_last_fit)
                _tab10_update_fit_parameters(self, result=self._tab10_last_fit)
            self._tab10_ii_current_result = None
            _tab10_sync_intensity_values(self)
            _tab10_plot_intensity(self)



@_auto_open_export
def _tab10_export_current_profile_csv(self):
    """Export the current frame's raw/Gaussian line profiles."""
    if _ii2d_enabled(self,10):return _ii2d_export_tables(self,10,current=True)
    r = getattr(self, '_tab10_last_fit', None)
    if not isinstance(r, dict):
        messagebox.showwarning(
            'Tab 10 Export',
            'Run FIT CURRENT ROI first.',
            parent=self.root
        )
        return

    selected_folder = self._export_initialdir()
    if not selected_folder:
        return
    folder = Path(selected_folder)
    folder.mkdir(parents=True, exist_ok=True)
    frame_no = int(r.get('frame', 0)) + 1
    path = folder / f'Tab10_Gaussian_LineProfiles_Frame{frame_no:03d}.csv'

    data = {'Position_nm': np.asarray(r.get('t_nm', []), dtype=float)}
    for angle in r.get('angles', []):
        data[f'Raw_Profile_{float(angle):g}deg'] = np.asarray(
            r['profiles'][float(angle)], dtype=float
        )
    data['Raw_Average_Profile'] = np.asarray(r.get('average_profile', []), dtype=float)
    data['Gaussian_Fit'] = np.asarray(r.get('fit_profile', []), dtype=float)
    data['Gaussian_Residual'] = np.asarray(r.get('residual_profile', []), dtype=float)

    _export_capture_write(_tab10_profile_table(self, r).to_csv, path, index=False)
    self.tab10_export_status_var.set(f'✓ {path.name}')
    messagebox.showinfo('Tab 10 Export', f'Gaussian line profile exported:\n\n{path}', parent=self.root)


@_auto_open_export
def _tab10_export_selected_range_csvs(self):
    """Automatically export THREE separate CSV files for the selected frame range.

    1) Tab10_Table_Gaussian_DFit_...csv
    2) Tab10_Gaussian_LineProfiles_...csv
    3) Tab10_DFit_LineProfiles_...csv
    """
    if _ii2d_enabled(self,10):return _ii2d_export_tables(self,10)
    _tab10_sync_intensity_values(self)
    records = getattr(self, '_tab10_intensity_profiles', None) or {}
    df = getattr(self, '_tab10_tracking_df', None)

    if df is None or not isinstance(df, pd.DataFrame) or df.empty:
        messagebox.showwarning(
            'Tab 10 Export',
            'Run TRACK-SELECTED FRAMES first for the selected range.',
            parent=self.root
        )
        return

    try:
        start = int(self.tab10_start_var.get()) + 1
        end = int(self.tab10_end_var.get()) + 1
    except Exception:
        start = int(df['frame'].min()) + 1
        end = int(df['frame'].max()) + 1

    if start > end:
        start, end = end, start

    selected_folder = self._export_initialdir()
    if not selected_folder:
        return
    folder = Path(selected_folder)
    folder.mkdir(parents=True, exist_ok=True)
    stem = f'Frames{start:03d}-{end:03d}'

    # ---------- FILE 1: both methods' numeric table ----------
    table = pd.DataFrame()
    src = df[(df['frame'] + 1 >= start) & (df['frame'] + 1 <= end)].copy()
    if src.empty:
        messagebox.showwarning('Tab 10 Export', 'No analysed data in the selected range.', parent=self.root)
        return

    def numcol(name, default=np.nan):
        if name in src.columns:
            return pd.to_numeric(src[name], errors='coerce')
        return pd.Series(default, index=src.index, dtype=float)

    table['Frame'] = numcol('frame') + 1
    table['Equivalent_Field_mT'] = numcol('field_mT')
    table['Gaussian_FWHM_nm'] = numcol('fwhm')
    table['Gaussian_FWHM_SD_nm'] = numcol('fwhm_err')
    table['Gaussian_Amplitude_au'] = numcol('amplitude')
    table['Gaussian_Amplitude_SD_au'] = numcol('amplitude_err')
    table['D_Fit_Diameter_nm'] = numcol('diameter_nm')
    table['D_Fit_Diameter_SD_nm'] = numcol('diameter_err_nm')
    table['D_Fit_SG_Level'] = numcol('dfit_sg_level')
    table['D_Fit_SG_Window_Points'] = numcol('dfit_sg_window_points')
    table['D_Fit_Raw_Core_Intensity_au'] = numcol('core_intensity')
    table['Core_Detected'] = src['core_detected'] if 'core_detected' in src.columns else True

    if self.tab10_integrated_intensity_var.get():
        table['II_Avg_Line_Fit_au_nm'] = numcol('ii_avg_line_fit')
        table['II_Gaussian_Fit_au_nm'] = numcol('ii_gaussian_fit')
        table['II_Baseline_au'] = numcol('ii_baseline')
        table['II_Range_Min_nm'] = numcol('ii_xmin_nm')
        table['II_Range_Max_nm'] = numcol('ii_xmax_nm')
        table['II_Status'] = src.get('ii_status', '')
    table_path = folder / f'Tab10_Table_Gaussian_DFit_{stem}.csv'
    _ii_add_export_columns(table, src, self.tab10_integrated_intensity_var.get())
    complete = _tab10_complete_table(self, src)
    for col in complete:
        if col not in table:
            table[col] = complete[col].to_numpy()
    _export_capture_write(table.to_csv, table_path, index=False)
    figure5_path = folder / f'Tab10_Figure5_Diameter_IntegratedIntensity_{stem}.csv'
    _export_capture_write(_ii_export_table(src, self.tab10_integrated_intensity_var.get()).to_csv, figure5_path, index=False)

    # ---------- FILE 2: Gaussian/raw profiles ----------
    gaussian_rows = []
    for frame0 in sorted(records):
        if frame0 + 1 < start or frame0 + 1 > end:
            continue
        rec = records[frame0]
        t = np.asarray(rec.get('t_nm', []), dtype=float)
        angles = rec.get('angles', [])
        if t.size == 0:
            continue
        n = t.size
        for j in range(n):
            row = {
                'Frame': frame0 + 1,
                'Equivalent_Field_mT': float(rec.get('field_mT', np.nan)),
                'Position_nm': float(t[j]),
            }
            for a in angles:
                arr = np.asarray(rec['profiles'].get(float(a), np.full(n, np.nan)), dtype=float)
                row[f'Raw_Profile_{float(a):g}deg'] = float(arr[j]) if j < arr.size else np.nan
            avg = np.asarray(rec.get('average_profile', np.full(n, np.nan)), dtype=float)
            gf = np.asarray(rec.get('fit_profile', np.full(n, np.nan)), dtype=float)
            rr = np.asarray(rec.get('residual_profile', np.full(n, np.nan)), dtype=float)
            row['Raw_Average_Profile'] = float(avg[j]) if j < avg.size else np.nan
            row['Gaussian_Fit'] = float(gf[j]) if j < gf.size else np.nan
            row['Gaussian_Residual'] = float(rr[j]) if j < rr.size else np.nan
            gaussian_rows.append(row)

    gaussian_path = folder / f'Tab10_Gaussian_LineProfiles_{stem}.csv'
    _export_capture_write((pd.DataFrame(gaussian_rows) if gaussian_rows else pd.DataFrame(columns=['Frame', 'Equivalent_Field_mT', 'Position_nm'])).to_csv, gaussian_path, index=False)

    # ---------- FILE 3: D-Fit profiles ----------
    dfit_rows = []
    for frame0 in sorted(records):
        if frame0 + 1 < start or frame0 + 1 > end:
            continue
        rec = records[frame0]
        t = np.asarray(rec.get('dfit_diameter_profile_t_nm', []), dtype=float)
        profiles = rec.get('dfit_diameter_profiles', {})
        avg = np.asarray(rec.get('dfit_normalized_average_profile', []), dtype=float)
        sg_level = int(rec.get('dfit_sg_level', 0))
        sg_window = int(rec.get('dfit_sg_window_points', 0))
        if t.size == 0:
            continue
        n = t.size
        for j in range(n):
            row = {
                'Frame': frame0 + 1,
                'Equivalent_Field_mT': float(rec.get('field_mT', np.nan)),
                'Position_nm': float(t[j]),
            }
            smooth_profiles = rec.get('dfit_diameter_smoothed_profiles', {})
            for a in sorted(profiles):
                arr = np.asarray(profiles[a], dtype=float)
                row[f'DFit_Normalized_Profile_{float(a):g}deg'] = float(arr[j]) if j < arr.size else np.nan
                sarr = np.asarray(smooth_profiles.get(a, np.full(n, np.nan)), dtype=float)
                row[f'DFit_SG_Smoothed_Profile_{float(a):g}deg'] = float(sarr[j]) if j < sarr.size else np.nan
            row['D_Fit_Average_Normalized_Profile'] = float(avg[j]) if j < avg.size else np.nan
            row['D_Fit_SG_Level'] = sg_level
            row['D_Fit_SG_Window_Points'] = sg_window
            dfit_rows.append(row)

    dfit_path = folder / f'Tab10_DFit_LineProfiles_{stem}.csv'
    _export_capture_write((pd.DataFrame(dfit_rows) if dfit_rows else pd.DataFrame(columns=['Frame', 'Equivalent_Field_mT', 'Position_nm'])).to_csv, dfit_path, index=False)

    _tab10_export_detail_bundle(self, folder, stem, start, end)
    self.tab10_export_status_var.set(f'Exported 7 Tab-10 CSVs: {stem}')
    messagebox.showinfo(
        'Tab 10 Export',
        'Seven CSV files exported: summary, Gaussian profiles, D-fit profiles, Figure 5, full profile samples and D-fit measurements.\n\n'
        f'{table_path.name}\n'
        f'{gaussian_path.name}\n'
        f'{dfit_path.name}\n'
        f'{figure5_path.name}\n\n'
        f'Folder:\n{folder}',
        parent=self.root
    )

@_auto_open_export
def _tab10_export_tracking_csv(self):
    """Export Tab-10 tracking data with explicit Gaussian/D-FIT prefixes."""
    if _ii2d_enabled(self,10):return _ii2d_export_tables(self,10)
    _tab10_sync_intensity_values(self)
    df = getattr(self, '_tab10_tracking_df', None)
    if df is None or not isinstance(df, pd.DataFrame) or df.empty:
        messagebox.showwarning(
            'Tab 10 Export',
            'Run TRACK-SELECTED FRAMES first.',
            parent=self.root
        )
        return

    try:
        path = filedialog.asksaveasfilename(
            parent=self.root,
            title='Export Tab-10 Table',
            defaultextension='.csv',
            filetypes=[('CSV', '*.csv'), ('All files', '*.*')],
            initialfile='Tab10_Tracking_Results.csv'
        )
        if not path:
            return

        src = df.copy()
        dfit_mode = bool(getattr(self, 'tab10_dfit_var', None) is not None and self.tab10_dfit_var.get())
        mode_text = 'D-Fit' if dfit_mode else 'Gaussian'
        sg_level = np.nan
        try:
            sg_level = int(self.tab10_dfit_sg_level_var.get())
        except Exception:
            pass

        # Explicit names prevent ambiguity when Gaussian and D-FIT quantities
        # are viewed together in the exported CSV.
        export_df = pd.DataFrame(index=src.index)
        if 'frame' in src.columns:
            export_df['Frame'] = pd.to_numeric(src['frame'], errors='coerce') + 1
        if 'field_mT' in src.columns:
            export_df['Field (mT)'] = pd.to_numeric(src['field_mT'], errors='coerce')
        export_df['D-Fit Mode'] = mode_text
        export_df['D-Fit Savitzky-Golay Level'] = sg_level
        export_df['D-Fit SG Window Points'] = (2*sg_level+1) if np.isfinite(sg_level) and sg_level>0 else 0

        export_df['Gaussian_fwhm'] = pd.to_numeric(src.get('fwhm', np.nan), errors='coerce')
        export_df['Gaussian_fwhm_err'] = pd.to_numeric(src.get('fwhm_err', np.nan), errors='coerce')
        export_df['D-FIT_diameter_nm'] = pd.to_numeric(src.get('diameter_nm', np.nan), errors='coerce')
        export_df['D-FIT_diameter_err_nm'] = pd.to_numeric(src.get('diameter_err_nm', np.nan), errors='coerce')
        export_df['D-FIT_core_intensity'] = pd.to_numeric(src.get('core_intensity', np.nan), errors='coerce')
        export_df['Gaussian_amplitude'] = pd.to_numeric(src.get('amplitude', np.nan), errors='coerce')
        export_df['Gaussian_amplitude_err'] = pd.to_numeric(src.get('amplitude_err', np.nan), errors='coerce')

        if self.tab10_integrated_intensity_var.get():
            export_df['II_Avg_Line_Fit_au_nm'] = pd.to_numeric(src.get('ii_avg_line_fit', np.nan), errors='coerce')
            export_df['II_Gaussian_Fit_au_nm'] = pd.to_numeric(src.get('ii_gaussian_fit', np.nan), errors='coerce')
            export_df['II_Baseline_au'] = pd.to_numeric(src.get('ii_baseline', np.nan), errors='coerce')
            export_df['II_Range_Min_nm'] = pd.to_numeric(src.get('ii_xmin_nm', np.nan), errors='coerce')
            export_df['II_Range_Max_nm'] = pd.to_numeric(src.get('ii_xmax_nm', np.nan), errors='coerce')
            export_df['II_Status'] = src.get('ii_status', '')
        _ii_add_export_columns(export_df, src, self.tab10_integrated_intensity_var.get())
        complete = _tab10_complete_table(self, src)
        for col in complete:
            if col not in export_df:
                export_df[col] = complete[col].to_numpy()
        _export_capture_write(export_df.to_csv, path, index=False)
        _tab10_export_detail_bundle(self, Path(path).parent, Path(path).stem,
                                    int(src['frame'].min()) + 1, int(src['frame'].max()) + 1)
        _export_capture_write(_ii_export_table(src, self.tab10_integrated_intensity_var.get()).to_csv, Path(path).with_name(Path(path).stem + '_Figure5.csv'), index=False)
        self.tab10_export_status_var.set(
            f'✓ Exported Tab-10 table: {Path(path).name}'
        )
        messagebox.showinfo(
            'Tab 10 Export',
            'Exported table with explicit Gaussian / D-FIT column names:\n\n' +
            ', '.join(export_df.columns),
            parent=self.root
        )
    except Exception as exc:
        self.tab10_export_status_var.set(
            f'✗ Tab-10 table export failed: {type(exc).__name__}: {exc}'
        )
        _export_error_dialog(messagebox.showerror, 'Tab 10 Export', f'{type(exc).__name__}: {exc}', parent=self.root)


def _tab10_tab_changed(self,event=None):
    try:
        if self.nb.select()==str(self.tab_single_roi10):
            _tab10_sync_roi4_from_tab9(self,preserve_frame=True)
    except Exception as exc:
        try:
            self.tab10_status_var.set(
                f'Could not fetch ROI from Tab 9: '
                f'{type(exc).__name__}: {exc}'
            )
        except Exception:
            pass





CDIWorkflowApp._tab10_tab_changed = _tab10_tab_changed


def _tab10_update_fit_parameters(self, result=None, center=None, message=None):
    """Refresh the scrollable Tab-10 parameter panel without changing analysis."""
    vars_ = getattr(self, 'tab10_param_vars', {})
    if not vars_:
        return
    vals = {k: '—' for k in vars_}
    if center is not None:
        vals.update({
            'center': f"({float(center.get('x0', np.nan)):.4f}, {float(center.get('y0', np.nan)):.4f}) px",
            'background': f"{float(center.get('background', np.nan)):.6g}",
            'threshold': f"{float(center.get('threshold', np.nan)):.6g}",
            'sign': f"{float(center.get('sign', np.nan)):.0f}",
        })
    if result is not None:
        vals.update({
            'center': f"({result['local_center_x_px']:.4f}, {result['local_center_y_px']:.4f}) px",
            'background': f"{result['background']:.6g}",
            'threshold': f"{result['contrast_threshold']:.6g}",
            'sign': f"{result['contrast_sign']:.0f}",
            'amplitude': f"{result['amplitude']:.6g} ± {result['amplitude_err']:.3g}",
            'core_intensity': f"{result.get('core_intensity',np.nan):.6g}",
            'sigma': f"{result['sigma']:.6g} ± {result['sigma_err']:.3g} nm",
            'fwhm': f"{result['fwhm']:.6g} ± {result['fwhm_err']:.3g} nm",
            'diameter': f"{result.get('diameter_nm',np.nan):.6g} nm",
            'diameter_sd': f"{result.get('diameter_err_nm',np.nan):.6g} nm",
            'dfit_sg': f"{int(result.get('dfit_sg_level',self.tab10_dfit_sg_level_var.get()))} (window {int(result.get('dfit_sg_window_points',0))})",
            'r2': f"{result['r2']:.6g}",
            'rmse': f"{result['rmse']:.6g}",
            'line_rmse': f"{result['line_rmse']:.6g}",
            'line_cv': f"{result['line_cv']:.6g}",
            'fov': f"{result['fov_width_nm']:.6g} × {result['fov_height_nm']:.6g} nm",
            'frame': f"{result['frame'] + 1} / {len(self._tab10_roi4_stack)}",
            'field': f"{result['field_mT']:+.6g} mT",
        })
    if message is not None:
        vals['status'] = str(message)
    else:
        vals['status'] = ('Gaussian fit not performed.' if result is None else
                          'Core not detected; no fit.' if result.get('core_detected') is False else
                          'Gaussian fit complete.')
    for k, v in vals.items():
        if k in vars_:
            vars_[k].set(v)


def _tab10_fig1_mouse_zoom(self, event):
    """Mouse-wheel zoom for Tab-10 Figure 1 (ROI image only).

    Scroll up  -> zoom in
    Scroll down -> zoom out

    The zoom is centered at the mouse cursor and preserves the current
    X/Y aspect relationship.  Figure 2/3/4 are not affected.
    """
    try:
        ax = getattr(self, 'tab10_ax_image', None)
        if ax is None or event.inaxes is not ax:
            return

        if event.xdata is None or event.ydata is None:
            return

        button = getattr(event, 'button', None)
        if button == 'up':
            scale = 1.0 / 1.25
        elif button == 'down':
            scale = 1.25
        else:
            return

        x0, x1 = map(float, ax.get_xlim())
        y0, y1 = map(float, ax.get_ylim())
        cx, cy = float(event.xdata), float(event.ydata)

        ax.set_xlim(
            cx + (x0 - cx) * scale,
            cx + (x1 - cx) * scale
        )
        ax.set_ylim(
            cy + (y0 - cy) * scale,
            cy + (y1 - cy) * scale
        )

        # Keep the image aspect ratio consistent with the displayed ROI.
        try:
            ax.set_aspect('equal', adjustable='box')
        except Exception:
            pass

        self.tab10_canvas.draw_idle()
    except Exception:
        pass


def _tab10_mouse_zoom(self, event):
    """Mouse-wheel zoom for Figure 1 (ROI image) and Figure 4 (tracking).

    Zoom is centered on the mouse position and rescales both y axes of Figure 4
    together.  The normal frame/tracking redraw still restores the automatic
    limits; wheel zoom then gives an interactive local view.
    """
    try:
        ax = event.inaxes
        if ax is None or ax not in (getattr(self,'tab10_ax_image',None), getattr(self,'tab10_ax_tracking',None), getattr(self,'_tab10_ax_tracking2',None)):
            return
        if event.xdata is None or event.ydata is None:
            return
        direction = getattr(event, 'button', None)
        if direction == 'up':
            scale = 1.0/1.25
        elif direction == 'down':
            scale = 1.25
        else:
            return
        x0,x1=ax.get_xlim(); y0,y1=ax.get_ylim()
        cx=float(event.xdata); cy=float(event.ydata)
        new_x0=cx+(x0-cx)*scale; new_x1=cx+(x1-cx)*scale
        new_y0=cy+(y0-cy)*scale; new_y1=cy+(y1-cy)*scale
        ax.set_xlim(new_x0,new_x1); ax.set_ylim(new_y0,new_y1)
        if ax in (getattr(self,'tab10_ax_tracking',None), getattr(self,'_tab10_ax_tracking2',None)):
            a1=getattr(self,'tab10_ax_tracking',None); a2=getattr(self,'_tab10_ax_tracking2',None)
            if a1 is not None and a2 is not None:
                if ax is a1:
                    # x is shared; y zoom for both twin axes around the mouse
                    a2x0,a2x1=a2.get_xlim(); a2.set_xlim(new_x0,new_x1)
                    if a2.get_ylim()[0] == a2.get_ylim()[1]: pass
                    else:
                        ay0,ay1=a2.get_ylim();
                        # Map the mouse y from primary to secondary axis.
                        p0,p1=y0,y1; s0,s1=ay0,ay1
                        frac=(cy-p0)/(p1-p0) if p1!=p0 else 0.5; scy=s0+frac*(s1-s0)
                        a2.set_ylim(scy+(s0-scy)*scale, scy+(s1-scy)*scale)
                else:
                    a1.set_xlim(new_x0,new_x1)
        self.tab10_canvas.draw_idle()
    except Exception:
        pass


def _tab10_bind_mouse_zoom(self):
    """Bind Tab-10 Figure-1/Figure-4 interactive zoom controls.

    Figure 4:
      * mouse wheel = zoom around cursor
      * left-button drag = draw a zoom window and apply it
      * middle-button drag = pan the current view
      * double left click = restore automatic limits

    Figure 1 retains mouse-wheel zoom.
    """
    try:
        old = getattr(self, '_tab10_zoom_cids', []) or []
        for cid in old:
            try:
                self.tab10_canvas.mpl_disconnect(cid)
            except Exception:
                pass
        cids = []
# Disabled custom Figure-4 pan/zoom:         cids.append(self.tab10_canvas.mpl_connect('scroll_event', lambda e: _tab10_mouse_zoom(self, e)))
# Disabled custom Figure-4 pan/zoom:         cids.append(self.tab10_canvas.mpl_connect('button_press_event', lambda e: _tab10_fig4_mouse_press(self, e)))
# Disabled custom Figure-4 pan/zoom:         cids.append(self.tab10_canvas.mpl_connect('motion_notify_event', lambda e: _tab10_fig4_mouse_motion(self, e)))
# Disabled custom Figure-4 pan/zoom:         cids.append(self.tab10_canvas.mpl_connect('button_release_event', lambda e: _tab10_fig4_mouse_release(self, e)))
        self._tab10_zoom_cids = cids
        self._tab10_fig4_drag = None
        self._tab10_fig4_rect = None
    except Exception:
        self._tab10_zoom_cids = []


def _tab10_fig4_event_xy(self, event):
    """Return Figure-4 coordinates in the PRIMARY y-axis data system.

    The twin y-axis sits on top of the primary axis and therefore receives
    mouse events whenever the cursor is over the right-axis side of Figure 4.
    Convert through display pixels so rectangle zoom/pan works on either axis.
    """
    a1 = getattr(self, 'tab10_ax_tracking', None)
    a2 = getattr(self, '_tab10_ax_tracking2', None)
    if a1 is None or event.inaxes not in (a1, a2):
        return None
    if event.x is None or event.y is None:
        return None
    try:
        x1, y1 = a1.transData.inverted().transform((float(event.x), float(event.y)))
        return float(x1), float(y1)
    except Exception:
        return None


def _tab10_fig4_mouse_press(self, event):
    """Figure-4 left-drag rectangle zoom; middle-drag pan; double-left reset."""
    try:
        xy = _tab10_fig4_event_xy(self, event)
        if xy is None:
            return
        x, y = xy
        if getattr(event, 'dblclick', False) and event.button == 1:
            _tab10_fig4_reset_view(self)
            return
        ax = getattr(self, 'tab10_ax_tracking', None)
        if event.button == 1:
            self._tab10_fig4_drag = {
                'mode': 'zoom', 'x0': x, 'y0': y, 'x1': x, 'y1': y,
                'xlim0': tuple(map(float, ax.get_xlim())),
                'ylim0': tuple(map(float, ax.get_ylim()))
            }
            try:
                from matplotlib.patches import Rectangle
                old = getattr(self, '_tab10_fig4_rect', None)
                if old is not None:
                    old.remove()
                self._tab10_fig4_rect = Rectangle(
                    (x, y), 0.0, 0.0, fill=False, linewidth=1.5,
                    linestyle='--', edgecolor='black', zorder=1000
                )
                ax.add_patch(self._tab10_fig4_rect)
                self.tab10_canvas.draw_idle()
            except Exception:
                pass
        elif event.button == 2:
            self._tab10_fig4_drag = {
                'mode': 'pan', 'x0': x, 'y0': y,
                'xlim0': tuple(map(float, ax.get_xlim())),
                'ylim0': tuple(map(float, ax.get_ylim())),
                'sec_ylim0': tuple(map(float, getattr(self, '_tab10_ax_tracking2').get_ylim())) if getattr(self, '_tab10_ax_tracking2', None) is not None else None
            }
    except Exception:
        self._tab10_fig4_drag = None


def _tab10_fig4_mouse_motion(self, event):
    try:
        drag = getattr(self, '_tab10_fig4_drag', None)
        if not drag:
            return
        xy = _tab10_fig4_event_xy(self, event)
        if xy is None:
            return
        x, y = xy
        ax = getattr(self, 'tab10_ax_tracking', None)
        if ax is None:
            return
        if drag['mode'] == 'zoom':
            drag['x1'], drag['y1'] = x, y
            rect = getattr(self, '_tab10_fig4_rect', None)
            if rect is not None:
                rect.set_xy((min(drag['x0'], x), min(drag['y0'], y)))
                rect.set_width(abs(x - drag['x0']))
                rect.set_height(abs(y - drag['y0']))
                self.tab10_canvas.draw_idle()
        elif drag['mode'] == 'pan':
            dx = x - drag['x0']; dy = y - drag['y0']
            x0, x1 = drag['xlim0']; y0, y1 = drag['ylim0']
            ax.set_xlim(x0 - dx, x1 - dx)
            ax.set_ylim(y0 - dy, y1 - dy)
            a2 = getattr(self, '_tab10_ax_tracking2', None)
            if a2 is not None:
                a2.set_xlim(ax.get_xlim())
                # Preserve the current primary-to-secondary y mapping by
                # transforming the displayed primary limits through the axes.
                try:
                    oldp0, oldp1 = y0, y1
                    s0, s1 = drag.get('sec_ylim0', tuple(map(float, a2.get_ylim())))
                    scale_y = (s1-s0)/(oldp1-oldp0) if oldp1 != oldp0 else 1.0
                    a2.set_ylim(s0 - dy*scale_y, s1 - dy*scale_y)
                except Exception:
                    pass
            self.tab10_canvas.draw_idle()
    except Exception:
        pass


def _tab10_fig4_mouse_release(self, event):
    try:
        drag = getattr(self, '_tab10_fig4_drag', None)
        if not drag:
            return
        if drag['mode'] == 'zoom' and event.button == 1:
            x1 = drag.get('x1', drag['x0']); y1 = drag.get('y1', drag['y0'])
            x0, x1 = sorted((drag['x0'], x1)); y0, y1 = sorted((drag['y0'], y1))
            ax = getattr(self, 'tab10_ax_tracking', None)
            if ax is not None and abs(x1-x0) > 1e-12 and abs(y1-y0) > 1e-12:
                oldp0, oldp1 = drag.get('ylim0', ax.get_ylim())
                a2 = getattr(self, '_tab10_ax_tracking2', None)
                ax.set_xlim(x0, x1)
                ax.set_ylim(y0, y1)
                if a2 is not None:
                    s0, s1 = map(float, a2.get_ylim())
                    # Map selected primary y-window proportionally into the
                    # existing secondary y-range.
                    f0 = (y0-oldp0)/(oldp1-oldp0) if oldp1 != oldp0 else 0.0
                    f1 = (y1-oldp0)/(oldp1-oldp0) if oldp1 != oldp0 else 1.0
                    a2.set_xlim(x0, x1)
                    a2.set_ylim(s0 + f0*(s1-s0), s0 + f1*(s1-s0))
            rect = getattr(self, '_tab10_fig4_rect', None)
            if rect is not None:
                try: rect.remove()
                except Exception: pass
                self._tab10_fig4_rect = None
            if getattr(self, 'tab10_canvas', None) is not None:
                self.tab10_canvas.draw_idle()
    except Exception:
        pass
    finally:
        self._tab10_fig4_drag = None

def _tab10_fig4_reset_view(self):
    """Restore automatic limits for Figure 4 and both y axes."""
    try:
        ax = getattr(self, 'tab10_ax_tracking', None)
        a2 = getattr(self, '_tab10_ax_tracking2', None)
        if ax is not None:
            ax.relim(); ax.autoscale_view()
        if a2 is not None:
            a2.relim(); a2.autoscale_view()
            if ax is not None:
                a2.set_xlim(ax.get_xlim())
        rect = getattr(self, '_tab10_fig4_rect', None)
        if rect is not None:
            try: rect.remove()
            except Exception: pass
            self._tab10_fig4_rect = None
        if getattr(self, 'tab10_canvas', None) is not None:
            self.tab10_canvas.draw_idle()
    except Exception:
        pass


def _tab10_refresh_layout(self):
    """Keep the Tab-6-style 2x2 layout stable and fully responsive."""
    try:
        fig = self.tab10_fig
        # Do NOT call tight_layout here: twin Y/X axes used by Figure 4 can
        # be moved/clipped by repeated tight_layout calls.  Fixed margins
        # provide predictable space for all titles, labels and legends.
        fig.subplots_adjust(
            left=0.075, right=0.905, bottom=0.095, top=0.905,
            wspace=0.30, hspace=0.48
        )

        # Figure 4: reserve explicit space for the right Y2 label and top X2.
        ax = getattr(self, 'tab10_ax_tracking', None)
        ax2 = getattr(self, '_tab10_ax_tracking2', None)
        secx = getattr(self, '_tab10_tracking_secx', None)

        dfit_on = bool(
            getattr(self, 'tab10_dfit_var', None) is not None
            and self.tab10_dfit_var.get()
        )
        y1_label = 'Diameter (nm)' if dfit_on else 'Gaussian FWHM (nm)'
        y2_label = 'Core Intensity (a.u.)' if dfit_on else 'Gaussian Amplitude (a.u.)'

        if ax is not None:
            ax.xaxis.labelpad = 8
            ax.yaxis.labelpad = 8
            ax.set_title(ax.get_title(), pad=5)
        if ax2 is not None:
            ax2.yaxis.labelpad = 12
            ax2.yaxis.set_label_position('right')
            ax2.yaxis.tick_right()
        if secx is not None:
            secx.xaxis.labelpad = 7
            secx.xaxis.set_label_position('top')
            secx.xaxis.tick_top()

        # Keep titles/labels separated between the top and bottom panels.
        for a in (
            getattr(self, 'tab10_ax_image', None),
            getattr(self, 'tab10_ax_profiles', None),
            getattr(self, 'tab10_ax_fit', None),
        ):
            if a is not None:
                a.set_title(a.get_title(), pad=5)

        self.tab10_canvas.draw_idle()
    except Exception as exc:
        try:
            self.tab10_fit_status_var.set(
                f'Layout adjustment warning: {type(exc).__name__}: {exc}'
            )
        except Exception:
            pass


@_auto_open_export
def _tab10_export_figures_png(self):
    """Export the four visible Tab-10 panels as separate 300-ppi PNG files."""
    if _ii2d_enabled(self,10):return _ii2d_export_figures(self,10)
    if getattr(self, 'tab10_fig', None) is None:
        messagebox.showwarning('Tab 10 Export', 'Tab 10 figure is not available.', parent=self.root)
        return
    folder = _export_capture_folder(filedialog.askdirectory, parent=self.root, title='Select folder for Tab 10 figure export')
    if not folder:
        return
    fig = self.tab10_fig
    all_axes = list(fig.axes)
    frame = int(getattr(self, 'tab10_frame_var', tk.IntVar(value=0)).get()) + 1
    field = np.nan
    try:
        field = float(_tab10_intensity_field(self, frame - 1))
    except Exception:
        pass
    field_txt = f'{field:+.2f}mT' if np.isfinite(field) else 'FieldNA'
    groups = [
        ('Figure1_ROI4_Image', [self.tab10_ax_image] + ([self._tab10_cbar_image.ax] if getattr(self, '_tab10_cbar_image', None) is not None else [])),
        ('Figure2_LineProfiles', [self.tab10_ax_profiles]),
        ('Figure3_GaussianFit', [self.tab10_ax_fit] + ([self._tab10_fit_residual_ax] if getattr(self, '_tab10_fit_residual_ax', None) is not None else [])),
        ('Figure4_Diameter_CoreIntensity_vs_Field' if bool(getattr(self,'tab10_dfit_var',None) is not None and self.tab10_dfit_var.get()) else 'Figure4_FWHM_Amplitude_vs_Field', [self.tab10_ax_tracking] + ([self._tab10_ax_tracking2] if getattr(self, '_tab10_ax_tracking2', None) is not None else []) + ([self._tab10_tracking_secx] if getattr(self, '_tab10_tracking_secx', None) is not None else [])),
    ]
    visible_state = {ax: ax.get_visible() for ax in all_axes}
    written = []
    try:
        for stem, keep_axes in groups:
            keep = {ax for ax in keep_axes if ax is not None and ax in all_axes}
            for ax in all_axes:
                ax.set_visible(ax in keep)
            fig.canvas.draw()
            path = os.path.join(folder, f'Tab10_ROI4_{stem}_Frame{frame:03d}_{field_txt}.png')
            _export_capture_write(fig.savefig, path, dpi=300, bbox_inches='tight', pad_inches=0.15, facecolor='white')
            written.append(path)
    finally:
        for ax, state in visible_state.items():
            try:
                ax.set_visible(state)
            except Exception:
                pass
        fig.canvas.draw_idle()
    if hasattr(self, 'tab10_ii_fig'):
        _tab10_sync_intensity_values(self)
        _tab10_plot_intensity(self)
        self.tab10_ii_canvas.draw()
        path = os.path.join(folder, f'Tab10_ROI4_Figure5_Diameter_IntegratedIntensity_Frame{frame:03d}_{field_txt}.png')
        _export_capture_write(self.tab10_ii_fig.savefig, path, dpi=300, bbox_inches='tight', pad_inches=0.15, facecolor='white')
        written.append(path)
    self.tab10_export_status_var.set(f'✓ Exported {len(written)} separate Tab 10 figures at 300 ppi.')
    messagebox.showinfo('Tab 10 Export', f'Exported {len(written)} separate PNG figures (300 ppi) to:\n{folder}', parent=self.root)



