def _tab10_mode_changed(self, mode):
    if mode == 'gaussian':
        if bool(self.tab10_gaussian_var.get()):
            self.tab10_dfit_var.set(False)
        else:
            self.tab10_gaussian_var.set(True)
    elif mode == 'dfit':
        if bool(self.tab10_dfit_var.get()):
            self.tab10_gaussian_var.set(False)
        else:
            self.tab10_dfit_var.set(True)

    _tab10_apply_mode_ui(self)

    # Keep Figure-4 axis selections synchronized with the active analysis mode.
    # Gaussian mode -> FWHM + Gaussian Amplitude.
    # D-FIT mode    -> D-FIT Diameter + D-FIT Intensity.
    # The dropdowns remain available for manual alternative selection.
    try:
        if bool(self.tab10_dfit_var.get()):
            self.tab10_plot_y1_var.set('D-Fit Diameter (nm)')
            self.tab10_plot_y2_var.set('Core Intensity (a.u.)')
            if hasattr(self, 'tab10_plot_y1_combo'):
                self.tab10_plot_y1_combo.set('D-Fit Diameter (nm)')
            if hasattr(self, 'tab10_plot_y2_combo'):
                self.tab10_plot_y2_combo.set('Core Intensity (a.u.)')
        else:
            self.tab10_plot_y1_var.set('Gaussian FWHM (nm)')
            self.tab10_plot_y2_var.set('Gaussian Amplitude (a.u.)')
            if hasattr(self, 'tab10_plot_y1_combo'):
                self.tab10_plot_y1_combo.set('Gaussian FWHM (nm)')
            if hasattr(self, 'tab10_plot_y2_combo'):
                self.tab10_plot_y2_combo.set('Gaussian Amplitude (a.u.)')
    except Exception:
        pass

    # IMPORTANT: changing Gaussian/D-Fit mode must NOT start a fit or tracking run.
    # Only refresh the ROI display/labels. Fitting starts only when the user clicks
    # FIT CURRENT ROI or TRACK-SELECTED FRAMES.
    try:
        if getattr(self, '_tab10_roi4_stack', None) is not None:
            _tab10_render_current(self, int(self.tab10_frame_var.get()))
        if isinstance(getattr(self, '_tab10_tracking_df', None), pd.DataFrame) and not self._tab10_tracking_df.empty:
            _tab10_plot_tracking(self, self._tab10_tracking_df,
                                 int(self.tab10_start_var.get()),
                                 int(self.tab10_end_var.get()),
                                 draw_now=True)
        mode_text = 'D-Fit selected — click FIT CURRENT ROI or TRACK-SELECTED FRAMES to calculate.' if bool(self.tab10_dfit_var.get()) else '1D-Gaussian selected — click FIT CURRENT ROI or TRACK-SELECTED FRAMES to calculate.'
        self.tab10_fit_status_var.set(mode_text)
    except Exception as exc:
        try:
            self.tab10_fit_status_var.set(f'Mode update failed: {type(exc).__name__}: {exc}')
        except Exception:
            pass


