# ---------------------------------------------------------------------------

# ---------------------------------------------------------------------------
# TAB 11 — MULTI-ROI 1D GAUSSIAN / FWHM
# ---------------------------------------------------------------------------
# Layout requested:
#   3 rows x 2 columns
#   Row 1: [Processed Primary ROI1 from Tab 6] [Selected ROI]
#   Row 2: [Current ROI average profile + Gaussian + residual]
#          [Current ROI FWHM + amplitude vs field/frame]
#   Row 3: [Average FWHM + amplitude of ALL selected ROIs vs field/frame]
#
# Both the figure panel and the right control panel support scrolling.
# The divider between them is adjustable through a horizontal Panedwindow.
# ---------------------------------------------------------------------------

def _tab11_field_mT(self, idx):
    return _tab10_intensity_field(self, idx)


def _tab11_scale_nm(self):
    try:
        v = _tab6_effective_nm_per_output_px(self)
        if v is not None:
            sx, sy = float(v[0]), float(v[1])
            if np.isfinite(sx) and np.isfinite(sy) and sx > 0 and sy > 0:
                return sx, sy
    except Exception:
        pass
    try:
        v = float(self.primary_roi_final_nm_per_pixel)
        if np.isfinite(v) and v > 0:
            return v, v
    except Exception:
        pass
    return None, None


def _tab11_primary_processed_image(self, idx):
    """Fetch the EXACT image displayed by Tab 6 ROI Processing for this frame.

    The fetch is robust to Tab 6 having a confirmed Primary ROI whose output
    resolution has not yet been explicitly applied. In that case we apply the
    existing Tab-6 resolution path using the confirmed ROI dimensions; this
    does not alter the processing/fitting algorithms.
    """
    if getattr(self, 'recons', None) is None:
        return None

    if not getattr(self, 'roi_resolution_applied', False):
        try:
            if getattr(self, 'roi_mask', None) is None:
                return None
            width = int(float(str(getattr(self, 'roi_width_var').get()).strip()))
            height = int(float(str(getattr(self, 'roi_height_var').get()).strip()))
            if width < 1 or height < 1:
                width = int(getattr(self, 'original_roi_w', 0) or 0)
                height = int(getattr(self, 'original_roi_h', 0) or 0)
            if width < 1 or height < 1:
                return None
            _proc_apply_resolution(self, width, height)
        except Exception as exc:
            try:
                self.tab11_status_var.set(
                    f'Tab-6 Primary ROI is confirmed but its output resolution could not be applied: '
                    f'{type(exc).__name__}: {exc}'
                )
            except Exception:
                pass
            return None

    try:
        image = np.asarray(_proc_image(self, int(idx)), dtype=_intensity_dtype(self))
        view = str(getattr(self, 'view_var').get() or 'Image')

        if view == 'Image':
            display = image

        elif view == 'FFT':
            _, display = _proc_fft(self, image)

        else:
            # Exact Tab-6 IFFT path.
            F, _ = _proc_fft(self, image)
            Fm, _ = _proc_fft_mask(self, F, self.fft_mask_var.get())
            r = np.abs(_compute_fft2(np.fft.ifftshift(Fm), inverse=True))
            mn = float(np.nanmin(r))
            mx = float(np.nanmax(r))
            display = (r - mn) / (mx - mn + 1e-12)
            display = np.where(
                np.asarray(self.local_mask, dtype=bool),
                display,
                0.0
            )

        return np.asarray(display, dtype=_intensity_dtype(self))

    except Exception as exc:
        try:
            self.tab11_status_var.set(
                f'Cannot fetch Tab-6 processed/display image: '
                f'{type(exc).__name__}: {exc}'
            )
        except Exception:
            pass
        return None



def _tab11_fetch_primary(self, preserve_frame=True):
    """Fetch Tab-6 Primary ROI1 without requiring a separate manual resolution click.

    If Tab 6 already has a confirmed Primary ROI but ``roi_resolution_applied``
    is false, use the same existing Tab-6 ``_proc_apply_resolution`` path with
    the current/confirmed ROI dimensions. No D-Fit, Gaussian-fit, tracking,
    export, or other analysis logic is changed.
    """
    if getattr(self, 'recons', None) is None:
        self.tab11_status_var.set('No reconstruction data loaded.')
        return False

    # Tab 6 can have a valid confirmed Primary ROI before the output-resolution
    # flag is set. Prepare that existing Tab-6 state so FETCH works directly.
    if not getattr(self, 'roi_resolution_applied', False):
        try:
            if getattr(self, 'roi_mask', None) is None:
                self.tab11_status_var.set(
                    'No confirmed Primary ROI is available in Tab 6. Confirm Primary ROI first.'
                )
                return False
            width = int(float(str(getattr(self, 'roi_width_var').get()).strip()))
            height = int(float(str(getattr(self, 'roi_height_var').get()).strip()))
            if width < 1 or height < 1:
                width = int(getattr(self, 'original_roi_w', 0) or 0)
                height = int(getattr(self, 'original_roi_h', 0) or 0)
            if width < 1 or height < 1:
                self.tab11_status_var.set(
                    'Confirmed Primary ROI exists, but its dimensions are unavailable in Tab 6.'
                )
                return False
            _proc_apply_resolution(self, width, height)
        except Exception as exc:
            self.tab11_status_var.set(
                f'Could not prepare the confirmed Tab-6 Primary ROI: '
                f'{type(exc).__name__}: {exc}'
            )
            return False

    sx, sy = _tab11_scale_nm(self)
    if sx is None or sy is None:
        self.tab11_status_var.set('Primary ROI physical calibration is unavailable.')
        return False

    try:
        old_idx = int(self.tab11_frame_var.get()) if preserve_frame else 0
    except Exception:
        old_idx = 0

    n = len(self.recons)
    old_idx = max(0, min(old_idx, n - 1))

    frames = []
    for i in range(n):
        arr = _tab11_primary_processed_image(self, i)
        if arr is None:
            self.tab11_status_var.set(
                f'Failed to fetch processed Primary ROI frame {i + 1}/{n}.'
            )
            return False
        frames.append(arr)

    self._tab11_primary_stack = np.asarray(frames, dtype=_intensity_dtype(self))
    self._tab11_scale_nm = (float(sx), float(sy))
    self._tab11_primary_ready = True

    # Always follow the live Tab-6 visualization settings.
    try:
        self._tab11_cmap = str(self.colormap_var.get() or 'gray')
    except Exception:
        self._tab11_cmap = str(getattr(self, '_tab11_cmap', 'gray') or 'gray')
    self._tab11_view = str(getattr(self, 'view_var').get() or 'Image')

    h, w = self._tab11_primary_stack[0].shape[:2]
    self._tab11_primary_extent = (0.0, w * sx, 0.0, h * sy)

    finite = np.isfinite(self._tab11_primary_stack[old_idx])
    if np.any(finite):
        self._tab11_clim = (
            float(np.nanmin(self._tab11_primary_stack[old_idx][finite])),
            float(np.nanmax(self._tab11_primary_stack[old_idx][finite]))
        )
        if self._tab11_clim[1] <= self._tab11_clim[0]:
            self._tab11_clim = (0.0, 1.0)
    else:
        self._tab11_clim = (0.0, 1.0)

    self._tab11_programmatic = True
    try:
        self.tab11_frame_var.set(old_idx)
        self.tab11_slider.configure(
            from_=0, to=max(0, n - 1), resolution=1, state='normal'
        )
        self.tab11_slider.set(old_idx)
        self.tab11_start_spin.configure(from_=0, to=max(0, n - 1), increment=1)
        self.tab11_end_spin.configure(from_=0, to=max(0, n - 1), increment=1)
        self.tab11_start_var.set(0)
        self.tab11_end_var.set(n - 1)
    finally:
        self._tab11_programmatic = False

    self.tab11_status_var.set(
        f'✓ Tab-6 {getattr(self, "_tab11_view", "Image")} processed Primary ROI1 fetched | '
        f'FOV = {w*sx:.6g} × {h*sy:.6g} nm | Frame {old_idx + 1}/{n}'
    )
    self._tab11_render( old_idx)
    return True



def _tab11_selected_roi_index(self):
    rois = getattr(self, '_tab11_rois', [])
    if not rois:
        return 0
    text = str(self.tab11_roi_select_var.get())
    m = re.search(r'(\d+)', text)
    try:
        idx = int(m.group(1)) - 1 if m else int(text)
    except Exception:
        idx = 0
    return max(0, min(idx, len(rois) - 1))


def _tab11_update_roi_selector(self, select_idx=None):
    rois = getattr(self, '_tab11_rois', [])
    values = [f'ROI {i + 1}' for i in range(len(rois))]
    self.tab11_roi_select_combo.configure(values=values)
    if not values:
        self.tab11_roi_select_var.set('')
        return
    if select_idx is None:
        select_idx = self._tab11_selected_roi_index(self)
    select_idx = max(0, min(int(select_idx), len(values) - 1))
    self.tab11_roi_select_var.set(values[select_idx])


def _tab11_mouse_press(self,event):
    if getattr(self,'_tab11_fixed_roi_mode',False):
        if event.inaxes is not self.tab11_ax_primary or event.xdata is None or event.ydata is None:return
        dims=getattr(self,'_tab11_fixed_roi_dims_nm',None)
        if dims is None:return
        ww,hh=dims; sx,sy=self._tab11_scale_nm; H,W=self._tab11_primary_stack.shape[1:3]
        cx,cy=float(event.xdata),float(event.ydata); total_w,total_h=W*sx,H*sy
        nx=max(0.0,min(cx-ww/2.0,total_w-ww)); ny=max(0.0,min(cy-hh/2.0,total_h-hh))
        self._tab11_fixed_roi_rect=(nx,ny,ww,hh); self._tab11_fixed_roi_dragging=False
        _tab11_draw_fixed_roi_preview(self)
        self.tab11_status_var.set(f'ROI centered at ({cx:.6g}, {cy:.6g}) nm. Click CONFIRM ROI POSITION.')
        return
    if not getattr(self,'_tab11_select_mode',False):return
    if event.inaxes is not self.tab11_ax_primary or event.xdata is None or event.ydata is None:return
    self._tab11_press_xy=(float(event.xdata),float(event.ydata))


def _tab11_mouse_move(self,event):
    if getattr(self,'_tab11_fixed_roi_mode',False): return
    if not getattr(self,'_tab11_select_mode',False) or getattr(self,'_tab11_press_xy',None) is None or event.inaxes is not self.tab11_ax_primary or event.xdata is None or event.ydata is None:return
    x0,y0=self._tab11_press_xy; x1,y1=float(event.xdata),float(event.ydata); sx,sy=self._tab11_scale_nm
    xmin_nm,xmax_nm=sorted((x0,x1)); ymin_nm,ymax_nm=sorted((y0,y1)); xmin=int(np.floor(xmin_nm/sx)); xmax=int(np.ceil(xmax_nm/sx))-1; ymin=int(np.floor(ymin_nm/sy)); ymax=int(np.ceil(ymax_nm/sy))-1
    h,w=self._tab11_primary_stack.shape[1:3]; xmin=max(0,min(xmin,w-1)); xmax=max(0,min(xmax,w-1)); ymin=max(0,min(ymin,h-1)); ymax=max(0,min(ymax,h-1))
    if xmax<=xmin or ymax<=ymin:return
    old=getattr(self,'_tab11_preview_rect',None)
    if old is not None:
        try:old.remove()
        except Exception:pass
    self._tab11_preview_rect=plt.Rectangle((xmin*sx,ymin*sy),(xmax-xmin+1)*sx,(ymax-ymin+1)*sy,fill=False,edgecolor='yellow',linewidth=2.0,linestyle='--',zorder=50)
    self.tab11_ax_primary.add_patch(self._tab11_preview_rect); self.tab11_canvas.draw_idle()


def _tab11_mouse_release(self,event):
    if getattr(self,'_tab11_fixed_roi_mode',False): return
    if not getattr(self,'_tab11_select_mode',False):return
    self._tab11_select_mode=False
    try:self.tab11_canvas.get_tk_widget().configure(cursor='')
    except Exception:pass
    c=getattr(self,'_tab11_preview_rect',None)
    if c is not None:
        try:c.remove()
        except Exception:pass
        self._tab11_preview_rect=None
    press=getattr(self,'_tab11_press_xy',None); self._tab11_press_xy=None
    if press is None or event.inaxes is not self.tab11_ax_primary or event.xdata is None or event.ydata is None:
        self.tab11_status_var.set('ROI selection cancelled.'); self.tab11_canvas.draw_idle(); return
    sx,sy=self._tab11_scale_nm; x0,y0=press; x1,y1=float(event.xdata),float(event.ydata); xmin_nm,xmax_nm=sorted((x0,x1)); ymin_nm,ymax_nm=sorted((y0,y1))
    xmin=int(np.floor(xmin_nm/sx)); xmax=int(np.ceil(xmax_nm/sx))-1; ymin=int(np.floor(ymin_nm/sy)); ymax=int(np.ceil(ymax_nm/sy))-1
    h,w=self._tab11_primary_stack.shape[1:3]; xmin=max(0,min(xmin,w-1)); xmax=max(0,min(xmax,w-1)); ymin=max(0,min(ymin,h-1)); ymax=max(0,min(ymax,h-1))
    if xmax<=xmin or ymax<=ymin:self.tab11_status_var.set('ROI is too small. Draw a larger rectangle.'); return
    self._tab11_pending_free_roi_coords = {'xmin':xmin,'xmax':xmax,'ymin':ymin,'ymax':ymax}
    try:self.tab11_confirm_roi_btn.configure(state='normal')
    except Exception:pass
    self.tab11_status_var.set(f'ROI selection ready | FOV = {(xmax-xmin+1)*sx:.6g} × {(ymax-ymin+1)*sy:.6g} nm. Click CONFIRM ROI POSITION.')
    self._tab11_render(int(self.tab11_frame_var.get()))


def _tab11_draw_fixed_roi_preview(self):
    rect=getattr(self,'_tab11_fixed_roi_rect',None)
    if rect is None or not getattr(self,'_tab11_fixed_roi_mode',False):return
    ax=self.tab11_ax_primary; old=getattr(self,'_tab11_fixed_roi_artist',None)
    if old is not None:
        try:old.remove()
        except Exception:pass
    x,y,ww,hh=rect
    self._tab11_fixed_roi_artist=plt.Rectangle((x,y),ww,hh,fill=False,edgecolor='yellow',linewidth=2.2,linestyle='--',zorder=60); ax.add_patch(self._tab11_fixed_roi_artist)
    ax.text(x+3,y+hh-4,f'Fixed ROI: {ww:g} × {hh:g} nm',color='yellow',fontsize=8,weight='bold',zorder=61,bbox=dict(facecolor='black',alpha=0.30,edgecolor='none',pad=1.5)); self.tab11_canvas.draw_idle()


def _tab11_confirm_fixed_roi(self):
    """Confirm either the movable fixed-size ROI or a pending free-form ROI."""
    pending = getattr(self, '_tab11_pending_free_roi_coords', None)
    if not getattr(self, '_tab11_fixed_roi_mode', False) and pending is not None:
        xmin=int(pending['xmin']); xmax=int(pending['xmax']); ymin=int(pending['ymin']); ymax=int(pending['ymax'])
        h,w=self._tab11_primary_stack.shape[1:3]
        if not (0<=xmin<=xmax<w and 0<=ymin<=ymax<h):
            self.tab11_status_var.set('Pending ROI is outside the processed Primary ROI.'); return
        _tab11_clear_intensity(self)
        self._tab11_rois.append({'xmin':xmin,'xmax':xmax,'ymin':ymin,'ymax':ymax})
        idx=len(self._tab11_rois)-1; sx,sy=self._tab11_scale_nm
        self._tab11_pending_free_roi_coords=None; self._tab11_center_fixed=False; self._tab11_auto_frame_fit=False; self._tab11_dynamic_centers={}; self._tab11_centers.pop(idx,None); self._tab11_last_fit=None
        try:
            self.tab11_confirm_roi_btn.configure(state='disabled'); self.tab11_canvas.get_tk_widget().configure(cursor=''); self.tab11_auto_center_btn.configure(state='normal')
        except Exception: pass
        _tab11_update_roi_selector(self,idx)
        self.tab11_status_var.set(f'✓ ROI {idx+1} confirmed | FOV = {(xmax-xmin+1)*sx:.6g} × {(ymax-ymin+1)*sy:.6g} nm')
        _tab11_render(self,int(self.tab11_frame_var.get())); return

    if not getattr(self, '_tab11_fixed_roi_mode', False):
        self.tab11_status_var.set('Select an ROI first, then click CONFIRM ROI POSITION.'); return
    rect=getattr(self,'_tab11_fixed_roi_rect',None)
    if rect is None:return
    sx,sy=self._tab11_scale_nm; x_nm,y_nm,ww_nm,hh_nm=rect; h,w=self._tab11_primary_stack.shape[1:3]
    xmin=max(0,min(int(np.floor(x_nm/sx)),w-1)); ymin=max(0,min(int(np.floor(y_nm/sy)),h-1)); xmax=max(xmin,min(int(np.ceil((x_nm+ww_nm)/sx))-1,w-1)); ymax=max(ymin,min(int(np.ceil((y_nm+hh_nm)/sy))-1,h-1))
    if xmax<=xmin or ymax<=ymin:self.tab11_status_var.set('Fixed ROI is too small after pixel conversion.'); return
    _tab11_clear_intensity(self)
    self._tab11_rois.append({'xmin':xmin,'xmax':xmax,'ymin':ymin,'ymax':ymax}); idx=len(self._tab11_rois)-1
    self._tab11_center_fixed=False; self._tab11_auto_frame_fit=False; self._tab11_dynamic_centers={}; self._tab11_centers.pop(idx,None); self._tab11_last_fit=None
    self._tab11_fixed_roi_mode=False; self._tab11_fixed_roi_dims_nm=None; self._tab11_fixed_roi_dragging=False; self._tab11_fixed_roi_drag_offset=None; self._tab11_pending_free_roi_coords=None
    artist=getattr(self,'_tab11_fixed_roi_artist',None)
    if artist is not None:
        try:artist.remove()
        except Exception:pass
    self._tab11_fixed_roi_artist=None
    try:self.tab11_confirm_roi_btn.configure(state='disabled'); self.tab11_canvas.get_tk_widget().configure(cursor='')
    except Exception:pass
    _tab11_update_roi_selector(self,idx)
    try:self.tab11_auto_center_btn.configure(state='normal')
    except Exception:pass
    self.tab11_status_var.set(f'✓ ROI {idx+1} added | FOV = {(xmax-xmin+1)*sx:.6g} × {(ymax-ymin+1)*sy:.6g} nm')
    _tab11_render(self,int(self.tab11_frame_var.get()))

def _tab11_auto_center_selected_roi(self):
    """Center the currently selected Tab-11 ROI on the strongest local
    bright/dark core contrast in the CURRENT processed Primary-ROI frame.

    The selected ROI width/height are preserved in pixels.  Only its position
    is translated.  This is intentionally per-ROI: choose ROI 1/2/3... from
    the ROI dropdown and click AUTO CENTER ROI for that ROI.
    """
    if _ii2d_enabled(self,11):return _ii2d_run(self,11)
    rois = getattr(self, '_tab11_rois', [])
    if not rois:
        try:
            messagebox.showwarning(
                'Auto Center ROI',
                'First select/confirm at least one ROI.',
                parent=self.root
            )
        except Exception:
            pass
        return False

    ridx = _tab11_selected_roi_index(self)
    if ridx < 0 or ridx >= len(rois):
        ridx = 0

    c = rois[ridx]
    try:
        frame = int(self.tab11_frame_var.get())
        image = np.asarray(
            self._tab11_primary_stack[frame],
            dtype=np.float64
        )
        if image.ndim != 2:
            raise ValueError(
                f'Processed frame has shape {image.shape}; expected 2-D image.'
            )

        h, w = image.shape
        xmin = int(c['xmin'])
        xmax = int(c['xmax'])
        ymin = int(c['ymin'])
        ymax = int(c['ymax'])

        if not (
            0 <= xmin <= xmax < w and
            0 <= ymin <= ymax < h and
            xmax > xmin and ymax > ymin
        ):
            raise ValueError('Selected ROI is outside the processed Primary ROI.')

        roi_w = xmax - xmin + 1
        roi_h = ymax - ymin + 1

        crop = image[ymin:ymax + 1, xmin:xmax + 1]
        finite = np.isfinite(crop)
        if not np.any(finite):
            raise ValueError('Selected ROI contains no valid intensity data.')

        center = _tab11_center(self, crop)
        if center['peak'] <= 0:
            raise ValueError('No isolated central core; refine the selected ROI.')
        cx_local, cy_local = center['x0'], center['y0']
        polarity = 'bright' if center['sign'] > 0 else 'dark'

        core_x = float(xmin + cx_local)
        core_y = float(ymin + cy_local)

        # Preserve the EXACT existing ROI dimensions; translate only.
        new_xmin = int(round(core_x - (roi_w - 1) / 2.0))
        new_ymin = int(round(core_y - (roi_h - 1) / 2.0))

        max_xmin = max(0, w - roi_w)
        max_ymin = max(0, h - roi_h)
        clipped = False

        clipped_x = max(0, min(new_xmin, max_xmin))
        clipped_y = max(0, min(new_ymin, max_ymin))
        if clipped_x != new_xmin or clipped_y != new_ymin:
            clipped = True

        new_c = {
            'xmin': int(clipped_x),
            'xmax': int(clipped_x + roi_w - 1),
            'ymin': int(clipped_y),
            'ymax': int(clipped_y + roi_h - 1),
        }
        _tab11_clear_intensity(self)
        rois[ridx] = new_c

        # Auto-centering changes the ROI geometry, so old centers/fits/tracking
        # results are no longer valid and must not be silently reused.
        self._tab11_centers.pop(ridx, None)
        self._tab11_dynamic_centers = {}
        self._tab11_center_fixed = False
        self._tab11_auto_frame_fit = False
        self._tab11_last_fit = None

        try:
            _tab11_clear_current_fit_views(self)
        except Exception:
            pass

        for name in ('_tab11_current_tracking_df', '_tab11_tracking_df'):
            obj = getattr(self, name, None)
            if isinstance(obj, pd.DataFrame):
                setattr(self, name, pd.DataFrame())

        _tab11_update_roi_selector(self, ridx)
        _tab11_render(self, frame)

        sx, sy = self._tab11_scale_nm
        new_w_nm = roi_w * sx
        new_h_nm = roi_h * sy
        center_x_nm = (clipped_x + (roi_w - 1) / 2.0) * sx
        center_y_nm = (clipped_y + (roi_h - 1) / 2.0) * sy

        note = ' | boundary-clipped' if clipped else ''
        self.tab11_status_var.set(
            f'✓ ROI {ridx + 1} auto-centered on {polarity} core '
            f'({center_x_nm:.3f}, {center_y_nm:.3f}) nm | '
            f'FOV = {new_w_nm:.6g} × {new_h_nm:.6g} nm{note}'
        )
        return True

    except Exception as exc:
        try:
            messagebox.showerror(
                'Auto Center ROI',
                f'Could not auto-center ROI {ridx + 1}:\n'
                f'{type(exc).__name__}: {exc}',
                parent=self.root
            )
        except Exception:
            pass
        return False


def _tab11_start_selection(self):
    self._tab11_pending_free_roi_coords = None
    try:
        self.tab11_confirm_roi_btn.configure(state='disabled')
    except Exception:
        pass
    try:
        self.tab11_auto_center_btn.configure(state='disabled')
    except Exception:
        pass
    if not getattr(self, '_tab11_primary_ready', False):
        if not _tab11_fetch_primary(self, preserve_frame=True): return
    try:
        width_nm=float(str(self.tab11_roi_width_nm_var.get()).strip()); length_nm=float(str(self.tab11_roi_length_nm_var.get()).strip())
        fixed_valid=np.isfinite(width_nm) and np.isfinite(length_nm) and width_nm>0 and length_nm>0
    except Exception:
        fixed_valid=False; width_nm=length_nm=np.nan
    if fixed_valid:
        sx,sy=self._tab11_scale_nm; h,w=self._tab11_primary_stack.shape[1:3]
        fw=max(1,int(round(width_nm/sx))); fh=max(1,int(round(length_nm/sy)))
        if fw>w or fh>h:
            self.tab11_status_var.set(f'Fixed ROI ({width_nm:g} × {length_nm:g} nm) is larger than the fetched Primary ROI; using original free-draw selection.')
            fixed_valid=False
    if fixed_valid:
        self._tab11_pending_free_roi_coords = None
        self._tab11_select_mode=False; self._tab11_fixed_roi_mode=True
        self._tab11_fixed_roi_dragging=False; self._tab11_fixed_roi_dims_nm=(float(width_nm),float(length_nm))
        total_w,total_h=w*sx,h*sy
        x0=max(0.0,min((total_w-width_nm)/2.0,total_w-width_nm)); y0=max(0.0,min((total_h-length_nm)/2.0,total_h-length_nm))
        self._tab11_fixed_roi_rect=(x0,y0,float(width_nm),float(length_nm))
        try:
            self.tab11_confirm_roi_btn.configure(state='normal'); self.tab11_canvas.get_tk_widget().configure(cursor='crosshair')
        except Exception: pass
        self.tab11_status_var.set(f'Click on the particle to center the fixed ROI ({width_nm:g} × {length_nm:g} nm), then click CONFIRM ROI POSITION.')
        _tab11_draw_fixed_roi_preview(self); return
    self._tab11_fixed_roi_mode=False; self._tab11_fixed_roi_dims_nm=None
    self._tab11_pending_free_roi_coords = None
    try:self.tab11_confirm_roi_btn.configure(state='disabled')
    except Exception:pass
    self._tab11_select_mode=True; self._tab11_press_xy=None
    self.tab11_status_var.set('SELECT ROI: drag a rectangle on the processed Primary ROI.')
    try:self.tab11_canvas.get_tk_widget().configure(cursor='crosshair')
    except Exception:pass


def _tab11_clear_selected(self):
    _tab11_clear_intensity(self)
    if not getattr(self, '_tab11_rois', []):
        return
    idx = _tab11_selected_roi_index(self)
    self._tab11_rois.pop(idx)

    old = self._tab11_centers
    self._tab11_centers = {}
    for old_idx, value in old.items():
        if old_idx == idx:
            continue
        self._tab11_centers[old_idx if old_idx < idx else old_idx - 1] = value

    self._tab11_center_fixed = False
    self._tab11_auto_frame_fit = False
    self._tab11_dynamic_centers = {}
    self._tab11_last_fit = None
    _tab11_update_roi_selector(self, min(idx, len(self._tab11_rois) - 1) if self._tab11_rois else None)
    try:
        self.tab11_auto_center_btn.configure(
            state='normal' if getattr(self, '_tab11_rois', []) else 'disabled'
        )
    except Exception:
        pass
    self.tab11_status_var.set('Selected ROI cleared.')
    self._tab11_render( int(self.tab11_frame_var.get()))


def _tab11_clear_all(self):
    _analysis_progress_update(self, 11, 0)
    _tab11_clear_intensity(self)
    """CLEAR ALL: remove every Tab-11 ROI/data point and clear all Tab-11 result graphs/tables."""
    # ------------------------------------------------------------------
    # 1. Clear ALL ROI selections, centers, marks and labels.
    # ------------------------------------------------------------------
    self._tab11_rois = []
    self._tab11_centers = {}
    self._tab11_center_fixed = False
    self._tab11_last_fit = None
    self._tab11_current_tracking_df = None
    self._tab11_tracking_df = None

    self._tab11_select_mode = False
    self._tab11_press_xy = None
    self._tab11_preview_rect = None
    self._tab11_pending_free_roi_coords = None
    self._tab11_fixed_roi_mode = False
    self._tab11_fixed_roi_dragging = False
    self._tab11_fixed_roi_drag_offset = None
    self._tab11_fixed_roi_dims_nm = None
    self._tab11_fixed_roi_rect = None
    try:
        if getattr(self, '_tab11_fixed_roi_artist', None) is not None:
            self._tab11_fixed_roi_artist.remove()
    except Exception:
        pass
    self._tab11_fixed_roi_artist = None
    try:
        self.tab11_confirm_roi_btn.configure(state='disabled')
        self.tab11_auto_center_btn.configure(state='disabled')
        self.tab11_canvas.get_tk_widget().configure(cursor='')
    except Exception:
        pass

    # ------------------------------------------------------------------
    # 2. Clear the actual data sources used by the Tab-11 graphs.
    # ------------------------------------------------------------------
    # Remove any fit/tracking result objects that may contain plotted points.
    for name in (
        '_tab11_results',
        '_tab11_fit_results',
        '_tab11_current_results',
        '_tab11_all_results',
        '_tab11_tracking_results',
    ):
        obj = getattr(self, name, None)
        if isinstance(obj, dict):
            obj.clear()
        elif isinstance(obj, list):
            obj.clear()
        else:
            try:
                setattr(self, name, None)
            except Exception:
                pass

    # ------------------------------------------------------------------
    # 3. Remove twin axes FIRST, then clear every result/graph base axis.
    #    This guarantees that no old FWHM/amplitude/frame data points
    #    survive on hidden Matplotlib twin axes.
    # ------------------------------------------------------------------
    for attr in (
        '_tab11_fit_residual_ax',
        '_tab11_current_amp_ax',
        '_tab11_current_frame_ax',
        '_tab11_all_amp_ax',
        '_tab11_all_frame_ax',
    ):
        ax = getattr(self, attr, None)
        if ax is not None:
            try:
                ax.remove()
            except Exception:
                pass
        try:
            setattr(self, attr, None)
        except Exception:
            pass

    # Figure 3 — fit profile / Gaussian / residual.
    ax = getattr(self, 'tab11_ax_fit', None)
    if ax is not None:
        try:
            ax.clear()
            ax.set_title('FIT CURRENT ROI', pad=9)
            ax.set_xlabel('Position from fixed center (nm)')
            ax.set_ylabel('Intensity (a.u.)')
            ax.grid(alpha=0.2)
        except Exception:
            pass

    # Figure 4 — current ROI tracking.
    ax = getattr(self, 'tab11_ax_current_tracking', None)
    if ax is not None:
        try:
            ax.clear()
            ax.set_title('CURRENT ROI', pad=9)
            ax.set_xlabel('Equivalent field (mT)')
            ax.set_ylabel('Gaussian FWHM (nm)')
            ax.grid(alpha=0.2)
        except Exception:
            pass

    # Figure 5 — ALL selected ROI tracking.
    ax = getattr(self, 'tab11_ax_all_tracking', None)
    if ax is not None:
        try:
            ax.clear()
            ax.set_title('ALL SELECTED ROIs', pad=9)
            ax.set_xlabel('Equivalent field (mT)')
            ax.set_ylabel('D-Fit Diameter (nm)' if bool(getattr(self,'tab11_dfit_var',None) is not None and self.tab11_dfit_var.get()) else 'Gaussian FWHM (nm)')
            ax.grid(alpha=0.2)
        except Exception:
            pass

    # ------------------------------------------------------------------
    # 4. Clear ANY Treeview table actually belonging to Tab 11.
    #    The current build may not expose the table under one fixed name,
    #    so walk only the Tab-11 widget tree and clear Treeview rows.
    # ------------------------------------------------------------------
    def _clear_tab11_treeviews(widget):
        try:
            if isinstance(widget, ttk.Treeview):
                for item in widget.get_children():
                    widget.delete(item)
        except Exception:
            pass
        try:
            for child in widget.winfo_children():
                _clear_tab11_treeviews(child)
        except Exception:
            pass

    tab11 = getattr(self, 'tab_multi_roi11', None)
    if tab11 is not None:
        _clear_tab11_treeviews(tab11)

    # Also clear explicitly named Tab-11 result tables if present.
    for name in (
        'tab11_results_tree',
        'tab11_table',
        'tab11_results_table',
        '_tab11_results_tree',
        '_tab11_table',
    ):
        tree = getattr(self, name, None)
        if tree is not None:
            try:
                for item in tree.get_children():
                    tree.delete(item)
            except Exception:
                pass

    # ------------------------------------------------------------------
    # 5. Update the ROI selector without rebuilding the Tab-11 UI.
    # ------------------------------------------------------------------
    try:
        _tab11_update_roi_selector(self)
    except Exception:
        pass

    # Render the source image/selected-ROI panels with no ROI overlays.
    # This does NOT recreate the result data points in Figures 3–5.
    try:
        if getattr(self, '_tab11_primary_ready', False):
            _tab11_render(self, int(self.tab11_frame_var.get()))
    except Exception:
        pass

    # ------------------------------------------------------------------
    # 6. Reset status text and redraw the complete figure.
    # ------------------------------------------------------------------
    try:
        self.tab11_fit_status_var.set('No fit/tracking performed. All data cleared.')
    except Exception:
        pass

    try:
        self.tab11_export_status_var.set('')
    except Exception:
        pass

    try:
        self.tab11_status_var.set(
            'CLEAR ALL: all ROI marks/labels, graph data points and table data cleared.'
        )
    except Exception:
        pass

    try:
        self.tab11_canvas.draw_idle()
    except Exception:
        pass

def _tab11_zoom(self, event):
    if not getattr(self, '_tab11_primary_ready', False):
        return
    if event.inaxes is not self.tab11_ax_primary or event.xdata is None or event.ydata is None:
        return
    ext = self._tab11_primary_extent
    if ext is None:
        return

    step = float(getattr(event, 'step', 0) or 0)
    if step == 0:
        step = 1.0 if getattr(event, 'num', None) == 4 else -1.0

    factor = 1.25 ** (-step)
    x0, x1 = self.tab11_ax_primary.get_xlim()
    y0, y1 = self.tab11_ax_primary.get_ylim()
    cx, cy = float(event.xdata), float(event.ydata)

    rx = (cx - x0) / max(x1 - x0, 1e-12)
    ry = (cy - y0) / max(y1 - y0, 1e-12)
    nx0 = cx - rx * (x1 - x0) * factor
    nx1 = cx + (1 - rx) * (x1 - x0) * factor
    ny0 = cy - ry * (y1 - y0) * factor
    ny1 = cy + (1 - ry) * (y1 - y0) * factor

    fx0, fx1, fy0, fy1 = ext
    nx0 = max(fx0, min(nx0, fx1)); nx1 = min(fx1, max(nx1, fx0))
    ny0 = max(fy0, min(ny0, fy1)); ny1 = min(fy1, max(ny1, fy0))
    if nx1 <= nx0 or ny1 <= ny0:
        return

    self.tab11_ax_primary.set_xlim(nx0, nx1)
    self.tab11_ax_primary.set_ylim(ny0, ny1)
    self.tab11_ax_primary.set_aspect('equal', adjustable='box')
    self.tab11_canvas.draw_idle()


def _tab11_reset_zoom(self):
    if not getattr(self, '_tab11_primary_ready', False):
        return
    ext = self._tab11_primary_extent
    self.tab11_ax_primary.set_xlim(ext[0], ext[1])
    self.tab11_ax_primary.set_ylim(ext[2], ext[3])
    self.tab11_ax_primary.set_aspect('equal', adjustable='box')
    self.tab11_canvas.draw_idle()


def _tab11_center(self, crop):
    return _particle_focus_center(crop, self.tab11_contrast_fraction_var.get())


def _tab11_roi_crop(self, roi_idx, frame_idx):
    rois = getattr(self, '_tab11_rois', [])
    if not rois or not getattr(self, '_tab11_primary_ready', False):
        return None, None
    roi_idx = int(roi_idx)
    if roi_idx < 0 or roi_idx >= len(rois):
        return None, None

    c = rois[roi_idx]
    image = np.asarray(self._tab11_primary_stack[int(frame_idx)], dtype=float)
    crop = image[c['ymin']:c['ymax'] + 1, c['xmin']:c['xmax'] + 1].copy()
    return crop, c


def _tab11_active_angles(self):
    """Gaussian mode uses selected reference lines; D-Fit always uses 12 radial lines."""
    if bool(getattr(self, 'tab11_dfit_var', None) is not None and self.tab11_dfit_var.get()):
        return [float(a) for a in np.arange(0.0, 360.0, 30.0)]
    return _tab11_get_angles(self)


def _tab11_get_angles(self):
    return {
        '1': [0.0],
        '2': [0.0, 90.0],
        '4': [0.0, 45.0, 90.0, 135.0],
        '6': [0.0, 30.0, 60.0, 90.0, 120.0, 150.0]
    }.get(str(self.tab11_ref_mode_var.get()), [0.0, 90.0])


def _tab11_fit_roi(self, roi_idx, frame_idx, store=True, dynamic_center=False):
    crop, bounds = _tab11_roi_crop(self, roi_idx, frame_idx)
    if crop is None:
        return None

    if dynamic_center:
        center = _tab11_center(self, crop)
        self._tab11_dynamic_centers[int(roi_idx)] = center
    elif getattr(self, '_tab11_center_fixed', False) and roi_idx in self._tab11_centers:
        center = self._tab11_centers[roi_idx]
    else:
        center = _tab11_center(self, crop)
        self._tab11_centers[roi_idx] = center

    angles = _tab11_active_angles(self)
    t_px, profiles, avg = _tab10_extract_profiles(self,
        crop, float(center['x0']), float(center['y0']),
        angles
    )

    sx, sy = self._tab11_scale_nm
    scale_line = float(np.sqrt(sx * sy)) if sx > 0 and sy > 0 else 1.0
    t_nm = np.asarray(t_px, dtype=float) * scale_line

    # Gaussian fit is always calculated and retained independently of D-Fit.
    fit = self._fit_fixed_center_1d_gaussian(t_nm, avg)

    stack = np.vstack([profiles[float(a)] for a in angles])
    per_line_rmse = np.sqrt(np.nanmean((stack - avg[None, :]) ** 2, axis=1))
    line_rmse = float(np.nanmean(per_line_rmse))
    line_cv = float(line_rmse / max(float(np.nanmax(np.abs(avg))), 1e-12))

    result = {
        'roi_index': int(roi_idx + 1),
        'frame': int(frame_idx),
        'field_mT': _tab11_field_mT(self, int(frame_idx)),
        'center_x_px': float(bounds['xmin'] + center['x0']),
        'center_y_px': float(bounds['ymin'] + center['y0']),
        'local_center_x_px': float(center['x0']),
        'local_center_y_px': float(center['y0']),
        'contrast_background': float(center['background']),
        'contrast_threshold': float(center['threshold']),
        'contrast_sign': float(center['sign']),
        'contrast_peak': float(center['peak']),
        'angles': list(angles),
        't_px': np.asarray(t_px, dtype=float),
        't_nm': t_nm,
        'profiles': profiles,
        'average_profile': np.asarray(avg, dtype=float),
        'fit_profile': np.asarray(fit['fit_profile'], dtype=float),
        'residual_profile': np.asarray(fit['residual_profile'], dtype=float),
        'background': float(fit['background']),
        'amplitude': float(fit['amplitude']),
        'amplitude_err': float(fit.get('amplitude_err', np.nan)),
        'sigma': float(fit['sigma']),
        'sigma_err': float(fit.get('sigma_err', np.nan)),
        'fwhm': float(fit['fwhm']),
        'fwhm_err': float(fit.get('fwhm_err', np.nan)),
        'r2': float(fit.get('r2', np.nan)),
        'rmse': float(fit.get('rmse', np.nan)),
        'line_rmse': line_rmse,
        'line_cv': line_cv,
        'per_line_rmse': per_line_rmse,
        'fov_width_nm': float((bounds['xmax'] - bounds['xmin'] + 1) * sx),
        'fov_height_nm': float((bounds['ymax'] - bounds['ymin'] + 1) * sy),
    }

    # D-Fit mode: original SG-gradient method by default; optional user-defined
    # threshold mode uses the averaged six-diameter profile crossings.
    sg_level = int(np.clip(round(float(getattr(self, 'tab11_dfit_sg_level_var', tk.IntVar(value=0)).get())), 0, 30))
    use_threshold = bool(getattr(self, 'tab11_dfit_threshold_mode_var', tk.BooleanVar(value=False)).get()) and bool(self.tab11_dfit_var.get())
    dfit_t_px, dfit_profiles, dfit_avg = t_px, profiles, avg
    if not all(float(a) in profiles for a in np.arange(0.0, 360.0, 30.0)):
        dfit_t_px, dfit_profiles, dfit_avg = _tab10_extract_profiles(self,
            crop, float(center['x0']), float(center['y0']), list(np.arange(0., 360., 30.)))
    result.update(dfit_input_profiles=dfit_profiles, dfit_input_t_px=np.asarray(dfit_t_px, float),
                  dfit_input_average_profile=np.asarray(dfit_avg, float),
                  dfit_scale_x_nm_per_px=float(sx), dfit_scale_y_nm_per_px=float(sy))
    if use_threshold:
        try:
            dfit_threshold = float(np.clip(float(self.tab11_dfit_threshold_var.get()), 0.00, 1.00))
        except Exception:
            dfit_threshold = 0.50
        dfit = _tab10_11_dfit_from_profiles(
            dfit_profiles, dfit_t_px, sx=float(sx), sy=float(sy), threshold=dfit_threshold,
            average_profile=np.asarray(dfit_avg, float), sg_level=sg_level
        )
    else:
        dfit = _tab10_gradient_dfit_from_profiles(
            dfit_profiles, dfit_t_px, sx=float(sx), sy=float(sy),
            sg_level=sg_level, average_profile=np.asarray(dfit_avg, float)
        )
    if dfit is not None:
        result.update({
            'diameter_nm': dfit.get('avg_diameter_nm', np.nan),
            'diameter_err_nm': dfit.get('sd_diameter_nm', np.nan),
            'dfit_sg_level': dfit.get('sg_level', sg_level),
            'dfit_sg_window_points': dfit.get('sg_window_points', np.nan),
            'dfit_measurements': dfit.get('measurements', []),
            'dfit_pair_measurements': dfit.get('pair_measurements', []),
            'core_intensity': dfit.get('core_intensity', np.nan),
            'dfit_valid_count': dfit.get('valid_count', 0),
            'dfit_normalized_average_profile': dfit.get('normalized_average_profile', np.array([])),
            'dfit_average_profile_t_nm': dfit.get('normalized_average_t_nm', dfit.get('diameter_profile_t_nm', np.array([]))),
            'dfit_radial_normalized_profiles': dfit.get('radial_normalized_profiles', {}),
            'dfit_radial_smoothed_profiles': dfit.get('radial_smoothed_profiles', {}),
            'dfit_radial_gradient_profiles': dfit.get('radial_gradient_profiles', {}),
            'dfit_diameter_profile_t_nm': dfit.get('diameter_profile_t_nm', np.array([])),
            'dfit_diameter_profiles': dfit.get('diameter_profiles', {}),
            'dfit_diameter_smoothed_profiles': dfit.get('diameter_smoothed_profiles', {}),
            # In threshold mode these are the two crossings of the averaged
            # six-diameter profile; otherwise they are the original gradient edges.
            'dfit_left_intercept_nm': dfit.get('fit_left_intercept_nm', dfit.get('left_edge_mean_nm', np.nan)),
            'dfit_right_intercept_nm': dfit.get('fit_right_intercept_nm', dfit.get('right_edge_mean_nm', np.nan)),
            'dfit_sg_slider': sg_level,
            'dfit_threshold_mode': bool(use_threshold),
            'dfit_threshold': float(dfit.get('threshold', np.nan)) if use_threshold else np.nan,
            'dfit_diameter_method': dfit.get('diameter_method', 'Savitzky-Golay radial gradient edge'),
            'dfit_scale_x_nm_per_px': float(sx),
            'dfit_scale_y_nm_per_px': float(sy),
        })
    else:
        result.update({
            'diameter_nm': np.nan, 'diameter_err_nm': np.nan,
            'dfit_sg_level': sg_level, 'dfit_sg_slider': sg_level,
            'dfit_measurements': [], 'dfit_pair_measurements': [],
            'core_intensity': np.nan, 'dfit_valid_count': 0,
            'dfit_normalized_average_profile': np.array([]),
            'dfit_average_profile_t_nm': np.array([]),
            'dfit_radial_normalized_profiles': {},
            'dfit_radial_smoothed_profiles': {},
            'dfit_radial_gradient_profiles': {},
            'dfit_diameter_profile_t_nm': np.array([]),
            'dfit_diameter_profiles': {},
            'dfit_diameter_smoothed_profiles': {},
            'dfit_left_intercept_nm': np.nan,
            'dfit_right_intercept_nm': np.nan,
            'dfit_threshold_mode': False, 'dfit_threshold': np.nan,
            'dfit_diameter_method': 'Savitzky-Golay radial gradient edge',
            'dfit_scale_x_nm_per_px': float(sx),
            'dfit_scale_y_nm_per_px': float(sy),
        })

    result['analysis_position_min_nm'] = float(np.min(t_nm))
    result['analysis_position_max_nm'] = float(np.max(t_nm))
    result['gaussian_covariance'] = np.asarray(fit['covariance'], float).copy()
    result.update(_intensity_provenance(self, int(frame_idx)))
    _tab11_update_integrated_result(self, result)
    _tab11_cache_intensity(self, result)
    last = getattr(self, '_tab11_last_fit', None)
    if (self._tab11_ii_busy and self._tab11_ii_scope == 'tracking' and isinstance(last, dict)
            and int(last['roi_index']) == int(result['roi_index'])
            and int(last['frame']) == int(result['frame'])):
        self._tab11_ii_current_result = result
    if store:
        self._tab11_last_fit = result
    return result

def _tab11_auto_analyze_current_frame(self, frame_idx=None, draw=True):
    """
    After FIX CENTERS — ALL ROIs, automatically process the current slider
    frame. ROI bounds remain fixed; the core is freshly detected in each ROI
    for the current frame, followed by profile extraction, Gaussian fitting,
    FWHM and intensity (Gaussian amplitude).
    """
    if self._tab11_ii_busy:
        return []
    if self._tab11_ii_dirty:
        self._tab11_intensity_profiles = {}
        self._tab11_tracking_df = None
        self._tab11_current_tracking_df = None
    self._tab11_ii_dirty = False
    if not getattr(self, '_tab11_primary_ready', False):
        return []
    rois = getattr(self, '_tab11_rois', [])
    if not rois:
        return []
    stack = getattr(self, '_tab11_primary_stack', None)
    if stack is None or len(stack) == 0:
        return []

    n = len(stack)
    if frame_idx is None:
        frame_idx = int(self.tab11_frame_var.get())
    frame_idx = max(0, min(int(frame_idx), n - 1))

    if not isinstance(getattr(self, '_tab11_dynamic_centers', None), dict):
        self._tab11_dynamic_centers = {}

    results=[]
    errors=[]
    for ridx in range(len(rois)):
        try:
            r=_tab11_fit_roi(self,ridx,frame_idx,store=False,dynamic_center=True)
            if r is not None:
                results.append(r)
        except Exception as exc:
            errors.append(f"ROI {ridx+1}: {type(exc).__name__}: {exc}")

    if not results:
        self.tab11_fit_status_var.set(
            f'Automatic analysis failed at frame {frame_idx+1}.')
        return []

    selected_idx=_tab11_selected_roi_index(self)
    selected=next(
        (r for r in results if int(r['roi_index'])==selected_idx+1),
        results[0])

    self._tab11_last_fit=selected

    current_row={
        'roi_index':selected['roi_index'],'frame':selected['frame'],
        'field_mT':selected['field_mT'],'fwhm':selected['fwhm'],
        'fwhm_err':selected['fwhm_err'],'diameter_nm':selected.get('diameter_nm',np.nan),'diameter_err_nm':selected.get('diameter_err_nm',np.nan),'core_intensity':selected.get('core_intensity',np.nan),'amplitude':selected['amplitude'],
        'amplitude_err':selected['amplitude_err']}
    old=getattr(self,'_tab11_current_tracking_df',None)
    rows=old.to_dict('records') if isinstance(old,pd.DataFrame) else []
    rows=[x for x in rows if not (
        int(x.get('roi_index',-999))==int(selected['roi_index']) and
        int(x.get('frame',-999))==int(selected['frame']))]
    rows.append(current_row)
    self._tab11_current_tracking_df=pd.DataFrame(rows).sort_values(
        ['frame','roi_index']).reset_index(drop=True)

    # Figure 5 tracking store: replace only same ROI/frame, retain other
    # frames visited through the slider.
    old=getattr(self,'_tab11_tracking_df',None)
    rows=old.to_dict('records') if isinstance(old,pd.DataFrame) else []
    keys={(int(r['roi_index']),int(r['frame'])) for r in results}
    rows=[x for x in rows if (int(x.get('roi_index',-999)),int(x.get('frame',-999))) not in keys]
    for r in results:
        rows.append({k:r[k] for k in (
            'roi_index','frame','field_mT','fwhm','fwhm_err','diameter_nm','diameter_err_nm','core_intensity',
            'amplitude','amplitude_err','sigma','sigma_err',
            'r2','rmse','line_rmse','line_cv')})
    self._tab11_tracking_df=pd.DataFrame(rows).sort_values(
        ['frame','roi_index']).reset_index(drop=True)

    # Display the selected ROI exactly as a current-frame fit.
    _tab11_render(self,frame_idx)
    _tab11_draw_current_fit_views(self,selected)
    _tab11_plot_tracking_panel(
        self,self._tab11_tracking_df,self.tab11_ax_all_tracking,
        mode='all',title='ALL SELECTED ROIs',
        draw=False)
    _tab11_update_params(
        self,result=selected,
        status='✓ Automatic core detection + Gaussian fit complete.')
    self.tab11_fit_status_var.set(
        f'✓ Frame {frame_idx+1}/{n} | {len(results)} ROIs | '
        f'ROI {selected["roi_index"]}: FWHM = {selected["fwhm"]:.6g} nm | '
        f'Intensity = {selected["amplitude"]:.6g}')
    if errors:
        self.tab11_status_var.set(
            f'Auto analysis: {len(results)}/{len(rois)} ROIs fitted at '
            f'frame {frame_idx+1}; ' + '; '.join(errors[:2]))
    else:
        self.tab11_status_var.set(
            f'✓ Frame {frame_idx+1}: automatically detected cores and '
            f'calculated FWHM + intensity for all {len(results)} ROIs.')
    if draw:
        self.tab11_canvas.draw_idle()
    _tab11_sync_intensity(self)
    _tab11_plot_intensity(self)
    return results

def _tab11_update_params(self, result=None, status=None):
    vars_ = getattr(self, 'tab11_param_vars', {})
    for key, var in vars_.items():
        var.set('—')

    if result is not None:
        vals = {
            'roi': f"ROI {result['roi_index']}",
            'center': f"({result['local_center_x_px']:.3f}, {result['local_center_y_px']:.3f})",
            'background': f"{result['background']:.6g}",
            'threshold': f"{result['contrast_threshold']:.6g}",
            'sign': f"{result['contrast_sign']:.0f}",
            'amplitude': f"{result['amplitude']:.6g} ± {result['amplitude_err']:.3g}",
            'core_intensity': f"{result.get('core_intensity',np.nan):.6g}",
            'sigma': f"{result['sigma']:.6g} ± {result['sigma_err']:.3g} nm",
            'fwhm': f"{result['fwhm']:.6g} ± {result['fwhm_err']:.3g} nm",
            'diameter': f"{result.get('diameter_nm',np.nan):.6g} nm",
            'diameter_sd': f"{result.get('diameter_err_nm',np.nan):.6g} nm",
            'dfit_sg': f"{result.get('dfit_sg_level',self.tab11_dfit_sg_level_var.get())}",
            'r2': f"{result['r2']:.6g}",
            'rmse': f"{result['rmse']:.6g}",
            'line_rmse': f"{result['line_rmse']:.6g}",
            'line_cv': f"{result['line_cv']:.6g}",
            'fov': f"{result['fov_width_nm']:.6g} × {result['fov_height_nm']:.6g} nm",
            'frame': f"{result['frame'] + 1} / {len(self._tab11_primary_stack)}",
            'field': (
                f"{result['field_mT']:+.6g} mT"
                if np.isfinite(result['field_mT']) else '—'
            )
        }
        for key, value in vals.items():
            if key in vars_:
                vars_[key].set(value)

    if 'status' in vars_:
        vars_['status'].set(
            status if status is not None
            else ('Gaussian fit complete.' if result is not None else 'No fit performed.')
        )


def _tab11_clear_twin_axes(self, base_ax_name):
    base = getattr(self, base_ax_name, None)
    if base is None:
        return
    tracked_names = {
        '_tab11_current_amp_ax': 'current',
        '_tab11_current_frame_ax': 'current',
        '_tab11_all_amp_ax': 'all',
        '_tab11_all_frame_ax': 'all',
        '_tab11_fit_residual_ax': 'fit',
    }
    for attr in tracked_names:
        ax = getattr(self, attr, None)
        if ax is not None:
            try:
                ax.remove()
            except Exception:
                pass
            setattr(self, attr, None)


def _tab11_plot_tracking_panel(self, df, ax_base, mode='current', title='', draw=True):
    """Figure 4/5 plot with user-selectable Y1/Y2 metrics; no aggregate-average series."""
    amp_attr = '_tab11_current_amp_ax' if mode == 'current' else '_tab11_all_amp_ax'
    frame_attr = '_tab11_current_frame_ax' if mode == 'current' else '_tab11_all_frame_ax'
    for attr in (amp_attr, frame_attr):
        old_ax = getattr(self, attr, None)
        if old_ax is not None:
            try: old_ax.remove()
            except Exception: pass
            setattr(self, attr, None)
    ax_base.clear()

    y1_choice = getattr(self, 'tab11_fig5_y1_var', tk.StringVar(value='Gaussian FWHM (nm)')).get()
    y2_choice = getattr(self, 'tab11_fig5_y2_var', tk.StringVar(value='Gaussian Amplitude (a.u.)')).get()
    y1_map = {
        'Gaussian FWHM (nm)': ('fwhm','fwhm_err','Gaussian FWHM (nm)','FWHM'),
        'D-Fit Diameter (nm)': ('diameter_nm','diameter_err_nm','D-Fit Diameter (nm)','D-Fit Diameter'),
    }
    y2_map = {
        'Gaussian Amplitude (a.u.)': ('amplitude','amplitude_err','Gaussian Amplitude (a.u.)','Gaussian Amplitude'),
        'Core Intensity (a.u.)': ('core_intensity',None,'Core Intensity (a.u.)','Core Intensity'),
    }
    size_col, err_col, y1_label, y1_legend = y1_map.get(y1_choice, y1_map['Gaussian FWHM (nm)'])
    intensity_col, intensity_err_col, y2_label, y2_legend = y2_map.get(y2_choice, y2_map['Gaussian Amplitude (a.u.)'])

    if df is None or df.empty:
        ax_base.set_title(title,pad=10); ax_base.set_xlabel('Equivalent field (mT)'); ax_base.set_ylabel(y1_label); ax_base.grid(alpha=0.2)
        if draw: self.tab11_canvas.draw_idle()
        return
    data=df.copy()
    for col in ('field_mT','frame','roi_index','fwhm','fwhm_err','diameter_nm','diameter_err_nm','amplitude','amplitude_err','core_intensity'):
        if col in data.columns: data[col]=pd.to_numeric(data[col],errors='coerce')
    data=data.dropna(subset=['frame'])
    frame_axis = _tracking_frame_axis(data)
    if data.empty:
        ax_base.set_title(title,pad=10); ax_base.set_xlabel('Equivalent field (mT)'); ax_base.set_ylabel(y1_label); ax_base.grid(alpha=0.2)
        if draw: self.tab11_canvas.draw_idle()
        return

    if mode=='current':
        ridx=_tab11_selected_roi_index(self); groups=[(ridx+1,data[data['roi_index']==ridx+1].sort_values('frame'))]
    else:
        groups=[]
        for rid in sorted(data['roi_index'].dropna().astype(int).unique()):
            g=data[data['roi_index'].astype(int)==rid].sort_values('frame')
            if not g.empty: groups.append((int(rid),g))

    ax2=ax_base.twinx(); setattr(self,amp_attr,ax2)
    for rid,g in groups:
        x = g['frame'].to_numpy(float)+1 if frame_axis else g['field_mT'].to_numpy(float)
        y=g.get(size_col,pd.Series(np.nan,index=g.index)).to_numpy(float)
        ye=pd.to_numeric(g.get(err_col,pd.Series(np.zeros(len(g)),index=g.index)),errors='coerce').fillna(0).to_numpy(float)
        yi=g.get(intensity_col,pd.Series(np.nan,index=g.index)).to_numpy(float)
        if intensity_err_col is None: yie=np.zeros(len(g),dtype=float)
        else: yie=pd.to_numeric(g.get(intensity_err_col,pd.Series(np.zeros(len(g)),index=g.index)),errors='coerce').fillna(0).to_numpy(float)
        gy=np.isfinite(x)&np.isfinite(y); gi=np.isfinite(x)&np.isfinite(yi)
        if np.any(gy): ax_base.errorbar(x[gy],y[gy],yerr=ye[gy],marker='^',linestyle='-',linewidth=1.5,capsize=2,label=f'ROI {rid} — {y1_legend}')
        if np.any(gi): ax2.errorbar(x[gi],yi[gi],yerr=yie[gi],marker='o',linestyle=':',linewidth=1.5,capsize=2,label=f'ROI {rid} — {y2_legend}')


    secx=ax_base.twiny(); setattr(self,frame_attr,secx); secx.set_xlim(ax_base.get_xlim())
    _tracking_top_axis(secx, data, frame_axis)
    ax_base.set_xlabel('Frame' if frame_axis else 'Field (mT)',labelpad=8); ax_base.set_ylabel(y1_label,labelpad=8); ax_base.set_title(title,pad=12); ax_base.grid(alpha=0.2)
    ax2.set_ylabel(y2_label,labelpad=10); ax2.yaxis.set_label_position('right'); ax2.yaxis.tick_right()
    h1,l1=ax_base.get_legend_handles_labels(); h2,l2=ax2.get_legend_handles_labels()
    if h1 or h2: ax_base.legend(h1+h2,l1+l2,fontsize=7.5,loc='upper left',bbox_to_anchor=(0.01,0.99),frameon=True)
    if draw:
        self.tab11_fig.subplots_adjust(left=0.07,right=0.94,bottom=0.07,top=0.94,wspace=0.32,hspace=0.48); self.tab11_canvas.draw_idle()

def _tab11_clear_current_fit_views(self):
    """Clear Fig.3/Fig.4 only; Fig.5/all-ROI tracking is independent."""
    # Remove residual twin axis from current fit.
    axr = getattr(self, '_tab11_fit_residual_ax', None)
    if axr is not None:
        try:
            axr.remove()
        except Exception:
            pass
        self._tab11_fit_residual_ax = None

    # Remove current ROI Figure-4 twin axes.
    for attr in ('_tab11_current_amp_ax', '_tab11_current_frame_ax'):
        ax = getattr(self, attr, None)
        if ax is not None:
            try:
                ax.remove()
            except Exception:
                pass
            setattr(self, attr, None)

    # Clear Fig.3.
    ax = getattr(self, 'tab11_ax_fit', None)
    if ax is not None:
        ax.clear()
        ax.set_title(
            'Average Line Profile — Gaussian Fit',
            pad=9
        )
        ax.set_xlabel('Position From Fixed Center (nm)')
        ax.set_ylabel('Intensity (a.u.)')
        ax.grid(alpha=0.2)

    # Clear Fig.4/current-ROI tracking.
    ax = getattr(self, 'tab11_ax_current_tracking', None)
    if ax is not None:
        ax.clear()
        ax.set_title('CURRENT ROI', pad=9)
        ax.set_xlabel('Equivalent Field (mT)')
        ax.set_ylabel('Gaussian FWHM (nm)')
        ax.grid(alpha=0.2)

    self._tab11_last_fit = None
    self._tab11_current_tracking_df = None



@_auto_open_export
def _tab11_export_multi_fit_info(self):
    """Export ALL selected-ROI line profiles for the selected frame range.

    Two separate CSV files are produced: one Gaussian-profile file and one
    D-Fit/SG-edge file. Both contain every selected ROI and every selected
    frame; the D-Fit file additionally stores SG-smoothed and gradient data.
    """
    try:
        if not getattr(self, '_tab11_primary_ready', False):
            if not _tab11_fetch_primary(self, preserve_frame=True):
                return
        rois = getattr(self, '_tab11_rois', [])
        if not rois:
            messagebox.showwarning('Tab 11 Export','Add at least one ROI first.',parent=self.root)
            return
        n=len(self._tab11_primary_stack)
        start=max(0,min(int(self.tab11_start_var.get()),n-1)); end=max(0,min(int(self.tab11_end_var.get()),n-1))
        if start>end: start,end=end,start
        folder=_export_capture_folder(filedialog.askdirectory, parent=self.root, title='Select folder for Tab 11 ALL ROI line-profile export')
        if not folder: return
        gaussian_rows=[]; dfit_rows=[]; numeric_rows=[]
        for frame in range(start,end+1):
            for ridx in range(len(rois)):
                r=_tab11_fit_roi(self,ridx,frame,store=False)
                if r is None: continue
                numeric_rows.append({k:v for k,v in r.items() if np.isscalar(v)})
                t=np.asarray(r['t_nm'],float); avg=np.asarray(r['average_profile'],float); gf=np.asarray(r['fit_profile'],float)
                raw_profiles={float(a):np.asarray(r['profiles'][float(a)],float) for a in r['angles']}
                sg_profiles=r.get('dfit_radial_smoothed_profiles',{})
                grad_profiles=r.get('dfit_radial_gradient_profiles',{})
                norm_profiles=r.get('dfit_radial_normalized_profiles',{})
                for j in range(len(t)):
                    base={'ROI':int(r['roi_index']),'Frame':int(r['frame'])+1,'Field_mT':r['field_mT'],'Position_nm':t[j],'Average_Profile':avg[j] if j<len(avg) else np.nan}
                    gr=dict(base); gr['Gaussian_Fit']=gf[j] if j<len(gf) else np.nan
                    dr=dict(base); dr['D_Fit_SG_Level']=r.get('dfit_sg_level',0); dr['D_Fit_Diameter_nm']=r.get('diameter_nm',np.nan); dr['D_Fit_SD_nm']=r.get('diameter_err_nm',np.nan); dr['Core_Intensity']=r.get('core_intensity',np.nan)
                    for a,arr in raw_profiles.items():
                        gr[f'Raw_Profile_{a:g}deg']=arr[j] if j<len(arr) else np.nan
                        dr[f'Raw_Profile_{a:g}deg']=arr[j] if j<len(arr) else np.nan
                        arrs=np.asarray(sg_profiles.get(float(a),[]),float); arrg=np.asarray(grad_profiles.get(float(a),[]),float); arrn=np.asarray(norm_profiles.get(float(a),[]),float)
                        dr[f'SG_Profile_{a:g}deg']=arrs[j] if j<len(arrs) else np.nan
                        dr[f'Gradient_{a:g}deg']=arrg[j] if j<len(arrg) else np.nan
                        dr[f'Normalized_{a:g}deg']=arrn[j] if j<len(arrn) else np.nan
                    gaussian_rows.append(gr); dfit_rows.append(dr)
        if not gaussian_rows: raise RuntimeError('No fitting results were generated in the selected frame range.')
        stem=f'Tab11_ALL_ROIs_Frames{start+1:03d}-{end+1:03d}'
        gpath=os.path.join(folder,stem+'_Gaussian_LineProfiles.csv'); dpath=os.path.join(folder,stem+'_DFit_SG_LineProfiles.csv')
        _export_capture_write(pd.DataFrame(gaussian_rows).to_csv, gpath, index=False); _export_capture_write(pd.DataFrame(dfit_rows).to_csv, dpath, index=False)
        table_path = os.path.join(folder, stem + '_Table.csv')
        figure6_path = os.path.join(folder, stem + '_Figure6.csv')
        numeric = pd.DataFrame(numeric_rows)
        table = _ii_export_table(numeric, self.tab11_integrated_intensity_var.get())
        _export_capture_write(table.to_csv, table_path, index=False)
        _export_capture_write(table.to_csv, figure6_path, index=False)
        self.tab11_export_status_var.set(f'✓ Exported table + Figure 6 + Gaussian + D-Fit line profiles: {Path(gpath).name}; {Path(dpath).name}')
        messagebox.showinfo('Tab 11 Export ALL ROI',f'Exported selected frames {start+1}–{end+1}.\n\nGaussian:\n{gpath}\n\nD-Fit/SG:\n{dpath}\n\nTable:\n{table_path}\n\nFigure 6:\n{figure6_path}',parent=self.root)
    except Exception as exc:
        self.tab11_export_status_var.set(f'✗ ALL ROI export failed: {type(exc).__name__}: {exc}')
        _export_error_dialog(messagebox.showerror, 'Tab 11 Export — ALL ROI', f'{type(exc).__name__}: {exc}', parent=self.root)


def _tab11_render(self, idx=None):
    if _ii2d_enabled(self,11):return _ii2d_render_safe(self,11,idx)
    if not getattr(self, '_tab11_primary_ready', False):
        return

    n = len(self._tab11_primary_stack)
    idx = int(self.tab11_frame_var.get()) if idx is None else int(idx)
    idx = max(0, min(idx, n - 1))
    self.tab11_frame_var.set(idx)

    sx, sy = self._tab11_scale_nm
    image = np.asarray(self._tab11_primary_stack[idx], dtype=float)
    h, w = image.shape[:2]
    ext = (0.0, w*sx, 0.0, h*sy)
    self._tab11_primary_extent = ext

    _tab11_limits = _intensity_limits(self, idx, True)

    # ---------- Row 1 / Col 1: processed Primary ROI1 ----------
    self.tab11_ax_primary.clear()
    # Pull the live Tab-6 colormap each time the frame is rendered.
    try:
        self._tab11_cmap = str(self.colormap_var.get() or self._tab11_cmap)
    except Exception:
        pass

    im = self.tab11_ax_primary.imshow(
        image, cmap=self._tab11_cmap, origin='lower',
        extent=ext, vmin=_tab11_limits[0], vmax=_tab11_limits[1],
        interpolation='nearest', aspect='equal'
    )
    self.tab11_ax_primary.set_title(
        f'{getattr(self, "_tab11_view", "")}| PROCESSED ROI | '
        f'Frame {idx + 1}/{n} | {_analysis_field_label(_tab11_field_mT(self, idx))}',
        pad=9
    )
    self.tab11_ax_primary.set_xlabel('X (nm)')
    self.tab11_ax_primary.set_ylabel('Y (nm)')
    self.tab11_ax_primary.set_xlim(ext[0], ext[1])
    self.tab11_ax_primary.set_ylim(ext[2], ext[3])
    self.tab11_ax_primary.set_aspect('equal', adjustable='box')
    self.tab11_ax_primary.grid(alpha=0.10)

    _tab11_bind_colorbar(self, im)

    palette = ['red', 'lime', 'cyan', 'magenta', 'orange', 'yellow', 'white', 'purple']
    for ridx, c in enumerate(getattr(self, '_tab11_rois', [])):
        col = palette[ridx % len(palette)]
        self.tab11_ax_primary.add_patch(plt.Rectangle(
            (c['xmin']*sx, c['ymin']*sy),
            (c['xmax'] - c['xmin'] + 1)*sx,
            (c['ymax'] - c['ymin'] + 1)*sy,
            fill=False, edgecolor=col, linewidth=2.0, zorder=20
        ))
        self.tab11_ax_primary.text(
            c['xmin']*sx + 4*sx,
            c['ymax']*sy - 6*sy,
            f'ROI {ridx + 1}',
            color=col, fontsize=9, weight='bold',
            bbox=dict(facecolor='black', alpha=0.26, edgecolor='none', pad=1.4),
            zorder=21
        )

    # ---------- Row 1 / Col 2: selected ROI ----------
    self.tab11_ax_selected.clear()
    if getattr(self, '_tab11_rois', []):
        ridx = _tab11_selected_roi_index(self)
        crop, bounds = _tab11_roi_crop(self, ridx, idx)
    else:
        ridx, crop, bounds = 0, None, None

    if crop is None:
        self.tab11_ax_selected.imshow(
            np.zeros((10, 10)), cmap=self._tab11_cmap, origin='lower',
            extent=(0, 10, 0, 10), vmin=_tab11_limits[0], vmax=_tab11_limits[1],
            interpolation='nearest', aspect='equal'
        )
        self.tab11_ax_selected.set_title('SELECTED ROI — none', pad=9)
        self.tab11_ax_selected.set_xlabel('X (nm)')
        self.tab11_ax_selected.set_ylabel('Y (nm)')
    else:
        roi_h, roi_w = crop.shape
        self.tab11_ax_selected.imshow(
            crop, cmap=self._tab11_cmap, origin='lower',
            extent=(0, roi_w*sx, 0, roi_h*sy),
            vmin=_tab11_limits[0], vmax=_tab11_limits[1],
            interpolation='nearest', aspect='equal'
        )
        self.tab11_ax_selected.set_title(
            f'Selected ROI—{ridx + 1}  | Frame {idx + 1}/{n}',
            pad=9
        )
        self.tab11_ax_selected.set_xlabel('X (nm)')
        self.tab11_ax_selected.set_ylabel('Y (nm)')
        self.tab11_ax_selected.set_xlim(0, roi_w*sx)
        self.tab11_ax_selected.set_ylim(0, roi_h*sy)
        self.tab11_ax_selected.set_aspect('equal', adjustable='box')

        center = (
            self._tab11_dynamic_centers.get(ridx)
            if getattr(self, '_tab11_auto_frame_fit', False)
            else self._tab11_centers.get(ridx)
        )
        if center is not None:
            self.tab11_ax_selected.plot(
                center['x0']*sx, center['y0']*sy,
                marker='+', markersize=14, markeredgewidth=2.4,
                color='white', linestyle='None', label='Fixed center'
            )
            angles = _tab11_active_angles(self)
            rmax = 2.0 * max(1.0, min(
                center['x0'], roi_w - 1 - center['x0'],
                center['y0'], roi_h - 1 - center['y0']
            ))
            tline = np.array([-rmax, rmax], dtype=float)
            for ai, angle in enumerate(angles):
                th = np.deg2rad(float(angle))
                self.tab11_ax_selected.plot(
                    (center['x0'] + tline*np.cos(th))*sx,
                    (center['y0'] + tline*np.sin(th))*sy,
                    linewidth=1.5, color=palette[ai % len(palette)],
                    label=f'{angle:g}°'
                )

            if bool(getattr(self, 'tab11_dfit_var', None) is not None and self.tab11_dfit_var.get()):
                fit_result = getattr(self, '_tab11_last_fit', None)
                measurements = (fit_result or {}).get('dfit_measurements', []) if isinstance(fit_result, dict) else []
                sg = (fit_result or {}).get('dfit_sg_level', getattr(self, 'tab11_dfit_sg_level_var', tk.IntVar(value=0)).get()) if isinstance(fit_result, dict) else getattr(self, 'tab11_dfit_sg_level_var', tk.IntVar(value=0)).get()
                for m in measurements:
                    rr = float(m.get('radius_nm', np.nan)); aa = float(m.get('angle_deg', np.nan))
                    if not (np.isfinite(rr) and np.isfinite(aa)):
                        continue
                    th = np.deg2rad(aa)
                    rr_px = rr / (float(np.sqrt(sx*sy)) if sx > 0 and sy > 0 else 1.0)
                    self.tab11_ax_selected.plot((center['x0'] + rr_px*np.cos(th))*sx,(center['y0'] + rr_px*np.sin(th))*sy,
                                                 marker='o',markersize=4.5,markerfacecolor='none',
                                                 markeredgecolor='red',markeredgewidth=1.5,linestyle='None',zorder=25)
                self.tab11_ax_selected.text(0.02,0.98,f'D-Fit: SG = {int(sg)}',
                                             transform=self.tab11_ax_selected.transAxes,va='top',ha='left',fontsize=8,
                                             bbox=dict(facecolor='black',alpha=0.28,edgecolor='none',pad=2),color='white',zorder=26)
            self.tab11_ax_selected.legend(fontsize=7, loc='best')

    # ---------- Row 2 / Col 1: fit detail ----------
    if getattr(self, '_tab11_last_fit', None) is None:
        self.tab11_ax_fit.clear()
        self.tab11_ax_fit.set_title('FIT CURRENT ROI | Average Line Profile - Gaussian Fit', pad=9)
        self.tab11_ax_fit.set_xlabel('Position from fixed center (nm)')
        self.tab11_ax_fit.set_ylabel('Intensity (a.u.)')
        self.tab11_ax_fit.grid(alpha=0.2)

    try:
        self.tab11_frame_label_var.set(
            f'Frame {idx + 1}/{n} | {_analysis_field_label(_tab11_field_mT(self, idx))}'
        )
    except Exception:
        pass

    self.tab11_fig.subplots_adjust(
        left=0.065, right=0.90, bottom=0.06, top=0.95,
        wspace=0.30, hspace=0.52
    )
    self.tab11_canvas.draw_idle()



def _tab11_draw_current_fit_views(self, result):
    # Remove only Tab-11-owned twin axes from the previous draw.
    for attr in ('_tab11_fit_residual_ax', '_tab11_current_amp_ax', '_tab11_current_frame_ax'):
        old = getattr(self, attr, None)
        if old is not None:
            try:
                old.remove()
            except Exception:
                pass
            setattr(self, attr, None)

    ax = self.tab11_ax_fit
    ax.clear()
    _ii2d_prepare_line_axis(ax)
    t = np.asarray(result['t_nm'], float)
    avg = np.asarray(result['average_profile'], float)

    if bool(self.tab11_dfit_var.get()):
        # ------------------------------------------------------------
        # Tab-11 Fig. 3 intentionally mirrors Tab-10 Fig. 2.
        # The calculation itself is unchanged and is still performed by
        # _tab10_gradient_dfit_from_profiles(). Only the visualization is
        # made identical: 12 raw directional profiles on Y1, raw average,
        # normalized SG-smoothed six-diameter average on Y2, the two mean
        # gradient-edge points, and the green D-Fit diameter guide.
        # ------------------------------------------------------------
        for angle in result['angles']:
            th_a = np.deg2rad(float(angle))
            step_a = float(np.hypot(
                result.get('dfit_scale_x_nm_per_px', 1.0) * np.cos(th_a),
                result.get('dfit_scale_y_nm_per_px', 1.0) * np.sin(th_a)
            ))
            self.tab11_ax_fit.plot(
                np.asarray(result['t_px'], float) * step_a,
                result['profiles'][float(angle)],
                linewidth=0.9,
                alpha=0.58,
                label=f'{angle:g}°'
            )

        self.tab11_ax_fit.plot(
            t, avg,
            color='black', linewidth=2.5,
            label='Avg. line profile'
        )

        ra = self.tab11_ax_fit.twinx()
        self._tab11_fit_residual_ax = ra

        norm_avg = np.asarray(
            result.get('dfit_normalized_average_profile', np.full_like(t, np.nan)),
            float
        )
        norm_t = np.asarray(
            result.get('dfit_average_profile_t_nm', result.get('dfit_diameter_profile_t_nm', t)),
            float
        )

        if norm_avg.size == norm_t.size and norm_avg.size >= 2:
            ra.plot(
                norm_t, norm_avg,
                color='purple', linewidth=2.0,
                label='SG-smoothed'
            )

        left = float(result.get('dfit_left_intercept_nm', np.nan))
        right = float(result.get('dfit_right_intercept_nm', np.nan))

        if np.isfinite(left) and np.isfinite(right):
            threshold_mode = bool(result.get('dfit_threshold_mode', False))
            threshold_value = float(result.get('dfit_threshold', np.nan)) if threshold_mode else 0.0
            if threshold_mode and np.isfinite(threshold_value):
                ra.axhline(threshold_value, color='gray', linestyle='--', linewidth=1.0, zorder=12,
                           label=f'Threshold = {threshold_value:.2f}')
            guide_y = threshold_value if threshold_mode and np.isfinite(threshold_value) else 0.0
            ra.plot(
                [left, right], [guide_y, guide_y],
                color='green', linewidth=1.5,
                solid_capstyle='round', zorder=18,
                label=f'Diameter = {right-left:.4g} nm'
            )
            if norm_t.size == norm_avg.size and norm_t.size >= 2:
                vals = np.interp([left, right], norm_t, norm_avg)
                if np.all(np.isfinite(vals)):
                    ra.plot(
                        [left, right], vals, 'o', ms=5.5,
                        markerfacecolor='red', markeredgecolor='black', markeredgewidth=0.7,
                        zorder=20,
                        label='Threshold crossing points' if threshold_mode else 'Edge points'
                    )

        ra.set_ylabel('Normalized Intensity (a.u.)')
        ra.yaxis.set_label_position('right')
        ra.yaxis.tick_right()

        self.tab11_ax_fit.axvline(
            0.0, color='gray', linestyle=':', linewidth=1.0,
            label='Center'
        )
        self.tab11_ax_fit.set_title(
            'Avg. line profile — D-Fit (radial gradient edge)'
        )
        self.tab11_ax_fit.set_xlabel('Position from fixed center (nm)')
        self.tab11_ax_fit.set_ylabel('Intensity (a.u.)')
        self.tab11_ax_fit.grid(alpha=0.2)

        h1, l1 = self.tab11_ax_fit.get_legend_handles_labels()
        h2, l2 = ra.get_legend_handles_labels()
        self.tab11_ax_fit.legend(
            h1 + h2, l1 + l2,
            fontsize=7,
            loc='best'
        )

    else:
        # Gaussian mode remains independent and unchanged.
        ax.plot(t, avg, color='black', linewidth=2.0, label='Average full profile')
        ax.plot(t, result['fit_profile'], linestyle='--', linewidth=2.0,
                color='blue', label='Fixed-center Gaussian fit')
        ax.axvline(0.0, linestyle=':', linewidth=1.0, label='Fixed center')
        ra = ax.twinx()
        self._tab11_fit_residual_ax = ra
        ra.plot(t, result['residual_profile'], linestyle=':', linewidth=1.5, label='Residual')
        ra.axhline(0.0, linestyle='--', linewidth=.8)
        ra.set_ylabel('Residual')
        ra.yaxis.tick_right()
        ax.set_title(f'ROI—{result["roi_index"]} Average Line Profile — Gaussian Fit', pad=10)
        ax.set_xlabel('Position from fixed center (nm)')
        ax.set_ylabel('Intensity (a.u.)')
        ax.grid(alpha=.2)
        h1, l1 = ax.get_legend_handles_labels()
        h2, l2 = ra.get_legend_handles_labels()
        ax.legend(h1+h2, l1+l2, fontsize=8, loc='best')

    current_df = getattr(self, '_tab11_current_tracking_df', None)
    _tab11_plot_tracking_panel(
        self, current_df, self.tab11_ax_current_tracking,
        mode='current', title=f'ROI—{result["roi_index"]} Tracking', draw=False
    )

    self.tab11_fig.subplots_adjust(
        left=.065, right=.90, bottom=.06, top=.95,
        wspace=.30, hspace=.52
    )
    self.tab11_canvas.draw_idle()

def _tab11_fit_current(self):
    if _ii2d_enabled(self,11):return _ii2d_run(self,11)
    if self._tab11_ii_busy:
        return
    job = self._tab11_ii_recalculate_job
    if job:
        self.root.after_cancel(job)
    self._tab11_ii_recalculate_job = None
    self._tab11_ii_scope = 'current'
    self._tab11_ii_busy = True
    if self._tab11_ii_dirty:
        self._tab11_intensity_profiles = {}
        self._tab11_tracking_df = None
        self._tab11_current_tracking_df = None
    self._tab11_ii_dirty = False
    run_source = self._tab11_primary_stack
    run_rois = [dict(r) for r in self._tab11_rois]
    try:
        # A new explicit FIT CURRENT ROI request starts a fresh operation.
        self._tab11_stop_requested = False
        if not getattr(self, '_tab11_primary_ready', False):
            if not _tab11_fetch_primary(self, preserve_frame=True):
                return
        if not getattr(self, '_tab11_rois', []):
            messagebox.showwarning(
                'Tab 11',
                'Add at least one ROI first.',
                parent=self.root
            )
            return

        run_source = self._tab11_primary_stack
        ridx = _tab11_selected_roi_index(self)
        frame = int(self.tab11_frame_var.get())

        _analysis_progress_update(self, 11, 0)
        try:
            result = _tab11_fit_roi(self, ridx, frame, store=True)
            if result is None:
                raise RuntimeError('No fitting result returned for the selected ROI.')

            self._tab11_last_fit = result
            self._tab11_current_tracking_df = pd.DataFrame([{
                'roi_index': result['roi_index'],
                'frame': result['frame'],
                'field_mT': result['field_mT'],
                'fwhm': result['fwhm'],
                'fwhm_err': result['fwhm_err'],
                'diameter_nm': result.get('diameter_nm', np.nan),
                'diameter_err_nm': result.get('diameter_err_nm', np.nan),
                'core_intensity': result.get('core_intensity', np.nan),
                'amplitude': result['amplitude'],
                'amplitude_err': result['amplitude_err']
            }])

            # Render source/selected ROI without touching Fig.3/Fig.4.
            self._tab11_render( frame)

            # Deterministically redraw only Fig.3 and Fig.4.
            _tab11_draw_current_fit_views(self, result)

            if bool(self.tab11_dfit_var.get()):
                status='✓ D-Fit complete; Gaussian FWHM retained for reference.'
                status_text=(f'✓ ROI {result["roi_index"]} D-Fit complete | Avg.Diameter = {result.get("diameter_nm",np.nan):.6g} nm | SD = {result.get("diameter_err_nm",np.nan):.6g} nm | Core Intensity = {result.get("core_intensity",np.nan):.6g} | Threshold = {result.get("dfit_sg_level",self.tab11_dfit_sg_level_var.get()):.3f} | Gaussian FWHM = {result["fwhm"]:.6g} nm')
            else:
                status='✓ Gaussian fit complete.'
                status_text=(f'✓ ROI {result["roi_index"]} Gaussian fit complete | FWHM = {result["fwhm"]:.6g} nm | Amplitude = {result["amplitude"]:.6g}')
            _tab11_update_params(self, result=result, status=status)
            _analysis_progress_update(self, 11, 1)
            self.tab11_fit_status_var.set(status_text)

        except Exception as exc:
            self._tab11_last_fit = None
            self._tab11_current_tracking_df = None
            _tab11_clear_current_fit_views(self)
            self.tab11_fit_status_var.set(
                f'✗ FIT CURRENT ROI failed: {type(exc).__name__}: {exc}'
            )
            messagebox.showerror(
                'Tab 11 — FIT CURRENT ROI',
                f'{type(exc).__name__}: {exc}',
                parent=self.root
            )
    finally:
        self._tab11_ii_busy = False
        if run_source is self._tab11_primary_stack and run_rois == self._tab11_rois:
            _tab11_sync_intensity(self)
            _tab11_plot_intensity(self)



def _tab11_recalculate_center_selected(self):
    if not getattr(self, '_tab11_primary_ready', False):
        if not _tab11_fetch_primary(self, preserve_frame=True):
            return
    if not getattr(self, '_tab11_rois', []):
        messagebox.showwarning('Tab 11', 'Add at least one ROI first.', parent=self.root)
        return

    ridx = _tab11_selected_roi_index(self)
    frame = int(self.tab11_frame_var.get())
    crop, _ = _tab11_roi_crop(self, ridx, frame)
    if crop is None:
        return

    center = _tab11_center(self, crop)
    self._tab11_centers[ridx] = center
    self._tab11_center_fixed = False
    self._tab11_last_fit = None

    self.tab11_status_var.set(
        f'✓ ROI {ridx + 1} center recalculated | '
        f'center = ({center["x0"]:.3f}, {center["y0"]:.3f})'
    )
    _tab11_update_params(self, status='Center recalculated. Fit the selected ROI.')
    self._tab11_render( frame)
    _tab11_intensity_settings_changed(self)


def _tab11_fix_all_centers(self):
    if _ii2d_enabled(self,11):return _ii2d_run(self,11)
    if not getattr(self, '_tab11_primary_ready', False):
        if not _tab11_fetch_primary(self, preserve_frame=True):
            return
    if not getattr(self, '_tab11_rois', []):
        messagebox.showwarning('Tab 11', 'Add at least one ROI first.', parent=self.root)
        return

    frame=int(self.tab11_frame_var.get())
    centers={}
    for ridx in range(len(self._tab11_rois)):
        crop,_=_tab11_roi_crop(self,ridx,frame)
        if crop is not None:
            centers[ridx]=_tab11_center(self,crop)

    if not self._tab11_ii_busy:
        _tab11_clear_intensity(self)
    self._tab11_centers=centers
    self._tab11_dynamic_centers=dict(centers)
    self._tab11_center_fixed=True
    self._tab11_auto_frame_fit=True

    self.tab11_status_var.set(
        f'✓ Fixed centers for all {len(centers)} selected ROIs at frame {frame+1}. '
        'Frame Slider AUTO: detect core + calculate FWHM + intensity.')
    _tab11_auto_analyze_current_frame(self,frame,draw=True)
def _tab11_ref_changed(self, event=None):
    _tab11_clear_current_fit_views(self)
    if getattr(self, '_tab11_primary_ready', False):
        self._tab11_render( int(self.tab11_frame_var.get()))


def _tab11_roi_selection_changed(self, event=None):
    _tab11_clear_current_fit_views(self)
    try:
        self.tab11_auto_center_btn.configure(
            state='normal' if getattr(self, '_tab11_rois', []) else 'disabled'
        )
    except Exception:
        pass
    if getattr(self, '_tab11_primary_ready', False):
        self._tab11_render( int(self.tab11_frame_var.get()))


def _tab11_frame_changed(self, value=None):
    if _ii2d_enabled(self,11):return _ii2d_frame_changed(self,11,value)
    if getattr(self, '_tab11_programmatic', False):
        return
    if not getattr(self, '_tab11_primary_ready', False):
        if not _tab11_fetch_primary(self, preserve_frame=True):
            return

    try:
        idx=int(round(float(value))) if value is not None else int(self.tab11_frame_var.get())
    except Exception:
        idx=int(self.tab11_frame_var.get())

    idx=max(0,min(idx,len(self._tab11_primary_stack)-1))
    self._tab11_programmatic=True
    try:
        self.tab11_frame_var.set(idx)
        self.tab11_slider.set(idx)
    finally:
        self._tab11_programmatic=False

    # Once FIX CENTERS — ALL ROIs has been clicked, the slider is the
    # trigger for automatic per-frame core detection + FWHM/intensity fit.
    if (getattr(self,'_tab11_auto_frame_fit',False) and
        getattr(self,'_tab11_center_fixed',False) and
        getattr(self,'_tab11_rois',[])):
        try:
            _tab11_auto_analyze_current_frame(self,idx,draw=True)
            return
        except Exception as exc:
            self.tab11_status_var.set(
                f'Automatic frame analysis failed: {type(exc).__name__}: {exc}')

    # Existing behavior before FIX CENTERS — ALL ROIs.
    _tab11_clear_current_fit_views(self)
    self._tab11_render(idx)

def _tab11_clear_figure5(self):
    """Clear ONLY Figure 5 curves/data and its ALL-ROI tracking dataframe.

    Important: do not use _tab11_clear_twin_axes() here because that helper
    also removes the twin axes belonging to Figure 3 (current ROI) and
    Figure 4 (fit residual/current tracking).  Figure 5 has its own twin
    axes, so remove only those Figure-5-specific axes.
    """
    # Remove ONLY Figure-5 twin axes:
    #   _tab11_all_amp_ax   -> Gaussian amplitude axis for Figure 5
    #   _tab11_all_frame_ax -> frame-number axis for Figure 5
    for attr in ('_tab11_all_amp_ax', '_tab11_all_frame_ax'):
        ax5 = getattr(self, attr, None)
        if ax5 is not None:
            try:
                ax5.remove()
            except Exception:
                pass
            setattr(self, attr, None)

    ax = getattr(self, 'tab11_ax_all_tracking', None)
    if ax is not None:
        try:
            ax.clear()
            ax.set_title('ALL SELECTED ROIs', pad=10)
            ax.set_xlabel('Equivalent field (mT)')
            ax.set_ylabel('Gaussian FWHM (nm)')
            ax.grid(alpha=0.2)
        except Exception:
            pass

    # Clear only Figure-5 tracking data. Do not touch ROI/current-fit state.
    self._tab11_tracking_df = pd.DataFrame()

    try:
        self.tab11_fit_status_var.set(
            '✓ Figure 5 cleared. ROI definitions, fixed centers and current-frame analysis preserved.'
        )
    except Exception:
        pass
    try:
        self.tab11_status_var.set('✓ Figure 5 cleared.')
    except Exception:
        pass
    try:
        self.tab11_canvas.draw_idle()
    except Exception:
        pass
    _tab11_sync_intensity(self)
    _tab11_plot_intensity(self)


def _tab11_detect_particle_for_tracking(self, crop, roi_idx):
    """
    Particle-presence detector used ONLY by TRACK ALL ROIs-SELECTED FRAMES.

    The detector is deliberately independent of _tab11_center() and
    _tab11_fit_roi().  It uses the fixed ROI center as a search reference,
    removes slow background variation, searches several particle-size
    scales, and requires a localized, high-SNR core with measurable
    center-vs-annulus contrast.  A noise maximum therefore does not get
    passed to the Gaussian fitter.

    Returns
    -------
    detected : bool
    center : dict or None
        Detection center in ROI-local pixels, plus diagnostic quantities.
    """
    try:
        a = np.asarray(crop, dtype=float)
        if a.ndim != 2 or a.size < 49:
            return False, None

        finite = np.isfinite(a)
        if not np.any(finite):
            return False, None

        med_all = float(np.nanmedian(a[finite]))
        if not np.isfinite(med_all):
            return False, None
        a = np.where(finite, a, med_all)

        h, w = a.shape
        if min(h, w) < 9:
            return False, None

        # Fixed center established by FIX CENTERS — ALL ROIs.
        fixed = getattr(self, '_tab11_centers', {}).get(int(roi_idx), None)
        if not isinstance(fixed, dict):
            return False, None

        fx = float(fixed.get('x0', np.nan))
        fy = float(fixed.get('y0', np.nan))
        if not (np.isfinite(fx) and np.isfinite(fy)):
            return False, None

        # The particle may move within the selected ROI, but do not allow a
        # distant noise feature to become the tracked particle.
        search_radius = max(5.0, 0.22 * min(h, w))

        # Edge/corner particles must not inflate the target's noise estimate.
        edge = max(1, int(.15*min(h,w)))
        interior = np.zeros_like(finite)
        interior[edge:h-edge,edge:w-edge] = True
        finite &= interior
        fill = float(np.median(a[finite])) if finite.any() else float(np.median(a))
        a = np.where(finite, a, fill)

        # Remove illumination/background gradients.  This is only for
        # detection; the original image is still sent to the existing fitter.
        bg_sigma = max(3.0, 0.18 * min(h, w))
        bg = gaussian_filter(a, sigma=bg_sigma, mode='nearest')
        residual = a - bg

        # Robust global noise estimate from the residual.
        b = max(2, int(round(0.10 * min(h, w))))
        border = np.concatenate([
            residual[:b, :].ravel(), residual[-b:, :].ravel(),
            residual[:, :b].ravel(), residual[:, -b:].ravel()
        ])
        border = border[np.isfinite(border)]
        if border.size < 20:
            border = residual.ravel()

        noise = 1.4826 * float(np.median(
            np.abs(border - np.median(border))
        ))
        if not np.isfinite(noise) or noise <= 0:
            noise = float(np.std(border))
        if not np.isfinite(noise) or noise <= 0:
            noise = max(float(np.finfo(float).eps), np.std(residual) * 0.1)

        # Multi-scale matched-filter-like search.  The Gaussian filtering
        # suppresses isolated pixel noise while retaining particle-sized cores.
        scales = (
            max(1.5, 0.025 * min(h, w)),
            max(2.0, 0.035 * min(h, w)),
            max(2.5, 0.050 * min(h, w)),
            max(3.0, 0.070 * min(h, w)),
            max(4.0, 0.095 * min(h, w)),
            max(5.0, 0.125 * min(h, w)),
        )

        yy, xx = np.indices((h, w), dtype=float)
        search = (xx - fx) ** 2 + (yy - fy) ** 2 <= search_radius ** 2

        best = None
        for sig in scales:
            smooth = gaussian_filter(residual, sigma=sig, mode='nearest')

            # Estimate the noise in this smoothed response from the border.
            rb = np.concatenate([
                smooth[:b, :].ravel(), smooth[-b:, :].ravel(),
                smooth[:, :b].ravel(), smooth[:, -b:].ravel()
            ])
            rb = rb[np.isfinite(rb)]
            rmad = 1.4826 * float(np.median(
                np.abs(rb - np.median(rb))
            ))
            if not np.isfinite(rmad) or rmad <= 0:
                rmad = float(np.std(rb))
            if not np.isfinite(rmad) or rmad <= 0:
                rmad = noise / max(1.0, np.sqrt(2.0 * np.pi) * sig)

            # Evaluate both contrast polarities.
            for polarity in (1.0, -1.0):
                response = polarity * smooth
                candidate = np.where(search, response, -np.inf)
                flat = int(np.argmax(candidate))
                cy, cx = np.unravel_index(flat, candidate.shape)
                peak = float(response[cy, cx])

                if not np.isfinite(peak):
                    continue

                candidate_noise = _core_response_noise(a, smooth, finite, cx, cy, sig, rmad)
                snr = peak / max(candidate_noise, np.finfo(float).eps)

                # First gate: a particle must be clearly above filtered noise.
                if snr < 4.5:
                    continue

                # Local prominence against an annulus around the candidate.
                rr = max(3.0, 2.2 * sig)
                inner_r = max(1.5, 0.65 * sig)
                outer_r = max(inner_r + 1.0, 1.75 * sig)

                dy = yy - cy
                dx = xx - cx
                dist = np.sqrt(dx * dx + dy * dy)

                inner = response[dist <= inner_r]
                annulus = response[
                    (dist >= inner_r) & (dist <= outer_r)
                ]

                if inner.size < 3 or annulus.size < 8:
                    continue

                raw_ring = a[(dist >= outer_r) & (dist <= max(outer_r + 1.0, 3.0 * sig))]
                if raw_ring.size < 8:
                    continue
                raw_core = polarity * (a[dist <= inner_r] - np.median(raw_ring))
                if np.count_nonzero(raw_core > max(0.25 * peak, candidate_noise)) < 3:
                    continue
                center_level = float(np.median(inner))
                annulus_level = float(np.median(annulus))
                prominence = center_level - annulus_level

                # Both absolute and relative prominence gates are required.
                if prominence < max(2.5 * candidate_noise, 0.12 * peak):
                    continue

                # The candidate must be away from the ROI edge.
                margin = max(2.0, 1.5 * sig)
                if (
                    cx < margin or cx > w - 1 - margin or
                    cy < margin or cy > h - 1 - margin
                ):
                    continue

                # Compactness / localization test using the existing 0.60
                # contrast threshold.  This prevents a broad gradient from
                # being accepted just because it has a maximum.
                frac = 0.60
                try:
                    frac = float(np.clip(
                        self.tab11_contrast_fraction_var.get(), 0.0, 0.95
                    ))
                except Exception:
                    pass

                local_patch = response[
                    max(0, int(cy - outer_r)):min(h, int(cy + outer_r) + 1),
                    max(0, int(cx - outer_r)):min(w, int(cx + outer_r) + 1)
                ]
                if local_patch.size == 0:
                    continue

                threshold = frac * peak
                core_mask = local_patch >= threshold
                area = int(np.count_nonzero(core_mask))

                expected_area = np.pi * max(sig, 1.0) ** 2
                if area < max(2, int(0.18 * expected_area)):
                    continue
                if area > max(12, int(7.0 * expected_area)):
                    continue

                # Require the central region itself to carry signal.
                if center_level < max(2.5 * candidate_noise, 0.08 * peak):
                    continue

                score = snr + 0.5 * (prominence / max(candidate_noise, 1e-12))
                if best is None or score > best['score']:
                    best = {
                        'x0': float(cx),
                        'y0': float(cy),
                        'background': float(np.nanmedian(bg)),
                        'sign': float(polarity),
                        'peak': float(peak),
                        'threshold': float(frac * peak),
                        'snr': float(snr),
                        'prominence': float(prominence),
                        'scale': float(sig),
                        'score': float(score),
                    }

        if best is None:
            return False, None

        # Final fixed-center proximity gate. This is intentionally applied
        # after the multi-scale search so real shifted particles can still be
        # found, while unrelated structures/noise cannot hijack tracking.
        if np.hypot(best['x0'] - fx, best['y0'] - fy) > search_radius:
            return False, None

        return True, best

    except Exception:
        return False, None


def _tab11_track_all(self):
    if _ii2d_enabled(self,11):return _ii2d_run(self,11,tracking=True)
    if self._tab11_ii_busy:
        return
    job = self._tab11_ii_recalculate_job
    if job:
        self.root.after_cancel(job)
    self._tab11_ii_recalculate_job = None
    self._tab11_ii_scope = 'tracking'
    self._tab11_ii_busy = True
    if self._tab11_ii_dirty:
        self._tab11_intensity_profiles = {}
        self._tab11_tracking_df = None
        self._tab11_current_tracking_df = None
    self._tab11_ii_dirty = False
    run_source = self._tab11_primary_stack
    run_rois = [dict(r) for r in self._tab11_rois]
    self._tab11_intensity_profiles = {}
    self._tab11_ii_current_result = None
    try:
        # Reset the cooperative stop flag for this explicit tracking run.
        self._tab11_stop_requested = False

        if not getattr(self, '_tab11_primary_ready', False):
            if not _tab11_fetch_primary(self, preserve_frame=True):
                return
        rois = getattr(self, '_tab11_rois', [])
        if not rois:
            messagebox.showwarning('Tab 11', 'Add at least one ROI first.', parent=self.root)
            return

        start = max(0, min(int(self.tab11_start_var.get()), len(self._tab11_primary_stack) - 1))
        end = max(0, min(int(self.tab11_end_var.get()), len(self._tab11_primary_stack) - 1))
        if start > end:
            start, end = end, start

        if not getattr(self, '_tab11_center_fixed', False):
            _tab11_fix_all_centers(self)

        rows = []
        # IMPORTANT: FIT CURRENT ROI Fig.3/Fig.4 are intentionally untouched here.
        # Only the third-row ALL-SELECTED-ROIs tracking panel is refreshed.
        self._tab11_tracking_df = pd.DataFrame()
        self.tab11_fig.subplots_adjust(
            left=0.065, right=0.90, bottom=0.06, top=0.95,
            wspace=0.30, hspace=0.52
        )
        self.tab11_canvas.draw_idle()
        self.root.update_idletasks()

        total = (end - start + 1) * len(rois)
        done = 0
        _analysis_progress_update(self, 11, 0, total)
        detected_count = 0
        stopped = False

        self.tab11_fit_status_var.set(
            f'⏳ Tracking {len(rois)} ROIs | frames {start + 1}–{end + 1} | 0/{total}'
        )
        self.root.update_idletasks()

        run_source = self._tab11_primary_stack
        run_rois = [dict(r) for r in self._tab11_rois]
        for frame in range(start, end + 1):
            if run_source is not self._tab11_primary_stack or run_rois != self._tab11_rois:
                return
            if getattr(self, '_tab11_stop_requested', False):
                stopped = True
                break
            for ridx in range(len(rois)):
                if getattr(self, '_tab11_stop_requested', False):
                    stopped = True
                    break
                zero_mode = bool(self.tab11_zero_if_undetected_var.get())
                try:
                    crop, bounds = _tab11_roi_crop(self, ridx, frame)

                    # Per-ROI, per-frame particle-presence test.
                    # The existing _tab11_center() and _tab11_fit_roi() are not
                    # modified and are used only after a real core is detected.
                    zero_mode = bool(
                        getattr(self, 'tab11_zero_if_undetected_var', None) is not None
                        and self.tab11_zero_if_undetected_var.get()
                    )

                    if zero_mode:
                        detected, det = _tab11_detect_particle_for_tracking(
                            self, crop, ridx
                        )
                    else:
                        # Existing TAB 11 fitting/tracking path is retained.
                        detected, det = True, None

                    if not detected:
                        r = _tab11_zero_tracking_result(self,ridx,frame,crop,bounds)
                        rows.append(_tab10_numeric_result(r))
                    else:
                        r = _tab11_fit_roi(self, ridx, frame, store=False)
                        if r is None:
                            raise RuntimeError('Particle detected but fitting returned no result.')

                        r.update(core_detected=True if zero_mode else None,
                            detection_status='detected' if zero_mode else 'not checked',
                            detection_reason='Core passes tracking detection tests' if zero_mode else 'Zero if Undetected disabled')
                        _tab11_cache_intensity(self,r)
                        rows.append({
                            'roi_index': r['roi_index'],
                            'frame': r['frame'],
                            'field_mT': r['field_mT'],
                            'fwhm': r['fwhm'],
                            'fwhm_err': r['fwhm_err'],
                            'diameter_nm': r.get('diameter_nm', np.nan),
                            'diameter_err_nm': r.get('diameter_err_nm', np.nan),
                            'core_intensity': r.get('core_intensity', np.nan),
                            'amplitude': r['amplitude'],
                            'amplitude_err': r['amplitude_err'],
                            'sigma': r['sigma'],
                            'sigma_err': r['sigma_err'],
                            'r2': r['r2'],
                            'rmse': r['rmse'],
                            'line_rmse': r['line_rmse'],
                            'line_cv': r['line_cv'],
                            'core_detected': True,
                        })
                        detected_count += 1

                except Exception as exc:
                    rows.append({
                        'roi_index': ridx + 1,
                        'frame': frame,
                        'field_mT': _tab11_field_mT(self, frame),
                        'fwhm': np.nan,
                        'fwhm_err': np.nan,
                        'diameter_nm': np.nan,
                        'diameter_err_nm': np.nan,
                        'core_intensity': np.nan,
                        'amplitude': np.nan,
                        'amplitude_err': np.nan,
                        'sigma': np.nan,
                        'sigma_err': np.nan,
                        'r2': np.nan,
                        'rmse': np.nan,
                        'line_rmse': np.nan,
                        'line_cv': np.nan,
                        'core_detected': None,
                        'detection_status': 'error',
                        'detection_reason': str(exc),
                        'error': f'{type(exc).__name__}: {exc}',
                    })

                done += 1
                _analysis_progress_update(self, 11, done, total)

                # Keep the existing live TRACK ALL progress display.
                self._tab11_tracking_df = pd.DataFrame(rows)
                _tab11_plot_tracking_panel(
                    self, self._tab11_tracking_df,
                    self.tab11_ax_all_tracking, mode='all',
                    title='ALL SELECTED ROIs',
                    draw=False
                )
                self.tab11_fig.subplots_adjust(
                    left=0.065, right=0.90, bottom=0.06, top=0.95,
                    wspace=0.30, hspace=0.52
                )
                self.tab11_canvas.draw_idle()
                self.root.update_idletasks()

                self.tab11_fit_status_var.set(
                    f'⏳ Tracking {len(rois)} ROIs | '
                    f'frame {frame + 1}/{len(self._tab11_primary_stack)} | '
                    f'{done}/{total} | cores detected: {detected_count}'
                )

                try:
                    # Process button events so STOP FIT can be clicked during tracking.
                    self.root.update()
                except Exception:
                    self.root.update_idletasks()

                if run_source is not self._tab11_primary_stack or run_rois != self._tab11_rois:
                    return
                if getattr(self, '_tab11_stop_requested', False):
                    stopped = True
                    break

        self._tab11_tracking_df = pd.DataFrame(rows)

        _tab11_plot_tracking_panel(
            self, self._tab11_tracking_df,
            self.tab11_ax_all_tracking, mode='all',
            title='ALL SELECTED ROIs',
            draw=False
        )
        self.tab11_fig.subplots_adjust(
            left=0.065, right=0.90, bottom=0.06, top=0.95,
            wspace=0.30, hspace=0.52
        )
        self.tab11_canvas.draw_idle()

        if stopped or getattr(self, '_tab11_stop_requested', False):
            self.tab11_fit_status_var.set(
                f'⏹ Tracking stopped | {len(rois)} ROIs | '
                f'frames {start + 1}–{end + 1} | {len(rows)} completed measurements | '
                f'{detected_count} particle cores detected'
            )
        else:
            self.tab11_fit_status_var.set(
                f'✓ Tracking complete | {len(rois)} ROIs | '
                f'frames {start + 1}–{end + 1} | {len(rows)} measurements | '
                f'{detected_count} particle cores detected'
            )

        self._tab11_stop_requested = False
    finally:
        self._tab11_ii_busy = False
        if run_source is self._tab11_primary_stack and run_rois == self._tab11_rois:
            if self.tab11_integrated_intensity_var.get() and not self._tab11_ii_dirty:
                last = getattr(self, '_tab11_last_fit', None)
                if isinstance(last, dict) and self._tab11_ii_current_result is None and self._tab11_intensity_profiles:
                    try:
                        _tab11_fit_roi(self, int(last['roi_index']) - 1, int(last['frame']), store=False)
                    except Exception as exc:
                        self._tab11_last_fit = None
                        self.log(f'Tab 11 displayed-profile refit unavailable: {exc}')
                if self._tab11_ii_current_result is not None:
                    self._tab11_last_fit = self._tab11_ii_current_result
                    _tab11_draw_current_fit_views(self, self._tab11_last_fit)
            self._tab11_ii_current_result = None
            _tab11_sync_intensity(self)
            _tab11_plot_intensity(self)


@_auto_open_export
def _tab11_export_current_csv(self):
    """Export only the currently selected ROI profile/average/Gaussian fit."""
    if _ii2d_enabled(self,11):return _ii2d_export_tables(self,11,current=True)
    result = getattr(self, '_tab11_last_fit', None)
    if not isinstance(result, dict):
        messagebox.showwarning(
            'Tab 11 Export',
            'Run FIT CURRENT ROI first.',
            parent=self.root
        )
        return

    try:
        roi_id = int(result['roi_index'])
        frame_id = int(result['frame']) + 1
        field = result.get('field_mT', np.nan)
        field_txt = f'{field:+.2f}mT' if np.isfinite(field) else 'FieldNA'

        path = filedialog.asksaveasfilename(
            parent=self.root,
            title='Export Current Selected ROI',
            defaultextension='.csv',
            filetypes=[('CSV', '*.csv'), ('All files', '*.*')],
            initialfile=(
                f'Tab11_ROI{roi_id}_Current_Frame{frame_id:03d}_'
                f'LineProfile_Avg_Gaussian.csv'
            )
        )
        if not path:
            return

        data = {
            'ROI': np.full(len(result['t_nm']), roi_id, dtype=int),
            'Frame': np.full(len(result['t_nm']), frame_id, dtype=int),
            'Field_mT': np.full(len(result['t_nm']), field, dtype=float),
            'Position_nm': np.asarray(result['t_nm'], dtype=float),
        }

        for angle in result['angles']:
            data[f'Profile_{float(angle):g}deg'] = np.asarray(
                result['profiles'][float(angle)], dtype=float
            )

        data['Average_Profile'] = np.asarray(
            result['average_profile'], dtype=float
        )
        data['Gaussian_Fit'] = np.asarray(
            result['fit_profile'], dtype=float
        )

        _tab11_update_integrated_result(self, result)
        _export_capture_write(pd.DataFrame(data).to_csv, path, index=False)
        numeric = pd.DataFrame([{k:v for k,v in result.items() if np.isscalar(v)}])
        _export_capture_write(_ii_export_table(numeric, self.tab11_integrated_intensity_var.get()).to_csv, Path(path).with_name(Path(path).stem + '_Figure6.csv'), index=False)

        self.tab11_export_status_var.set(
            f'✓ Exported current ROI {roi_id}: {Path(path).name}'
        )

    except Exception as exc:
        self.tab11_export_status_var.set(
            f'✗ Current ROI export failed: {type(exc).__name__}: {exc}'
        )
        _export_error_dialog(messagebox.showerror, 'Tab 11 Export — Current ROI', f'{type(exc).__name__}: {exc}', parent=self.root)



@_auto_open_export
def _tab11_export_tracking_csv(self):
    """Export both Gaussian and D-Fit data represented by Figure 5."""
    if _ii2d_enabled(self,11):return _ii2d_export_tables(self,11)
    df=getattr(self,'_tab11_tracking_df',None)
    if df is None or not isinstance(df,pd.DataFrame) or df.empty:
        messagebox.showwarning('Tab 11 Export','Figure 5 has no tracking data. Run FIT AND TRACK ALL SELECTED ROIs first.',parent=self.root); return
    try:
        path=filedialog.asksaveasfilename(parent=self.root,title='Export Data — Figure 5',defaultextension='.csv',filetypes=[('CSV','*.csv'),('All files','*.*')],initialfile='Tab11_Figure5_Gaussian_and_DFit_Data.csv')
        if not path:return
        _tab11_sync_intensity(self)
        outdf=df.copy()
        if 'frame' in outdf: outdf['Frame']=pd.to_numeric(outdf['frame'],errors='coerce')+1
        if 'field_mT' in outdf: outdf['Equivalent_Field_mT']=pd.to_numeric(outdf['field_mT'],errors='coerce')
        ren={'fwhm':'Gaussian_FWHM_nm','fwhm_err':'Gaussian_FWHM_SD_nm','amplitude':'Gaussian_Amplitude_au','amplitude_err':'Gaussian_Amplitude_SD_au','diameter_nm':'D_Fit_Diameter_nm','diameter_err_nm':'D_Fit_Diameter_SD_nm','core_intensity':'Core_Intensity_au','dfit_sg_level':'D_Fit_SG_Level'}
        outdf=outdf.rename(columns=ren)
        preferred=['roi_index','Frame','Equivalent_Field_mT','Gaussian_FWHM_nm','Gaussian_FWHM_SD_nm','Gaussian_Amplitude_au','Gaussian_Amplitude_SD_au','D_Fit_Diameter_nm','D_Fit_Diameter_SD_nm','Core_Intensity_au','D_Fit_SG_Level']
        cols=[c for c in preferred if c in outdf.columns]
        table = outdf[cols if cols else outdf.columns].copy()
        _ii_add_export_columns(table, df, self.tab11_integrated_intensity_var.get())
        _export_capture_write(table.to_csv, path, index=False)
        _tab11_export_intensity_csv(self, Path(path).with_name(Path(path).stem + '_Figure6.csv'))
        self.tab11_export_status_var.set(f'✓ Exported Figure 5 Gaussian + D-Fit data: {Path(path).name}')
    except Exception as exc:
        self.tab11_export_status_var.set(f'✗ Figure 5 export failed: {type(exc).__name__}: {exc}')
        _export_error_dialog(messagebox.showerror, 'Tab 11 Export — Figure 5', f'{type(exc).__name__}: {exc}', parent=self.root)


@_auto_open_export
def _tab11_export_figures(self):
    """Export each Tab-11 figure panel separately as 300-PPI PNG."""
    if _ii2d_enabled(self,11):return _ii2d_export_figures(self,11)
    if getattr(self, 'tab11_fig', None) is None:
        return

    folder = _export_capture_folder(filedialog.askdirectory, parent=self.root, title='Select folder for Tab 11 figure export')
    if not folder:
        return

    try:
        self.tab11_canvas.draw()
        fig = self.tab11_fig
        renderer = fig.canvas.get_renderer()

        frame0 = int(self.tab11_frame_var.get())
        field = _tab11_field_mT(self, frame0)
        field_txt = f'{field:+.2f}mT' if np.isfinite(field) else 'FieldNA'

        panels = [
            ('Figure1_ProcessedPrimaryROI1_MultiROI',
             [getattr(self, 'tab11_ax_primary', None),
              getattr(getattr(self, '_tab11_cbar', None), 'ax', None)]),
            ('Figure2_SelectedROI_ReferenceLines',
             [getattr(self, 'tab11_ax_selected', None)]),
            ('Figure3_CurrentROI_AvgProfile_Gaussian_Residual',
             [getattr(self, 'tab11_ax_fit', None),
              getattr(self, '_tab11_fit_residual_ax', None)]),
            ('Figure4_CurrentROI_Diameter_CoreIntensity' if bool(getattr(self,'tab11_dfit_var',None) is not None and self.tab11_dfit_var.get()) else 'Figure4_CurrentROI_FWHM_Amplitude',
             [getattr(self, 'tab11_ax_current_tracking', None),
              getattr(self, '_tab11_current_amp_ax', None),
              getattr(self, '_tab11_current_frame_ax', None)]),
            ('Figure5_AllSelectedROIs_AvgDiameter_CoreIntensity' if bool(getattr(self,'tab11_dfit_var',None) is not None and self.tab11_dfit_var.get()) else 'Figure5_AllSelectedROIs_AvgFWHM_Amplitude',
             [getattr(self, 'tab11_ax_all_tracking', None),
              getattr(self, '_tab11_all_amp_ax', None),
              getattr(self, '_tab11_all_frame_ax', None)]),
        ]

        written=[]
        for stem, axes in panels:
            axes=[a for a in axes if a is not None and a in fig.axes]
            if not axes:
                continue

            # Matplotlib Bbox objects are not sequences; never use len(bbox).
            boxes=[]
            for ax in axes:
                try:
                    b=ax.get_tightbbox(renderer)
                    if b is not None and np.isfinite(
                        [b.x0,b.y0,b.x1,b.y1]
                    ).all():
                        boxes.append(b)
                except Exception:
                    pass

            if boxes:
                # Union the Bboxes explicitly.
                x0=min(b.x0 for b in boxes)
                y0=min(b.y0 for b in boxes)
                x1=max(b.x1 for b in boxes)
                y1=max(b.y1 for b in boxes)
                from matplotlib.transforms import Bbox
                box=Bbox.from_extents(x0,y0,x1,y1)
                bbox=box.transformed(
                    fig.dpi_scale_trans.inverted()
                ).expanded(1.06,1.10)
            else:
                bbox='tight'

            filename=(
                f'Tab11_{stem}_Frame{frame0+1:03d}_{field_txt}.png'
            )
            path=os.path.join(folder,filename)

            _export_capture_write(fig.savefig, path, dpi=300, bbox_inches=bbox, facecolor='white', edgecolor='white', format='png')
            written.append(path)

        _tab11_sync_intensity(self)
        _tab11_plot_intensity(self)
        self.tab11_ii_canvas.draw()
        path = os.path.join(folder, f'Tab11_Figure6_Diameter_IntegratedIntensity_Frame{frame0+1:03d}_{field_txt}.png')
        _export_capture_write(self.tab11_ii_fig.savefig, path, dpi=300, bbox_inches='tight', pad_inches=0.15, facecolor='white')
        written.append(path)
        self.tab11_export_status_var.set(
            f'✓ Exported {len(written)} separate Tab 11 figures at 300 PPI.'
        )
        messagebox.showinfo(
            'Tab 11 Export Figures',
            f'Exported {len(written)} separate PNG figures at 300 PPI to:\n{folder}',
            parent=self.root
        )

    except Exception as exc:
        self.tab11_export_status_var.set(
            f'✗ Figure export failed: {type(exc).__name__}: {exc}'
        )
        _export_error_dialog(messagebox.showerror, 'Tab 11 Export Figures', f'{type(exc).__name__}: {exc}', parent=self.root)



@_auto_open_export
def _tab11_export_selected_roi_data(self):
    """Export all stored data points currently represented by Figure 4."""
    if _ii2d_enabled(self,11):return _ii2d_export_tables(self,11,current=True)
    df = getattr(self, '_tab11_current_tracking_df', None)
    if df is None or not isinstance(df, pd.DataFrame) or df.empty:
        messagebox.showwarning(
            'Tab 11 Export',
            'Figure 4 has no current-ROI tracking data. Run FIT CURRENT ROI first.',
            parent=self.root
        )
        return

    try:
        roi_id = _tab11_selected_roi_index(self) + 1
        path = filedialog.asksaveasfilename(
            parent=self.root,
            title='Export Selected ROI Data — Figure 4',
            defaultextension='.csv',
            filetypes=[('CSV', '*.csv'), ('All files', '*.*')],
            initialfile=f'Tab11_Selected_ROI{roi_id}_Figure4_{"DFit" if bool(getattr(self,"tab11_dfit_var",None) is not None and self.tab11_dfit_var.get()) else "Gaussian"}_Data.csv'
        )
        if not path:
            return

        export_df = df.copy()
        if 'frame' in export_df.columns:
            export_df['Frame'] = pd.to_numeric(
                export_df['frame'], errors='coerce'
            ) + 1
        if 'field_mT' in export_df.columns:
            export_df['Equivalent_Field_mT'] = pd.to_numeric(
                export_df['field_mT'], errors='coerce'
            )
        if 'fwhm' in export_df.columns:
            export_df['FWHM_nm'] = pd.to_numeric(
                export_df['fwhm'], errors='coerce'
            )
        if 'fwhm_err' in export_df.columns:
            export_df['FWHM_Error_nm'] = pd.to_numeric(
                export_df['fwhm_err'], errors='coerce'
            )
        if 'amplitude' in export_df.columns:
            export_df['Gaussian_Amplitude'] = pd.to_numeric(
                export_df['amplitude'], errors='coerce'
            )
        if 'amplitude_err' in export_df.columns:
            export_df['Amplitude_Error'] = pd.to_numeric(
                export_df['amplitude_err'], errors='coerce'
            )
        if 'diameter_nm' in export_df.columns:
            export_df['D_Fit_Avg_Diameter_nm'] = pd.to_numeric(export_df['diameter_nm'], errors='coerce')
        if 'diameter_err_nm' in export_df.columns:
            export_df['D_Fit_Diameter_SD_nm'] = pd.to_numeric(export_df['diameter_err_nm'], errors='coerce')
        if 'dfit_sg_level' in export_df.columns:
            export_df['D_Fit_Threshold'] = pd.to_numeric(export_df['dfit_sg_level'], errors='coerce')
        if 'core_intensity' in export_df.columns:
            export_df['Core_Intensity'] = pd.to_numeric(export_df['core_intensity'], errors='coerce')

        # Keep the exported version compact and meaningful.
        preferred = [
            'roi_index', 'Frame', 'Equivalent_Field_mT',
            'FWHM_nm', 'FWHM_Error_nm',
            'D_Fit_Avg_Diameter_nm', 'D_Fit_Diameter_SD_nm', 'D_Fit_Threshold', 'Core_Intensity',
            'Gaussian_Amplitude', 'Amplitude_Error'
        ]
        cols = [c for c in preferred if c in export_df.columns]
        _tab11_sync_intensity(self)
        table = export_df[cols if cols else export_df.columns].copy()
        _ii_add_export_columns(table, df, self.tab11_integrated_intensity_var.get())
        _export_capture_write(table.to_csv, path, index=False)
        _export_capture_write(_ii_export_table(df, self.tab11_integrated_intensity_var.get()).to_csv, Path(path).with_name(Path(path).stem + '_Figure6.csv'), index=False)

        self.tab11_export_status_var.set(
            f'✓ Exported Figure 4 data: {Path(path).name}'
        )

    except Exception as exc:
        self.tab11_export_status_var.set(
            f'✗ Selected ROI data export failed: {type(exc).__name__}: {exc}'
        )
        _export_error_dialog(messagebox.showerror, 'Tab 11 Export — Selected ROI Data', f'{type(exc).__name__}: {exc}', parent=self.root)

def _tab11_build(self):
    if not hasattr(self, 'tab_multi_roi11'):
        self.tab_multi_roi11 = ttk.Frame(self.nb)
        self.nb.add(self.tab_multi_roi11, text='11. Multi-ROI Fit')

    tab = self.tab_multi_roi11
    for child in list(tab.winfo_children()):
        try:
            child.destroy()
        except Exception:
            pass

    self.tab11_contrast_fraction_var = tk.DoubleVar(value=0.50)
    self.tab11_gaussian_var = tk.BooleanVar(value=True)
    self.tab11_dfit_var = tk.BooleanVar(value=False)
    self.tab11_dfit_sg_level_var = tk.IntVar(value=0)
    self.tab11_dfit_threshold_mode_var = tk.BooleanVar(value=False)
    self.tab11_dfit_threshold_var = tk.DoubleVar(value=0.50)
    # Optional fixed-size ROI selector (Tab 11 only). Empty/invalid values
    # deliberately fall back to the original free-draw ROI workflow.
    self.tab11_roi_width_nm_var = tk.StringVar(value='')
    self.tab11_roi_length_nm_var = tk.StringVar(value='')
    self._tab11_fixed_roi_mode = False
    self._tab11_fixed_roi_rect = None
    self._tab11_fixed_roi_dragging = False
    self._tab11_fixed_roi_drag_offset = None
    self._tab11_fixed_roi_dims_nm = None
    self.tab11_fig5_y1_var = tk.StringVar(value='Gaussian FWHM (nm)')
    self.tab11_fig5_y2_var = tk.StringVar(value='Gaussian Amplitude (a.u.)')
    self.tab11_ref_mode_var = tk.StringVar(value='2')
    self.tab11_frame_var = tk.IntVar(value=0)
    self.tab11_start_var = tk.IntVar(value=0)
    self.tab11_end_var = tk.IntVar(value=0)
    self.tab11_frame_label_var = tk.StringVar(value='Frame = 1')
    self.tab11_roi_select_var = tk.StringVar(value='')
    self.tab11_status_var = tk.StringVar(value='Click FETCH PRIMARY ROI FROM TAB 6 — uses current Filter / Brightness / Contrast / View / Color.')
    self.tab11_fit_status_var = tk.StringVar(value='No fit/tracking performed.')
    self.tab11_export_status_var = tk.StringVar(value='')
    self.tab11_zero_if_undetected_var = tk.BooleanVar(value=False)

    self._tab11_primary_ready = False
    self._tab11_primary_stack = None
    self._tab11_scale_nm = (1.0, 1.0)
    self._tab11_primary_extent = None
    self._tab11_cmap = str(getattr(self, 'colormap_var', tk.StringVar(value='gray')).get() or 'gray')
    self._tab11_view = str(getattr(self, 'view_var', tk.StringVar(value='Image')).get() or 'Image')
    self._tab11_clim = (0.0, 1.0)
    self._tab11_rois = []
    self._tab11_centers = {}
    self._tab11_center_fixed = False
    self._tab11_select_mode = False
    self._tab11_press_xy = None
    self._tab11_preview_rect = None
    self._tab11_pending_free_roi_coords = None
    self._tab11_fixed_roi_artist = None
    self._tab11_last_fit = None
    self._tab11_current_tracking_df = None
    self._tab11_tracking_df = None
    self._tab11_programmatic = False
    self._tab11_cbar = None
    self._tab11_fit_residual_ax = None
    self._tab11_current_amp_ax = None
    self._tab11_current_frame_ax = None
    self._tab11_all_amp_ax = None
    self._tab11_all_frame_ax = None
    self._tab11_stop_requested = False

    # ---------- Adjustable divider: plot area | scrollable controls ----------
    outer = ttk.Panedwindow(tab, orient='horizontal')
    outer.grid(row=0, column=0, sticky='nsew')
    tab.grid_rowconfigure(0, weight=1)
    tab.grid_columnconfigure(0, weight=1)

    # ---------- LEFT: scrollable figure panel ----------
    self.tab11_plot_views = ttk.Notebook(outer)
    plot_outer = ttk.Frame(self.tab11_plot_views)
    plot_outer.grid_rowconfigure(0, weight=1)
    plot_outer.grid_columnconfigure(0, weight=1)

    plot_scroll = tk.Canvas(
        plot_outer, highlightthickness=0, borderwidth=0
    )
    plot_vbar = ttk.Scrollbar(
        plot_outer, orient='vertical', command=plot_scroll.yview
    )
    plot_hbar = ttk.Scrollbar(
        plot_outer, orient='horizontal', command=plot_scroll.xview
    )
    plot_scroll.configure(
        yscrollcommand=plot_vbar.set,
        xscrollcommand=plot_hbar.set
    )
    plot_scroll.grid(row=0, column=0, sticky='nsew')
    plot_vbar.grid(row=0, column=1, sticky='ns')
    plot_hbar.grid(row=1, column=0, sticky='ew')

    plot_host = ttk.Frame(plot_scroll, width=1180, height=1080)
    plot_window = plot_scroll.create_window((0, 0), window=plot_host, anchor='nw')

    def _plot_sync(_event=None):
        plot_scroll.configure(scrollregion=plot_scroll.bbox('all'))
    plot_host.bind('<Configure>', _plot_sync)

    self.tab11_plot_views.add(plot_outer, text='Figures 1-5')
    intensity_page = ttk.Frame(self.tab11_plot_views)
    intensity_page.rowconfigure(0, weight=1)
    intensity_page.columnconfigure(0, weight=1)
    self.tab11_plot_views.add(intensity_page, text='Figure 6')
    outer.add(self.tab11_plot_views, weight=7)

    self.tab11_fig = plt.Figure(
        figsize=(15, 11), dpi=100, facecolor='white'
    )
    gs = self.tab11_fig.add_gridspec(
        3, 2,
        left=0.08, right=0.92,
        bottom=0.05, top=0.96,
        wspace=0.42, hspace=0.40,
        width_ratios=[1.0, 1.0],
        height_ratios=[1.50, 0.9, 0.9]
    )
    self.tab11_ax_primary = self.tab11_fig.add_subplot(gs[0, 0])
    self.tab11_ax_selected = self.tab11_fig.add_subplot(gs[0, 1])
    self.tab11_ax_fit = self.tab11_fig.add_subplot(gs[1, 0])
    self.tab11_ax_current_tracking = self.tab11_fig.add_subplot(gs[1, 1])
    self.tab11_ax_all_tracking = self.tab11_fig.add_subplot(gs[2, :])

    dummy = np.zeros((10, 10))
    for ax, title in (
        (self.tab11_ax_primary, 'PROCESSED PRIMARY ROI'),
        (self.tab11_ax_selected, 'SELECTED ROI — None')
    ):
        ax.imshow(
            dummy, cmap=self._tab11_cmap, origin='lower',
            extent=(0, 10, 0, 10), vmin=0, vmax=1,
            interpolation='nearest', aspect='equal'
        )
        ax.set_xlabel('X (nm)')
        ax.set_ylabel('Y (nm)')
        ax.set_title(title, pad=9)

    self.tab11_ax_fit.set_title(
        'FIT CURRENT ROI',
        pad=9
    )
    self.tab11_ax_fit.set_xlabel('Position from fixed center (nm)')
    self.tab11_ax_fit.set_ylabel('Intensity (a.u.)')
    self.tab11_ax_fit.grid(alpha=0.2)

    self.tab11_ax_current_tracking.set_title(
        'CURRENT ROI',
        pad=9
    )
