# ============================================================================
# FINAL PERFORMANCE PATCH — LAZY OPEN FOR TABS 8 AND 9
# Purpose:
#   * Do not process the complete Primary-ROI stack while the main window is
#     being constructed.
#   * Do not process/copy the stack repeatedly when returning to a tab.
#   * Reuse Tab 6's authoritative processed-stack cache.
#   * Preserve all existing Tab-8/Tab-9 analysis, export, ROI and hand-off
#     behavior once the tab is actually selected.
# ============================================================================

# -----------------------------
# TAB 8 — lazy UI construction
# -----------------------------
_TAB8_BUILD_FULL_BEFORE_FAST_OPEN = _tab8_v7_build

def _tab8_v7_build_fast_open(self):
    """
    Build Tab 8 widgets/layout only.
    Heavy source synchronization and plot refresh are deferred until Tab 8
    is selected by the user.
    """
    heavy_names = (
        '_tab8_v7_sync_source',
        '_tab8_v7_refresh_table',
        '_tab8_v7_plot',
        '_tab8_v7_particle_number_size_plot',
        '_tab8_v7_plot_dfit',
        '_tab8_v7_refresh_image',
    )
    saved = {}
    for name in heavy_names:
        saved[name] = globals().get(name)

    try:
        # These calls occur only at the end of the existing Tab-8 builder.
        # Returning no-op values lets the full widget tree be created without
        # touching the complete processed Primary-ROI stack.
        globals()['_tab8_v7_sync_source'] = lambda *a, **k: False
        globals()['_tab8_v7_refresh_table'] = lambda *a, **k: None
        globals()['_tab8_v7_plot'] = lambda *a, **k: None
        globals()['_tab8_v7_particle_number_size_plot'] = lambda *a, **k: None
        globals()['_tab8_v7_plot_dfit'] = lambda *a, **k: None
        globals()['_tab8_v7_refresh_image'] = lambda *a, **k: None
        result = _TAB8_BUILD_FULL_BEFORE_FAST_OPEN(self)
    finally:
        for name, fn in saved.items():
            if fn is not None:
                globals()[name] = fn

    self._tab8_lazy_built = True
    self._tab8_last_ready_signature = None

    # The tab is intentionally disabled until the user enters it.
    try:
        self._tab8_frame_slider.configure(
            from_=0, to=0, resolution=1, state='disabled'
        )
    except Exception:
        pass
    try:
        self.pd_status_var.set(
            'Tab 8 ready — select this tab to load the processed Primary ROI1.'
        )
    except Exception:
        pass
    return result

_tab8_v7_build = _tab8_v7_build_fast_open
CDIWorkflowApp._tab8_v7_build = _tab8_v7_build_fast_open


# -----------------------------
# TAB 8 — lazy source refresh
# -----------------------------
def _tab8_v7_ensure_ready_fast(self):
    """
    Load/refresh Tab 8 only when Tab 8 is the active notebook tab.
    Repeated tab entry reuses Tab 6's cached processed stack.
    """
    try:
        if not hasattr(self, 'nb') or not hasattr(self, 'tab_particle_density'):
            return False

        try:
            selected = self.nb.select()
        except Exception:
            selected = None

        if selected is not None and selected != str(self.tab_particle_density):
            # Important: the startup after_idle callback now becomes a no-op.
            return False

        st = _tab8_v7_get_primary_stack(self)
        if st is None:
            ok = bool(_tab8_v7_sync_source(self, preserve_current=True))
            if not ok:
                tries = int(getattr(self, '_tab8_source_retry_count', 0))
                if tries < 20:
                    self._tab8_source_retry_count = tries + 1
                    try:
                        self.root.after(300, lambda: _tab8_v7_ensure_ready_fast(self))
                    except Exception:
                        pass
                return False
            self._tab8_source_retry_count = 0
            st = _tab8_v7_get_primary_stack(self)
            if st is None:
                return False

        st = np.asarray(st)
        if st.ndim != 3 or st.shape[0] < 1:
            return False

        n = int(st.shape[0])
        idx = 0
        try:
            idx = int(self._tab8_frame_var.get())
        except Exception:
            pass
        idx = max(0, min(idx, n - 1))

        try:
            self._tab8_frame_slider.configure(
                from_=0, to=n - 1, resolution=1, state='normal'
            )
            self._tab8_frame_var.set(idx)
        except Exception:
            pass

        # Keep the selected-frame rendering exactly as before.
        _tab8_v7_refresh_image(self)
        return True
    except Exception as exc:
        try:
            self.pd_status_var.set(
                f'Tab 8 refresh failed: {type(exc).__name__}: {exc}'
            )
        except Exception:
            pass
        return False

_tab8_v7_ensure_ready = _tab8_v7_ensure_ready_fast
CDIWorkflowApp._tab8_ensure_ready_on_enter = _tab8_v7_ensure_ready_fast


# -----------------------------
# TAB 9 — lazy UI construction
# -----------------------------
_TAB9_BUILD_FULL_BEFORE_FAST_OPEN = _tab9_roi4_build

def _tab9_roi4_build_fast_open(self):
    """
    Build Tab 9 widgets/layout only.
    The complete processed Primary-ROI stack is fetched only when Tab 9 is
    actually selected.
    """
    old_fetch = globals().get('_tab9_roi4_fetch_from_tab6')
    old_refresh = globals().get('_tab9_roi4_refresh')

    try:
        # The existing builder performs one source fetch at the very end.
        # Suppress only that automatic startup fetch.
        globals()['_tab9_roi4_fetch_from_tab6'] = lambda *a, **k: False
        globals()['_tab9_roi4_refresh'] = lambda *a, **k: False
        result = _TAB9_BUILD_FULL_BEFORE_FAST_OPEN(self)
    finally:
        if old_fetch is not None:
            globals()['_tab9_roi4_fetch_from_tab6'] = old_fetch
        if old_refresh is not None:
            globals()['_tab9_roi4_refresh'] = old_refresh

    self._tab9_lazy_built = True
    self._tab9_last_source_signature = None

    try:
        self.tab9_roi4_slider.configure(
            from_=0, to=0, state='disabled'
        )
        self.tab9_roi4_play_button.configure(state='disabled')
        self.tab9_roi4_first_button.configure(state='disabled')
        self.tab9_roi4_status_var.set(
            'Tab 9 ready — select this tab to load the processed Primary ROI1.'
        )
    except Exception:
        pass

    return result

_tab9_roi4_build = _tab9_roi4_build_fast_open
CDIWorkflowApp._tab9_roi4_build = _tab9_roi4_build_fast_open


# -----------------------------
# TAB 9 — cached fetch path
# -----------------------------
_TAB9_CACHED_FETCH_SOURCE = _tab9_roi4_fetch_from_tab6

def _tab9_source_processed_for_cache(self):
    """
    Resolve Tab 6's exact processed stack once. The Tab-6 builder itself is
    cached by source + processing settings, so this is cheap on repeated entry.
    """
    builder = globals().get('_tab6_build_exact_processed_primary_stack')
    if not callable(builder):
        return None, None

    processed = builder(self)
    if processed is None:
        return None, None

    arr = np.asarray(processed)
    if arr.ndim != 3 or arr.shape[0] < 1:
        return None, None

    try:
        sx, sy = _tab6_effective_nm_per_output_px(self)
        sx, sy = float(sx), float(sy)
    except Exception:
        sx = sy = np.nan

    tab6_sig = getattr(self, '_tab6_exact_processed_primary_stack_signature', None)
    sig = (
        tab6_sig,
        id(processed),
        tuple(arr.shape),
        round(sx, 12) if np.isfinite(sx) else None,
        round(sy, 12) if np.isfinite(sy) else None,
    )
    return processed, sig


def _tab9_final_fetch_processed_roi_from_tab6_fast(self, preserve_frame=True):
    """
    Fast Tab-9 fetch:
      1) reuse Tab 6's cached exact processed stack;
      2) skip the full UI rewrite when the source/signature is unchanged;
      3) fall back to the existing authoritative Tab-9 fetch when the source
         has changed.
    """
    try:
        processed, sig = _tab9_source_processed_for_cache(self)
        if processed is not None:
            same = (
                bool(getattr(self, '_tab9_roi1_ready', False))
                and getattr(self, '_tab9_last_source_signature', None) == sig
                and getattr(self, '_tab9_roi1_stack_ref', None) is processed
            )
            if same:
                # Nothing changed in the source stack/settings. Keep the
                # current ROI4 selection, slider and plots exactly as they are.
                return True

        ok = bool(_TAB9_CACHED_FETCH_SOURCE(self, preserve_frame=preserve_frame))
        if ok:
            # _TAB9_CACHED_FETCH_SOURCE references the Tab-6 cached array;
            # therefore this signature is stable across repeated tab entries.
            try:
                _, sig2 = _tab9_source_processed_for_cache(self)
            except Exception:
                sig2 = sig
            self._tab9_last_source_signature = sig2
        return ok
    except Exception as exc:
        try:
            self.tab9_roi4_status_var.set(
                f'TAB 9 fetch failed: {type(exc).__name__}: {exc}'
            )
        except Exception:
            pass
        return False

# Replace only the final Tab-9 source-fetch entry point. Existing buttons and
# tab-entry callbacks resolve the global name at call time.
_tab9_final_fetch_processed_roi_from_tab6 = _tab9_final_fetch_processed_roi_from_tab6_fast
_tab9_roi4_fetch_from_tab6 = _tab9_final_fetch_processed_roi_from_tab6_fast
_tab9_roi4_refresh = lambda self, preserve_frame=True: _tab9_final_fetch_processed_roi_from_tab6_fast(
    self, preserve_frame=preserve_frame
)
CDIWorkflowApp._tab9_roi4_fetch_from_tab6 = _tab9_final_fetch_processed_roi_from_tab6_fast


