# ---------------------------------------------------------------------------
# FINALIZED ROTATION STACK HANDOFF FOR TABS 8-11
# ---------------------------------------------------------------------------
# Tab 8/9/10/11 consume Tab 6's exact processed Primary ROI stack.  When SET
# has finalized a rotation, replace that handoff stack with a once-rotated
# stack for ALL frames.  This keeps every downstream tab in one fixed rotated
# coordinate system and prevents frame changes from reverting to 0°.
try:
    _TAB6_V8_ORIGINAL_STACK_BUILDER = CDIWorkflowApp.__dict__.get('_tab6_build_exact_processed_primary_stack', None)
except Exception:
    _TAB6_V8_ORIGINAL_STACK_BUILDER = None
if _TAB6_V8_ORIGINAL_STACK_BUILDER is None:
    _TAB6_V8_ORIGINAL_STACK_BUILDER = globals().get('_tab6_build_exact_processed_primary_stack')


def _tab6_v8_build_exact_processed_primary_stack(self):
    if not callable(_TAB6_V8_ORIGINAL_STACK_BUILDER):
        return None
    base_processed = _TAB6_V8_ORIGINAL_STACK_BUILDER(self)
    if base_processed is None:
        return None
    base_processed = np.asarray(base_processed, dtype=_intensity_dtype(self))

    locked = bool(getattr(self, '_tab6_analysis_rotation_committed', False))
    angle = float(getattr(self, '_tab6_analysis_rotation_angle', 0.0)) if locked else 0.0
    version = int(getattr(self, '_tab6_analysis_rotation_version', 0)) if locked else 0
    sig = (
        id(base_processed), tuple(base_processed.shape),
        'FINALIZED_ROTATION', version, round(angle, 6),
    )
    old_sig = getattr(self, '_tab6_v8_finalized_stack_signature', None)
    old_stack = getattr(self, '_tab6_v8_finalized_primary_stack', None)
    if old_stack is not None and old_sig == sig:
        return old_stack

    if not locked or abs(angle) < 1e-12:
        result = base_processed.copy()
    else:
        frames = []
        for frame in base_processed:
            frames.append(_tab6_v8_rotate_for_analysis(self, frame, angle=angle, order=1))
        result = np.stack(frames, axis=0).astype(_intensity_dtype(self), copy=False)

    self._tab6_v8_finalized_primary_stack = result
    self._tab6_v8_finalized_stack_signature = sig
    return result


CDIWorkflowApp._tab6_build_exact_processed_primary_stack = _tab6_v8_build_exact_processed_primary_stack
globals()['_tab6_build_exact_processed_primary_stack'] = _tab6_v8_build_exact_processed_primary_stack

# NOTE: Early Tab-6 downstream wrapper removed; the finalized wrapper is installed later after the real rotation callbacks exist.

# ============================================================================
# APPLICATION LAUNCH — intentionally LAST so all notebook patches/bindings are
# installed before CDIWorkflowApp builds its UI.
# ============================================================================

# ============================================================================
# FINAL TAB 6 ROI DRAW FIX — DIRECT Tk CANVAS MOUSE DISPATCH
# Scope: Tab 6 Secondary ROI selection only.
# This is deliberately installed at the button-click time so later Tab-6
# canvas callback rebuilds cannot leave the button in DRAWING mode without
# working mouse events. Tabs 1–5 and 7–14 are untouched.
# ============================================================================

def _tab6_roi_direct_tk_bindings(self):
    """Install owned Tk mouse bindings for Tab-6 Secondary ROI drawing.

    The Matplotlib canvas can have its callback registry rebuilt by Tab-6
    display/zoom updates. Direct bindings on the embedded Tk widget are more
    reliable for the press -> drag -> release sequence. We convert the Tk
    coordinates into the same physical-nm Matplotlib coordinates already used
    by the existing D/Fit/ROI processing code, so the actual ROI calculation
    is unchanged.
    """
    canvas = getattr(self, '_proc_canvas', None)
    ax = getattr(self, '_proc_ax', None)
    if canvas is None or ax is None:
        return False

    widget = canvas.get_tk_widget()
    if widget is None:
        return False

    # Remove only bindings owned by this Tab-6 patch.
    owned = getattr(self, '_tab6_roi_direct_tk_ids', {})
    for seq, fid in list(owned.items()):
        try:
            if fid:
                widget.unbind(seq, fid)
        except Exception:
            pass
    owned = {}

    def _convert(ev):
        try:
            return _final_tk_event_to_mpl_data(canvas, ax, ev)
        except Exception:
            return None

    def _press(ev):
        if not getattr(self, '_proc_secondary_roi_selecting', False):
            return
        e = _convert(ev)
        if e is None:
            return 'break'
        _final_tab6_secondary_press_nm(self, e)
        return 'break'

    def _motion(ev):
        if not getattr(self, '_proc_secondary_roi_selecting', False):
            return
        e = _convert(ev)
        if e is None:
            return 'break'
        _proc_secondary_on_move_nm_safe(self, e)
        return 'break'

    def _release(ev):
        if not getattr(self, '_proc_secondary_roi_selecting', False):
            return
        e = _convert(ev)
        if e is None:
            return 'break'
        _proc_secondary_on_release_nm_safe(self, e)
        return 'break'

    owned['<ButtonPress-1>'] = widget.bind('<ButtonPress-1>', _press, add='+')
    owned['<B1-Motion>'] = widget.bind('<B1-Motion>', _motion, add='+')
    owned['<ButtonRelease-1>'] = widget.bind('<ButtonRelease-1>', _release, add='+')
    self._tab6_roi_direct_tk_ids = owned
    return True


# Wrap only the existing Tab-6 Secondary ROI start command. The original
