# ============================================================================
# TAB 6 ROTATION PRE-FLIGHT FIX
# Install the bbox method BEFORE CDIWorkflowApp is instantiated.
# This prevents AttributeError during early Tab-6 callbacks.
# ============================================================================

def _tab6_preflight_active_bbox(self, display_shape=None, mask=None, image=None):
    """Safe active-region bbox available from the moment the app is created.

    Supports all historical call forms:
        self._tab6_rotation_active_bbox((h, w))
        self._tab6_rotation_active_bbox((h, w), mask)
        self._tab6_rotation_active_bbox((h, w), mask, image=arr)
    """
    try:
        if image is not None:
            arr = np.asarray(image)
        elif display_shape is not None:
            shape = tuple(int(v) for v in display_shape)
            if len(shape) >= 2:
                arr = np.zeros(shape[:2], dtype=float)
            else:
                arr = np.zeros((1, 1), dtype=float)
        else:
            artist = getattr(self, "_proc_image_display", None)
            arr = np.asarray(artist.get_array()) if artist is not None else np.zeros((1, 1), dtype=float)
    except Exception:
        arr = np.zeros((1, 1), dtype=float)

    h, w = arr.shape[:2]
    if h <= 0 or w <= 0:
        return (0, 0, 0, 0)

    active = None

    # Prefer an explicitly supplied active mask.
    try:
        if mask is not None:
            m = np.asarray(mask, dtype=bool)
            if m.shape == (h, w) and np.any(m):
                active = m
    except Exception:
        active = None

    # Otherwise detect the non-background figure from the image.
    if active is None:
        try:
            v = np.asarray(arr, dtype=float)
            if v.ndim > 2:
                v = np.nanmean(v, axis=tuple(range(2, v.ndim)))

            finite = np.isfinite(v)
            vals = v[finite]

            if vals.size:
                lo = float(np.nanpercentile(vals, 1.0))
                hi = float(np.nanpercentile(vals, 99.0))
                span = hi - lo

                # Background is commonly constant/near-constant. Detect
                # meaningful deviation without assuming bright vs dark.
                if np.isfinite(span) and span > 0:
                    med = float(np.nanmedian(vals))
                    tol = max(1e-10, 0.02 * span)
                    active = finite & (np.abs(v - med) > tol)

                if active is None or not np.any(active):
                    active = finite
            else:
                active = finite
        except Exception:
            active = np.ones((h, w), dtype=bool)

    yy, xx = np.where(active)
    if xx.size == 0 or yy.size == 0:
        return (0, w, 0, h)

    x0, x1 = int(xx.min()), int(xx.max()) + 1
    y0, y1 = int(yy.min()), int(yy.max()) + 1

    # Small fixed margin; it does not increase with rotation angle.
    mx = max(2, int(round(0.02 * max(1, x1 - x0))))
    my = max(2, int(round(0.02 * max(1, y1 - y0))))

    return (
        max(0, x0 - mx),
        min(w, x1 + mx),
        max(0, y0 - my),
        min(h, y1 + my),
    )

