class DomainProgressBar(tk.Canvas):
    def __init__(self, master):
        super().__init__(master, height=22, background='white', highlightthickness=1,
            highlightbackground='#a0a0a0', borderwidth=0)
        self.value = 0.
        self.maximum = 100.
        self.bind('<Configure>', self.redraw)
        self.redraw()

    def configure(self, cnf=None, **kwargs):
        if isinstance(cnf, dict):
            kwargs = dict(cnf, **kwargs); cnf = None
        changed = 'value' in kwargs or 'maximum' in kwargs
        self.value = float(kwargs.pop('value', getattr(self, 'value', 0.)))
        self.maximum = float(kwargs.pop('maximum', getattr(self, 'maximum', 100.)))
        result = super().configure(cnf, **kwargs)
        if changed:
            self.redraw()
        return result

    config = configure

    def cget(self, key):
        if key in ('value', 'maximum'):
            return getattr(self, key)
        return super().cget(key)

    def redraw(self, event=None):
        self.delete('all')
        fraction = np.clip(self.value/max(self.maximum, 1.), 0., 1.)
        width, height = self.winfo_width(), max(22, self.winfo_height())
        self.create_rectangle(0, 0, width*fraction, height, fill='#248b42', outline='')
        self.create_text(width/2, height/2, text=f'{fraction*100:.0f}%', fill='black', font=('TkDefaultFont', 9))


def _analysis_progress_install(self, tab, parent):
    bar = DomainProgressBar(parent)
    setattr(self, f'tab{tab}_analysis_progress', bar)
    return bar


def _analysis_progress_update(self, tab, done, total=1):
    bar = getattr(self, f'tab{tab}_analysis_progress', None)
    if bar is not None and bar.winfo_exists():
        bar.configure(maximum=max(1, total), value=done)
        bar.update_idletasks()


def _analysis_progress_reset_all(self):
    for tab in (8, 10, 11):
        _analysis_progress_update(self, tab, 0)


