# FINAL EXPORT POLICY PATCH — folder-first + automatic filenames
# ---------------------------------------------------------------------------
# Destination-selection-only patch.  It changes export/save dialogs so the
# user selects an output folder first and the application supplies the
# filename automatically.  Analysis, fitting, D-Fit, Gaussian fitting,
# tracking, ROI, plotting, and other non-export logic are intentionally left
# untouched.
try:
    _EXPORT_ORIGINAL_ASKSAVE = filedialog.asksaveasfilename
    _EXPORT_ORIGINAL_ASKDIR = filedialog.askdirectory
except Exception:
    _EXPORT_ORIGINAL_ASKSAVE = None
    _EXPORT_ORIGINAL_ASKDIR = None


def _export_folder_first(parent=None, title='Select Output Folder'):
    """Ask for the destination folder and return it; Cancel returns ''."""
    if _EXPORT_ORIGINAL_ASKDIR is None:
        return ''
    try:
        folder = _export_capture_folder(_EXPORT_ORIGINAL_ASKDIR, parent=parent, title=title)
    except TypeError:
        folder = _export_capture_folder(_EXPORT_ORIGINAL_ASKDIR, title=title)
    return os.path.abspath(folder) if folder else ''


def _export_auto_filename(kwargs):
    """Generate a deterministic filename from initialfile/title + extension."""
    initialfile = str(kwargs.get('initialfile') or '').strip()
    if initialfile:
        name = os.path.basename(initialfile)
    else:
        title = str(kwargs.get('title') or 'Export').strip()
        name = re.sub(r'[^A-Za-z0-9._ -]+', '_', title)
        name = re.sub(r'\s+', '_', name).strip('._ ')
        if not name:
            name = 'Export'

    ext = str(kwargs.get('defaultextension') or '').strip()
    if ext and not ext.startswith('.'):
        ext = '.' + ext
    if ext and not os.path.splitext(name)[1]:
        name += ext

    # If no default extension was supplied, infer it from the first filetype.
    if not os.path.splitext(name)[1]:
        filetypes = kwargs.get('filetypes') or []
        for item in filetypes:
            try:
                pattern = str(item[1])
            except Exception:
                continue
            m = re.search(r'\*\.([A-Za-z0-9]+)', pattern)
            if m:
                name += '.' + m.group(1).lower()
                break
    return name


def _export_asksaveasfilename_folder_first(**kwargs):
    """Replacement save dialog: select folder only; filename is automatic."""
    parent = kwargs.get('parent')
    initialdir = kwargs.get('initialdir')

    # If the caller already selected the destination through an export helper,
    # reuse that directory so one export action produces only one prompt.
    if initialdir and os.path.isdir(str(initialdir)):
        folder = os.path.abspath(str(initialdir))
    else:
        folder = _export_folder_first(parent=parent, title='Select Output Folder')

    if not folder:
        return ''

    os.makedirs(folder, exist_ok=True)
    return os.path.join(folder, _export_auto_filename(kwargs))


if _EXPORT_ORIGINAL_ASKSAVE is not None:
    filedialog.asksaveasfilename = _export_asksaveasfilename_folder_first


