def _t6c_canvas_xy_to_data(self, event):
    """Convert a Tk canvas event (root coordinates) to Tab-6 Axes data coordinates."""
    canvas = getattr(self, '_proc_canvas', None)
    ax = getattr(self, '_proc_ax', None)
    if canvas is None or ax is None or event is None:
        return None
    try:
        w = canvas.get_tk_widget()
        cx = float(event.x_root) - float(w.winfo_rootx())
        cy_top = float(event.y_root) - float(w.winfo_rooty())
        height = float(w.winfo_height())
        cy = height - cy_top
        if cx < 0 or cy < 0 or cx > float(w.winfo_width()) or cy > height:
            # Still allow clamped coordinates during an active drag.
            cx = min(max(cx, 0.0), float(w.winfo_width()))
            cy = min(max(cy, 0.0), height)
        xy = ax.transData.inverted().transform([[cx, cy]])[0]
        x, y = float(xy[0]), float(xy[1])
        geom = self._tab6_physical_geometry()
        if geom is not None:
            pw, ph, _, _, *rest = geom
            x = min(max(x, 0.0), float(pw))
            y = min(max(y, 0.0), float(ph))
        return (x, y)
    except Exception:
        return None

def _t6c_canvas_event_inside_axes(self, event):
    canvas = getattr(self, '_proc_canvas', None)
    ax = getattr(self, '_proc_ax', None)
    if canvas is None or ax is None or event is None:
        return False
    try:
        w = canvas.get_tk_widget()
        cx = float(event.x_root) - float(w.winfo_rootx())
        cy = float(w.winfo_height()) - (float(event.y_root) - float(w.winfo_rooty()))
        bb = ax.get_window_extent()
        return bool(bb.x0 <= cx <= bb.x1 and bb.y0 <= cy <= bb.y1)
    except Exception:
        return False

def _t6c_remove_root_drag_bindings(self):
    root = getattr(self, 'root', None)
    if root is None:
        return
    for seq, attr in (
        ('<B1-Motion>', '_t6c_root_motion_id'),
        ('<ButtonRelease-1>', '_t6c_root_release_id'),
    ):
        fid = getattr(self, attr, None)
        if fid:
            try:
                root.unbind(seq, fid)
            except Exception:
                pass
            setattr(self, attr, None)

def _t6c_finish_drag(self, event=None):
    mode = getattr(self, '_t6c_drag_mode', None)
    start = getattr(self, '_t6c_drag_start', None)
    last = getattr(self, '_t6c_drag_last', None)
    if mode is None or start is None or last is None:
        _t6c_remove_root_drag_bindings(self)
        return

    x0, y0 = start
    x1, y1 = last

    if mode == 'roi':
        geom = self._tab6_physical_geometry()
        if geom is None:
            self.proc_secondary_status_var.set('Cannot determine Tab-6 physical ROI scale.')
            _t6c_remove_root_drag_bindings(self)
            self._t6c_drag_mode = None
            self._t6c_drag_start = None
            self._t6c_drag_last = None
            return
        pw, ph, w, h, *rest = geom
        xa, xb = sorted((max(0.0, min(x0, pw)), max(0.0, min(x1, pw))))
        ya, yb = sorted((max(0.0, min(y0, ph)), max(0.0, min(y1, ph))))
        xmin = max(0, min(int(np.floor(xa * w / pw)), w - 1))
        xmax = max(0, min(int(np.ceil(xb * w / pw) - 1), w - 1))
        ymin = max(0, min(int(np.floor(ya * h / ph)), h - 1))
        ymax = max(0, min(int(np.ceil(yb * h / ph) - 1), h - 1))
        if xmax <= xmin or ymax <= ymin:
            self.proc_secondary_status_var.set('Secondary ROI too small. Drag a larger rectangle.')
        else:
            self.roi2_coords = {
                'xmin': int(xmin), 'xmax': int(xmax),
                'ymin': int(ymin), 'ymax': int(ymax)
            }
            try:
                self.roi2_idx_var.set(max(0, min(int(self.proc_idx_var.get()), len(self.recons) - 1)))
            except Exception:
                pass
            self._proc_secondary_roi_selecting = False
            self._proc_secondary_press_xy = None
            try:
                self.proc_secondary_select_button.configure(text='SELECT SECONDARY ROI')
                self.proc_secondary_status_var.set(
                    self._tab6_secondary_status_nm() + ' | ✓ ROI SELECTED — click ✓ CONFIRM SECONDARY ROI.'
                )
            except Exception:
                pass
            try:
                self._proc_draw_secondary_roi_patch(confirmed=False)
            except Exception:
                pass

    elif mode == 'line':
        length_nm = float(np.hypot(x1 - x0, y1 - y0))
        if length_nm > 0:
            output_px = np.nan
            try:
                pw, ph, w, h, *rest = self._tab6_physical_geometry()
                output_px = float(np.hypot((x1 - x0) * w / pw, (y1 - y0) * h / ph))
            except Exception:
                pass
            try:
                if np.isfinite(output_px):
                    self.proc_profile_pixels_var.set(f'Profile length = {output_px:.3f} output-px')
                else:
                    self.proc_profile_pixels_var.set('Profile length = -- output-px')
                self.proc_profile_nm_var.set(f'Profile length = {length_nm:.6g} nm')
                self.proc_status_var.set(f'Profile measured: {length_nm:.6g} nm.')
            except Exception:
                pass
        self.proc_profile_mode = False
        self.proc_profile_press_xy = None

    _t6c_remove_root_drag_bindings(self)
    self._t6c_drag_mode = None
    self._t6c_drag_start = None
    self._t6c_drag_last = None
    try:
        self._proc_canvas.draw_idle()
    except Exception:
        pass

def _t6c_root_motion(self, event):
    mode = getattr(self, '_t6c_drag_mode', None)
    if mode is None:
        return
    xy = _t6c_canvas_xy_to_data(self, event)
    if xy is None:
        return
    self._t6c_drag_last = xy
    x0, y0 = self._t6c_drag_start
    x1, y1 = xy
    if mode == 'roi':
        xa, xb = sorted((x0, x1))
        ya, yb = sorted((y0, y1))
        patch = getattr(self, '_proc_secondary_patch', None)
        if patch is None:
            patch = plt.Rectangle(
                (xa, ya), max(1e-9, xb - xa), max(1e-9, yb - ya),
                fill=False, edgecolor='red', linewidth=2.5, zorder=100
            )
            self._proc_secondary_patch = patch
            self._proc_ax.add_patch(patch)
        else:
            patch.set_xy((xa, ya))
            patch.set_width(max(1e-9, xb - xa))
            patch.set_height(max(1e-9, yb - ya))
        self.proc_secondary_status_var.set('DRAWING — drag to set the Secondary ROI, then release.')
    elif mode == 'line':
        line = getattr(self, '_proc_profile_line_artist', None)
        if line is None:
            line, = self._proc_ax.plot(
                [x0, x1], [y0, y1], zorder=120,
                **self._proc_profile_line_kwargs()
            )
            self._proc_profile_line_artist = line
        else:
            line.set_data([x0, x1], [y0, y1])
        self.proc_status_var.set('DRAW LINE — release to measure the physical length.')
    try:
        self._proc_canvas.draw_idle()
    except Exception:
        pass

def _t6c_start_root_drag_bindings(self):
    _t6c_remove_root_drag_bindings(self)
    self._t6c_root_motion_id = self.root.bind(
        '<B1-Motion>', lambda e: _t6c_root_motion(self, e), add='+'
    )
    self._t6c_root_release_id = self.root.bind(
        '<ButtonRelease-1>', lambda e: _t6c_finish_drag(self, e), add='+'
    )

def _t6c_canvas_press(self, event):
    if event is None or getattr(event, 'num', None) != 1:
        return
    if not _t6c_canvas_event_inside_axes(self, event):
        return
    xy = _t6c_canvas_xy_to_data(self, event)
    if xy is None:
        return

    if getattr(self, '_proc_secondary_roi_selecting', False):
        # Fixed-size ROI mode: the exact clicked point is the ROI CENTER.
        # The ROI window is translated so its geometric center follows the
        # user's click; no drag operation is used.
        geom = self._tab6_physical_geometry()
        dims_px = getattr(self, '_tab6_secondary_fixed_shape_px', None)
        if geom is None or not dims_px:
            self.proc_secondary_status_var.set('Cannot determine the fixed Secondary ROI geometry.')
            return

        pw, ph, w, h = geom
        wp, hp = map(int, dims_px)
        if wp >= w or hp >= h:
            self.proc_secondary_status_var.set('Requested Secondary ROI is larger than the processed image.')
            return

        # Convert the click from the displayed physical coordinate system to
        # output-pixel coordinates.  Keep the click as the center coordinate.
        cx_nm = max(0.0, min(float(xy[0]), float(pw)))
        cy_nm = max(0.0, min(float(xy[1]), float(ph)))
        cx_px = cx_nm * w / pw
        cy_px = cy_nm * h / ph

        # Integer crop bounds for the existing ROI2 processing pipeline.
        # Center the fixed-size window on the clicked pixel.  The min/max
        # limits only prevent an invalid crop outside the primary ROI image.
        cx_idx = int(round(cx_px))
        cy_idx = int(round(cy_px))
        xmin = cx_idx - wp // 2
        ymin = cy_idx - hp // 2
        xmin = max(0, min(xmin, w - wp))
        ymin = max(0, min(ymin, h - hp))
        xmax = xmin + wp - 1
        ymax = ymin + hp - 1

        self.roi2_coords = {
            'xmin': int(xmin), 'xmax': int(xmax),
            'ymin': int(ymin), 'ymax': int(ymax)
        }
        try:
            self.roi2_idx_var.set(
                max(0, min(int(self.proc_idx_var.get()), len(self.recons) - 1))
            )
        except Exception:
            pass

        # Draw the visual ROI from the actual clicked center, rather than from
        # the integer crop origin.  This keeps the red window visually centered
        # on the exact point the user clicked.
        ww_nm = wp * pw / w
        hh_nm = hp * ph / h
        patch_x = cx_nm - ww_nm / 2.0
        patch_y = cy_nm - hh_nm / 2.0
        try:
            if self._proc_secondary_patch is not None:
                self._proc_secondary_patch.remove()
        except Exception:
            pass
        self._proc_secondary_patch = plt.Rectangle(
            (patch_x, patch_y), ww_nm, hh_nm,
            fill=False, edgecolor='red', linewidth=2.5, zorder=100
        )
        self._proc_ax.add_patch(self._proc_secondary_patch)

        self._proc_secondary_roi_selecting = False
        self._proc_secondary_press_xy = None
        self._t6c_drag_mode = None
        self._t6c_drag_start = None
        self._t6c_drag_last = None
        _t6c_remove_root_drag_bindings(self)
        try:
            self.proc_secondary_select_button.configure(
                text='SELECT / ADD ROI', state='normal'
            )
            self.proc_secondary_status_var.set(
                f'Secondary ROI selected: {ww_nm:.6g} × {hh_nm:.6g} nm. '
                f'Center = ({cx_nm:.6g}, {cy_nm:.6g}) nm. '
                'Click ✓ CONFIRM ROI to accept.'
            )
            self._proc_canvas.get_tk_widget().configure(cursor='')
        except Exception:
            pass
        try:
            self._proc_canvas.draw_idle()
        except Exception:
            pass
        return

    if getattr(self, 'proc_profile_mode', False):
        self._t6c_drag_mode = 'line'
        self._t6c_drag_start = xy
        self._t6c_drag_last = xy
        self.proc_profile_press_xy = xy
        try:
            if self._proc_profile_line_artist is not None:
                self._proc_profile_line_artist.remove()
        except Exception:
            pass
        self._proc_profile_line_artist, = self._proc_ax.plot(
            [xy[0], xy[0]], [xy[1], xy[1]],
            zorder=120, **self._proc_profile_line_kwargs()
        )
        self.proc_status_var.set('DRAW LINE — drag from endpoint 1 to endpoint 2, then release.')
        _t6c_start_root_drag_bindings(self)
        self._proc_canvas.draw_idle()

def _t6c_uninstall(self):
    widget = getattr(getattr(self, '_proc_canvas', None), 'get_tk_widget', lambda: None)()
    if widget is not None:
        try:
            tag = getattr(self, '_t6c_bindtag', None)
            if tag:
                for seq in ('<ButtonPress-1>', '<B1-Motion>', '<ButtonRelease-1>'):
                    try:
                        widget.unbind_class(tag, seq)
                    except Exception:
                        pass
                widget.bindtags(tuple(t for t in widget.bindtags() if t != tag))
        except Exception:
            pass
    self._t6c_bindtag = None
    _t6c_remove_root_drag_bindings(self)

def _t6c_install(self):
    """Install one authoritative Tk bindtag for Tab-6 press/motion/release."""
    widget = getattr(getattr(self, '_proc_canvas', None), 'get_tk_widget', lambda: None)()
    if widget is None:
        return
    _t6c_uninstall(self)
    tag = f'CDI_Tab6_CLEAN_{id(self)}'
    self._t6c_bindtag = tag
    try:
        tags = list(widget.bindtags())
        widget.bindtags((tag, *[t for t in tags if t != tag]))

        def _press(ev):
            if _figure_navigation_active(self._proc_canvas):
                return
            _t6c_canvas_press(self, ev)
            if getattr(self, '_t6c_drag_mode', None) is not None:
                return 'break'

        def _motion(ev):
            if _figure_navigation_active(self._proc_canvas):
                return
            if getattr(self, '_t6c_drag_mode', None) is None:
                return
            _t6c_root_motion(self, ev)
            return 'break'

        def _release(ev):
            if _figure_navigation_active(self._proc_canvas):
                return
            if getattr(self, '_t6c_drag_mode', None) is None:
                return
            _t6c_finish_drag(self, ev)
            return 'break'

        widget.bind_class(tag, '<ButtonPress-1>', _press, add='+')
        widget.bind_class(tag, '<B1-Motion>', _motion, add='+')
        widget.bind_class(tag, '<ButtonRelease-1>', _release, add='+')
    except Exception:
        pass

def _t6c_start_secondary_roi(self):
    if self.recons is None or self.roi_mask is None:
        messagebox.showwarning('Secondary ROI', 'Confirm the Primary ROI and load the processed data first.', parent=self.root)
        return
    if not getattr(self, 'roi_resolution_applied', False):
        messagebox.showwarning('Secondary ROI', 'Apply the confirmed ROI resolution first.', parent=self.root)
        return
    try:
        self._roi2_stop_playback()
    except Exception:
        pass
    self.proc_profile_mode = False
    self._proc_secondary_roi_selecting = True
    self._proc_secondary_press_xy = None
    self._t6c_drag_mode = None
    self._t6c_drag_start = None
    self._t6c_drag_last = None
    try:
        self.proc_secondary_select_button.configure(text='DRAWING — DRAG ON IMAGE')
        self.proc_secondary_status_var.set('DRAWING MODE ON: left-click + drag a rectangle on the processed image, then release.')
    except Exception:
        pass
    _t6c_install(self)

def _t6c_start_line(self):
    if self.roi_mask is None or self.recons is None:
        messagebox.showwarning('ROI Measurement', 'Confirm the Primary ROI in Tab 4 first.', parent=self.root)
        return
    base = self._proc_get_tab5_base_pixel_size()
    if base is None or not np.isfinite(base) or base <= 0:
        messagebox.showwarning('ROI Measurement', 'No valid Final Primary ROI nm/pixel was found in Tab 5. Confirm Tab-5 calibration first.', parent=self.root)
        return
    try:
        self.update_processing_pixel_size()
    except Exception:
        pass
    self._proc_secondary_roi_selecting = False
    self.proc_profile_mode = True
    self.proc_profile_press_xy = None
    self._t6c_drag_mode = None
    self._t6c_drag_start = None
    self._t6c_drag_last = None
    try:
        self.proc_status_var.set('DRAW LINE: left-click + drag from endpoint 1 to endpoint 2, then release.')
    except Exception:
        pass
    _t6c_install(self)

def _t6c_confirm_secondary_roi(self):
    if getattr(self, 'roi2_coords', None) is None:
        messagebox.showwarning('Secondary ROI', 'First select a Secondary ROI by click-dragging on the processed image.', parent=self.root)
        return
    if self.recons is None:
        messagebox.showwarning('Secondary ROI', 'Load the processed data first.', parent=self.root)
        return
    try:
        if hasattr(self, 'roi2_idx_var'):
            self.roi2_idx_var.set(max(0, min(int(self.proc_idx_var.get()), len(self.recons) - 1)))
        # Use the original, established ROI2 processing pipeline unchanged.
        self.confirm_roi2()
    except Exception as exc:
        messagebox.showerror('Secondary ROI', f'Failed to confirm secondary ROI:\n{type(exc).__name__}: {exc}', parent=self.root)
        self.log(f'Tab-6 Secondary ROI confirmation failed: {type(exc).__name__}: {exc}')
        return
    self._proc_secondary_roi_selecting = False
    try:
        self.roi2_confirmed_coords = dict(self.roi2_coords)
    except Exception:
        pass
    try:
        self.proc_secondary_select_button.configure(text='SELECT SECONDARY ROI')
        self.proc_secondary_status_var.set('✓ SECONDARY ROI CONFIRMED. ROI2 is ready for Tab 7.')
    except Exception:
        pass
    try:
        self._proc_draw_secondary_roi_patch(confirmed=True)
    except Exception:
        pass
    _t6c_uninstall(self)

def _t6c_clear_secondary_roi(self):
    self._proc_secondary_roi_selecting = False
    self._proc_secondary_press_xy = None
    self._t6c_drag_mode = None
    self._t6c_drag_start = None
    self._t6c_drag_last = None
    _t6c_uninstall(self)
    try:
        self._roi2_stop_playback()
    except Exception:
        pass
    try:
        self.clear_roi2()
    except Exception:
        # Clear local display state if the legacy helper is unavailable.
        self.roi2_coords = None
        self.roi2_confirmed_coords = None
        self.roi2_mask = None
        self.roi2_stack = None
    try:
        if self._proc_secondary_patch is not None:
            self._proc_secondary_patch.remove()
    except Exception:
        pass
    self._proc_secondary_patch = None
    try:
        self.proc_secondary_select_button.configure(text='SELECT SECONDARY ROI')
        self.proc_secondary_status_var.set('Secondary ROI cleared.')
        self._proc_canvas.draw_idle()
    except Exception:
        pass

def _t7c_canvas_xy_to_data(self, event):
    canvas = getattr(self, '_lpa_canvas', None)
    ax = getattr(self, '_lpa_ax', None)
    if canvas is None or ax is None or event is None:
        return None
    try:
        w = canvas.get_tk_widget()
        cx = float(event.x_root) - float(w.winfo_rootx())
        cy = float(w.winfo_height()) - (float(event.y_root) - float(w.winfo_rooty()))
        xy = ax.transData.inverted().transform([[cx, cy]])[0]
        return float(xy[0]), float(xy[1])
    except Exception:
        return None

def _t7c_press(self, event):
    if _figure_navigation_active(getattr(self, '_lpa_canvas', None)):
        return
    if not getattr(self, '_lpa_draw_mode', False) or getattr(event, 'num', None) != 1:
        return
    xy = _t7c_canvas_xy_to_data(self, event)
    if xy is None:
        return
    self._lpa_drag_start = xy
    try:
        old = getattr(self, '_lpa_temp_line', None)
        if old is not None:
            old.remove()
    except Exception:
        pass
    self._lpa_temp_line = self._lpa_ax.plot(
        [xy[0], xy[0]], [xy[1], xy[1]], '--', lw=2, alpha=0.8, zorder=50
    )[0]
    try:
        self._lpa_canvas.draw_idle()
    except Exception:
        pass

def _t7c_root_motion(self, event):
    if _figure_navigation_active(getattr(self, '_lpa_canvas', None)):
        return
    p0 = getattr(self, '_lpa_drag_start', None)
    if p0 is None:
        return
    xy = _t7c_canvas_xy_to_data(self, event)
    if xy is None:
        return
    self._lpa_drag_last = xy
    t = getattr(self, '_lpa_temp_line', None)
    if t is not None:
        t.set_data([p0[0], xy[0]], [p0[1], xy[1]])
        self._lpa_canvas.draw_idle()

def _t7c_release(self, event=None):
    if _figure_navigation_active(getattr(self, '_lpa_canvas', None)):
        return
    p0 = getattr(self, '_lpa_drag_start', None)
    p1 = getattr(self, '_lpa_drag_last', None)
    if p1 is None and event is not None:
        p1 = _t7c_canvas_xy_to_data(self, event)
    self._lpa_drag_start = None
    self._lpa_drag_last = None
    try:
        if self._lpa_temp_line is not None:
            self._lpa_temp_line.remove()
    except Exception:
        pass
    self._lpa_temp_line = None
    if p0 is None or p1 is None:
        return
    if np.hypot(p1[0] - p0[0], p1[1] - p0[1]) <= 1e-12:
        return
    self._lpa_lines.append((p0, p1))
    _lpa_redraw_lines_and_plot(self)
    target = getattr(self, '_lpa_draw_target', 1)
    if len(self._lpa_lines) >= target:
        self._lpa_draw_mode = False
        self._lpa_status_var.set(f'{len(self._lpa_lines)} line(s) drawn. Intensity profiles updated.')
        _t7c_uninstall(self)
    else:
        self._lpa_status_var.set(f'Draw line {len(self._lpa_lines) + 1}/{target} on ROI2.')

def _t7c_root_motion_and_release_install(self):
    root = self.root
    try:
        old = getattr(self, '_t7c_root_motion_id', None)
        if old: root.unbind('<B1-Motion>', old)
    except Exception: pass
    try:
        old = getattr(self, '_t7c_root_release_id', None)
        if old: root.unbind('<ButtonRelease-1>', old)
    except Exception: pass
    self._t7c_root_motion_id = root.bind('<B1-Motion>', lambda e: _t7c_root_motion(self, e), add='+')
    self._t7c_root_release_id = root.bind('<ButtonRelease-1>', lambda e: _t7c_release(self, e), add='+')

def _t7c_uninstall(self):
    """Completely remove the temporary DRAW LINE Tk bindtag.

    The old implementation removed only the root motion/release bindings but
    left the custom canvas bindtag installed. That tag consumed ButtonPress-1
    and prevented Matplotlib's button_press_event from reaching the Tab-7 line
    selection handler. After drawing finishes, remove the tag and all three
    temporary mouse bindings so normal line selection works.
    """
    try:
        old = getattr(self, '_t7c_root_motion_id', None)
        if old: self.root.unbind('<B1-Motion>', old)
    except Exception:
        pass
    try:
        old = getattr(self, '_t7c_root_release_id', None)
        if old: self.root.unbind('<ButtonRelease-1>', old)
    except Exception:
        pass
    self._t7c_root_motion_id = None
    self._t7c_root_release_id = None

    # IMPORTANT: remove the temporary canvas bindtag itself.  If it remains,
    # its ButtonPress-1 callback returns "break" and swallows Matplotlib
    # button_press_event, making SELECT/DELETE appear non-functional.
    canvas = getattr(self, '_lpa_canvas', None)
    tag = getattr(self, '_t7c_bindtag', None)
    if canvas is not None and tag:
        try:
            widget = canvas.get_tk_widget()
            for seq in ('<ButtonPress-1>', '<B1-Motion>', '<ButtonRelease-1>'):
                try:
                    widget.unbind_class(tag, seq)
                except Exception:
                    pass
            try:
                widget.bindtags(tuple(t for t in widget.bindtags() if t != tag))
            except Exception:
                pass
        except Exception:
            pass
    self._t7c_bindtag = None

def _t7c_start_draw(self):
    # Preserve the existing Tab-7 data-fetch/analysis path.
    if getattr(self, '_lpa_stack', None) is None:
        if not _lpa_fetch_roi2(self):
            return
    try:
        n = max(1, int(self._lpa_nlines_var.get()))
    except Exception:
        n = 1
    self._lpa_draw_target = n
    self._lpa_draw_mode = True
    self._lpa_drag_start = None
    self._lpa_drag_last = None
    _t7c_root_motion_and_release_install(self)

    canvas = getattr(self, '_lpa_canvas', None)
    if canvas is not None:
        widget = canvas.get_tk_widget()
        try:
            old_tag = getattr(self, '_t7c_bindtag', None)
            if old_tag:
                for seq in ('<ButtonPress-1>', '<B1-Motion>', '<ButtonRelease-1>'):
                    try: widget.unbind_class(old_tag, seq)
                    except Exception: pass
                try: widget.bindtags(tuple(t for t in widget.bindtags() if t != old_tag))
                except Exception: pass
            tag = f'CDI_Tab7_CLEAN_{id(self)}'
            self._t7c_bindtag = tag
            widget.bindtags((tag, *[t for t in widget.bindtags() if t != tag]))
            widget.bind_class(tag, '<ButtonPress-1>', lambda e: None if _figure_navigation_active(canvas) else (_t7c_press(self, e), 'break')[1], add='+')
            widget.bind_class(tag, '<B1-Motion>', lambda e: (_t7c_root_motion(self, e), 'break')[1] if not _figure_navigation_active(canvas) and getattr(self, '_lpa_drag_start', None) is not None else None, add='+')
            widget.bind_class(tag, '<ButtonRelease-1>', lambda e: (_t7c_release(self, e), 'break')[1] if not _figure_navigation_active(canvas) and getattr(self, '_lpa_drag_start', None) is not None else None, add='+')
        except Exception:
            pass
    try:
        self._lpa_status_var.set(f'Draw line 1/{n} on ROI2 (click-drag-release).')
    except Exception:
        pass

def _clean_legacy_tab6_rebind(self):
    _t6c_install(self)

def _clean_legacy_tab7_rebind(self):
    if getattr(self, '_lpa_draw_mode', False):
        _t7c_start_draw(self)

def _clean_legacy_tab7_measure_rebind(self):
    return None

def _tab6_confirm_secondary_roi_rebuilt_v6(self):
    """Confirm ROI2 directly from Tab 6 without any dependency on roi2_ax."""
    coords = getattr(self, 'roi2_coords', None)
    if not isinstance(coords, dict):
        messagebox.showwarning(
            'Secondary ROI',
            'First select a Secondary ROI by click-dragging on the processed image.',
            parent=self.root
        )
        return False

    recons = getattr(self, 'recons', None)
    if recons is None or len(recons) == 0:
        messagebox.showwarning(
            'Secondary ROI', 'Load the processed data first.', parent=self.root
        )
        return False

    # Make the optional viewer attributes exist, but NEVER construct or use the
    # viewer as part of confirmation.  This is the critical fix for roi2_ax.
    for name, default in (
        ('roi2_ax', None), ('roi2_canvas', None), ('roi2_fig', None),
        ('roi2_image', None), ('roi2_colorbar', None)
    ):
        if not hasattr(self, name):
            setattr(self, name, default)

    try:
        # Synchronize the selected frame only if the variable already exists.
        try:
            idx = int(self.proc_idx_var.get())
        except Exception:
            idx = 0
        idx = max(0, min(idx, len(recons) - 1))
        if hasattr(self, 'roi2_idx_var'):
            try:
                self.roi2_idx_var.set(idx)
            except Exception:
                pass

        # The Tab-6 processed image is the authoritative ROI2 coordinate space.
        source0 = np.asarray(self._roi2_source_image(idx), dtype=_intensity_dtype(self))
        source0 = np.squeeze(source0)
        if source0.ndim != 2:
            raise ValueError(f'Processed ROI image must be 2-D; received shape {source0.shape}.')
        h, w = source0.shape

        x0 = max(0, min(int(coords.get('xmin', 0)), w - 1))
        x1 = max(0, min(int(coords.get('xmax', 0)), w - 1))
        y0 = max(0, min(int(coords.get('ymin', 0)), h - 1))
        y1 = max(0, min(int(coords.get('ymax', 0)), h - 1))
        if x1 <= x0 or y1 <= y0:
            raise ValueError('Selected Secondary ROI has zero width or height.')

        # Build exactly the confirmed ROI2 stack used by downstream Tab 7.
        mask = np.zeros((h, w), dtype=bool)
        mask[y0:y1 + 1, x0:x1 + 1] = True
        lm = getattr(self, 'local_mask', None)
        if lm is not None:
            lm = np.asarray(lm, dtype=bool)
            if lm.shape == mask.shape:
                mask &= lm
        if not np.any(mask):
            raise ValueError('Selected Secondary ROI contains no valid processed pixels.')

        local_mask = mask[y0:y1 + 1, x0:x1 + 1]
        stack = np.empty(
            (len(recons), y1 - y0 + 1, x1 - x0 + 1), dtype=_intensity_dtype(self)
        )
        for i in range(len(recons)):
            img = np.asarray(self._roi2_source_image(i), dtype=_intensity_dtype(self))
            img = np.squeeze(img)
            if img.ndim != 2 or img.shape[0] != h or img.shape[1] != w:
                raise ValueError(
                    f'Processed frame {i + 1} has inconsistent shape {img.shape}; expected {(h, w)}.'
                )
            crop = np.array(img[y0:y1 + 1, x0:x1 + 1], dtype=_intensity_dtype(self), copy=True)
            crop[~local_mask] = 0.0
            stack[i] = crop

        confirmed = {'xmin': x0, 'xmax': x1, 'ymin': y0, 'ymax': y1}
        self.roi2_mask = mask
        self.roi2_coords = dict(confirmed)
        self.roi2_confirmed_coords = dict(confirmed)
        self.roi2_stack = stack

        # Stop only the Tab-6 ROI drawing transport; no legacy confirm routine.
        try:
            self._proc_secondary_roi_selecting = False
            self._proc_secondary_press_xy = None
            self._t6c_drag_mode = None
            self._t6c_drag_start = None
            self._t6c_drag_last = None
            _t6c_uninstall(self)
        except Exception:
            pass

        # Keep the selected rectangle visible in Tab 6.
        try:
            self._proc_draw_secondary_roi_patch(confirmed=True)
        except Exception as exc:
            try:
                self.log(f'Tab-6 ROI display refresh warning: {type(exc).__name__}: {exc}')
            except Exception:
                pass

        try:
            self.proc_secondary_select_button.configure(text='SELECT SECONDARY ROI')
        except Exception:
            pass
        try:
            self.proc_secondary_status_var.set(
                f'✓ SECONDARY ROI CONFIRMED. X={x0}:{x1}, Y={y0}:{y1} | '
                f'{x1-x0+1} × {y1-y0+1} px | {len(recons)} frames | ROI2 ready for Tab 7.'
            )
        except Exception:
            pass

        # Downstream handoff only.  These routines operate on roi2_stack and do
        # not need the Secondary-ROI viewer axes.  Each is independently guarded
        # so a display problem can never invalidate the confirmed ROI.
        try:
            capture = globals().get('_tab7_capture_roi2')
            if callable(capture):
                capture(self)
        except Exception as exc:
            try:
                self.log(f'Tab-7 ROI2 handoff warning: {type(exc).__name__}: {exc}')
            except Exception:
                pass

        try:
            refresh = getattr(self, '_pd7_refresh_from_confirmed_roi', None)
            if callable(refresh):
                refresh(preserve_zoom=True)
        except Exception as exc:
            try:
                self.log(f'Tab-7 display refresh warning: {type(exc).__name__}: {exc}')
            except Exception:
                pass

        try:
            self.log(
                f'Tab-6 Secondary ROI confirmed: X={x0}:{x1}, Y={y0}:{y1}, '
                f'size={x1-x0+1}x{y1-y0+1}, frames={len(recons)}.'
            )
        except Exception:
            pass
        return True

    except Exception as exc:
        try:
            self.log(
                f'Tab-6 Secondary ROI confirmation failed: '
                f'{type(exc).__name__}: {exc}'
            )
        except Exception:
            pass
        messagebox.showerror(
            'Secondary ROI',
            f'Failed to confirm secondary ROI:\n{type(exc).__name__}: {exc}',
            parent=self.root
        )
        return False


def _v6_find_button(root_widget, exact_text):
    try:
        for child in root_widget.winfo_children():
            try:
                if isinstance(child, (ttk.Button, tk.Button)):
                    if str(child.cget('text')).strip() == exact_text:
                        return child
            except Exception:
                pass
            found = _v6_find_button(child, exact_text)
            if found is not None:
                return found
    except Exception:
        pass
    return None

def _v6_install_tab7_measure_events(self):
    """Install native Matplotlib events for Tab-7 MEASURE.

    The measurement logic itself is the existing _lpa_measure_* implementation.
    Only the event transport is restored here.
    """
    canvas = getattr(self, '_lpa_plot_canvas', None)
    ax = getattr(self, '_lpa_plot_ax', None)
    if canvas is None or ax is None:
        return False

    # Disconnect only callbacks installed by this final patch.
    for attr in (
        '_v6_t7_measure_press_cid',
        '_v6_t7_measure_motion_cid',
        '_v6_t7_measure_release_cid',
    ):
        cid = getattr(self, attr, None)
        if cid is not None:
            try:
                canvas.mpl_disconnect(cid)
            except Exception:
                pass
            setattr(self, attr, None)

    self._v6_t7_measure_press_cid = canvas.mpl_connect(
        'button_press_event',
        lambda event: _lpa_measure_graph_press(self, event)
    )
    self._v6_t7_measure_motion_cid = canvas.mpl_connect(
        'motion_notify_event',
        lambda event: _lpa_measure_graph_motion(self, event)
    )
    self._v6_t7_measure_release_cid = canvas.mpl_connect(
        'button_release_event',
        lambda event: _lpa_measure_graph_release(self, event)
    )
    return True

def _v6_wire_tab6_buttons(self):
    """Wire the actual Tab-6 controls to the authoritative V6 methods."""
    try:
        btn = getattr(self, 'proc_secondary_select_button', None)
        if btn is not None:
            btn.configure(command=self.start_secondary_roi_selection)
    except Exception:
        pass

    try:
        btn = _v6_find_button(getattr(self, '_proc_control_frame', None),
                              '✓ CONFIRM SECONDARY ROI')
        if btn is not None:
            btn.configure(command=self.confirm_secondary_roi_from_processing)
    except Exception:
        pass

    try:
        btn = _v6_find_button(getattr(self, '_proc_control_frame', None),
                              'CLEAR SECONDARY ROI')
        if btn is not None:
            btn.configure(command=self.clear_secondary_roi_from_processing)
    except Exception:
        pass

    try:
        btn = _v6_find_button(getattr(self, '_proc_control_frame', None),
                              'DRAW LINE')
        if btn is not None:
            btn.configure(command=self.start_processing_profile_measure)
    except Exception:
        pass

def _v6_wire_tab7_buttons(self):
    """Wire Tab-7 DRAW LINE and MEASURE without touching analysis code."""
    parent = getattr(self, 'tab_line_profile_analysis', None)
    if parent is None:
        return

    try:
        btn = _v6_find_button(parent, 'DRAW LINE')
        if btn is not None:
            btn.configure(command=lambda: _t7c_start_draw(self))
    except Exception:
        pass

    try:
        btn = _v6_find_button(parent, 'MEASURE')
        if btn is not None:
            btn.configure(command=lambda: _lpa_measure_start(self))
    except Exception:
        pass

    _v6_install_tab7_measure_events(self)

def _v6_refresh_tab7_event_transport(self):
    """Reinstall Tab-7 measurement events after Tab-7 widgets are rebuilt."""
    try:
        self.after_idle(lambda: _v6_wire_tab7_buttons(self))
    except Exception:
        try:
            _v6_wire_tab7_buttons(self)
        except Exception:
            pass

CDIWorkflowApp.update_processing_view = _tab6_update_processing_view_v2

CDIWorkflowApp._final_rebind_tab6_callbacks = _clean_legacy_tab6_rebind

CDIWorkflowApp._final_lpa_force_draw_bindings = _clean_legacy_tab7_rebind

CDIWorkflowApp._final_rebind_tab7_measure_bindings = _clean_legacy_tab7_measure_rebind

_t6_bind = lambda app_obj: _t6c_install(app_obj)

_t7_bind = lambda app_obj: (_t7c_start_draw(app_obj) if getattr(app_obj, '_lpa_draw_mode', False) else None)



# Install only the clean authoritative commands. No old Tab-6/7 mouse handlers are called.

CDIWorkflowApp.start_secondary_roi_selection = _t6c_start_secondary_roi

CDIWorkflowApp.confirm_secondary_roi_from_processing = _t6c_confirm_secondary_roi

CDIWorkflowApp.clear_secondary_roi_from_processing = _t6c_clear_secondary_roi

CDIWorkflowApp.start_processing_profile_measure = _t6c_start_line

_lpa_start_draw = _t7c_start_draw

CDIWorkflowApp.confirm_secondary_roi_from_processing = _tab6_confirm_secondary_roi_rebuilt_v6

# Tab 6: authoritative button/event path.
