# ---------------- Tab 6: independent callbacks ----------------
def _tab6_proc_slider_independent_final(self, value=None):
    """Move Tab 6 processing frame without touching Tab 7."""
    if getattr(self, '_frame_sync_guard', False):
        return
    self._frame_sync_guard = True
    try:
        try:
            idx = self._ui_frame_to_internal(
                value if value is not None
                else getattr(self, '_proc_display_frame_var', tk.DoubleVar(value=0)).get()
            )
        except Exception:
            idx = self._clamp_frame(getattr(self, 'proc_idx_var', tk.IntVar(value=0)).get())
        idx = self._clamp_frame(idx)
        self.current_index = idx
        self.proc_idx_var.set(idx)
        try:
            self._proc_display_frame_var.set(idx)
        except Exception:
            pass
        try:
            self.update_processing_view()
        except Exception:
            pass
        try:
            self.line_profile_frame_var.set(idx)
            if getattr(self, 'line_profile_image', None) is not None:
                self._line_profile_update_image(idx=idx, preserve_lines=True)
        except Exception:
            pass
        try:
            self.roi2_idx_var.set(idx)
        except Exception:
            pass
    finally:
        self._frame_sync_guard = False


def _tab6_line_profile_slider_independent_final(self, value=None):
    """Move Tab-6 line-profile frame without touching Tab 7."""
    if getattr(self, '_frame_sync_guard', False):
        return
    self._frame_sync_guard = True
    try:
        try:
            idx = self._ui_frame_to_internal(
                value if value is not None
                else getattr(self, '_line_profile_display_frame_var', tk.DoubleVar(value=0)).get()
            )
        except Exception:
            idx = self._clamp_frame(getattr(self, 'line_profile_frame_var', tk.IntVar(value=0)).get())
        idx = self._clamp_frame(idx)
        self.current_index = idx
        self.line_profile_frame_var.set(idx)
        try:
            self._line_profile_display_frame_var.set(idx)
        except Exception:
            pass
        try:
            self._line_profile_update_image(idx=idx, preserve_lines=True)
        except Exception:
            pass
        try:
            self.proc_idx_var.set(idx)
            if getattr(self, 'proc_slider', None) is not None and hasattr(self, '_proc_display_frame_var'):
                self._proc_display_frame_var.set(idx)
                self.proc_slider.set(idx)
        except Exception:
            pass
        try:
            self.roi2_idx_var.set(idx)
        except Exception:
            pass
    finally:
        self._frame_sync_guard = False


CDIWorkflowApp._proc_slider_update = _tab6_proc_slider_independent_final
CDIWorkflowApp._line_profile_frame_slider_changed = _tab6_line_profile_slider_independent_final


def _bind_tab6_frame_slider_independent_final(self):
    """Rebind Tab-6 sliders so later range refreshes cannot recouple Tab 7."""
    n = max(1, self._frame_count())
    try:
        if getattr(self, 'proc_slider', None) is not None:
            if not hasattr(self, '_proc_display_frame_var'):
                self._proc_display_frame_var = tk.DoubleVar(value=self._clamp_frame(self.proc_idx_var.get()))
            self.proc_slider.configure(
                from_=0, to=max(0, n - 1), resolution=1,
                variable=self._proc_display_frame_var,
                command=lambda v: _tab6_proc_slider_independent_final(self, v)
            )
    except Exception:
        pass
    try:
        if getattr(self, 'line_profile_frame_slider', None) is not None:
            if not hasattr(self, '_line_profile_display_frame_var'):
                self._line_profile_display_frame_var = tk.DoubleVar(value=self._clamp_frame(self.line_profile_frame_var.get()) + 1)
            self.line_profile_frame_slider.configure(
                from_=0, to=max(0, n - 1), resolution=1,
                variable=self._line_profile_display_frame_var,
                command=lambda v: _tab6_line_profile_slider_independent_final(self, v)
            )
    except Exception:
        pass

CDIWorkflowApp._bind_tab6_frame_slider_sync = _bind_tab6_frame_slider_independent_final


# Do not let the old common-range routine overwrite Tab-7's independent frame.
def _sync_all_visible_frame_ranges_independent_final(self):
    n = self._frame_count()
    if n <= 0:
        return
    try:
        self._tab4_sync_roi_index_range()
    except Exception:
        pass

    # Tab 6 controls follow Tab 6/current processing frame.
    try:
        idx6 = self._clamp_frame(getattr(self, 'current_index', 0))
        if getattr(self, 'proc_slider', None) is not None:
            if not hasattr(self, '_proc_display_frame_var'):
                self._proc_display_frame_var = tk.DoubleVar(value=idx6)
            self.proc_slider.configure(
                from_=0, to=max(0, n - 1), resolution=1,
                variable=self._proc_display_frame_var,
                command=lambda v: _tab6_proc_slider_independent_final(self, v)
            )
            self._proc_display_frame_var.set(idx6)
            self.proc_slider.set(idx6)
        if getattr(self, 'line_profile_frame_slider', None) is not None:
            if not hasattr(self, '_line_profile_display_frame_var'):
                self._line_profile_display_frame_var = tk.DoubleVar(value=int(getattr(self, 'line_profile_frame_var', tk.IntVar(value=idx6)).get()) + 1)
            idx_lp = self._clamp_frame(self.line_profile_frame_var.get())
            self._line_profile_display_frame_var.set(idx_lp)
            self.line_profile_frame_slider.configure(
                from_=0, to=max(0, n - 1), resolution=1,
                variable=self._line_profile_display_frame_var,
                command=lambda v: _tab6_line_profile_slider_independent_final(self, v)
            )
            self.line_profile_frame_slider.set(idx_lp)
    except Exception:
        pass

    # Tab 7 keeps its own frame. Only its range is refreshed when N changes.
    try:
        if getattr(self, 'pd_frame_slider', None) is not None:
            stack = getattr(self, 'roi2_stack', None)
            n7 = len(stack) if stack is not None and len(stack) else n
            n7 = max(1, int(n7))
            idx7 = max(0, min(int(self.pd_frame_var.get()), n7 - 1))
            self.pd_frame_var.set(idx7)
            if not hasattr(self, '_pd_display_frame_var'):
                self._pd_display_frame_var = tk.DoubleVar(value=idx7)
            self._pd_display_frame_var.set(idx7)
            self.pd_frame_slider.configure(
                from_=0, to=max(0, n7 - 1), resolution=1,
                variable=self._pd_display_frame_var,
                command=lambda v: _tab7_independent_frame_changed_final(self, v)
            )
            self.pd_frame_slider.set(idx7)
    except Exception:
        pass

CDIWorkflowApp._sync_all_visible_frame_ranges = _sync_all_visible_frame_ranges_independent_final

