# ============================================================================
# FINAL FRAME DECOUPLING: TAB 6 <-> TAB 7
# Tab 7 (Line Profile) owns its own frame state after ROI2 is fetched.
# Tab 6 processing frame changes must never move Tab 7's slider, and vice versa.
# This block is intentionally placed immediately before mainloop so it is active
# during the running application.
# ============================================================================

def _tab7_frame_slider_decoupled_final(self, value=None):
    """Move ONLY Tab 7 Line Profile to the requested frame."""
    if getattr(self, '_tab7_frame_change_guard', False):
        return 'break'
    stack = getattr(self, '_t7_stack_copy', None)
    if stack is None:
        stack = getattr(self, 'line_source_stack', None)
    if stack is None:
        stack = getattr(self, 'roi2_stack', None)
    if stack is None or len(stack) == 0:
        return 'break'
    try:
        display_no = int(round(float(value))) if value is not None else int(round(float(self._t7_frame_ui_var.get())))
    except Exception:
        display_no = 0
    n = int(len(stack))
    display_no = max(0, min(display_no, n - 1))
    idx = display_no
    self._tab7_frame_change_guard = True
    try:
        self._t7_frame = idx
        self._t7_frame_ui_var.set(display_no)
        if hasattr(self, 'line_profile_frame_var'):
            self.line_profile_frame_var.set(idx)
        if hasattr(self, 'line_profile_frame_slider'):
            self.line_profile_frame_slider.configure(
                from_=0, to=max(0, n - 1), resolution=1,
                variable=self._t7_frame_ui_var,
                command=lambda v: _tab7_frame_slider_decoupled_final(self, v)
            )
            self.line_profile_frame_slider.set(display_no)
        _t7_render(self, idx, preserve_zoom=True)
    finally:
        self._tab7_frame_change_guard = False
    return 'break'


def _tab6_proc_slider_decoupled_final(self, value=None):
    """Move ONLY Tab 6 processing frame; never touch Tab 7 frame state."""
    if getattr(self, '_frame_sync_guard', False):
        return
    self._frame_sync_guard = True
    try:
        try:
            idx = self._ui_frame_to_internal(
                value if value is not None else getattr(self, '_proc_display_frame_var', tk.DoubleVar(value=0)).get()
            )
        except Exception:
            idx = self._clamp_frame(getattr(self, 'proc_idx_var', tk.IntVar(value=0)).get())
        idx = self._clamp_frame(idx)
        self.current_index = idx
        self.proc_idx_var.set(idx)
        try:
            self._proc_display_frame_var.set(idx)
        except Exception:
            pass
        try:
            self.update_processing_view()
        except Exception:
            pass
        # Deliberately DO NOT modify:
        #   line_profile_frame_var / line_profile_frame_slider / _t7_frame
        #   _t7_frame_ui_var / Tab 7 image or measurements.
    finally:
        self._frame_sync_guard = False


def _update_frame_ui_decoupled_final(self, idx):
    """Update shared Tab-6/Tab-8 UI without touching Tab 7's frame."""
    idx = self._clamp_frame(idx)
    n = self._frame_count()
    self.current_index = idx
    # Tab 6 + ROI2 state remains synchronized as before.
    for name in ('proc_idx_var', 'roi2_idx_var', 'pd_frame_var'):
        var = getattr(self, name, None)
        if var is not None:
            try:
                var.set(idx)
            except Exception:
                pass
    try:
        if hasattr(self, '_proc_display_frame_var'):
            self._proc_display_frame_var.set(idx)
        if getattr(self, 'proc_slider', None) is not None:
            self.proc_slider.set(idx)
    except Exception:
        pass
    # Tab 7 is intentionally omitted here.
    try:
        if hasattr(self, '_pd_display_frame_var'):
            self._pd_display_frame_var.set(idx)
        if getattr(self, 'pd_frame_slider', None) is not None:
            self.pd_frame_slider.set(idx)
    except Exception:
        pass
    try:
        if hasattr(self, '_tab4_display_var'):
            self._tab4_display_var.set(str(idx))
        if getattr(self, '_tab4_roi_index_spinbox', None) is not None:
            self._tab4_roi_index_spinbox.set(idx)
    except Exception:
        pass
    field = None
    try:
        if self.real_fields_mT is not None and len(self.real_fields_mT) > idx:
            field = float(self.real_fields_mT[idx])
    except Exception:
        field = None
    frame_text = f'Frame {idx}/{n}'
    if field is not None:
        frame_text += f' | Field = {field:+.2f} mT'
    try:
        self.proc_field_var.set(frame_text)
    except Exception:
        pass
    # Do not update line_profile_frame_label here: it belongs to Tab 7.
    try:
        w = getattr(self, 'pd_frame_label', None)
        if w is not None:
            w.config(text=f'{idx}/{n} | {field:+.2f} mT' if field is not None else f'{idx}/{n}')
    except Exception:
        pass
    return idx


# Install the truly isolated callbacks.
CDIWorkflowApp._tab7_frame_slider_changed_decoupled = _tab7_frame_slider_decoupled_final
CDIWorkflowApp._tab6_proc_slider_update_decoupled = _tab6_proc_slider_decoupled_final
