# Prevent future common-range refreshes from re-binding Tab 7 to Tab 6.
_TAB7_OLD_COMMON_SYNC_FINAL = getattr(CDIWorkflowApp, '_sync_all_visible_frame_ranges', None)
def _sync_all_visible_frame_ranges_tab7_decoupled_final(self):
    saved_idx7 = int(getattr(self, '_t7_frame', 0))
    result = None
    if _TAB7_OLD_COMMON_SYNC_FINAL is not None:
        try:
            result = _TAB7_OLD_COMMON_SYNC_FINAL(self)
        except Exception:
            result = None
    try:
        stack7 = getattr(self, '_t7_stack_copy', None)
        if stack7 is None:
            stack7 = getattr(self, 'line_source_stack', None)
        if stack7 is None:
            stack7 = getattr(self, 'roi2_stack', None)
        if stack7 is not None and len(stack7):
            n7 = int(len(stack7))
            idx7 = max(0, min(saved_idx7, n7 - 1))
            self._t7_frame = idx7
            self._t7_frame_ui_var.set(idx7)
            self.line_profile_frame_var.set(idx7)
            self.line_profile_frame_slider.configure(
                from_=0, to=max(0, n7 - 1), resolution=1,
                variable=self._t7_frame_ui_var,
                command=lambda v: _tab7_frame_slider_decoupled_final(self, v)
            )
            self.line_profile_frame_slider.set(idx7)
    except Exception:
        pass
    return result
CDIWorkflowApp._sync_all_visible_frame_ranges = _sync_all_visible_frame_ranges_tab7_decoupled_final

