_T7_DELETE_REDRAW_BASE = _lpa_redraw_lines_and_plot

def _t7_redraw_with_selection(self):
    _T7_DELETE_REDRAW_BASE(self)
    _t7_style_selected_lines(self)

_lpa_redraw_lines_and_plot = _t7_redraw_with_selection
CDIWorkflowApp._lpa_redraw_lines_and_plot = _t7_redraw_with_selection

# Clear selection/undo state whenever the normal CLEAR LINES operation is used.
_T7_DELETE_CLEAR_BASE = getattr(CDIWorkflowApp, '_lpa_clear_lines', None)
if _T7_DELETE_CLEAR_BASE is not None:
    def _t7_clear_lines_with_delete_reset(self):
        result = _T7_DELETE_CLEAR_BASE(self)
        self._t7_selected_lines = set()
        self._t7_last_deleted_lines = None
