# -----------------------------------------------------------------------------
# FINAL TAB 4 ROI / FRAME CONTROL FIX
# -----------------------------------------------------------------------------
# Tab 4 is the Primary ROI selector.  Keep its frame number user-facing as
# 1..N while the internal reconstruction arrays remain 0..N-1.

def _tab4_final_refresh(self, *args, **kwargs):
    """Refresh Tab 4 using the current internal frame index."""
    if getattr(self, 'recons', None) is None:
        try:
            self.roi_status_var.set('Load reconstructions first.')
        except Exception:
            pass
        return
    try:
        n = len(self.recons)
        idx = self._clamp_frame(self.roi_index_var.get())
        self.roi_index_var.set(idx)
        if hasattr(self, '_tab4_display_var'):
            self._tab4_display_var.set(str(idx))
    except Exception:
        idx = 0
    # Call the original refresh implementation saved before this final wrapper.
    return _TAB4_REFRESH_BASE(self)


def _tab4_final_sync_range(self):
    """Synchronize Tab 4's one-based Spinbox with the internal frame index."""
    n = self._frame_count()
    spin = getattr(self, '_tab4_roi_index_spinbox', None)
    if n <= 0:
        if spin is not None:
            try:
                spin.configure(from_=0, to=0, state='disabled')
                spin.set(0)
            except Exception:
                pass
        return
    idx = self._clamp_frame(getattr(self, 'roi_index_var', tk.IntVar(value=0)).get())
    try:
        self.roi_index_var.set(idx)
    except Exception:
        pass
    try:
        if not hasattr(self, '_tab4_display_var'):
            self._tab4_display_var = tk.StringVar(value=str(idx))
        self._tab4_display_var.set(str(idx))
    except Exception:
        pass
    if spin is not None:
        try:
            spin.configure(from_=0, to=max(0, n - 1), state='normal', increment=1, wrap=False)
            spin.set(idx)
        except Exception:
            pass


def _tab4_final_set_frame(self, value=None):
    """Apply a one-based Tab-4 frame number and redraw only Tab 4."""
    n = self._frame_count()
    if n <= 0:
        return 'break'
    try:
        display_no = int(round(float(value))) if value is not None else int(round(float(self._tab4_display_var.get())))
    except Exception:
        display_no = 0
    display_no = max(0, min(display_no, n - 1))
    idx = display_no
    if getattr(self, '_frame_sync_guard', False):
        return 'break'
    self._frame_sync_guard = True
    try:
        self.roi_index_var.set(idx)
        if not _tab4_has_confirmed_roi(self):
            self.current_index = idx
        if hasattr(self, '_tab4_display_var'):
            self._tab4_display_var.set(str(display_no))
        self._tab4_sync_roi_index_range()
        _TAB4_REFRESH_BASE(self)
    finally:
        self._frame_sync_guard = False
    return 'break'


# Preserve the already-composed Tab-4 refresh implementation and wrap it once.
_TAB4_REFRESH_BASE = CDIWorkflowApp.refresh_roi_image
CDIWorkflowApp.refresh_roi_image = _tab4_final_refresh
CDIWorkflowApp._tab4_sync_roi_index_range = _tab4_final_sync_range

# Rebind the existing Tab-4 Spinbox after all prior wrappers have been installed.
_TAB4_BUILD_BASE_FINAL = CDIWorkflowApp._build_roi_tab

def _tab4_final_build(self):
    _TAB4_BUILD_BASE_FINAL(self)
    try:
        spin = getattr(self, '_tab4_roi_index_spinbox', None)
        if spin is None:
            def walk(widget):
                for child in widget.winfo_children():
                    yield child
                    yield from walk(child)
            for w in walk(self.tab_roi):
                if str(w.winfo_class()).lower().endswith('spinbox'):
                    spin = w
                    break
        self._tab4_roi_index_spinbox = spin
        if not hasattr(self, '_tab4_display_var'):
            self._tab4_display_var = tk.StringVar(value='0')
        if spin is not None:
            spin.configure(textvariable=self._tab4_display_var, state='normal', from_=0, to=0, increment=1, wrap=False)
            spin.configure(command=lambda: _tab4_final_set_frame(self))
            # Avoid duplicate class bindings by replacing the Tab-4-specific binding tag.
            spin.bind('<Up>', lambda e: _tab4_final_set_frame(self), add='+')
            spin.bind('<Down>', lambda e: _tab4_final_set_frame(self), add='+')
            spin.bind('<Return>', lambda e: _tab4_final_set_frame(self), add='+')
        self._tab4_sync_roi_index_range()
    except Exception as exc:
        try:
            self.log(f'Tab 4 frame-control initialization warning: {exc}')
        except Exception:
            pass

CDIWorkflowApp._build_roi_tab = _tab4_final_build

# Ensure frame loading always leaves Tab 4 in a valid range.
for _tab4_loader_name in ('load_reconstructions', 'load_all_reconstructions', 'full_load', 'test_single_hdf5'):
    _tab4_old_loader = getattr(CDIWorkflowApp, _tab4_loader_name, None)
    if _tab4_old_loader is None:
        continue
    def _tab4_make_loader(old_method):
        def _tab4_loader(self, *args, **kwargs):
            result = old_method(self, *args, **kwargs)
            try:
                self._tab4_sync_roi_index_range()
                if getattr(self, 'recons', None) is not None and len(self.recons):
                    self.refresh_roi_image()
            except Exception as exc:
                try:
                    self.log(f'Tab 4 frame sync warning after load: {exc}')
                except Exception:
                    pass
            return result
        return _tab4_loader
    setattr(CDIWorkflowApp, _tab4_loader_name, _tab4_make_loader(_tab4_old_loader))


# ===== TAB 10: EXPORT TABLE =====
@_auto_open_export
def export_table():
    """Export all available Tab-10 tracking/result data points to CSV."""
    import csv
    from tkinter import filedialog, messagebox
    path = filedialog.asksaveasfilename(
        title="Export Table",
        defaultextension=".csv",
        filetypes=[("CSV files", "*.csv")]
    )
    if not path:
        return
    try:
        rows = []
        # Prefer an existing results dataframe/list if supplied by the notebook.
        if 'results_df' in globals() and results_df is not None:
            _export_capture_write(results_df.to_csv, path, index=False)
        elif 'tracking_data' in globals() and tracking_data:
            if isinstance(tracking_data, dict):
                keys = list(tracking_data.keys())
                n = max((len(v) if hasattr(v, "__len__") and not isinstance(v, str) else 1)
                        for v in tracking_data.values())
                for i in range(n):
                    rows.append({
                        k: (v[i] if hasattr(v, "__len__") and not isinstance(v, str) and i < len(v) else v)
                        for k,v in tracking_data.items()
                    })
            else:
                rows = tracking_data
            with _export_capture_stream(open, path, 'w', newline='', encoding='utf-8-sig') as f:
                if rows:
                    writer = csv.DictWriter(f, fieldnames=list(rows[0].keys()))
                    writer.writeheader()
                    writer.writerows(rows)
        elif 'results_rows' in globals() and results_rows:
            with _export_capture_stream(open, path, 'w', newline='', encoding='utf-8-sig') as f:
                writer = csv.writer(f)
                writer.writerows(results_rows)
        else:
            raise RuntimeError("No Tab-10 results/tracking data are available to export.")
        messagebox.showinfo("Export Table", f"Table exported to:\n{path}")
    except Exception as e:
        _export_error_dialog(messagebox.showerror, 'Export Table', str(e))


# ============================================================================
# FINAL TAB-6 SECONDARY ROI COORDINATE-SYSTEM FIX (v13)
# ----------------------------------------------------------------------------
# The Tab-6 image is rotated with reshape=True AND tightly cropped to the
# active/figure edge.  Earlier downstream ROI2 code rotated the source again
# but recomputed a different crop for each frame.  Therefore a rectangle drawn
# in Tab-6 could refer to different pixels in Tab-7.
#
# This patch makes the Tab-6 displayed crop the single authoritative coordinate
# system for Secondary ROI selection/confirmation and for the ROI2 stack.
# It does not modify the original reconstruction stack or other tabs' logic.
# ============================================================================

# Keep the exact bbox used by the visible Tab-6 image.
try:
    _TAB6_V13_DISPLAY_APPLY_BASE = _tab6_signed_display_apply
except Exception:
    _TAB6_V13_DISPLAY_APPLY_BASE = None

if _TAB6_V13_DISPLAY_APPLY_BASE is not None:
    def _tab6_v13_display_apply(self, reset_zoom=True):
        result = _TAB6_V13_DISPLAY_APPLY_BASE(self, reset_zoom=reset_zoom)
        try:
            base = np.asarray(getattr(self, '_tab6_base_display_array'), dtype=float)
            mask = getattr(self, '_tab6_base_mask', None)
            angle = float(getattr(self, '_tab6_rotation_angle', 0.0))
            rotated = _tab6_final_rotate_array(self, base, angle=angle, order=1)
            rmask = None
            if mask is not None:
                rmask = _tab6_final_rotate_array(
                    self, np.asarray(mask, dtype=_intensity_dtype(self)), angle=angle, order=0
                ) > 0.5
            bbox = _tab6_final_active_bbox(self, rotated, rmask)
            self._tab6_display_crop_bbox = tuple(int(v) for v in bbox)
            # Once SET has been pressed, this is the coordinate system in which
            # the user draws the Secondary ROI. Do not replace it on frame change.
            if not getattr(self, '_tab6_analysis_rotation_committed', False):
                self._tab6_analysis_display_bbox = None
        except Exception:
            pass
        return result


    _tab6_signed_display_apply = _tab6_v13_display_apply
    _tab6_final_apply_rotation = _tab6_v13_display_apply
    CDIWorkflowApp._tab6_apply_rotation_to_display = _tab6_v13_display_apply

# Fixed-size crop helper.  If a later frame has a slightly different rotated
# canvas, pad/crop it into exactly the SET-frame coordinate system.
def _tab6_v13_crop_fixed(self, arr, bbox, fill=0.0):
    a = np.asarray(arr)
    x0, x1, y0, y1 = [int(v) for v in bbox]
    out_h = max(1, y1 - y0)
    out_w = max(1, x1 - x0)
    out = np.full((out_h, out_w), fill, dtype=a.dtype)
    h, w = a.shape[:2]
    ix0, ix1 = max(0, x0), min(w, x1)
    iy0, iy1 = max(0, y0), min(h, y1)
    if ix1 > ix0 and iy1 > iy0:
        ox0, oy0 = ix0 - x0, iy0 - y0
        out[oy0:oy0 + (iy1 - iy0), ox0:ox0 + (ix1 - ix0)] = a[iy0:iy1, ix0:ix1]
    return out

# Capture the exact Tab-6 display bbox at SET time.
try:
    _TAB6_V13_SET_BASE = CDIWorkflowApp._tab6_rotation_set
except Exception:
    _TAB6_V13_SET_BASE = None

if _TAB6_V13_SET_BASE is not None:
    def _tab6_v13_set(self, *args, **kwargs):
        result = _TAB6_V13_SET_BASE(self, *args, **kwargs)
        try:
            bbox = getattr(self, '_tab6_display_crop_bbox', None)
            if bbox is not None:
                self._tab6_analysis_display_bbox = tuple(int(v) for v in bbox)
        except Exception:
            pass
        return result
    CDIWorkflowApp._tab6_rotation_set = _tab6_v13_set

# RESET clears the frozen coordinate system. RELEASE intentionally keeps it,
# because the last SET angle remains authoritative downstream.
try:
    _TAB6_V13_RESET_BASE = CDIWorkflowApp._tab6_rotation_reset
except Exception:
    _TAB6_V13_RESET_BASE = None
if _TAB6_V13_RESET_BASE is not None:
    def _tab6_v13_reset(self, *args, **kwargs):
        result = _TAB6_V13_RESET_BASE(self, *args, **kwargs)
        self._tab6_analysis_display_bbox = None
        self._tab6_display_crop_bbox = None
        return result
    CDIWorkflowApp._tab6_rotation_reset = _tab6_v13_reset

# Authoritative source for Tab-7/ROI2: rotate the ORIGINAL unrotated processed
# frame and crop it using the SAME fixed bbox that was visible in Tab-6 when SET
# was pressed.  Never recompute the bbox per frame.
try:
    _TAB6_V13_ORIGINAL_ROI2_SOURCE = globals().get('_TAB6_SIGNED_ORIGINAL_ROI2_SOURCE', None)
    if not callable(_TAB6_V13_ORIGINAL_ROI2_SOURCE):
        _TAB6_V13_ORIGINAL_ROI2_SOURCE = globals().get('_TAB6_V8_ORIGINAL_ROI2_SOURCE', None)
except Exception:
    _TAB6_V13_ORIGINAL_ROI2_SOURCE = None

if callable(_TAB6_V13_ORIGINAL_ROI2_SOURCE):
    def _tab6_v13_roi2_source_image(self, idx):
        base = np.asarray(_TAB6_V13_ORIGINAL_ROI2_SOURCE(self, idx), dtype=_intensity_dtype(self))
        if not getattr(self, '_tab6_analysis_rotation_committed', False):
            return base
        angle = float(getattr(self, '_tab6_analysis_rotation_angle', 0.0))
        rotated = _tab6_final_rotate_array(self, base, angle=angle, order=1).astype(_intensity_dtype(self))
        bbox = getattr(self, '_tab6_analysis_display_bbox', None)
        if bbox is None:
            # Safety fallback: use the current frame's exact Tab-6 edge.
            rmask = None
            bm = getattr(self, '_tab6_base_mask', None)
            if bm is not None:
                rmask = _tab6_final_rotate_array(
                    self, np.asarray(bm, dtype=_intensity_dtype(self)), angle=angle, order=0
                ) > 0.5
            bbox = _tab6_final_active_bbox(self, rotated, rmask)
        return _tab6_v13_crop_fixed(self, rotated, bbox, fill=0.0).astype(_intensity_dtype(self))


    CDIWorkflowApp._roi2_source_image = _tab6_v13_roi2_source_image

# Correct Secondary ROI confirmation for the rotated coordinate system.  The
# old routine intersected the rectangle with the UNROTATED local_mask when the
# rotated ROI happened to have the same shape, producing a mismatched mask.
try:
    _TAB6_V13_CONFIRM_ROI2_BASE = CDIWorkflowApp.confirm_roi2
except Exception:
    _TAB6_V13_CONFIRM_ROI2_BASE = None

if _TAB6_V13_CONFIRM_ROI2_BASE is not None:
    def _tab6_v13_confirm_roi2(self):
        if not getattr(self, '_tab6_analysis_rotation_committed', False):
            return _TAB6_V13_CONFIRM_ROI2_BASE(self)
        if self.recons is None:
            messagebox.showwarning('Secondary ROI', 'Load reconstructions first.', parent=self.root)
            return
        if self.roi2_coords is None:
            messagebox.showwarning('Secondary ROI', 'Drag a rectangle on the processed image first.', parent=self.root)
            return
        self._roi2_stop_playback()
        idx = max(0, min(int(self.roi2_idx_var.get()), len(self.recons) - 1))
        try:
            reference = self._roi2_source_image(idx)
        except Exception as exc:
            messagebox.showerror('Secondary ROI', str(exc), parent=self.root)
            return
        h, w = reference.shape[:2]
        x0 = max(0, min(int(self.roi2_coords['xmin']), w - 1))
        x1 = max(0, min(int(self.roi2_coords['xmax']), w - 1))
        y0 = max(0, min(int(self.roi2_coords['ymin']), h - 1))
        y1 = max(0, min(int(self.roi2_coords['ymax']), h - 1))
        if x1 <= x0 or y1 <= y0:
            messagebox.showerror('Secondary ROI', 'Selected ROI is too small.', parent=self.root)
            return

        # Use the rotated/cropped Tab-6 active mask, not the pre-rotation mask.
        analysis_mask = getattr(self, '_tab6_finalized_mask', None)
        if analysis_mask is None:
            dm = getattr(self, '_tab6_display_mask', None)
            if dm is not None:
                analysis_mask = np.asarray(dm, dtype=bool)
        if analysis_mask is not None:
            analysis_mask = np.asarray(analysis_mask, dtype=bool)
            if analysis_mask.shape != (h, w):
                analysis_mask = None

        mask = np.zeros((h, w), dtype=bool)
        mask[y0:y1 + 1, x0:x1 + 1] = True
        if analysis_mask is not None:
            mask &= analysis_mask
        if not np.any(mask):
            messagebox.showerror('Secondary ROI', 'Selected ROI contains no valid active pixels.', parent=self.root)
            return

        self.roi2_mask = mask
        self.roi2_coords = {'xmin': x0, 'xmax': x1, 'ymin': y0, 'ymax': y1}
        self.roi2_confirmed_coords = dict(self.roi2_coords)
        self.roi2_stack = np.zeros((len(self.recons), y1-y0+1, x1-x0+1), dtype=_intensity_dtype(self))
        local_mask = mask[y0:y1+1, x0:x1+1]
        for i in range(len(self.recons)):
            img = np.asarray(self._roi2_source_image(i), dtype=_intensity_dtype(self))
            crop = img[y0:y1+1, x0:x1+1].copy()
            crop[~local_mask] = 0.0
            self.roi2_stack[i] = crop

        self.roi2_status_var.set(
            f'✓ SECONDARY ROI CONFIRMED | X={x0}:{x1} | Y={y0}:{y1} | '
            f'{x1-x0+1} × {y1-y0+1} px | {len(self.recons)} frames | '
            'TAB-6 ROTATED COORDINATES'
        )
        self.log(f'Tab-6 rotated Secondary ROI confirmed: X={x0}:{x1}, Y={y0}:{y1}, size={x1-x0+1}x{y1-y0+1}')
        self._roi2_sync_controls()
        self.roi2_idx_var.set(max(0, min(int(self.proc_idx_var.get()), len(self.roi2_stack)-1)) if hasattr(self, 'proc_idx_var') else 0)
        self.update_roi2_view()
        try:
            sync = getattr(self, '_pd_sync_secondary_roi', None)
            if callable(sync):
                sync()
        except Exception:
            pass

    CDIWorkflowApp.confirm_roi2 = _tab6_v13_confirm_roi2

# Rebuild any exact primary stack request using the same frozen SET-frame crop.
def _tab6_v13_build_primary_stack(self):
    try:
        base_builder = globals().get('_TAB6_V8_ORIGINAL_STACK_BUILDER', None)
        if not callable(base_builder):
            return None
        base_stack = np.asarray(base_builder(self), dtype=_intensity_dtype(self))
    except Exception:
        return None
    if not getattr(self, '_tab6_analysis_rotation_committed', False):
        return base_stack.copy()
    angle = float(getattr(self, '_tab6_analysis_rotation_angle', 0.0))
    bbox = getattr(self, '_tab6_analysis_display_bbox', None)
    if bbox is None:
        return base_stack.copy()
    frames = []
    for frame in base_stack:
        rot = _tab6_final_rotate_array(self, frame, angle=angle, order=1).astype(_intensity_dtype(self))
        frames.append(_tab6_v13_crop_fixed(self, rot, bbox, fill=0.0))
    result = np.stack(frames, axis=0).astype(_intensity_dtype(self), copy=False)
    self._tab6_signed_final_stack = result
    self._tab6_signed_stack_signature = None
    return result


CDIWorkflowApp._tab6_build_exact_processed_primary_stack = _tab6_v13_build_primary_stack
globals()['_tab6_build_exact_processed_primary_stack'] = _tab6_v13_build_primary_stack


# FINAL GUI STARTUP — all class patches and Tab-6 handoff patches must be installed first.

# ============================================================================
# FINAL TAB 6 SIGNED-ANGLE ROTATION FIX
# ============================================================================
# This is the LAST Tab-6 rotation patch.  It intentionally overrides the
# earlier compatibility layers because one earlier display function converted
# signed angles with "% 360", turning -60° into +300°.  The authoritative
# control is now strictly -180° .. +180° in 1° steps.
#
# IMPORTANT:
#   +angle = counter-clockwise
#   -angle = clockwise
#   SET     = freeze the selected angle and make the same rotated/cropped
#             coordinate system authoritative for Tabs 7–11
#   RELEASE = unlock the control but keep the last SET angle for Tabs 7–11
#   RESET   = 0°, original orientation, unlock and clear finalized handoff
# ============================================================================

def _tab6_signed_angle_value(self, value=None):
    try:
        raw = float(self.tab6_rotation_angle_var.get() if value is None else value)
    except Exception:
        raw = 0.0
    raw = max(-180.0, min(180.0, raw))
    return float(round(raw))

def _tab6_signed_rotate_and_crop(self, image, mask=None, angle=None, order=1,
                                 fixed_bbox=None):
    """Rotate an unrotated image with a SIGNED angle and crop to active edge."""
    arr = np.asarray(image)
    if arr.ndim < 2:
        return arr.copy(), None, (0, arr.shape[1] if arr.ndim else 0,
                                  0, arr.shape[0] if arr.ndim else 0)

    if angle is None:
        angle = getattr(self, '_tab6_rotation_angle', 0.0)
    try:
        angle = max(-180.0, min(180.0, float(angle)))
    except Exception:
        angle = 0.0

    rotated = _tab6_final_rotate_array(self, arr, angle=angle, order=order)

    rotated_mask = None
    if mask is not None:
        try:
            m = np.asarray(mask, dtype=bool)
            if m.shape == arr.shape[:2]:
                rotated_mask = _tab6_final_rotate_array(
                    self, m.astype(_intensity_dtype(self)), angle=angle, order=0
                ) > 0.5
        except Exception:
            rotated_mask = None

    bbox = fixed_bbox
    if bbox is None:
        bbox = _tab6_final_active_bbox(self, rotated, rotated_mask)

    x0, x1, y0, y1 = [int(v) for v in bbox]
    x0 = max(0, min(x0, rotated.shape[1]))
    x1 = max(x0, min(x1, rotated.shape[1]))
    y0 = max(0, min(y0, rotated.shape[0]))
    y1 = max(y0, min(y1, rotated.shape[0]))

    cropped = rotated[y0:y1, x0:x1]
    if cropped.size == 0:
        x0, x1, y0, y1 = 0, rotated.shape[1], 0, rotated.shape[0]
        cropped = rotated

    cropped_mask = None
    if rotated_mask is not None:
        cropped_mask = rotated_mask[y0:y1, x0:x1].copy()

    return cropped, cropped_mask, (x0, x1, y0, y1)



def _tab6_signed_display_apply(self, reset_zoom=True):
    """Display the selected SIGNED angle without modulo conversion."""
    im = getattr(self, '_proc_image_display', None)
    ax = getattr(self, '_proc_ax', None)
    canvas = getattr(self, '_proc_canvas', None)
    if im is None or ax is None:
        return

    try:
        angle = float(getattr(self, '_tab6_rotation_angle', 0.0))
    except Exception:
        angle = 0.0
    angle = max(-180.0, min(180.0, angle))

    if not getattr(self, '_tab6_rotation_enabled', True):
        angle = 0.0

    # Always start from the unrotated source.
    base = getattr(self, '_tab6_base_display_array', None)
    if base is None:
        base = np.asarray(im.get_array()).copy()
        self._tab6_base_display_array = base.copy()
    base = np.asarray(base)

    base_mask = getattr(self, '_tab6_base_mask', None)
    if base_mask is None:
        try:
            lm = getattr(self, 'local_mask', None)
            base_mask = None if lm is None else np.asarray(lm, dtype=bool).copy()
        except Exception:
            base_mask = None
        self._tab6_base_mask = base_mask

    cropped, cropped_mask, bbox = _tab6_signed_rotate_and_crop(
        self, base, mask=base_mask, angle=angle, order=1
    )

    # The same transformed/cropped image is the Tab-6 processing image.
    base_processed = getattr(self, '_tab6_base_current_processed', None)
    if base_processed is not None:
        try:
            p = np.asarray(base_processed)
            pcropped, _, _ = _tab6_signed_rotate_and_crop(
                self, p, mask=base_mask, angle=angle, order=1,
                fixed_bbox=bbox
            )
            self.current_processed = pcropped.astype(_intensity_dtype(self), copy=True)
        except Exception:
            pass

    # Keep transformed mask and geometry available to all downstream tabs.
    try:
        full_rot_mask = None
        if base_mask is not None:
            full_rot_mask = _tab6_final_rotate_array(
                self, np.asarray(base_mask, dtype=_intensity_dtype(self)),
                angle=angle, order=0
            ) > 0.5
        self._tab6_rotated_mask_cache = full_rot_mask
    except Exception:
        self._tab6_rotated_mask_cache = None

    self._tab6_display_mask = None if cropped_mask is None else cropped_mask.copy()
    self._proc_display_shape = tuple(cropped.shape[:2])

    # Calibrated physical sampling remains tied to the original calibrated
    # pixel size. Rotation changes orientation, not the underlying calibration.
    try:
        base_nm = float(self._proc_get_tab5_base_pixel_size())
    except Exception:
        base_nm = float('nan')

    try:
        rw, rh = getattr(self, 'roi_resolution', (0, 0))
        ow = int(getattr(self, 'original_roi_w', 0) or 0)
        oh = int(getattr(self, 'original_roi_h', 0) or 0)
        rw, rh = int(rw or 0), int(rh or 0)

        if np.isfinite(base_nm) and base_nm > 0 and rw > 0 and rh > 0 and ow > 0 and oh > 0:
            sx = base_nm * ow / rw
            sy = base_nm * oh / rh
        elif np.isfinite(base_nm) and base_nm > 0:
            sx = sy = base_nm
        else:
            sx = sy = 1.0

        # Only exact quarter-turns exchange the physical axes.
        if abs((abs(angle) % 180.0) - 90.0) < 1e-10:
            sx, sy = sy, sx
    except Exception:
        sx = sy = 1.0

    extent = (
        0.0, float(cropped.shape[1]) * sx,
        0.0, float(cropped.shape[0]) * sy
    )

    im.set_data(cropped)
    im.set_extent(extent)
    ax.set_axis_on()
    ax.set_xlabel('X (nm)')
    ax.set_ylabel('Y (nm)')
    ax.set_aspect('equal', adjustable='box')
    ax.set_anchor('C')
    ax.set_autoscale_on(False)

    # Refit only when the rotation changes.  Do not accumulate zoom limits.
    self._proc_zoom_limits = None
    self._proc_zoomed = False
    ax.set_xlim(extent[0], extent[1])
    ax.set_ylim(extent[2], extent[3])
    self._proc_full_physical_extent = extent

    try:
        sign = '+' if angle > 0 else ''
        self.tab6_rotation_scale_var.set(
            f'Display X scale = {sx:.9g} nm/px    |    Y scale = {sy:.9g} nm/px'
        )
    except Exception:
        pass

    try:
        if getattr(self, '_proc_colorbar', None) is not None:
            self._proc_colorbar.update_normal(im)
            self._proc_colorbar.set_label('Intensity')
    except Exception:
        pass

    try:
        if canvas is not None:
            canvas.draw_idle()
    except Exception:
        pass



def _tab6_signed_angle_changed_final(self, *_args):
    if getattr(self, '_tab6_rotation_locked', False):
        return
    if not getattr(self, '_tab6_rotation_enabled', True):
        return

    snapped = _tab6_signed_angle_value(self)

    self._tab6_rotation_angle = snapped

    # Write the snapped value back without triggering recursive callbacks.
    try:
        self._tab6_rotation_trace_busy_final = True
        self.tab6_rotation_angle_var.set(int(snapped))
    finally:
        self._tab6_rotation_trace_busy_final = False

    _tab6_signed_display_apply(self, reset_zoom=True)

    try:
        sign = '+' if snapped > 0 else ''
        self.tab6_rotation_status_var.set(
            f'Rotation UNLOCKED — current angle = {sign}{snapped:.0f}°'
        )
    except Exception:
        pass


def _tab6_signed_set_final(self):
    """SET freezes the signed angle and the exact rotated coordinate system."""
    snapped = _tab6_signed_angle_value(self)
    self._tab6_rotation_angle = snapped
    self._tab6_rotation_enabled = True
    self._tab6_rotation_locked = True

    try:
        self._tab6_rotation_trace_busy_final = True
        self.tab6_rotation_angle_var.set(int(snapped))
    finally:
        self._tab6_rotation_trace_busy_final = False

    # Freeze the same signed angle for Tabs 7–11.
    self._tab6_analysis_rotation_angle = snapped
    self._tab6_analysis_rotation_locked = True
    self._tab6_analysis_rotation_committed = True
    self._tab6_analysis_rotation_version = (
        int(getattr(self, '_tab6_analysis_rotation_version', 0)) + 1
    )

    _tab6_signed_display_apply(self, reset_zoom=True)

    # Rebuild the finalized current-frame handoff from the unrotated source.
    try:
        base = getattr(self, '_tab6_base_current_processed', None)
        if base is not None:
            fin, fmask, fbbox = _tab6_signed_rotate_and_crop(
                self, base,
                mask=getattr(self, '_tab6_base_mask', None),
                angle=snapped, order=1
            )
            self._tab6_finalized_processed = fin.astype(_intensity_dtype(self), copy=True)
            self._tab6_finalized_mask = (
                None if fmask is None else fmask.astype(bool, copy=True)
            )
            self._tab6_finalized_bbox = fbbox
    except Exception:
        self._tab6_finalized_processed = getattr(self, 'current_processed', None)
        self._tab6_finalized_mask = getattr(self, '_tab6_display_mask', None)

    # A Secondary ROI drawn before SET belongs to the old coordinate system.
    # Force reconfirmation so Tab 7 cannot silently use stale coordinates.
    try:
        if getattr(self, 'roi2_stack', None) is not None:
            self.roi2_stack = None
            self.roi2_confirmed_coords = None
            self.line_source_stack = None
            self.line_source_coords = None
            self.gauss2d_source_stack = None
            self.gauss2d_source_coords = None
            if hasattr(self, 'roi2_status_var'):
                self.roi2_status_var.set(
                    'Rotation finalized. Reconfirm Secondary ROI in the rotated Tab-6 image.'
                )
    except Exception:
        pass

    try:
        self._tab6_v8_finalized_stack_signature = None
        self._tab8_last_ready_signature = None
        self._tab9_last_source_signature = None
    except Exception:
        pass

    try:
        self.tab6_rotation_spin.configure(state='disabled')
    except Exception:
        pass

    try:
        sign = '+' if snapped > 0 else ''
        self.tab6_rotation_status_var.set(
            f'Rotation LOCKED at {sign}{snapped:.0f}° — finalized for Tabs 7–11.'
        )
    except Exception:
        pass



def _tab6_signed_release_final(self):
    """RELEASE unlocks editing; downstream analysis keeps the last SET angle."""
    self._tab6_rotation_locked = False
    self._tab6_rotation_enabled = True

    try:
        self.tab6_rotation_spin.configure(state='normal')
    except Exception:
        pass

    try:
        current = float(self._tab6_rotation_angle)
        sign = '+' if current > 0 else ''
        self.tab6_rotation_status_var.set(
            f'Rotation UNLOCKED — current angle = {sign}{current:.0f}°. '
            'Tabs 7–11 keep the last SET angle until SET is pressed again.'
        )
    except Exception:
        pass


def _tab6_signed_reset_final(self):
    """RESET = original 0° orientation, unlock, clear finalized handoff."""
    self._tab6_rotation_locked = False
    self._tab6_rotation_enabled = True
    self._tab6_rotation_angle = 0.0

    self._tab6_analysis_rotation_angle = 0.0
    self._tab6_analysis_rotation_locked = False
    self._tab6_analysis_rotation_committed = False
    self._tab6_analysis_rotation_version = (
        int(getattr(self, '_tab6_analysis_rotation_version', 0)) + 1
    )
    self._tab6_finalized_processed = None
    self._tab6_finalized_mask = None
    self._tab6_finalized_bbox = None

    try:
        self._tab6_rotation_trace_busy_final = True
        self.tab6_rotation_angle_var.set(0)
    finally:
        self._tab6_rotation_trace_busy_final = False

    try:
        self.tab6_rotation_spin.configure(state='normal')
    except Exception:
        pass

    _tab6_signed_display_apply(self, reset_zoom=True)

    try:
        self._tab6_v8_finalized_stack_signature = None
        self._tab8_last_ready_signature = None
        self._tab9_last_source_signature = None
    except Exception:
        pass

    try:
        self.tab6_rotation_status_var.set(
            'Rotation RESET — 0° original orientation, UNLOCKED. Tabs 7–11 use 0°.'
        )
    except Exception:
        pass


def _tab6_signed_rotate_for_analysis_final(self, image, angle=None, order=1):
    """Return the exact cropped coordinate system used by Tab 6 display."""
    arr = np.asarray(image)
    if angle is None:
        angle = (
            getattr(self, '_tab6_analysis_rotation_angle', 0.0)
            if getattr(self, '_tab6_analysis_rotation_committed', False)
            else getattr(self, '_tab6_rotation_angle', 0.0)
        )
    angle = max(-180.0, min(180.0, float(angle)))

    mask = getattr(self, '_tab6_base_mask', None)
    cropped, _, _ = _tab6_signed_rotate_and_crop(
        self, arr, mask=mask, angle=angle, order=order
    )
    return np.asarray(cropped, dtype=_intensity_dtype(self))



def _tab6_signed_rotate_mask_for_analysis_final(self, mask, angle=None):
    if mask is None:
        return None
    m = np.asarray(mask, dtype=bool)
    if angle is None:
        angle = getattr(self, '_tab6_analysis_rotation_angle', 0.0)
    angle = max(-180.0, min(180.0, float(angle)))

    # Use the same crop as the image.
    dummy = np.zeros(m.shape, dtype=_intensity_dtype(self))
    _, cmask, _ = _tab6_signed_rotate_and_crop(
        self, dummy, mask=m, angle=angle, order=1
    )
    return None if cmask is None else cmask.astype(bool)



def _tab6_signed_build_primary_stack_final(self):
    """Build one fixed-size rotated primary stack for Tabs 7–11."""
    try:
        base_builder = globals().get('_TAB6_V8_ORIGINAL_STACK_BUILDER', None)
        if not callable(base_builder):
            return None
        base_stack = np.asarray(base_builder(self), dtype=_intensity_dtype(self))
    except Exception:
        return None

    locked = bool(getattr(self, '_tab6_analysis_rotation_committed', False))
    angle = float(getattr(self, '_tab6_analysis_rotation_angle', 0.0)) if locked else 0.0

    sig = (
        id(base_stack), tuple(base_stack.shape),
        'SIGNED_FINAL_ROTATION', int(getattr(self, '_tab6_analysis_rotation_version', 0)),
        round(angle, 6)
    )
    if getattr(self, '_tab6_signed_stack_signature', None) == sig:
        old = getattr(self, '_tab6_signed_final_stack', None)
        if old is not None:
            return old

    if not locked or abs(angle) < 1e-12:
        result = base_stack.copy()
    else:
        # Use one common crop for the whole stack so every frame has identical
        # dimensions.  With the workflow mask present this is the exact active
        # Primary ROI edge used by Tab 6.
        base_mask = getattr(self, '_tab6_base_mask', None)
        first = base_stack[0]
        first_rot = _tab6_final_rotate_array(self, first, angle=angle, order=1)
        first_rmask = None
        if base_mask is not None:
            try:
                first_rmask = _tab6_final_rotate_array(
                    self, np.asarray(base_mask, dtype=_intensity_dtype(self)),
                    angle=angle, order=0
                ) > 0.5
            except Exception:
                first_rmask = None
        bbox = _tab6_final_active_bbox(self, first_rot, first_rmask)

        frames = []
        for frame in base_stack:
            cf, _, _ = _tab6_signed_rotate_and_crop(
                self, frame, mask=base_mask, angle=angle, order=1,
                fixed_bbox=bbox
            )
            frames.append(cf.astype(_intensity_dtype(self), copy=False))
        result = np.stack(frames, axis=0).astype(_intensity_dtype(self), copy=False)

    self._tab6_signed_final_stack = result
    self._tab6_signed_stack_signature = sig
    return result



# Replace the display implementation with the signed-angle version.
_tab6_final_apply_rotation = _tab6_signed_display_apply
CDIWorkflowApp._tab6_apply_rotation_to_display = _tab6_signed_display_apply
CDIWorkflowApp._tab6_rotation_angle_changed = _tab6_signed_angle_changed_final
CDIWorkflowApp._tab6_rotation_set = _tab6_signed_set_final
CDIWorkflowApp._tab6_rotation_release = _tab6_signed_release_final
CDIWorkflowApp._tab6_rotation_reset = _tab6_signed_reset_final
CDIWorkflowApp._tab6_rotate_array = _tab6_final_rotate_array
CDIWorkflowApp._tab6_rotate_for_analysis = _tab6_signed_rotate_for_analysis_final
CDIWorkflowApp._tab6_build_exact_processed_primary_stack = _tab6_signed_build_primary_stack_final

# Ensure the final authoritative rotation state matches the checked UI at startup.
try:
    app._tab6_rotation_enabled = bool(app.tab6_rotation_enabled_var.get())
except Exception:
    app._tab6_rotation_enabled = True

# Remove all known old angle traces and install exactly one authoritative trace.
try:
    var = getattr(app, 'tab6_rotation_angle_var', None)
    if var is not None:
        for attr in (
            '_tab6_rotation_angle_trace_id',
            '_tab6_rotation_trace_id',
            '_tab6_rotation_trace_id_v5',
            '_tab6_rotation_trace_id_final',
        ):
            tid = getattr(app, attr, None)
            if tid:
                try:
                    var.trace_remove('write', tid)
                except Exception:
                    pass
                setattr(app, attr, None)
except Exception:
    pass

app._tab6_rotation_trace_busy_final = False

def _tab6_signed_trace_final(*_args):
    if getattr(app, '_tab6_rotation_trace_busy_final', False):
        return
    if getattr(app, '_tab6_rotation_locked', False):
        return
    try:
        _tab6_signed_angle_changed_final(app)
    except Exception as exc:
        try:
            app.log(f'Tab 6 signed-angle update error: {type(exc).__name__}: {exc}')
        except Exception:
            pass

try:
    app._tab6_rotation_trace_id_final = (
        app.tab6_rotation_angle_var.trace_add('write', _tab6_signed_trace_final)
    )
except Exception:
    app._tab6_rotation_trace_id_final = None

# Rebind Spinbox: negative values are real signed values, never modulo-wrapped.
try:
    spin = getattr(app, 'tab6_rotation_spin', None)
    if spin is not None:
        spin.configure(
            from_=-180, to=180, increment=1,
            command=lambda: _tab6_signed_angle_changed_final(app)
        )
        spin.bind(
            '<Return>',
            lambda e: (_tab6_signed_angle_changed_final(app), 'break')[1],
            add='+'
        )
        spin.bind(
            '<FocusOut>',
            lambda e: (_tab6_signed_angle_changed_final(app), 'break')[1],
            add='+'
        )
except Exception:
    pass

# Make the finalized rotated/cropped ROI2 source identical to the Tab-6 image.
try:
    _TAB6_SIGNED_ORIGINAL_ROI2_SOURCE = globals().get(
        '_TAB6_V8_ORIGINAL_ROI2_SOURCE', None
    )
except Exception:
    _TAB6_SIGNED_ORIGINAL_ROI2_SOURCE = None

if callable(_TAB6_SIGNED_ORIGINAL_ROI2_SOURCE):
    def _tab6_signed_roi2_source_image(self, idx):
        base = np.asarray(_TAB6_SIGNED_ORIGINAL_ROI2_SOURCE(self, idx), dtype=float)
        if getattr(self, '_tab6_analysis_rotation_committed', False):
            return _tab6_signed_rotate_for_analysis_final(
                self, base,
                angle=getattr(self, '_tab6_analysis_rotation_angle', 0.0),
                order=1
            )
        return base
    CDIWorkflowApp._roi2_source_image = _tab6_signed_roi2_source_image

# Force the finalized stack method into every downstream stack request.
globals()['_tab6_build_exact_processed_primary_stack'] = _tab6_signed_build_primary_stack_final

# Final initial state.
app._tab6_rotation_enabled = True
if not hasattr(app, '_tab6_rotation_locked'):
    app._tab6_rotation_locked = False
if not hasattr(app, '_tab6_rotation_angle'):
    app._tab6_rotation_angle = 0.0
if not hasattr(app, '_tab6_analysis_rotation_angle'):
    app._tab6_analysis_rotation_angle = 0.0
if not hasattr(app, '_tab6_analysis_rotation_committed'):
    app._tab6_analysis_rotation_committed = False



# ============================================================================
# FINAL TAB-6 SECONDARY ROI SELECTION FIX
# Keep ONE authoritative Tk event path and preserve the signed-rotation handoff.
# ============================================================================
# The notebook contains older Tab-6 ROI handlers for backward compatibility.
# This final patch does not delete them; it makes the clean _t6c path the
# last active mouse transport and prevents a new selection from inheriting an
# old roi2_coords/patch.

_TAB6_FINAL_CURRENT_START = CDIWorkflowApp.start_secondary_roi_selection
_TAB6_FINAL_CURRENT_CLEAR = CDIWorkflowApp.clear_secondary_roi_from_processing
_TAB6_FINAL_CURRENT_UPDATE = CDIWorkflowApp.update_processing_view
_TAB6_FINAL_CURRENT_CONFIRM = CDIWorkflowApp.confirm_secondary_roi_from_processing


def _tab6_final_confirm_secondary_roi(self, *args, **kwargs):
    result = _TAB6_FINAL_CURRENT_CONFIRM(self, *args, **kwargs)
    try:
        if result is not False and getattr(self, 'roi2_confirmed_coords', None) is not None:
            self.proc_secondary_select_button.configure(text='SELECT / ADD ROI', state='normal')
            self._proc_canvas.get_tk_widget().configure(cursor='')
    except Exception:
        pass
    return result


def _tab6_secondary_fixed_dimensions(self):
    try:
        width_nm = float(self.proc_secondary_width_nm_var.get())
        length_nm = float(self.proc_secondary_length_nm_var.get())
        if not (np.isfinite(width_nm) and np.isfinite(length_nm) and width_nm > 0 and length_nm > 0):
            return None
        return float(width_nm), float(length_nm)
    except Exception:
        return None


def _tab6_final_start_secondary_roi(self, *args, **kwargs):
    """Start fixed-size Tab-6 Secondary ROI placement; click image to position it."""
    if self.recons is None or self.roi_mask is None:
        messagebox.showwarning(
            'Secondary ROI',
            'Confirm the Primary ROI and load the processed data first.',
            parent=self.root
        )
        return
    if not getattr(self, 'roi_resolution_applied', False):
        messagebox.showwarning(
            'Secondary ROI',
            'Apply the confirmed ROI resolution first.',
            parent=self.root
        )
        return

    dims = _tab6_secondary_fixed_dimensions(self)
    if dims is None:
        messagebox.showwarning(
            'Secondary ROI',
            'Enter valid positive ROI Width and ROI Length in nm first.',
            parent=self.root
        )
        return

    geom = self._tab6_physical_geometry()
    if geom is None:
        messagebox.showwarning(
            'Secondary ROI',
            'Cannot determine the Tab-6 physical ROI scale.',
            parent=self.root
        )
        return

    pw, ph, w, h = geom
    width_nm, length_nm = dims
    wp = max(2, int(round(width_nm * w / pw)))
    hp = max(2, int(round(length_nm * h / ph)))
    if wp >= w or hp >= h:
        messagebox.showwarning(
            'Secondary ROI',
            f'ROI size is too large. Requested {width_nm:g} × {length_nm:g} nm; available {pw:g} × {ph:g} nm.',
            parent=self.root
        )
        return

    try:
        self._roi2_stop_playback()
    except Exception:
        pass

    self.roi2_coords = None
    self.roi2_confirmed_coords = None
    try:
        self.roi2_stack = None
        self.line_source_stack = None
        self.gauss2d_source_stack = None
    except Exception:
        pass

    try:
        old_patch = getattr(self, '_proc_secondary_patch', None)
        if old_patch is not None:
            old_patch.remove()
    except Exception:
        pass
    self._proc_secondary_patch = None

    self.proc_profile_mode = False
    self._proc_secondary_roi_selecting = True
    self._proc_secondary_press_xy = None
    self._t6c_drag_mode = None
    self._t6c_drag_start = None
    self._t6c_drag_last = None
    self._tab6_secondary_fixed_shape_px = (wp, hp)

    try:
        self.proc_secondary_select_button.configure(
            text='CLICK IMAGE TO PLACE ROI', state='normal'
        )
        self.proc_secondary_status_var.set(
            f'ROI size = {wp * pw / w:.6g} × {hp * ph / h:.6g} nm. '
            'Click the processed image to place the ROI center.'
        )
        self._proc_canvas.get_tk_widget().configure(cursor='crosshair')
    except Exception:
        pass

    _t6c_install(self)
    try:
        self._proc_canvas.draw_idle()
    except Exception:
        pass


def _tab6_final_update_processing_view(self, *args, **kwargs):
    """Refresh Tab-6 without losing the clean ROI event transport."""
    result = _TAB6_FINAL_CURRENT_UPDATE(self, *args, **kwargs)

    # update_processing_view may recreate the Matplotlib canvas. Reinstall the
    # clean bindtag on the new canvas while drawing/profile mode is active.
    try:
        if (getattr(self, '_proc_secondary_roi_selecting', False)
                or getattr(self, 'proc_profile_mode', False)):
            _t6c_install(self)
    except Exception:
        pass

    # Recreate the stored ROI outline on the NEW axes after a canvas rebuild.
    try:
        if (not getattr(self, '_proc_secondary_roi_selecting', False)
                and getattr(self, 'roi2_coords', None) is not None):
            self._proc_draw_secondary_roi_patch(
                confirmed=(getattr(self, 'roi2_confirmed_coords', None) is not None),
                redraw=True
            )
    except Exception:
        pass
    return result


def _tab6_final_clear_secondary_roi(self, *args, **kwargs):
    """Clear the Tab-6 Secondary ROI and all associated display state."""
    try:
        self._t6c_uninstall()
    except Exception:
        pass
    result = _TAB6_FINAL_CURRENT_CLEAR(self, *args, **kwargs)
    try:
        self.roi2_coords = None
        self.roi2_confirmed_coords = None
        self._proc_secondary_roi_selecting = False
        self._proc_secondary_press_xy = None
        self._t6c_drag_mode = None
        self._t6c_drag_start = None
        self._t6c_drag_last = None
        self._tab6_secondary_fixed_shape_px = None
    except Exception:
        pass
    return result


# Install the final Tab-6 commands LAST. The existing confirmation method is
# intentionally preserved so the signed-angle/downstream handoff remains intact.
CDIWorkflowApp.start_secondary_roi_selection = _tab6_final_start_secondary_roi
CDIWorkflowApp.clear_secondary_roi_from_processing = _tab6_final_clear_secondary_roi
CDIWorkflowApp.update_processing_view = _tab6_final_update_processing_view
CDIWorkflowApp.confirm_secondary_roi_from_processing = _tab6_final_confirm_secondary_roi

# The Tab-6 widgets were created before this final patch block, so explicitly
# rebind their Tk commands to the final fixed-size ROI handlers.
try:
    app.proc_secondary_select_button.configure(
        command=lambda: _tab6_final_start_secondary_roi(app)
    )
    app.proc_secondary_confirm_button.configure(
        command=lambda: _tab6_final_confirm_secondary_roi(app)
    )
    app.proc_secondary_clear_button.configure(
        command=lambda: _tab6_final_clear_secondary_roi(app)
    )
except Exception:
    pass

# Reinstall the clean bindtag on the currently displayed canvas once at startup.
try:
    _t6c_install(app)
except Exception:
    pass


# ============================================================================
# FINAL ROI2 SYNCHRONIZATION PATCH
# ============================================================================
# Root cause fixed:
# Tab-6 can have the correct current selection/roi2_stack while Tab-7's
# independent display/export cache (_lpa_stack / line_source_stack) still
# contains an older confirmed ROI.  This patch makes the current confirmed
# Tab-6 ROI2 stack + geometry the single source for all Tab-7 ROI displays.
#
# It does NOT change ROI dimensions, center-click placement, rotation, line
# drawing, zoom algorithms, or any downstream analysis.  It only refreshes
# the already-confirmed ROI2 snapshot whenever confirmation/tab selection
# occurs.

def _tab6_sync_current_roi2_to_tab7(self, reset_view=True):
    stack = getattr(self, 'roi2_stack', None)
    coords = getattr(self, 'roi2_confirmed_coords', None)
    if stack is None or coords is None:
        return False
    try:
        arr = np.asarray(stack, dtype=np.float64)
        if arr.ndim != 3 or arr.shape[0] == 0:
            return False
        c = dict(coords)

        # Current confirmed Tab-6 ROI2 is authoritative.
        self.line_source_stack = arr.copy()
        self.line_source_coords = dict(c)
        self._lpa_stack = arr.copy()
        self._lpa_roi2_coords = dict(c)

        # Keep all known Tab-7 snapshot aliases synchronized.
        try:
            self._tab7_roi2_stack = arr.copy()
        except Exception:
            pass
        try:
            self._tab7_roi2_coords = dict(c)
        except Exception:
            pass

        # Preserve the exact Tab-6 physical scale.
        try:
            sc = _tab6_effective_nm_per_output_px(self)
        except Exception:
            sc = None
        if sc is None:
            try:
                v = _tab5_effective_pixel_size_final(self)
                sc = (v, v) if v is not None else (1.0, 1.0)
            except Exception:
                sc = (1.0, 1.0)
        self._tab7_fixed_nm_per_output_px = (float(sc[0]), float(sc[1]))

        try:
            idx = int(self.roi2_idx_var.get())
        except Exception:
            try:
                idx = int(self.proc_idx_var.get())
            except Exception:
                idx = 0
        idx = max(0, min(idx, arr.shape[0] - 1))

        # A newly confirmed ROI must start at the full ROI view, not at an
        # old ROI's zoom window.
        if reset_view:
            self._lpa_zoomed = False
            self._lpa_zoom_limits = None
            self._tab7_roi_zoomed = False
            self._tab7_roi_zoom_limits = None
            self._tab7_zoom_view_nm = None

        try:
            self._lpa_frame_var.set(idx)
        except Exception:
            pass
        try:
            self.line_profile_frame_var.set(idx)
        except Exception:
            pass

        # Refresh whichever Tab-7 ROI viewers exist.  Failures here must never
        # invalidate the confirmed ROI2 data itself.
        try:
            if hasattr(self, '_lpa_render_frame'):
                self._lpa_render_frame(idx, preserve_zoom=not reset_view)
        except Exception:
            pass
        try:
            if hasattr(self, '_line_profile_update_image'):
                self._line_profile_update_image(idx=idx, preserve_lines=True)
        except Exception:
            pass

        return True
    except Exception:
        return False


# Preserve the complete existing Tab-6 confirmation pipeline, then force the
# exact current confirmed ROI2 stack into every Tab-7 display/cache.
_TAB6_V19_CONFIRM_BASE = _tab6_final_confirm_secondary_roi

def _tab6_v19_confirm_secondary_roi(self, *args, **kwargs):
    result = _TAB6_V19_CONFIRM_BASE(self, *args, **kwargs)
    if result is not False:
        try:
            _tab6_sync_current_roi2_to_tab7(self, reset_view=True)
        except Exception:
            pass
    return result

CDIWorkflowApp.confirm_secondary_roi_from_processing = _tab6_v19_confirm_secondary_roi

# The Tab-6 confirm button was created earlier with a direct lambda, so rebind
# that actual widget as well.
try:
    app.proc_secondary_confirm_button.configure(
        command=lambda: _tab6_v19_confirm_secondary_roi(app)
    )
except Exception:
    pass

# When Tab-7 is selected later, always refresh from the CURRENT Tab-6
# confirmed ROI2 instead of reusing a previous _lpa_stack snapshot.
def _tab6_v19_notebook_roi2_sync(event=None):
    try:
        selected = app.nb.select()
        tab_names = {
            str(getattr(app, 'tab_line_profile', '')),
            str(getattr(app, 'tab_line_profile_analysis', '')),
        }
        if selected in tab_names:
            _tab6_sync_current_roi2_to_tab7(app, reset_view=False)
            try:
                _lpa_fetch_roi2(app, select_tab=False)
            except Exception:
                pass
    except Exception:
        pass

try:
    app.nb.bind('<<NotebookTabChanged>>', _tab6_v19_notebook_roi2_sync, add='+')
except Exception:
    pass

# Ensure the current Tab-7 plot export also uses the latest Tab-6 ROI2.
try:
    _TAB6_V19_EXPORT_BASE = _t7v2_export_plot
    @_auto_open_export
    def _tab6_v19_export_plot(self):
        _tab6_sync_current_roi2_to_tab7(self, reset_view=False)
        return _TAB6_V19_EXPORT_BASE(self)
    CDIWorkflowApp._tab7_plot_export = _tab6_v19_export_plot
except Exception:
    pass

