# ============================================================================
# TAB 6 — AUTHORITATIVE REBUILD (v21)
# ----------------------------------------------------------------------------
# Scope: Tab 6 rotation + fixed-size Secondary ROI selection/confirmation.
#
# Design:
#   1. One authoritative rotated Primary-ROI stack is built from the SAME
#      unrotated processed Primary-ROI stack used by Tab 6.
#   2. After SET, the Tab-6 display itself is taken directly from that stack.
#   3. Secondary ROI selection reads coordinates from the ACTUAL displayed
#      image extent.
#   4. Confirmation crops the SAME authoritative stack at the SAME coordinates.
#
# Therefore the green rectangle and the confirmed ROI cannot silently refer to
# two different rotated coordinate systems.
#
# Existing Tabs 1–5 and Tabs 7–14 analysis algorithms are not rewritten.
# ============================================================================

_TAB6_AUTH_BASE_STACK_BUILDER_V21 = globals().get(
    '_TAB6_V8_ORIGINAL_STACK_BUILDER', None
)
if not callable(_TAB6_AUTH_BASE_STACK_BUILDER_V21):
    _TAB6_AUTH_BASE_STACK_BUILDER_V21 = CDIWorkflowApp.__dict__.get(
        '_tab6_build_exact_processed_primary_stack', None
    )

_TAB6_AUTH_OLD_UPDATE_V21 = CDIWorkflowApp.update_processing_view
_TAB6_AUTH_OLD_SET_V21 = CDIWorkflowApp._tab6_rotation_set
_TAB6_AUTH_OLD_RELEASE_V21 = CDIWorkflowApp._tab6_rotation_release
_TAB6_AUTH_OLD_RESET_V21 = CDIWorkflowApp._tab6_rotation_reset
_TAB6_AUTH_OLD_CLEAR_V21 = CDIWorkflowApp.clear_secondary_roi_from_processing


def _tab6_auth_angle_v21(self):
    try:
        if bool(getattr(self, '_tab6_analysis_rotation_committed', False)):
            return float(getattr(self, '_tab6_analysis_rotation_angle', 0.0))
        return float(getattr(self, '_tab6_rotation_angle', 0.0))
    except Exception:
        return 0.0


def _tab6_auth_build_stack_v21(self, force=False):
    """Build the exact rotated stack that Tab 6 will display and ROI2 will use."""
    if not callable(_TAB6_AUTH_BASE_STACK_BUILDER_V21):
        return None

    try:
        base = np.asarray(
            _TAB6_AUTH_BASE_STACK_BUILDER_V21(self),
            dtype=_intensity_dtype(self)
        )
    except Exception:
        return None

    if base.ndim != 3 or base.shape[0] == 0:
        return None

    angle = max(-180.0, min(180.0, _tab6_auth_angle_v21(self)))
    committed = bool(getattr(self, '_tab6_analysis_rotation_committed', False))

    sig = (
        id(base), tuple(base.shape),
        'TAB6_AUTHORITATIVE_V21',
        bool(committed), round(angle, 8),
        int(getattr(self, '_tab6_analysis_rotation_version', 0))
    )

    if not force and getattr(self, '_tab6_auth_stack_signature_v21', None) == sig:
        old = getattr(self, '_tab6_auth_stack_v21', None)
        if old is not None:
            return old

    # No finalized rotation: exact original Tab-6 processed stack.
    if (not committed) or abs(angle) < 1e-12:
        result = base.copy()
        bbox = (0, result.shape[2], 0, result.shape[1])
    else:
        # Compute ONE common crop from the same Primary-ROI mask used by Tab 6.
        base_mask = getattr(self, '_tab6_base_mask', None)
        if base_mask is not None:
            base_mask = np.asarray(base_mask, dtype=bool)
            if base_mask.shape != base.shape[1:]:
                base_mask = None

        first_rot = _tab6_final_rotate_array(
            self, base[0], angle=angle, order=1
        )
        first_rmask = None
        if base_mask is not None:
            try:
                first_rmask = (
                    _tab6_final_rotate_array(
                        self,
                        base_mask.astype(_intensity_dtype(self)),
                        angle=angle,
                        order=0
                    ) > 0.5
                )
            except Exception:
                first_rmask = None

        bbox = _tab6_final_active_bbox(self, first_rot, first_rmask)
        x0, x1, y0, y1 = [int(v) for v in bbox]
        x0 = max(0, min(x0, first_rot.shape[1]))
        x1 = max(x0, min(x1, first_rot.shape[1]))
        y0 = max(0, min(y0, first_rot.shape[0]))
        y1 = max(y0, min(y1, first_rot.shape[0]))

        frames = []
        for frame in base:
            rot = _tab6_final_rotate_array(
                self, frame, angle=angle, order=1
            )
            cf = rot[y0:y1, x0:x1]
            frames.append(np.asarray(cf, dtype=_intensity_dtype(self)))

        result = np.stack(frames, axis=0).astype(_intensity_dtype(self), copy=False)

    self._tab6_auth_stack_v21 = result
    self._tab6_auth_stack_signature_v21 = sig
    self._tab6_auth_bbox_v21 = bbox
    return result



def _tab6_auth_display_stack_frame_v21(self, idx=None):
    """Put the authoritative stack frame directly into the existing Tab-6 axes."""
    stack = _tab6_auth_build_stack_v21(self)
    if stack is None:
        return False

    n, h, w = stack.shape
    try:
        idx = int(self.proc_idx_var.get()) if idx is None else int(idx)
    except Exception:
        idx = int(getattr(self, 'current_index', 0) or 0)
    idx = max(0, min(idx, n - 1))

    im = getattr(self, '_proc_image_display', None)
    ax = getattr(self, '_proc_ax', None)
    canvas = getattr(self, '_proc_canvas', None)
    if im is None or ax is None:
        return False

    # Get the calibrated scale from the EXISTING Tab-6 display convention.
    try:
        base_nm = float(self._proc_get_tab5_base_pixel_size())
    except Exception:
        base_nm = np.nan

    try:
        original_w = int(getattr(self, 'original_roi_w', 0) or 0)
        original_h = int(getattr(self, 'original_roi_h', 0) or 0)
    except Exception:
        original_w = original_h = 0

    if np.isfinite(base_nm) and base_nm > 0 and original_w > 0 and original_h > 0:
        sx = float(original_w) * base_nm / float(w)
        sy = float(original_h) * base_nm / float(h)
        angle = abs(_tab6_auth_angle_v21(self))
        if abs((angle % 180.0) - 90.0) < 1e-10:
            sx, sy = sy, sx
    else:
        # Preserve the current displayed physical scale when calibration
        # metadata are unavailable.
        try:
            ex = tuple(map(float, im.get_extent()))
            sx = abs(ex[1] - ex[0]) / max(1, np.asarray(im.get_array()).shape[1])
            sy = abs(ex[3] - ex[2]) / max(1, np.asarray(im.get_array()).shape[0])
        except Exception:
            sx = sy = 1.0

    extent = (0.0, float(w) * sx, 0.0, float(h) * sy)

    im.set_data(stack[idx])
    im.set_extent(extent)
    ax.set_xlim(extent[0], extent[1])
    ax.set_ylim(extent[2], extent[3])
    ax.set_aspect('equal', adjustable='box')
    ax.set_autoscale_on(False)
    self._proc_full_physical_extent = extent
    self._proc_display_shape = (h, w)
    self.current_processed = np.asarray(stack[idx], dtype=_intensity_dtype(self)).copy()

    try:
        self._tab6_display_mask = None
    except Exception:
        pass

    try:
        if getattr(self, '_proc_colorbar', None) is not None:
            self._proc_colorbar.update_normal(im)
            self._proc_colorbar.set_label('Intensity')
    except Exception:
        pass

    try:
        if canvas is not None:
            canvas.draw_idle()
    except Exception:
        pass
    return True



def _tab6_auth_update_processing_view_v21(self, *args, **kwargs):
    # Let the existing processing/view machinery run first.
    result = _TAB6_AUTH_OLD_UPDATE_V21(self, *args, **kwargs)

    # Once SET has committed the rotation, immediately replace the displayed
    # frame with the exact common-stack frame used for Secondary ROI confirmation.
    try:
        if bool(getattr(self, '_tab6_analysis_rotation_committed', False)):
            _tab6_auth_display_stack_frame_v21(self)
    except Exception as exc:
        try:
            self.log(
                f'Tab-6 authoritative rotated display warning: '
                f'{type(exc).__name__}: {exc}'
            )
        except Exception:
            pass

    try:
        if (
            getattr(self, '_proc_secondary_roi_selecting', False)
            or getattr(self, 'proc_profile_mode', False)
        ):
            _t6c_install(self)
    except Exception:
        pass

    return result


def _tab6_auth_set_v21(self, *args, **kwargs):
    # Capture the physical coordinate system that the user is looking at
    # immediately BEFORE SET changes/rotates the display.  SET must never
    # silently replace this with Tab-5's raw nm/px or the pre-resample ROI
    # dimensions, because Tab 6 may already be resized to (e.g.) 483x512.
    try:
        im0 = getattr(self, '_proc_image_display', None)
        if im0 is not None and im0.get_array() is not None:
            a0 = np.asarray(im0.get_array())
            ex0 = tuple(map(float, im0.get_extent()))
            h0, w0 = a0.shape[:2]
            if w0 > 0 and h0 > 0 and len(ex0) == 4:
                sx0 = abs(ex0[1] - ex0[0]) / float(w0)
                sy0 = abs(ex0[3] - ex0[2]) / float(h0)
                if np.isfinite(sx0) and np.isfinite(sy0) and sx0 > 0 and sy0 > 0:
                    self._tab6_preserved_pre_set_scale = (float(sx0), float(sy0))
                    self._tab6_preserved_pre_set_fov = (
                        abs(ex0[1] - ex0[0]), abs(ex0[3] - ex0[2])
                    )
    except Exception:
        pass

    # Existing SET handles UI state, signed angle and downstream lock state.
    result = _TAB6_AUTH_OLD_SET_V21(self, *args, **kwargs)

    try:
        # Invalidate everything derived from the previous coordinate system.
        self._tab6_auth_stack_signature_v21 = None
        self._tab6_auth_stack_v21 = None

        # Build the exact stack FIRST, then make that same stack the display.
        stack = _tab6_auth_build_stack_v21(self, force=True)
        if stack is not None:
            self._tab6_auth_display_stack_frame_v21 = _tab6_auth_display_stack_frame_v21
            _tab6_auth_display_stack_frame_v21(self)

        # A previously selected ROI belongs to the previous coordinate system.
        self.roi2_coords = None
        self.roi2_confirmed_coords = None
        self.roi2_stack = None
        self.roi2_mask = None
        self.line_source_stack = None
        self.line_source_coords = None
        self.gauss2d_source_stack = None
        self.gauss2d_source_coords = None

        try:
            p = getattr(self, '_proc_secondary_patch', None)
            if p is not None:
                p.remove()
        except Exception:
            pass
        self._proc_secondary_patch = None

        self.proc_secondary_status_var.set(
            'Rotation SET. Enter ROI Width/Length, click SELECT / ADD ROI, '
            'then click the displayed image center.'
        )
    except Exception as exc:
        try:
            self.log(
                f'Tab-6 authoritative SET warning: {type(exc).__name__}: {exc}'
            )
        except Exception:
            pass

    return result


def _tab6_auth_release_v21(self, *args, **kwargs):
    result = _TAB6_AUTH_OLD_RELEASE_V21(self, *args, **kwargs)
    # RELEASE changes the editable angle only; the last SET coordinate system
    # remains authoritative until another SET.
    try:
        if getattr(self, '_tab6_analysis_rotation_committed', False):
            _tab6_auth_display_stack_frame_v21(self)
    except Exception:
        pass
    return result


def _tab6_auth_reset_v21(self, *args, **kwargs):
    result = _TAB6_AUTH_OLD_RESET_V21(self, *args, **kwargs)
    try:
        self._tab6_auth_stack_signature_v21 = None
        self._tab6_auth_stack_v21 = None
        # At 0° the existing update path is authoritative again.
    except Exception:
        pass
    return result


def _tab6_auth_start_secondary_roi_v21(self, *args, **kwargs):
    """Start fixed-size center-click Secondary ROI placement."""
    if getattr(self, 'recons', None) is None or getattr(self, 'roi_mask', None) is None:
        messagebox.showwarning(
            'Secondary ROI',
            'Confirm the Primary ROI and load the processed data first.',
            parent=self.root
        )
        return
    if not getattr(self, 'roi_resolution_applied', False):
        messagebox.showwarning(
            'Secondary ROI',
            'Apply the confirmed ROI resolution first.',
            parent=self.root
        )
        return

    try:
        width_nm = float(self.proc_secondary_width_nm_var.get())
        length_nm = float(self.proc_secondary_length_nm_var.get())
    except Exception:
        width_nm = length_nm = np.nan

    # A non-zero rotation must be SET before a Secondary ROI is selected.
    # This makes the displayed coordinate system and downstream ROI coordinate
    # system immutable and identical.
    try:
        current_angle = float(getattr(self, '_tab6_rotation_angle', 0.0))
    except Exception:
        current_angle = 0.0
    if abs(current_angle) > 1e-12 and not bool(
        getattr(self, '_tab6_analysis_rotation_committed', False)
    ):
        messagebox.showwarning(
            'Secondary ROI',
            'Press SET to finalize the current rotation before selecting '
            'the Secondary ROI.',
            parent=self.root
        )
        return

    # FREE-DRAW is enabled ONLY when BOTH ROI size boxes are empty.
    # If either box contains a value, keep the existing fixed-size ROI path.
    try:
        width_text = str(self.proc_secondary_width_nm_var.get()).strip()
    except Exception:
        width_text = ''
    try:
        length_text = str(self.proc_secondary_length_nm_var.get()).strip()
    except Exception:
        length_text = ''

    free_draw = (width_text == '' and length_text == '')
    self._tab6_secondary_free_draw_v21 = bool(free_draw)

    if not free_draw and (
        not np.isfinite(width_nm) or not np.isfinite(length_nm)
        or width_nm <= 0 or length_nm <= 0
    ):
        messagebox.showwarning(
            'Secondary ROI',
            'Enter valid positive ROI Width and ROI Length in nm, '
            'or leave BOTH boxes empty to use Free Draw.',
            parent=self.root
        )
        self._tab6_secondary_free_draw_v21 = False
        return

    im = getattr(self, '_proc_image_display', None)
    ax = getattr(self, '_proc_ax', None)
    if im is None or ax is None or im.get_array() is None:
        messagebox.showwarning(
            'Secondary ROI',
            'The Tab-6 processed Primary ROI image is not available.',
            parent=self.root
        )
        return

    arr = np.asarray(im.get_array())
    if arr.ndim != 2:
        messagebox.showwarning(
            'Secondary ROI',
            'The Tab-6 processed Primary ROI image is not 2-D.',
            parent=self.root
        )
        return

    try:
        ex = tuple(map(float, im.get_extent()))
        px_nm = abs(ex[1] - ex[0]) / float(arr.shape[1])
        py_nm = abs(ex[3] - ex[2]) / float(arr.shape[0])
    except Exception:
        messagebox.showwarning(
            'Secondary ROI',
            'Cannot determine the displayed Tab-6 physical scale.',
            parent=self.root
        )
        return

    if free_draw:
        wp = hp = None
    else:
        wp = max(2, int(round(width_nm / px_nm)))
        hp = max(2, int(round(length_nm / py_nm)))

        if wp >= arr.shape[1] or hp >= arr.shape[0]:
            messagebox.showwarning(
                'Secondary ROI',
                f'ROI size {width_nm:g} × {length_nm:g} nm is larger than the '
                f'displayed Primary ROI.',
                parent=self.root
            )
            self._tab6_secondary_free_draw_v21 = False
            return

    try:
        self._roi2_stop_playback()
    except Exception:
        pass

    self.roi2_coords = None
    self.roi2_confirmed_coords = None
    self.roi2_stack = None
    self.roi2_mask = None
    self.line_source_stack = None
    self.line_source_coords = None

    try:
        p = getattr(self, '_proc_secondary_patch', None)
        if p is not None:
            p.remove()
    except Exception:
        pass
    self._proc_secondary_patch = None

    self.proc_profile_mode = False
    self._proc_secondary_roi_selecting = True
    self._tab6_secondary_fixed_shape_px = None if free_draw else (wp, hp)
    self._tab6_secondary_display_scale_v21 = (px_nm, py_nm)
    self._tab6_secondary_requested_size_v21 = (
        None if free_draw else (width_nm, length_nm)
    )
    self._tab6_secondary_draw_start_nm_v21 = None

    try:
        self.proc_secondary_select_button.configure(
            text='DRAW ROI' if free_draw else 'CLICK IMAGE TO PLACE ROI',
            state='normal'
        )
        if free_draw:
            self.proc_secondary_status_var.set(
                'FREE DRAW: click and drag on the displayed Primary ROI '
                'to draw the Secondary ROI, then release.'
            )
        else:
            self.proc_secondary_status_var.set(
                f'ROI size = {wp * px_nm:.6g} × {hp * py_nm:.6g} nm. '
                'Click anywhere on the displayed Primary ROI to set the ROI center.'
            )
        self._proc_canvas.get_tk_widget().configure(cursor='crosshair')
    except Exception:
        pass

    _tab6_auth_install_mouse_v21(self)
    try:
        self._proc_canvas.draw_idle()
    except Exception:
        pass


def _tab6_auth_canvas_press_v21(self, event):
    if event is None or getattr(event, 'num', None) != 1:
        return

    if not getattr(self, '_proc_secondary_roi_selecting', False):
        # Preserve the existing Tab-6 line-profile mouse behavior.
        try:
            _t6c_canvas_press(self, event)
        except Exception:
            pass
        return

    if not _t6c_canvas_event_inside_axes(self, event):
        return

    xy = _t6c_canvas_xy_to_data(self, event)
    if xy is None:
        return

    im = getattr(self, '_proc_image_display', None)
    if im is None or im.get_array() is None:
        return

    arr = np.asarray(im.get_array())
    h, w = arr.shape[:2]
    try:
        ex = tuple(map(float, im.get_extent()))
        xlo, xhi = sorted((ex[0], ex[1]))
        ylo, yhi = sorted((ex[2], ex[3]))
        px_nm = (xhi - xlo) / float(w)
        py_nm = (yhi - ylo) / float(h)
    except Exception:
        return

    # Free-draw path: record the first corner and let motion/release
    # determine the final rectangle. This branch is reachable only when
    # BOTH ROI size boxes were empty at SELECT time.
    if bool(getattr(self, '_tab6_secondary_free_draw_v21', False)):
        self._tab6_secondary_draw_start_nm_v21 = (float(xy[0]), float(xy[1]))
        self._tab6_secondary_draw_start_px_v21 = (
            (float(xy[0]) - xlo) / px_nm,
            (float(xy[1]) - ylo) / py_nm
        )
        return

    dims = getattr(self, '_tab6_secondary_fixed_shape_px', None)
    if not dims:
        return
    wp, hp = map(int, dims)

    # event data are already in the displayed physical coordinate system.
    cx_nm = float(xy[0])
    cy_nm = float(xy[1])

    cx_px = (cx_nm - xlo) / px_nm
    cy_px = (cy_nm - ylo) / py_nm

    # A fixed-size ROI must remain inside the displayed Primary ROI. For clicks
    # sufficiently far from an edge, the clicked point is the exact geometric
    # center. Near an edge we report the constraint instead of silently moving
    # the ROI away from the click.
    half_w = wp / 2.0
    half_h = hp / 2.0
    if (
        cx_px < half_w or cx_px > (w - half_w)
        or cy_px < half_h or cy_px > (h - half_h)
    ):
        self.proc_secondary_status_var.set(
            'Click is too close to the Primary ROI edge for the requested '
            'fixed-size ROI. Choose a point farther inside.'
        )
        return

    xmin = int(round(cx_px - half_w))
    ymin = int(round(cy_px - half_h))
    xmax = xmin + wp - 1
    ymax = ymin + hp - 1

    self.roi2_coords = {
        'xmin': int(xmin), 'xmax': int(xmax),
        'ymin': int(ymin), 'ymax': int(ymax)
    }
    self.roi2_confirmed_coords = None

    # Store the actual clicked center for display/diagnostics.
    self._tab6_secondary_center_nm_v21 = (cx_nm, cy_nm)
    self._tab6_secondary_center_px_v21 = (cx_px, cy_px)

    # Visual rectangle is centered on the EXACT clicked physical point.
    patch_x = cx_nm - (wp * px_nm) / 2.0
    patch_y = cy_nm - (hp * py_nm) / 2.0
    try:
        old = getattr(self, '_proc_secondary_patch', None)
        if old is not None:
            old.remove()
    except Exception:
        pass

    self._proc_secondary_patch = plt.Rectangle(
        (patch_x, patch_y),
        wp * px_nm, hp * py_nm,
        fill=False, edgecolor='red', linewidth=2.5, zorder=100
    )
    self._proc_ax.add_patch(self._proc_secondary_patch)

    self._proc_secondary_roi_selecting = False
    try:
        _tab6_auth_remove_mouse_v21(self)
    except Exception:
        pass

    try:
        self.proc_secondary_select_button.configure(
            text='SELECT / ADD ROI', state='normal'
        )
        self.proc_secondary_status_var.set(
            f'Secondary ROI selected: {wp * px_nm:.6g} × {hp * py_nm:.6g} nm | '
            f'Center = ({cx_nm:.6g}, {cy_nm:.6g}) nm. '
            'Click ✓ CONFIRM ROI.'
        )
        self._proc_canvas.get_tk_widget().configure(cursor='')
        self._proc_canvas.draw_idle()
    except Exception:
        pass



def _tab6_auth_canvas_motion_v21(self, event):
    """Update the visual free-draw rectangle while the mouse is dragged."""
    if not getattr(self, '_proc_secondary_roi_selecting', False):
        return
    if not bool(getattr(self, '_tab6_secondary_free_draw_v21', False)):
        return
    start = getattr(self, '_tab6_secondary_draw_start_nm_v21', None)
    if start is None or not _t6c_canvas_event_inside_axes(self, event):
        return
    xy = _t6c_canvas_xy_to_data(self, event)
    if xy is None:
        return

    x0, y0 = start
    x1, y1 = float(xy[0]), float(xy[1])
    try:
        old = getattr(self, '_proc_secondary_patch', None)
        if old is not None:
            old.remove()
    except Exception:
        pass

    self._proc_secondary_patch = plt.Rectangle(
        (min(x0, x1), min(y0, y1)),
        abs(x1 - x0), abs(y1 - y0),
        fill=False, edgecolor='red', linewidth=2.5, zorder=100
    )
    self._proc_ax.add_patch(self._proc_secondary_patch)
    try:
        self._proc_canvas.draw_idle()
    except Exception:
        pass


def _tab6_auth_canvas_release_v21(self, event):
    """Commit the free-drawn rectangle to the same roi2_coords structure."""
    if not getattr(self, '_proc_secondary_roi_selecting', False):
        return
    if not bool(getattr(self, '_tab6_secondary_free_draw_v21', False)):
        return
    start = getattr(self, '_tab6_secondary_draw_start_nm_v21', None)
    if start is None or not _t6c_canvas_event_inside_axes(self, event):
        return

    xy = _t6c_canvas_xy_to_data(self, event)
    if xy is None:
        return

    im = getattr(self, '_proc_image_display', None)
    if im is None or im.get_array() is None:
        return
    arr = np.asarray(im.get_array())
    h, w = arr.shape[:2]

    try:
        ex = tuple(map(float, im.get_extent()))
        xlo, xhi = sorted((ex[0], ex[1]))
        ylo, yhi = sorted((ex[2], ex[3]))
        px_nm = (xhi - xlo) / float(w)
        py_nm = (yhi - ylo) / float(h)
    except Exception:
        return

    x0_nm, y0_nm = start
    x1_nm, y1_nm = float(xy[0]), float(xy[1])
    xa, xb = sorted((x0_nm, x1_nm))
    ya, yb = sorted((y0_nm, y1_nm))

    xmin = int(np.floor((xa - xlo) / px_nm))
    xmax = int(np.ceil((xb - xlo) / px_nm) - 1)
    ymin = int(np.floor((ya - ylo) / py_nm))
    ymax = int(np.ceil((yb - ylo) / py_nm) - 1)

    xmin = max(0, min(xmin, w - 1))
    xmax = max(0, min(xmax, w - 1))
    ymin = max(0, min(ymin, h - 1))
    ymax = max(0, min(ymax, h - 1))

    if xmax <= xmin or ymax <= ymin:
        self.proc_secondary_status_var.set(
            'Free-draw ROI is too small. Drag a larger rectangle.'
        )
        return

    self.roi2_coords = {
        'xmin': int(xmin), 'xmax': int(xmax),
        'ymin': int(ymin), 'ymax': int(ymax)
    }
    self.roi2_confirmed_coords = None
    self._tab6_secondary_center_nm_v21 = (
        (x0_nm + x1_nm) / 2.0, (y0_nm + y1_nm) / 2.0
    )
    self._tab6_secondary_center_px_v21 = (
        (xmin + xmax) / 2.0, (ymin + ymax) / 2.0
    )

    try:
        old = getattr(self, '_proc_secondary_patch', None)
        if old is not None:
            old.remove()
    except Exception:
        pass
    self._proc_secondary_patch = plt.Rectangle(
        (xa, ya), xb - xa, yb - ya,
        fill=False, edgecolor='red', linewidth=2.5, zorder=100
    )
    self._proc_ax.add_patch(self._proc_secondary_patch)

    self._tab6_secondary_draw_start_nm_v21 = None
    self._proc_secondary_roi_selecting = False
    try:
        _tab6_auth_remove_mouse_v21(self)
        self.proc_secondary_select_button.configure(
            text='SELECT / ADD ROI', state='normal'
        )
        width_draw = (xmax - xmin + 1) * px_nm
        length_draw = (ymax - ymin + 1) * py_nm
        self.proc_secondary_status_var.set(
            f'Free-drawn ROI selected: {width_draw:.6g} × '
            f'{length_draw:.6g} nm | '
            f'Center = ({self._tab6_secondary_center_nm_v21[0]:.6g}, '
            f'{self._tab6_secondary_center_nm_v21[1]:.6g}) nm. '
            'Click ✓ CONFIRM ROI.'
        )
        self._proc_canvas.get_tk_widget().configure(cursor='')
        self._proc_canvas.draw_idle()
    except Exception:
        pass


def _tab6_auth_remove_mouse_v21(self):
    widget = getattr(
        getattr(self, '_proc_canvas', None),
        'get_tk_widget',
        lambda: None
    )()
    tag = getattr(self, '_tab6_auth_bindtag_v21', None)
    if widget is not None and tag:
        try:
            widget.unbind_class(tag, '<ButtonPress-1>')
            widget.unbind_class(tag, '<B1-Motion>')
            widget.unbind_class(tag, '<ButtonRelease-1>')
            widget.bindtags(tuple(t for t in widget.bindtags() if t != tag))
        except Exception:
            pass
    self._tab6_auth_bindtag_v21 = None


def _tab6_auth_install_mouse_v21(self):
    _tab6_auth_remove_mouse_v21(self)
    widget = getattr(
        getattr(self, '_proc_canvas', None),
        'get_tk_widget',
        lambda: None
    )()
    if widget is None:
        return

    tag = f'CDI_Tab6_AUTHORITATIVE_{id(self)}'
    self._tab6_auth_bindtag_v21 = tag
    try:
        tags = list(widget.bindtags())
        widget.bindtags((tag, *[t for t in tags if t != tag]))

        def press(ev):
            if _figure_navigation_active(self._proc_canvas):
                return
            _tab6_auth_canvas_press_v21(self, ev)
            return 'break'

        widget.bind_class(tag, '<ButtonPress-1>', press, add='+')

        def motion(ev):
            if _figure_navigation_active(self._proc_canvas):
                return
            _tab6_auth_canvas_motion_v21(self, ev)
            return 'break'

        def release(ev):
            if _figure_navigation_active(self._proc_canvas):
                return
            _tab6_auth_canvas_release_v21(self, ev)
            return 'break'

        widget.bind_class(tag, '<B1-Motion>', motion, add='+')
        widget.bind_class(tag, '<ButtonRelease-1>', release, add='+')
    except Exception:
        pass


def _tab6_auth_confirm_v21(self, *args, **kwargs):
    """Confirm from the exact same authoritative stack used for display."""
    coords = getattr(self, 'roi2_coords', None)
    if not isinstance(coords, dict):
        messagebox.showwarning(
            'Secondary ROI',
            'First click SELECT / ADD ROI and place the Secondary ROI on the image.',
            parent=self.root
        )
        return False

    stack = _tab6_auth_build_stack_v21(self)
    if stack is None:
        messagebox.showerror(
            'Secondary ROI',
            'The authoritative Tab-6 processed Primary ROI stack is unavailable.',
            parent=self.root
        )
        return False

    n, h, w = stack.shape
    x0 = int(coords['xmin'])
    x1 = int(coords['xmax'])
    y0 = int(coords['ymin'])
    y1 = int(coords['ymax'])

    if not (0 <= x0 <= x1 < w and 0 <= y0 <= y1 < h):
        messagebox.showerror(
            'Secondary ROI',
            'The selected ROI is outside the current displayed Primary ROI.',
            parent=self.root
        )
        return False

    crop_h = y1 - y0 + 1
    crop_w = x1 - x0 + 1

    # Use the current displayed mask only when it has the exact same shape.
    # Otherwise do not introduce a mismatched mask from the unrotated system.
    local_mask = None
    dm = getattr(self, '_tab6_display_mask', None)
    if dm is not None:
        dm = np.asarray(dm, dtype=bool)
        if dm.shape == (h, w):
            local_mask = dm[y0:y1 + 1, x0:x1 + 1].copy()

    if local_mask is None:
        local_mask = np.ones((crop_h, crop_w), dtype=bool)

    roi_mask = np.zeros((h, w), dtype=bool)
    roi_mask[y0:y1 + 1, x0:x1 + 1] = local_mask

    out = np.empty((n, crop_h, crop_w), dtype=_intensity_dtype(self))
    for i in range(n):
        crop = np.asarray(
            stack[i, y0:y1 + 1, x0:x1 + 1],
            dtype=_intensity_dtype(self)
        ).copy()
        crop[~local_mask] = 0.0
        out[i] = crop

    confirmed = {
        'xmin': x0, 'xmax': x1,
        'ymin': y0, 'ymax': y1
    }

    self.roi2_mask = roi_mask
    self.roi2_coords = dict(confirmed)
    self.roi2_confirmed_coords = dict(confirmed)
    self.roi2_stack = out

    try:
        self.roi2_idx_var.set(
            max(0, min(int(self.proc_idx_var.get()), n - 1))
        )
    except Exception:
        pass

    try:
        _tab6_auth_remove_mouse_v21(self)
        self._proc_secondary_roi_selecting = False
        self._proc_canvas.get_tk_widget().configure(cursor='')
    except Exception:
        pass

    try:
        self._proc_draw_secondary_roi_patch(confirmed=True)
    except Exception:
        pass

    try:
        self.proc_secondary_select_button.configure(
            text='SELECT / ADD ROI', state='normal'
        )
        cx = getattr(self, '_tab6_secondary_center_nm_v21', None)
        center_text = (
            f' | Center = ({cx[0]:.6g}, {cx[1]:.6g}) nm'
            if cx is not None else ''
        )
        self.proc_secondary_status_var.set(
            f'✓ ROI CONFIRMED | X={x0}:{x1}, Y={y0}:{y1} | '
            f'{crop_w} × {crop_h} px | {n} frames{center_text}'
        )
    except Exception:
        pass

    # Preserve the existing downstream handoff, but now it receives the
    # authoritative stack produced above.
    try:
        capture = globals().get('_tab7_capture_roi2')
        if callable(capture):
            capture(self)
    except Exception:
        pass
    try:
        refresh = getattr(self, '_pd7_refresh_from_confirmed_roi', None)
        if callable(refresh):
            refresh(preserve_zoom=True)
    except Exception:
        pass

    try:
        _tab6_sync_current_roi2_to_tab7(self, reset_view=True)
    except Exception:
        pass

    return True



def _tab6_auth_clear_v21(self, *args, **kwargs):
    try:
        _tab6_auth_remove_mouse_v21(self)
    except Exception:
        pass

    try:
        result = _TAB6_AUTH_OLD_CLEAR_V21(self, *args, **kwargs)
    except Exception:
        result = None

    self.roi2_coords = None
    self.roi2_confirmed_coords = None
    self.roi2_stack = None
    self.roi2_mask = None
    self.line_source_stack = None
    self.line_source_coords = None
    self.gauss2d_source_stack = None
    self.gauss2d_source_coords = None
    self._tab6_secondary_center_nm_v21 = None
    self._tab6_secondary_center_px_v21 = None
    self._tab6_secondary_fixed_shape_px = None
    self._tab6_auth_stack_signature_v21 = None

    try:
        p = getattr(self, '_proc_secondary_patch', None)
        if p is not None:
            p.remove()
    except Exception:
        pass
    self._proc_secondary_patch = None
    self._proc_secondary_roi_selecting = False
    self._tab6_secondary_free_draw_v21 = False
    self._tab6_secondary_draw_start_nm_v21 = None
    self._tab6_secondary_draw_start_px_v21 = None

    try:
        self.proc_secondary_select_button.configure(
            text='SELECT / ADD ROI', state='normal'
        )
        self.proc_secondary_status_var.set('Secondary ROI cleared.')
        self._proc_canvas.get_tk_widget().configure(cursor='')
        self._proc_canvas.draw_idle()
    except Exception:
        pass

    return result


