app._tab6_preserved_pre_set_fov = None


# ===== ORIGINAL CELL BREAK =====



# ============================================================================
# FINAL DOWNSTREAM ROI HANDOFF FIX — TAB 9 + TAB 11
# ----------------------------------------------------------------------------
# Tabs 9 and 11 must consume the SAME authoritative Primary-ROI stack that
# Tab 6 displays.  In particular:
#   * rotation disabled / 0°  -> exact unrotated Tab-6 processed ROI
#   * rotation SET             -> exact rotated + common-cropped Tab-6 ROI
#
# Do not rebuild/rotate the image independently in Tabs 9/11.
# ============================================================================

def _tab6_downstream_authoritative_primary_stack_v22(self):
    """Return Tab-6's exact displayed Primary-ROI stack and its nm/px scale."""
    # The v21 authoritative builder is installed before this patch in the
    # notebook.  It returns the original processed stack at 0° and the exact
    # rotated/common-cropped stack after SET.
    builder = globals().get('_tab6_auth_build_stack_v21')
    if callable(builder):
        stack = builder(self, force=False)
    else:
        builder = getattr(self, '_tab6_build_exact_processed_primary_stack', None)
        if not callable(builder):
            return None, None, None
        stack = builder(self)

    if stack is None:
        return None, None, None

    arr = np.asarray(stack, dtype=_intensity_dtype(self))
    if arr.ndim != 3 or arr.shape[0] < 1:
        return None, None, None

    # Prefer the actual Tab-6 displayed image extent. This is essential after
    # rotation because the output dimensions/FOV can differ from the original.
    sx = sy = np.nan
    try:
        im = getattr(self, '_proc_image_display', None)
        ia = None if im is None else im.get_array()
        if ia is not None:
            ia = np.asarray(ia)
            ex = tuple(map(float, im.get_extent()))
            if ia.ndim >= 2 and len(ex) == 4 and ia.shape[:2] == arr.shape[1:]:
                sx = abs(ex[1] - ex[0]) / float(arr.shape[2])
                sy = abs(ex[3] - ex[2]) / float(arr.shape[1])
    except Exception:
        pass

    # If Tab 6 has not refreshed its canvas yet, derive the same scale from
    # the authoritative output dimensions and Tab-5 physical calibration.
    if not (np.isfinite(sx) and np.isfinite(sy) and sx > 0 and sy > 0):
        try:
            base_nm = float(self._proc_get_tab5_base_pixel_size())
            ow = int(getattr(self, 'original_roi_w', 0) or 0)
            oh = int(getattr(self, 'original_roi_h', 0) or 0)
            if np.isfinite(base_nm) and base_nm > 0 and ow > 0 and oh > 0:
                sx = ow * base_nm / float(arr.shape[2])
                sy = oh * base_nm / float(arr.shape[1])
                angle = float(_tab6_auth_angle_v21(self)) if callable(
                    globals().get('_tab6_auth_angle_v21')
                ) else 0.0
                if abs((abs(angle) % 180.0) - 90.0) < 1e-10:
                    sx, sy = sy, sx
        except Exception:
            pass

    if not (np.isfinite(sx) and np.isfinite(sy) and sx > 0 and sy > 0):
        try:
            sx, sy = map(float, _tab6_effective_nm_per_output_px(self))
        except Exception:
            return None, None, None

    # Include rotation state + exact output geometry in the source signature.
    committed = bool(getattr(self, '_tab6_analysis_rotation_committed', False))
    angle = float(getattr(
        self, '_tab6_analysis_rotation_angle', 0.0
    )) if committed else 0.0
    version = int(getattr(self, '_tab6_analysis_rotation_version', 0))
    sig = (
        'TAB6_AUTH_PRIMARY_V22',
        getattr(self, '_roi_normalization_signature', None),
        getattr(self, '_tab6_exact_processed_primary_stack_signature', None),
        committed,
        round(angle, 8),
        version,
        tuple(arr.shape),
        round(float(sx), 12),
        round(float(sy), 12),
    )
    return arr, (float(sx), float(sy)), sig



def _tab9_fetch_tab6_authoritative_v22(self, preserve_frame=True):
    """Final Tab-9 source fetch from the authoritative Tab-6 ROI."""
    try:
        stack, scale, sig = _tab6_downstream_authoritative_primary_stack_v22(self)
        if stack is None:
            self._tab9_roi1_ready = False
            self.tab9_roi4_status_var.set(
                'TAB 9: Tab-6 Primary ROI is unavailable. Confirm Primary ROI and apply its resolution in Tab 6 first.'
            )
            return False

        n, h, w = map(int, stack.shape)
        try:
            old_idx = int(round(float(self.tab9_roi4_frame_var.get()))) if preserve_frame else 0
        except Exception:
            old_idx = 0
        old_idx = max(0, min(old_idx, n - 1))

        old_sig = getattr(self, '_tab9_last_source_signature_v22', None)
        source_changed = old_sig != sig
        if source_changed:
            old_idx = (n - 1) // 2

        self._tab9_roi1_stack = stack.copy()
        self._tab9_roi1_stack_ref = self._tab9_roi1_stack
        self._tab9_roi1_shape = (h, w)
        self._tab9_roi4_scale = tuple(scale)
        self._tab9_roi1_extent = (
            0.0, w * scale[0], 0.0, h * scale[1]
        )
        self._tab9_roi1_ready = True
        self._tab9_last_source_signature = sig
        self._tab9_last_source_signature_v22 = sig

        # A rotation/resolution change creates a new coordinate system.
        # Never silently reuse an ROI4 rectangle from the previous geometry.
        if source_changed:
            self._tab9_roi4_coords = None
            self._tab9_roi4_preview_coords = None
            self._tab9_roi4_confirmed = False
            self._tab9_roi4_stack = None
            self._tab9_roi4_stack_coords = None
            self._tab9_roi4_stack_shape = None
            try:
                _tab9_roi4_reset_tab10_handoff(self)
            except Exception:
                pass

        try:
            self._tab9_roi1_cmap = str(self.colormap_var.get() or 'gray')
        except Exception:
            self._tab9_roi1_cmap = 'gray'
        self._tab9_roi1_clim = (0.0, 1.0)

        self._tab9_roi4_programmatic = True
        try:
            self.tab9_roi4_slider.configure(
                from_=0, to=max(0, n - 1), resolution=1, state='normal'
            )
            self.tab9_roi4_start_var.set(1)
            self.tab9_roi4_end_var.set(n)
            self.tab9_roi4_frame_var.set(old_idx)
            self.tab9_roi4_slider.set(old_idx)
        finally:
            self._tab9_roi4_programmatic = False

        _tab9_roi4_show_frame(self, old_idx, preserve_zoom=True)
        try:
            self.tab9_roi4_play_button.configure(text='PLAY', state='normal')
            self.tab9_roi4_first_button.configure(state='normal')
        except Exception:
            pass

        mode = 'ROTATED' if bool(getattr(
            self, '_tab6_analysis_rotation_committed', False
        )) and abs(float(getattr(
            self, '_tab6_analysis_rotation_angle', 0.0
        ))) > 1e-12 else 'UNROTATED'

        self.tab9_roi4_status_var.set(
            f'✓ TAB 6 {mode} PRIMARY ROI FETCHED | '
            f'Frames={n} | Size={w} × {h} px | '
            f'FOV={w*scale[0]:.6g} × {h*scale[1]:.6g} nm | '
            f'Frame={old_idx+1}/{n}'
        )
        return True
    except Exception as exc:
        try:
            self.tab9_roi4_status_var.set(
                f'TAB 9 fetch failed: {type(exc).__name__}: {exc}'
            )
        except Exception:
            pass
        return False


def _tab11_fetch_primary_authoritative_v22(self, preserve_frame=True):
    """Final Tab-11 source fetch from exactly the Tab-6 displayed ROI."""
    try:
        stack, scale, sig = _tab6_downstream_authoritative_primary_stack_v22(self)
        if stack is None:
            self._tab11_primary_ready = False
            self.tab11_status_var.set(
                'No valid Tab-6 Primary ROI is available. Confirm/apply the Primary ROI in Tab 6 first.'
            )
            return False

        n, h, w = map(int, stack.shape)
        try:
            old_idx = int(self.tab11_frame_var.get()) if preserve_frame else 0
        except Exception:
            old_idx = 0
        old_idx = max(0, min(old_idx, n - 1))

        old_sig = getattr(self, '_tab11_primary_source_signature_v22', None)
        source_changed = old_sig != sig
        if source_changed:
            old_idx = (n - 1) // 2

        self._tab11_primary_stack = stack.copy()
        self._tab11_scale_nm = tuple(scale)
        self._tab11_primary_ready = True
        self._tab11_primary_extent = (
            0.0, w * scale[0], 0.0, h * scale[1]
        )
        self._tab11_primary_source_signature_v22 = sig

        # Existing Tab-11 ROIs are pixel coordinates in the old source frame.
        # Clear them whenever Tab 6 changes rotation/resolution/source geometry.
        if source_changed:
            _tab11_clear_intensity(self)
            self._tab11_rois = []
            self._tab11_centers = {}
            self._tab11_dynamic_centers = {}
            self._tab11_last_fit = None
            self._tab11_fixed_roi_rect = None
            self._tab11_fixed_roi_dims_nm = None
            self._tab11_fixed_roi_mode = False
            self._tab11_center_fixed = False
            self._tab11_auto_frame_fit = False
            try:
                old = getattr(self, '_tab11_preview_rect', None)
                if old is not None:
                    old.remove()
            except Exception:
                pass
            self._tab11_preview_rect = None
            try:
                old = getattr(self, '_tab11_fixed_roi_artist', None)
                if old is not None:
                    old.remove()
            except Exception:
                pass
            self._tab11_fixed_roi_artist = None
            try:
                _tab11_update_roi_selector(self)
            except Exception:
                pass

        try:
            self._tab11_cmap = str(self.colormap_var.get() or 'gray')
        except Exception:
            self._tab11_cmap = 'gray'
        self._tab11_view = 'Image'

        finite = np.isfinite(self._tab11_primary_stack[old_idx])
        if np.any(finite):
            lo = float(np.nanmin(self._tab11_primary_stack[old_idx][finite]))
            hi = float(np.nanmax(self._tab11_primary_stack[old_idx][finite]))
            self._tab11_clim = (lo, hi) if hi > lo else (0.0, 1.0)
        else:
            self._tab11_clim = (0.0, 1.0)

        self._tab11_programmatic = True
        try:
            self.tab11_frame_var.set(old_idx)
            self.tab11_slider.configure(
                from_=0, to=max(0, n - 1), resolution=1, state='normal'
            )
            self.tab11_slider.set(old_idx)
            self.tab11_start_spin.configure(
                from_=0, to=max(0, n - 1), increment=1
            )
            self.tab11_end_spin.configure(
                from_=0, to=max(0, n - 1), increment=1
            )
            self.tab11_start_var.set(0)
            self.tab11_end_var.set(n - 1)
        finally:
            self._tab11_programmatic = False

        mode = 'ROTATED' if bool(getattr(
            self, '_tab6_analysis_rotation_committed', False
        )) and abs(float(getattr(
            self, '_tab6_analysis_rotation_angle', 0.0
        ))) > 1e-12 else 'UNROTATED'

        self.tab11_status_var.set(
            f'✓ TAB 6 {mode} PRIMARY ROI FETCHED | '
            f'FOV={w*scale[0]:.6g} × {h*scale[1]:.6g} nm | '
            f'Frame={old_idx+1}/{n}'
        )
        _tab11_render(self, old_idx)
        _tab11_sync_intensity(self)
        _tab11_plot_intensity(self)
        return True
    except Exception as exc:
        try:
            self.tab11_status_var.set(
                f'Tab-11 Tab-6 ROI fetch failed: {type(exc).__name__}: {exc}'
            )
        except Exception:
            pass
        return False


