# ============================================================================
# TAB 9 — EXPORT IMAGES v28
# ============================================================================
# EXPORT IMAGES produces TWO SEPARATE image files for every frame:
#
#   1) Primary ROI image + GREEN ROI WINDOW MARKER + its colorbar
#   2) Selected ROI image + its colorbar
#
# The two files use the same frame, field, colormap, intensity scale and
# physical nm calibration as the Tab-9 display.
# ============================================================================

@_auto_open_export
def _tab9_roi4_export_primary_figure_v28(self, idx, dpi):
    if not getattr(self, '_tab9_roi4_confirmed', False) or \
       getattr(self, '_tab9_roi4_coords', None) is None:
        raise RuntimeError('Confirm ROI before exporting.')

    stack = np.asarray(self._tab9_roi1_stack, dtype=_intensity_dtype(self))
    idx = int(idx)
    image = stack[idx]
    h, w = image.shape[:2]

    c = self._tab9_roi4_coords
    xmin, xmax = int(c['xmin']), int(c['xmax'])
    ymin, ymax = int(c['ymin']), int(c['ymax'])
    sx, sy = map(float, self._tab9_roi4_scale)

    cmap = str(getattr(self, 'colormap_var').get() or 'gray')
    field = _tab9_roi4_field(self, idx)
    n = _tab9_roi4_frame_count(self)

    fig = plt.figure(figsize=(9.0, 7.2), dpi=int(dpi), facecolor='white')
    _intensity_tag_figure(self, fig, idx)
    ax = fig.add_axes([0.09, 0.12, 0.76, 0.78])
    cb = fig.add_axes([0.875, 0.12, 0.035, 0.78])

    im = ax.imshow(
        image, origin='lower',
        extent=(0, w*sx, 0, h*sy),
        interpolation='nearest',
        cmap=cmap, vmin=0.0, vmax=1.0, aspect='equal'
    )

    ax.add_patch(matplotlib.patches.Rectangle(
        (xmin*sx, ymin*sy),
        (xmax-xmin+1)*sx,
        (ymax-ymin+1)*sy,
        fill=False, edgecolor='lime', linewidth=2.2, zorder=1000
    ))

    ax.set_xlabel('X (nm)')
    ax.set_ylabel('Y (nm)')
    ax.set_title(
        f'PROCESSED ROI | Frame {idx+1}/{n} | Field = {field:+.2f} mT',
        fontsize=12
    )
    fig.colorbar(im, cax=cb).set_label('Intensity')
    return fig



@_auto_open_export
def _tab9_roi4_export_selected_figure_v28(self, idx, dpi):
    if not getattr(self, '_tab9_roi4_confirmed', False) or \
       getattr(self, '_tab9_roi4_coords', None) is None:
        raise RuntimeError('Confirm ROI before exporting.')

    stack = np.asarray(self._tab9_roi1_stack, dtype=_intensity_dtype(self))
    idx = int(idx)
    image = stack[idx]

    c = self._tab9_roi4_coords
    xmin, xmax = int(c['xmin']), int(c['xmax'])
    ymin, ymax = int(c['ymin']), int(c['ymax'])
    sx, sy = map(float, self._tab9_roi4_scale)

    crop = image[ymin:ymax+1, xmin:xmax+1]

    cmap = str(getattr(self, 'colormap_var').get() or 'gray')

    fig = plt.figure(figsize=(7.6, 7.2), dpi=int(dpi), facecolor='white')
    _intensity_tag_figure(self, fig, idx)
    ax = fig.add_axes([0.10, 0.12, 0.73, 0.78])
    cb = fig.add_axes([0.875, 0.12, 0.035, 0.78])

    im = ax.imshow(
        crop, origin='lower',
        extent=(0, crop.shape[1]*sx, 0, crop.shape[0]*sy),
        interpolation='nearest',
        cmap=cmap, vmin=0.0, vmax=1.0, aspect='equal'
    )

    ax.set_xlabel('X (nm)')
    ax.set_ylabel('Y (nm)')
    ax.set_title(
        f'ROI — SELECTED | '
        f'{crop.shape[1]*sx:.3f} × {crop.shape[0]*sy:.3f} nm',
        fontsize=12
    )
    fig.colorbar(im, cax=cb).set_label('Intensity')
    return fig



@_auto_open_export
def _tab9_roi4_batch_export_images_v28(self):
    """Export Primary ROI and Selected ROI as separate files per frame."""
    try:
        start, end, dpi = _tab9_roi4_get_export_range(self)

        fmt = str(self.tab9_roi4_format_var.get()).upper()
        fmt_map = {
            'PNG': ('png', '.png'),
            'JPG': ('jpg', '.jpg'),
            'TIFF': ('tiff', '.tiff')
        }
        if fmt not in fmt_map:
            raise ValueError('Image format must be PNG, JPG or TIFF.')

        mpl_fmt, extension = fmt_map[fmt]

        folder = os.path.abspath(
            os.path.expanduser(
                str(self.output_var.get()).strip()
                or self._export_initialdir()
                or 'ROI4_exports'
            )
        )
        os.makedirs(folder, exist_ok=True)

        primary_dir = os.path.join(folder, 'Primary_ROI')
        selected_dir = os.path.join(folder, 'Selected_ROI')
        os.makedirs(primary_dir, exist_ok=True)
        os.makedirs(selected_dir, exist_ok=True)

        exported = 0

        for i in range(start - 1, end):
            field = _tab9_roi4_field(self, i)
            tag = f'Frame{i+1:03d}_{field:+.2f}mT'

            fig1 = fig2 = None
            try:
                fig1 = _tab9_roi4_export_primary_figure_v28(self, i, dpi)
                _export_capture_write(fig1.savefig, os.path.join(primary_dir, f'Tab9_Primary_ROI_{tag}{extension}'), dpi=dpi, bbox_inches='tight', facecolor='white', format=mpl_fmt)

                fig2 = _tab9_roi4_export_selected_figure_v28(self, i, dpi)
                _export_capture_write(fig2.savefig, os.path.join(selected_dir, f'Tab9_Selected_ROI_{tag}{extension}'), dpi=dpi, bbox_inches='tight', facecolor='white', format=mpl_fmt)

                exported += 2
            finally:
                if fig1 is not None:
                    plt.close(fig1)
                if fig2 is not None:
                    plt.close(fig2)

        self.tab9_roi4_export_status_var.set(
            f'✓ Exported {exported} separate images | '
            f'{end-start+1} frame(s) | '
            f'Primary_ROI + Selected_ROI | {fmt} | {dpi} DPI'
        )

        _tab6_open_output_folder(folder)

    except Exception as exc:
        self.tab9_roi4_export_status_var.set(
            f'✗ Tab 9 export failed: {exc}'
        )
        _export_error_dialog(messagebox.showerror, 'Tab 9 Export Images', str(exc), parent=self.root)


