# ============================================================================
# TAB-6 FINAL SCALE FIX + REMOVE SINGLE MP4
# ----------------------------------------------------------------------------
# Root cause of the post-SET horizontal compression:
# _tab6_auth_display_stack_frame_v21() was deriving sx/sy from
# original_roi_w/original_roi_h divided by the NEW rotated/cropped pixel
# dimensions.  After rotation/cropping this changes the physical nm/px scale
# and therefore visually stretches/compresses the image.
#
# The calibrated pixel size does NOT change when an image is rotated/cropped.
# Use the original calibrated nm/px equally on both axes.  Cropping changes
# the number of pixels, not their physical size.
# ============================================================================

_TAB6_AUTH_DISPLAY_STACK_FRAME_V21_FIXED = _tab6_auth_display_stack_frame_v21

def _tab6_auth_display_stack_frame_v21_scale_fixed(self, idx=None):
    """Display the finalized Tab-6 stack without changing its physical X/Y scale.

    Critical rule: SET preserves the physical scale that was visible immediately
    before SET.  Rotation/cropping/resampling may change the pixel array shape,
    but it must NOT change the physical field of view or make the image suddenly
    expand from ~2.4 um to ~6--7 um.
    """
    stack = _tab6_auth_build_stack_v21(self)
    if stack is None:
        return False

    n, h, w = stack.shape
    try:
        idx = int(self.proc_idx_var.get()) if idx is None else int(idx)
    except Exception:
        idx = int(getattr(self, 'current_index', 0) or 0)
    idx = max(0, min(idx, n - 1))

    im = getattr(self, '_proc_image_display', None)
    ax = getattr(self, '_proc_ax', None)
    canvas = getattr(self, '_proc_canvas', None)
    if im is None or ax is None:
        return False

    # First choice: exact scale captured immediately before SET.
    scale = getattr(self, '_tab6_preserved_pre_set_scale', None)
    if scale is not None:
        try:
            sx, sy = float(scale[0]), float(scale[1])
            if not (np.isfinite(sx) and np.isfinite(sy) and sx > 0 and sy > 0):
                raise ValueError
        except Exception:
            scale = None

    # Startup / RESET / first display fallback: preserve the currently visible
    # physical scale rather than inventing a new one.
    if scale is None:
        try:
            old = np.asarray(im.get_array())
            ex = tuple(map(float, im.get_extent()))
            oh, ow = old.shape[:2]
            sx = abs(ex[1] - ex[0]) / max(1, ow)
            sy = abs(ex[3] - ex[2]) / max(1, oh)
        except Exception:
            try:
                base_nm = float(self._proc_get_tab5_base_pixel_size())
            except Exception:
                base_nm = 1.0
            sx = sy = base_nm if np.isfinite(base_nm) and base_nm > 0 else 1.0
    else:
        sx, sy = scale

    extent = (0.0, float(w) * sx, 0.0, float(h) * sy)

    im.set_data(stack[idx])
    im.set_extent(extent)
    ax.set_xlim(extent[0], extent[1])
    ax.set_ylim(extent[2], extent[3])
    ax.set_aspect('equal', adjustable='box')
    ax.set_autoscale_on(False)

    self._proc_full_physical_extent = extent
    self._proc_display_shape = (h, w)
    self.current_processed = np.asarray(stack[idx], dtype=_intensity_dtype(self)).copy()

    try:
        self._tab6_display_mask = None
    except Exception:
        pass

    try:
        if getattr(self, '_proc_colorbar', None) is not None:
            self._proc_colorbar.update_normal(im)
            self._proc_colorbar.set_label('Intensity')
    except Exception:
        pass

    try:
        self.tab6_rotation_scale_var.set(
            f'Display X scale = {sx:.9g} nm/px    |    '
            f'Y scale = {sy:.9g} nm/px    |    '
            f'FOV = {extent[1]:.6g} × {extent[3]:.6g} nm'
        )
    except Exception:
        pass

    try:
        if canvas is not None:
            canvas.draw_idle()
    except Exception:
        pass

    return True



# Replace the global function used by the authoritative SET/update wrappers.
_tab6_auth_display_stack_frame_v21 = _tab6_auth_display_stack_frame_v21_scale_fixed

