# ============================================================================
# Remove ONLY the "SINGLE MP4" Tab-6 button.
# BATCH MP4 and all PNG/JPG/TIFF export functions remain untouched.
# ============================================================================

def _tab6_remove_single_mp4_button(self):
    removed = 0

    def walk(widget):
        try:
            children = widget.winfo_children()
        except Exception:
            children = []
        for child in children:
            yield child
            yield from walk(child)

    for widget in list(walk(self.root)):
        try:
            text = str(widget.cget('text')).strip().upper()
            cls = str(widget.winfo_class())
        except Exception:
            continue

        if cls == 'TButton' and text == 'SINGLE MP4':
            try:
                widget.destroy()
                removed += 1
            except Exception:
                pass

    try:
        self.log(f'Tab-6 SINGLE MP4 removed: {removed} button(s). BATCH MP4 retained.')
    except Exception:
        pass

try:
    _tab6_remove_single_mp4_button(app)
except Exception:
    pass

