# ============================================================================
# FINAL TAB-7 EXPORT PATCH — EXPORT EXACT VISIBLE TABLE + EXACT VISIBLE PLOT
# - TABLE EXPORT: exports every row/column currently shown in the Tab-7
#   Measured distances Treeview, including summary rows such as AVG FWHM.
# - PLOT EXPORT: exports the actual live Tab-7 line-profile Matplotlib figure,
#   so every currently visible artist is included: raw profiles, Gaussian fits
#   (when enabled), M1/M2 markers, distance arrows/labels, threshold line and
#   annotation, legend, and any other annotations currently drawn on the plot.
# ============================================================================
import csv as _t7_export_csv


@_auto_open_export
def _t7_export_all_visible_table(self):
    tree = getattr(self, '_lpa_measure_tree', None)
    if tree is None:
        messagebox.showwarning('Table Export', 'Tab-7 measurement table is not available.', parent=self.root)
        return

    columns = list(tree['columns'])
    if not columns:
        messagebox.showwarning('Table Export', 'No table columns are available to export.', parent=self.root)
        return

    rows = []
    for iid in tree.get_children(''):
        rows.append(list(tree.item(iid, 'values')))

    if not rows:
        messagebox.showwarning('Table Export', 'No data points are currently shown in the Tab-7 table.', parent=self.root)
        return

    try:
        initial = self._export_initialdir()
    except Exception:
        initial = os.path.expanduser('~')

    fp = filedialog.asksaveasfilename(
        parent=self.root,
        initialdir=initial,
        title='Export Tab-7 Table — All Data Points Shown',
        defaultextension='.csv',
        filetypes=[('CSV', '*.csv'), ('All files', '*.*')]
    )
    if not fp:
        return

    try:
        with _export_capture_stream(open, fp, 'w', newline='', encoding='utf-8-sig') as f:
            writer = _t7_export_csv.writer(f)
            writer.writerow([str(tree.heading(col, 'text')) for col in columns])
            writer.writerows(rows)
        frame = int(self._lpa_frame_var.get())
        identity = dict(Frame_Index=frame, Frame=frame+1, Field_mT=_tab10_intensity_field(self, frame))
        full = pd.DataFrame([dict(**identity, Line=index+1, **_measurement_scalar_record(record))
            for index, record in sorted((getattr(self, '_lpa_gaussian_results', {}) or {}).items())])
        endpoints = pd.DataFrame([dict(**identity, **_measurement_scalar_record(record))
            for record in getattr(self, '_lpa_measurements', [])])
        for label, table in (('Gaussian_FullPrecision', full), ('Endpoints_FullPrecision', endpoints)):
            if not table.empty:
                _export_capture_write(table.to_csv, Path(fp).with_name(Path(fp).stem+'_'+label+'.csv'), index=False)
        self._lpa_status_var.set(
            f'Table exported: {len(rows)} displayed rows plus full-precision stored measurements → {fp}'
        )
    except Exception as exc:
        _export_error_dialog(messagebox.showerror, 'Table Export', str(exc), parent=self.root)


@_auto_open_export
def _t7_export_exact_visible_plot(self):
    # Always use the current authoritative Tab-6 ROI2 before exporting.
    try:
        _tab6_sync_current_roi2_to_tab7(self, reset_view=False)
    except Exception:
        pass

    stack = getattr(self, '_lpa_stack', None)
    lines = getattr(self, '_lpa_lines', []) or []
    if stack is None or len(stack) == 0:
        messagebox.showwarning('Plot Export', 'Fetch confirmed ROI2 from Tab 6 first.', parent=self.root)
        return
    if not lines:
        messagebox.showwarning('Plot Export', 'Draw at least one line before exporting.', parent=self.root)
        return

    now = time.monotonic()
    if getattr(self, '_tab7_plot_export_busy', False):
        return
    last = float(getattr(self, '_tab7_plot_export_last_time', 0.0) or 0.0)
    if (now - last) < 0.8:
        return
    self._tab7_plot_export_busy = True
    self._tab7_plot_export_last_time = now

    try:
        try:
            idx = max(0, min(int(self._lpa_frame_var.get()), len(stack) - 1))
        except Exception:
            idx = 0

        try:
            initial = self._export_initialdir()
        except Exception:
            initial = os.path.expanduser('~')

        folder = _export_capture_folder(filedialog.askdirectory, parent=self.root, initialdir=initial, title='Select Tab-7 Plot Export Folder')
        if not folder:
            return
        folder = os.path.abspath(folder)
        os.makedirs(folder, exist_ok=True)

        # ------------------------------------------------------------
        # 1) Keep the existing ROI2 export, including drawn ROI lines
        #    and M1/M2 markers.
        # ------------------------------------------------------------
        image = np.asarray(stack[idx], dtype=float)
        h, w = image.shape[:2]
        sx, sy = _lpa_scale_nm(self)
        width_nm = float(w * sx)
        height_nm = float(h * sy)
        cmap = 'RdBu_r'
        try:
            c = str(self.colormap_var.get()).strip()
            if c:
                cmap = c
        except Exception:
            pass

        field = None
        try:
            if self.real_fields_mT is not None and idx < len(self.real_fields_mT):
                field = float(self.real_fields_mT[idx])
        except Exception:
            pass
        field_text = f' | Field = {field:+.2f} mT' if field is not None else ''

        roi_fig = plt.figure(figsize=(8.6, 7.4), dpi=300, facecolor='white')
        _intensity_tag_figure(self, roi_fig, _intensity_default_frame(self, 'line'))
        roi_ax = roi_fig.add_axes([0.09, 0.10, 0.77, 0.82])
        roi_cax = roi_fig.add_axes([0.89, 0.10, 0.035, 0.82])
        roi_im = roi_ax.imshow(
            image, origin='lower', interpolation='nearest', cmap=cmap,
            vmin=0.0, vmax=1.0,
            extent=(0.0, width_nm, 0.0, height_nm), aspect='equal'
        )
        roi_ax.set_xlabel('X (nm)')
        roi_ax.set_ylabel('Y (nm)')
        roi_ax.set_title(
            f'Confirmed ROI — Frame {idx+1}/{len(stack)}{field_text}', fontsize=10
        )
        cb = roi_fig.colorbar(roi_im, cax=roi_cax)
        cb.set_label('Intensity')
        _t7v2_add_scale_bar(roi_ax, width_nm, height_nm)

        colors = plt.rcParams['axes.prop_cycle'].by_key().get(
            'color', ['C0','C1','C2','C3','C4','C5','C6','C7']
        )
        for j, (p0, p1) in enumerate(lines):
            p0 = np.asarray(p0, dtype=float)
            p1 = np.asarray(p1, dtype=float)
            roi_ax.plot(
                [p0[0], p1[0]], [p0[1], p1[1]], lw=2.5,
                color=colors[j % len(colors)], zorder=50, label=f'Line {j+1}'
            )

        for m in getattr(self, '_lpa_measurements', []) or []:
            li = int(m.get('line', -1))
            if li < 0 or li >= len(lines):
                continue
            p0 = np.asarray(lines[li][0], dtype=float)
            p1 = np.asarray(lines[li][1], dtype=float)
            got = _t7v2_line_profile(self, li)
            if got is None:
                continue
            d, prof = got
            total = float(d[-1]) if len(d) else 0.0
            if total <= 0:
                continue
            q0 = p0 + (float(m['m1_nm']) / total) * (p1 - p0)
            q1 = p0 + (float(m['m2_nm']) / total) * (p1 - p0)
            roi_ax.plot([q0[0], q1[0]], [q0[1], q1[1]], color='yellow', lw=3.0, zorder=70)
            for q, mid in ((q0, 2*li+1), (q1, 2*li+2)):
                roi_ax.text(
                    q[0], q[1], 'I', color='black', fontsize=15, fontweight='bold',
                    ha='center', va='center', zorder=72,
                    bbox=dict(boxstyle='round,pad=0.08', facecolor='white', edgecolor='black', alpha=0.95)
                )
                roi_ax.text(
                    q[0], q[1], f'M{mid}', color='black', fontsize=8, fontweight='bold',
                    ha='center', va='bottom', zorder=73,
                    bbox=dict(boxstyle='round,pad=0.10', facecolor='white', edgecolor='black', alpha=0.9)
                )
        try:
            roi_ax.legend(loc='best', fontsize=8, framealpha=0.9)
        except Exception:
            pass

        roi_path = os.path.join(folder, f'Tab7_ROI2_Frame_{idx+1:03d}.png')
        _export_capture_write(roi_fig.savefig, roi_path, dpi=300, bbox_inches='tight', pad_inches=0.08, facecolor='white')
        plt.close(roi_fig)

        # ------------------------------------------------------------
        # 2) Export the ACTUAL live Tab-7 line-profile figure.
        #    This is deliberately not redrawn from scratch.  Therefore
        #    every artist currently visible in Fig. 2 is preserved,
        #    including Gaussian fits when enabled and all markers/
        #    annotations/threshold overlays.
        # ------------------------------------------------------------
        plot_fig = getattr(self, '_lpa_fig2', None)
        plot_canvas = getattr(self, '_lpa_plot_canvas', None)
        if plot_fig is None:
            raise RuntimeError('Tab-7 line-profile figure is not available.')

        try:
            if plot_canvas is not None:
                plot_canvas.draw()
            else:
                plot_fig.canvas.draw()
        except Exception:
            pass

        plot_path = os.path.join(folder, f'Tab7_LineProfiles_Frame_{idx+1:03d}.png')
        _export_capture_write(plot_fig.savefig, plot_path, dpi=300, bbox_inches='tight', pad_inches=0.08, facecolor='white')

        self._lpa_status_var.set(
            'Plot export complete: live Tab-7 graph exported with all visible '
            'profiles, Gaussian fits (if enabled), markers and annotations.'
        )
        try:
            _tab6_open_output_folder(folder)
        except Exception:
            try:
                if os.name == 'nt':
                    _export_request_open(folder)
                else:
                    _export_request_open(folder)
            except Exception:
                pass
    except Exception as exc:
        _export_error_dialog(messagebox.showerror, 'Plot Export', str(exc), parent=self.root)
    finally:
        self._tab7_plot_export_busy = False


# Install these as the final Tab-7 export handlers so later notebook patches
# cannot overwrite them.
try:
    CDIWorkflowApp._tab7_table_export = _t7_export_all_visible_table
    CDIWorkflowApp._tab7_plot_export = _t7_export_exact_visible_plot
except Exception:
    pass

# Rebind the actual live Tab-7 buttons.  They were originally created with
# lambdas capturing the earlier handlers, so replacing the class method alone
# is not sufficient.  Locate the unique control row containing both buttons.
try:
    @_auto_open_export
    def _t7_rebind_export_buttons_final(self):
        def walk(widget):
            try:
                children = widget.winfo_children()
            except Exception:
                children = []
            for child in children:
                yield child
                yield from walk(child)

        for parent in walk(self.root):
            try:
                children = parent.winfo_children()
            except Exception:
                continue
            table_btn = None
            plot_btn = None
            for child in children:
                try:
                    text = str(child.cget('text')).strip().upper()
                except Exception:
                    continue
                if text == 'TABLE EXPORT':
                    table_btn = child
                elif text == 'PLOT EXPORT':
                    plot_btn = child
            if table_btn is not None and plot_btn is not None:
                table_btn.configure(command=lambda: _t7_export_all_visible_table(self))
                plot_btn.configure(command=lambda: _t7_export_exact_visible_plot(self))
                return True
        return False

    _t7_rebind_export_buttons_final(app)
except Exception:
    pass



# ============================================================================
# TAB 6 EXPORT — REBUILT FROM THE SAME AUTHORITATIVE SOURCE AS TAB 9
# ----------------------------------------------------------------------------
# This is the FINAL export implementation.  It intentionally bypasses every
# older Tab-6 export routine.  The source is the exact same authoritative
# Primary-ROI stack used by Tab 9.  Therefore, when Tab 6 SET has committed a
# rotation, exported frames are the rotated/common-cropped frames too.
#
# IMPORTANT: this block is installed BEFORE root.mainloop(), so the actual
# Tk buttons use these handlers during the running application.  Earlier
# patches located after root.mainloop() could not affect the already-running
# UI, which is why the previous export fixes appeared to have no effect.
# ============================================================================

@_auto_open_export
def _tab6_rebuilt_export_source(self):
    """Return exactly the Primary-ROI stack used by Tab 9."""
    fetch = globals().get('_tab6_downstream_authoritative_primary_stack_v22')
    if not callable(fetch):
        raise RuntimeError('Tab-6 authoritative Primary-ROI source is unavailable.')

    stack, scale, sig = fetch(self)
    if stack is None:
        raise RuntimeError(
            'No authoritative Tab-6 Primary ROI is available. '
            'Confirm/apply the Primary ROI resolution first.'
        )

    stack = np.asarray(stack, dtype=_intensity_dtype(self))
    if stack.ndim != 3 or stack.shape[0] == 0:
        raise RuntimeError(f'Invalid authoritative Tab-6 ROI stack shape: {stack.shape}')

    sx, sy = map(float, scale)
    if not (np.isfinite(sx) and np.isfinite(sy) and sx > 0 and sy > 0):
        raise RuntimeError('Invalid authoritative Tab-6 ROI nm/pixel scale.')

    # Keep an explicit export signature for diagnostics.  This is the same
    # signature that Tab 9 receives from the authoritative source.
    self._tab6_rebuilt_export_source_signature = sig
    self._tab6_rebuilt_export_scale = (sx, sy)
    self._tab6_rebuilt_export_stack = stack.copy()
    return stack, (sx, sy)



@_auto_open_export
def _tab6_rebuilt_export_figure(self, image, idx, scale, dpi, title_prefix='ROI'):
    image = np.asarray(image, dtype=_intensity_dtype(self))
    if image.ndim != 2 or image.size == 0:
        raise RuntimeError('Invalid Tab-6 export frame.')

    h, w = image.shape
    sx, sy = map(float, scale)
    cmap_name = 'gray'
    try:
        cmap_name = str(self.colormap_var.get() or 'gray')
    except Exception:
        pass

    fig = plt.figure(figsize=(9.0, 7.2), dpi=int(dpi), facecolor='white')
    _intensity_tag_figure(self, fig, idx)
    ax = fig.add_axes([0.09, 0.12, 0.76, 0.78])
    cax = fig.add_axes([0.875, 0.12, 0.035, 0.78])

    im = ax.imshow(
        image,
        origin='lower',
        extent=(0.0, w * sx, 0.0, h * sy),
        interpolation='nearest',
        cmap=cmap_name,
        vmin=0.0,
        vmax=1.0,
        aspect='equal'
    )
    ax.set_xlim(0.0, w * sx)
    ax.set_ylim(0.0, h * sy)
    ax.set_xlabel('X (nm)')
    ax.set_ylabel('Y (nm)')

    try:
        field = float(self.real_fields_mT[idx])
        title = (
            f'{title_prefix} | Frame {idx + 1}/{len(self.recons)} | '
            f'Field = {field:+.2f} mT'
        )
    except Exception:
        title = f'{title_prefix} | Frame {idx + 1}'
    ax.set_title(title, fontsize=12)
    fig.colorbar(im, cax=cax).set_label('Intensity', rotation=90)
    return fig



@_auto_open_export
def _tab6_rebuilt_save_single(self, extension, fmt):
    if not getattr(self, 'roi_resolution_applied', False):
        messagebox.showwarning(
            'ROI Resolution Required',
            'Apply SAME CONFIRMED ROI resolution first.',
            parent=self.root
        )
        return
    try:
        dpi = int(self.proc_export_dpi_var.get())
    except Exception:
        dpi = 300
    if dpi not in (150, 300, 600, 900):
        messagebox.showwarning(
            'Export DPI',
            'Select 150, 300, 600 or 900 DPI.',
            parent=self.root
        )
        return

    fig = None
    try:
        stack, scale = _tab6_rebuilt_export_source(self)
        n = stack.shape[0]
        i = max(0, min(int(round(float(self.proc_idx_var.get()))), n - 1))
        field = float(self.real_fields_mT[i])
        folder = os.path.abspath(
            os.path.expanduser(str(self.output_var.get()).strip() or 'ROI_exports')
        )
        os.makedirs(folder, exist_ok=True)
        path = os.path.join(folder, f'ROI_{i:03d}_{field:+.2f}mT{extension}')

        # DIRECTLY export the authoritative frame. No _proc_image(), no
        # display-cache reconstruction, and no second rotation is performed.
        fig = _tab6_rebuilt_export_figure(self, stack[i], i, scale, dpi, 'ROI')
        kwargs = {
            'dpi': dpi,
            'bbox_inches': 'tight',
            'pad_inches': 0.08,
            'format': fmt,
            'facecolor': 'white'
        }
        _export_capture_write(fig.savefig, path, **kwargs)

        mode = 'ROTATED' if (
            bool(getattr(self, '_tab6_analysis_rotation_committed', False)) and
            abs(float(getattr(self, '_tab6_analysis_rotation_angle', 0.0))) > 1e-12
        ) else 'UNROTATED'
        self.proc_status_var.set(
            f'Saved: {path} | {dpi} DPI | Tab-6 authoritative {mode} ROI'
        )
        self.log(
            f'Tab-6 REBUILT image export: {path} | frame={i+1} | '
            f'shape={stack[i].shape} | scale={scale} | mode={mode}'
        )
        _tab6_open_output_folder(folder)
    except Exception as exc:
        self.proc_status_var.set('Single-image export failed.')
        self.log(f'Tab-6 rebuilt single export failed: {exc}')
        _export_error_dialog(messagebox.showerror, 'Export Error', str(exc), parent=self.root)
    finally:
        if fig is not None:
            try:
                plt.close(fig)
            except Exception:
                pass


@_auto_open_export
def _tab6_rebuilt_save_batch(self, extension, fmt):
    if not getattr(self, 'roi_resolution_applied', False):
        messagebox.showwarning(
            'ROI Resolution Required',
            'Apply SAME CONFIRMED ROI resolution first.',
            parent=self.root
        )
        return
    try:
        dpi = int(self.proc_export_dpi_var.get())
    except Exception:
        dpi = 300
    if dpi not in (150, 300, 600, 900):
        messagebox.showwarning(
            'Export DPI',
            'Select 150, 300, 600 or 900 DPI.',
            parent=self.root
        )
        return

    try:
        stack, scale = _tab6_rebuilt_export_source(self)
        n = stack.shape[0]
        folder = os.path.abspath(
            os.path.expanduser(str(self.output_var.get()).strip() or 'ROI_exports')
        )
        os.makedirs(folder, exist_ok=True)

        mode = 'ROTATED' if (
            bool(getattr(self, '_tab6_analysis_rotation_committed', False)) and
            abs(float(getattr(self, '_tab6_analysis_rotation_angle', 0.0))) > 1e-12
        ) else 'UNROTATED'

        for i in range(n):
            field = float(self.real_fields_mT[i])
            path = os.path.join(folder, f'ROI_{i:03d}_{field:+.2f}mT{extension}')
            fig = None
            try:
                fig = _tab6_rebuilt_export_figure(self, stack[i], i, scale, dpi, 'ROI')
                _export_capture_write(fig.savefig, path, dpi=dpi, bbox_inches='tight', pad_inches=0.08, format=fmt, facecolor='white')
            finally:
                if fig is not None:
                    try:
                        plt.close(fig)
                    except Exception:
                        pass
            self.proc_status_var.set(
                f'Exporting {fmt}: {i + 1}/{n} | {dpi} DPI | '
                f'Tab-6 authoritative {mode} ROI'
            )
            self.root.update_idletasks()

        self.proc_status_var.set(
            f'Batch {fmt} export complete | {n} images | '
            f'Tab-6 authoritative {mode} ROI'
        )
        self.log(
            f'Tab-6 REBUILT batch export: format={fmt} | count={n} | '
            f'scale={scale} | mode={mode}'
        )
        _tab6_open_output_folder(folder)
    except Exception as exc:
        self.proc_status_var.set('Batch export failed.')
        self.log(f'Tab-6 rebuilt batch export failed: {exc}')
        _export_error_dialog(messagebox.showerror, 'Batch Export Error', str(exc), parent=self.root)


# The existing IMAGE buttons were created with lambdas that resolve these
# global names when clicked. Replace those names directly.
@_auto_open_export
def _tab6_export_single_selected(self):
    extension, fmt = _tab6_format_to_args(self.proc_single_format_var.get())
    _tab6_rebuilt_save_single(self, extension, fmt)


@_auto_open_export
def _tab6_export_batch_selected(self):
    extension, fmt = _tab6_format_to_args(self.proc_batch_format_var.get())
    _tab6_rebuilt_save_batch(self, extension, fmt)


@_auto_open_export
def _tab6_rebuilt_mp4(self, indices, filename):
    if not getattr(self, 'roi_resolution_applied', False):
        messagebox.showwarning(
            'ROI Resolution Required',
            'Apply SAME CONFIRMED ROI resolution first.',
            parent=self.root
        )
        return
    imageio = _proc_imageio(self)
    if imageio is None:
        return
    try:
        dpi = int(self.proc_export_dpi_var.get())
    except Exception:
        dpi = 300
    if dpi not in (150, 300, 600, 900):
        messagebox.showwarning('Export DPI', 'Select 150, 300, 600 or 900 DPI.', parent=self.root)
        return

    stack, scale = _tab6_rebuilt_export_source(self)
    indices = [int(i) for i in indices]
    if not indices:
        messagebox.showwarning('MP4 Export', 'No frames selected.', parent=self.root)
        return
    if min(indices) < 0 or max(indices) >= stack.shape[0]:
        raise ValueError('Selected MP4 frame range is outside the Tab-6 Primary ROI stack.')

    folder = os.path.abspath(
        os.path.expanduser(str(self.output_var.get()).strip() or 'ROI_exports')
    )
    os.makedirs(folder, exist_ok=True)
    path = os.path.join(folder, filename)
    fps = max(1, int(self.fps_var.get()))

    fig = writer = None
    try:
        # Use the same Matplotlib representation for every frame.  The DATA
        # array comes directly from the same rotated stack used by Tab 9.
        fig = plt.figure(figsize=(9.0, 7.2), dpi=dpi, facecolor='white')
        _intensity_tag_figure(self, fig, _intensity_default_frame(self, 'processing'))
        ax = fig.add_axes([0.09, 0.12, 0.76, 0.78])
        cax = fig.add_axes([0.875, 0.12, 0.035, 0.78])
        cmap_name = str(self.colormap_var.get() or 'gray')

        errors = []
        for codec in ('libx264', 'mpeg4', None):
            try:
                kw = {'fps': fps, 'format': 'ffmpeg', 'macro_block_size': None}
                if codec is not None:
                    kw['codec'] = codec
                writer = _export_capture_writer(imageio.get_writer, path, **kw)
                break
            except Exception as exc:
                errors.append(f'{codec or "default"}: {exc}')
        if writer is None:
            raise RuntimeError('Could not initialize an MP4 encoder.\n\n' + '\n'.join(errors))

        for count, i in enumerate(indices, start=1):
            image = np.asarray(stack[i], dtype=_intensity_dtype(self))
            h, w = image.shape
            sx, sy = scale
            ax.clear()
            cax.clear()
            im = ax.imshow(
                image, origin='lower', extent=(0.0, w*sx, 0.0, h*sy),
                interpolation='nearest', cmap=cmap_name,
                vmin=0.0, vmax=1.0, aspect='equal'
            )
            ax.set_xlim(0.0, w*sx)
            ax.set_ylim(0.0, h*sy)
            ax.set_xlabel('X (nm)')
            ax.set_ylabel('Y (nm)')
            try:
                field = float(self.real_fields_mT[i])
                ax.set_title(
                    f'ROI | Frame {i+1}/{len(self.recons)} | Field = {field:+.2f} mT',
                    fontsize=12
                )
            except Exception:
                ax.set_title(f'ROI | Frame {i+1}', fontsize=12)
            fig.colorbar(im, cax=cax).set_label('Intensity', rotation=90)
            fig.canvas.draw()
            frame = np.asarray(fig.canvas.buffer_rgba())[:, :, :3]
            fh, fw = frame.shape[:2]
            if fh % 2 or fw % 2:
                frame = np.pad(frame, ((0, fh % 2), (0, fw % 2), (0, 0)), mode='edge')
            writer.append_data(frame)
            self.proc_status_var.set(
                f'MP4: {count}/{len(indices)} | {fps} FPS | {dpi} DPI | '
                f'Tab-6 authoritative ROI'
            )
            self.root.update_idletasks()
    except Exception as exc:
        self.proc_status_var.set('MP4 export failed.')
        self.log(f'Tab-6 rebuilt MP4 export failed: {path} | {exc}')
        _export_error_dialog(messagebox.showerror, 'MP4 Error', str(exc), parent=self.root)
        return
    finally:
        close_error = None
        try:
            if writer is not None:
                writer.close()
        except Exception as exc:
            close_error = exc
            _export_mark_failed()
        try:
            if fig is not None:
                plt.close(fig)
        except Exception:
            pass

    if close_error is not None:
        self.proc_status_var.set(f'MP4 finalization failed: {close_error}')
        self.log(f'MP4 encoder finalization failed: {path} | {close_error}')
        _export_error_dialog(messagebox.showerror, 'MP4 Error',
            f'MP4 could not be finalized: {close_error}', parent=self.root)
        return

    self.proc_status_var.set(
        f'MP4 saved: {filename} | {fps} FPS | {dpi} DPI | '
        'Tab-6 authoritative ROI'
    )
    self.log(
        f'Tab-6 REBUILT MP4 export: {path} | frames={len(indices)} | '
        f'fps={fps} | dpi={dpi} | scale={scale}'
    )
    _tab6_open_output_folder(folder)
    messagebox.showinfo(
        'MP4 Export',
        f'MP4 successfully saved:\n\n{path}\n\n'
        f'Frames: {len(indices)}\nFPS: {fps}\nDPI: {dpi}\n\n'
        'Source: exact Tab-6 Primary ROI stack used by Tab 9.',
        parent=self.root
    )



def _tab6_rebuilt_single_mp4(self):
    i = int(self.proc_idx_var.get())
    frames = max(1, int(self.fps_var.get()) * 2)
    _tab6_rebuilt_mp4(
        self, [i] * frames,
        f'ROI_single_{i:03d}_{self.real_fields_mT[i]:+.2f}mT.mp4'
    )


def _tab6_rebuilt_batch_mp4(self):
    try:
        indices, start, end, fps = _proc_get_batch_mp4_indices(self)
        self.fps_var.set(fps)
        _tab6_rebuilt_mp4(
            self, indices,
            f'ROI_frames_{start:04d}-{end:04d}_{fps}fps.mp4'
        )
    except Exception as exc:
        messagebox.showerror('Batch MP4 Export', str(exc), parent=self.root)


# Rebind the class methods for any future callers, AND rebind the actual
# already-created MP4 buttons because their original commands captured bound
# method objects during UI construction.
CDIWorkflowApp.save_single = _tab6_rebuilt_save_single
CDIWorkflowApp.batch_export = _tab6_rebuilt_save_batch
CDIWorkflowApp.create_mp4 = _tab6_rebuilt_mp4
CDIWorkflowApp.export_single_mp4 = _tab6_rebuilt_single_mp4
CDIWorkflowApp.export_batch_mp4 = _tab6_rebuilt_batch_mp4


def _tab6_rebuilt_walk_widgets(widget):
    yield widget
    try:
        for child in widget.winfo_children():
            yield from _tab6_rebuilt_walk_widgets(child)
    except Exception:
        return

try:
    mp4_buttons = []
    for widget in _tab6_rebuilt_walk_widgets(app.tab_proc):
        try:
            if isinstance(widget, ttk.Button):
                text = str(widget.cget('text')).strip().upper()
                if text in ('SINGLE MP4', 'BATCH MP4'):
                    mp4_buttons.append((text, widget))
        except Exception:
            pass
    for text, widget in mp4_buttons:
        if text == 'SINGLE MP4':
            widget.configure(command=lambda a=app: _tab6_rebuilt_single_mp4(a))
        elif text == 'BATCH MP4':
            widget.configure(command=lambda a=app: _tab6_rebuilt_batch_mp4(a))
    app.log(
        f'Tab-6 export options REBUILT before mainloop: '
        f'{len(mp4_buttons)} MP4 button(s) rebound to authoritative rotated ROI.'
    )
except Exception as exc:
    try:
        app.log(f'Tab-6 export button rebinding warning: {type(exc).__name__}: {exc}')
    except Exception:
        pass

print('TAB 6 EXPORT OPTIONS REBUILT: image + MP4 now use the exact Primary-ROI source used by Tab 9.')


# ===== TAB 6: ALL FRAMES export selector =====
@_auto_open_export
def _tab6_use_all_frames_export(self):
    """Select the complete loaded reconstruction range for Tab-6 exports."""
    try:
        n = int(len(self.recons)) if self.recons is not None else 0
    except Exception:
        n = 0
    if n <= 0:
        try:
            messagebox.showwarning('ALL FRAMES', 'Load reconstruction frames first.', parent=self.root)
        except Exception:
            pass
        return
    try:
        self.proc_mp4_start_var.set(1)
        self.proc_mp4_end_var.set(n)
    except Exception:
        pass
    try:
        self.proc_mp4_start_spin.configure(from_=1, to=n, state='normal')
        self.proc_mp4_end_spin.configure(from_=1, to=n, state='normal')
    except Exception:
        pass
    try:
        self._tab6_export_all_frames = True
    except Exception:
        pass
    try:
        self.proc_status_var.set(
            f'ALL FRAMES selected: frames 1–{n}. Batch Image and Batch MP4 will use the complete range.'
        )
        self.log(f'Tab-6 ALL FRAMES selected: 1-{n}')
    except Exception:
        pass

CDIWorkflowApp._tab6_use_all_frames_export = _tab6_use_all_frames_export

# Add the button to the already-built Tab-6 MP4 controls BEFORE mainloop.
try:
    _all_frames_added = False
    for _w in _tab6_rebuilt_walk_widgets(app.tab_proc):
        try:
            if isinstance(_w, ttk.Button) and str(_w.cget('text')).strip().upper() == 'BATCH MP4':
                _parent = _w.master
                ttk.Button(
                    _parent,
                    text='ALL FRAMES',
                    command=lambda a=app: a._tab6_use_all_frames_export()
                ).pack(side='left', expand=True, fill='x', padx=2)
                _all_frames_added = True
                break
        except Exception:
            pass
    if not _all_frames_added:
        app.log('Tab-6 ALL FRAMES button could not be inserted.')
    else:
        app.log('Tab-6 ALL FRAMES button added successfully.')
except Exception as exc:
    try:
        app.log(f'Tab-6 ALL FRAMES button warning: {type(exc).__name__}: {exc}')
    except Exception:
        pass








# ============================================================================
# FINAL PATCH: TAB 4 COMPONENT SELECTION + TAB 4 HISTOGRAM LAYOUT
# ----------------------------------------------------------------------------
# Tab 4 owns component selection. The dropdown is pending until the user clicks
# Confirm Component. Confirmation commits the selected component as the active
# downstream analysis stack so Tabs 6-14 cannot silently fall back to Real.
# Histogram mode renders a 1x2 layout: line-chart histogram on the left and ROI
# image/selector on the right. Histogram CSV export supports a selected frame
# range.
# ============================================================================

_TAB4_COMPONENT_CHOICES = ('Real', 'Imaginary', 'Amplitude', 'Phase')


def _tab4_component_capture_sources(self):
    try:
        n = len(self.recons) if getattr(self, 'recons', None) is not None else 0
    except Exception:
        n = 0
    complex_source = getattr(self, 'complex_recons', None)
    sig = (n, id(complex_source), tuple(np.asarray(complex_source).shape)) if complex_source is not None else (
        n, tuple(id(getattr(self, name, None)) for name in
                 ('recons', 'imag_recons', 'amplitude_recons', 'phase_recons')))
    # Committing a component may alias recons; retain the captured originals.
    if complex_source is None and getattr(self, '_analysis_component_stack_confirmed', None) is getattr(self, 'recons', None):
        sig = getattr(self, '_tab4_component_source_signature', sig)
    sources = getattr(self, '_tab4_component_source_stacks', None)
    if sources is not None and getattr(self, '_tab4_component_source_signature', None) == sig:
        return sources

    complex_stack = getattr(self, 'complex_recons', None)
    sources = {}
    try:
        if complex_stack is not None:
            sources['Real'] = np.real(complex_stack).astype(np.float64)
        elif getattr(self, 'real_recons', None) is not None and np.asarray(self.real_recons).ndim == 3:
            sources['Real'] = np.asarray(self.real_recons, dtype=np.float64).copy()
        elif getattr(self, 'recons', None) is not None:
            sources['Real'] = np.asarray(self.recons, dtype=np.float64).copy()
    except Exception:
        pass
    try:
        if getattr(self, 'imag_recons', None) is not None and np.asarray(self.imag_recons).ndim == 3:
            sources['Imaginary'] = np.asarray(self.imag_recons, dtype=np.float64).copy()
        elif complex_stack is not None:
            sources['Imaginary'] = np.imag(complex_stack).astype(np.float64)
    except Exception:
        pass
    try:
        if getattr(self, 'amplitude_recons', None) is not None and np.asarray(self.amplitude_recons).ndim == 3:
            sources['Amplitude'] = np.asarray(self.amplitude_recons, dtype=np.float64).copy()
        elif complex_stack is not None:
            sources['Amplitude'] = np.abs(complex_stack).astype(np.float64)
    except Exception:
        pass
    try:
        if getattr(self, 'phase_recons', None) is not None and np.asarray(self.phase_recons).ndim == 3:
            sources['Phase'] = np.asarray(self.phase_recons, dtype=np.float64).copy()
        elif complex_stack is not None:
            sources['Phase'] = np.angle(complex_stack).astype(np.float64)
    except Exception:
        pass

    self._tab4_component_source_stacks = sources
    self._tab4_component_source_signature = sig
    return sources


def _tab4_component_pending(self):
    try:
        value = str(self.tab4_component_var.get()).strip()
    except Exception:
        value = str(getattr(self, 'analysis_component_name', 'Real')).strip()
    return value if value in _TAB4_COMPONENT_CHOICES else 'Real'


def _tab4_component_confirmed(self):
    value = str(getattr(self, 'analysis_component_name', 'Real')).strip()
    return value if value in _TAB4_COMPONENT_CHOICES else 'Real'


def _tab4_component_stack(self, component=None):
    component = component or _tab4_component_confirmed(self)
    sources = _tab4_component_capture_sources(self)
    arr = sources.get(component)
    if arr is None:
        raise RuntimeError(f'{component} component is unavailable. Load reconstructions first.')
    arr = np.asarray(arr, dtype=np.float64)
    if arr.ndim != 3:
        raise ValueError(f'{component} component stack must be (N,Y,X); got {arr.shape}')
    return arr


def _tab4_commit_component_for_downstream(self, component=None):
    component = component or _tab4_component_pending(self)
    stack = np.asarray(_tab4_component_stack(self, component), dtype=np.float64)
    self.recons = stack
    # Legacy downstream callbacks may still read real_recons. Point it to the
    # selected component while original component sources remain preserved above.
    self.real_recons = stack
    self.analysis_component_name = component
    self.roi_analysis_component = component
    self.analysis_component_confirmed = True
    self._analysis_component_stack_confirmed = stack
    try:
        self.current_display_component = component
    except Exception:
        pass
    return stack


def _tab4_confirm_component(self):
    try:
        comp = _tab4_component_pending(self)
        _tab4_commit_component_for_downstream(self, comp)
        try:
            self.roi_resolution_applied = False
            self.roi2_coords = None
            self.roi2_confirmed_coords = None
            self.roi2_stack = None
            self.roi2_mask = None
            self.line_source_stack = None
            self.gauss2d_source_stack = None
        except Exception:
            pass
        if hasattr(self, 'tab4_component_status_var'):
            self.tab4_component_status_var.set(f'Confirmed component: {comp}')
        try:
            self.roi_status_var.set(f'Component CONFIRMED: {comp}. Draw/select ROI, then Confirm ROI.')
        except Exception:
            pass
        try:
            self.log(f'Tab 4 confirmed component for downstream analysis: {comp}')
        except Exception:
            pass
        self.refresh_roi_image()
    except Exception as exc:
        messagebox.showerror('Confirm Component', f'Failed to confirm component:\n{type(exc).__name__}: {exc}', parent=self.root)


def _tab4_frame_count(self):
    try:
        return int(len(_tab4_component_stack(self, _tab4_component_confirmed(self))))
    except Exception:
        try:
            return int(len(self.recons)) if self.recons is not None else 0
        except Exception:
            return 0


def _tab4_sync_slider_and_range(self):
    n = max(1, _tab4_frame_count(self))
    try:
        idx = int(self.roi_index_var.get())
    except Exception:
        idx = int(getattr(self, 'current_index', 0) or 0)
    idx = max(0, min(idx, n - 1))
    display_no = idx
    try:
        self.roi_index_var.set(idx)
    except Exception:
        pass
    try:
        self.tab4_frame_slider.configure(from_=0, to=n - 1, resolution=1)
        self.tab4_frame_slider_var.set(display_no)
    except Exception:
        pass
    try:
        self.tab4_frame_label_var.set(f'Frame {display_no}/{n}')
    except Exception:
        pass
    for attr in ('tab4_hist_start_spin', 'tab4_hist_end_spin'):
        try:
            getattr(self, attr).configure(from_=1, to=n)
        except Exception:
            pass
    try:
        s = max(1, min(int(self.tab4_hist_start_var.get()), n))
    except Exception:
        s = 1
    try:
        e = max(1, min(int(self.tab4_hist_end_var.get()), n))
    except Exception:
        e = n
    if s > e:
        e = s
    try:
        self.tab4_hist_start_var.set(s)
        self.tab4_hist_end_var.set(e)
    except Exception:
        pass


def _tab4_set_frame_from_slider(self, value=None):
    n = max(1, _tab4_frame_count(self))
    try:
        display_no = int(round(float(value))) if value is not None else int(round(float(self.tab4_frame_slider_var.get())))
    except Exception:
        display_no = 0
    display_no = max(0, min(display_no, n - 1))
    idx = display_no
    try:
        self.roi_index_var.set(idx)
    except Exception:
        pass
    if not _tab4_has_confirmed_roi(self):
        self.current_index = idx
    try:
        self.tab4_frame_slider_var.set(display_no)
        self.tab4_frame_label_var.set(f'Frame {display_no}/{n}')
    except Exception:
        pass
    try:
        self.refresh_roi_image()
    except Exception:
        pass
    return 'break'


def _tab4_hist_enabled(self):
    try:
        return bool(self.tab4_histogram_var.get())
    except Exception:
        return False


def _tab4_install_controls(self):
    if not hasattr(self, 'tab4_component_var'):
        self.tab4_component_var = tk.StringVar(value=str(getattr(self, 'analysis_component_name', 'Real')))
    if not hasattr(self, 'tab4_component_status_var'):
        self.tab4_component_status_var = tk.StringVar(value=f'Confirmed component: {_tab4_component_confirmed(self)}')
    if not hasattr(self, 'tab4_frame_slider_var'):
        self.tab4_frame_slider_var = tk.DoubleVar(value=0.0)
    if not hasattr(self, 'tab4_frame_label_var'):
        self.tab4_frame_label_var = tk.StringVar(value='Frame 1/1')
    if not hasattr(self, 'tab4_histogram_var'):
        self.tab4_histogram_var = tk.BooleanVar(value=False)
    if not hasattr(self, 'tab4_histogram_status_var'):
        self.tab4_histogram_status_var = tk.StringVar(value='Histogram: off')
    if not hasattr(self, 'tab4_hist_start_var'):
        self.tab4_hist_start_var = tk.IntVar(value=1)
    if not hasattr(self, 'tab4_hist_end_var'):
        self.tab4_hist_end_var = tk.IntVar(value=max(1, _tab4_frame_count(self)))

    if getattr(self, '_tab4_controls_installed_final', False):
        _tab4_sync_slider_and_range(self)
        return

    try:
        top = None
        for child in self.tab_roi.winfo_children():
            try:
                if isinstance(child, ttk.Frame):
                    top = child
                    break
            except Exception:
                pass
        if top is None:
            top = ttk.Frame(self.tab_roi, padding=8)
            top.pack(fill='x')

        # Rebuild the top strip in the requested order.
        for child in list(top.winfo_children()):
            try:
                child.pack_forget()
            except Exception:
                pass

        if not hasattr(self, 'tab4_normalized_intensity_var'):
            self._analysis_intensity_mode = 'Normalized'
            self.tab4_normalized_intensity_var = tk.BooleanVar(value=True)
            self.tab4_raw_intensity_var = tk.BooleanVar(value=False)
        mode_row = ttk.Frame(self.tab_roi, padding=(8, 2))
        mode_row.pack(fill='x', after=top)
        self.tab4_normalized_intensity_check = ttk.Checkbutton(mode_row, text='Normalized Intensity',
            variable=self.tab4_normalized_intensity_var, command=lambda: _tab4_set_intensity_mode(self, 'Normalized'))
        self.tab4_normalized_intensity_check.pack(side='left', padx=(0, 12))
        self.tab4_raw_intensity_check = ttk.Checkbutton(mode_row, text='Raw Intensity',
            variable=self.tab4_raw_intensity_var, command=lambda: _tab4_set_intensity_mode(self, 'Raw'))
        self.tab4_raw_intensity_check.pack(side='left')
        ttk.Label(mode_row, text='Raw: original component units; brightness/contrast affect display only. Spatial filters and resizing still apply.').pack(side='left', padx=14)

        ttk.Label(top, text='Component').pack(side='left', padx=(0, 2))
        combo = ttk.Combobox(top, textvariable=self.tab4_component_var, values=list(_TAB4_COMPONENT_CHOICES), state='readonly', width=12)
        combo.pack(side='left', padx=(0, 5))
        self.tab4_component_combo = combo

        def _component_changed(event=None):
            pending = _tab4_component_pending(self)
            confirmed = _tab4_component_confirmed(self)
            self.tab4_component_status_var.set(f'Pending: {pending} | Confirmed: {confirmed}')

        combo.bind('<<ComboboxSelected>>', _component_changed)
        ttk.Button(top, text='Confirm Component', command=lambda: _tab4_confirm_component(self)).pack(side='left', padx=4)
        ttk.Button(top, text='Confirm ROI', command=lambda: self.confirm_roi()).pack(side='left', padx=4)
        ttk.Button(top, text='Clear ROI', command=lambda: self.clear_roi()).pack(side='left', padx=4)

        ttk.Label(top, text='Frame Range').pack(side='left', padx=(12, 2))
        start_spin = ttk.Spinbox(top, from_=1, to=1, textvariable=self.tab4_hist_start_var, width=6)
        start_spin.pack(side='left', padx=(0, 2))
        ttk.Label(top, text='to').pack(side='left')
        end_spin = ttk.Spinbox(top, from_=1, to=1, textvariable=self.tab4_hist_end_var, width=6)
        end_spin.pack(side='left', padx=(2, 4))
        self.tab4_hist_start_spin = start_spin
        self.tab4_hist_end_spin = end_spin
        ttk.Button(top, text='Save Histogram CSV', command=lambda: _tab4_save_histogram_csv(self)).pack(side='left', padx=4)
        ttk.Label(top, textvariable=self.tab4_component_status_var).pack(side='left', padx=(10, 0))

        # Hide any old spinbox from earlier Tab-4 patches.
        try:
            spin = getattr(self, '_tab4_roi_index_spinbox', None)
            if spin is not None:
                spin.pack_forget()
        except Exception:
            pass

        hist_row = ttk.Frame(self.tab_roi, padding=(8, 0, 8, 2))
        try:
            hist_row.pack(fill='x', after=mode_row)
        except Exception:
            hist_row.pack(fill='x')
        ttk.Checkbutton(hist_row, text='Histogram analysis', variable=self.tab4_histogram_var, command=lambda: self.refresh_roi_image()).pack(side='left')
        ttk.Label(hist_row, textvariable=self.tab4_histogram_status_var).pack(side='left', padx=(8, 0))
        self.tab4_histogram_row = hist_row
        reference_row = ttk.LabelFrame(self.tab_roi, text='Dataset normalization references — source frame numbers start at 0', padding=(6, 3))
        reference_row.pack(fill='x', after=hist_row, padx=8, pady=(2, 3))
        columns = ('dataset', 'component', 'minimum', 'minimum_frame', 'maximum', 'maximum_frame')
        table = ttk.Treeview(reference_row, columns=columns, show='headings', height=1, selectmode='browse')
        for column, title, width in zip(columns,
                ('Dataset / sweep', 'Component', 'Minimum → 0', 'Source frame', 'Maximum → 1', 'Source frame'),
                (220, 95, 150, 100, 150, 100)):
            table.heading(column, text=title)
            table.column(column, width=width, minwidth=70, anchor='w' if column in ('dataset', 'component') else 'center')
        table.pack(fill='x')
        self.tab4_normalization_reference_table = table
        self._tab4_normalization_table_signature = None
        self.tab4_normalization_status_var = tk.StringVar(value='Confirm a component to find each dataset’s fixed minimum and maximum across all loaded frames.')
        ttk.Label(reference_row, textvariable=self.tab4_normalization_status_var, wraplength=1100).pack(fill='x', pady=(3, 0))
        self.tab4_normalization_reference_row = reference_row

        slider_row = ttk.Frame(self.tab_roi, padding=(8, 0, 8, 4))
        try:
            slider_row.pack(fill='x', after=reference_row)
        except Exception:
            slider_row.pack(fill='x')
        ttk.Label(slider_row, text='Frame').pack(side='left')
        slider = tk.Scale(slider_row, from_=0, to=0, orient='horizontal', variable=self.tab4_frame_slider_var, command=lambda v: _tab4_set_frame_from_slider(self, v), showvalue=True, resolution=1, length=420)
        slider.pack(side='left', fill='x', expand=True, padx=6)
        ttk.Label(slider_row, textvariable=self.tab4_frame_label_var, width=14).pack(side='left')
        self.tab4_frame_slider = slider
        self._tab4_controls_installed_final = True
        _tab4_sync_slider_and_range(self)
    except Exception as exc:
        try:
            self.log(f'Tab 4 controls warning: {type(exc).__name__}: {exc}')
        except Exception:
            pass


def _tab4_component_display_image(self, idx):
    comp = _tab4_component_confirmed(self)
    stack = _tab4_component_stack(self, comp)
    idx = max(0, min(int(idx), len(stack) - 1))
    img = np.asarray(stack[idx], dtype=float)
    support = np.asarray(getattr(self, 'supportmask2', np.ones(img.shape, dtype=bool)), dtype=bool)
    if support.shape != img.shape:
        support = np.ones(img.shape, dtype=bool)
    valid = support & np.isfinite(img)
    reference = _update_component_normalization_status(self, idx)
    disp = img.copy() if _intensity_raw(self) else _normalize_component_frame_values(img, reference)
    disp[~support] = np.nan
    return img, disp, support, valid


def _tab4_current_histogram(self, idx, bins=120):
    img, disp, support, valid = _tab4_component_display_image(self, idx)
    if _tab4_has_confirmed_roi(self):
        valid &= np.asarray(self.roi_mask, dtype=bool)
    values = img[valid]
    values = values[np.isfinite(values)]
    if values.size == 0:
        return np.array([]), np.array([]), np.array([]), img, disp, support
    counts, edges = np.histogram(values, bins=int(bins))
    centers = 0.5 * (edges[:-1] + edges[1:])
    return centers, counts, edges, img, disp, support


@_auto_open_export
def _tab4_save_histogram_csv(self):
    try:
        _tab4_install_controls(self)
        n = max(1, _tab4_frame_count(self))
        start = max(1, min(int(self.tab4_hist_start_var.get()), n))
        end = max(1, min(int(self.tab4_hist_end_var.get()), n))
        if start > end:
            start, end = end, start
        comp = _tab4_component_confirmed(self)
        path = filedialog.asksaveasfilename(parent=self.root, title='Save Tab 4 histogram CSV', defaultextension='.csv', filetypes=[('CSV files', '*.csv'), ('All files', '*.*')])
        if not path:
            return
        rows = []
        for frame_no in range(start, end + 1):
            idx = frame_no - 1
            centers, counts, edges, *_ = _tab4_current_histogram(self, idx, bins=120)
            try:
                field = float(self.real_fields_mT[idx]) if self.real_fields_mT is not None and idx < len(self.real_fields_mT) else np.nan
            except Exception:
                field = np.nan
            for j, count in enumerate(counts):
                rows.append({
                    'frame': frame_no,
                    'frame_index': idx,
                    'component': comp,
                    'field_mT': field,
                    **_intensity_provenance(self, idx),
                    'histogram_signal': 'original selected-component reconstruction values',
                    'histogram_units': 'rad' if comp == 'Phase' else 'reconstruction a.u.',
                    'bin_left': float(edges[j]),
                    'bin_right': float(edges[j + 1]),
                    'bin_center': float(centers[j]),
                    'count': int(count),
                })
        _export_capture_write(pd.DataFrame(rows).to_csv, path, index=False)
        try:
            self.tab4_histogram_status_var.set(f'Saved histogram CSV: frames {start}-{end}')
            self.log(f'Tab 4 histogram CSV saved: {path} | frames {start}-{end} | component={comp}')
        except Exception:
            pass
    except Exception as exc:
        _export_error_dialog(messagebox.showerror, 'Save Histogram CSV', f'Failed to save histogram CSV:\n{type(exc).__name__}: {exc}', parent=self.root)


def _tab4_has_confirmed_roi(self):
    frame = getattr(self, 'confirmed_roi_frame', None)
    mask = getattr(self, 'roi_mask', None)
    stack = getattr(self, 'recons', None)
    return (isinstance(frame, dict) and getattr(self, 'confirmed_roi_frame_index', None) is not None
            and mask is not None and stack is not None
            and np.asarray(mask).shape == stack.shape[-2:] and np.any(mask))


def _tab4_roi_selection_status(self):
    if _tab4_has_confirmed_roi(self):
        frame = self.confirmed_roi_frame
        message = (f"ROI CONFIRMED | X={frame['xmin']}:{frame['xmax']} | "
                   f"Y={frame['ymin']}:{frame['ymax']} | reference frame {self.confirmed_roi_frame_index+1}")
        draft = getattr(self, 'roi_coords', None)
        if draft is not None and draft != frame:
            message += ' | New selection pending confirmation'
        return message
    draft = getattr(self, 'roi_coords', None)
    if draft is not None:
        return (f"ROI selected | X={draft['xmin']}:{draft['xmax']} | "
                f"Y={draft['ymin']}:{draft['ymax']} | pending confirmation")
    return 'ROI READY'


def _tab4_install_roi_selector(self, fig, ax, canvas, shape):
    h, w = shape
    # Redraws retain the confirmed selection and replace, rather than accumulate,
    # callbacks on a reused canvas.
    for cid in getattr(canvas, '_tab4_roi_selection_cids', ()):
        canvas.mpl_disconnect(cid)
    self._roi_patch = None
    self._roi_confirmed_patch = None
    self._roi_press_xy = None

    def rectangle(coords, color):
        patch = plt.Rectangle((coords['xmin']-.5, coords['ymin']-.5),
            coords['xmax']-coords['xmin']+1, coords['ymax']-coords['ymin']+1,
            fill=False, edgecolor=color, linewidth=2.0, zorder=25)
        ax.add_patch(patch)
        return patch

    confirmed = self.confirmed_roi_frame if _tab4_has_confirmed_roi(self) else None
    if confirmed is not None:
        self._roi_confirmed_patch = rectangle(confirmed, 'lime')
    draft = getattr(self, 'roi_coords', None)
    if draft is not None and draft != confirmed:
        self._roi_patch = rectangle(draft, 'red')

    def clamp_xy(event):
        if event.xdata is None or event.ydata is None:
            return None
        return float(np.clip(event.xdata, 0, w-1)), float(np.clip(event.ydata, 0, h-1))

    def on_press(event):
        if event.inaxes is not ax or getattr(event, 'button', None) != 1:
            return
        xy = clamp_xy(event)
        if xy is None:
            return
        self._roi_press_xy = xy
        if self._roi_patch is not None:
            self._roi_patch.remove()
            self._roi_patch = None
        # A draft never replaces the confirmed mask until Confirm ROI.
        self.roi_coords = None
        self.roi_status_var.set(_tab4_roi_selection_status(self))
        canvas.draw_idle()

    def on_move(event):
        if self._roi_press_xy is None or event.inaxes is not ax:
            return
        xy = clamp_xy(event)
        if xy is None:
            return
        x0, y0 = self._roi_press_xy
        xmin, xmax = sorted((x0, xy[0]))
        ymin, ymax = sorted((y0, xy[1]))
        if self._roi_patch is None:
            self._roi_patch = plt.Rectangle((xmin-.5, ymin-.5), xmax-xmin+1, ymax-ymin+1,
                fill=False, edgecolor='red', linewidth=2.0, zorder=25)
            ax.add_patch(self._roi_patch)
        else:
            self._roi_patch.set_xy((xmin-.5, ymin-.5))
            self._roi_patch.set_width(xmax-xmin+1)
            self._roi_patch.set_height(ymax-ymin+1)
        canvas.draw_idle()

    def on_release(event):
        if self._roi_press_xy is None or getattr(event, 'button', None) != 1:
            return
        if event.inaxes is not ax:
            self._roi_press_xy = None
            self.roi_status_var.set(_tab4_roi_selection_status(self))
            return
        xy = clamp_xy(event)
        if xy is None:
            self._roi_press_xy = None
            return
        x0, y0 = self._roi_press_xy
        self._roi_press_xy = None
        xmin, xmax = sorted((int(round(x0)), int(round(xy[0]))))
        ymin, ymax = sorted((int(round(y0)), int(round(xy[1]))))
        if xmax <= xmin or ymax <= ymin:
            self.roi_coords = None
            if self._roi_patch is not None:
                self._roi_patch.remove()
                self._roi_patch = None
            self.roi_status_var.set(_tab4_roi_selection_status(self))
            canvas.draw_idle()
            return
        self.roi_coords = dict(xmin=xmin, xmax=xmax, ymin=ymin, ymax=ymax)
        if self._roi_patch is not None:
            self._roi_patch.remove()
        self._roi_patch = rectangle(self.roi_coords, 'red')
        self.roi_status_var.set(_tab4_roi_selection_status(self))
        canvas.draw_idle()

    self._roi_press_cid = canvas.mpl_connect('button_press_event', on_press)
    self._roi_move_cid = canvas.mpl_connect('motion_notify_event', on_move)
    self._roi_release_cid = canvas.mpl_connect('button_release_event', on_release)
    canvas._tab4_roi_selection_cids = (self._roi_press_cid, self._roi_move_cid, self._roi_release_cid)


_TAB4_COMPONENT_OLD_REFRESH = CDIWorkflowApp.refresh_roi_image


def _tab4_component_refresh_roi_image(self, *args, **kwargs):
    _tab4_install_controls(self)
    if getattr(self, 'recons', None) is None:
        return _TAB4_COMPONENT_OLD_REFRESH(self, *args, **kwargs)
    comp = _tab4_component_confirmed(self)
    n = _tab4_frame_count(self)
    idx = max(0, min(int(self.roi_index_var.get()), max(0, n-1)))
    self.roi_index_var.set(idx)
    _tab4_sync_slider_and_range(self)
    hist_enabled = _tab4_hist_enabled(self)
    if hist_enabled:
        centers, counts, edges, img, disp, support = _tab4_current_histogram(self, idx, bins=120)
    else:
        img, disp, support, valid = _tab4_component_display_image(self, idx)

    previous_fig = self._figs.get('roi')
    canvas = getattr(self, '_roi_canvas', None)
    expected_axes = 2 if hist_enabled else 1
    reusable = (previous_fig is not None and canvas is not None
                and len(previous_fig.axes) == expected_axes
                and canvas.get_tk_widget().winfo_exists())
    if reusable:
        fig = previous_fig
        for axis in fig.axes:
            axis.clear()
        ax_roi = fig.axes[-1]
        ax_hist = fig.axes[0] if hist_enabled else None
    else:
        if canvas is not None:
            idle = getattr(canvas, '_idle_draw_id', None)
            if idle:
                try:
                    canvas.get_tk_widget().after_cancel(idle)
                    canvas._idle_draw_id = None
                except tk.TclError:
                    pass
        for widget in self.roi_canvas_frame.winfo_children():
            widget.destroy()
        if previous_fig is not None:
            plt.close(previous_fig)
        if hist_enabled:
            fig, (ax_hist, ax_roi) = plt.subplots(1, 2, figsize=(13.0, 6.8), dpi=100,
                gridspec_kw={'width_ratios': [.9, 1.25]})
        else:
            fig, ax_roi = plt.subplots(figsize=(8, 7), dpi=100)
            ax_hist = None
        canvas = FigureCanvasTkAgg(fig, master=self.roi_canvas_frame)
        canvas.get_tk_widget().pack(fill='both', expand=True)
        self._figs['roi'] = fig
        self._roi_canvas = canvas
    self._roi_ax = ax_roi
    if hist_enabled:
        if centers.size:
            ax_hist.plot(centers, counts, color='blue', linewidth=1.8)
            ax_hist.fill_between(centers, counts, color='skyblue', alpha=.25)
        ax_hist.set_title('Confirmed ROI histogram' if _tab4_has_confirmed_roi(self) else 'Support histogram')
        ax_hist.set_xlabel(f'{comp} intensity')
        ax_hist.set_ylabel('Count')
        ax_hist.grid(alpha=.18)
        self.tab4_histogram_status_var.set(f'Line histogram: frame {idx+1}, pixels={int(counts.sum())}')
    else:
        self.tab4_histogram_status_var.set('Histogram: off')
    ax_roi.imshow(disp, cmap='gray', origin='lower', vmin=0, vmax=1, interpolation='nearest')
    if np.any(support) and not np.all(support):
        ax_roi.contour(support.astype(float), levels=[.5], colors='cyan', linewidths=.8)
    ax_roi.set_title(f'{comp} | Frame {idx+1}/{n}\n{self._field_label_for_frame(idx)}', fontsize=10)
    ax_roi.set_xlabel('X pixel')
    ax_roi.set_ylabel('Y pixel')
    ax_roi.set_aspect('equal')
    # Display margin is not additional data; ROI callbacks remain clamped to the array.
    margin = max(2, int(np.ceil(.03 * max(img.shape))))
    ax_roi.set_facecolor('black')
    ax_roi.set_xlim(-.5-margin, img.shape[1]-.5+margin)
    ax_roi.set_ylim(-.5-margin, img.shape[0]-.5+margin)
    edge_support = bool(support[0].any() or support[-1].any()
                        or support[:, 0].any() or support[:, -1].any())
    grid_kind = 'Aligned analysis grid' if getattr(self, '_focused_common_grid', None) else 'Native focused grid'
    if getattr(self,'_analysis_signal_kind','')=='full_retrieved_state':
        grid_kind = 'Full retrieval STATE analysis grid'
    grid_label = f'{grid_kind}: {img.shape[1]} x {img.shape[0]} px'
    if edge_support and not support.all():
        grid_label += ' | Support reaches data edge'
    ax_roi.set_title(f'{comp} | Frame {idx+1}/{n}\n{self._field_label_for_frame(idx)}\n{grid_label}', fontsize=10)
    _tab4_install_roi_selector(self, fig, ax_roi, canvas, img.shape)
    self.roi_status_var.set(_tab4_roi_selection_status(self))
    fig.tight_layout()
    canvas.draw_idle()
    return None


_TAB4_COMPONENT_OLD_CONFIRM = CDIWorkflowApp.confirm_roi


def _tab4_component_confirm_roi(self, *args, **kwargs):
    comp = _tab4_component_confirmed(self)
    _tab4_commit_component_for_downstream(self, comp)
    result = _TAB4_COMPONENT_OLD_CONFIRM(self, *args, **kwargs)
    _tab4_commit_component_for_downstream(self, comp)
    try:
        if getattr(self, 'roi_mask', None) is not None:
            self.build_roi_stack()
    except Exception as exc:
        try:
            self.log(f'Tab 4 component stack rebuild warning: {type(exc).__name__}: {exc}')
        except Exception:
            pass
    try:
        self.roi_resolution_applied = False
        self.roi2_coords = None
        self.roi2_confirmed_coords = None
        self.roi2_stack = None
        self.roi2_mask = None
        self.line_source_stack = None
        self.gauss2d_source_stack = None
    except Exception:
        pass
    try:
        self.proc_status_var.set(f'Primary ROI uses {comp} component for Tabs 6-14. Apply resolution in Tab 6.')
    except Exception:
        pass
    try:
        self.log(f'Tab 4 confirmed ROI using component: {comp}; active analysis stack shape={self.recons.shape}')
    except Exception:
        pass
    return result


CDIWorkflowApp.refresh_roi_image = _tab4_component_refresh_roi_image
CDIWorkflowApp.confirm_roi = _tab4_component_confirm_roi
CDIWorkflowApp._tab4_component_stack = _tab4_component_stack
CDIWorkflowApp._tab4_commit_component_for_downstream = _tab4_commit_component_for_downstream
CDIWorkflowApp._tab4_confirm_component = _tab4_confirm_component
CDIWorkflowApp._tab4_save_histogram_csv = _tab4_save_histogram_csv

try:
    if not hasattr(app, 'analysis_component_name'):
        app.analysis_component_name = 'Real'
    _tab4_install_controls(app)
except Exception as exc:
    try:
        app.log(f'Tab 4 component/histogram install warning: {type(exc).__name__}: {exc}')
    except Exception:
        pass

try:
    app.log('Final patch installed: Tab 4 Confirm Component, line histogram, frame-range CSV export.')
except Exception:
    pass

# END FINAL PATCH: TAB 4 COMPONENT SELECTION + TAB 4 HISTOGRAM LAYOUT


# ============================================================================
# FINAL PATCH: TAB 1 ORDER FOLDER POPUPS + NEW UPLOAD + DUAL AXIS FIELD PLOT
# ----------------------------------------------------------------------------
# Single-pass order choices now prompt for one HDF5 folder, matching the cycle
# choices that prompt for two folders. New Upload clears current analysis state
# and starts a fresh order-driven upload. The metadata plot uses separate axes:
# y1 = Field (mT), y2 = Current (A).
# ============================================================================

_SINGLE_ORDER_LABELS = {
    'Ramp Down (+ to -)': '+ to -',
    'Ramp Up (- to +)': '- to +',
    '+ to -': '+ to -',
    '- to +': '- to +',
}


def _tab1_normalize_order(direction):
    direction = str(direction or '').strip()
    if direction == '+ to -':
        return 'Ramp Down (+ to -)'
    if direction == '- to +':
        return 'Ramp Up (- to +)'
    return direction


def _tab1_is_single_order(direction):
    return _tab1_normalize_order(direction) in ('Ramp Down (+ to -)', 'Ramp Up (- to +)')


def _tab1_order_short_label(direction):
    return _SINGLE_ORDER_LABELS.get(str(direction).strip(), _SINGLE_ORDER_LABELS.get(_tab1_normalize_order(direction), str(direction)))


def _tab1_reset_loaded_state(self):
    for attr in (
        'hdf5_files', 'reconstruction_files', 'reconstruction_paths',
        'reconstruction_metadata_by_path', 'reconstruction_formats',
        'reconstruction_global_indices', '_cycle_global_index_by_path',
        'recons', 'complex_recons', 'real_recons', 'imag_recons',
        'amplitude_recons', 'phase_recons', 'supportmask', 'supportmask2',
        'raw_fields', 'real_fields_mT', 'current_values_A', 'field_value_source',
        'roi_mask', 'roi_coords', 'roi_stack', 'roi_mean', 'roi_std', 'roi_crop',
        'confirmed_roi_frame', 'confirmed_roi_frame_index', 'current_display',
        'current_processed', 'roi2_coords', 'roi2_confirmed_coords', 'roi2_mask',
        'roi2_stack', 'line_source_stack', 'gauss2d_source_stack',
        '_analysis_component_stack_confirmed', '_tab4_component_source_stacks',
        '_tab4_component_source_signature', '_component_frame_normalization_cache',
        '_roi_normalization_signature', '_roi_normalization_records',
        '_component_normalization_layout_cache', '_tab4_normalization_table_signature'
    ):
        try:
            if attr in ('hdf5_files', 'reconstruction_files', 'reconstruction_paths'):
                setattr(self, attr, [])
            elif attr in ('reconstruction_metadata_by_path', '_cycle_global_index_by_path'):
                setattr(self, attr, {})
            elif attr == 'reconstruction_global_indices':
                setattr(self, attr, np.asarray([], dtype=int))
            else:
                setattr(self, attr, None)
        except Exception:
            pass
    try:
        self.roi_resolution_applied = False
    except Exception:
        pass
    try:
        self.current_index = 0
    except Exception:
        pass
    try:
        self.file_list.delete(0, 'end')
    except Exception:
        pass
    for var_attr, text in (
        ('file_count_var', '0 HDF5 files'),
        ('info_var', 'No reconstruction loaded.'),
        ('roi_status_var', 'Ready for ROI selection.'),
        ('proc_status_var', 'Ready'),
        ('proc_field_var', '--'),
    ):
        try:
            getattr(self, var_attr).set(text)
        except Exception:
            pass
    try:
        self.field_label_var.set('Field: --')
    except Exception:
        pass

    table = getattr(self, 'tab4_normalization_reference_table', None)
    if table is not None:
        children = table.get_children()
        if children:
            table.delete(*children)
        table.configure(height=1)
    status = getattr(self, 'tab4_normalization_status_var', None)
    if status is not None:
        status.set('Load reconstructions and confirm a component to find dataset reference limits.')



def _tab1_load_single_folder(self, folder, direction=None, auto_load=False):
    folder = Path(folder).expanduser().resolve()
    if not folder.is_dir():
        messagebox.showerror('HDF5 folder', f'Selected path is not a folder:\n{folder}', parent=self.root)
        return False
    h5_files = sorted(list(folder.rglob('*.h5')) + list(folder.rglob('*.hdf5')), key=self._natural_path_key)
    if not h5_files:
        messagebox.showerror('HDF5 folder', f'No .h5 or .hdf5 files were found under:\n{folder}', parent=self.root)
        return False

    direction = _tab1_normalize_order(direction or self.ramp_direction_var.get())
    calibration = {name: getattr(self, name, None) for name in
                   ('field_calib_file', 'calib_current', 'calib_field_mT', 'field_interpolator',
                    '_magnet_branches', '_magnet_selected_label', '_magnet_calibration_file_key')}
    calibration_label = self.calib_var.get()
    self.new_upload()
    for name, value in calibration.items():
        setattr(self, name, value)
    self.calib_var.set(calibration_label)
    self.magnet_branch_var.set(self._magnet_selected_label or '')
    self.magnet_branch_combo.configure(values=tuple(b['label'] for b in (self._magnet_branches or [])),
        state='readonly' if self._magnet_branches else 'disabled')
    if self.field_calib_file is not None:
        self.log('Retained magnet calibration for ORDER-selected dataset: ' + str(self.field_calib_file))
    try:
        self.ramp_direction_var.set(direction)
        if hasattr(self, 'ramp_direction_combo'):
            self.ramp_direction_combo.set(direction)
    except Exception:
        pass

    # Single-order uploads supersede any previous two-folder cycle state.
    self._cycle_folders_active = False
    self._cycle_folder_prompt_direction = None
    self._cycle_neg_to_pos_dir = None
    self._cycle_pos_to_neg_dir = None
    self._cycle_neg_to_pos_items = []
    self._cycle_pos_to_neg_items = []

    self.data_dir = folder
    try:
        self.data_dir_var.set(str(folder))
    except Exception:
        pass
    self.hdf5_files = h5_files
    self.reconstruction_files = []
    self.reconstruction_paths = []
    self.reconstruction_raw_fields = np.asarray([], dtype=float)
    self.reconstruction_metadata_by_path = {}
    self._discover_reconstruction_files()
    if not getattr(self, 'reconstruction_paths', None):
        messagebox.showerror(
            'No CDI reconstructions',
            'The selected folder contains HDF5 files, but none matched the supported reconstruction formats.\n\n'
            'Supported formats:\n- NEW_V2 focused difference, or full reconstructions/poisson or warmup (confirmation required)\n- Legacy: p_pc + n_pc',
            parent=self.root,
        )
        return False
    self._apply_ramp_direction_order()

    try:
        self.file_list.delete(0, 'end')
        recon_set = {str(Path(fp).resolve()) for fp in self.reconstruction_paths}
        for i, f in enumerate(self.hdf5_files):
            tag = ' [RECON]' if str(Path(f).resolve()) in recon_set else ' [RAW/OTHER]'
            try:
                rel = str(Path(f).relative_to(folder))
            except Exception:
                rel = Path(f).name
            self.file_list.insert('end', f'{i}: {rel}{tag}')
    except Exception:
        pass
    try:
        self.file_count_var.set(f'{len(self.hdf5_files)} HDF5 files | {len(self.reconstruction_paths)} reconstruction files')
        self.info_var.set(f'{len(self.reconstruction_paths)} reconstruction files found for {_tab1_order_short_label(direction)}. Ready to load reconstructions.')
        self.log(f'Selected {_tab1_order_short_label(direction)} folder: {folder} | HDF5={len(self.hdf5_files)} | recon={len(self.reconstruction_paths)}')
    except Exception:
        pass
    try:
        self._update_ramp_direction_status(select_default=False)
        self._last_ramp_direction = direction
    except Exception:
        pass
    if auto_load:
        return bool(self.full_load())
    return True


def _tab1_prompt_single_order_folder(self, direction=None, auto_load=False):
    direction = _tab1_normalize_order(direction or self.ramp_direction_var.get())
    if not _tab1_is_single_order(direction):
        raise ValueError(f'A single-folder upload requires a single-ramp ORDER, got {direction!r}')
    label = _tab1_order_short_label(direction)
    title = f'{label} | Select one reconstruction folder'
    result = {'folder': None}
    popup = tk.Toplevel(self.root)
    popup.withdraw()
    popup.title(title)
    popup.transient(self.root)
    popup.resizable(False, False)
    frame = ttk.Frame(popup, padding=14)
    frame.grid(row=0, column=0, sticky='nsew')
    frame.columnconfigure(0, weight=1)
    ttk.Label(frame, text=title, font=('Arial', 11, 'bold')).grid(
        row=0, column=0, columnspan=2, sticky='w', pady=(0, 14))
    ttk.Label(frame, text=f'FOLDER: {label}', font=('Arial', 10, 'bold')).grid(
        row=1, column=0, columnspan=2, sticky='w', pady=(0, 4))
    folder_var = tk.StringVar(master=popup, value='')
    entry = ttk.Entry(frame, textvariable=folder_var, width=72)
    entry.grid(row=2, column=0, sticky='ew', padx=(0, 6))
    status = tk.StringVar(master=popup, value='No reconstruction folder selected.')
    pulse_job = None

    def close():
        if pulse_job is not None:
            try:
                popup.after_cancel(pulse_job)
            except tk.TclError:
                pass
        if popup.winfo_exists():
            popup.destroy()

    def cancel():
        result['folder'] = None
        close()

    def browse():
        options = {'parent': popup, 'title': f'Select HDF5 folder for {label}', 'mustexist': True}
        previous = folder_var.get().strip()
        if previous:
            options['initialdir'] = previous
        selected = _export_capture_folder(filedialog.askdirectory, **options)
        if selected:
            folder_var.set(selected)
            status.set('Folder selected.')
        popup.lift()
        entry.focus_set()

    def accept():
        selected = folder_var.get().strip()
        if not selected:
            status.set('Please select a reconstruction folder.')
            return
        try:
            folder = Path(selected).expanduser().resolve()
            if not folder.is_dir():
                status.set('The selected folder does not exist.')
                return
            has_hdf5 = any(p.is_file() and p.suffix.lower() in ('.h5', '.hdf5') for p in folder.rglob('*'))
            if not has_hdf5:
                status.set('No .h5 or .hdf5 files found in this folder or its subfolders.')
                return
        except (OSError, RuntimeError, ValueError) as exc:
            status.set(f'Cannot read folder: {exc}')
            return
        result['folder'] = folder
        close()

    ttk.Button(frame, text='Browse...', command=browse).grid(row=2, column=1, sticky='e')
    ttk.Label(frame, textvariable=status, foreground='darkgreen', wraplength=680).grid(
        row=3, column=0, columnspan=2, sticky='w', pady=(14, 8))
    buttons = ttk.Frame(frame)
    buttons.grid(row=4, column=0, columnspan=2, sticky='e', pady=(6, 0))
    ttk.Button(buttons, text='CANCEL', command=cancel).pack(side='right', padx=(6, 0))
    ttk.Button(buttons, text='LOAD FOLDER', command=accept).pack(side='right')
    popup.protocol('WM_DELETE_WINDOW', cancel)
    popup.bind('<Return>', lambda event: accept())
    popup.bind('<Escape>', lambda event: cancel())
    popup.update_idletasks()
    try:
        width = max(640, popup.winfo_reqwidth())
        height = max(190, popup.winfo_reqheight())
        x = self.root.winfo_rootx() + max(0, (self.root.winfo_width() - width) // 2)
        y = self.root.winfo_rooty() + max(0, (self.root.winfo_height() - height) // 2)
        popup.geometry(f'{width}x{height}+{x}+{y}')
        # Match the cycle popup's Windows visibility handling without holding a grab.
        popup.deiconify()
        popup.lift()
        popup.attributes('-topmost', True)
        pulse_job = popup.after(250, lambda: popup.attributes('-topmost', False))
        popup.focus_force()
        entry.focus_set()
        self.root.wait_window(popup)
    finally:
        close()
    if result['folder'] is None:
        return False
    return _tab1_load_single_folder(self, result['folder'], direction=direction, auto_load=auto_load)


_TAB1_OLD_RAMP_DIRECTION_CHANGED = CDIWorkflowApp._ramp_direction_changed


def _tab1_ramp_direction_changed(self, event=None):
    if getattr(self, '_tab1_factory_resetting', False) or getattr(self, '_tab1_folder_dialog_active', False):
        return
    direction = _tab1_normalize_order(self.ramp_direction_var.get())
    if direction == _TAB1_ORDER_PLACEHOLDER or not direction:
        return
    previous = getattr(self, '_last_ramp_direction', _TAB1_ORDER_PLACEHOLDER)
    self.ramp_direction_var.set(direction)
    self._tab1_folder_dialog_active = True
    try:
        if _tab1_is_single_order(direction):
            ok = _tab1_prompt_single_order_folder(self, direction=direction, auto_load=True)
            if not ok:
                fallback = previous if getattr(self, 'recons', None) is not None else _TAB1_ORDER_PLACEHOLDER
                self.ramp_direction_var.set(fallback)
                self.ramp_direction_combo.set(fallback)
            else:
                self._tab1_waiting_for_order = False
            return
        if direction in ('+ to - to +', '- to + to -'):
            result = _TAB1_OLD_RAMP_DIRECTION_CHANGED(self, event)
            if getattr(self, '_cycle_folders_active', False):
                self._tab1_waiting_for_order = False
            return result
        raise ValueError(f'Unsupported ORDER: {direction}')
    except Exception as exc:
        self.log(f'ORDER folder loading failed: {type(exc).__name__}: {exc}')
        messagebox.showerror('ORDER / HDF5 upload', str(exc), parent=self.root)
    finally:
        self._tab1_folder_dialog_active = False


CDIWorkflowApp._ramp_direction_changed = _tab1_ramp_direction_changed


_TAB1_OLD_PLOT_FIELD_CALIBRATION = CDIWorkflowApp._plot_field_calibration


def _tab1_plot_field_calibration_dual_axis(self):
    if self.field_plot_canvas is not None:
        try:
            self.field_plot_canvas.get_tk_widget().destroy()
        except Exception:
            pass
    if self.field_plot_fig is not None:
        try:
            plt.close(self.field_plot_fig)
        except Exception:
            pass

    fig, axes = plt.subplots(nrows=1, ncols=2, figsize=(11.6, 4.8), dpi=100)
    self.field_plot_fig = fig

    if self.calib_current is not None and self.calib_field_mT is not None:
        axes[0].plot(self.calib_current, self.calib_field_mT, 'o-', markersize=4, linewidth=1.5, label='Calibration data')
        xx = np.linspace(float(np.min(self.calib_current)), float(np.max(self.calib_current)), 500)
        if self.field_interpolator is not None:
            axes[0].plot(xx, self.field_interpolator(xx), '-', linewidth=2, label='Interpolation')
        axes[0].set_title(getattr(self,'_magnet_selected_label','') or 'Raw magnet calibration')
        axes[0].set_xlabel('Current (A)')
        axes[0].set_ylabel('Field (mT)')
        axes[0].grid(True, linestyle=':', alpha=0.7)
        axes[0].legend(fontsize=8)
    else:
        axes[0].set_title(getattr(self,'_magnet_selected_label','') or 'Raw magnet calibration')
        axes[0].text(0.5, 0.5, 'Load calibration JSON', ha='center', va='center', transform=axes[0].transAxes)
        axes[0].set_axis_on()
        axes[0].set_xlabel('Current (A)')
        axes[0].set_ylabel('Field (mT)')
        axes[0].grid(True, linestyle=':', alpha=0.35)

    ax_field = axes[1]
    if self.real_fields_mT is not None:
        x = np.arange(len(self.real_fields_mT), dtype=float)
        fields = np.asarray(self.real_fields_mT, dtype=float)
        ax_field.plot(x, fields, 'o-', ms=3, lw=1.2, color='tab:orange', label='Field (mT)')
        ax_field.set_title('Reconstruction metadata')
        ax_field.set_xlabel('Reconstruction index')
        ax_field.set_ylabel('Field (mT)', color='tab:orange')
        ax_field.tick_params(axis='y', labelcolor='tab:orange')
        ax_field.grid(True, linestyle=':', alpha=0.7)

        current = None
        if getattr(self, 'current_values_A', None) is not None and np.any(np.isfinite(self.current_values_A)):
            current = np.asarray(self.current_values_A, dtype=float)
        elif getattr(self, 'raw_fields', None) is not None:
            raw = np.asarray(self.raw_fields, dtype=float)
            # Only use raw values as current when NEW_V2 current metadata was the raw axis.
            if getattr(self, 'field_value_source', None) is not None and np.any(np.asarray(self.field_value_source, dtype=object) == 'calibrated_current_A'):
                current = raw
        if current is not None and len(current) == len(x):
            ax_current = ax_field.twinx()
            ax_current.plot(x, current, 'o-', ms=3, lw=1.0, color='tab:blue', label='Current (A)')
            ax_current.set_ylabel('Current (A)', color='tab:blue')
            ax_current.tick_params(axis='y', labelcolor='tab:blue')
            lines = ax_field.lines + ax_current.lines
            labels = [line.get_label() for line in lines]
            ax_field.legend(lines, labels, fontsize=8, loc='best')
        else:
            ax_field.legend(fontsize=8, loc='best')
    else:
        ax_field.set_title('Reconstruction metadata')
        ax_field.text(0.5, 0.5, 'Load reconstructions', ha='center', va='center', transform=ax_field.transAxes)
        ax_field.set_axis_on()
        ax_field.set_xlabel('Reconstruction index')
        ax_field.set_ylabel('Field (mT)')
        ax_field.grid(True, linestyle=':', alpha=0.35)

    fig.tight_layout()
    self.field_plot_canvas = FigureCanvasTkAgg(fig, master=self.field_plot_frame)
    self.field_plot_canvas.draw()
    self.field_plot_canvas.get_tk_widget().pack(fill='both', expand=True)


CDIWorkflowApp._plot_field_calibration = _tab1_plot_field_calibration_dual_axis


def _tab1_new_upload(self):
    """Clear dataset analysis, retain fixed calibration, then await ORDER selection."""
    if getattr(self, '_tab1_factory_resetting', False):
        return
    _tab8_cancel_batch(self,status=False)
    fixed_calibration = copy.deepcopy(self._fixed_magnet_calibration)
    _analysis_progress_reset_all(self)
    if hasattr(self, 'domain_periodicity'):
        self.domain_periodicity.reset()
    defaults = getattr(self, '_tab1_factory_defaults', None)
    if defaults is None:
        raise RuntimeError('New Upload startup defaults are unavailable. Restart the notebook.')
    self._tab1_factory_resetting = True
    traces = []
    try:
        widgets = list(_tab1_walk_widgets(self.root))
        figures = _tab1_live_figures(self)
        for name, value in list(vars(self).items()):
            if (name.endswith('_job') or name.endswith('_after_id')) and value:
                try:
                    self.root.after_cancel(value)
                except (tk.TclError, TypeError):
                    pass
        for fig in figures:
            canvas = fig.canvas
            idle = getattr(canvas, '_idle_draw_id', None)
            if idle:
                try:
                    self.root.after_cancel(idle)
                    canvas._idle_draw_id = None
                except tk.TclError:
                    pass

        # Restoring controls must not run analysis callbacks on a half-reset dataset.
        var_names = set(defaults['variables'])
        var_names.update(str(v) for v in vars(self).values() if isinstance(v, tk.Variable))
        for name in var_names:
            for ops, command in self.root.tk.call('trace', 'info', 'variable', name):
                self.root.tk.call('trace', 'remove', 'variable', name, ops, command)
                traces.append((name, ops, command))

        for name, value in list(vars(self).items()):
            if name.startswith('_tab1_factory') or name in ('_tab1_folder_dialog_active','_tab8_compute_executor'):
                continue
            if name not in defaults['names']:
                if isinstance(value, tk.Variable):
                    if isinstance(value, tk.BooleanVar):
                        value.set(False)
                    elif isinstance(value, (tk.IntVar, tk.DoubleVar)):
                        value.set(0)
                    else:
                        value.set('')
                    continue
                if isinstance(value, tk.Misc) or callable(value):
                    continue
                # Matplotlib objects remain connected to their widgets; clear their data below.
                if type(value).__module__.startswith('matplotlib'):
                    continue
                if isinstance(value, h5py.File):
                    value.close()
                delattr(self, name)
        for name, value in defaults['state'].items():
            setattr(self, name, copy.deepcopy(value))
        for name, value in defaults['variables'].items():
            if self.root.tk.call('info', 'exists', name):
                self.root.setvar(name, value)
        for attr, value in defaults['variable_attrs'].items():
            var = getattr(self, attr, None)
            if isinstance(var, tk.Variable):
                var.set(value)

        for widget, config in defaults['widget_config']:
            if widget.winfo_exists():
                widget.configure(**config)
        for widget in widgets:
            if not widget.winfo_exists():
                continue
            if isinstance(widget, ttk.Treeview):
                children = widget.get_children()
                if children:
                    widget.delete(*children)
            elif isinstance(widget, tk.Listbox):
                widget.delete(0, 'end')
            elif isinstance(widget, tk.Text):
                state = str(widget.cget('state'))
                widget.configure(state='normal')
                widget.delete('1.0', 'end')
                widget.configure(state=state)
        _tab1_clear_analysis_figures(figures)
        self._pixel_cal_sync_roi_frame()
        _tab10_reset_center_follow(self)
        _tab10_plot_intensity(self)
        _ii_refresh_table(self, 10, None)
        _tab11_sync_intensity(self)
        _tab11_plot_intensity(self)
        self.tab11_plot_views.select(0)
        self.tab10_plot_views.select(0)
        self.ramp_direction_var.set(_TAB1_ORDER_PLACEHOLDER)
        self.ramp_direction_combo.set(_TAB1_ORDER_PLACEHOLDER)
        self._last_ramp_direction = _TAB1_ORDER_PLACEHOLDER
        self._tab1_waiting_for_order = True
        text = 'New Upload: all tabs cleared. Select ORDER to browse HDF5 folders.'
        self.ramp_direction_status_var.set(text)
        self.info_var.set(text)
        self.status_var.set(text)
        _magnet_restore_fixed(self, fixed_calibration)
        if fixed_calibration is not None:
            text = 'New Upload: dataset cleared; fixed calibration retained. Select ORDER to browse HDF5 folders.'
            self.ramp_direction_status_var.set(text)
            self.info_var.set(text)
            self.status_var.set(text)
        self._plot_field_calibration()
        self.nb.select(self.tab_data)
        self.log(text)
    finally:
        for name, ops, command in traces:
            if self.root.tk.call('info', 'exists', name):
                self.root.tk.call('trace', 'add', 'variable', name, ops, command)
        self._tab1_factory_resetting = False


CDIWorkflowApp.new_upload = _tab1_new_upload


def _tab1_install_new_upload_button(self):
    if getattr(self, '_tab1_new_upload_button_installed', False):
        return
    try:
        target = None
        parent = None
        def walk(widget):
            for child in widget.winfo_children():
                yield child
                yield from walk(child)
        for w in walk(self.tab_data):
            try:
                if isinstance(w, ttk.Button) and str(w.cget('text')).strip().lower() == 'test hdf5 (optional)':
                    target = w
                    parent = w.master
                    break
            except Exception:
                pass
        if parent is None:
            parent = getattr(self, 'data_control_canvas', self.tab_data)
        btn = ttk.Button(parent, text='New Upload', command=lambda: self.new_upload())
        if target is not None:
            try:
                btn.pack(fill='x', pady=5, after=target)
            except Exception:
                btn.pack(fill='x', pady=5)
        else:
            btn.pack(fill='x', pady=5)
        self._tab1_new_upload_button = btn
        self._tab1_new_upload_button_installed = True
    except Exception as exc:
        try:
            self.log(f'New Upload button install warning: {type(exc).__name__}: {exc}')
        except Exception:
            pass


