# New Upload uses the startup defaults of this notebook's complete UI, including
# later tabs and component/rotation caches that the old partial reset omitted.
_TAB1_ORDER_PLACEHOLDER = 'Select ORDER...'


def _tab1_walk_widgets(widget):
    for child in widget.winfo_children():
        yield child
        yield from _tab1_walk_widgets(child)


def _tab1_resettable_value(value):
    if isinstance(value, np.ndarray):
        # Axes grids are object arrays; copying them detaches them from Tk canvases.
        return not value.dtype.hasobject or all(_tab1_resettable_value(item) for item in value.flat)
    if value is None or isinstance(value, (str, bytes, bool, int, float, complex, Path, np.generic)):
        return True
    if isinstance(value, (list, tuple, set)):
        return all(_tab1_resettable_value(item) for item in value)
    if isinstance(value, dict):
        return all(_tab1_resettable_value(k) and _tab1_resettable_value(v) for k, v in value.items())
    return isinstance(value, (pd.DataFrame, pd.Series))


def _tab1_live_figures(self):
    figures = {}
    seen = set()

    def visit(value):
        if id(value) in seen:
            return
        seen.add(id(value))
        if isinstance(value, matplotlib.figure.Figure):
            figures[id(value)] = value
        elif type(value).__module__.startswith('matplotlib'):
            figure = getattr(value, 'figure', None)
            if isinstance(figure, matplotlib.figure.Figure):
                figures[id(figure)] = figure
        elif isinstance(value, dict):
            for item in value.values():
                visit(item)
        elif isinstance(value, (list, tuple)):
            for item in value:
                visit(item)

    for name, value in vars(self).items():
        if not name.startswith('_tab1_factory'):
            visit(value)
    return list(figures.values())


def _tab1_clear_analysis_figures(figures):
    for fig in figures:
        for ax in fig.axes:
            # Keep image and line artists alive for the existing update callbacks.
            for image in ax.images:
                image.set_data(np.ma.masked_all((2, 2)))
            for line in ax.lines:
                line.set_data([], [])
            # Colorbar internals must survive for later mappable updates.
            if getattr(ax, '_colorbar', None) is None:
                for artist in list(ax.collections) + list(ax.patches) + list(ax.tables):
                    artist.remove()
            for text in ax.texts:
                text.set_text('')
            ax.set_title('')
            ax.set_xlabel('')
            ax.set_ylabel('')
            legend = ax.get_legend()
            if legend is not None:
                legend.remove()
        for text in fig.texts:
            text.set_text('')
        fig.canvas.draw_idle()


def _tab1_capture_factory_defaults(self):
    state = {}
    variable_attrs = {}
    variables = {}
    config = []
    for name, value in vars(self).items():
        if name.startswith('_tab1_factory'):
            continue
        if isinstance(value, tk.Variable):
            variable_attrs[name] = value.get()
            variables[str(value)] = value.get()
        elif _tab1_resettable_value(value):
            state[name] = copy.deepcopy(value)
    for widget in _tab1_walk_widgets(self.root):
        keys = widget.keys()
        for key in ('textvariable', 'variable'):
            if key in keys:
                name = str(widget.cget(key))
                if name and self.root.tk.call('info', 'exists', name):
                    variables[name] = self.root.getvar(name)
        options = {}
        if isinstance(widget, (tk.Scale, ttk.Scale, tk.Spinbox, ttk.Spinbox)):
            options.update({key: widget.cget(key) for key in ('from', 'to')})
        if isinstance(widget, (tk.Label, ttk.Label)) and not str(widget.cget('textvariable')):
            options['text'] = widget.cget('text')
        if options:
            config.append((widget, options))
    self._tab1_factory_defaults = {
        'state': state, 'names': set(vars(self)), 'variables': variables,
        'variable_attrs': variable_attrs, 'widget_config': config,
    }


def _tab1_install_order_selection_callback(self):
    # Resolve the patched method at selection time and let the dropdown close
    # before opening a native folder picker on Windows.
    self.ramp_direction_combo.bind(
        '<<ComboboxSelected>>',
        lambda event: self.root.after_idle(lambda: self._ramp_direction_changed(event)),
    )


CDIWorkflowApp._tab1_capture_factory_defaults = _tab1_capture_factory_defaults
