# ===== ORIGINAL CELL BREAK =====


# ============================================================================
# TAB 6 EXPORT FIX — EXPORT THE EXACT IMAGE CURRENTLY DISPLAYED IN TAB 6
# ----------------------------------------------------------------------------
# IMPORTANT:
#   Export Image and MP4 must use the SAME pixel array and physical extent
#   that the user is currently seeing in Tab 6.
#
#   The previous exporter rebuilt the ROI stack.  Even when that stack was
#   intended to be authoritative, the exported result could fall back to the
#   original/unrotated processing path.  That is why the displayed rotated
#   image and exported image did not match.
#
#   This patch deliberately does NOT rebuild/rotate an image for export.
#   Instead it:
#       1. asks Tab 6's normal display/update path to show the requested frame;
#       2. reads _proc_image_display.get_array() directly;
#       3. reads the SAME Matplotlib image extent directly;
#       4. renders/saves that exact array + extent.
#
# Scope: Tab 6 export callbacks only.
# ============================================================================

@_auto_open_export
def _tab6_export_exact_display_frame_v24(self, idx):
    """Return the SAME authoritative Tab-6 Primary-ROI stack used by Tab 9.

    IMPORTANT: Tab 9 already fetches the rotated Tab-6 ROI correctly through
    _tab6_downstream_authoritative_primary_stack_v22(). Tab-6 export must use
    that exact same source instead of reading/rebuilding the display artist.
    """
    fetch = globals().get('_tab6_downstream_authoritative_primary_stack_v22')
    if not callable(fetch):
        raise RuntimeError(
            'Tab 6 export cannot access the same authoritative ROI source used by Tab 9.'
        )

    stack, scale, _sig = fetch(self)
    if stack is None:
        raise RuntimeError(
            'Tab 6 Primary ROI is unavailable. Confirm/apply the Primary ROI first.'
        )

    arr = np.asarray(stack, dtype=_intensity_dtype(self))
    if arr.ndim != 3 or arr.shape[0] < 1:
        raise RuntimeError('Invalid Tab 6 authoritative ROI stack.')

    try:
        idx = int(idx)
    except Exception:
        idx = 0
    idx = max(0, min(idx, arr.shape[0] - 1))

    image = np.asarray(arr[idx], dtype=_intensity_dtype(self))
    if image.ndim != 2 or image.size == 0:
        raise RuntimeError('Invalid Tab 6 authoritative ROI frame.')

    # Cache exactly the source/scale used by Tab 9 for the export extent.
    self._tab6_export_authoritative_scale_v24 = (float(scale[0]), float(scale[1]))
    self._tab6_export_authoritative_stack_signature_v24 = _sig
    return image.copy()

@_auto_open_export
def _tab6_export_exact_display_extent_v24(self, image):
    """Return the physical extent using the SAME scale fetched by Tab 9."""
    image = np.asarray(image)
    if image.ndim != 2:
        raise ValueError('Tab-6 export expects a 2-D image.')
    h, w = image.shape[:2]

    scale = getattr(self, '_tab6_export_authoritative_scale_v24', None)
    if scale is None:
        fetch = globals().get('_tab6_downstream_authoritative_primary_stack_v22')
        if not callable(fetch):
            raise RuntimeError('Tab 6 authoritative ROI source is unavailable.')
        stack, scale, _sig = fetch(self)
        if stack is None:
            raise RuntimeError('Tab 6 Primary ROI is unavailable.')
        scale = (float(scale[0]), float(scale[1]))
        self._tab6_export_authoritative_scale_v24 = scale

    sx, sy = map(float, scale)
    if not (np.isfinite(sx) and np.isfinite(sy) and sx > 0 and sy > 0):
        raise RuntimeError('Invalid Tab 6 ROI physical calibration.')

    return (0.0, w * sx, 0.0, h * sy)
@_auto_open_export
def _tab6_export_figure_v24(self, image, idx, dpi=300, title_prefix='ROI'):
    image = np.asarray(image, dtype=float)
    if image.ndim != 2:
        raise ValueError('Tab-6 export expects a 2-D processed ROI image.')

    extent = _tab6_export_exact_display_extent_v24(self, image)

    cmap_name = 'RdBu_r'
    try:
        candidate = str(self.colormap_var.get()).strip()
        if candidate:
            cmap_name = candidate
    except Exception:
        pass

    fig = plt.figure(figsize=(8.6, 7.2), dpi=int(dpi), facecolor='white')
    _intensity_tag_figure(self, fig, idx)
    fig._intensity_owner = self
    fig._intensity_frame_index = int(idx)
    ax = fig.add_axes([0.1, 0.1, 0.76, 0.82])
    cax = fig.add_axes([0.89, 0.1, 0.035, 0.82])

    im = ax.imshow(
        _intensity_display_pixels(self, image),
        cmap=cmap_name,
        origin='lower',
        interpolation='nearest',
        vmin=0.0,
        vmax=1.0,
        aspect='equal',
        extent=extent
    )
    ax.set_xlim(extent[0], extent[1])
    ax.set_ylim(extent[2], extent[3])
    ax.set_xlabel('X (nm)')
    ax.set_ylabel('Y (nm)')
    ax.set_aspect('equal', adjustable='box')
    ax.set_anchor('C')
    ax.grid(False)

    try:
        field = float(self.real_fields_mT[idx])
    except Exception:
        field = None

    if field is None:
        ax.set_title(f'{title_prefix} | Frame {idx + 1}', fontsize=12)
    else:
        ax.set_title(
            f'{title_prefix} | Frame {idx + 1}/{len(self.recons)} | '
            f'Field = {field:+.2f} mT',
            fontsize=12
        )

    cb = fig.colorbar(im, cax=cax)
    cb.set_label('Intensity', rotation=90)
    fig.canvas.draw()
    return fig



@_auto_open_export
def _tab6_save_single_export_exact_display_v24(self, extension, fmt):
    if not getattr(self, 'roi_resolution_applied', False):
        messagebox.showwarning(
            'ROI Resolution Required',
            'Apply SAME CONFIRMED ROI resolution first.',
            parent=self.root
        )
        return

    try:
        dpi = int(self.proc_export_dpi_var.get())
    except Exception:
        dpi = 300

    if dpi not in (150, 300, 600, 900):
        messagebox.showwarning(
            'Export DPI',
            'Select 150, 300, 600 or 900 DPI.',
            parent=self.root
        )
        return

    fig = None
    try:
        folder = os.path.abspath(
            os.path.expanduser(
                str(self.output_var.get()).strip() or 'ROI_exports'
            )
        )
        os.makedirs(folder, exist_ok=True)

        i = max(
            0,
            min(
                int(round(float(self.proc_idx_var.get()))),
                len(self.recons) - 1
            )
        )
        field = float(self.real_fields_mT[i])
        path = os.path.join(
            folder, f'ROI_{i:03d}_{field:+.2f}mT{extension}'
        )

        # EXACT displayed Tab-6 pixels.
        image = _tab6_export_exact_display_frame_v24(self, i)
        fig = _tab6_export_figure_v24(
            self, image, i, dpi=dpi, title_prefix='ROI'
        )

        save_kwargs = {
            'dpi': dpi,
            'bbox_inches': 'tight',
            'pad_inches': 0.08,
            'format': fmt
        }
        if fmt == 'JPEG':
            save_kwargs['facecolor'] = 'white'

        _export_capture_write(fig.savefig, path, **save_kwargs)

        self.proc_status_var.set(
            f'Saved: {path} | {dpi} DPI | EXACT Tab-6 displayed frame'
        )
        self.log(
            f'Tab 6 exact-display export complete: {path} | format={fmt} | '
            f'dpi={dpi}'
        )
        _tab6_open_output_folder(folder)

    except Exception as exc:
        self.proc_status_var.set('Single-image export failed.')
        self.log(f'Tab 6 single-image export failed: {exc}')
        _export_error_dialog(messagebox.showerror, 'Export Error', str(exc), parent=self.root)
    finally:
        if fig is not None:
            try:
                plt.close(fig)
            except Exception:
                pass


@_auto_open_export
def _tab6_batch_export_exact_display_v24(self, extension, fmt):
    if not getattr(self, 'roi_resolution_applied', False):
        messagebox.showwarning(
            'ROI Resolution Required',
            'Apply SAME CONFIRMED ROI resolution first.',
            parent=self.root
        )
        return

    try:
        dpi = int(self.proc_export_dpi_var.get())
    except Exception:
        dpi = 300

    if dpi not in (150, 300, 600, 900):
        messagebox.showwarning(
            'Export DPI',
            'Select 150, 300, 600 or 900 DPI.',
            parent=self.root
        )
        return

    old_idx = None
    try:
        old_idx = int(self.proc_idx_var.get())
    except Exception:
        pass

    try:
        folder = os.path.abspath(
            os.path.expanduser(
                str(self.output_var.get()).strip() or 'ROI_exports'
            )
        )
        os.makedirs(folder, exist_ok=True)

        total = len(self.recons)

        for i in range(total):
            field = float(self.real_fields_mT[i])
            path = os.path.join(
                folder, f'ROI_{i:03d}_{field:+.2f}mT{extension}'
            )
            fig = None
            try:
                # IMPORTANT: each frame is first put through the normal Tab-6
                # display path, then the actual displayed artist is read.
                image = _tab6_export_exact_display_frame_v24(self, i)
                fig = _tab6_export_figure_v24(
                    self, image, i, dpi=dpi, title_prefix='ROI'
                )
                save_kwargs = {
                    'dpi': dpi,
                    'bbox_inches': 'tight',
                    'pad_inches': 0.08,
                    'format': fmt
                }
                if fmt == 'JPEG':
                    save_kwargs['facecolor'] = 'white'
                _export_capture_write(fig.savefig, path, **save_kwargs)
            finally:
                if fig is not None:
                    try:
                        plt.close(fig)
                    except Exception:
                        pass

            self.proc_status_var.set(
                f'Exporting {fmt}: {i + 1}/{total} | {dpi} DPI | '
                f'EXACT Tab-6 displayed frame'
            )
            self.root.update_idletasks()

        self.proc_status_var.set(
            f'Batch {fmt} export complete | {total} images | '
            f'EXACT Tab-6 displayed frames'
        )
        self.log(
            f'Tab 6 batch exact-display export complete: format={fmt} | '
            f'count={total} | dpi={dpi}'
        )
        _tab6_open_output_folder(folder)

    except Exception as exc:
        self.proc_status_var.set('Batch export failed.')
        self.log(f'Tab 6 batch export failed: {exc}')
        _export_error_dialog(messagebox.showerror, 'Batch Export Error', str(exc), parent=self.root)

    finally:
        # Restore the frame the user was viewing before batch export.
        if old_idx is not None:
            try:
                self.proc_idx_var.set(old_idx)
                updater = getattr(self, 'update_processing_view', None)
                if callable(updater):
                    updater()
            except Exception:
                pass


@_auto_open_export
def _tab6_mp4_export_exact_display_v24(self, indices, filename):
    if not getattr(self, 'roi_resolution_applied', False):
        messagebox.showwarning(
            'ROI Resolution Required',
            'Apply SAME CONFIRMED ROI resolution first.',
            parent=self.root
        )
        return

    imageio = _proc_imageio(self)
    if imageio is None:
        return

    try:
        dpi = int(self.proc_export_dpi_var.get())
    except Exception:
        dpi = 300

    if dpi not in (150, 300, 600, 900):
        messagebox.showwarning(
            'Export DPI',
            'Select 150, 300, 600 or 900 DPI.',
            parent=self.root
        )
        return

    folder = os.path.abspath(
        os.path.expanduser(
            str(self.output_var.get()).strip() or 'ROI_exports'
        )
    )
    os.makedirs(folder, exist_ok=True)

    indices = list(indices)
    if not indices:
        messagebox.showwarning(
            'MP4 Export',
            'No frames selected.',
            parent=self.root
        )
        return

    fps = max(1, int(self.fps_var.get()))
    path = os.path.join(folder, filename)

    old_idx = None
    try:
        old_idx = int(self.proc_idx_var.get())
    except Exception:
        pass

    fig = writer = None

    try:
        fig = plt.figure(
            figsize=(8.6, 7.2),
            dpi=dpi,
            facecolor='white'
        )
        _intensity_tag_figure(self, fig, _intensity_default_frame(self, 'processing'))
        ax = fig.add_axes([0.1, 0.1, 0.76, 0.82])
        cax = fig.add_axes([0.89, 0.1, 0.035, 0.82])

        for codec in ('libx264', 'mpeg4', None):
            try:
                kwargs = {
                    'fps': fps,
                    'format': 'ffmpeg',
                    'macro_block_size': None
                }
                if codec is not None:
                    kwargs['codec'] = codec
                writer = _export_capture_writer(imageio.get_writer, path, **kwargs)
                break
            except Exception:
                writer = None

        if writer is None:
            raise RuntimeError('Could not initialize an MP4 encoder.')

        for count, i in enumerate(indices, start=1):
            # EXACT Tab-6 displayed frame for this index.
            _intensity_tag_figure(self, fig, i)
            image = _tab6_export_exact_display_frame_v24(self, i)
            extent = _tab6_export_exact_display_extent_v24(self, image)

            ax.clear()
            cax.clear()

            ax.set_aspect('equal', adjustable='box')

            cmap_name = (
                str(self.colormap_var.get()).strip() or 'RdBu_r'
            )

            im = ax.imshow(
                _intensity_display_pixels(self, image),
                cmap=cmap_name,
                origin='lower',
                interpolation='nearest',
                vmin=0.0,
                vmax=1.0,
                aspect='equal',
                extent=extent
            )

            ax.set_xlim(extent[0], extent[1])
            ax.set_ylim(extent[2], extent[3])
            ax.set_xlabel('X (nm)')
            ax.set_ylabel('Y (nm)')
            ax.set_aspect('equal', adjustable='box')
            ax.set_anchor('C')

            try:
                field = float(self.real_fields_mT[i])
                title = (
                    f'ROI | Frame {i + 1}/{len(self.recons)} | '
                    f'Field = {field:+.2f} mT'
                )
            except Exception:
                title = f'ROI | Frame {i + 1}/{len(self.recons)}'

            ax.set_title(title, fontsize=12)
            cb = fig.colorbar(im, cax=cax)
            cb.set_label('Intensity', rotation=90)

            fig.canvas.draw()
            frame = np.asarray(
                fig.canvas.buffer_rgba()
            )[:, :, :3]

            fh, fw = frame.shape[:2]
            if fh % 2 or fw % 2:
                frame = np.pad(
                    frame,
                    ((0, fh % 2), (0, fw % 2), (0, 0)),
                    mode='edge'
                )

            writer.append_data(frame)

            self.proc_status_var.set(
                f'MP4: {count}/{len(indices)} | {fps} FPS | {dpi} DPI | '
                f'EXACT Tab-6 displayed frame'
            )
            self.root.update_idletasks()

    except Exception as exc:
        self.proc_status_var.set('MP4 export failed.')
        self.log(f'MP4 export failed: {path} | {exc}')
        _export_error_dialog(messagebox.showerror, 'MP4 Error', str(exc), parent=self.root)
        return

    finally:
        close_error = None
        try:
            if writer is not None:
                writer.close()
        except Exception as exc:
            close_error = exc
            _export_mark_failed()
        try:
            if fig is not None:
                plt.close(fig)
        except Exception:
            pass

        # Restore the frame the user was viewing.
        if old_idx is not None:
            try:
                self.proc_idx_var.set(old_idx)
                updater = getattr(self, 'update_processing_view', None)
                if callable(updater):
                    updater()
            except Exception:
                pass

    if close_error is not None:
        self.proc_status_var.set(f'MP4 finalization failed: {close_error}')
        self.log(f'MP4 encoder finalization failed: {path} | {close_error}')
        _export_error_dialog(messagebox.showerror, 'MP4 Error',
            f'MP4 could not be finalized: {close_error}', parent=self.root)
        return

    self.proc_status_var.set(
        f'MP4 saved: {filename} | {fps} FPS | {dpi} DPI | '
        f'EXACT Tab-6 displayed frames'
    )
    self.log(
        f'MP4 exact-display export saved: {path} | frames={len(indices)} | '
        f'fps={fps} | dpi={dpi}'
    )
    _tab6_open_output_folder(folder)

    messagebox.showinfo(
        'MP4 Export',
        f'MP4 successfully saved:\n\n{path}\n\n'
        f'Frames: {len(indices)}\n'
        f'FPS: {fps}\n'
        f'DPI: {dpi}\n'
        f'Exact Tab-6 displayed frames.',
        parent=self.root
    )



def _tab6_single_mp4_exact_display_v24(self):
    i = int(self.proc_idx_var.get())
    frames = max(1, int(self.fps_var.get()) * 2)
    _tab6_mp4_export_exact_display_v24(
        self,
        [i] * frames,
        f'ROI_single_{i:03d}_{self.real_fields_mT[i]:+.2f}mT.mp4'
    )


def _tab6_batch_mp4_exact_display_v24(self):
    try:
        indices, start, end, fps = _proc_get_batch_mp4_indices(self)
        self.fps_var.set(fps)
        _tab6_mp4_export_exact_display_v24(
            self,
            indices,
            f'ROI_frames_{start:04d}-{end:04d}_{fps}fps_axes_colorbar.mp4'
        )
    except Exception as exc:
        messagebox.showerror('Batch MP4 Export', str(exc), parent=self.root)


