"""Calibrated radial Fourier analysis for a masked magnetic-domain image."""
import numpy as np
from scipy import fft as dp_fft
from scipy import ndimage as dp_ndi
from scipy.optimize import curve_fit as dp_curve_fit
from scipy.signal import find_peaks as dp_find_peaks
from scipy.signal import peak_widths as dp_peak_widths
from scipy.signal import fftconvolve as dp_fftconvolve
from scipy.special import j0 as dp_j0
from scipy.spatial import cKDTree as dp_KDTree

DOMAIN_PERIODICITY_REFERENCES = (
    'https://doi.org/10.1063/5.0244024',
    'https://doi.org/10.1038/s41467-019-09934-z',
)


def domain_periodicity_circle(shape, scale, circle):
    return domain_periodicity_roi(shape, scale, circle, 'Circle')


def domain_periodicity_dimensions(scale, size, units='nm'):
    if units not in ('nm', 'px'):
        raise ValueError('ROI units must be nm or px.')
    return (float(size)*float(scale[0]), float(size)*float(scale[1])) if units=='px' else (float(size), float(size))


def domain_periodicity_roi_info(scale, region, roi_shape, units):
    width, height = domain_periodicity_dimensions(scale, region[2], units)
    equal = np.isclose(width, height)
    return dict(roi_shape=roi_shape, roi_units=units, roi_input_size=float(region[2]),
        roi_width_nm=width, roi_height_nm=height, roi_size_nm=min(width, height),
        diameter_nm=width if roi_shape=='Circle' and equal else np.nan,
        side_length_nm=width if roi_shape=='Square' and equal else np.nan,
        diameter_px=float(region[2]) if units=='px' and roi_shape=='Circle' else np.nan,
        side_length_px=float(region[2]) if units=='px' and roi_shape=='Square' else np.nan)


def domain_periodicity_roi(shape, scale, region, roi_shape='Circle', roi_units='nm'):
    sx, sy = map(float, scale)
    cx, cy, diameter = map(float, region)
    if roi_shape not in ('Circle', 'Square'):
        raise ValueError('ROI shape must be Circle or Square.')
    if not all(np.isfinite([sx, sy, cx, cy, diameter])) or min(sx, sy, diameter) <= 0:
        raise ValueError('A finite physical calibration and positive ROI size are required.')
    height, width = shape
    physical_width, physical_height = domain_periodicity_dimensions(scale, diameter, roi_units)
    rx, ry = physical_width/2, physical_height/2
    if cx-rx < -1e-8 or cy-ry < -1e-8 or cx+rx > width*sx+1e-8 or cy+ry > height*sy+1e-8:
        raise ValueError('The ROI must lie inside the Primary ROI bounds.')
    x0 = max(0, int(np.floor((cx-rx)/sx)))
    x1 = min(width, int(np.ceil((cx+rx)/sx)))
    y0 = max(0, int(np.floor((cy-ry)/sy)))
    y1 = min(height, int(np.ceil((cy+ry)/sy)))
    yy, xx = np.indices((y1-y0, x1-x0), dtype=float)
    dx, dy = (xx+x0+.5)*sx-cx, (yy+y0+.5)*sy-cy
    circle_mask = ((dx/rx)**2+(dy/ry)**2 <= 1.) if roi_shape=='Circle' else (
        (dx >= -rx) & (dx < rx) & (dy >= -ry) & (dy < ry))
    return (slice(y0, y1), slice(x0, x1)), circle_mask


def domain_periodicity_measure(image, scale, circle, support=None, settings=None):
    """Return a period plus diagnostic arrays; absent peaks retain NaN measurements.

    Frequencies are cycles/nm. Radial bins are annular means, not annular sums.
    Peak-fit SE is a local model estimate, separate from the spectral peak width.
    """
    cfg = dict(min_period_nm=0., max_period_nm=0., taper_fraction=.2,
               detrend='Mean', padding=2, radial_smoothing=.75,
               min_peak_ratio=3., min_prominence=.1, min_coverage=.7,
               min_cycles=3., peak_model='Lorentzian', method='2D FFT / radial power',
               radial_bin_nm=0., acf_min_r2=.5, particle_polarity='Dark',
               particle_min_nm=20., particle_max_nm=150., particle_separation_nm=40.,
               particle_threshold=.08, particle_snr=3., particle_min_count=6,
               gr_min_peak=1.2, roi_shape='Circle', roi_units='nm')
    if settings:
        cfg.update(settings)
    if cfg['method'] != '2D FFT / radial power':
        if cfg['method'] not in ('2D autocorrelation', 'Particle pair correlation g(r)'):
            raise ValueError('Unknown domain analysis method.')
        return _domain_correlation_measure(image, scale, circle, support, cfg)
    arr = np.asarray(image, dtype=float)
    if arr.ndim != 2:
        raise ValueError('Domain periodicity requires one 2-D intensity image.')
    sx, sy = map(float, scale)
    geometry = domain_periodicity_roi_info(scale, circle, cfg['roi_shape'], cfg['roi_units'])
    diameter = geometry['roi_size_nm']
    crop, circle_mask = domain_periodicity_roi(arr.shape, scale, circle, cfg['roi_shape'], cfg['roi_units'])
    data = arr[crop].copy()
    valid = circle_mask & np.isfinite(data)
    if support is not None:
        support = np.asarray(support, dtype=bool)
        if support.shape != arr.shape:
            raise ValueError('Primary ROI support does not match its processed image.')
        valid &= support[crop]
    min_period = float(cfg['min_period_nm']) or 4*max(sx, sy)
    max_period = float(cfg['max_period_nm']) or diameter/float(cfg['min_cycles'])
    taper = float(cfg['taper_fraction'])
    padding = int(cfg['padding'])
    if not (0 < min_period < max_period and min_period >= 2*max(sx, sy)):
        raise ValueError('Period bounds must be ordered and above the X/Y Nyquist limit.')
    if not .02 <= taper <= .8 or padding not in (1, 2, 4):
        raise ValueError('Edge taper must be 0.02-0.8 and FFT padding must be 1, 2 or 4.')
    for key, low, high in [('min_cycles', 2., 20.), ('min_peak_ratio', 1., 100.),
                           ('min_prominence', .01, 1.), ('min_coverage', .1, 1.),
                           ('radial_smoothing', 0., 3.)]:
        if not low <= float(cfg[key]) <= high:
            raise ValueError(f'Invalid {key}: expected {low:g}-{high:g}.')
    if cfg['detrend'] not in ('Mean', 'Plane'):
        raise ValueError('Background must be Mean or Plane.')
    if cfg['peak_model'] not in ('Lorentzian', 'Gaussian', 'Spectral maximum'):
        raise ValueError('Select Lorentzian, Gaussian or Spectral maximum for the peak.')
    cfg.update(min_period_nm=min_period, max_period_nm=max_period)
    result = dict(valid=False, status='No resolved peak', period_nm=np.nan,
        period_fit_se_nm=np.nan, peak_frequency_cycles_nm=np.nan,
        peak_fwhm_cycles_nm=np.nan, peak_ratio=np.nan, fit_r2=np.nan,
        cycles_in_roi=np.nan, fit_used=False, valid_pixels=int(valid.sum()),
        coverage=float(valid.sum()/max(1, circle_mask.sum())),
        diameter_nm=diameter if cfg['roi_shape']=='Circle' else np.nan,
        side_length_nm=diameter if cfg['roi_shape']=='Square' else np.nan,
        roi_shape=cfg['roi_shape'], roi_size_nm=diameter,
        center_x_nm=float(circle[0]), center_y_nm=float(circle[1]),
        scale_x_nm=sx, scale_y_nm=sy, settings=cfg,
        crop=crop, roi=data, mask=valid, frequency=np.array([]),
        radial_power=np.array([]), fitted_power=np.array([]), fit_frequency=np.array([]),
        power=None, fx=np.array([]), fy=np.array([]), window=None,
        frequency_resolution_cycles_nm=1/diameter)
    result.update(half_period_nm=np.nan, half_period_fit_se_nm=np.nan,
        method=cfg['method'], measurement_kind='Domain periodicity', particle_spacing_nm=np.nan,
        domain_width_nm=np.nan, domain_width_fit_se_nm=np.nan,
        domain_width_hm_low_nm=np.nan, domain_width_hm_high_nm=np.nan,
        period_hm_low_nm=np.nan, period_hm_high_nm=np.nan,
        q_peak_rad_nm=np.nan, peak_fwhm_rad_nm=np.nan,
        azimuth_deg=np.array([]), azimuth_power=np.array([]))
    result.update(geometry)
    if min(data.shape) < 12 or valid.sum() < 128:
        result['status'] = 'ROI too small for a radial spectrum'
        return result
    if result['coverage'] < cfg['min_coverage']:
        result['status'] = 'Insufficient valid support inside circle'
        return result
    # Pad the mask before EDT so support/ROI edges are tapered on every side.
    distance = dp_ndi.distance_transform_edt(np.pad(valid, 1), sampling=(sy, sx))[1:-1, 1:-1]
    window = .5*(1-np.cos(np.pi*np.clip(distance/(diameter*.5*taper), 0., 1.)))
    window *= valid
    values = data[valid]
    weights = window[valid]
    yy, xx = np.indices(data.shape, dtype=float)
    xx = (xx-xx.mean())*sx/diameter
    yy = (yy-yy.mean())*sy/diameter
    if cfg['detrend'] == 'Plane':
        design = np.column_stack((np.ones(values.size), xx[valid], yy[valid]))
        coeff, _, _, _ = np.linalg.lstsq(design*np.sqrt(weights[:, None]), values*np.sqrt(weights), rcond=None)
        background = coeff[0] + coeff[1]*xx + coeff[2]*yy
    else:
        background = np.sum(values*weights)/np.sum(weights)
    centered = np.where(valid, np.where(np.isfinite(data), data, 0.)-background, 0.)
    centered -= np.sum(centered*window)/window.sum()
    signal = centered*window
    result['window'] = window
    if np.sum(signal**2) <= np.finfo(float).eps**2*max(1., np.sum(values**2)):
        result['status'] = 'No intensity variation in ROI'
        return result
    fft_shape = tuple(dp_fft.next_fast_len(n*padding) for n in data.shape)
    if max(fft_shape) > 4096:
        raise ValueError('FFT exceeds 4096 pixels per axis. Reduce circle size or FFT padding.')
    transform = dp_fft.fftshift(dp_fft.fft2(signal, s=fft_shape))
    power = abs(transform)**2 / np.sum(window**2)
    fy = dp_fft.fftshift(dp_fft.fftfreq(fft_shape[0], d=sy))
    fx = dp_fft.fftshift(dp_fft.fftfreq(fft_shape[1], d=sx))
    radius_f = np.hypot(fy[:, None], fx[None, :])
    # Only complete annuli below both directional Nyquist limits are retained.
    upper = min(.5/sx, .5/sy)
    native_df = max(1/(data.shape[1]*sx), 1/(data.shape[0]*sy))
    bin_width = native_df/padding
    bins = np.floor(radius_f/bin_width).astype(int)
    in_range = (radius_f > 0) & (radius_f < upper)
    count = np.bincount(bins[in_range].ravel())
    total = np.bincount(bins[in_range].ravel(), weights=power[in_range].ravel())
    fsum = np.bincount(bins[in_range].ravel(), weights=radius_f[in_range].ravel())
    enough = count >= 6
    freq = fsum[enough]/count[enough]
    radial = total[enough]/count[enough]
    result.update(power=power, fx=fx, fy=fy, frequency=freq, radial_power=radial)
    f_low = max(1/max_period, float(cfg['min_cycles'])/diameter)
    f_high = min(1/min_period, upper)
    search = (freq >= f_low) & (freq <= f_high)
    indices = np.flatnonzero(search)
    if len(indices) < 5:
        result['status'] = 'Period search range has too few radial bins'
        return result
    smooth = dp_ndi.gaussian_filter1d(radial, float(cfg['radial_smoothing'])) if cfg['radial_smoothing'] else radial.copy()
    peaks, properties = dp_find_peaks(smooth, prominence=max(float(smooth[search].max())*float(cfg['min_prominence']), np.finfo(float).tiny))
    candidates = [(j, int(p)) for j, p in enumerate(peaks) if search[p]]
    if not candidates:
        result['status'] = 'No spectral peak inside period bounds'
        return result
    _, peak = max(candidates, key=lambda item: smooth[item[1]])
    if peak <= indices[0] or peak >= indices[-1]:
        result['status'] = 'Peak reaches period search boundary'
        return result
    noise = max(float(np.percentile(radial[search], 30)), np.finfo(float).tiny)
    ratio = float(smooth[peak]/noise)
    result['peak_ratio'] = ratio
    if ratio < float(cfg['min_peak_ratio']):
        result['status'] = 'Weak peak relative to spectral background'
        return result
    widths = dp_peak_widths(smooth, [peak], rel_height=.5)
    left = float(np.interp(widths[2][0], np.arange(len(freq)), freq))
    right = float(np.interp(widths[3][0], np.arange(len(freq)), freq))
    width = max(right-left, bin_width)
    peak_frequency = float(freq[peak])
    result['peak_fwhm_cycles_nm'] = width
    # Fit unsmoothed annular means near the selected dominant peak.
    fit_mask = search & (abs(freq-peak_frequency) <= max(1.4*width, 3*bin_width))
    xf, yf = freq[fit_mask], radial[fit_mask]
    if len(xf) >= 6 and cfg['peak_model'] != 'Spectral maximum':
        unit = native_df
        z = xf/unit
        yn = yf/max(float(yf.max()), np.finfo(float).tiny)
        width_factor = 2.354820045 if cfg['peak_model'] == 'Gaussian' else 2.
        def profile(z, base, amp, mean, size):
            if cfg['peak_model'] == 'Gaussian':
                return base + amp*np.exp(-.5*((z-mean)/size)**2)
            return base + amp/(1+((z-mean)/size)**2)
        try:
            fit, covariance = dp_curve_fit(profile, z, yn,
                p0=(min(.9, noise/yf.max()), max(.1, 1-noise/yf.max()), peak_frequency/unit, max(width/width_factor, bin_width)/unit),
                bounds=([0., 0., max(f_low, xf[0])/unit, bin_width/(2*unit)],
                        [2., 3., min(f_high, xf[-1])/unit, max(2*width, 2*bin_width)/unit]),
                maxfev=6000)
            model = profile(z, *fit)*yf.max()
            residual = np.sum((yf-model)**2)
            ss = np.sum((yf-yf.mean())**2)
            r2 = 1-residual/ss if ss > 0 else np.nan
            if r2 >= .5 and abs(fit[2]*unit-peak_frequency) <= width and f_low+bin_width*.25 < fit[2]*unit < f_high-bin_width*.25:
                peak_frequency = float(fit[2]*unit)
                result.update(fit_used=True, fit_r2=float(r2),
                    peak_fwhm_cycles_nm=float(width_factor*fit[3]*unit),
                    fit_frequency=xf, fitted_power=model)
                if np.all(np.isfinite(covariance)) and covariance[2, 2] >= 0:
                    # Padded/interpolated radial samples do not add independent information.
                    f_se = np.sqrt(covariance[2, 2])*unit*np.sqrt(max(1., native_df/bin_width))
                    result['period_fit_se_nm'] = float(f_se/peak_frequency**2)
        except (ValueError, RuntimeError, FloatingPointError):
            pass
    period = 1/peak_frequency
    cycles = diameter/period
    if cycles < cfg['min_cycles'] or not min_period <= period <= max_period:
        result['status'] = 'Too few periods inside ROI'
        return result
    half_width = result['peak_fwhm_cycles_nm']/2
    result.update(valid=True, status=f'Resolved ({cfg["peak_model"]} peak fit)' if result['fit_used'] else 'Resolved (spectral maximum)',
        period_nm=float(period), peak_frequency_cycles_nm=peak_frequency, cycles_in_roi=float(cycles))
    result.update(half_period_nm=period/2, half_period_fit_se_nm=result['period_fit_se_nm']/2,
        domain_width_nm=period/2, domain_width_fit_se_nm=result['period_fit_se_nm']/2,
        period_hm_low_nm=1/(peak_frequency+half_width),
        period_hm_high_nm=1/(peak_frequency-half_width) if peak_frequency > half_width else np.nan,
        q_peak_rad_nm=2*np.pi*peak_frequency,
        peak_fwhm_rad_nm=2*np.pi*result['peak_fwhm_cycles_nm'])
    result.update(domain_width_hm_low_nm=result['period_hm_low_nm']/2,
        domain_width_hm_high_nm=result['period_hm_high_nm']/2)
    # Angular variation on the selected Fourier annulus diagnoses orientational order.
    band = abs(radius_f-peak_frequency) <= max(half_width, native_df/2)
    angles = (np.degrees(np.arctan2(fy[:, None], fx[None, :]))+180) % 360 - 180
    angular_bins = np.floor((angles[band]+180)/5).astype(int).clip(0, 71)
    counts = np.bincount(angular_bins, minlength=72)
    totals = np.bincount(angular_bins, weights=power[band], minlength=72)
    angular_power = np.divide(totals, counts, out=np.full(72, np.nan), where=counts > 0)
    result.update(azimuth_deg=np.arange(72)*5.-177.5, azimuth_power=angular_power,
        angular_band_half_width_cycles_nm=max(half_width, native_df/2))
    return result


def domain_particle_pair_correlation(centers_nm, mask, scale, bin_nm, cutoff_nm):
    """Translation edge correction using the actual valid center-observation mask."""
    centers = np.asarray(centers_nm, float)
    sx, sy = map(float, scale)
    area = float(mask.sum()*sx*sy)
    if centers.ndim != 2 or centers.shape[1] != 2 or len(centers) < 2:
        raise ValueError('At least two particle centers are required.')
    edges = np.arange(0., cutoff_nm+bin_nm*.5, bin_nm)
    if len(edges) < 6:
        raise ValueError('Correlation range needs at least five distance bins.')
    tree = dp_KDTree(centers)
    if tree.count_neighbors(tree, edges[-1]) > 2000000:
        raise ValueError('Too many particle pairs. Reduce correlation range or increase detection threshold.')
    pairs = tree.query_pairs(edges[-1], output_type='ndarray')
    if len(pairs) == 0:
        return (edges[:-1]+edges[1:])/2, np.zeros(len(edges)-1), np.zeros(len(edges)-1, int)
    delta = centers[pairs[:, 1]]-centers[pairs[:, 0]]
    distance = np.linalg.norm(delta, axis=1)
    overlap = dp_fftconvolve(mask.astype(float), mask[::-1, ::-1].astype(float), mode='full')*sx*sy
    available = dp_ndi.map_coordinates(overlap,
        [delta[:, 1]/sy+mask.shape[0]-1, delta[:, 0]/sx+mask.shape[1]-1], order=1, mode='constant')
    use = available > .05*area
    weights = 2*area**2/(len(centers)*(len(centers)-1)*available[use])
    totals, _ = np.histogram(distance[use], edges, weights=weights)
    counts, _ = np.histogram(distance[use], edges)
    shell_area = np.pi*(edges[1:]**2-edges[:-1]**2)
    return (edges[:-1]+edges[1:])/2, totals/shell_area, counts


def _domain_correlation_measure(image, scale, circle, support, cfg):
    arr = np.asarray(image, float)
    if arr.ndim != 2:
        raise ValueError('Domain analysis requires a 2-D intensity image.')
    sx, sy = map(float, scale)
    geometry = domain_periodicity_roi_info(scale, circle, cfg['roi_shape'], cfg['roi_units'])
    crop, mask = domain_periodicity_roi(arr.shape, scale, circle, cfg['roi_shape'], cfg['roi_units'])
    roi_pixels = int(mask.sum())
    data = arr[crop].copy()
    mask &= np.isfinite(data)
    if support is not None:
        if np.shape(support) != arr.shape:
            raise ValueError('Primary ROI support does not match its processed image.')
        mask &= np.asarray(support, bool)[crop]
    diameter = geometry['roi_size_nm']
    cfg = dict(cfg)
    cfg['min_period_nm'] = float(cfg['min_period_nm']) or 4*max(sx, sy)
    cfg['max_period_nm'] = float(cfg['max_period_nm']) or diameter/3
    lo, hi = cfg['min_period_nm'], cfg['max_period_nm']
    dr = float(cfg['radial_bin_nm']) or max(sx, sy)
    if not (np.isfinite([lo, hi, dr]).all() and 2*max(sx, sy) <= lo < hi <= diameter/2 and dr >= max(sx, sy)):
        raise ValueError('Use ordered period bounds up to half the ROI size; radial bins must be at least one physical pixel.')
    if not .1 <= float(cfg['min_coverage']) <= 1 or not 0 <= float(cfg['radial_smoothing']) <= 3:
        raise ValueError('Invalid coverage or radial smoothing.')
    if cfg['detrend'] not in ('Mean', 'Plane') or not .02 <= float(cfg['taper_fraction']) <= .8:
        raise ValueError('Select Mean/Plane background and an edge taper from 0.02 to 0.8.')
    result = dict(valid=False, status='No resolved correlation peak', method=cfg['method'],
        measurement_kind='Particle center spacing' if cfg['method'].startswith('Particle') else 'Domain periodicity',
        period_nm=np.nan, period_fit_se_nm=np.nan, half_period_nm=np.nan, half_period_fit_se_nm=np.nan,
        domain_width_nm=np.nan, domain_width_fit_se_nm=np.nan, domain_width_hm_low_nm=np.nan,
        domain_width_hm_high_nm=np.nan, period_hm_low_nm=np.nan, period_hm_high_nm=np.nan,
        particle_spacing_nm=np.nan, peak_frequency_cycles_nm=np.nan, peak_fwhm_cycles_nm=np.nan,
        q_peak_rad_nm=np.nan, peak_fwhm_rad_nm=np.nan, peak_ratio=np.nan, fit_r2=np.nan,
        cycles_in_roi=np.nan, fit_used=False, valid_pixels=int(mask.sum()),
        coverage=float(mask.sum()/max(1, roi_pixels)),
        diameter_nm=diameter if cfg['roi_shape']=='Circle' else np.nan,
        side_length_nm=diameter if cfg['roi_shape']=='Square' else np.nan,
        roi_shape=cfg['roi_shape'], roi_size_nm=diameter,
        center_x_nm=float(circle[0]), center_y_nm=float(circle[1]),
        scale_x_nm=sx, scale_y_nm=sy, settings=cfg, crop=crop, roi=data, mask=mask,
        frequency=np.array([]), radial_power=np.array([]), fitted_power=np.array([]), fit_frequency=np.array([]),
        power=None, fx=np.array([]), fy=np.array([]), window=None, azimuth_deg=np.array([]), azimuth_power=np.array([]),
        correlation_map=None, lag_x_nm=np.array([]), lag_y_nm=np.array([]),
        distance_nm=np.array([]), correlation=np.array([]), correlation_fit=np.array([]),
        particle_centers_nm=np.empty((0, 2)), particle_count=0, pair_counts=np.array([], int),
        frequency_resolution_cycles_nm=1/diameter, nearest_neighbor_mean_nm=np.nan, nearest_neighbor_sd_nm=np.nan)
    result.update(geometry)
    if mask.sum() < 128 or min(data.shape) < 12:
        result['status'] = 'ROI too small for correlation analysis'
        return result
    if result['coverage'] < cfg['min_coverage']:
        result['status'] = 'Insufficient valid support inside circle'
        return result
    values = data[mask]
    if np.ptp(values) <= np.finfo(float).eps*max(1., np.max(abs(values))):
        result['status'] = 'No intensity variation in ROI'
        return result
    if cfg['method'].startswith('Particle'):
        return _domain_particle_measure(result, data, mask, scale, cfg, dr)
    return _domain_autocorrelation_measure(result, data, mask, scale, cfg, dr)


def _domain_autocorrelation_measure(result, data, mask, scale, cfg, dr):
    sx, sy = map(float, scale)
    if not 0 < float(cfg['acf_min_r2']) < 1:
        raise ValueError('Autocorrelation minimum fit R-squared must be between 0 and 1.')
    diameter = result['roi_size_nm']
    distance = dp_ndi.distance_transform_edt(np.pad(mask, 1), sampling=(sy, sx))[1:-1, 1:-1]
    window = mask*.5*(1-np.cos(np.pi*np.clip(distance/(diameter*.5*cfg['taper_fraction']), 0, 1)))
    yy, xx = np.indices(data.shape, dtype=float)
    design = np.column_stack((np.ones(mask.sum()), xx[mask]*sx/diameter, yy[mask]*sy/diameter))
    if cfg['detrend'] == 'Plane':
        weights = np.sqrt(window[mask])
        coeff = np.linalg.lstsq(design*weights[:, None], data[mask]*weights, rcond=None)[0]
        background = coeff[0]+coeff[1]*xx*sx/diameter+coeff[2]*yy*sy/diameter
    else:
        background = np.average(data[mask], weights=window[mask])
    signal = np.where(mask, np.nan_to_num(data)-background, 0)*window
    overlap = dp_fftconvolve(window, window[::-1, ::-1], mode='full')
    numerator = dp_fftconvolve(signal, signal[::-1, ::-1], mode='full')
    origin = (data.shape[0]-1, data.shape[1]-1)
    covariance = np.divide(numerator, overlap, out=np.full_like(numerator, np.nan), where=overlap > .15*overlap[origin])
    if not np.isfinite(covariance[origin]) or covariance[origin] <= np.finfo(float).tiny:
        result['status'] = 'No intensity variation after background removal'
        return result
    covariance /= covariance[origin]
    lag_x = np.arange(-data.shape[1]+1, data.shape[1])*sx
    lag_y = np.arange(-data.shape[0]+1, data.shape[0])*sy
    radius = np.hypot(lag_y[:, None], lag_x[None, :])
    use = np.isfinite(covariance) & (radius <= diameter/2)
    indices = np.floor(radius[use]/dr).astype(int)
    counts = np.bincount(indices)
    enough = counts > 0
    r = np.bincount(indices, weights=radius[use])[enough]/counts[enough]
    acf = np.bincount(indices, weights=covariance[use])[enough]/counts[enough]
    result.update(correlation_map=covariance, lag_x_nm=lag_x, lag_y_nm=lag_y,
        distance_nm=r, correlation=acf, window=window)
    fit_use = (r >= 2*dr) & (r <= diameter/2)
    x, y = r[fit_use], acf[fit_use]
    if len(x) < 12 or np.max(y)-np.min(y) < .1:
        result['status'] = 'No resolved autocorrelation oscillations'
        return result
    lo, hi = cfg['min_period_nm'], cfg['max_period_nm']
    def model(x, base, amplitude, period, decay):
        return base+amplitude*dp_j0(2*np.pi*x/period)*np.exp(-(x/decay)**2)
    candidates = []
    for period in np.geomspace(lo*1.001, hi*.999, 64):
        basis = dp_j0(2*np.pi*x/period)*np.exp(-(x/diameter)**2)
        coeff = np.linalg.lstsq(np.column_stack((np.ones(len(x)), basis)), y, rcond=None)[0]
        candidates.append((np.sum((y-coeff[0]-coeff[1]*basis)**2), period))
    guess = min(candidates)[1]
    try:
        fit, cov = dp_curve_fit(model, x, y, p0=(0., 1., guess, diameter),
            bounds=([-.5, .05, lo, max(2*dr, lo/2)], [.5, 2., hi, diameter*10]), maxfev=6000)
    except (ValueError, RuntimeError):
        result['status'] = 'Autocorrelation model fit failed'
        return result
    predicted = model(x, *fit)
    r2 = 1-np.sum((y-predicted)**2)/max(np.sum((y-y.mean())**2), np.finfo(float).tiny)
    result.update(fit_r2=float(r2), correlation_fit=model(r, *fit), acf_decay_nm=float(fit[3]))
    if r2 < cfg['acf_min_r2'] or fit[1] < .15 or not lo*1.01 < fit[2] < hi*.99:
        result['status'] = 'Autocorrelation fit is weak or reaches period bounds'
        return result
    period = float(fit[2])
    se = float(np.sqrt(cov[2, 2])) if np.isfinite(cov[2, 2]) and cov[2, 2] >= 0 else np.nan
    result.update(valid=True, status='Resolved (damped-Bessel autocorrelation fit)', fit_used=True,
        period_nm=period, period_fit_se_nm=se, half_period_nm=period/2, half_period_fit_se_nm=se/2,
        domain_width_nm=period/2, domain_width_fit_se_nm=se/2,
        peak_frequency_cycles_nm=1/period, q_peak_rad_nm=2*np.pi/period, cycles_in_roi=diameter/period)
    return result


def _domain_particle_measure(result, data, mask, scale, cfg, dr):
    from skimage.feature import blob_log
    sx, sy = map(float, scale)
    dmin, dmax, separation = (float(cfg[k]) for k in ('particle_min_nm', 'particle_max_nm', 'particle_separation_nm'))
    threshold, snr = float(cfg['particle_threshold']), float(cfg['particle_snr'])
    minimum = int(cfg['particle_min_count'])
    if not (2*max(sx, sy) <= dmin < dmax < result['roi_size_nm']/2 and separation > 0
            and 0 < threshold < 1 and 0 <= snr <= 100 and minimum >= 3 and cfg['gr_min_peak'] > 1):
        raise ValueError('Invalid particle size, separation, threshold, SNR or minimum count.')
    if cfg['particle_polarity'] not in ('Dark', 'Bright'):
        raise ValueError('Choose Dark or Bright particle polarity.')
    edge = dp_ndi.distance_transform_edt(np.pad(mask, 1), sampling=(sy, sx))[1:-1, 1:-1]
    center_mask = mask & (edge >= dmax/2)
    if center_mask.sum() < 128:
        result['status'] = 'Particle diameter leaves insufficient center-observation area'
        return result
    fill = float(np.median(data[mask]))
    safe = np.where(mask, data, fill)
    sign = -1. if cfg['particle_polarity'] == 'Dark' else 1.
    smooth = dp_ndi.gaussian_filter(safe, (max(.5, dmin/(8*sy)), max(.5, dmin/(8*sx))))
    background = dp_ndi.gaussian_filter(safe, (dmax/sy, dmax/sx))
    contrast = sign*(smooth-background)
    positive = np.maximum(contrast, 0)
    peak = float(np.max(positive[center_mask]))
    if peak <= np.finfo(float).eps*max(1., abs(fill)):
        result['status'] = 'No particle contrast of selected polarity'
        return result
    normalized = np.where(mask, positive/peak, 0.)
    noise_data = (safe-smooth)[mask]
    noise = max(1.4826*np.median(abs(noise_data-np.median(noise_data))), np.finfo(float).eps*max(1., abs(fill)))
    blobs = blob_log(normalized, min_sigma=(dmin/(2*np.sqrt(2)*sy), dmin/(2*np.sqrt(2)*sx)),
        max_sigma=(dmax/(2*np.sqrt(2)*sy), dmax/(2*np.sqrt(2)*sx)), num_sigma=16,
        threshold=threshold, overlap=.5, exclude_border=False)
    candidates = []
    for blob in blobs:
        row, col = np.rint(blob[:2]).astype(int)
        if center_mask[row, col] and contrast[row, col] >= snr*noise:
            candidates.append((float(contrast[row, col]), float(blob[1]), float(blob[0])))
    chosen = []
    for _, x, y in sorted(candidates, reverse=True):
        center = np.array([(x+.5)*sx, (y+.5)*sy])
        if not chosen or min(np.linalg.norm(center-c) for c in chosen) >= separation:
            chosen.append(center)
        if len(chosen) > 3000:
            raise ValueError('More than 3000 particles detected. Tighten detection controls.')
    centers = np.asarray(chosen, float).reshape(-1, 2)
    result.update(particle_count=len(centers), particle_centers_nm=centers,
        center_observation_area_nm2=float(center_mask.sum()*sx*sy))
    if len(centers) < minimum:
        result['status'] = f'Too few particles: {len(centers)} detected; at least {minimum} required'
        return result
    nearest = dp_KDTree(centers).query(centers, k=2)[0][:, 1]
    r, gr, counts = domain_particle_pair_correlation(centers, center_mask, scale, dr, result['roi_size_nm']/2)
    result.update(distance_nm=r, correlation=gr, pair_counts=counts,
        nearest_neighbor_mean_nm=float(nearest.mean()), nearest_neighbor_sd_nm=float(nearest.std(ddof=1)))
    smooth_gr = dp_ndi.gaussian_filter1d(gr, float(cfg['radial_smoothing'])) if cfg['radial_smoothing'] else gr
    peaks, props = dp_find_peaks(smooth_gr, prominence=max(.1, float(cfg['min_prominence'])))
    candidates = [int(p) for p in peaks if cfg['min_period_nm'] < r[p] < cfg['max_period_nm']
        and smooth_gr[p] >= cfg['gr_min_peak'] and counts[p] >= 3]
    if not candidates:
        result['status'] = 'No resolved first-neighbor pair-correlation peak'
        return result
    peak_index = candidates[0]
    spacing = float(r[peak_index])
    widths = dp_peak_widths(smooth_gr, [peak_index], rel_height=.5)
    low = float(np.interp(widths[2][0], np.arange(len(r)), r))
    high = float(np.interp(widths[3][0], np.arange(len(r)), r))
    result.update(valid=True, status='Resolved particle spacing; domain width unavailable',
        period_nm=spacing, particle_spacing_nm=spacing, period_hm_low_nm=low,
        period_hm_high_nm=high, peak_ratio=float(smooth_gr[peak_index]))
    return result


from matplotlib.figure import Figure


def domain_periodicity_fft_limits(result, zoom=True):
    """Choose display bounds from this frame, without changing its measurement."""
    fx, fy = np.asarray(result['fx']), np.asarray(result['fy'])
    dx, dy = abs(fx[1]-fx[0]), abs(fy[1]-fy[0])
    full = ((fx[0]-dx/2, fx[-1]+dx/2), (fy[0]-dy/2, fy[-1]+dy/2))
    if not zoom:
        return full
    peak = result.get('peak_frequency_cycles_nm', np.nan)
    width = result.get('peak_fwhm_cycles_nm', np.nan)
    if not result.get('valid') or not np.isfinite(peak) or peak <= 0:
        frequency = np.asarray(result['frequency'])
        radial = np.asarray(result['radial_power'])
        # Exclude the DC/window lobe; a rejected fit can still have a clear ring.
        span = result.get('roi_size_nm', np.nan)
        minimum = 1.5/span if np.isfinite(span) and span > 0 else 3*max(dx, dy)
        usable = np.flatnonzero(np.isfinite(radial) & (radial > 0)
            & np.isfinite(frequency) & (frequency >= minimum))
        if len(usable) < 4:
            return full
        tail = radial[usable[-max(3, len(usable)//4):]]
        background = float(np.median(tail))
        noise = float(1.4826*np.median(abs(tail-background)))
        index = usable[np.argmax(radial[usable])]
        height = radial[index]-background
        if height <= max(2*background, 3*noise, np.finfo(float).tiny):
            return full
        peak = frequency[index]
        half = background+height/2
        left = right = index
        while left > usable[0] and radial[left-1] >= half:
            left -= 1
        while right < usable[-1] and radial[right+1] >= half:
            right += 1
        width = frequency[right]-frequency[left]
    width = width if np.isfinite(width) and width >= 0 else 0.
    limit = max(2.5*peak, peak+2*width, 3*max(dx, dy))
    return tuple((max(low, -limit), min(high, limit)) for low, high in full)


class DomainPeriodicityPanel:
    """Tab 12: a fixed physical ROI and per-frame Fourier measurements."""

    def __init__(self, app):
        self.app = app
        self.root = app.root
        self.stack = self.support = self.scale = self.source_token = None
        self.circle = self.pending_circle = None
        self.selecting = False
        self.results = {}
        self.last_result = None
        self.last_frame = None
        self.batch_job = self.play_job = self.redraw_job = None
        self.queue = []
        self.muted = True
        self.frame = tk.IntVar(value=0)
        self.fps = tk.IntVar(value=5)
        self.first = tk.IntVar(value=1)
        self.last = tk.IntVar(value=1)
        self.step = tk.IntVar(value=1)
        self.diameter = tk.StringVar(value='1000')
        self.side_length = tk.StringVar(value='1000')
        self.pixel_diameter = tk.StringVar(value='100')
        self.pixel_side_length = tk.StringVar(value='100')
        self.roi_units = tk.StringVar(value='nm')
        self.roi_shape = tk.StringVar(value='Circle')
        self.auto_range = tk.BooleanVar(value=True)
        self.min_period = tk.StringVar(value='40')
        self.max_period = tk.StringVar(value='400')
        self.detrend = tk.StringVar(value='Mean')
        self.method = tk.StringVar(value='2D FFT / radial power')
        self.radial_bin = tk.StringVar(value='0')
        self.acf_r2 = tk.DoubleVar(value=.5)
        self.particle_polarity = tk.StringVar(value='Dark')
        self.particle_min = tk.StringVar(value='40')
        self.particle_max = tk.StringVar(value='200')
        self.particle_separation = tk.StringVar(value='40')
        self.particle_threshold = tk.DoubleVar(value=.08)
        self.particle_snr = tk.DoubleVar(value=3.)
        self.particle_min_count = tk.IntVar(value=6)
        self.gr_min_peak = tk.DoubleVar(value=1.2)
        self.peak_model = tk.StringVar(value='Lorentzian')
        self.error_mode = tk.StringVar(value='Spectral half-maximum span')
        self.frequency_unit = tk.StringVar(value='f (cycles/nm)')
        self.peak_zoom = tk.BooleanVar(value=True)
        self.taper = tk.DoubleVar(value=.2)
        self.padding = tk.IntVar(value=2)
        self.smoothing = tk.DoubleVar(value=.75)
        self.peak_ratio = tk.DoubleVar(value=3.)
        self.prominence = tk.DoubleVar(value=.1)
        self.coverage = tk.DoubleVar(value=.7)
        self.cycles = tk.DoubleVar(value=3.)
        self.advanced = tk.BooleanVar(value=False)
        self.status = tk.StringVar(value='Primary ROI unavailable')
        self.frame_label = tk.StringVar(value='Frame -- | Field --')
        self.scale_label = tk.StringVar(value='Scale -- nm/pixel')
        self.result_label = tk.StringVar(value='Domain periodicity -- nm\nDomain width (period/2) -- nm')
        self.frame_widget = ttk.Frame(app.nb)
        app.tab_domain_periodicity = self.frame_widget
        app.nb.insert(11, self.frame_widget, text='12. Domain Periodicity')
        self._build()
        for variable in (self.auto_range, self.min_period, self.max_period, self.detrend,
                         self.taper, self.padding, self.smoothing, self.peak_ratio,
                         self.prominence, self.coverage, self.cycles, self.peak_model,
                         self.method, self.radial_bin, self.acf_r2, self.particle_polarity,
                         self.particle_min, self.particle_max, self.particle_separation,
                         self.particle_threshold, self.particle_snr, self.particle_min_count, self.gr_min_peak):
            variable.trace_add('write', self.settings_changed)
        for variable in (self.error_mode, self.frequency_unit, self.peak_zoom):
            variable.trace_add('write', self.plot_changed)
        self.diameter.trace_add('write', self.diameter_changed)
        self.side_length.trace_add('write', self.diameter_changed)
        self.pixel_diameter.trace_add('write', self.diameter_changed)
        self.pixel_side_length.trace_add('write', self.diameter_changed)
        self.roi_shape.trace_add('write', self.shape_changed)
        self.roi_units.trace_add('write', self.shape_changed)
        self.muted = False
        self.draw_analysis()
        self.draw_tracking()
        self.tab_binding = app.nb.bind('<<NotebookTabChanged>>', self.on_tab, add='+')

    def _build(self):
        self.panes = ttk.Panedwindow(self.frame_widget, orient='horizontal')
        self.panes.pack(fill='both', expand=True)
        left, right = ttk.Frame(self.panes), ttk.Frame(self.panes, width=390)
        self.panes.add(left, weight=7)
        self.panes.add(right, weight=3)
        self.views = ttk.Notebook(left)
        self.views.pack(fill='both', expand=True)
        analysis, tracking, angular, table = (ttk.Frame(self.views) for _ in range(4))
        for widget, title in [(analysis, 'ROI / Analysis'), (tracking, 'Width / Periodicity vs Field'),
                              (angular, 'Angular Spectrum'), (table, 'Results')]:
            self.views.add(widget, text=title)
        self.figure = Figure(figsize=(8.2, 7.2), dpi=100, constrained_layout=True)
