    def token(self):
        app = self.app
        values = []
        for name in ('filter_var', 'strength_var', 'contrast_var', 'brightness_var'):
            value = getattr(app, name, None)
            values.append(value.get() if hasattr(value, 'get') else None)
        try:
            base_scale = float(app._proc_get_tab5_base_pixel_size())
        except Exception:
            base_scale = None
        return (id(getattr(app, 'recons', None)), id(getattr(app, 'roi_stack', None)),
            id(getattr(app, 'local_mask', None)), tuple(values), base_scale,
            getattr(app, 'original_roi_w', None), getattr(app, 'original_roi_h', None),
            bool(getattr(app, 'roi_resolution_applied', False)),
            bool(getattr(app, '_tab6_analysis_rotation_committed', False)),
            getattr(app, '_tab6_analysis_rotation_angle', 0.),
            getattr(app, '_tab6_analysis_rotation_version', 0))

    def check_source(self):
        if self.stack is None:
            self.status.set('Fetch the processed Primary ROI from Tab 6.')
            return False
        if self.source_token != self.token():
            self.reset()
            self.status.set('Tab 6 source or calibration changed. Fetch Primary ROI again.')
            return False
        return True

    def fetch(self):
        self.cancel(quiet=True)
        self.pause()
        try:
            if not getattr(self.app, 'roi_resolution_applied', False):
                raise ValueError('Apply the confirmed Primary ROI resolution in Tab 6 first.')
            stack, scale, signature = _tab6_downstream_authoritative_primary_stack_v22(self.app)
            if stack is None or scale is None or not np.all(np.isfinite(scale)) or min(scale) <= 0:
                raise ValueError('Tab 6 processed Primary ROI and physical calibration are required.')
            mask = getattr(self.app, '_tab6_base_mask', None)
            if mask is None:
                mask = getattr(self.app, 'local_mask', None)
            if mask is not None:
                mask = np.asarray(mask, dtype=bool)
                if getattr(self.app, '_tab6_analysis_rotation_committed', False):
                    angle = float(getattr(self.app, '_tab6_analysis_rotation_angle', 0.))
                    if abs(angle) > 1e-12:
                        mask = _tab6_final_rotate_array(self.app, mask.astype(float), angle=angle, order=0) > .5
                        x0, x1, y0, y1 = self.app._tab6_auth_bbox_v21
                        mask = mask[y0:y1, x0:x1]
                if mask.shape != stack.shape[1:]:
                    raise ValueError('Tab 6 support geometry does not match its processed Primary ROI.')
            self.stack = np.array(stack, dtype=_intensity_dtype(self), copy=True)
            self.support = None if mask is None else mask.copy()
            self.scale = tuple(map(float, scale))
            self.source_token = self.token()
            self.source_description = repr(signature)
            self.circle = self.pending_circle = None
            self.selecting = False
            self.clear_results(quiet=True)
            n, h, w = self.stack.shape
            self.muted = True
            self.diameter.set(f'{.8*min(w*scale[0], h*scale[1]):.6g}')
            self.side_length.set(self.diameter.get())
            self.pixel_diameter.set(f'{.8*min(w,h):.6g}')
            self.pixel_side_length.set(self.pixel_diameter.get())
            self.particle_min.set(f'{4*max(scale):.6g}')
            self.particle_max.set(f'{min(20*max(scale), .3*min(self.roi_physical_size())):.6g}')
            self.particle_separation.set(f'{4*max(scale):.6g}')
            self.frame.set(min(max(self.frame.get(), 0), n-1))
            self.first.set(1); self.last.set(n); self.step.set(1)
            self.slider.configure(to=n-1, state='normal')
            self.frame.set((n - 1) // 2)
            for spin in self.range_spins:
                spin.configure(to=n)
            self.muted = False
            self.scale_label.set(f'X: {scale[0]:.5g} | Y: {scale[1]:.5g} nm/pixel')
            self.status.set(f'Primary ROI loaded: {n} frames, {w} x {h} pixels.')
            self.update_auto_range()
            self.draw_analysis(); self.draw_tracking(); self.refresh_table()
            self.views.select(0)
            return True
        except Exception as exc:
            self.muted = False
            self.reset()
            self.status.set(f'Primary ROI unavailable: {exc}')
            return False


    def update_auto_range(self):
        if not self.auto_range.get() or self.scale is None:
            return
        try:
            diameter = min(self.roi_physical_size())
            max_period = diameter/float(self.cycles.get())
            min_period = 4*max(self.scale)
        except (ValueError, tk.TclError, ZeroDivisionError):
            return
        previous = self.muted
        self.muted = True
        self.min_period.set(f'{min_period:.7g}')
        self.max_period.set(f'{max_period:.7g}')
        self.muted = previous

    def settings(self):
        self.update_auto_range()
        cfg = dict(min_period_nm=float(self.min_period.get()), max_period_nm=float(self.max_period.get()),
            detrend=self.detrend.get(), taper_fraction=float(self.taper.get()), padding=int(self.padding.get()),
            radial_smoothing=float(self.smoothing.get()), min_peak_ratio=float(self.peak_ratio.get()),
            min_prominence=float(self.prominence.get()), min_coverage=float(self.coverage.get()),
            min_cycles=float(self.cycles.get()), peak_model=self.peak_model.get(), method=self.method.get(),
            roi_shape=self.roi_shape.get(), roi_units=self.roi_units.get())
        if self.method.get() != '2D FFT / radial power':
            cfg.update(radial_bin_nm=float(self.radial_bin.get()), acf_min_r2=float(self.acf_r2.get()))
        if self.method.get().startswith('Particle'):
            cfg.update(particle_polarity=self.particle_polarity.get(), particle_min_nm=float(self.particle_min.get()),
                particle_max_nm=float(self.particle_max.get()), particle_separation_nm=float(self.particle_separation.get()),
                particle_threshold=float(self.particle_threshold.get()), particle_snr=float(self.particle_snr.get()),
                particle_min_count=int(self.particle_min_count.get()), gr_min_peak=float(self.gr_min_peak.get()))
        return cfg

    def plot_changed(self, *args):
        if not self.muted:
            self.schedule_draw()
            self.draw_tracking()

    def settings_changed(self, *args):
        if self.muted:
            return
        self.update_method_controls()
        self.min_entry.configure(state='disabled' if self.auto_range.get() else 'normal')
        self.max_entry.configure(state='disabled' if self.auto_range.get() else 'normal')
        self.update_auto_range()
        self.clear_results(quiet=True)
        self.status.set('Analysis settings changed. Results cleared.')
        self.schedule_draw()

    def update_method_controls(self):
        is_fft = self.method.get() == '2D FFT / radial power'
        for widget in (self.peak_model_label, self.peak_model_combo):
            widget.grid() if is_fft else widget.grid_remove()
        self.correlation_controls.grid_remove() if is_fft else self.correlation_controls.grid()
        for widget in (self.acf_quality_label, self.acf_quality_spin):
            widget.grid() if self.method.get() == '2D autocorrelation' else widget.grid_remove()
        if self.method.get().startswith('Particle'):
            self.particle_controls.pack(fill='x', pady=3, before=self.plots_box)
        else:
            self.particle_controls.pack_forget()
        self.tree.heading('period_nm', text='Particle spacing (nm)' if self.method.get().startswith('Particle') else 'Domain periodicity (nm)')

    def diameter_changed(self, *args):
        if self.muted:
            return
        self.circle = self.pending_circle = None
        self.selecting = False
        self.update_auto_range()
        self.clear_results(quiet=True)
        self.status.set('ROI size changed. Select and confirm ROI.')
        self.schedule_draw()

    def roi_size(self):
        return float(self.roi_size_variable().get())

    def roi_size_variable(self):
        if self.roi_units.get()=='px':
            return self.pixel_side_length if self.roi_shape.get()=='Square' else self.pixel_diameter
        return self.side_length if self.roi_shape.get()=='Square' else self.diameter

    def roi_physical_size(self, size=None):
        return domain_periodicity_dimensions(self.scale, self.roi_size() if size is None else size, self.roi_units.get())

    def shape_changed(self, *args):
        square = self.roi_shape.get()=='Square'
        self.size_label.configure(text=('Side length' if square else 'Circle diameter')+f' ({self.roi_units.get()})')
        self.diameter_entry.configure(textvariable=self.roi_size_variable())
        self.diameter_changed()

    def toggle_advanced(self):
        self.advanced_box.grid() if self.advanced.get() else self.advanced_box.grid_remove()

    def select_roi(self):
        if not self.check_source():
            return False
        try:
            diameter = self.roi_size()
            h, w = self.stack.shape[1:]
            unit = self.roi_units.get()
            minimum = 12 if unit=='px' else 12*max(self.scale)
            maximum = min(w,h) if unit=='px' else min(w*self.scale[0], h*self.scale[1])
            if not np.isfinite(diameter) or not minimum <= diameter <= maximum:
                raise ValueError(f'ROI size must be {minimum:.6g}-{maximum:.6g} {unit}.')
            previous = self.circle or self.pending_circle
            cx, cy = previous[:2] if previous else (w*self.scale[0]/2, h*self.scale[1]/2)
            self.clear_results(quiet=True)
            self.circle = None
            self.selecting = True
            self.move_circle(cx, cy, diameter)
            self.views.select(0)
            self.canvas.get_tk_widget().focus_set()
            return True
        except (ValueError, tk.TclError) as exc:
            self.status.set(str(exc))
            return False

    def move_circle(self, cx, cy, diameter=None):
        diameter = self.roi_size() if diameter is None else float(diameter)
        h, w = self.stack.shape[1:]
        width, height = self.roi_physical_size(diameter)
        cx = float(np.clip(cx, width/2, w*self.scale[0]-width/2))
        cy = float(np.clip(cy, height/2, h*self.scale[1]-height/2))
        self.pending_circle = (cx, cy, diameter)
        self.status.set(f'Pending {self.roi_shape.get().lower()}: center ({cx:.4g}, {cy:.4g}) nm; size {diameter:.4g} {self.roi_units.get()}.')
        self.draw_analysis()

    def on_click(self, event):
        if not self.selecting or event.inaxes is not getattr(self, 'primary_axis', None) or event.button != 1:
            return
        if getattr(self.canvas, 'toolbar', None) is not None and self.canvas.toolbar.mode:
            return
        if event.xdata is not None and event.ydata is not None:
            self.canvas.get_tk_widget().focus_set()
            self.move_circle(event.xdata, event.ydata)

    def on_key(self, event):
        if not self.selecting or self.pending_circle is None:
            return
        if getattr(self.canvas, 'toolbar', None) is not None and self.canvas.toolbar.mode:
            return
        moves = {'Left': (-1, 0), 'Right': (1, 0), 'Up': (0, 1), 'Down': (0, -1)}
        if event.keysym not in moves:
            return
        dx, dy = moves[event.keysym]
        step = 10 if event.state & 1 else 1
        cx, cy, diameter = self.pending_circle
        self.move_circle(cx+dx*self.scale[0]*step, cy+dy*self.scale[1]*step, diameter)
        return 'break'

    def confirm_roi(self):
        if not self.check_source() or self.pending_circle is None:
            self.status.set('Select a region before confirming the ROI.')
            return False
        self.circle = tuple(self.pending_circle)
        self.selecting = False
        self.clear_results(quiet=True)
        self.status.set(f'{self.roi_shape.get()} ROI confirmed across all frames.')
        self.draw_analysis()
        return True

    def clear_roi(self):
        self.circle = self.pending_circle = None
        self.selecting = False
        self.clear_results(quiet=True)
        self.status.set('ROI cleared.')
        self.draw_analysis()

    def clear_results(self, quiet=False):
        self.cancel(quiet=True)
        self.results.clear()
        self.progress.configure(value=0)
        self.last_result = self.last_frame = None
        self.result_label.set('Domain periodicity -- nm\nDomain width (period/2) -- nm')
        self.refresh_table()
        self.draw_tracking()
        if not quiet:
            self.status.set('Analysis results cleared.')
            self.draw_analysis()

    def schedule_draw(self):
        if self.redraw_job:
            self.root.after_cancel(self.redraw_job)
        self.redraw_job = self.root.after(80, self._scheduled_draw)

    def _scheduled_draw(self):
        self.redraw_job = None
        self.draw_analysis()

    def frame_changed(self, value=None):
        if not self.muted:
            self.schedule_draw()

    def set_frame(self, frame):
        if self.stack is not None:
            self.frame.set(int(np.clip(frame, 0, len(self.stack)-1)))
            self.schedule_draw()

    def pause(self):
        if self.play_job:
            self.root.after_cancel(self.play_job)
        self.play_job = None

    def play(self):
        self.pause()
        if self.check_source():
            self._play_step()

    def _play_step(self):
        self.play_job = None
        if not self.check_source():
            return
        try:
            fps = float(self.fps.get())
            if not 1 <= fps <= 30:
                raise ValueError()
        except (ValueError, tk.TclError):
            self.status.set('FPS must be between 1 and 30.')
            return
        self.set_frame((self.frame.get()+1) % len(self.stack))
        self.play_job = self.root.after(int(1000/fps), self._play_step)

    def all_frames(self):
        if self.stack is not None:
            self.first.set(1); self.last.set(len(self.stack)); self.step.set(1)

    def field(self, frame, attribute='real_fields_mT'):
        values = getattr(self.app, attribute, None)
        return float(values[frame]) if values is not None and 0 <= frame < len(values) else np.nan

    def prepare_analysis(self):
        if not self.check_source():
            return None
        if self.circle is None or self.selecting:
            self.status.set('Confirm the ROI before analysis.')
            return None
        try:
            return self.settings()
        except (ValueError, tk.TclError) as exc:
            self.status.set(f'Invalid analysis settings: {exc}')
            return None

    def compute(self, frame, cfg):
        _intensity_require_scalar(self.app)
        result = domain_periodicity_measure(self.stack[frame], self.scale, self.circle, self.support, cfg)
        compact = {key: value for key, value in result.items() if key not in ('roi', 'mask', 'power', 'fx', 'fy', 'window', 'crop', 'correlation_map', 'lag_x_nm', 'lag_y_nm')}
        compact.update(frame_index=int(frame), frame=int(frame)+1,
            field_mT=self.field(frame), current_A=self.field(frame, 'current_values_A'))
        paths = getattr(self.app, 'reconstruction_paths', [])
        compact['source_file'] = str(paths[frame]) if frame < len(paths) else ''
        compact['signal_kind'] = getattr(self.app, '_analysis_signal_kind', 'difference')
        self.results[frame] = compact
        self.last_result, self.last_frame = result, frame
        return result

    def analyze_current(self):
        cfg = self.prepare_analysis()
        if cfg is None:
            return False
        self.cancel(quiet=True); self.pause()
        self.progress.configure(maximum=1, value=0)
        self.progress.update_idletasks()
        try:
            result = self.compute(self.frame.get(), cfg)
            self.status.set(result['status'])
            self.progress.configure(value=1)
            self.draw_analysis(); self.draw_tracking(); self.refresh_table()
            return True
        except (ValueError, RuntimeError) as exc:
            self.status.set(f'Analysis stopped: {exc}')
            return False

    def track_selected(self):
        cfg = self.prepare_analysis()
        if cfg is None:
            return False
        try:
            start, end, step = int(self.first.get()), int(self.last.get()), int(self.step.get())
            if not 1 <= start <= end <= len(self.stack) or step < 1:
                raise ValueError('Use an ordered frame range within the loaded stack and a positive step.')
            # Validate numerical controls before clearing/replacing any frame records.
            domain_periodicity_measure(self.stack[start-1], self.scale, self.circle, self.support, cfg)
        except (ValueError, tk.TclError) as exc:
            self.status.set(f'Invalid frame range or settings: {exc}')
            return False
        self.cancel(quiet=True); self.pause()
        self.queue = list(range(start-1, end, step))
        self.batch_settings = cfg
        self.batch_total = len(self.queue)
        self.batch_done = 0
        self.progress.configure(maximum=self.batch_total, value=0)
        self.batch_job = self.root.after(1, self.batch_step)
        self.status.set(f'Analyzing 0/{self.batch_total} frames | 0%')
        return True

    def batch_step(self):
        self.batch_job = None
        if not self.check_source() or not self.queue:
            return
        index = self.queue.pop(0)
        try:
            self.compute(index, self.batch_settings)
        except (ValueError, RuntimeError) as exc:
            self.cancel(quiet=True)
            self.status.set(f'Frame {index+1} analysis stopped: {exc}')
            self.draw_tracking(); self.refresh_table()
            return
        self.batch_done += 1
        self.progress.configure(value=self.batch_done)
        self.status.set(f'Analyzing {self.batch_done}/{self.batch_total} frames | {100*self.batch_done/self.batch_total:.0f}%')
        if self.queue:
            self.batch_job = self.root.after(1, self.batch_step)
        else:
            self.status.set(f'Analysis complete: {self.batch_done} frames | 100%')
            self.draw_analysis(); self.draw_tracking(); self.refresh_table()

    def cancel(self, quiet=False):
        if self.batch_job:
            self.root.after_cancel(self.batch_job)
        self.batch_job = None
        self.queue = []
        if not quiet:
            self.status.set('Tracking cancelled. Completed frames retained.')
            self.draw_tracking(); self.refresh_table()

    def analysis_colorbar(self, artist, axis, label):
        cax = self._analysis_colorbar_axes[axis]
        cax.set_visible(True)
        return self.figure.colorbar(artist, cax=cax, label=label)

    def draw_analysis(self):
        from matplotlib.patches import Circle, Rectangle, Ellipse
        self.figure.clear()
        # A shared grid keeps columns aligned without colorbars stealing panel space.
        # Explicit margins avoid feedback between aspect-aware bar locators and constrained layout.
        self.figure.set_layout_engine(None)
        grid = self.figure.add_gridspec(2, 4, width_ratios=(1., .05, 1., .05))
        self.figure._responsive_analysis_layout = lambda: _layout_domain_analysis_grid(self.figure, grid)
        axes = np.empty((2, 2), dtype=object)
        self._analysis_colorbar_axes = {}
        for row in range(2):
            for col in range(2):
                ax = self.figure.add_subplot(grid[row, 2*col])
                cax = self.figure.add_subplot(grid[row, 2*col+1])
                cax.set_visible(False)
                axes[row, col] = ax
                ax.set_anchor('C')
                self._analysis_colorbar_axes[ax] = cax
        axes[1, 1].set_box_aspect(1.)
        self.primary_axis = axes[0, 0]
        self.analysis_axes = tuple(axes.ravel())
        method = self.method.get()
        titles = ('2D FFT power', 'Radial power spectrum') if method == '2D FFT / radial power' else (
            ('2D autocorrelation', 'Radial autocorrelation') if method == '2D autocorrelation'
            else ('Detected particle centers', 'Particle pair correlation g(r)'))
        for ax, title in zip(axes.ravel(), ('Processed Primary ROI', self.roi_shape.get()+' ROI')+titles):
            ax.set_title(title, fontsize=10)
        if self.stack is None:
            for ax in axes.ravel():
                ax.set_axis_off()
            self.canvas.draw_idle()
            self.draw_angular(None)
            return
        index = int(np.clip(self.frame.get(), 0, len(self.stack)-1))
        field = self.field(index)
        self.frame_label.set(f'Frame {index+1}/{len(self.stack)} | Field {field:+.4g} mT' if np.isfinite(field) else f'Frame {index+1}/{len(self.stack)} | Field unavailable')
        sx, sy = self.scale
        image = self.stack[index]
        h, w = image.shape
        cmap = str(self.app.colormap_var.get() or 'RdBu_r')
        displayed = np.ma.array(image, mask=~self.support) if self.support is not None else image
        primary_artist = axes[0, 0].imshow(displayed, origin='lower', cmap=cmap, vmin=0., vmax=1.,
            extent=(0, w*sx, 0, h*sy), interpolation='nearest')
        self.analysis_colorbar(primary_artist, axes[0, 0], 'Intensity (a.u.)')
        axes[0, 0].set(xlabel='X (nm)', ylabel='Y (nm)')
        circle = self.circle or self.pending_circle
        if circle is not None:
            cx, cy, diameter = circle
            physical_width, physical_height = self.roi_physical_size(diameter)
            patch_options = dict(fill=False, edgecolor='lime' if self.circle else '#e3a000', linewidth=1.5)
            patch = (Rectangle((cx-physical_width/2, cy-physical_height/2), physical_width, physical_height, **patch_options)
                if self.roi_shape.get()=='Square' else Ellipse((cx, cy), physical_width, physical_height, **patch_options))
            axes[0, 0].add_patch(patch)
            crop, mask = domain_periodicity_roi(image.shape, self.scale, circle, self.roi_shape.get(), self.roi_units.get())
            if self.support is not None:
                mask &= self.support[crop]
            masked = np.ma.array(image[crop], mask=~mask | ~np.isfinite(image[crop]))
            artist = axes[0, 1].imshow(masked, origin='lower', cmap=cmap, vmin=0., vmax=1.,
                extent=(crop[1].start*sx, crop[1].stop*sx, crop[0].start*sy, crop[0].stop*sy), interpolation='nearest')
            axes[0, 1].set(xlabel='X (nm)', ylabel='Y (nm)')
            self.analysis_colorbar(artist, axes[0, 1], 'Intensity (a.u.)')
        else:
            axes[0, 1].set_axis_off()
        result = None
        if index in self.results and self.circle is not None:
            if self.last_frame != index:
                self.last_result = domain_periodicity_measure(image, self.scale, self.circle, self.support, self.results[index]['settings'])
                self.last_frame = index
            result = self.last_result
        q_units = self.frequency_unit.get() == 'q (rad/nm)'
        factor = 2*np.pi if q_units else 1.
        prefix, unit = ('q', 'rad/nm') if q_units else ('f', 'cycles/nm')
        axes[1, 0].set(xlabel=f'{prefix}x ({unit})', ylabel=f'{prefix}y ({unit})')
        axes[1, 1].set(xlabel=f'{prefix} ({unit})', ylabel='Mean power (a.u.)')
        if result is not None:
            if result['method'] != '2D FFT / radial power':
                self.draw_correlation(axes, result, cmap)
            elif result['power'] is not None:
                fx, fy, power = result['fx']*factor, result['fy']*factor, result['power']
                df_x, df_y = fx[1]-fx[0], fy[1]-fy[0]
                relative = 10*np.log10(np.maximum(power/max(power.max(), np.finfo(float).tiny), 1e-8))
                im = axes[1, 0].imshow(relative, origin='lower', cmap='magma', vmin=-60, vmax=0,
                    extent=(fx[0]-df_x/2, fx[-1]+df_x/2, fy[0]-df_y/2, fy[-1]+df_y/2))
                x_bounds, y_bounds = domain_periodicity_fft_limits(result, self.peak_zoom.get())
                axes[1, 0].set_xlim(np.asarray(x_bounds)*factor)
                axes[1, 0].set_ylim(np.asarray(y_bounds)*factor)
                self.analysis_colorbar(im, axes[1, 0], 'Relative power (dB)')
                if result['valid']:
                    axes[1, 0].add_patch(Circle((0, 0), factor*result['peak_frequency_cycles_nm'], fill=False, edgecolor='cyan', linewidth=1.))
                frequency, radial = factor*result['frequency'], result['radial_power']
                axes[1, 1].plot(frequency, radial, color='#23749c', label='Radial power')
                if result['fit_used']:
                    axes[1, 1].plot(factor*result['fit_frequency'], result['fitted_power'], '--', color='#b5343e', label=result['settings']['peak_model']+' fit')
                cfg = result['settings']
                axes[1, 1].axvspan(factor*max(1/cfg['max_period_nm'], cfg['min_cycles']/result['roi_size_nm']),
                    factor/cfg['min_period_nm'], alpha=.08, color='green')
                if result['valid']:
                    axes[1, 1].axvline(factor*result['peak_frequency_cycles_nm'], color='black', lw=1, ls=':')
                spectrum_limit = frequency[-1]
                if self.peak_zoom.get():
                    spectrum_limit = min(spectrum_limit, factor*max(x_bounds[1], y_bounds[1]))
                axes[1, 1].set_xlim(0, spectrum_limit)
                axes[1, 1].legend(fontsize=8)
                axes[1, 1].grid(alpha=.2)
            if result['valid']:
                se = result['period_fit_se_nm']
                error = f' | Peak-fit SE {se:.3g} nm' if np.isfinite(se) else ''
                if result['method'].startswith('Particle'):
                    self.result_label.set(f"Particle spacing: {result['particle_spacing_nm']:.5g} nm\nParticles: {result['particle_count']}\nDomain width: unavailable")
                else:
                    detail = (f"Peak FWHM {result['peak_fwhm_cycles_nm']:.4g} cycles/nm" if result['method'].startswith('2D FFT')
                        else f"Autocorrelation fit R-squared: {result['fit_r2']:.4g}")
                    self.result_label.set(f"Domain periodicity: {result['period_nm']:.5g} nm{error}\nDomain width (period/2): {result['domain_width_nm']:.5g} nm\n{detail}")
            else:
                self.result_label.set('Domain periodicity / width unavailable: '+result['status'])
        else:
            self.result_label.set('Domain periodicity -- nm\nDomain width (period/2) -- nm')
        self.figure.suptitle(self.frame_label.get(), fontsize=11)
        self.canvas.draw_idle()
        self.draw_angular(result)

    def draw_correlation(self, axes, result, cmap):
        ax, profile = axes[1]
        is_particle = result['method'].startswith('Particle')
        if is_particle:
            crop = result['crop']; sx, sy = self.scale
            extent = (crop[1].start*sx, crop[1].stop*sx, crop[0].start*sy, crop[0].stop*sy)
            particle_artist = ax.imshow(np.ma.array(result['roi'], mask=~result['mask']), cmap=cmap, origin='lower', extent=extent, vmin=0., vmax=1.)
            self.analysis_colorbar(particle_artist, ax, 'Intensity (a.u.)')
            centers = result['particle_centers_nm']
            if len(centers):
                global_centers = centers+np.array([extent[0], extent[2]])
                for target in (ax, axes[0, 1]):
                    target.scatter(global_centers[:, 0], global_centers[:, 1], s=24,
                        facecolors='none', edgecolors='#ffe100', linewidths=1.1)
            ax.set(xlabel='X (nm)', ylabel='Y (nm)', title=f"Detected particle centers ({result['particle_count']})")
            profile.set(xlabel='Center separation (nm)', ylabel='g(r)')
            profile.axhline(1, color='gray', ls=':', label='Uncorrelated baseline')
        else:
            ax.set(xlabel='X displacement (nm)', ylabel='Y displacement (nm)')
            if result['correlation_map'] is not None:
                lx, ly = result['lag_x_nm'], result['lag_y_nm']
                im = ax.imshow(np.ma.masked_invalid(result['correlation_map']), origin='lower', cmap='RdBu_r', vmin=-1, vmax=1,
                    extent=(lx[0]-self.scale[0]/2, lx[-1]+self.scale[0]/2, ly[0]-self.scale[1]/2, ly[-1]+self.scale[1]/2))
                self.analysis_colorbar(im, ax, 'ACF')
                limit = result['roi_size_nm']/2
                ax.set_xlim(-limit, limit); ax.set_ylim(-limit, limit)
            profile.set(xlabel='Displacement (nm)', ylabel='C(r)')
            profile.axhline(0, color='gray', ls=':')
        if len(result['distance_nm']):
            profile.plot(result['distance_nm'], result['correlation'], color='#23749c',
                label='Pair correlation' if is_particle else 'Radial autocorrelation')
            if result['fit_used']:
                profile.plot(result['distance_nm'], result['correlation_fit'], '--', color='#b5343e', label='Damped-Bessel fit')
            if result['valid']:
                profile.axvline(result['period_nm'], color='black', ls=':', label='Spacing' if is_particle else 'Fitted period')
            profile.legend(fontsize=8)
        profile.grid(alpha=.2)

    def draw_angular(self, result):
        self.angular_figure.clear()
        ax = self.angular_figure.subplots()
        ax.set(xlabel='Fourier azimuth (degrees)', ylabel='Annular mean power (a.u.)',
            title='Angular spectrum at the domain-period peak', xlim=(-180, 180))
        ax.grid(alpha=.2)
        if result is not None and result['valid'] and len(result['azimuth_deg']):
            ax.plot(result['azimuth_deg'], result['azimuth_power'], color='#8c2862', lw=1.5)
            self.angular_figure.suptitle(self.frame_label.get(), fontsize=11)
        elif self.method.get() != '2D FFT / radial power':
            ax.text(.5, .5, 'Angular spectrum is available for FFT analysis', ha='center', va='center', transform=ax.transAxes)
        self.angular_canvas.draw_idle()

    def records(self):
        rows = []
        for index in sorted(self.results):
            source = self.results[index]
            row = {key: value for key, value in source.items()
                if key != 'settings' and not isinstance(value, (np.ndarray, tuple, list, dict))}
            row.update(field_mT=self.field(index), current_A=self.field(index, 'current_values_A'))
            row.update(_intensity_provenance(self.app, index))
            row['domain_periodicity_nm'] = source['period_nm'] if source['measurement_kind']=='Domain periodicity' else np.nan
            row.update(source['settings'])
            rows.append(row)
        return rows

    def draw_tracking(self):
        self.tracking_figure.clear()
        width_ax = self.tracking_figure.subplots()
        period_ax = width_ax.twinx()
        frame_ax = width_ax.twiny()
        self.tracking_axes = (width_ax, period_ax, frame_ax)
        rows = self.records()
        particles = self.method.get().startswith('Particle')
        width_ax.set(xlabel='Field (mT)', ylabel='Domain width (nm)')
        period_ax.set_ylabel('Particle spacing (nm)' if particles else 'Domain periodicity (nm)')
        frame_ax.set_xlabel('Frame')
        width_ax.yaxis.label.set_color('#a53162'); width_ax.tick_params(axis='y', colors='#a53162')
        period_ax.yaxis.label.set_color('#176c86'); period_ax.tick_params(axis='y', colors='#176c86')
        width_ax.grid(alpha=.2)
        if rows:
            x = np.array([r['field_mT'] for r in rows], float)
            for ax, key, se_key, low_key, high_key, label, color, marker in [
                (width_ax, 'domain_width_nm', 'domain_width_fit_se_nm', 'domain_width_hm_low_nm', 'domain_width_hm_high_nm',
                    'Domain width (period/2)', '#a53162', '^'),
                (period_ax, 'period_nm', 'period_fit_se_nm', 'period_hm_low_nm', 'period_hm_high_nm',
                    'Particle spacing' if particles else 'Domain periodicity', '#176c86', 'o')]:
                y = np.array([r.get(key, np.nan) if r['valid'] else np.nan for r in rows], float)
                ax.plot(x, y, marker=marker, color=color, ls='--' if key=='period_nm' else '-',
                    ms=4 if key=='period_nm' else 7, lw=1.1, label=label if np.isfinite(y).any() else '_nolegend_')
                mode = self.error_mode.get()
                if mode != 'None':
                    if mode == 'Peak-fit SE' or self.method.get() == '2D autocorrelation':
                        errors = np.array([r.get(se_key, np.nan) for r in rows], float)
                        use = np.isfinite(x) & np.isfinite(y) & np.isfinite(errors)
                        errors = errors[use]
                        error_label = 'Fit SE'
                    else:
                        low = np.array([r.get(low_key, np.nan) for r in rows], float)
                        high = np.array([r.get(high_key, np.nan) for r in rows], float)
                        use = np.isfinite(x) & np.isfinite(y) & np.isfinite(low) & np.isfinite(high)
                        errors = np.array([np.maximum(0, y[use]-low[use]), np.maximum(0, high[use]-y[use])])
                        error_label = 'Peak span'
                    if use.any():
                        ax.errorbar(x[use], y[use], yerr=errors, fmt='none', ecolor=color, capsize=3,
                            label=error_label if ax is period_ax else '_nolegend_')
            # Field may repeat/reverse in a hysteresis loop: label actual sampled frames,
            # never infer an invertible field-to-frame conversion.
            finite = np.isfinite(x)
            fields = np.unique(x[finite])
            if len(fields):
                fields = fields[np.unique(np.rint(np.linspace(0, len(fields)-1, min(7, len(fields)))).astype(int))]
                labels = []
                for value in fields:
                    frames = [str(r['frame']) for r in rows if np.isfinite(r['field_mT']) and r['field_mT']==value]
                    labels.append('/'.join(frames) if len(frames)<=3 else frames[0]+'/.../'+frames[-1])
                frame_ax.set_xticks(fields, labels=labels)
                frame_ax.set_xlim(width_ax.get_xlim())
            else:
                frame_ax.set_xticks([])
                width_ax.text(.5, .5, 'Calibrated field unavailable', transform=width_ax.transAxes, ha='center')
            handles, labels = width_ax.get_legend_handles_labels()
            right_handles, right_labels = period_ax.get_legend_handles_labels()
            width_ax.legend(handles+right_handles, labels+right_labels, fontsize=9, loc='best')
        else:
            frame_ax.set_xticks([])
        if particles:
            width_ax.set_yticks([])
            width_ax.text(.02, .02, 'Domain width unavailable for pair correlation',
                transform=width_ax.transAxes, fontsize=9, color='#a53162')
        width_ax.callbacks.connect('xlim_changed', lambda axis: frame_ax.set_xlim(axis.get_xlim(), emit=False))
        frame_ax.callbacks.connect('xlim_changed', lambda axis: width_ax.set_xlim(axis.get_xlim(), emit=False))
        self.tracking_figure.suptitle('Domain width and periodicity' if not particles else 'Particle center spacing', fontsize=12)
        self.tracking_canvas.draw_idle()

    def refresh_table(self):
        selection = self.tree.selection()
        for child in self.tree.get_children():
            self.tree.delete(child)
        for row in self.records():
            values = []
            for key in self.columns:
                value = row.get(key, np.nan)
                values.append(f'{value:.7g}' if isinstance(value, (float, np.floating)) and np.isfinite(value)
                    else '--' if isinstance(value, (float, np.floating)) else str(value))
            self.tree.insert('', 'end', iid=str(row['frame_index']), values=values)
        if selection and self.tree.exists(selection[0]):
            self.tree.selection_set(selection[0])

    def table_selected(self, event=None):
        selected = self.tree.selection()
        if selected:
            self.set_frame(int(selected[0]))

    def refresh_fields(self):
        if self.stack is not None:
            self.draw_tracking(); self.refresh_table(); self.schedule_draw()

    def on_tab(self, event=None):
        if self.app.nb.select() == str(self.frame_widget) and self.stack is not None:
            if self.check_source():
                self.refresh_fields()

    def export_directory(self, kind):
        from datetime import datetime
        folder = filedialog.askdirectory(title='Domain Periodicity output folder', parent=self.root)
        if not folder:
            return None
        path = Path(folder)/('DomainPeriodicity_'+kind+'_'+datetime.now().strftime('%Y%m%d_%H%M%S_%f'))
        path.mkdir(parents=True)
        return path

    def export_tables(self):
        if not self.check_source() or not self.results:
            self.status.set('Analyze frames before exporting tables.')
            return False
        folder = self.export_directory('Tables')
        if folder is None:
            return False
        try:
            pd.DataFrame(self.records()).to_csv(folder/'domain_periodicity.csv', index=False)
            spectra = []
            for index, result in sorted(self.results.items()):
                fitted = dict(zip(result['fit_frequency'], result['fitted_power']))
                for f, power in zip(result['frequency'], result['radial_power']):
                    spectra.append(dict(frame_index=index, frame=index+1, field_mT=self.field(index),
                        frequency_cycles_nm=f, q_rad_nm=2*np.pi*f, radial_power=power, fitted_power=fitted.get(f, np.nan)))
            pd.DataFrame(spectra, columns=('frame_index', 'frame', 'field_mT', 'frequency_cycles_nm', 'q_rad_nm', 'radial_power', 'fitted_power')).to_csv(folder/'radial_spectra.csv', index=False)
            angular = [dict(frame_index=index, frame=index+1, field_mT=self.field(index),
                azimuth_deg=angle, annular_mean_power=power)
                for index, result in sorted(self.results.items())
                for angle, power in zip(result['azimuth_deg'], result['azimuth_power'])]
            pd.DataFrame(angular, columns=('frame_index', 'frame', 'field_mT', 'azimuth_deg', 'annular_mean_power')).to_csv(folder/'angular_spectra.csv', index=False)
            correlations, centers = [], []
            for index, result in sorted(self.results.items()):
                distance = result.get('distance_nm', [])
                fitted = result.get('correlation_fit', [])
                counts = result.get('pair_counts', [])
                for sample, radius in enumerate(distance):
                    correlations.append(dict(frame_index=index, frame=index+1, field_mT=self.field(index),
                        method=result['method'], distance_nm=radius, correlation=result['correlation'][sample],
                        model=fitted[sample] if len(fitted)==len(distance) else np.nan,
                        pair_count=counts[sample] if len(counts)==len(distance) else np.nan))
                for particle, center in enumerate(result.get('particle_centers_nm', []), 1):
                    centers.append(dict(frame_index=index, frame=index+1, field_mT=self.field(index),
                        particle_index_in_frame=particle, x_in_roi_crop_nm=center[0], y_in_roi_crop_nm=center[1]))
            pd.DataFrame(correlations, columns=('frame_index','frame','field_mT','method','distance_nm','correlation','model','pair_count')).to_csv(folder/'correlation_profiles.csv', index=False)
            pd.DataFrame(centers, columns=('frame_index','frame','field_mT','particle_index_in_frame','x_in_roi_crop_nm','y_in_roi_crop_nm')).to_csv(folder/'particle_centers.csv', index=False)
            metadata = dict(intensity_provenance=_intensity_provenance(self.app, int(self.frame.get())), method=self.method.get(),
                source='Processed Primary ROI from Tab 6', source_geometry=self.source_description,
                circle_nm=list(self.circle) if self.roi_shape.get()=='Circle' and self.roi_units.get()=='nm' else None,
                roi_geometry=domain_periodicity_roi_info(self.scale, self.circle, self.roi_shape.get(), self.roi_units.get()),
                roi_shape=self.roi_shape.get(), roi_units=self.roi_units.get(), roi_center_nm=list(self.circle[:2]),
                scale_nm=list(self.scale), settings=self.settings(),
                uncertainty='period_fit_se_nm is an approximate local peak-fit standard error, corrected for FFT padding; not domain-width dispersion or temporal SD',
                spectral_span='period_hm_low_nm = 1/(f0+FWHM_f/2), period_hm_high_nm = 1/(f0-FWHM_f/2); half-maximum spectral span, not statistical confidence limits; includes window and finite-ROI broadening',
                definition='period_nm = 1/f0 = 2*pi/q0; domain_width_nm = half_period_nm = period_nm/2. Domain width is inferred from half-period and assumes equal up/down stripe widths; not an independently segmented width, particle diameter or domain-wall width',
                angular_spectrum='5-degree annular means around selected peak; annulus half-width is max(FWHM_f/2, native FFT bin width/2); angle is Fourier wavevector azimuth, perpendicular to stripe direction',
                autocorrelation='Linear 2D covariance divided by tapered-mask overlap, normalized at zero lag; radial fit base+A*J0(2*pi*r/L)*exp(-(r/decay)^2); fit SE is conditional on this narrowband model, not independent spatial-sample SD',
                pair_correlation='LoG particle centers; translation edge correction from the actual eroded ROI support; g(r) normalized to 1 for uniform random centers; first resolved neighbor peak is particle_spacing_nm, not domain width. period_nm is a legacy common spacing column; domain_periodicity_nm is unavailable for g(r)',
                tracking_axes='Bottom: actual calibrated field mT; top: frame labels at selected sampled fields. Repeated fields list multiple frames; no invertible field/frame map is assumed. Left: derived width; right: domain periodicity or explicitly labeled particle spacing',
                plot_quantity='Width and periodicity / particle spacing', error_bars=self.error_mode.get(), fft_axes=self.frequency_unit.get(),
                references=list(DOMAIN_PERIODICITY_REFERENCES),
                reference_usage='10.1063/5.0244024: PSD/Lorentzian peak and full/half-period convention; 10.1038/s41467-019-09934-z: reciprocal-space angular diagnostics. FFT of a reconstructed ROI is not raw resonant-scattering intensity or speckle-avalanche analysis',
                frequency_resolution='approximately 1 / ROI diameter; FFT padding does not improve physical resolution',
                unavailable='Unresolved frames have NaN period and a status reason')
            (folder/'analysis_metadata.json').write_text(json.dumps(metadata, indent=2), encoding='utf-8')
            _tab6_open_output_folder(str(folder))
            self.status.set(f'Tables exported: {folder}')
            return True
        except Exception as exc:
            self.status.set(f'Table export failed: {exc}')
            return False

    def export_figures(self):
        if not self.check_source() or not self.results:
            self.status.set('Analyze frames before exporting figures.')
            return False
        if self.frame.get() not in self.results:
            if not self.analyze_current():
                return False
        folder = self.export_directory('Figures')
        if folder is None:
            return False
        try:
            self.draw_analysis(); self.draw_tracking()
            self.figure.savefig(folder/f'roi_analysis_frame_{self.frame.get()+1:04d}.png', dpi=300, bbox_inches='tight', pad_inches=.15)
            self.tracking_figure.savefig(folder/'domain_periodicity_tracking.png', dpi=300, bbox_inches='tight', pad_inches=.15)
            if self.method.get() == '2D FFT / radial power':
                self.angular_figure.savefig(folder/f'angular_spectrum_frame_{self.frame.get()+1:04d}.png', dpi=300, bbox_inches='tight', pad_inches=.15)
            _tab6_open_output_folder(str(folder))
            self.status.set(f'Figures exported at 300 PPI: {folder}')
            return True
        except Exception as exc:
            self.status.set(f'Figure export failed: {exc}')
            return False

    def reset(self):
        self.cancel(quiet=True); self.pause()
        if self.redraw_job:
            self.root.after_cancel(self.redraw_job)
        self.redraw_job = None
        self.stack = self.support = self.scale = self.source_token = None
        self.circle = self.pending_circle = None
        self.selecting = False
        self.results.clear()
        self.last_result = self.last_frame = None
        self.muted = True
        for var, value in [(self.frame, 0), (self.first, 1), (self.last, 1), (self.step, 1),
            (self.fps, 5), (self.diameter, '1000'), (self.side_length, '1000'), (self.roi_shape, 'Circle'), (self.auto_range, True),
            (self.pixel_diameter, '100'), (self.pixel_side_length, '100'), (self.roi_units, 'nm'),
            (self.min_period, '40'), (self.max_period, '400'), (self.detrend, 'Mean'),
            (self.method, '2D FFT / radial power'), (self.peak_model, 'Lorentzian'),
            (self.radial_bin, '0'), (self.acf_r2, .5), (self.particle_polarity, 'Dark'),
            (self.particle_min, '40'), (self.particle_max, '200'), (self.particle_separation, '40'),
            (self.particle_threshold, .08), (self.particle_snr, 3.), (self.particle_min_count, 6), (self.gr_min_peak, 1.2),
            (self.error_mode, 'Spectral half-maximum span'), (self.frequency_unit, 'f (cycles/nm)'),
            (self.peak_zoom, True),
            (self.taper, .2), (self.padding, 2), (self.smoothing, .75),
            (self.peak_ratio, 3.), (self.prominence, .1), (self.coverage, .7), (self.cycles, 3.), (self.advanced, False)]:
            var.set(value)
        self.muted = False
        self.min_entry.configure(state='disabled'); self.max_entry.configure(state='disabled')
        self.toggle_advanced()
        self.update_method_controls()
        self.slider.configure(to=0, state='disabled')
        self.progress.configure(value=0)
        self.status.set('Primary ROI unavailable')
        self.frame_label.set('Frame -- | Field --')
        self.scale_label.set('Scale -- nm/pixel')
        self.result_label.set('Domain periodicity -- nm\nDomain width (period/2) -- nm')
        self.refresh_table(); self.draw_analysis(); self.draw_tracking()


