def _run_gui_event_loop(window):
    """Use the kernel's Tk event pump so notebook execution can finish."""
    try:
        shell = get_ipython()
    except NameError:
        shell = None
    if shell is not None and getattr(shell, 'kernel', None) is not None:
        shell.enable_gui('tk')
        # Keep Tk on the kernel's main thread; its input hook pumps events
        # between notebook requests, including slider and redraw callbacks.
        window.update_idletasks()
        print(f'GUI ready in {_startup_ready_s:.2f} s. '
              'The GUI stays open; the notebook kernel is available.', flush=True)
        return 'ipykernel-tk'
    window.mainloop()
    return 'standalone-tk'


_NATIVE_OLD_DOWNSTREAM = _tab6_downstream_authoritative_primary_stack_v22
_NATIVE_OLD_AUTH_BUILD = _tab6_auth_build_stack_v21
_NATIVE_OLD_UPDATE = CDIWorkflowApp.update_processing_view


def _native_downstream(owner):
    return _native_require_finalized(owner)


def _native_finalized_stack(owner):
    return _native_require_finalized(owner)[0]


def _native_auth_build(owner, force=False):
    snapshot = getattr(owner, '_native_finalized_snapshot', None)
    if snapshot is not None and getattr(owner, '_native_finalized_signature', None) == _native_signature(owner):
        return snapshot[0]
    if getattr(owner, '_native_preview_active', False) or getattr(owner, '_native_finalizing', False):
        return _NATIVE_OLD_AUTH_BUILD(owner, force=force)
    return _native_require_finalized(owner)[0]


def _native_sync_calibration(owner):
    try: current = float(owner._proc_get_tab5_base_pixel_size())
    except (TypeError, ValueError, tk.TclError): return False
    if not np.isfinite(current) or current <= 0: return False
    previous = getattr(owner, '_native_display_calibration', None)
    previous = current if previous is None else float(previous)
    owner._native_display_calibration = current
    changed = np.isfinite(previous) and previous > 0 and abs(current-previous) > 1e-12
    if changed:
        preserved = getattr(owner, '_tab6_preserved_pre_set_scale', None)
        if preserved is not None:
            owner._tab6_preserved_pre_set_scale = tuple(float(value)*current/previous for value in preserved)
        _native_mark_dirty(owner, 'Physical pixel calibration changed')
    return changed


def _native_update_view(owner, *args, **kwargs):
    if getattr(owner, 'recons', None) is not None:
        _native_sync_calibration(owner)
        try:
            current = _native_config_key(owner)
            if getattr(owner, '_native_seen_preview_key', current) != current:
                _native_settings_changed(owner)
                return
            if getattr(owner, '_native_preview_job', None) is not None and not getattr(owner, '_native_forced_preview', False):
                return
        except (ValueError, tk.TclError): return
    previous = getattr(owner, '_native_preview_active', False)
    owner._native_preview_active = True
    try:
        result = _NATIVE_OLD_UPDATE(owner, *args, **kwargs)
        # Ensure an in-place calibration/rotation/source change cannot retain an old commitment.
        if getattr(owner, '_native_finalized_snapshot', None) is not None:
            if owner._native_finalized_signature != _native_signature(owner): _native_mark_dirty(owner)
        return result
    except Exception as exc:
        owner.native_finalize_status_var.set('Preview unavailable: '+str(exc))
    finally: owner._native_preview_active = previous


def _native_rotation_action(owner, method, *args, **kwargs):
    _native_mark_dirty(owner, 'Rotation preview changed')
    previous = getattr(owner, '_native_preview_active', False)
    owner._native_preview_active = True
    try: return method(owner, *args, **kwargs)
    finally: owner._native_preview_active = previous


def _native_install(owner):
    import functools
    owner._native_workflow_installed = True
    owner._native_display_calibration = None
    _native_sync_calibration(owner)
    owner._native_seen_preview_key = _native_config_key(owner)
    owner._native_finalized_snapshot = None
    for name in ('filter_var', 'strength_var', 'brightness_var', 'contrast_var', 'fft_mask_var'):
        variable = getattr(owner, name, None)
        if variable is not None:
            def changed(*args, name=name):
                try:
                    current = _native_config_key(owner)
                    if current != getattr(owner, '_native_seen_preview_key', None): _native_settings_changed(owner)
                except (ValueError, tk.TclError): pass
            variable.trace_add('write', changed)
    for name in ('_tab6_rotation_set', '_tab6_rotation_reset', '_tab6_rotation_release'):
        method = getattr(CDIWorkflowApp, name, None)
        if callable(method):
            def wrapped(self, *args, _method=method, **kwargs):
                return _native_rotation_action(self, _method, *args, **kwargs)
            setattr(CDIWorkflowApp, name, wrapped)
    # Buttons constructed before these final bindings hold their original command.
    for widget in _tab6_rebuilt_walk_widgets(owner._proc_control_frame):
        if isinstance(widget, ttk.LabelFrame) and str(widget.cget('text')).strip() == 'IMAGE ROTATION':
            commands = {'SET':'_tab6_rotation_set','RESET':'_tab6_rotation_reset','RELEASE':'_tab6_rotation_release'}
            for child in _tab6_rebuilt_walk_widgets(widget):
                if isinstance(child, (ttk.Button, tk.Button)):
                    name = commands.get(str(child.cget('text')).strip())
                    if name: child.configure(command=getattr(owner, name))


_tab6_downstream_authoritative_primary_stack_v22 = _native_downstream
_tab6_auth_build_stack_v21 = _native_auth_build
CDIWorkflowApp.update_processing_view = _native_update_view
CDIWorkflowApp.process_image = _proc_image
CDIWorkflowApp._tab6_build_exact_processed_primary_stack = _native_finalized_stack
_tab6_build_exact_processed_primary_stack = _native_finalized_stack
CDIWorkflowApp.finalize_primary_roi = _native_finalize
_native_install(app)


def _tab6_view_source(owner):
    key = (id(getattr(owner, 'recons', None)), id(getattr(owner, 'roi_mask', None)))
    changed = getattr(owner, '_tab6_view_source_key', key) != key
    owner._tab6_view_source_key = key
    if changed:
        owner._tab6_persistent_view = None
        owner._proc_zoom_limits = None
        owner._proc_zoomed = False
    return changed


def _tab6_remember_view(owner, axis=None, force=False):
    if getattr(owner, '_tab6_view_update_depth', 0): return
    if _tab6_view_source(owner): return
    if not getattr(owner, 'roi_resolution_applied', False): return
    if not force and not getattr(owner, '_tab6_user_view_active', False): return
    axis = owner._proc_ax
    xlim, ylim = tuple(axis.get_xlim()), tuple(axis.get_ylim())
    full = tuple(map(float, owner._proc_image_display.get_extent()))
    limits = xlim+ylim
    if not np.all(np.isfinite(limits)) or xlim[0] == xlim[1] or ylim[0] == ylim[1]: return
    if np.allclose(limits, full, rtol=1e-9, atol=1e-9):
        owner._tab6_persistent_view = None
        owner._proc_zoom_limits = None
        owner._proc_zoomed = False
        return
    owner._tab6_persistent_view = (xlim, ylim)
    owner._proc_zoom_limits = limits
    owner._proc_zoomed = True


def _tab6_restore_view(owner):
    view = getattr(owner, '_tab6_persistent_view', None)
    if view is None: return
    xlim, ylim = view
    owner._proc_zoom_limits = tuple(xlim)+tuple(ylim)
    owner._proc_zoomed = True
    owner._proc_ax.set_xlim(xlim, emit=False)
    owner._proc_ax.set_ylim(ylim, emit=False)
    owner._proc_ax.set_autoscale_on(False)
    owner._proc_canvas.draw_idle()


def _tab6_keep_view(owner, operation, *args, **kwargs):
    depth = getattr(owner, '_tab6_view_update_depth', 0)
    if depth == 0:
        changed = _tab6_view_source(owner)
        if not changed and getattr(owner, '_tab6_persistent_view', None) is None:
            _tab6_remember_view(owner, force=True)
    owner._tab6_view_update_depth = depth+1
    try: return operation(owner, *args, **kwargs)
    finally:
        owner._tab6_view_update_depth = depth
        if depth == 0: _tab6_restore_view(owner)


def _tab6_reset_persistent_zoom(owner):
    owner._tab6_persistent_view = None
    owner._proc_zoom_limits = None
    owner._proc_zoomed = False
    owner._tab6_view_update_depth += 1
    try:
        extent = tuple(map(float, owner._proc_image_display.get_extent()))
        owner._proc_ax.set_xlim(extent[:2])
        owner._proc_ax.set_ylim(extent[2:])
        owner._proc_ax.set_autoscale_on(False)
        owner._proc_canvas.draw_idle()
    finally: owner._tab6_view_update_depth -= 1
    owner.proc_status_var.set('Zoom reset — showing the full processed ROI.')


def _tab6_user_view_begin(owner, event):
    owner._tab6_user_view_active = event.inaxes is owner._proc_ax


def _tab6_user_view_end(owner, event):
    if not getattr(owner, '_tab6_user_view_active', False): return
    # Toolbar release handlers may be registered after this callback. Capture
    # after all release handlers have applied the user's new viewport.
    def finish():
        _tab6_remember_view(owner, force=True)
        owner._tab6_user_view_active = False
    owner.root.after_idle(finish)


def _tab6_user_wheel(owner, operation, event):
    owner._tab6_user_view_active = True
    try: return operation(owner, event)
    finally:
        _tab6_remember_view(owner, force=True)
        owner._tab6_user_view_active = False


def _tab6_status_refresh(owner, variable=None, help_text=None):
    def value(name):
        try: return str(getattr(owner, name).get()).strip()
        except (AttributeError, tk.TclError): return ''
    if variable in owner._tab6_status_action_names:
        owner._tab6_latest_status_message = value(variable)
    finalized = value('native_finalize_status_var')
    current = help_text if help_text is not None else getattr(owner, '_tab6_latest_status_message', '')
    lines = [line for line in (finalized, current) if line]
    if len(lines) == 2 and lines[0] == lines[1]: lines.pop()
    details = [value(name) for name in ('proc_roi_info_var', 'proc_effective_pixel_size_var')]
    details = [detail for detail in details if detail and '--' not in detail]
    if details: lines.append(' | '.join(details))
    owner.tab6_image_status_var.set('\n'.join(lines))


def _tab6_install_compact_status(owner):
    controls = owner._proc_control_frame
    widgets = list(_tab6_rebuilt_walk_widgets(controls))
    rotation = next(widget for widget in widgets if isinstance(widget, ttk.LabelFrame)
                    and str(widget.cget('text')) == 'IMAGE ROTATION')
    finalize = owner.tab6_finalize_button.master
    finalize.pack_configure(before=rotation)
    owner.proc_slider.pack_configure(before=finalize, fill='x', padx=6)
    field_label = next(widget for widget in widgets if isinstance(widget, ttk.Label)
                       and str(widget.cget('textvariable')) == str(owner.proc_field_var))
    field_label.pack_configure(before=owner.proc_slider)
    frame_heading = next(widget for widget in widgets if isinstance(widget, ttk.Label)
                         and str(widget.cget('text')) == 'FIELD / IMAGE')
    frame_heading.pack_configure(before=field_label)

    image_frame = owner._proc_canvas.get_tk_widget().master
    packed = image_frame.pack_slaves()
    status = ttk.Frame(image_frame, padding=(8, 5))
    status.pack(side='bottom', fill='x', before=packed[0])
    owner.tab6_image_status_frame = status
    owner.tab6_image_status_var = tk.StringVar(master=owner.root)
    ttk.Separator(status).pack(fill='x', pady=(0, 4))
    label = ttk.Label(status, textvariable=owner.tab6_image_status_var, justify='left', anchor='w', wraplength=750)
    label.pack(fill='x')
    status.bind('<Configure>', lambda event: label.configure(wraplength=max(180, event.width-16)))
    owner._tab6_status_action_names = ('proc_status_var', 'native_finalize_status_var',
        'tab6_rotation_status_var', 'proc_secondary_status_var', 'roi_play_status_var',
        'proc_profile_pixels_var', 'proc_profile_nm_var')
    verbose = owner._tab6_status_action_names + ('proc_roi_info_var', 'proc_effective_pixel_size_var', 'tab6_rotation_scale_var')
    hidden_variables = {str(getattr(owner, name)) for name in verbose if hasattr(owner, name)}
    owner._tab6_status_hidden_labels = []
    for widget in widgets:
        if not isinstance(widget, ttk.Label): continue
        text = str(widget.cget('text')).strip()
        variable = str(widget.cget('textvariable'))
        explanatory = len(text) > 65 or text.startswith(('Process at original pixel', 'Base value =', 'None bypasses'))
        if variable not in hidden_variables and not explanatory: continue
        # Retain the widget and its binding; only its explanatory presentation moves.
        if widget.winfo_manager() == 'pack': widget.pack_forget()
        elif widget.winfo_manager() == 'grid': widget.grid_remove()
        owner._tab6_status_hidden_labels.append(widget)
        if explanatory:
            widget.master.bind('<Enter>', lambda event, message=text:
                _tab6_status_refresh(owner, help_text=message), add='+')
            widget.master.bind('<Leave>', lambda event: _tab6_status_refresh(owner), add='+')
    for name in verbose:
        variable = getattr(owner, name, None)
        if variable is not None:
            variable.trace_add('write', lambda *args, name=name: _tab6_status_refresh(owner, variable=name))
    _tab6_status_refresh(owner)

    owner._tab6_view_update_depth = 0
    owner._tab6_persistent_view = None
    _tab6_view_source(owner)
    owner._proc_ax.callbacks.connect('xlim_changed', lambda axis: _tab6_remember_view(owner, axis))
    owner._proc_ax.callbacks.connect('ylim_changed', lambda axis: _tab6_remember_view(owner, axis))
    owner._proc_canvas.callbacks.connect('button_press_event', lambda event: _tab6_user_view_begin(owner, event))
    owner._proc_canvas.callbacks.connect('button_release_event', lambda event: _tab6_user_view_end(owner, event))
    owner._proc_canvas.callbacks.connect('scroll_event', lambda event: _tab6_remember_view(owner, force=True))
    wheel = CDIWorkflowApp._tab6_native_tk_mouse_zoom
    CDIWorkflowApp._tab6_native_tk_mouse_zoom = lambda self, event: _tab6_user_wheel(self, wheel, event)
    # Navigation tools are installed lazily when a canvas first becomes visible.
    def hook_navigation(event=None):
        toolbar = getattr(owner._proc_canvas, 'toolbar', None)
        if toolbar is None or getattr(toolbar, '_tab6_view_tracking', False): return
        old_view = toolbar._update_view
        def navigate():
            result = old_view()
            _tab6_remember_view(owner, force=True)
            return result
        toolbar._update_view = navigate
        toolbar._tab6_view_tracking = True
    owner._proc_canvas.get_tk_widget().bind('<Map>', lambda event: owner.root.after_idle(hook_navigation), add='+')
    owner.root.after_idle(hook_navigation)
    CDIWorkflowApp._proc_reset_zoom = _tab6_reset_persistent_zoom
    for widget in widgets:
        if isinstance(widget, (ttk.Button, tk.Button)):
            if str(widget.cget('text')) == 'RESET ZOOM':
                widget.configure(command=owner._proc_reset_zoom)
            elif str(widget.cget('text')) == 'RESET' and widget.master is owner._proc_display_control_cells[3]:
                widget.configure(command=owner.reset_processing)


def _tab6_preserve_view_method(operation):
    import functools
    @functools.wraps(operation)
    def wrapped(owner, *args, **kwargs):
        return _tab6_keep_view(owner, operation, *args, **kwargs)
    return wrapped


_proc_apply_resolution = _tab6_preserve_view_method(_proc_apply_resolution)
_native_finalize = _tab6_preserve_view_method(_native_finalize)
_native_rotation_action = _tab6_preserve_view_method(_native_rotation_action)
_tab6_auth_display_stack_frame_v21 = _tab6_preserve_view_method(_tab6_auth_display_stack_frame_v21)
_tab6_downstream_authoritative_primary_stack_v22 = _tab6_preserve_view_method(_tab6_downstream_authoritative_primary_stack_v22)
CDIWorkflowApp.update_processing_view = _tab6_preserve_view_method(CDIWorkflowApp.update_processing_view)
CDIWorkflowApp.update_processing_pixel_size = _tab6_preserve_view_method(CDIWorkflowApp.update_processing_pixel_size)
CDIWorkflowApp.reset_processing = _tab6_preserve_view_method(CDIWorkflowApp.reset_processing)
CDIWorkflowApp.finalize_primary_roi = _native_finalize
_tab6_install_compact_status(app)


def _panel_status_value(owner, variable):
    try: return str(owner.root.globalgetvar(variable)).strip()
    except tk.TclError: return ''


def _panel_status_publish(record, message=None):
    if message is not None: record['latest'] = message
    record['variable'].set(record.get('help') or record.get('latest') or 'Ready')


def _panel_status_scan(owner, number):
    if number == 6: return  # Tab 6 has its combined processing/scale status area.
    record = owner._panel_status_records[number]
    names = owner._panel_status_variable_names
    protected = ('frame', 'field:', 'pixel size', 'scale ', 'sem nm/pixel', 'verification:',
        'primary roi line:', 'transferred physical length:', 'final primary roi',
        'domain periodicity', 'domain width', 'confirmed component:', 'original:',
        'candidate:', 'changed:', 'native reconstruction:', 'dataset direction:')
    instructions = ('click ', 'drag ', 'draw ', 'move the ', 'use the ', 'select ', 'choose ',
        'press ', 'load ', 'upload ', 'recommended:', 'suggested ', 'raw:', 'full controls',
        'direct entry overrides', 'mouse wheel ', 'circularity:')
    for widget in _legend_walk(record['tab']):
        if not isinstance(widget, (ttk.Label, tk.Label)) or widget in record['hidden']: continue
        if widget.master is record['frame']: continue
        text = str(widget.cget('text')).strip()
        variable = str(widget.cget('textvariable'))
        if not widget.winfo_manager(): continue
        lower = text.lower()
        if lower.startswith(protected): continue
        semantic_names = names.get(variable, ())
        is_status = bool(variable and any(any(word in name.lower() for word in
            ('status', 'hint', 'message', 'instruction', 'info_var', '.info', 'help')) for name in semantic_names))
        is_instruction = not variable and (lower.startswith(instructions) or len(text) > 85)
        if not is_status and not is_instruction: continue
        if widget.winfo_manager() == 'pack': widget.pack_forget()
        elif widget.winfo_manager() == 'grid': widget.grid_remove()
        else: continue
        record['hidden'].append(widget)
        if is_status:
            if variable not in record['traced']:
                def changed(*args, variable=variable, record=record):
                    _panel_status_publish(record, _panel_status_value(owner, variable))
                command = owner.root._register(changed)
                owner.root.tk.call('trace', 'add', 'variable', variable, 'write', command)
                record['traced'].add(variable)
                value = _panel_status_value(owner, variable)
                if value: _panel_status_publish(record, value)
        else:
            message = text.replace('\\n', '\n')
            def enter(event, message=message, record=record):
                record['help'] = message
                _panel_status_publish(record)
            def leave(event, record=record):
                record['help'] = None
                _panel_status_publish(record)
            widget.master.bind('<Enter>', enter, add='+')
            widget.master.bind('<Leave>', leave, add='+')
            if not record.get('latest'): _panel_status_publish(record, message)


def _install_all_tab_status_areas(owner):
    owner._panel_status_records = {}
    owner._panel_status_variable_names = {}
    objects = [('', owner)]
    for name, value in vars(owner).items():
        if getattr(value, 'app', None) is owner and not isinstance(value, tk.Misc):
            objects.append((name+'.', value))
    for prefix, obj in objects:
        for name, variable in vars(obj).items():
            if isinstance(variable, tk.Variable):
                owner._panel_status_variable_names.setdefault(str(variable), []).append(prefix+name)
    for number, path in enumerate(owner.nb.tabs(), 1):
        if number == 6:
            owner._panel_status_records[number] = dict(tab=owner.root.nametowidget(path),
                frame=owner.tab6_image_status_frame, variable=owner.tab6_image_status_var,
                hidden=owner._tab6_status_hidden_labels)
            continue
        tab = owner.root.nametowidget(path)
        packed = tab.pack_slaves()
        grid = tab.grid_slaves()
        footer = ttk.Frame(tab, padding=(8, 5))
        if grid:
            rows, columns = [], []
            for child in grid:
                info = child.grid_info()
                rows.append(int(info['row'])+int(info.get('rowspan', 1)))
                columns.append(int(info['column'])+int(info.get('columnspan', 1)))
            footer.grid(row=max(rows), column=0, columnspan=max(columns), sticky='ew')
        elif packed:
            footer.pack(side='bottom', fill='x', before=packed[0])
        else:
            footer.pack(side='bottom', fill='x')
        variable = tk.StringVar(master=owner.root, value='Ready')
        ttk.Separator(footer).pack(fill='x', pady=(0, 3))
        label = ttk.Label(footer, textvariable=variable, anchor='w', justify='left', wraplength=1000)
        label.pack(fill='x')
        footer.bind('<Configure>', lambda event, label=label:
            label.configure(wraplength=max(180, event.width-16)))
        owner._panel_status_records[number] = dict(tab=tab, frame=footer, variable=variable,
            hidden=[], traced=set(), latest='', help=None)
        _panel_status_scan(owner, number)
    def selected(event=None):
        selected = owner.nb.select()
        tabs = list(owner.nb.tabs())
        if selected in tabs:
            owner.root.after_idle(lambda: _panel_status_scan(owner, tabs.index(selected)+1))
    owner.nb.bind('<<NotebookTabChanged>>', selected, add='+')


_install_all_tab_status_areas(app)


_tab8_install_tv_traces(app)

# Function-based button colors. Explicit existing custom colors/styles are kept.
_BUTTON_PALETTE = {
    'Primary': ('#D7E2ED', '#E4ECF3', '#BED1E2', '#244A6E'),
    'Import': ('#D0E8E6', '#DFF1EF', '#B5D9D5', '#0D514B'),
    'Confirm': ('#DDE1EB', '#E9ECF3', '#C8D1E1', '#34466A'),
    'Secondary': ('#DCE4ED', '#E8EDF3', '#C7D2DF', '#263442'),
    'Export': ('#D7E6DE', '#E6F0EA', '#BFD7C9', '#245139'),
    'Destructive': ('#F1DBDA', '#F8E9E8', '#E4BEBC', '#7A302F'),
}


def _button_function(text):
    import re
    text = re.sub(r'[^a-z0-9]+', ' ', str(text).lower()).strip()
    words = set(text.split())
    if text.startswith(('stop ', 'cancel ', 'pause ', 'reset ', 'preview ', 'view ', 'undo ')) or text in {'stop','cancel','pause','reset','preview','view'}:
        return 'Secondary'
    if words & {'delete', 'remove'} or text.startswith('clear all'):
        return 'Destructive'
    if words & {'export', 'save', 'mp4', 'png', 'csv', 'xlsx'}:
        return 'Export'
    if words & {'browse', 'load', 'import', 'upload', 'fetch'} or text.startswith('open folder') or re.search(r'roi\d* from tab', text) or text in {'select folder', 'refresh hdf5'}:
        return 'Import'
    if words & {'confirm', 'fix', 'fixed', 'lock', 'locked', 'unlock', 'release'}:
        return 'Confirm'
    if text in {'set', 'set center', 'use direct'}:
        return 'Confirm'
    if text.startswith(('set ', 'auto center ')): return 'Primary'
    if words & {'apply', 'process', 'run', 'analyze', 'analyse', 'analysis', 'reconstruct',
                 'calculate', 'recalculate', 'compute', 'fit', 'track', 'detect', 'measure',
                 'generate', 'update', 'optimize', 'refine'}:
        return 'Primary'
    return 'Secondary'


def _button_color_mix(color, target, fraction):
    return '#'+''.join(f'{round(int(color[i:i+2],16)*(1-fraction)+int(target[i:i+2],16)*fraction):02x}'
                       for i in (1,3,5))


def _button_border_image(root, color, pressed=False, disabled=False):
    # Nine-slice border: light upper rim, dark lower rim and a 1px shadow.
    image = tk.PhotoImage(master=root, width=24, height=24)
    image.put(color, to=(0,0,24,24))
    dark = _button_color_mix(color, '#000000', .28 if not disabled else .12)
    light = _button_color_mix(color, '#ffffff', .36 if not disabled else .15)
    image.put(dark, to=(0,0,24,1)); image.put(dark, to=(0,0,1,23))
    image.put(dark, to=(23,0,24,23)); image.put(dark, to=(0,22,24,23))
    image.put(_button_color_mix(color, '#000000', .20), to=(1,23,24,24))
    image.put(dark if pressed else light, to=(1,1,23,2))
    image.put(dark if pressed else light, to=(1,1,2,22))
    return image


def _install_function_button_theme(owner):
    import tkinter.font as tkfont
    style = ttk.Style(owner.root)
    owner._button_theme_style = style
    owner._button_theme_images = []
    owner._button_theme_fonts = {}
    owner._button_theme_preserved = set()
    owner._button_theme_records = {}
    for category, (normal, hover, pressed, foreground) in _BUTTON_PALETTE.items():
        name = f'Function.{category}.TButton'
        # Native border elements paint their label correctly on Windows Tk.
        # Image-based border elements can cover the label even when hit testing
        # reports Button.label, so use the theme's standard text/image layout.
        style.layout(name, style.layout('TButton'))
        base_font = tkfont.nametofont('TkDefaultFont').actual()
        font = (base_font['family'], base_font['size'],
                'normal' if category=='Secondary' else 'bold')
        owner._button_theme_fonts[category] = font
        style.configure(name, background=normal, foreground=foreground, font=font,
            padding=(6,4,6,4), relief='raised', borderwidth=2, anchor='center',
            bordercolor=_button_color_mix(normal,'#000000',.22),
            lightcolor=_button_color_mix(normal,'#ffffff',.36),
            darkcolor=_button_color_mix(normal,'#000000',.20))
        style.map(name, background=[('disabled','#D8DADD'),('pressed',pressed),('active',hover)],
            foreground=[('disabled','#747A82')],
            relief=[('pressed','sunken'),('!pressed','raised')],
            padding=[('pressed','!disabled',(7,5,5,3))])

    def apply(widget):
        if not isinstance(widget, (ttk.Button, tk.Button)): return
        if str(widget) in owner._button_theme_preserved: return
        category = _button_function(widget.cget('text'))
        if owner._button_theme_records.get(str(widget)) == category: return
        if isinstance(widget, ttk.Button):
            existing = str(widget.cget('style'))
            if existing and existing != 'TButton' and not existing.startswith('Function.'):
                owner._button_theme_preserved.add(str(widget)); return
            widget.configure(style=f'Function.{category}.TButton')
            if not getattr(widget,'_function_label_wrap_bound',False):
                def fit_label(event,button=widget):
                    available=max(40,event.width-18)
                    base=f'Function.{_button_function(button.cget("text"))}.TButton'
                    font=tkfont.Font(root=owner.root,font=style.lookup(base,'font'))
                    needed=max((font.measure(line) for line in str(button.cget('text')).splitlines()),default=0)
                    wrap=available if needed>available else 0
                    if getattr(button,'_function_label_wrap',None)==wrap: return
                    button._function_label_wrap=wrap
                    fitted=f'Function.W{id(button)}.{base}'
                    style.configure(fitted,wraplength=wrap,justify='center')
                    button.configure(style=fitted)
                widget.bind('<Configure>',fit_label,add='+')
                widget._function_label_wrap_bound=True
        else:
            previous = owner._button_theme_records.get(str(widget))
            current = widget.winfo_rgb(widget.cget('background'))
            default = widget.winfo_rgb(widget.configure('background')[3])
            custom_text = widget.winfo_rgb(widget.cget('foreground')) != widget.winfo_rgb(widget.configure('foreground')[3])
            if previous is None and (current != default or custom_text):
                owner._button_theme_preserved.add(str(widget)); return
            normal, hover, pressed, foreground = _BUTTON_PALETTE[category]
            widget.configure(background=normal, foreground=foreground, activebackground=hover,
                activeforeground=foreground, disabledforeground='#747A82',
                relief='raised', borderwidth=2, highlightthickness=1,
                highlightbackground=_button_color_mix(normal,'#000000',.25))
            if previous is None:
                def state(event, button=widget):
                    if str(button.cget('state')) == 'disabled':
                        button.configure(background='#D8DADD'); return
                    kind = _button_function(button.cget('text'))
                    colors = _BUTTON_PALETTE[kind]
                    color = colors[2] if event.type == tk.EventType.ButtonPress else colors[1] if event.type in (tk.EventType.Enter,tk.EventType.ButtonRelease) else colors[0]
                    button.configure(background=color, activebackground=color if event.type != tk.EventType.Leave else colors[1])
                # Match the ttk disabled palette when Matplotlib changes a native
                # toolbar button's state programmatically.
                original_configure = widget.configure
                def configure(cnf=None, _button=widget, _original=original_configure, **kwargs):
                    result = _original(cnf, **kwargs)
                    options = dict(cnf) if isinstance(cnf, dict) else {}
                    options.update(kwargs)
                    if 'state' in options:
                        color = '#D8DADD' if str(_button.cget('state')) == 'disabled' else _BUTTON_PALETTE[_button_function(_button.cget('text'))][0]
                        _original(background=color)
                    return result
                widget.configure = configure
                widget.config = configure
                if str(widget.cget('state')) == 'disabled': widget.configure(background='#D8DADD')
                for event in ('<Enter>','<Leave>','<ButtonPress-1>','<ButtonRelease-1>'):
                    widget.bind(event, state, add='+')
        owner._button_theme_records[str(widget)] = category

    owner._button_theme_apply = apply
    for widget in _legend_walk(owner.root): apply(widget)
    def mapped(event):
        apply(event.widget)
    # Newly built dialogs and controls receive the same palette when first shown.
    owner.root.bind_all('<Map>', mapped, add='+')


_install_function_button_theme(app)

# Measurement export helpers: read stored results without rerunning analysis.
def _measurement_scalar_record(record):
    return {key: value.item() if isinstance(value, np.generic) else value
            for key, value in record.items()
            if value is None or isinstance(value, (str, bool, int, float, np.generic))}


def _tab11_complete_measurement_table(self, source):
    if not isinstance(source, pd.DataFrame) or source.empty:
        return _ii_export_table(pd.DataFrame(), self.tab11_integrated_intensity_var.get())
    tables = []
    for roi, rows in source.groupby('roi_index', sort=True):
        tables.append(_tab10_complete_table(_tab11_export_adapter(self, int(roi)), rows))
    return pd.concat(tables, ignore_index=True)


def _tab8_complete_export_tables(self):
    columns = ['Frame No.', 'Field (mT)', 'Avg. Dia (nm)', 'SD (nm)',
               'Supported ROI area (um2)', 'Density (particles/um2)', 'Blob/Particle Count',
               'Avg. Core Intensity', 'SD of Core Intensity']
    rows = [(index, list(value[:9])) for index, value in sorted(self.pd_results.items())
            if isinstance(value, (tuple, list)) and len(value) >= 9]
    summary = pd.DataFrame([row for index, row in rows], columns=columns)
    summary.insert(0, 'Frame_Index', [index for index, row in rows])
    if rows:
        provenance = pd.DataFrame([_intensity_provenance(self, index) for index, row in rows])
        summary = pd.concat([summary, provenance], axis=1)
    particles, dfit, edges = [], [], []
    geometry = getattr(self, '_tab8_roi3_coords', None) or {}
    for index, detections in sorted((getattr(self, 'pd_frame_detections', {}) or {}).items()):
        for number, detection in enumerate(detections, 1):
            row = _measurement_scalar_record(detection)
            row.update(Frame_Index=index, Frame=index+1, Field_mT=_tab8_v7_get_field(self, index),
                       Particle_No=number, ROI_Shape=geometry.get('shape', 'Square'),
                       ROI_Geometry=repr(geometry))
            particles.append(row)
    for index, results in sorted((getattr(self, 'pd_dfit_results', {}) or {}).items()):
        for number, result in enumerate(results, 1):
            identity = dict(Frame_Index=index, Frame=index+1, Field_mT=_tab8_v7_get_field(self, index),
                            Particle_No=result.get('particle_no', number))
            row = _measurement_scalar_record(result)
            row.update(identity)
            dfit.append(row)
            for measurement in result.get('measurements', []):
                edge = _measurement_scalar_record(measurement)
                edge.update(identity)
                edges.append(edge)
    identity = ['Frame_Index', 'Frame', 'Field_mT', 'Particle_No']
    return {
        'FrameSummary': summary,
        'Particles': pd.DataFrame(particles) if particles else pd.DataFrame(columns=identity+['core_intensity']),
        'DFitParticles': pd.DataFrame(dfit) if dfit else pd.DataFrame(columns=identity+['avg_dia_nm', 'sd_nm']),
        'DFitEdges': pd.DataFrame(edges) if edges else pd.DataFrame(columns=identity+['angle_deg', 'radius_nm', 'diameter_nm', 'valid']),
    }


def _measurement_tree_table(tree):
    columns = list(tree['columns'])
    return pd.DataFrame([tree.item(child, 'values') for child in tree.get_children('')],
                        columns=[str(tree.heading(column, 'text')) for column in columns])


def _measurement_domain_samples(panel, kind):
    rows=[]
    for index, result in sorted(panel.results.items()):
        identity=dict(Frame_Index=index,Frame=index+1,Field_mT=panel.field(index))
        if kind=='RadialSpectra':
            fit=dict(zip(result.get('fit_frequency',[]),result.get('fitted_power',[])))
            for frequency,power in zip(result.get('frequency',[]),result.get('radial_power',[])):
                rows.append(dict(identity,Frequency_cycles_nm=frequency,q_rad_nm=2*np.pi*frequency,
                                 Radial_Power=power,Fitted_Power=fit.get(frequency,np.nan)))
        elif kind=='AngularSpectra':
            for angle,power in zip(result.get('azimuth_deg',[]),result.get('azimuth_power',[])):
                rows.append(dict(identity,Azimuth_deg=angle,Annular_Mean_Power=power))
        elif kind=='CorrelationProfiles':
            fit=result.get('correlation_fit',[]);count=result.get('pair_counts',[])
            for sample,(distance,value) in enumerate(zip(result.get('distance_nm',[]),result.get('correlation',[]))):
                rows.append(dict(identity,Distance_nm=distance,Correlation=value,Method=result.get('method',''),
                    Model=fit[sample] if sample<len(fit) else np.nan,Pair_Count=count[sample] if sample<len(count) else np.nan))
        elif kind=='ParticleCenters':
            for particle,center in enumerate(result.get('particle_centers_nm',[]),1):
                rows.append(dict(identity,Particle_No=particle,X_in_ROI_nm=center[0],Y_in_ROI_nm=center[1]))
    return pd.DataFrame(rows)


def _measurement_frc_samples(self):
    rows=[]
    for entry in getattr(self,'tab13_frc_entries',[]) or []:
        for index,(frequency,value) in enumerate(zip(np.ravel(entry.get('q',[])),np.ravel(entry.get('frc',[])))):
            rows.append(dict(Entry=entry.get('name',''),Source_Path=entry.get('path',''),Sample=index,
                q_or_Pixel=frequency,FRC=float(np.real(value)),Field_mT=entry.get('magnet_B',np.nan),
                Resolution=entry.get('resolution',np.nan),q_Cut=entry.get('q_cut',np.nan),
                FFT_Pixel_Cut=entry.get('FFT_pixel_cut',np.nan)))
    return pd.DataFrame(rows)


def _measurement_session_context(self):
    """Calibration and processing context, including fields without a plot table."""
    rows = []
    def add(tab, quantity, value, unit=''):
        if isinstance(value, np.generic): value = value.item()
        if isinstance(value, (dict, tuple, list)):
            value = json.dumps(value, default=str, ensure_ascii=False)
        rows.append(dict(Tab=tab, Quantity=quantity, Value=value, Unit=unit))
    add(1, 'Calibration JSON', str(getattr(self, 'field_calib_file', '') or ''))
    add(1, 'Calibration branch', getattr(self, '_magnet_selected_label', ''))
    add(4, 'Selected component', _tab4_component_confirmed(self))
    add(4, 'Intensity mode', _intensity_mode(self))
    add(4, 'Confirmed ROI', getattr(self, 'roi_coords', None))
    for name in ('pixel_cal_active_nm_per_pixel', 'primary_roi_final_nm_per_pixel', 'sem_nm_per_pixel'):
        value = getattr(self, name, None)
        if value is not None: add(5, name, value, 'nm/pixel')
    variable = getattr(self, 'pixel_cal_direct_nm_per_pixel_var', None)
    if variable is not None: add(5, 'Direct calibration entry', variable.get(), 'nm/pixel')
    add(6, 'Finalized version', getattr(self, '_native_finalized_version', None))
    add(6, 'Finalized processing settings', getattr(self, '_native_finalized_config', {}))
    snapshot = getattr(self, '_native_finalized_snapshot', None)
    if snapshot is not None:
        add(6, 'Finalized pixel scale', snapshot[1], 'nm/output pixel (X,Y)')
        add(6, 'Finalized stack shape', list(snapshot[0].shape), '(frames,height,width) pixels')
    for name, unit in [('sem_scale_pixels', 'pixels'), ('sem_verification_pixels', 'pixels'),
                       ('sem_verification_length_nm', 'nm'), ('primary_roi_scale_pixels', 'pixels')]:
        if getattr(self, name, None) is not None: add(5, name, getattr(self, name), unit)
    for name in ('_tab6_finalized_scale', '_native_finalized_scale', '_tab6_export_authoritative_scale_v24'):
        if getattr(self, name, None) is not None: add(6, name, getattr(self, name), 'nm/output pixel (X,Y)')
    add(6, 'Secondary ROI', getattr(self, 'roi2_coords', None))
    for name in ('_tab6_line_measurement', '_tab6_line_measurement_result'):
        if getattr(self, name, None) is not None: add(6, name, getattr(self, name))
    for name, unit in [('proc_profile_pixels_var', 'output pixels'), ('proc_profile_nm_var', 'nm')]:
        variable = getattr(self, name, None)
        if variable is not None: add(6, name, variable.get(), unit)
    add(8, 'Selected ROI geometry', getattr(self, '_tab8_roi3_coords', None))
    add(9, 'Selected ROI', getattr(self, '_tab9_roi4_coords', None))
    add(9, 'Pixel scale', getattr(self, '_tab9_roi4_scale', None), 'nm/pixel (X,Y)')
    return pd.DataFrame(rows)


@_auto_open_export
def _export_all_measurement_tables(self):
    """Export stored measurements and a manifest; never launch a fit or denoise."""
    from datetime import datetime
    folder = _export_capture_folder(filedialog.askdirectory, parent=self.root,
                                   title='Select folder for all stored measurement tables')
    if not folder:
        return False
    destination = Path(folder) / ('Measurement_Tables_' + datetime.now().strftime('%Y%m%d_%H%M%S_%f'))
    destination.mkdir(parents=True)
    manifest = []
    failures = []
    def write(tab, filename, builder, description):
        try:
            table = builder()
            if not isinstance(table, pd.DataFrame) or table.empty:
                manifest.append(dict(Tab=tab, File='', Rows=0, Status='No stored measurements', Description=description))
                return
            if not len(table.columns): raise ValueError('Missing column headers')
            _export_capture_write(table.to_csv, destination / filename, index=False)
            manifest.append(dict(Tab=tab, File=filename, Rows=len(table), Status='Exported', Description=description))
        except Exception as exc:
            failures.append(f'Tab {tab}: {exc}')
            manifest.append(dict(Tab=tab, File='', Rows=0, Status='Unavailable: '+str(exc), Description=description))
    write('1-6,8-9', 'Session_Calibration_ROI_Processing.csv', lambda: _measurement_session_context(self),
          'Stored calibration, component, intensity mode, processing settings and ROI geometry.')
    def frames():
        field = getattr(self, 'real_fields_mT', None)
        current = getattr(self, 'current_values_A', None)
        paths = getattr(self, 'reconstruction_paths', None) or []
        n = max(len(field) if field is not None else 0, len(current) if current is not None else 0, len(paths))
        return pd.DataFrame([dict(Frame_Index=i, Frame=i+1,
            Field_mT=field[i] if field is not None and i<len(field) else np.nan,
            Current_A=current[i] if current is not None and i<len(current) else np.nan,
            Source_File=str(paths[i]) if i<len(paths) else '') for i in range(n)])
    write(1, 'Tab1_Frame_Field_Current.csv', frames, 'Acquisition order retained; Frame_Index starts at 0; Frame starts at 1.')
    def calibration():
        current = getattr(self, 'calib_current', None)
        field = getattr(self, 'calib_field_mT', None)
        if current is None or field is None: return pd.DataFrame()
        return pd.DataFrame({'Current_A': current, 'Field_mT': field})
    write(1, 'Tab1_Calibration.csv', calibration, 'Selected measured calibration branch.')
    for tab, attribute, filename in [(4, 'tab4_normalization_reference_table', 'Tab4_Normalization_References.csv'),
                                     (7, '_lpa_measure_tree', 'Tab7_Visible_Measurements.csv'),
                                     (14, 'tab13_frc_tree', 'Tab14_FRC_Visible_Table.csv')]:
        write(tab, filename, lambda attribute=attribute: _measurement_tree_table(getattr(self, attribute)),
              'Exact visible table including headings and displayed precision.')
    write(7, 'Tab7_Gaussian_Parameters_FullPrecision.csv',
          lambda: pd.DataFrame([dict(Line=index+1, **_measurement_scalar_record(record))
              for index, record in sorted((getattr(self, '_lpa_gaussian_results', {}) or {}).items())]),
          'Full stored fit precision; nm and a.u. quantities follow named fields.')
    write(7, 'Tab7_Endpoint_Measurements_FullPrecision.csv',
          lambda: pd.DataFrame([_measurement_scalar_record(record) for record in getattr(self, '_lpa_measurements', [])]),
          'Stored endpoint positions and distances without display rounding.')
    if not getattr(self, '_tab8_batch_busy', False):
        for label in ('FrameSummary', 'Particles', 'DFitParticles', 'DFitEdges'):
            write(8, f'Tab8_{label}.csv', lambda label=label: _tab8_complete_export_tables(self)[label],
                  'All stored frames, including particle and radial D-fit measurements; no recalculation.')
    else:
        manifest.append(dict(Tab=8, File='', Rows=0, Status='Analysis running; export after completion', Description='Blob analysis'))
    for tab in (10, 11):
        if getattr(self, f'_tab{tab}_ii_busy', False) or getattr(self, f'_tab{tab}_ii_dirty', False):
            manifest.append(dict(Tab=tab, File='', Rows=0, Status='Settings changed or analysis running; rerun analysis', Description='Fit results'))
            continue
        if _ii2d_enabled(self, tab):
            write(tab, f'Tab{tab}_2D_Measurements.csv', lambda tab=tab: _ii2d_export_table(_ii2d_dataframe(self, tab)),
                  'Signed full ROI integral (a.u. nm^2), central feature area (nm^2), size (nm), detection and provenance.')
            continue
        if tab == 10:
            write(10, 'Tab10_Fit_Parameters.csv', lambda: _tab10_complete_table(self, getattr(self, '_tab10_tracking_df', None)),
                  'Gaussian/D-fit measurements, 1D integrated intensity (a.u. nm), uncertainties and provenance.')
            records = [(None, r) for r in self._tab10_intensity_profiles.values()]
        else:
            write(11, 'Tab11_Fit_Parameters.csv', lambda: _tab11_complete_measurement_table(self, _tab11_export_numeric_source(self)),
                  'Every measured ROI and frame, scalar fit measurements, uncertainties and provenance.')
            records = [(roi, r) for (roi, frame), r in self._tab11_intensity_profiles.items()]
        def profiles(builder, records=records, tab=tab):
            tables = []
            for roi, result in records:
                owner = self if tab==10 else _tab11_export_adapter(self, roi)
                table = builder(owner, result)
                if roi is not None: table.insert(0, 'ROI', roi)
                tables.append(table)
            return pd.concat(tables, ignore_index=True) if tables else pd.DataFrame()
        for label, builder in [('LineProfiles', _tab10_profile_table),
                               ('DFitProfiles', lambda owner, result: _tab10_dfit_profile_table(result)),
                               ('DFitMeasurements', lambda owner, result: _tab10_edge_table(result))]:
            write(tab, f'Tab{tab}_{label}.csv', lambda builder=builder, profiles=profiles: profiles(builder),
                  'Stored samples and radial measurements, with frame/field/ROI identity.')
    panel = getattr(self, 'domain_periodicity', None)
    write(12, 'Tab12_Domain_Periodicity.csv', lambda: pd.DataFrame(panel.records()) if panel else pd.DataFrame(),
          'Stored FFT/ACF period or particle spacing; unresolved values remain NaN with reasons.')
    if panel is not None:
        for kind in ('RadialSpectra','AngularSpectra','CorrelationProfiles','ParticleCenters'):
            write(12,f'Tab12_{kind}.csv',lambda kind=kind:_measurement_domain_samples(panel,kind),
                  'Original stored domain spectra, correlations and particle center samples.')
    write(14,'Tab14_FRC_Samples.csv',lambda:_measurement_frc_samples(self),
          'Original FRC curve samples, resolution, field and cutoff values; no display rounding.')
    for tab in (2, 3, 5, 6, 9, 13, 15):
        manifest.append(dict(Tab=tab, File='Session_Calibration_ROI_Processing.csv' if tab in (5,6,9) else '',
            Rows=0, Status='Context/image tab; use its existing image, mask, HDF5 report or log export',
            Description='No additional independent per-frame measurement table is calculated in this tab.'))
    _export_capture_write(pd.DataFrame(manifest).to_csv, destination/'Export_Manifest.csv', index=False)
    metadata = dict(frame_index='0-based', frame='1-based',
        missing_values='Empty CSV values represent unavailable/NaN measurements, not zero.',
        intensity='Raw reconstruction a.u. or normalized a.u. as recorded; 1D integrals are a.u. nm; 2D integrals are a.u. nm^2.',
        scope='Snapshot of stored results only. Analyses are never run by this export.',
        failures=failures)
    with _export_capture_stream(open, destination/'README.json', 'w', encoding='utf-8') as handle:
        json.dump(metadata, handle, indent=2)
    self.log(f'Measurement tables exported: {destination}' + ('; review unavailable entries in manifest' if failures else ''))
    _export_request_open(str(destination))
    return destination


CDIWorkflowApp.export_all_measurement_tables = _export_all_measurement_tables
# Place the action with the existing Tab 1 controls.
