app.export_all_tables_button = ttk.Button(_export_all_parent, text='EXPORT ALL MEASUREMENT TABLES',
                                         command=app.export_all_measurement_tables)
app.export_all_tables_button.pack(fill='x', pady=5)
app._button_theme_apply(app.export_all_tables_button)


